/**
 * カレンダー。1シーズン = 48週（4週 × 12か月）、8月開幕・翌5月閉幕。
 * 時間は絶対週 absWeek = season * 48 + week で一元管理する。
 *
 *   week 0-3    8月      プレシーズン（キャンプ・練習試合）
 *   移籍期間: 夏は week 0-7（8〜9 月）、冬は week 20-27（1〜2 月）
 *   week 4-20   9-12月   リーグ前半 第1〜17節（平日にカップ戦）
 *   week 21-23  1月      ウインターブレイク（キャンプ）
 *   week 24-40  2-5月    リーグ後半 第18〜34節
 *   week 41-44  6月      昇格プレーオフ・カップ決勝・大陸大会の決勝トーナメント
 *   week 45     7月      世界クラブ選手権
 *   week 46-47  7月      表彰・契約更改・引退・ユース昇格
 */
export const WEEKS_PER_SEASON = 48
export const MATCHDAYS = 34

export const PRESEASON_END = 3
export const FIRST_HALF_START = 4
export const FIRST_HALF_END = 20
export const WINTER_START = 21
export const WINTER_END = 23
export const SECOND_HALF_START = 24
export const SECOND_HALF_END = 40
export const POSTSEASON_START = 41
export const POSTSEASON_END = 44
export const WORLD_CLUB_WEEK = 45
export const OFFSEASON_START = 46

export type SeasonPhase = 'preseason' | 'firstHalf' | 'winter' | 'secondHalf' | 'postseason' | 'offseason'

export const PHASE_LABEL: Record<SeasonPhase, string> = {
  preseason: 'プレシーズン',
  firstHalf: 'リーグ前半',
  winter: 'ウインターブレイク',
  secondHalf: 'リーグ後半',
  postseason: 'ポストシーズン',
  offseason: 'オフシーズン',
}

export function phaseOfWeek(week: number): SeasonPhase {
  if (week <= PRESEASON_END) return 'preseason'
  if (week <= FIRST_HALF_END) return 'firstHalf'
  if (week <= WINTER_END) return 'winter'
  if (week <= SECOND_HALF_END) return 'secondHalf'
  if (week <= WORLD_CLUB_WEEK) return 'postseason'
  return 'offseason'
}

/** 移籍期間（M21 で延ばした。夏: 8〜9 月、冬: 1〜2 月。どちらも 8 週） */
export const SUMMER_WINDOW: readonly [number, number] = [0, 7]
export const WINTER_WINDOW: readonly [number, number] = [20, 27]

export function isTransferWindow(week: number): boolean {
  return (week >= SUMMER_WINDOW[0] && week <= SUMMER_WINDOW[1]) || (week >= WINTER_WINDOW[0] && week <= WINTER_WINDOW[1])
}

/**
 * 移籍期間の 1 週あたりの動きの量（前の長さ ÷ 今の長さ）。
 * 期間を延ばしても、AI の補強・キャリアのオファー・海外挑戦の志願の 1 回の期間での回数が前と同じになるように、毎週の確率に掛ける。
 * 前は夏 5 週（第 0〜4 週）、冬 4 週（第 21〜24 週）
 */
export function windowPace(week: number): number {
  return week <= SUMMER_WINDOW[1] ? 5 / 8 : 4 / 8
}

/** 移籍期間の残りの週（今週を含む。期間外は 0） */
export function windowWeeksLeft(week: number): number {
  if (week >= SUMMER_WINDOW[0] && week <= SUMMER_WINDOW[1]) return SUMMER_WINDOW[1] - week + 1
  if (week >= WINTER_WINDOW[0] && week <= WINTER_WINDOW[1]) return WINTER_WINDOW[1] - week + 1
  return 0
}

/** 次の移籍期間が始まるまでの週（期間中は 0） */
export function weeksToNextWindow(week: number): number {
  if (isTransferWindow(week)) return 0
  if (week < WINTER_WINDOW[0]) return WINTER_WINDOW[0] - week
  return WEEKS_PER_SEASON - week + SUMMER_WINDOW[0]
}

/** リーグの節（0-33）。試合のない週は null */
export function matchdayOfWeek(week: number): number | null {
  if (week >= FIRST_HALF_START && week <= FIRST_HALF_END) return week - FIRST_HALF_START
  if (week >= SECOND_HALF_START && week <= SECOND_HALF_END) return 17 + (week - SECOND_HALF_START)
  return null
}

export function weekOfMatchday(md: number): number {
  return md < 17 ? FIRST_HALF_START + md : SECOND_HALF_START + (md - 17)
}

/** 月（1-12） */
export function monthOfWeek(week: number): number {
  return ((7 + Math.floor(week / 4)) % 12) + 1
}

/** 表示用の西暦（1月以降は翌年） */
export function yearOfWeek(startYear: number, season: number, week: number): number {
  return startYear + season + (monthOfWeek(week) <= 7 ? 1 : 0)
}

export function seasonLabel(startYear: number, season: number): string {
  const y = startYear + season
  return `${y}-${String((y + 1) % 100).padStart(2, '0')}`
}

export function dateLabel(startYear: number, season: number, week: number): string {
  return `${yearOfWeek(startYear, season, week)}年${monthOfWeek(week)}月 第${(week % 4) + 1}週`
}

export function absWeekOf(season: number, week: number): number {
  return season * WEEKS_PER_SEASON + week
}

/** 絶対週から年齢 */
export function ageAt(absWeek: number, birthAbsWeek: number): number {
  return Math.floor((absWeek - birthAbsWeek) / WEEKS_PER_SEASON)
}
