export function defaultTraining(): TrainingPlan {
  return { intensity: 1, weights: Object.fromEntries(TRAINING_MENUS.map((m) => [m.id, 2])), individual: {} }
}

/** 練習の配分から、能力ごとの伸びやすさ（平均 1）を出す */
export function trainingFocus(plan: TrainingPlan, gk: boolean, individualMenu?: string): Partial<Record<AttrKey, number>> {
  const raw: Partial<Record<AttrKey, number>> = {}
  const add = (menu: TrainingMenu, w: number) => {
    if (menu.gkOnly !== gk && menu.gkOnly) return
    if (gk && !menu.gkOnly && menu.id !== 'physical' && menu.id !== 'tactics') w *= 0.4
    for (const [k, v] of Object.entries(menu.attrs)) raw[k as AttrKey] = (raw[k as AttrKey] ?? 0) + w * (v as number)
  }
  for (const m of TRAINING_MENUS) add(m, plan.weights[m.id] ?? 0)
  // 個別練習は配分の 4 割を上乗せ
  if (individualMenu && MENU_BY_ID[individualMenu]) {
    const total = Object.values(plan.weights).reduce((s, w) => s + w, 0) || 1
    add(MENU_BY_ID[individualMenu], total * 0.4)
  }
  const vals = Object.values(raw) as number[]
  const mean = vals.length ? vals.reduce((s, v) => s + v, 0) / vals.length : 1
  const out: Partial<Record<AttrKey, number>> = {}
  for (const [k, v] of Object.entries(raw)) out[k as AttrKey] = 0.45 + 0.55 * ((v as number) / (mean || 1))
  return out
}

