/** 選手。エンジン内では mutable なプレーンオブジェクトとして扱う。 */
import type { Attrs, Traits } from '../data/attributes'
import type { Position } from '../data/positions'
import type { GrowthType } from '../data/growth'
import type { Personality } from '../data/personality'
import type { Nation } from '../data/nations'
import type { FaceSpec } from './face'

export type Foot = 'R' | 'L' | 'B'

/** 約束した起用（やる気と契約交渉に効く） */
export type SquadRole = 'star' | 'regular' | 'rotation' | 'backup' | 'prospect'

export const SQUAD_ROLE_LABEL: Record<SquadRole, string> = {
  star: '中心選手',
  regular: 'レギュラー',
  rotation: '準レギュラー',
  backup: '控え',
  prospect: '若手有望株',
}

export interface Contract {
  /** 年俸（万円/年） */
  wage: number
  /** このシーズンの終わりまで（シーズン番号） */
  until: number
  releaseClause?: number
  role?: SquadRole
}

export interface Loan {
  fromClubId: number
  /** このシーズンの終わりに戻る */
  until: number
  /** 借り手が払う年俸の割合（0-1） */
  wageShare: number
}

export interface Injury {
  name: string
  weeks: number
}

export interface SeasonStats {
  apps: number
  starts: number
  minutes: number
  goals: number
  assists: number
  yellow: number
  red: number
  /** 評価点の合計（平均 = ratingSum / apps） */
  ratingSum: number
  cleanSheets: number
}

export interface SeasonRecord extends SeasonStats {
  season: number
  clubId: number
  ovr: number
}

export interface Player {
  id: number
  name: string
  /** 試合中の表示などに使う短い名前 */
  short: string
  nation: Nation
  birthAbsWeek: number
  heightCm: number
  /** 体重（kg。キャリアの主人公だけ。ほかは身長からの目安 weightOf） */
  weightKg?: number
  foot: Foot
  pos: Position
  /** ポジション適性 0-100 */
  apt: Record<Position, number>
  /** 現在の能力（小数で持ち、表示は四捨五入） */
  attr: Attrs
  /** 能力の上限（隠し） */
  cap: Attrs
  growth: GrowthType
  traits: Traits
  personality: Personality
  skills: string[]
  /** 調子 0-100（50 が普通） */
  condition: number
  /** 疲労 0-100 */
  fatigue: number
  injury: Injury | null
  /** やる気 0-100 */
  morale: number
  /** 出場停止の残り試合数 */
  suspension: number
  clubId: number
  isYouth: boolean
  /** ユースアカデミーで育ったクラブの id（M16。生え抜きの印と物語） */
  homegrown?: number
  /** 最後に面談した週（M19。4 週あける） */
  lastMeeting?: number
  /** 済んだ物語の節目（M16。club/youthStory.ts） */
  story?: string[]
  /** どこからユースに来たか（M25。「ブラジル・サンパウロ校」など） */
  origin?: string
  /** ユースの留学（M25。海外アカデミーの国へ。この週まで） */
  study?: { nation: Nation; untilAbsWeek: number }
  contract: Contract
  loan?: Loan
  number: number
  /** 画像のある固有キャラの id（public/chars/ のフォルダ名） */
  starId?: string
  face?: FaceSpec
  retired: boolean
  stats: SeasonStats
  history: SeasonRecord[]
  /** 代表の通算（試合・得点・W 杯の出場回数） */
  intl?: { caps: number; goals: number; wc: number }
  /** キャリアモードから来たレジェンド（書き出しの key） */
  legend?: string
}

export function emptyStats(): SeasonStats {
  return { apps: 0, starts: 0, minutes: 0, goals: 0, assists: 0, yellow: 0, red: 0, ratingSum: 0, cleanSheets: 0 }
}
