/**
 * 海外の有望株（M25。クラブモード）: 海外の 15〜17 歳をユース契約で獲る。
 *   夏（第 1 週）と冬（第 24 週）に 6 人が並ぶ（世界の選手にはまだ入れない。state.overseasYouth）
 *   顔ぶれ: 国際ユースカップで目立った子（冬）・アカデミーのある国の子・ほかの国の子
 *   申し込み（育成補償金 + 契約金）。欧州の強豪も狙っている。締め切り（第 6 週・第 29 週）に本人が決める
 *   決め手: クラブの格と狙っているクラブの格・その国のアカデミー・ユース施設・契約金・ワールドリーグ・大会で対戦した
 *   入った子はユース（選手枠は使わない）。ユースは 30 人まで
 * 乱数は種とシーズンから（ほかの処理の並びを変えない）。判定のサイコロは申し込みにかかわらず並びの順で固定。
 */
import { absWeekOf } from '../core/calendar'
import { createRng, hashSeed, type Rng } from '../core/prng'
import { ACADEMY_BY_NATION, OVERSEAS_POOL, YOUTH_CITIES } from '../data/academies'
import { NATION_NAME, type Nation } from '../data/nations'
import type { Position } from '../data/positions'
import { assignNumbers, generatePlayer } from '../gen/playerGen'
import { allocId, type GameState } from '../models/game'
import type { Player } from '../models/player'
import { ovr, potentialOvr } from '../player/overall'
import { chargeYouth, findAcademy } from './academy'
import type { Standout } from './youthCup'

export const OY_ROUNDS = [
  { announce: 1, deadline: 6, label: '夏' },
  { announce: 24, deadline: 29, label: '冬' },
]
export const OY_BONUSES = [0, 1000, 3000]
export const OY_SIZE = 6
/** ユースの人数の上限（海外の有望株を獲るとき） */
export const YOUTH_LIMIT = 30

export interface OverseasProspect {
  player: Player
  team: string
  /** 狙っている海外のクラブ */
  interest: number[]
  /** 育成補償金（万円。入団が決まったら払う） */
  fee: number
  /** 国際ユースカップで対戦した（チームの名前） */
  met?: string
  applied?: { bonus: number }
}

export interface OverseasYouthList {
  season: number
  round: number
  deadline: number
  list: OverseasProspect[]
}

/** 前回の結果（申し込んだ子だけ。画面に出す） */
export interface OverseasYouthResult {
  season: number
  round: number
  list: { playerId: number; name: string; nation: Nation; team: string; joined: boolean; note: string }[]
}

const POSITIONS: Position[] = ['ST', 'WG', 'AM', 'CM', 'DM', 'CB', 'SB', 'GK']
/** 入団が決まるまでの仮の id（負の数） */
const TEMP_ID = 1_000_000
const SUFFIX = ['FC U-17', 'ユース', 'アカデミー', 'SC U-17']

function now(state: GameState): number {
  return absWeekOf(state.season, state.week)
}

export function youthCount(state: GameState): number {
  const me = state.playerClubId
  let n = 0
  for (const p of Object.values(state.players)) if (p.isYouth && p.clubId === me && !p.retired) n++
  return n
}

function pickNation(rng: Rng): Nation {
  return OVERSEAS_POOL[rng.weighted(OVERSEAS_POOL.map(([, w]) => w))][0]
}

function teamName(rng: Rng, nation: Nation): string {
  return `${rng.pick(YOUTH_CITIES[nation] ?? [NATION_NAME[nation]])} ${rng.pick(SUFFIX)}`
}

/** 狙っている海外のクラブ（将来性が高いほど多く。同じ国のクラブを先に） */
function interestOf(state: GameState, rng: Rng, nation: Nation, pot: number): number[] {
  const n = pot >= 82 ? 3 : pot >= 76 ? 2 : pot >= 70 ? 1 : rng.chance(0.4) ? 1 : 0
  if (!n) return []
  const big = state.clubs.filter((c) => !c.isPlayer && c.country !== 'JP' && c.rep >= 70 && c.leagueId !== 'AMA')
  const home = rng.shuffle(big.filter((c) => c.country === nation))
  const rest = rng.shuffle(big.filter((c) => c.country !== nation)).sort((a, b) => b.rep - a.rep).slice(0, 12)
  return rng
    .shuffle([...home.slice(0, 1), ...rest.slice(0, 4)])
    .slice(0, n)
    .sort((a, b) => b.rep - a.rep)
    .map((c) => c.id)
}

function feeOf(pot: number): number {
  return Math.round((300 + Math.max(0, pot - 64) * 140) / 100) * 100
}

function makeProspect(state: GameState, rng: Rng, nation: Nation, opts: { pos?: Position; target?: number; pot?: number; team?: string; met?: string; name?: { full: string; short: string } } = {}): OverseasProspect {
  const me = state.clubs[state.playerClubId]
  const age = rng.int(15, 17)
  const pot = opts.pot ?? 64 + rng.int(0, 20) + (me.rep >= 70 ? 2 : 0)
  const target = opts.target ?? 36 + (age - 15) * 4 + rng.int(0, 7) + Math.max(0, pot - 70) * 0.3
  const def = ACADEMY_BY_NATION[nation]
  const pos = opts.pos ?? (def && rng.chance(0.6) ? rng.pick(def.pos) : rng.pick(POSITIONS))
  // 入団が決まるまでは仮の id（世界の選手の id を使わない。申し込まなければ、ほかの処理の並びが変わらない）
  const keep = state.nextId.player
  const p = generatePlayer(state, rng, { clubId: -1, pos, targetOvr: target, age, nation, potentialOvr: pot, contractYears: -1, isYouth: true })
  state.nextId.player = keep
  p.id = -(TEMP_ID + rng.int(0, 999999))
  if (opts.name) {
    p.name = opts.name.full
    p.short = opts.name.short
  }
  return { player: p, team: opts.team ?? teamName(rng, nation), interest: interestOf(state, rng, nation, pot), fee: feeOf(pot), met: opts.met }
}

/** 国際ユースカップで目立った子から作る */
function fromStandout(state: GameState, rng: Rng, s: Standout): OverseasProspect {
  return makeProspect(state, rng, s.nation, { pos: s.pos, target: s.level + rng.int(0, 3), pot: Math.min(90, s.level + 22 + rng.int(0, 6)), team: s.team, met: s.team, name: { full: s.name, short: s.short } })
}

/** 発表する（夏は第 1 週、冬は第 24 週） */
export function announceOverseasYouth(state: GameState, round: number) {
  if (state.mode !== 'club') return
  const me = state.clubs[state.playerClubId]
  const rng = createRng(hashSeed(state.seed, state.season, 0x0e70 + round))
  const list: OverseasProspect[] = []
  // 冬: 国際ユースカップで目立った子
  const cup = state.youthCup
  if (round === 1 && cup?.season === state.season && cup.status === 'done') for (const s of cup.standouts.slice(0, 2)) list.push(fromStandout(state, rng, s))
  // アカデミーのある国（近くのクラブの子）
  for (const a of rng.shuffle([...(me.academies ?? [])]).slice(0, 2)) {
    if (list.length >= OY_SIZE) break
    if (now(state) < a.openAbsWeek) continue
    const def = ACADEMY_BY_NATION[a.nation]
    list.push(makeProspect(state, rng, rng.chance(0.75) || !def ? a.nation : rng.pick(def.neighbors)))
  }
  while (list.length < OY_SIZE) list.push(makeProspect(state, rng, pickNation(rng)))
  const r = OY_ROUNDS[round]
  state.overseasYouth = { season: state.season, round, deadline: r.deadline, list }
  state.news.push({ absWeek: now(state), category: 'club', mine: true, text: `海外の有望株 ${list.length} 人の情報が届きました。ユース契約の申し込みは第 ${r.deadline + 1} 週まで（ユースアカデミー → 海外の有望株）。` })
}

export interface OyFactor {
  label: string
  v: number
}

/** 来てくれる見込みの決め手（足すと見込み） */
export function overseasFactors(state: GameState, op: OverseasProspect, bonus: number): OyFactor[] {
  const me = state.clubs[state.playerClubId]
  const top = Math.max(me.rep - 5, ...op.interest.map((id) => state.clubs[id]?.rep ?? 0))
  const out: OyFactor[] = [{ label: 'もともとの関心', v: 0.32 }]
  const gap = (me.rep - top) * 0.012
  out.push({ label: op.interest.length ? '狙っている強豪との格の差' : 'クラブの格', v: gap })
  if (op.interest.length) out.push({ label: `ほかに ${op.interest.length} クラブが狙っている`, v: -op.interest.length * 0.04 })
  const a = findAcademy(me, op.player.nation)
  if (a && now(state) >= a.openAbsWeek) out.push({ label: `${NATION_NAME[a.nation]}のアカデミー`, v: 0.2 })
  if (me.facilities.youth) out.push({ label: `ユース施設 Lv${me.facilities.youth}`, v: me.facilities.youth * 0.03 })
  if (bonus) out.push({ label: '契約金', v: Math.min(0.25, bonus / 12000) })
  if (me.leagueId === 'WL') out.push({ label: 'ワールドリーグのクラブ', v: 0.1 })
  if (op.met) out.push({ label: '国際ユースカップで対戦した', v: 0.1 })
  return out
}

export function overseasChance(state: GameState, op: OverseasProspect, bonus: number): number {
  const x = overseasFactors(state, op, bonus).reduce((s, f) => s + f.v, 0)
  return Math.max(0.05, Math.min(0.92, x))
}

/** 見せる総合の幅と将来性（その国にアカデミーがあれば正確） */
export function overseasEstimate(state: GameState, op: OverseasProspect): { lo: number; hi: number; stars: number; sure: boolean } {
  const me = state.clubs[state.playerClubId]
  const scouts = me.staff.map((id) => state.staff[id]).filter((s) => s?.role === 'scout').length
  const sure = !!findAcademy(me, op.player.nation)
  const w = sure ? 1 : Math.max(2, 6 - scouts)
  const o = ovr(op.player)
  const pot = potentialOvr(op.player)
  return { lo: o - w, hi: o + w, stars: pot >= 82 ? 5 : pot >= 77 ? 4 : pot >= 72 ? 3 : 2, sure }
}

/** 申し込みの前に止める理由（ユースが満員・資金） */
export function overseasBlocker(state: GameState, op: OverseasProspect, bonus: number): string | null {
  if (youthCount(state) >= YOUTH_LIMIT) return `ユースがいっぱい（${YOUTH_LIMIT} 人）`
  if (state.clubs[state.playerClubId].budget < op.fee + bonus) return '資金が足りない'
  return null
}

export function applyOverseas(state: GameState, idx: number, bonus: number): boolean {
  const oy = state.overseasYouth
  const op = oy?.list[idx]
  if (!oy || !op || state.week > oy.deadline || overseasBlocker(state, op, bonus)) return false
  op.applied = { bonus }
  return true
}

export function cancelOverseas(state: GameState, idx: number) {
  const op = state.overseasYouth?.list[idx]
  if (op) op.applied = undefined
}

/** 締め切りの週: 本人が決める */
export function decideOverseasYouth(state: GameState) {
  const oy = state.overseasYouth
  if (!oy) return
  // 前のシーズンの残り（ふつうはない）は消す
  if (oy.season !== state.season) {
    state.overseasYouth = undefined
    return
  }
  const me = state.clubs[state.playerClubId]
  const rng = createRng(hashSeed(state.seed, state.season, 0x0e7a + oy.round))
  const absWeek = now(state)
  const joined: string[] = []
  const results: OverseasYouthResult['list'] = []
  for (const op of oy.list) {
    const roll = rng.next()
    if (!op.applied) continue
    const p = op.player
    const res = { playerId: p.id, name: p.name, nation: p.nation, team: op.team, joined: false, note: '' }
    results.push(res)
    const block = overseasBlocker(state, op, op.applied.bonus)
    if (block) {
      res.note = block
      state.news.push({ absWeek, category: 'club', mine: true, text: `${p.name}（${NATION_NAME[p.nation]}）は入団を望んだが、${block}で迎えられなかった。` })
      continue
    }
    if (roll < overseasChance(state, op, op.applied.bonus)) {
      p.id = allocId(state, 'player')
      res.playerId = p.id
      p.clubId = me.id
      p.isYouth = true
      p.homegrown = me.id
      p.origin = `${NATION_NAME[p.nation]}・${op.team}`
      p.contract = { ...p.contract, wage: 0, until: state.season + 3 }
      state.players[p.id] = p
      chargeYouth(state, op.fee + op.applied.bonus)
      joined.push(`${p.name}（${NATION_NAME[p.nation]}）`)
      res.joined = true
      res.note = '入団'
      continue
    }
    const to = op.interest[0] !== undefined ? state.clubs[op.interest[0]] : undefined
    res.note = to ? `${to.short}へ` : '地元に残った'
    state.news.push({ absWeek, category: 'club', mine: true, text: `${p.name}（${op.team}）は${to ? `${to.name}のユース` : '地元のクラブ'}を選んだ。` })
  }
  if (joined.length) {
    assignNumbers(Object.values(state.players).filter((p) => p.clubId === me.id && !p.retired), rng)
    state.news.push({ absWeek, category: 'club', mine: true, text: `海外から ${joined.join('・')} がユースに加わります！` })
  }
  state.overseasYouth = undefined
  state.overseasYouthLast = results.length ? { season: state.season, round: oy.round, list: results } : undefined
}

/** 毎週（クラブモード）: 発表と締め切り。発表した週は true（1 か月オートを止める） */
export function overseasYouthWeek(state: GameState): boolean {
  if (state.mode !== 'club') return false
  let announced = false
  OY_ROUNDS.forEach((r, i) => {
    if (state.week === r.announce) {
      announceOverseasYouth(state, i)
      announced = true
    }
    if (state.week === r.deadline) decideOverseasYouth(state)
  })
  return announced
}
