/** ゲーム全体の状態（セーブの単位）。 */
import type { Player } from './player'
import type { Staff } from './staff'
import type { Club, SponsorSlot } from './club'
import type { Competition } from './competition'
import type { MatchSummary } from '../match/live/types'
import type { NationalState } from './national'
import type { CareerState } from './career'
import type { TownTrait } from '../data/clubs'
import type { OwnerState } from '../club/owner'
import type { ActivityId } from '../club/community'
import type { Prospect } from '../club/prospects'
import type { OverseasYouthList, OverseasYouthResult } from '../club/overseasYouth'
import type { YouthCup, YouthCupRecord } from '../club/youthCup'
import type { Talk } from '../transfer/talks'
import type { ScoutReport } from '../scout/reports'
import type { PowerLog } from '../club/power'

export const SCHEMA_VERSION = 6

export type NewsCategory = 'match' | 'transfer' | 'growth' | 'club' | 'league' | 'event' | 'injury' | 'staff' | 'national'

export interface NewsItem {
  absWeek: number
  category: NewsCategory
  text: string
  /** 自クラブに関係するか */
  mine?: boolean
}

/** 自クラブの週ごとの収支（万円） */
export interface WeekFinance {
  absWeek: number
  ticket: number
  tv: number
  sponsor: number
  goods: number
  prize: number
  transferIn: number
  wages: number
  staffWages: number
  maintenance: number
  construction: number
  transferOut: number
  other: number
  /** サイドビジネスの損益（赤字ならマイナス） */
  business?: number
  /** 海外ユースの費用（M25。アカデミーの運営・開業・育成補償金・大会の遠征・留学） */
  youth?: number
}

/** シーズンの記録 */
export interface SeasonSummary {
  season: number
  leagueId: string
  rank: number
  points: number
  champions: { compId: string; clubId: number }[]
  promoted: number[]
  relegated: number[]
  topScorers: { compId: string; playerId: number; goals: number }[]
  budgetEnd: number
  awards?: Award[]
  /** 自クラブのカップ戦の成績（勝ち上がった回戦） */
  cup?: { compId: string; stage: string; champion: number }
  /** 自クラブの大陸大会・世界大会の成績 */
  continental?: { compId: string; stage: string; champion: number }[]
  /** この季に殿堂入りした選手 */
  hallOfFame?: number[]
  /** サイドビジネスの決算（事業 id → 売上・利益） */
  business?: { id: string; sales: number; profit: number }[]
  /** ライバルとの順位（リーグが同じときだけ） */
  rival?: { clubId: number; rank: number; above: boolean }
  /** リーグごとのベストイレブン（GK 1・DF 4・MF 3・FW 3）。名前などは引退して選手のデータが消えても出せるように */
  bestEleven?: Record<string, { playerId: number; name: string; short: string; pos: string; clubId: number }[]>
  /** 世界の年間最優秀選手（ピッチクラウン賞）の投票の上位 10 人 */
  worldRanking?: { playerId: number; clubId: number; score: number; name?: string }[]
}

/** 自クラブの直近の試合（試合後の画面用） */
export interface LastMatch {
  fixtureId: number
  compId: string
  home: number
  away: number
  summary: MatchSummary
}

export interface IdCounters {
  player: number
  staff: number
  fixture: number
  offer: number
}

export interface GameState {
  schemaVersion: number
  /** club = クラブ経営、career = 1 人の選手として成り上がる */
  mode: 'club' | 'career'
  /** キャリアモードの状態（mode が career のとき） */
  career?: CareerState
  seed: number
  startYear: number
  season: number
  /** 0-47 */
  week: number
  playerClubId: number
  nextId: IdCounters
  players: Record<number, Player>
  staff: Record<number, Staff>
  clubs: Club[]
  competitions: Competition[]
  news: NewsItem[]
  /** 自クラブのホームタウン */
  /** trait: 街の特色（M19。古いセーブはなし） */
  hometown: { city: string; pref: string; population: number; economy: number; passion: number; development: number; trait?: TownTrait }
  finance: WeekFinance[]
  seasons: SeasonSummary[]
  lastMatch?: LastMatch
  /** 資金難の管理（マイナスが続いた週数、オーナーの救済の回数） */
  money: { negWeeks: number; bailouts: number; gameOver?: boolean }
  /** オーナーの目標と信頼（M19。クラブモードだけ。古いセーブは読み込んだときに作る） */
  owner?: OwnerState
  /** ホームタウンとのつながり（M19。地域の活動の回数と最後の週） */
  community?: { total: number; count: Partial<Record<ActivityId, number>>; last?: number; fandaySeason?: number }
  /** 高校・ユース大会の有望株（M19。第 21〜30 週だけ。選手はまだ players に入れない） */
  prospects?: { season: number; list: Prospect[] }
  /** 海外の有望株（M25。夏と冬に 6 人。選手はまだ players に入れない。club/overseasYouth.ts） */
  overseasYouth?: OverseasYouthList
  /** 海外の有望株の前回の結果 */
  overseasYouthLast?: OverseasYouthResult
  /** 国際ユースカップ（M25。招待から決勝まで。club/youthCup.ts） */
  youthCup?: YouthCup
  /** 国際ユースカップの成績 */
  youthCupLog?: YouthCupRecord[]
  /** 返事待ちの申し出（スポンサー・移籍の打診・イベントなど） */
  offers: Offer[]
  /** スカウト: 自クラブが知っている度合い（選手 id → 0-100）と派遣 */
  scout: ScoutState
  /** 進めている交渉（M20。閉じても続きから。transfer/talks.ts） */
  talks?: Talk[]
  /** ワールドリーグへの参入の申請（M24。このシーズン末に参入） */
  worldApply?: { season: number }
  /** リーグごとのクラブの格の戻り先（M24。ワールドリーグができたときの平均。なければ data/clubs の LEAGUE_REP_ANCHOR） */
  repAnchors?: Record<string, number>
  /** クラブの総合力の推移（M23。月のはじめとシーズンの終わり。club/power.ts） */
  powerLog?: PowerLog[]
  /** 交渉が決裂した選手（id → 話を聞いてもらえるようになる週） */
  talkBlock?: Record<number, number>
  /** 自クラブが売りに出している選手（id → 希望額） */
  forSale: Record<number, number>
  /** 移籍の記録（直近） */
  transfers: TransferRecord[]
  /** 自クラブの連携（"小さい id:大きい id" → 0-100） */
  chem: Record<string, number>
  /** 来季の大陸大会の出場クラブ（シーズン末に決める） */
  qualified?: { acc: number[]; euc: number[] }
  /** 自クラブの記録 */
  records: ClubRecords
  /** 自クラブが獲ったタイトル */
  trophies: Trophy[]
  /** 優勝のセレモニーを見たタイトルの数（M16。trophies のここまで） */
  celebrated?: number
  /** 開く入団会見（M16。大型補強） */
  press?: { playerId: number; fee: number }[]
  /** 見せる生え抜きの物語（M16。club/youthStory.ts） */
  youthStories?: { playerId: number; kind: 'promote' | 'debut' | 'goal' | 'cap' | 'apps100' }[]
  /** 自クラブの殿堂 */
  hallOfFame: HallOfFamer[]
  /** 景気（0.75〜1.3、1 が普通）。サイドビジネスの売上に効く */
  bizCycle?: number
  /** 宿命のライバル（対戦成績つき） */
  rival?: { clubId: number; w: number; d: number; l: number }
  /** 代表チームと W 杯 */
  national?: NationalState
}

/** 1 試合の記録 */
export interface MatchRecord {
  season: number
  absWeek: number
  compId: string
  opponent: number
  /** 自クラブから見たスコア */
  gf: number
  ga: number
  home: boolean
}

export interface ClubRecords {
  biggestWin?: MatchRecord
  worstLoss?: MatchRecord
  mostGoalsMatch?: MatchRecord
  topAttendance?: { season: number; absWeek: number; opponent: number; value: number }
  mostGoalsSeason?: { season: number; playerId: number; name: string; goals: number }
  recordSigning?: { season: number; playerId: number; name: string; fee: number; from: number }
  recordSale?: { season: number; playerId: number; name: string; fee: number; to: number }
  /** 公式戦の通算 */
  total: { played: number; won: number; drawn: number; lost: number; gf: number; ga: number }
}

export interface Trophy {
  season: number
  compId: string
  name: string
}

export interface HallOfFamer {
  playerId: number
  name: string
  season: number
  pos: string
  nation: string
  apps: number
  goals: number
  reason: string
}

export function emptyRecords(): ClubRecords {
  return { total: { played: 0, won: 0, drawn: 0, lost: 0, gf: 0, ga: 0 } }
}

export interface ScoutMission {
  staffId: number
  region: ScoutRegion
  untilAbsWeek: number
  /** この視察で出した報告の数（M21） */
  found?: number
}

/** スカウトの前回の視察（M21。地域・戻った週・報告の数） */
export interface ScoutTrip {
  region: ScoutRegion
  absWeek: number
  count: number
}

export type ScoutRegion = 'JP' | 'AS' | 'EU' | 'SA'

export interface ScoutState {
  knowledge: Record<number, number>
  missions: ScoutMission[]
  /** 注目リスト（自分で ★ を付けた選手。期限なし） */
  watch: number[]
  /** スカウトの報告（M21。掲載は 8 週。古いセーブは読み込んだときに作る） */
  reports?: ScoutReport[]
  /** スカウトごとの前回の視察（staff id →） */
  trips?: Record<number, ScoutTrip>
}

export interface TransferRecord {
  absWeek: number
  playerId: number
  name: string
  from: number
  to: number
  fee: number
  kind: 'transfer' | 'free' | 'loan' | 'loanEnd' | 'release'
}

export interface Award {
  key: 'mvp' | 'scorer' | 'assist' | 'young' | 'keeper' | 'manager' | 'world'
  compId: string
  playerId?: number
  staffId?: number
  clubId: number
  value?: number
  /** 受賞したときの名前（引退して選手のデータが消えても表示できるように） */
  name?: string
}

export type Offer =
  | { kind: 'sponsor'; slot: SponsorSlot; company: string; annual: number; years: number; bonus?: { kind: 'rank' | 'promotion'; value: number; amount: number }; expiresAbsWeek: number; id: number }
  /** AI クラブから自クラブの選手への移籍の打診 */
  | { kind: 'bid'; playerId: number; clubId: number; fee: number; loan?: boolean; expiresAbsWeek: number; id: number }
  /** 選手の移籍志願（出場機会を求めて／海外クラブのオファーを受けて海外挑戦） */
  | { kind: 'request'; playerId: number; expiresAbsWeek: number; id: number; abroad?: { clubId: number; fee: number } }
  /** クラブのイベント（選択肢つき） */
  | { kind: 'event'; eventId: string; playerId?: number; expiresAbsWeek: number; id: number }

export function allocId(state: GameState, kind: keyof IdCounters): number {
  return state.nextId[kind]++
}
