/**
 * オーナーの目標と評価（M19。クラブモードだけ）。
 *   シーズンのはじめに 3 つの目標（順位はいつも。ほかは収支・観客・生え抜き・カップから）
 *   シーズン末に評価: 達成で信頼と追加の予算、未達成で信頼が下がる。信頼が低いと予算を削られる（ゲームオーバーにはしない）
 * 乱数は種とシーズンから（ほかの処理の並びを変えない）。
 */
import { absWeekOf, WEEKS_PER_SEASON } from '../core/calendar'
import { createRng, hashSeed } from '../core/prng'
import { CUP_ID, CUP_WEEKS } from '../competition/cup'
import { weekNet } from '../economy/finance'
import { teamStrength } from '../match/lineup'
import type { GameState } from '../models/game'

export type OwnerGoalKind = 'rank' | 'profit' | 'attendance' | 'youth' | 'cup' | 'worldFans'

export interface OwnerGoal {
  kind: OwnerGoalKind
  target: number
  label: string
  /** ホームの帯に出す短い名前 */
  short?: string
}

export interface OwnerState {
  /** 信頼 0〜100 */
  trust: number
  season: number
  goals: OwnerGoal[]
  /** 前のシーズンの評価（シーズン末の画面で見せる） */
  last?: { season: number; results: { label: string; ok: boolean; value: string }[]; trustBefore: number; trustAfter: number; bonus: number; cut: number }
}

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

/** 目標ひとつにつき、達成したときの追加の予算（万円、リーグの段で変わる） */
const BONUS_BY_TIER: Record<number, number> = { 1: 8000, 2: 4000, 3: 2000 }
/** ワールドリーグ（M24 の 3 回目）の目標ひとつの額 */
const BONUS_WORLD = 20000

const myLeague = (state: GameState) => {
  const me = state.clubs[state.playerClubId]
  return state.competitions.find((c) => c.id === me.leagueId)
}

/** 今季のリーグの順位（表がまだなら最下位扱い） */
function currentRank(state: GameState): number {
  const comp = myLeague(state)
  if (!comp) return 99
  const i = comp.table.findIndex((r) => r.clubId === state.playerClubId)
  return i < 0 ? comp.clubIds.length : i + 1
}

/** 今季の収支（帳簿の今季の週を足す） */
function seasonProfit(state: GameState): number {
  const from = absWeekOf(state.season, 0)
  return state.finance.filter((w) => w.absWeek >= from).reduce((s, w) => s + weekNet(w), 0)
}

/** 今季のホームの平均観客 */
function avgAttendance(state: GameState): number {
  const me = state.playerClubId
  const list = state.competitions.flatMap((c) => c.fixtures).filter((f) => f.home === me && f.result?.attendance && Math.floor(f.absWeek / WEEKS_PER_SEASON) === state.season)
  return list.length ? Math.round(list.reduce((s, f) => s + (f.result!.attendance ?? 0), 0) / list.length) : 0
}

/** リーグ戦に 3 試合以上出た生え抜きの選手の数 */
function youthPlayed(state: GameState): number {
  return Object.values(state.players).filter((p) => p.clubId === state.playerClubId && p.homegrown !== undefined && p.stats.apps >= 3).length
}

/** カップでいちばん進んだ回戦（0 始まり。出ていなければ -1） */
function cupRound(state: GameState): number {
  const cup = state.competitions.find((c) => c.id === CUP_ID)
  if (!cup) return -1
  const mine = cup.fixtures.filter((f) => f.home === state.playerClubId || f.away === state.playerClubId)
  return mine.length ? Math.max(...mine.map((f) => f.round)) : -1
}

/** シーズンのはじめに目標を決める（クラブの戦力とリーグから） */
export function setOwnerGoals(state: GameState) {
  if (state.mode === 'career') return
  const comp = myLeague(state)
  if (!comp) return
  const me = state.clubs[state.playerClubId]
  const rng = createRng(hashSeed(state.seed, state.season, 0x0e2))
  // 期待される順位: リーグ内の戦力の順
  const strengths = comp.clubIds.map((id) => ({ id, s: teamStrength(state, state.clubs[id]) })).sort((a, b) => b.s - a.s)
  const expected = strengths.findIndex((x) => x.id === me.id) + 1 || comp.clubIds.length
  const n = comp.clubIds.length
  // ワールドリーグ（M24）は残留（下位 3 クラブより上）が最低の目標
  const world = comp.id === 'WL'
  const target = clamp(Math.round(expected * 0.8), 1, world ? n - 3 : n - 1)
  const stay = world && target === n - 3
  const goals: OwnerGoal[] = [{ kind: 'rank', target, label: target === 1 ? 'リーグ優勝' : stay ? `残留（${target} 位以内）` : comp.tier > 1 && target <= 2 ? '昇格（2 位以内）' : `リーグ ${target} 位以内`, short: target === 1 ? '優勝' : stay ? '残留' : comp.tier > 1 && target <= 2 ? '昇格' : `${target} 位以内` }]
  // 収支: 資金が少ないうちは黒字、あれば赤字は 1 億円まで
  goals.push(me.budget < 30000 ? { kind: 'profit', target: 0, label: '収支を黒字に', short: '黒字' } : { kind: 'profit', target: -10000, label: '赤字は 1 億円まで', short: '赤字 1 億まで' })
  // もうひとつは観客・生え抜き・カップから（ワールドリーグは海外のファン）
  const third = rng.pick(['attendance', 'youth', 'cup'] as const)
  if (world) {
    const t = Math.round(((me.worldFans ?? 0) + 300000) / 10000) * 10000
    goals.push({ kind: 'worldFans', target: t, label: `海外のファン ${(t / 10000).toLocaleString()} 万人`, short: `海外のファン ${(t / 10000).toLocaleString()} 万` })
  } else if (third === 'attendance') {
    const base = Math.max(avgAttendance(state), Math.round(me.fans * 0.35))
    const t = Math.round(Math.min(me.stadium.capacity * 0.92, base * 1.08) / 100) * 100
    goals.push({ kind: 'attendance', target: t, label: `ホームの平均観客 ${t.toLocaleString()} 人`, short: `観客 ${t.toLocaleString()}` })
  } else if (third === 'youth') {
    goals.push({ kind: 'youth', target: 1, label: '生え抜きの選手をリーグ戦に 3 試合以上', short: '生え抜きの出場' })
  } else {
    const t = comp.tier === 1 ? CUP_WEEKS.length - 2 : CUP_WEEKS.length - 3
    goals.push({ kind: 'cup', target: t, label: `ナショナルカップ ${t === CUP_WEEKS.length - 2 ? 'ベスト 4' : 'ベスト 8'}`, short: `カップ ${t === CUP_WEEKS.length - 2 ? 'ベスト 4' : 'ベスト 8'}` })
  }
  state.owner = { trust: state.owner?.trust ?? 60, season: state.season, goals, last: state.owner?.last }
}

/** 目標の今の状況（画面と評価で使う） */
export function goalProgress(state: GameState, g: OwnerGoal): { ok: boolean; value: string } {
  switch (g.kind) {
    case 'rank': {
      const r = currentRank(state)
      return { ok: r <= g.target, value: `今 ${r} 位` }
    }
    case 'profit': {
      const v = seasonProfit(state)
      return { ok: v >= g.target, value: `${v >= 0 ? '+' : ''}${Math.round(v).toLocaleString()} 万円` }
    }
    case 'attendance': {
      const v = avgAttendance(state)
      return { ok: v >= g.target, value: `平均 ${v.toLocaleString()} 人` }
    }
    case 'youth': {
      const v = youthPlayed(state)
      return { ok: v >= g.target, value: `${v} 人` }
    }
    case 'worldFans': {
      const v = state.clubs[state.playerClubId].worldFans ?? 0
      return { ok: v >= g.target, value: `${Math.round(v / 10000).toLocaleString()} 万人` }
    }
    case 'cup': {
      const r = cupRound(state)
      const left = r < 0 ? 'まだ' : r >= CUP_WEEKS.length - 1 ? '決勝まで' : `${r + 1} 回戦まで`
      return { ok: r >= g.target, value: left }
    }
  }
}

/** 半ば（第 24 週）の声: ニュースで今の状況 */
export function ownerMidSeason(state: GameState) {
  const o = state.owner
  if (!o || o.season !== state.season || state.mode === 'career') return
  const ok = o.goals.filter((g) => goalProgress(state, g).ok).length
  const text = ok === o.goals.length ? 'オーナー「前半戦は文句なしだ。この調子で頼む」' : ok === 0 ? 'オーナー「どの目標にも届いていない。後半戦で巻き返してくれ」' : `オーナー「目標は ${o.goals.length} つのうち ${ok} つが届いている。残りもたのむ」`
  state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'club', mine: true, text })
}

/** シーズン末の評価（processSeasonEnd から。順位・収支が決まったあと） */
export function ownerSeasonEnd(state: GameState) {
  const o = state.owner
  if (!o || o.season !== state.season || state.mode === 'career') return
  const me = state.clubs[state.playerClubId]
  const tier = myLeague(state)?.tier ?? 3
  const before = o.trust
  const results = o.goals.map((g) => ({ label: g.label, ...goalProgress(state, g) }))
  const ok = results.filter((r) => r.ok).length
  let trust = before + ok * 7 - (results.length - ok) * 8 + (ok === results.length ? 5 : 0)
  trust = clamp(trust, 0, 100)
  // 追加の予算: 達成した目標の数 × 段ごとの額 × 信頼（全部達成なら 1.5 倍）
  const per = me.leagueId === 'WL' ? BONUS_WORLD : (BONUS_BY_TIER[tier] ?? 2000)
  const bonus = Math.round((ok * per * (0.7 + trust / 100) * (ok === results.length ? 1.5 : 1)) / 100) * 100
  // 信頼が低いと予算を削られる
  const cut = trust < 25 && me.budget > 0 ? Math.round(Math.min(me.budget * 0.1, 10000) / 100) * 100 : 0
  me.budget += bonus - cut
  const last = state.finance[state.finance.length - 1]
  if (last) last.other += bonus - cut
  o.trust = trust
  o.last = { season: state.season, results, trustBefore: before, trustAfter: trust, bonus, cut }
  const absWeek = absWeekOf(state.season, state.week)
  state.news.push({ absWeek, category: 'club', mine: true, text: `オーナーの評価: 目標 ${results.length} つのうち ${ok} つを達成（信頼 ${Math.round(before)} → ${Math.round(trust)}）${bonus ? `。追加の予算 ${bonus.toLocaleString()} 万円` : ''}${cut ? `。予算を ${cut.toLocaleString()} 万円削られた` : ''}` })
}
