export type StopKind = 'injury' | 'seasonEnd' | 'playoff' | 'budget' | 'offer' | 'construction' | 'encounter' | 'event' | 'gameOver' | 'continental'

export interface StopEvent {
  kind: StopKind
  text: string
  /** 1 か月まとめて進めているときでも止める */
  major: boolean
}

export interface PlayerFixtureResult {
  fixture: Fixture
  comp: Competition
  summary: MatchSummary
  attendance: number
}

export interface WeekReport {
  absWeek: number
  player?: PlayerFixtureResult
  seasonEnded: boolean
  stops: StopEvent[]
  finance?: WeekFinance
}

export interface AdvanceOptions {
  /** 自クラブの試合を画面で観戦した結果 */
  playerResult?: MatchSummary
}

/** 今週の自クラブのまだ終わっていない試合（平日のカップ戦を先に） */
export function playerFixtureThisWeek(state: GameState): { fixture: Fixture; comp: Competition } | null {
  const now = absWeekOf(state.season, state.week)
  const me = state.playerClubId
  // キャリアで主人公がクラブに入っていない（入団前・ユース期・引退後）ときは、自分の試合はない
  if (state.career && (state.players[state.career.playerId]?.clubId ?? -1) < 0) return null
  let found: { fixture: Fixture; comp: Competition } | null = null
  for (const comp of state.competitions) {
    for (const f of comp.fixtures) {
      if (f.absWeek !== now || f.result || (f.home !== me && f.away !== me)) continue
      if (!found || (f.slot === 'midweek' && found.fixture.slot !== 'midweek')) found = { fixture: f, comp }
    }
  }
  return found
}

/** 自クラブの試合だけ先に行う（観戦した結果を渡すか、自動で計算）。週は進めない */
export function playPlayerMatch(state: GameState, summary?: MatchSummary): PlayerFixtureResult | null {
  const fx = playerFixtureThisWeek(state)
  if (!fx) return null
  const absWeek = absWeekOf(state.season, state.week)
  const rng = weekRng(state.seed, absWeek, fx.fixture.id)
  const s = summary ?? new LiveMatch(buildMatchSetup(state, fx.fixture.id, fx.fixture.home, fx.fixture.away, matchOptions(fx.comp, fx.fixture)), { headless: true, focus: state.career?.playerId }).runToEnd()
  applyPlayerMatch(state, fx.comp, fx.fixture, s, rng)
  return { fixture: fx.fixture, comp: fx.comp, summary: s, attendance: fx.fixture.result?.attendance ?? 0 }
}

/** 延長・PK まで決着をつける試合か（fixture を渡すと大陸大会のグループ戦を区別する） */
export function isKnockout(comp: Competition, f?: Fixture): boolean {
  return f ? isKnockoutFixture(comp, f) : comp.kind !== 'league'
}

export function advanceWeek(state: GameState, opts: AdvanceOptions = {}): WeekReport {
  const absWeek = absWeekOf(state.season, state.week)
  const rng = weekRng(state.seed, absWeek)
  const report: WeekReport = { absWeek, seasonEnded: false, stops: [] }
  const me = state.playerClubId
  const newsBefore = state.news.length

  // ⓪ 工事の完成・申し出・合宿での出会い（古いセーブにはライバルがいないので決める）
  if (!state.rival) ensureRival(state)
  const newsBefore0 = state.news.length
  completeConstruction(state, absWeek)
  if (state.news.length > newsBefore0) report.stops.push({ kind: 'construction', text: state.news[state.news.length - 1].text, major: false })
  state.offers = state.offers.filter((o) => o.expiresAbsWeek >= absWeek)
  // キャリアモードではクラブ経営の処理をしない（所属クラブは AI が運営する）
  const career = isCareer(state)
  // 選手枠（M22）: 週のあいだに超えたら知らせる
  const rosterBefore = career ? 0 : rosterInfo(state).count
  if (!career) {
    if (state.week === 0 || state.week === 1) {
      const before = state.offers.length
      makeSponsorOffers(state, state.clubs[me], rng)
      if (state.offers.length > before) report.stops.push({ kind: 'offer', text: 'スポンサー契約の申し出が届いています', major: true })
    }
    const enc = campEncounter(state, state.clubs[me], rng)
    if (enc) report.stops.push({ kind: 'encounter', text: enc, major: true })
    // 契約更改の時期・人数の確認
    if (state.week === RENEWAL_WEEK && expiringPlayers(state).length) report.stops.push({ kind: 'offer', text: `契約更改の時期です（今季で契約が切れる選手 ${expiringPlayers(state).length} 人）`, major: true })
    if (state.week === 0 || state.week === 24) emergencySign(state)
    // オーナーの前半戦の評価（M19）
    if (state.week === 24) ownerMidSeason(state)
    // 高校・ユース大会の有望株（M19）: 発表と、本人が決める週
    if (state.week === PROSPECT_WEEK) announceProspects(state)
    if (state.week === PROSPECT_DEADLINE) decideProspects(state)
    // 海外ユース（M25）: 海外の有望株の発表と締め切り・国際ユースカップ（招待・試合）
    if (overseasYouthWeek(state)) report.stops.push({ kind: 'offer', text: '海外の有望株の情報が届きました', major: false })
    if (youthCupWeek(state) === 'invite') report.stops.push({ kind: 'offer', text: '国際ユースカップに招待されました', major: true })
    // 海外のファン（M24 の 2 回目）
    worldFansWeek(state, state.clubs[me])
  } else {
    // キャリア: 今週の過ごし方・経験点・課題・オファー
    const talksBefore = state.career!.talks.length
    const offersBefore = state.career!.offers.length
    const sponsorBefore = !!state.career!.sponsorOffer
    careerWeek(state, rng)
    if (!sponsorBefore && state.career!.sponsorOffer) report.stops.push({ kind: 'offer', text: '個人スポンサーの申し出が届きました', major: true })
    if (state.career!.talks.length > talksBefore) report.stops.push({ kind: 'encounter', text: '出来事がありました', major: true })
    if (state.career!.offers.length > offersBefore) report.stops.push({ kind: 'offer', text: 'オファーが届きました', major: true })
  }

  // ① 育成・調子・疲労（練習計画・コーチ・施設・合宿）
  weeklyPlayers(state, rng, absWeek, squadsByClub(state))

  // ② プレーオフ・カップ戦の抽選（ふつうは前の週の終わりに済んでいる。古いセーブ用）
  report.stops.push(...drawWeek(state))

  // ③ 先発（ケガ・出場停止・調子・疲労を反映）。自クラブも「おまかせ」なら毎週組み直す
  const squads = squadsByClub(state)
  for (const club of state.clubs) if (!club.lineup.manual) club.lineup = autoLineup(state, club, squads.get(club.id) ?? [])

  // ④ 試合（自クラブの試合がまだなら自動で行う）
  if (opts.playerResult) playPlayerMatch(state, opts.playerResult)
  while (playerFixtureThisWeek(state)) {
    const r = playPlayerMatch(state)
    if (!r) break
    report.player = r
    if (r.comp.id.endsWith('PO')) report.stops.push({ kind: 'playoff', text: `${r.comp.name}の試合が行われました`, major: true })
  }
  let attendance = 0
  for (const comp of state.competitions) {
    for (const f of comp.fixtures) {
      if (f.absWeek !== absWeek) continue
      if (f.home === me && f.result?.attendance) attendance += f.result.attendance
      if (f.result) continue
      const setup = buildMatchSetup(state, f.id, f.home, f.away, matchOptions(comp, f))
      const s = fastSim(setup, createRng(hashSeed(state.seed, f.id, 0xfa57)), comp.kind === 'league' ? comp.id : state.clubs[f.home].leagueId)
      applyMatchResult(state, comp, f, s, rng, squads)
    }
  }

  // 代表戦・W 杯（クラブの試合のあと。疲労とケガはクラブに戻ってくる）
  nationalWeek(state)

  // 移籍（AI の補強と、自クラブへのオファー）・スカウト・やる気・イベント・連携
  aiTransferWeek(state, rng, squads)
  if (!career) {
    talkWeek(state)
    aiBidsForPlayerClub(state, rng)
    reportWeek(state, scoutWeek(state, rng))
    moraleWeek(state, rng)
    if (maybeEvent(state, rng)) report.stops.push({ kind: 'event', text: 'クラブで相談ごとがあります', major: true })
    youthStoryWeek(state)
  }
  {
    const club = state.clubs[me]
    const camp = club.camp && absWeek >= club.camp.startAbsWeek && absWeek < club.camp.startAbsWeek + club.camp.weeks ? CAMP_PLACES.find((c) => c.name === club.camp!.place) : undefined
    chemWeekly(state, squadsByClub(state).get(me) ?? [], club.training?.weights.tactics ?? 2, camp?.chemistry ?? 0)
  }
  if (state.offers.some((o) => o.kind === 'bid' && o.expiresAbsWeek >= absWeek + 1)) report.stops.push({ kind: 'offer', text: '選手へのオファーが届いています', major: false })

  // ⑤ 財務（キャリアでは自分のクラブの財務はない）
  if (!career) report.finance = playerWeekFinance(state, absWeek, attendance, squads)
  aiWeekFinance(state, squads)
  const money = career ? 'ok' : checkMoney(state)
  if (money === 'warn' && state.money.negWeeks === 1) report.stops.push({ kind: 'budget', text: '資金がマイナスになりました。8 週続くとオーナーが介入します', major: true })
  if (money === 'bailout') {
    state.news.push({ absWeek, category: 'club', mine: true, text: `オーナーが資金を注入しました（${state.money.bailouts} 回目）。クラブの評判が下がりました。3 回目はありません。` })
    report.stops.push({ kind: 'budget', text: 'オーナーが資金を注入しました', major: true })
  }
  if (money === 'gameOver') report.stops.push({ kind: 'gameOver', text: '資金難でクラブの経営権を失いました', major: true })
  // 自クラブの選手のケガ（長期）
  for (const n of state.news.slice(newsBefore)) {
    if (n.mine && n.category === 'injury') report.stops.push({ kind: 'injury', text: n.text, major: /全治 ([4-9]|\d\d) 週/.test(n.text) })
  }

  // クラブの総合力の推移（M23）: 月のはじめとシーズンの最後の週
  if (!career) powerWeek(state)

  // ⑥ 週を進める
  state.week++
  if (state.week >= WEEKS_PER_SEASON) {
    processSeasonEnd(state, rng)
    state.season++
    state.week = 0
    startNewSeason(state)
    report.seasonEnded = true
    report.stops.push({ kind: 'seasonEnd', text: 'シーズンが終わりました', major: true })
  }
  // 選手枠（M22）: 超えたとき（レンタルからの復帰・有望株など）と、新しいシーズンの選手登録で知らせる
  if (!career) {
    const r = rosterInfo(state)
    if (r.over > 0 && (rosterBefore <= r.limit || report.seasonEnded))
      report.stops.push({ kind: 'offer', text: `${report.seasonEnded ? '選手登録: ' : ''}選手枠（${r.limit} 人）を ${r.over} 人超えています。選手を整理してください`, major: true })
  }
  // 次の週の組み合わせを今のうちに決める（週の頭に決めると、自クラブの試合が観戦できずに自動で終わってしまう）
  report.stops.push(...drawWeek(state))
  // 自クラブと同じリーグの主力に写真を割り当てる（移籍・ユース・新しいシーズンで入った選手など）。
  // 週の終わりに付けておくと、自動保存のあとに読み込んでも写真が変わらない
  assignPhotos(state)
  return report
}

/**
 * 今週の組み合わせ（昇格プレーオフ・カップ戦・大陸大会）。前の回戦が終わっていれば組む。何度呼んでもよい。
 * 返り値は止まる理由（世界クラブ選手権への出場）
 */
export function drawWeek(state: GameState): StopEvent[] {
  if (state.week === PLAYOFF_SEMI_WEEK) createPlayoffs(state)
  if (state.week === PLAYOFF_FINAL_WEEK) createPlayoffFinals(state)
  advanceCup(state)
  const hadWcc = state.competitions.some((c) => c.id === WCC_ID)
  advanceContinental(state)
  const wcc = state.competitions.find((c) => c.id === WCC_ID)
  // 代表: W 杯の組み合わせと招集（キャリアの主人公は招集を知ってから観戦できる）
  nationalPrepare(state)
  if (!hadWcc && wcc?.clubIds.includes(state.playerClubId)) return [{ kind: 'continental', text: '世界クラブ選手権への出場が決まりました！', major: true }]
  return []
}
