/**
 * 海外ユース（M25）の国ごとの定義: 海外アカデミーを開ける国（得意・費用・質）と、海外の有望株が出てくる国の街。
 */
import type { AttrKey } from './attributes'
import type { Nation } from './nations'
import type { Position } from './positions'

export interface AcademyNationDef {
  nation: Nation
  /** アカデミーを置く街 */
  city: string
  /** 得意（画面の札） */
  spec: string
  /** 得意の能力（入る子のこの能力が高く、留学でも伸びやすい） */
  attrs: AttrKey[]
  /** 出てきやすいポジション */
  pos: Position[]
  /** 開業の費用（万円） */
  openCost: number
  /** 1 シーズンの運営費（Lv1。授業料を引いた分、万円） */
  run: number
  /** 子どもの将来性の上乗せ（育成の土台） */
  quality: number
  /** 将来性のばらつき（大きいほど掘り出し物と外れが多い） */
  spread: number
  /** 近くの国（2 割はこの国の子） */
  neighbors: Nation[]
}

