/**
 * ユースの若手の物語（M16、クラブモード）: 自クラブのユースアカデミー出身（homegrown）の選手の節目を、秘書の話として見せる。
 *   昇格（トップへ）・デビュー・初ゴール・代表初選出・クラブで 100 試合
 * 毎週（advanceWeek の自クラブの処理）に確かめ、見せる話は state.youthStories にためる（ホームで 1 つずつ）。
 */
import { absWeekOf } from '../core/calendar'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import { clubCareer } from './records'
import { rosterInfo } from './roster'

export type YouthStoryKind = 'promote' | 'debut' | 'goal' | 'cap' | 'apps100'

export const YOUTH_STORY_TEXT: Record<YouthStoryKind, (name: string) => string> = {
  promote: (n) => `ユースから ${n} がトップチームに上がりました。小さいころから見てきた子です。ここからが本当の勝負ですね。`,
  debut: (n) => `${n} がトップチームでデビューしました！ スタンドのユースの後輩たちも、目を輝かせていましたよ。`,
  goal: (n) => `${n} がプロ初ゴール！ ユースのコーチたちが、ベンチの裏で泣いて喜んでいました。`,
  cap: (n) => `${n} が日本代表に選ばれました！ うちのアカデミーから代表選手が出るなんて……街じゅうが大騒ぎです。`,
  apps100: (n) => `${n} がクラブで 100 試合に出場しました。生え抜きの選手がチームの柱になっていく。クラブの誇りです。`,
}

/** ユースの選手をトップチームへ上げる（話を予約する） */
export function promoteYouth(state: GameState, p: Player): boolean {
  if (state.mode === 'club' && rosterInfo(state).full) return false
  p.isYouth = false
  p.contract = { ...p.contract, wage: Math.max(p.contract.wage, 240), until: state.season + 2 }
  state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'club', mine: true, text: `${p.name} をトップチームに昇格させました。` })
  if (p.homegrown === state.playerClubId) addStory(state, p, 'promote')
  return true
}

function addStory(state: GameState, p: Player, kind: YouthStoryKind) {
  p.story = [...(p.story ?? []), kind]
  state.youthStories = [...(state.youthStories ?? []), { playerId: p.id, kind }]
  state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'club', mine: true, text: `【生え抜き】${YOUTH_STORY_TEXT[kind](p.name).split('。')[0]}。` })
}

/** 毎週: 生え抜きの選手の節目を確かめる */
export function youthStoryWeek(state: GameState) {
  if (state.mode !== 'club') return
  const me = state.playerClubId
  for (const p of Object.values(state.players)) {
    if (p.homegrown !== me || p.clubId !== me || p.isYouth || p.retired) continue
    const done = new Set(p.story ?? [])
    const career = clubCareer(state, p)
    if (!done.has('debut') && career.apps >= 1) addStory(state, p, 'debut')
    else if (!done.has('goal') && career.goals >= 1) addStory(state, p, 'goal')
    else if (!done.has('cap') && (p.intl?.caps ?? 0) >= 1) addStory(state, p, 'cap')
    else if (!done.has('apps100') && career.apps >= 100) addStory(state, p, 'apps100')
  }
}
