/** スタッフの自動生成。 */
import { jpScale } from '../data/clubs'
import type { Rng } from '../core/prng'
import { WEEKS_PER_SEASON } from '../core/calendar'
import { generateName, NATION_MIX } from '../data/nations'
import { PERSONALITIES } from '../data/personality'
import { FORMATIONS } from '../data/formations'
import type { Staff, StaffRole, StaffSkill, TacticalStyle } from '../models/staff'
import { allocId, type GameState } from '../models/game'

const clamp = (v: number, lo = 1, hi = 99) => Math.max(lo, Math.min(hi, v))

/** 役割ごとに伸びている能力 */
const ROLE_SKILLS: Record<StaffRole, StaffSkill[]> = {
  manager: ['tactics', 'mental', 'attack', 'defense'],
  headCoach: ['attack', 'defense', 'tactics'],
  attackCoach: ['attack'],
  defenseCoach: ['defense'],
  physicalCoach: ['physical'],
  gkCoach: ['gk'],
  mentalCoach: ['mental'],
  physio: ['medical'],
  analyst: ['tactics'],
  scout: ['judging', 'network'],
  youthCoach: ['youth'],
  secretary: [],
  interpreter: [],
  owner: [],
}

const STYLES: TacticalStyle[] = ['balance', 'possession', 'counter', 'wing', 'pressing', 'defensive', 'longball']

/** 年俸の目安（万円/年） */
export function staffWage(role: StaffRole, ability: number, country: string): number {
  const base = role === 'manager' ? 2400 : role === 'scout' || role === 'secretary' || role === 'interpreter' ? 500 : 900
  const lvl = jpScale(country) ? 1 : 1.6
  return Math.round((base * (0.35 + (ability / 70) ** 2.2) * lvl) / 10) * 10
}

export function generateStaff(state: GameState, rng: Rng, role: StaffRole, clubId: number, ability: number, country = 'JP'): Staff {
  const mix = NATION_MIX[country] ?? NATION_MIX.JP
  const nation = mix.codes[rng.weighted(mix.weights)]
  const name = generateName(nation, rng)
  const ab = Math.round(clamp(ability, 15, 95))
  const sub: Partial<Record<StaffSkill, number>> = {}
  for (const k of ROLE_SKILLS[role]) sub[k] = Math.round(clamp(ab + rng.normal(0, 7), 10, 99))
  const age = role === 'manager' ? rng.int(38, 64) : rng.int(30, 60)
  const s: Staff = {
    id: allocId(state, 'staff'),
    name: name.full,
    nation,
    birthAbsWeek: state.season * WEEKS_PER_SEASON - age * WEEKS_PER_SEASON - rng.int(0, 47),
    role,
    ability: ab,
    sub,
    personality: rng.pick(PERSONALITIES),
    wage: staffWage(role, ab, country),
    until: state.season + rng.int(0, 2),
    clubId,
  }
  if (role === 'manager') {
    s.style = rng.pick(STYLES)
    s.formations = {}
    // 得意なフォーメーションを 2〜3 個
    const fav = rng.shuffle([...FORMATIONS]).slice(0, rng.int(2, 3))
    for (const f of FORMATIONS) s.formations[f.id] = Math.round(clamp(fav.includes(f) ? rng.range(75, 100) : rng.range(25, 60), 0, 100))
  }
  return s
}

/** クラブの基本スタッフ（監督・ヘッドコーチ・フィジカル・GK・トレーナー・スカウト） */
export const CLUB_STAFF_ROLES: StaffRole[] = ['manager', 'headCoach', 'physicalCoach', 'gkCoach', 'physio', 'scout']
