/**
 * 能力の見方（M21）: ランク（S〜G）・得意と苦手・うちの先発との比べ。画面で能力を分かりやすく見せるための計算だけ。
 */
import { ATTRS, type AttrKey, type Attrs } from '../data/attributes'
import { formationOf } from '../data/formations'
import { POSITION_DEFS, type Position } from '../data/positions'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import { ratingAt, rawRating } from './overall'

export type Rank = 'S' | 'A' | 'B' | 'C' | 'D' | 'E' | 'F' | 'G'

/** 能力値のランク（S 90〜・A 80〜・B 70〜・C 60〜・D 50〜・E 40〜・F 30〜・G） */
export function attrRank(v: number): Rank {
  return v >= 90 ? 'S' : v >= 80 ? 'A' : v >= 70 ? 'B' : v >= 60 ? 'C' : v >= 50 ? 'D' : v >= 40 ? 'E' : v >= 30 ? 'F' : 'G'
}

/** 誤差つきの能力のランク（同じなら 1 つ、またがれば「C〜B」） */
export function rankRange(v: number, err: number): string {
  const lo = attrRank(Math.max(1, v - err))
  const hi = attrRank(Math.min(99, v + err))
  return lo === hi ? lo : `${lo}〜${hi}`
}

export interface AttrPoint {
  key: AttrKey
  name: string
  value: number
}

const NAME = Object.fromEntries(ATTRS.map((a) => [a.key, a.name])) as Record<AttrKey, string>
const FIELD_KEYS = ATTRS.filter((a) => a.group !== 'gk').map((a) => a.key)

/**
 * 得意と苦手。
 *   得意: 高い能力の上から 3 つ（GK は GK に大事な能力から）
 *   苦手: そのポジションで大事な能力のうち、低い 2 つ
 */
export function strengthsOf(attr: Attrs, pos: Position): { strong: AttrPoint[]; weak: AttrPoint[] } {
  const relevant = Object.keys(POSITION_DEFS[pos].weights) as AttrKey[]
  const pool = pos === 'GK' ? relevant : FIELD_KEYS
  const pt = (key: AttrKey): AttrPoint => ({ key, name: NAME[key], value: attr[key] })
  const strong = [...pool].sort((a, b) => attr[b] - attr[a]).slice(0, 3).map(pt)
  const strongKeys = new Set(strong.map((s) => s.key))
  const weak = relevant
    .filter((k) => !strongKeys.has(k))
    .sort((a, b) => attr[a] - attr[b])
    .slice(0, 2)
    .map(pt)
  return { strong, weak }
}

export interface StarterCompare {
  pos: Position
  /** うちの先発（そのポジションでいちばん弱い人。枠はあるが空きなら -1） */
  starterId: number
  starterRating: number
  /** この選手のそのポジションでの評価（推定の能力から） */
  rating: number
  diff: number
}

/** うちのフォーメーションの同じポジションの先発と比べる（枠がなければ null） */
export function compareWithStarter(state: GameState, p: Player, attr: Attrs): StarterCompare | null {
  const me = state.clubs[state.playerClubId]
  if (!me || p.clubId === me.id) return null
  const f = formationOf(me.tactics.formation)
  const pos = p.pos
  let starterId = -1
  let starterRating = Infinity
  f.slots.forEach((s, i) => {
    if (s.pos !== pos) return
    const q = state.players[me.lineup.starters[i]]
    const r = q ? ratingAt(q, pos) : 0
    if (r < starterRating) {
      starterRating = r
      starterId = q ? q.id : -1
    }
  })
  if (starterRating === Infinity) return null
  const rating = rawRating(attr, pos) * (0.75 + (0.25 * (p.apt[pos] ?? 0)) / 100)
  return { pos, starterId, starterRating, rating, diff: rating - starterRating }
}
