/** 総合値（OVR）・年齢・市場価値・年俸の目安。 */
import type { Attrs } from '../data/attributes'
import { POSITION_DEFS, type Position } from '../data/positions'
import { ageAt } from '../core/calendar'
import type { Player } from '../models/player'

const WEIGHT_SUM: Record<Position, number> = Object.fromEntries(
  Object.values(POSITION_DEFS).map((d) => [d.id, Object.values(d.weights).reduce((s, w) => s + (w ?? 0), 0)]),
) as Record<Position, number>

/** ポジションごとの重みを配列にしたもの（毎週たくさん呼ぶので、オブジェクトの for-in を避ける。足す順番は同じ） */
const WEIGHT_KEYS = Object.fromEntries(Object.values(POSITION_DEFS).map((d) => [d.id, Object.keys(d.weights) as (keyof Attrs)[]])) as Record<Position, (keyof Attrs)[]>
const WEIGHT_VALS = Object.fromEntries(Object.values(POSITION_DEFS).map((d) => [d.id, Object.keys(d.weights).map((k) => d.weights[k as keyof Attrs] ?? 0)])) as Record<Position, number[]>

/** 能力値だけから見たポジション別の総合値（適性は無視） */
export function rawRating(attr: Attrs, pos: Position): number {
  const keys = WEIGHT_KEYS[pos]
  const vals = WEIGHT_VALS[pos]
  let s = 0
  for (let i = 0; i < keys.length; i++) s += attr[keys[i]] * vals[i]
  return s / WEIGHT_SUM[pos]
}

/** 適性を含めた、そのポジションでの総合値 */
export function ratingAt(p: Player, pos: Position): number {
  return rawRating(p.attr, pos) * (0.75 + 0.25 * (p.apt[pos] ?? 0) / 100)
}

export function ovr(p: Player): number {
  return Math.round(ratingAt(p, p.pos))
}

/** 上限まで育ったときの総合値（隠し） */
export function potentialOvr(p: Player): number {
  return Math.round(rawRating(p.cap, p.pos))
}

export function ageOf(p: Player, absWeek: number): number {
  return ageAt(absWeek, p.birthAbsWeek)
}

/** 国ごとの年俸水準 */
export const WAGE_LEVEL: Record<string, number> = { JP: 1.0, EN: 2.2, ES: 1.8, IT: 1.7, DE: 1.7, FR: 1.5, BR: 0.8 }

/** 年俸の目安（万円/年） */
export function fairWage(o: number, age: number, country: string): number {
  const base = Math.max(240, (o - 40) ** 2 * 14)
  const ageMul = age <= 19 ? 0.45 : age <= 21 ? 0.65 : age >= 33 ? 0.85 : 1
  return Math.round((base * ageMul * (WAGE_LEVEL[country] ?? 1)) / 10) * 10
}

/** 市場価値（万円） */
export function marketValue(p: Player, absWeek: number, season: number): number {
  const o = ovr(p)
  const age = ageOf(p, absWeek)
  const pot = potentialOvr(p)
  let v = Math.max(0, o - 40) ** 2.5 * 9
  // 若くて伸びしろがあるほど高い
  if (age <= 23) v *= 1 + Math.max(0, pot - o) * 0.04 * ((24 - age) / 6)
  if (age >= 30) v *= Math.max(0.2, 1 - (age - 29) * 0.14)
  // 契約が残り少ないと安い
  const left = p.contract.until - season
  if (left <= 0) v *= 0.45
  else if (left === 1) v *= 0.8
  v = Math.max(100, v)
  return Math.round(v / 100) * 100
}

/** 体重（kg）。持っていなければ身長からの目安（BMI 22.5） */
export function weightOf(p: { heightCm: number; weightKg?: number }): number {
  return p.weightKg ?? Math.round(22.5 * (p.heightCm / 100) ** 2)
}
