/**
 * 家と車（M12）。
 *   家: 賃貸（寮・アパート・マンション）と、買う家 8 件。買った家は ownedHomes、住んでいる家は housing。
 *     欧州の家は、その国のクラブにいるときだけ住める。住んでいない持ち家は別荘（シーズンのはじめに体力と調子が戻る）。
 *     売ると 8 割が戻る。移籍で国が変わったら、住める家へ引っ越す（relocateForRegion）。
 *   車: 車庫の数は住まいで決まる。いつも乗る車の効果が毎週入り、持っている台数で知名度も少しずつ上がる。
 *     売ると値下がりした分が戻る（クラシックカーは値上がりする）。古いセーブのぜいたく品「高級車」は欧州製の高級セダンにする。
 */
import { CAR_BY_ID, HOUSING, HOUSING_BY_ID, REGION_NAME, type HousingDef } from '../data/career'
import type { GameState } from '../models/game'
import type { CarId, HousingId, OwnedCar } from '../models/career'
import { clamp, regionOf, report } from './core'
import { gainExp } from './growth'

/** 家を売ったときに戻る割合 */
export const HOME_RESALE = 0.8

export function housingOf(state: GameState): HousingDef {
  return HOUSING_BY_ID[state.career!.housing ?? 'dorm'] ?? HOUSING_BY_ID.dorm
}

/** 住まいの段（0 寮〜4 豪邸） */
export function homeGrade(state: GameState): number {
  return housingOf(state).grade
}

/** 持っている家（古いセーブで一軒家・豪邸に住んでいれば、それを持っている家にする） */
export function ownedHomes(state: GameState): HousingId[] {
  const c = state.career!
  const cur = housingOf(state)
  if (cur.kind === 'own' && !(c.ownedHomes ?? []).includes(cur.id)) c.ownedHomes = [...(c.ownedHomes ?? []), cur.id]
  return c.ownedHomes ?? []
}

/** 今の国で住めるか（賃貸はどこでも、買った家はその国だけ） */
export function canLiveIn(state: GameState, id: HousingId): boolean {
  const h = HOUSING_BY_ID[id]
  if (h.kind === 'rent') return true
  return ownedHomes(state).includes(id) && (!h.region || h.region.includes(regionOf(state)))
}

/** 住んでいない持ち家（別荘） */
export function villaHomes(state: GameState): HousingId[] {
  const cur = state.career!.housing ?? 'dorm'
  return ownedHomes(state).filter((id) => id !== cur)
}

export function homeSellValue(id: HousingId): number {
  return Math.round(HOUSING_BY_ID[id].cost * HOME_RESALE)
}

/** 買えるか */
export function canBuyHome(state: GameState, id: HousingId): { ok: boolean; reason?: string } {
  const h = HOUSING_BY_ID[id]
  if (h.kind !== 'own') return { ok: false }
  if (ownedHomes(state).includes(id)) return { ok: false, reason: '持っている' }
  if (state.career!.money < h.cost) return { ok: false, reason: '貯金が足りない' }
  return { ok: true }
}

/** 家を買う。今の国で住めて、今より良い家なら、そのまま引っ越す */
export function buyHome(state: GameState, id: HousingId): boolean {
  if (!canBuyHome(state, id).ok) return false
  const c = state.career!
  const h = HOUSING_BY_ID[id]
  c.money -= h.cost
  c.ownedHomes = [...ownedHomes(state), id]
  report(state, `${h.name}を買った（${h.cost.toLocaleString()} 万円）。`)
  const cur = housingOf(state)
  if (canLiveIn(state, id) && (h.grade > cur.grade || (h.grade === cur.grade && h.rest > cur.rest))) moveInto(state, id)
  return true
}

/** 引っ越せるか（賃貸は引っ越しの費用、持ち家は無料） */
export function canMoveInto(state: GameState, id: HousingId): { ok: boolean; reason?: string } {
  const c = state.career!
  const h = HOUSING_BY_ID[id]
  if ((c.housing ?? 'dorm') === id) return { ok: false, reason: '今の住まい' }
  if (h.kind === 'own') {
    if (!ownedHomes(state).includes(id)) return { ok: false, reason: '持っていない' }
    if (!canLiveIn(state, id)) return { ok: false, reason: `${h.region!.map((r) => REGION_NAME[r]).join('・')}のクラブにいるとき` }
    return { ok: true }
  }
  if (c.money < h.cost) return { ok: false, reason: '貯金が足りない' }
  return { ok: true }
}

export function moveInto(state: GameState, id: HousingId): boolean {
  if (!canMoveInto(state, id).ok) return false
  const c = state.career!
  const h = HOUSING_BY_ID[id]
  if (h.kind === 'rent') c.money -= h.cost
  c.housing = id
  report(state, `${h.name}に引っ越した。`)
  return true
}

/** 家を売る（住んでいる家なら、住める持ち家かマンションへ移る） */
export function sellHome(state: GameState, id: HousingId): boolean {
  const c = state.career!
  if (!ownedHomes(state).includes(id)) return false
  const living = (c.housing ?? 'dorm') === id
  c.money += homeSellValue(id)
  c.ownedHomes = ownedHomes(state).filter((x) => x !== id)
  report(state, `${HOUSING_BY_ID[id].name}を売った（${homeSellValue(id).toLocaleString()} 万円）。`)
  if (living) {
    // 先に賃貸へ移してから選ぶ（住んでいる家は持ち家として数え直されるため）
    c.housing = 'mansion'
    const next = bestLivableOwned(state) ?? 'mansion'
    c.housing = next
    report(state, `${HOUSING_BY_ID[next].name}に移った。`)
  }
  return true
}

/** 今の国で住める持ち家のうち、いちばん良い家 */
function bestLivableOwned(state: GameState): HousingId | undefined {
  return ownedHomes(state)
    .filter((id) => canLiveIn(state, id))
    .sort((a, b) => HOUSING_BY_ID[b].grade - HOUSING_BY_ID[a].grade || HOUSING_BY_ID[b].rest - HOUSING_BY_ID[a].rest)[0]
}

/**
 * 移籍で国が変わったとき: 今の家に住めなければ、住める持ち家（なければクラブが用意したマンション）へ。
 * 賃貸に住んでいて、その国に持ち家があれば戻る。
 */
export function relocateForRegion(state: GameState) {
  const c = state.career!
  const cur = housingOf(state)
  const best = bestLivableOwned(state)
  if (!canLiveIn(state, cur.id)) {
    const next = best ?? 'mansion'
    c.housing = next
    report(state, `${REGION_NAME[regionOf(state)]}では${HOUSING_BY_ID[next].name}に住むことにした。${cur.name}は別荘として残した。`)
  } else if (cur.kind === 'rent' && best && HOUSING_BY_ID[best].grade >= cur.grade) {
    c.housing = best
    report(state, `${HOUSING_BY_ID[best].name}に戻ってきた。`)
  }
}

/** 家の毎週の費用: 住んでいる賃貸の家賃と、持っている家すべての維持費 */
export function homesWeeklyCost(state: GameState): number {
  const cur = housingOf(state)
  return (cur.kind === 'rent' ? cur.weekly : 0) + ownedHomes(state).reduce((n, id) => n + HOUSING_BY_ID[id].weekly, 0)
}

/** 住まいの毎週の特長と、別荘の効果（シーズンのはじめ） */
export function homesWeek(state: GameState) {
  const c = state.career!
  const p = state.players[c.playerId]
  const perk = housingOf(state).perk
  if (perk?.stamina) c.stamina = clamp(c.stamina + perk.stamina, 0, 100)
  if (perk?.exp) gainExp(state, perk.exp)
  if (perk?.fame) c.fame = clamp(c.fame + perk.fame, 0, 100)
  if (state.week === 0 && villaHomes(state).length) {
    c.stamina = 100
    p.condition = 100
  }
}

// ---------------------------------------------------------------- 車

/** 車庫の数 */
export function garageSize(state: GameState): number {
  return housingOf(state).garage
}

/** 持っている車（古いセーブのぜいたく品「高級車」を、欧州製の高級セダンにする） */
export function carsOf(state: GameState): OwnedCar[] {
  const c = state.career!
  if (c.luxuries?.includes('car')) {
    c.luxuries = c.luxuries.filter((x) => x !== 'car')
    if (!(c.cars ?? []).some((x) => x.id === 'sedan')) c.cars = [...(c.cars ?? []), { id: 'sedan', season: state.season }]
    c.mainCar ??= 'sedan'
  }
  return c.cars ?? []
}

export function hasCar(state: GameState): boolean {
  return carsOf(state).length > 0
}

export function canBuyCar(state: GameState, id: CarId): { ok: boolean; reason?: string } {
  const cars = carsOf(state)
  if (cars.some((x) => x.id === id)) return { ok: false, reason: '持っている' }
  if (cars.length >= garageSize(state)) return { ok: false, reason: `車庫は ${garageSize(state)} 台まで` }
  if (state.career!.money < CAR_BY_ID[id].cost) return { ok: false, reason: '貯金が足りない' }
  return { ok: true }
}

export function buyCar(state: GameState, id: CarId): boolean {
  if (!canBuyCar(state, id).ok) return false
  const c = state.career!
  const def = CAR_BY_ID[id]
  c.money -= def.cost
  c.cars = [...carsOf(state), { id, season: state.season }]
  c.mainCar ??= id
  if (def.buyFame) c.fame = clamp(c.fame + def.buyFame, 0, 100)
  report(state, `${def.name}を買った（${def.cost.toLocaleString()} 万円）。`)
  return true
}

/** 今売ったときの値段（年々下がる。クラシックカーは上がる） */
export function carValue(state: GameState, car: OwnedCar): number {
  const def = CAR_BY_ID[car.id]
  const age = Math.max(0, state.season - car.season)
  const mul = def.appreciate ? Math.min(2, 1 + def.appreciate * age) : Math.max(0.3, 0.75 - 0.08 * age)
  return Math.round(def.cost * mul)
}

export function sellCar(state: GameState, id: CarId): boolean {
  const c = state.career!
  const car = carsOf(state).find((x) => x.id === id)
  if (!car) return false
  const v = carValue(state, car)
  c.money += v
  c.cars = carsOf(state).filter((x) => x.id !== id)
  if (c.mainCar === id) c.mainCar = [...c.cars].sort((a, b) => CAR_BY_ID[b.id].cost - CAR_BY_ID[a.id].cost)[0]?.id
  report(state, `${CAR_BY_ID[id].name}を売った（${v.toLocaleString()} 万円）。`)
  return true
}

export function setMainCar(state: GameState, id: CarId) {
  if (carsOf(state).some((x) => x.id === id)) state.career!.mainCar = id
}

/** いつも乗る車 */
export function mainCarOf(state: GameState): CarId | undefined {
  const c = state.career!
  const cars = carsOf(state)
  if (c.mainCar && cars.some((x) => x.id === c.mainCar)) return c.mainCar
  return cars[0]?.id
}

export function carsWeeklyCost(state: GameState): number {
  return carsOf(state).reduce((n, x) => n + CAR_BY_ID[x.id].weekly, 0)
}

/** 毎週: いつも乗る車の効果と、持っている台数の知名度 */
export function carsWeek(state: GameState) {
  const c = state.career!
  const p = state.players[c.playerId]
  const main = mainCarOf(state)
  if (main) {
    const def = CAR_BY_ID[main]
    if (def.condition) p.condition = clamp(p.condition + def.condition, 0, 100)
    if (def.stamina) c.stamina = clamp(c.stamina + def.stamina, 0, 100)
    if (def.fame) c.fame = clamp(c.fame + def.fame, 0, 100)
  }
  const n = carsOf(state).length
  if (n >= 3) c.fame = clamp(c.fame + 0.01 * n, 0, 100)
}

/**
 * 貯金が足りないときに 1 つ売る: 乗っていない車 → 別荘 → いつも乗る車 → 住んでいる持ち家。売ったら true
 */
export function sellAssetForCash(state: GameState): boolean {
  const main = mainCarOf(state)
  const spare = carsOf(state)
    .filter((x) => x.id !== main)
    .sort((a, b) => carValue(state, b) - carValue(state, a))[0]
  if (spare) return sellCar(state, spare.id)
  const villa = villaHomes(state).sort((a, b) => HOUSING_BY_ID[b].cost - HOUSING_BY_ID[a].cost)[0]
  if (villa) return sellHome(state, villa)
  if (main) return sellCar(state, main)
  const cur = housingOf(state)
  if (cur.kind === 'own') return sellHome(state, cur.id)
  return false
}

/** 画面用: 家の一覧 */
export const HOMES_FOR_SALE = HOUSING.filter((h) => h.kind === 'own')
export const RENTALS = HOUSING.filter((h) => h.kind === 'rent')
