/**
 * お金（万円）。自クラブは週ごとの帳簿を付け、AI クラブは簡単な収支で資金を動かす。
 * M4 でスポンサー・グッズ・施設の維持費などを作り込む。
 */
import { jpScale } from '../data/clubs'
import type { Rng } from '../core/prng'
import type { Club } from '../models/club'
import type { GameState, WeekFinance } from '../models/game'
import type { Player } from '../models/player'
import { WEEKS_PER_SEASON } from '../core/calendar'
import { localSupport, sponsorIncome } from './sponsors'
import { bizLevel, businessWeek } from './business'
import { academyWeek } from '../club/academy'
import { WL_TV, worldGoods, worldVisitors } from '../club/worldClass'
import { hasTrait } from '../club/town'
import { merchMul, seasonTicketEstimate, seasonTicketHolders, ticketLevel } from './sales'
import { tieAttendanceMul } from '../club/community'

/** リーグの分配金（シーズンあたり） */
export const TV_MONEY: Record<number, number> = { 1: 35000, 2: 15000, 3: 5000 }

/** 入場料の平均（万円/人） */
export const TICKET_PRICE = 0.3

export function emptyWeek(absWeek: number): WeekFinance {
  return { absWeek, ticket: 0, tv: 0, sponsor: 0, goods: 0, prize: 0, transferIn: 0, wages: 0, staffWages: 0, maintenance: 0, construction: 0, transferOut: 0, other: 0 }
}

export function weekNet(w: WeekFinance): number {
  return w.ticket + w.tv + w.sponsor + w.goods + w.prize + w.transferIn + w.other + (w.business ?? 0) - (w.youth ?? 0) - w.wages - w.staffWages - w.maintenance - w.construction - w.transferOut
}

/** 観客数（人）: サポーター・人気・相手の格・スタジアムの設備から。収容人数が上限。mul はダービーなど */
export function attendanceFor(state: GameState, club: Club, opp: Club, rng: Rng, mul = 1): number {
  const base = club.fans * (0.32 + club.popularity * 0.004) * (0.9 + club.stadium.grade * 0.05) + opp.rep * 60 + (club.isPlayer ? state.hometown.passion * 20 : 0)
  // スタジアムカフェがあると客が増える
  const cafe = club.isPlayer ? 1 + bizLevel(state, club, 'cafe') * 0.03 : 1
  // 観光の街（M19）: 観光客が少し入る。チケットの値段で客の入りが変わり、年間シートの人は毎試合来る
  const tourism = hasTrait(state, 'tourism', club) ? 1.05 : 1
  // 地域とのつながり（M19）の段で 1% ずつ
  const price = club.isPlayer ? ticketLevel(club).att * tieAttendanceMul(state) : 1
  // 海外のファン（M24 の 2 回目）: 海外から観に来る人
  const visitors = club.isPlayer ? worldVisitors(club) : 0
  const n = Math.round(Math.min(club.stadium.capacity, base * cafe * tourism * price * mul * rng.range(0.85, 1.15) + visitors))
  return Math.min(club.stadium.capacity, Math.max(n, seasonTicketHolders(state, club)))
}

/** 入場料の平均（万円/人）: 設備が良いほど高く取れる */
export function ticketPrice(club: Club): number {
  return TICKET_PRICE * (0.85 + club.stadium.grade * 0.08)
}

export function squadWages(state: GameState, clubId: number, squad?: Player[]): number {
  let s = 0
  const list = squad ?? Object.values(state.players).filter((p) => p.clubId === clubId && !p.retired)
  for (const p of list) s += p.loan && p.loan.fromClubId !== clubId ? p.contract.wage * p.loan.wageShare : p.contract.wage
  return s
}

export function staffWages(state: GameState, club: Club): number {
  return club.staff.reduce((s, id) => s + (state.staff[id]?.wage ?? 0), 0)
}

/** 施設とスタジアムの維持費（シーズンあたり） */
export function maintenancePerSeason(club: Club): number {
  const fac = Object.values(club.facilities).reduce((s, l) => s + l ** 1.4 * 180, 0)
  return Math.round(fac + club.stadium.capacity * 0.08 + club.stadium.grade * 400)
}

/** スポンサー収入（シーズンあたり）: 契約＋地元の小口 */
export function sponsorPerSeason(state: GameState, club: Club): number {
  return sponsorIncome(club) + localSupport(state, club)
}

/** グッズ収入（シーズンあたり）。観光の街（M19）は 15% 増 */
export function goodsPerSeason(club: Club, state?: GameState): number {
  const tourism = state && hasTrait(state, 'tourism', club) ? 1.15 : 1
  const merch = state ? merchMul(state, club) : 1
  // 海外のファン（M24 の 2 回目）: 海外向けオンラインストア
  const world = club.isPlayer ? worldGoods(club) : 0
  return Math.round(club.fans * 0.25 * (0.5 + club.popularity / 100) * (1 + club.facilities.pr * 0.08) * tourism * merch + world)
}

/** 資金難: マイナスが 8 週続くとオーナーが資金を入れる。3 回目はゲームオーバー */
export function checkMoney(state: GameState): 'ok' | 'warn' | 'bailout' | 'gameOver' {
  const club = state.clubs[state.playerClubId]
  if (club.budget >= 0) {
    state.money.negWeeks = 0
    return 'ok'
  }
  state.money.negWeeks++
  if (state.money.negWeeks < 8) return 'warn'
  state.money.negWeeks = 0
  if (state.money.bailouts >= 2) {
    state.money.gameOver = true
    return 'gameOver'
  }
  state.money.bailouts++
  const inject = -club.budget + 20000
  club.budget += inject
  club.rep = Math.max(5, club.rep - 3)
  club.popularity = Math.max(1, club.popularity - 5)
  return 'bailout'
}

/** 自クラブの 1 週間の収支を付ける（ホームゲームがあれば入場料も） */
export function playerWeekFinance(state: GameState, absWeek: number, homeAttendance: number, squads?: Map<number, Player[]>): WeekFinance {
  const club = state.clubs[state.playerClubId]
  const comp = state.competitions.find((c) => c.id === club.leagueId)
  const w = emptyWeek(absWeek)
  // 入場料（年間シートの人の分は前払い済み）。チケットの値段の段で 1 人あたりが変わる
  const holders = homeAttendance > 0 ? seasonTicketHolders(state, club) : 0
  w.ticket = Math.round(Math.max(0, homeAttendance - holders) * ticketPrice(club) * ticketLevel(club).price)
  // 年間シート: シーズンのはじめ（第 0 週）に売る（M19）
  if (absWeek % WEEKS_PER_SEASON === 0 && club.sales?.seasonTickets && club.sales.sold?.season !== state.season) {
    const est = seasonTicketEstimate(club, ticketPrice(club))
    club.sales.sold = { season: state.season, ...est }
    w.ticket += est.revenue
    state.news.push({ absWeek, category: 'club', mine: true, text: `年間シートが ${est.count.toLocaleString()} 席売れた（${est.revenue.toLocaleString()} 万円）。` })
  }
  w.tv = Math.round((comp?.id === 'WL' ? WL_TV : (TV_MONEY[comp?.tier ?? 3] ?? 5000)) / WEEKS_PER_SEASON)
  w.sponsor = Math.round(sponsorPerSeason(state, club) / WEEKS_PER_SEASON)
  w.goods = Math.round(goodsPerSeason(club, state) / WEEKS_PER_SEASON)
  w.wages = Math.round(squadWages(state, club.id, squads?.get(club.id)) / WEEKS_PER_SEASON)
  w.staffWages = Math.round(staffWages(state, club) / WEEKS_PER_SEASON)
  w.maintenance = Math.round(maintenancePerSeason(club) / WEEKS_PER_SEASON)
  w.business = businessWeek(state, club, absWeek, homeAttendance > 0)
  // 海外アカデミーの運営費（M25）
  w.youth = academyWeek(state, club, absWeek)
  club.budget += weekNet(w)
  state.finance.push(w)
  if (state.finance.length > 104) state.finance.splice(0, state.finance.length - 104)
  return w
}

/** AI クラブ: 格に見合った収入で、資金はゆっくり増える（M5 の移籍で使う） */
export function aiWeekFinance(state: GameState, squads?: Map<number, Player[]>) {
  for (const club of state.clubs) {
    if (club.isPlayer) continue
    const wages = squadWages(state, club.id, squads?.get(club.id) ?? []) + staffWages(state, club)
    const income = wages * 1.04 + club.rep * 60 * (jpScale(club.country) ? 1 : 3)
    club.budget += Math.round((income - wages) / WEEKS_PER_SEASON)
  }
}

/** 順位に応じた賞金（シーズン末） */
export function prizeMoney(tier: number, rank: number): number {
  const top = tier === 1 ? 30000 : tier === 2 ? 10000 : 3000
  if (rank === 1) return top
  if (rank <= 3) return Math.round(top * 0.4)
  if (rank <= 6) return Math.round(top * 0.15)
  return 0
}
