/**
 * 交渉の土台: 相手クラブの求める額と、獲得・更改をまとめる処理。
 * 交渉の進め方（見込み・逆提案・ドラマ）は talks.ts。
 */
import { absWeekOf } from '../core/calendar'
import type { GameState } from '../models/game'
import type { Player, SquadRole } from '../models/player'
import { askingPrice, completeTransfer } from './market'

/** 相手クラブが求める額（格上のクラブは主力を手放したがらない） */
export function clubAsk(state: GameState, p: Player, ranks?: Map<number, number>): number {
  if (p.clubId < 0) return 0
  const club = state.clubs[p.clubId]
  const me = state.clubs[state.playerClubId]
  const pride = club.rep > me.rep + 15 ? 1.15 : 1
  return Math.round((askingPrice(state, p, ranks) * pride) / 100) * 100
}

/** 獲得をまとめる（移籍金と条件がそろったとき） */
export function finalizeSigning(state: GameState, p: Player, fee: number, wage: number, years: number, role?: SquadRole): boolean {
  const me = state.clubs[state.playerClubId]
  if (me.budget < fee) return false
  completeTransfer(state, p, me.id, p.clubId < 0 ? 0 : fee, { wage, until: state.season + years - 1, role })
  return true
}

/** 契約更改をまとめる */
export function finalizeRenewal(state: GameState, p: Player, wage: number, years: number, role?: SquadRole) {
  p.contract = { ...p.contract, wage, until: state.season + years, role }
  p.morale = Math.min(100, p.morale + 10)
  state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'transfer', mine: true, text: `${p.name} と契約を更新しました（年俸 ${wage.toLocaleString()} 万円・${years} 年）。` })
}
