/**
 * チケットとグッズ（M19。自クラブだけ）。
 *   チケット: 値段 5 段。安いほど客が入り人気も少し上がる。高いほど 1 人あたりの収入が増える（満員なら得）
 *   年間シート: シーズンのはじめ（第 0 週）に売る。前払いで、持っている人は毎試合来る（その分の入場料は試合ごとには入らない）
 *   グッズ: 商品の種類を Lv 0〜3 に。選手グッズは人気の選手（総合・得点・固有キャラ・生え抜き）で伸びる
 */
import type { Club } from '../models/club'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import { ovr } from '../player/overall'

export interface TicketLevel {
  name: string
  /** 入場料の倍率 */
  price: number
  /** 観客の倍率 */
  att: number
  /** ホームの試合ごとの人気の変化 */
  pop: number
}

export const TICKET_LEVELS: TicketLevel[] = [
  { name: 'とても安い', price: 0.7, att: 1.18, pop: 0.15 },
  { name: '安い', price: 0.85, att: 1.08, pop: 0.05 },
  { name: 'ふつう', price: 1, att: 1, pop: 0 },
  { name: '高い', price: 1.2, att: 0.9, pop: -0.05 },
  { name: 'とても高い', price: 1.45, att: 0.78, pop: -0.12 },
]

/** 年間シートの割引（1 試合あたりの値段に対して） */
export const SEASON_TICKET_DISCOUNT = 0.85
/** 年間シートで数える 1 シーズンのホームの試合 */
export const SEASON_HOME_GAMES = 17

export type MerchLineId = 'replica' | 'towel' | 'player' | 'kids' | 'collab'

export interface MerchLineDef {
  id: MerchLineId
  name: string
  desc: string
  /** Lv を 1 上げる費用の基準（万円。次の Lv × これ） */
  cost: number
  /** Lv ごとのグッズ収入の増え方 */
  bonus: number
}

export const MERCH_LINES: MerchLineDef[] = [
  { id: 'replica', name: 'レプリカユニフォーム', desc: 'いちばんの売れ筋', cost: 600, bonus: 0.2 },
  { id: 'towel', name: 'タオルマフラー', desc: '安くて手に取りやすい', cost: 200, bonus: 0.08 },
  { id: 'player', name: '選手グッズ', desc: '人気の選手がいるほど売れる', cost: 400, bonus: 0.15 },
  { id: 'kids', name: 'キッズグッズ', desc: '家族連れのファンに', cost: 300, bonus: 0.1 },
  { id: 'collab', name: '地元コラボ商品', desc: 'ホームタウンの店といっしょに', cost: 500, bonus: 0.12 },
]

export const MERCH_MAX = 3

export function salesOf(club: Club) {
  club.sales ??= { ticket: 2, seasonTickets: false }
  return club.sales
}

export function ticketLevel(club: Club): TicketLevel {
  return TICKET_LEVELS[club.sales?.ticket ?? 2] ?? TICKET_LEVELS[2]
}

export function merchLevel(club: Club, id: MerchLineId): number {
  return club.sales?.merch?.[id] ?? 0
}

/** 人気の選手（選手グッズの売れ行き）: 上位 3 人 */
export function starPlayers(state: GameState, club: Club): { p: Player; score: number }[] {
  return Object.values(state.players)
    .filter((p) => p.clubId === club.id && !p.retired)
    .map((p) => ({ p, score: ovr(p) + p.stats.goals * 0.8 + (p.starId ? 8 : 0) + (p.homegrown !== undefined ? 4 : 0) }))
    .sort((a, b) => b.score - a.score)
    .slice(0, 3)
}

/** グッズ収入の倍率（商品の Lv と、人気の選手） */
export function merchMul(state: GameState, club: Club): number {
  if (!club.isPlayer || !club.sales?.merch) return 1
  let mul = 1
  for (const def of MERCH_LINES) {
    const lv = merchLevel(club, def.id)
    if (!lv) continue
    let b = def.bonus * lv
    if (def.id === 'player') {
      const stars = starPlayers(state, club).reduce((s, x) => s + x.score, 0)
      b *= Math.max(0.5, Math.min(2, stars / 180))
    }
    mul += b
  }
  return mul
}

export function merchUpgradeCost(club: Club, id: MerchLineId): number | null {
  const lv = merchLevel(club, id)
  if (lv >= MERCH_MAX) return null
  return MERCH_LINES.find((d) => d.id === id)!.cost * (lv + 1)
}

export function upgradeMerch(state: GameState, id: MerchLineId): boolean {
  const club = state.clubs[state.playerClubId]
  const cost = merchUpgradeCost(club, id)
  if (cost === null || club.budget < cost) return false
  const s = salesOf(club)
  s.merch = { ...s.merch, [id]: merchLevel(club, id) + 1 }
  club.budget -= cost
  const last = state.finance[state.finance.length - 1]
  if (last) last.other -= cost
  return true
}

/** 年間シートの見込み（人数と前払いの額）。シーズンのはじめに売る */
export function seasonTicketEstimate(club: Club, ticketPrice: number): { count: number; revenue: number } {
  const lv = ticketLevel(club)
  const rate = 0.12 * lv.att * (0.6 + club.popularity / 100)
  const count = Math.round(Math.min(club.stadium.capacity * 0.45, club.fans * rate) / 10) * 10
  const revenue = Math.round(count * ticketPrice * lv.price * SEASON_TICKET_DISCOUNT * SEASON_HOME_GAMES)
  return { count, revenue }
}

/** 今季の年間シートを持っている人の数 */
export function seasonTicketHolders(state: GameState, club: Club): number {
  const sold = club.sales?.sold
  return club.isPlayer && sold && sold.season === state.season ? sold.count : 0
}
