/**
 * イベントの発生と選択の反映、やる気の変化と移籍志願。
 */
import type { Rng } from '../core/prng'
import { absWeekOf } from '../core/calendar'
import { CLUB_EVENTS, EVENT_BY_ID, type ClubEventDef, type EventEffect } from '../data/clubEvents'
import { allocId, type GameState } from '../models/game'
import type { Player } from '../models/player'
import { ageOf, fairWage, marketValue, ovr } from '../player/overall'
import { isTransferWindow, windowPace } from '../core/calendar'
import { jpScale } from '../data/clubs'
import { starterOvrForRep } from '../gen/playerGen'
import { completeTransfer } from '../transfer/market'
import { squadOf } from '../match/lineup'
import { chemKey } from './chemistry'
import { bizLevel, boostBusiness } from '../economy/business'
import { academyGem } from './academy'
import type { BusinessId } from '../models/club'
import { weekRng } from '../core/prng'
import { hasTrait } from './town'

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

function pickTarget(state: GameState, def: ClubEventDef, rng: Rng): Player | undefined {
  const me = state.clubs[state.playerClubId]
  const sq = squadOf(state, me.id)
  const age = (p: Player) => (absWeekOf(state.season, state.week) - p.birthAbsWeek) / 48
  const starters = new Set(me.lineup.starters)
  let pool = sq
  if (def.target === 'young') pool = sq.filter((p) => age(p) < 22)
  else if (def.target === 'star') pool = [...sq].sort((a, b) => ovr(b) - ovr(a)).slice(0, 4)
  else if (def.target === 'bench') pool = sq.filter((p) => !starters.has(p.id) && !p.injury)
  return pool.length ? rng.pick(pool) : undefined
}

/** 週にときどきイベントを起こす（返事待ちがあるときは起こさない） */
export function maybeEvent(state: GameState, rng: Rng): boolean {
  if (state.offers.some((o) => o.kind === 'event') || !rng.chance(0.07)) return false
  // 事業のイベントは、その事業が営業しているときだけ
  const me = state.clubs[state.playerClubId]
  const pool = CLUB_EVENTS.filter((e) => !e.business || bizLevel(state, me, e.business) > 0)
  const def = pool[rng.weighted(pool.map((e) => e.weight))]
  const target = def.target ? pickTarget(state, def, rng) : undefined
  if (def.target && !target) return false
  state.offers.push({ kind: 'event', eventId: def.id, playerId: target?.id, expiresAbsWeek: absWeekOf(state.season, state.week) + 3, id: allocId(state, 'offer') })
  return true
}

export function fillEventText(state: GameState, text: string, playerId?: number): string {
  const me = state.clubs[state.playerClubId]
  const p = playerId !== undefined ? state.players[playerId] : undefined
  return text.replace(/\{p\}/g, p?.name ?? '選手').replace(/\{c\}/g, me.name).replace(/\{t\}/g, state.hometown.city)
}

/** 選択を反映して、結果の文を返す */
export function resolveEvent(state: GameState, offerId: number, optionIndex: number): string | null {
  const o = state.offers.find((x) => x.id === offerId)
  if (!o || o.kind !== 'event') return null
  const def = EVENT_BY_ID[o.eventId]
  const opt = def?.options[optionIndex]
  state.offers = state.offers.filter((x) => x.id !== offerId)
  if (!opt) return null
  applyEffect(state, opt.effect, o.playerId, def.business)
  const text = fillEventText(state, opt.result, o.playerId)
  state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'event', mine: true, text: `【${def.title}】${text}` })
  return text
}

function applyEffect(state: GameState, e: EventEffect, playerId?: number, business?: BusinessId) {
  const me = state.clubs[state.playerClubId]
  const now = absWeekOf(state.season, state.week)
  if (business && e.bizBoost) boostBusiness(state, me, business, e.bizBoost.mul, e.bizBoost.weeks, e.bizBoost.label)
  if (business === 'academy' && e.prospect) academyGem(state, e.prospect, weekRng(state.seed, now, 0xacad))
  const sq = squadOf(state, me.id)
  if (e.budget) me.budget += e.budget
  if (e.popularity) me.popularity = clamp(me.popularity + e.popularity, 1, 100)
  if (e.fans) me.fans = Math.max(300, me.fans + e.fans)
  if (e.development) state.hometown.development = clamp(state.hometown.development + e.development, 0, 100)
  for (const p of sq) {
    if (e.morale) p.morale = clamp(p.morale + e.morale, 0, 100)
    if (e.condition) p.condition = clamp(p.condition + e.condition, 5, 100)
  }
  if (e.chem) {
    for (let i = 0; i < sq.length; i++)
      for (let j = i + 1; j < sq.length; j++) {
        const k = chemKey(sq[i].id, sq[j].id)
        if (state.chem[k] !== undefined || e.chem > 0) state.chem[k] = clamp((state.chem[k] ?? 0) + e.chem, 0, 100)
      }
  }
  const p = playerId !== undefined ? state.players[playerId] : undefined
  if (p) {
    if (e.playerMorale) p.morale = clamp(p.morale + e.playerMorale, 0, 100)
    if (e.playerCondition) p.condition = clamp(p.condition + e.playerCondition, 5, 100)
    if (e.playerFatigue) p.fatigue = clamp(p.fatigue + e.playerFatigue, 0, 100)
  }
}

/**
 * 毎週のやる気: 試合に出ていない実力者は下がり、下がりきると移籍を志願する。
 * 出ている選手は上がる（試合の結果の反映は results.ts）。
 */
export function moraleWeek(state: GameState, rng: Rng) {
  const me = state.clubs[state.playerClubId]
  const sq = squadOf(state, me.id)
  const starters = new Set(me.lineup.starters)
  const bench = new Set(me.lineup.bench)
  const level = sq.map(ovr).sort((a, b) => b - a)[10] ?? 50
  const port = hasTrait(state, 'port', me)
  for (const p of sq) {
    if (p.injury) continue
    // 港町（M19）: 外国籍の選手がなじみやすい
    if (port && p.nation !== 'JP') p.morale = clamp(p.morale + 0.4, 0, 100)
    const good = ovr(p) >= level - 2
    if (starters.has(p.id)) p.morale = clamp(p.morale + 0.8, 0, 100)
    else if (bench.has(p.id)) p.morale = clamp(p.morale - (good ? 0.8 : 0.2) * (p.traits.ambition / 10), 0, 100)
    else p.morale = clamp(p.morale - (good ? 1.6 : 0.6) * (p.traits.ambition / 10), 0, 100)
    if (p.morale < 22 && good && !state.offers.some((o) => o.kind === 'request' && o.playerId === p.id) && rng.chance(0.3)) {
      state.offers.push({ kind: 'request', playerId: p.id, expiresAbsWeek: absWeekOf(state.season, state.week) + 4, id: allocId(state, 'offer') })
      state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'club', mine: true, text: `${p.name} が出場機会を求めて移籍を志願しています。` })
    }
  }
  abroadWeek(state, rng)
}

/**
 * 海外挑戦の志願: 移籍期間に、クラブの格より明らかに上で野心のある選手が、
 * 海外クラブのオファーを持って移籍を願い出る（断るとやる気が大きく下がる）
 */
function abroadWeek(state: GameState, rng: Rng) {
  if (!isTransferWindow(state.week)) return
  const me = state.clubs[state.playerClubId]
  const now = absWeekOf(state.season, state.week)
  const level = starterOvrForRep(me.rep, me.country)
  if (state.offers.some((o) => o.kind === 'request' && o.abroad)) return
  for (const p of squadOf(state, me.id)) {
    const o = ovr(p)
    if (p.injury || p.loan || o < level + 8 || p.traits.ambition < 14 || ageOf(p, now) > 29) continue
    if (state.offers.some((x) => 'playerId' in x && x.playerId === p.id) || !rng.chance(0.05 * windowPace(state.week))) continue
    const fee = Math.round((marketValue(p, now, state.season) * rng.range(1.0, 1.25)) / 100) * 100
    const buyers = state.clubs.filter((c) => !c.isPlayer && !jpScale(c.country) && c.leagueId !== 'AMA' && c.budget > fee * 1.2 && Math.abs(starterOvrForRep(c.rep, c.country) - o) <= 5)
    if (!buyers.length) continue
    const buyer = rng.pick(buyers)
    state.offers.push({ kind: 'request', playerId: p.id, expiresAbsWeek: now + 3, id: allocId(state, 'offer'), abroad: { clubId: buyer.id, fee } })
    state.news.push({ absWeek: now, category: 'transfer', mine: true, text: `${p.name} に${buyer.name}からオファー。本人は海外挑戦を望んでいます。` })
    return
  }
}

/** 移籍志願への返事: 起用を約束（やる気が戻る）か、売りに出すか */
export function answerRequest(state: GameState, offerId: number, answer: 'promise' | 'sell'): string | null {
  const o = state.offers.find((x) => x.id === offerId)
  if (!o || o.kind !== 'request') return null
  const p = state.players[o.playerId]
  state.offers = state.offers.filter((x) => x.id !== offerId)
  if (!p) return null
  if (o.abroad) {
    const buyer = state.clubs[o.abroad.clubId]
    if (answer === 'promise' || p.clubId !== state.playerClubId || buyer.budget < o.abroad.fee) {
      p.morale = clamp(p.morale - 25, 0, 100)
      return `${p.name}「…わかりました。でも、夢はあきらめません」`
    }
    const now = absWeekOf(state.season, state.week)
    completeTransfer(state, p, buyer.id, o.abroad.fee, { wage: Math.max(p.contract.wage, fairWage(ovr(p), ageOf(p, now), buyer.country)), until: state.season + 3 })
    return `${p.name} の${buyer.name}への移籍が決まりました（移籍金 ${o.abroad.fee.toLocaleString()} 万円）。`
  }
  if (answer === 'promise') {
    p.morale = clamp(p.morale + 30, 0, 100)
    p.contract.role = 'regular'
    return `${p.name}「ありがとうございます！ 期待に応えます」`
  }
  state.forSale[p.id] = Math.round(marketValue(p, absWeekOf(state.season, state.week), state.season) / 100) * 100
  return `${p.name} を売りに出しました。`
}
