/**
 * スカウトの知識と「霧」。
 * 他クラブの選手の能力は、知っている度合い k（0-100）に応じた誤差つきでしか見えない。
 *   誤差の幅 = (1 - k/100) × 14、向きは選手と能力ごとに固定（見るたびに変わらない）
 * 知識が増える: 自クラブの選手（100）・対戦相手（+6）・同じリーグ（毎週少し）・スカウトの派遣
 */
import { ASIA_COUNTRIES } from '../data/clubs'
import type { Rng } from '../core/prng'
import { hashSeed } from '../core/prng'
import { absWeekOf } from '../core/calendar'
import { ATTR_KEYS, type AttrKey, type Attrs } from '../data/attributes'
import type { GameState, ScoutRegion } from '../models/game'
import type { Player } from '../models/player'
import { potentialOvr, rawRating } from '../player/overall'

export const REGION_LABEL: Record<ScoutRegion, string> = { JP: '日本', AS: 'アジア', EU: 'ヨーロッパ', SA: '南米' }
export const REGION_LEAGUES: Record<ScoutRegion, string[]> = { JP: ['NPL1', 'NPL2', 'NPL3', 'AMA'], AS: ['ASIA'], EU: ['ENG1', 'ESP1', 'ITA1', 'GER1', 'FRA1'], SA: ['BRA1'] }

export function knowledgeOf(state: GameState, p: Player): number {
  if (p.clubId === state.playerClubId || p.loan?.fromClubId === state.playerClubId) return 100
  const k = state.scout.knowledge[p.id] ?? 0
  // 固有キャラ（有名選手）は最初からある程度知られている
  return Math.max(k, p.starId ? 45 : 0)
}

/** -1〜1 の固定の誤差 */
function bias(state: GameState, p: Player, i: number): number {
  return ((hashSeed(state.seed, p.id, i, 0x5c0) % 2001) - 1000) / 1000
}

export interface Estimate {
  k: number
  attr: Attrs
  ovrLo: number
  ovrHi: number
  /** 将来性（★、0.5 刻み）の範囲 */
  potLo: number
  potHi: number
}

export function estimate(state: GameState, p: Player): Estimate {
  const k = knowledgeOf(state, p)
  const width = (1 - k / 100) * 14
  const attr = {} as Attrs
  ATTR_KEYS.forEach((key: AttrKey, i) => {
    attr[key] = Math.max(1, Math.min(99, Math.round(p.attr[key] + bias(state, p, i) * width)))
  })
  const center = rawRating(p.attr, p.pos) * (0.75 + 0.25 * (p.apt[p.pos] ?? 0) / 100)
  const shift = bias(state, p, 99) * width * 0.5
  const ovrLo = Math.round(center + shift - width * 0.5)
  const ovrHi = Math.round(center + shift + width * 0.5)
  const stars = Math.max(0.5, Math.min(5, (potentialOvr(p) - 45) / 9))
  const pw = (1 - k / 100) * 2
  const ps = bias(state, p, 98) * pw * 0.5
  const round = (v: number) => Math.max(0.5, Math.min(5, Math.round(v * 2) / 2))
  return { k, attr, ovrLo, ovrHi, potLo: round(stars + ps - pw / 2), potHi: round(stars + ps + pw / 2) }
}

export function learn(state: GameState, playerId: number, amount: number) {
  const cur = state.scout.knowledge[playerId] ?? 0
  if (cur >= 100) return
  state.scout.knowledge[playerId] = Math.min(100, cur + amount)
}

/** 対戦した相手の選手を少し知る */
export function learnFromMatch(state: GameState, playerIds: number[]) {
  for (const id of playerIds) learn(state, id, 6)
}

export function regionOf(state: GameState, p: Player): ScoutRegion | null {
  if (p.clubId < 0) return p.nation === 'BR' || p.nation === 'AR' || p.nation === 'UY' || p.nation === 'CO' ? 'SA' : p.nation === 'JP' ? 'JP' : (ASIA_COUNTRIES as readonly string[]).includes(p.nation) ? 'AS' : 'EU'
  const club = state.clubs[p.clubId]
  const lg = club.leagueId
  for (const r of Object.keys(REGION_LEAGUES) as ScoutRegion[]) if (REGION_LEAGUES[r].includes(lg)) return r
  // ワールドリーグ（M24）: クラブの国で
  if (lg === 'WL') return club.country === 'JP' ? 'JP' : club.country === 'BR' ? 'SA' : (ASIA_COUNTRIES as readonly string[]).includes(club.country) ? 'AS' : 'EU'
  return null
}

/** スカウトを地域へ派遣（4 週間） */
export function dispatchScout(state: GameState, staffId: number, region: ScoutRegion, weeks = 4): boolean {
  const s = state.staff[staffId]
  if (!s || s.role !== 'scout' || s.clubId !== state.playerClubId) return false
  if (state.scout.missions.some((m) => m.staffId === staffId)) return false
  state.scout.missions.push({ staffId, region, untilAbsWeek: absWeekOf(state.season, state.week) + weeks })
  return true
}

/** 1 週の視察の結果: 調べた選手と、最終週なら戻ったこと（それまでの報告の数） */
export interface ScoutFind {
  staffId: number
  players: Player[]
  done?: { region: ScoutRegion; found: number }
}

/** 毎週: 派遣中のスカウトが選手を調べる。調べた選手を返す（報告に載せるかは scout/reports.ts） */
export function scoutWeek(state: GameState, rng: Rng): ScoutFind[] {
  const now = absWeekOf(state.season, state.week)
  const me = state.clubs[state.playerClubId]
  const office = me.facilities.scoutOffice
  const out: ScoutFind[] = []
  for (const m of state.scout.missions) {
    const s = state.staff[m.staffId]
    if (!s) continue
    const judging = s.sub.judging ?? s.ability
    const network = s.sub.network ?? s.ability
    const n = 3 + Math.floor(network / 25) + office
    const pool = Object.values(state.players).filter((p) => !p.retired && p.clubId !== me.id && regionOf(state, p) === m.region)
    // 若くて伸びそうな選手と、知らない選手を優先
    pool.sort((a, b) => scoutPriority(state, b) - scoutPriority(state, a) + (rng.next() - 0.5) * 20)
    const found = pool.slice(0, n)
    for (const p of found) learn(state, p.id, 20 + judging / 4 + office * 3)
    out.push({ staffId: s.id, players: found, done: m.untilAbsWeek <= now ? { region: m.region, found: m.found ?? 0 } : undefined })
  }
  state.scout.missions = state.scout.missions.filter((m) => m.untilAbsWeek > now)
  return out
}

function scoutPriority(state: GameState, p: Player): number {
  const k = state.scout.knowledge[p.id] ?? 0
  const age = (absWeekOf(state.season, state.week) - p.birthAbsWeek) / 48
  // 日本のクラブは外国人枠（先発＋ベンチ 5 人）があるので、日本人を先に調べる
  const local = state.clubs[state.playerClubId].country === 'JP' && p.nation === 'JP' ? 12 : 0
  return (100 - k) * 0.3 + (potentialOvr(p) - 50) + Math.max(0, 24 - age) * 2 + local
}
