/**
 * GameState から試合の設定（MatchSetup）を作る。
 * 実効能力 = 能力 × 調子 × やる気 × ホーム/アウェイ × ポジション適性。
 */
import { ATTR_KEYS, type AttrKey, type Attrs } from '../data/attributes'
import { formationOf } from '../data/formations'
import type { Position } from '../data/positions'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import { hashSeed } from '../core/prng'
import { autoLineup, isAvailable, foreignCount, foreignLimit } from './lineup'
import type { MatchPlayerSetup, MatchSetup, TeamSetup } from './live/types'
import { formationFamiliarity, managerAbility } from '../staff/effects'
import { CHEM_AI, chemKey, teamCohesion, CHEM_FLOOR } from '../club/chemistry'

/** 適性が低いとき大きく下がる「位置取り」系の能力 */
const POSITIONAL: AttrKey[] = ['decision', 'defPos', 'offBall', 'marking', 'vision']

export function effectiveAttrs(p: Player, pos: Position, venue: 'home' | 'away' | 'neutral'): Attrs {
  const cond = 0.94 + (p.condition / 100) * 0.12
  const morale = 0.985 + (p.morale / 100) * 0.03
  const venueMul = venue === 'home' ? 1.02 : venue === 'away' ? 0.99 : 1
  const apt = (p.apt[pos] ?? 0) / 100
  const out = {} as Attrs
  for (const k of ATTR_KEYS) {
    const aptMul = POSITIONAL.includes(k) ? 0.78 + 0.22 * apt : 0.95 + 0.05 * apt
    out[k] = Math.min(99, p.attr[k] * cond * morale * venueMul * aptMul)
  }
  return out
}

export function matchPlayer(p: Player, pos: Position, venue: 'home' | 'away' | 'neutral'): MatchPlayerSetup {
  return {
    id: p.id,
    name: p.name,
    short: p.short,
    number: p.number,
    pos,
    attr: effectiveAttrs(p, pos, venue),
    skills: p.skills,
    stamina: Math.round(100 - p.fatigue * 0.35),
    aggression: p.traits.aggression,
    workRate: p.traits.workRate,
    starId: p.starId,
  }
}

export function buildTeamSetup(state: GameState, clubId: number, venue: 'home' | 'away' | 'neutral', ai: boolean): TeamSetup {
  const club = state.clubs[clubId]
  let lineup = club.lineup
  const f = formationOf(club.tactics.formation)
  const valid =
    lineup.starters.length === f.slots.length &&
    lineup.starters.every((id) => state.players[id] && state.players[id].clubId === clubId && isAvailable(state.players[id])) &&
    foreignCount(state, club, lineup) <= foreignLimit(club)
  if (!valid) {
    lineup = autoLineup(state, club)
    club.lineup = lineup
  }
  // 監督: 慣れたフォーメーションほど位置取りが良く、能力が高いほど全体が少し上がる。分析室も少し効く
  const fam = formationFamiliarity(state, club, f.id)
  const coach = 0.985 + managerAbility(state, club) / 3000 + club.facilities.analysis * 0.003
  const starters = lineup.starters.flatMap((id, i) => {
    if (!state.players[id]) return []
    const mp = matchPlayer(state.players[id], f.slots[i].pos, venue)
    for (const k of POSITIONAL) mp.attr[k] = Math.min(99, mp.attr[k] * (0.95 + 0.05 * (fam / 100)))
    for (const k of ATTR_KEYS) mp.attr[k] = Math.min(99, mp.attr[k] * coach)
    return [mp]
  })
  const bench = lineup.bench
    .map((id) => state.players[id])
    .filter((p) => p && isAvailable(p))
    .map((p) => matchPlayer(p, p.pos, venue))
  const mgr = club.staff.map((id) => state.staff[id]).find((s) => s?.role === 'manager')
  // 連携: 自クラブは記録から、AI は一定の値
  let chem: Record<string, number> | undefined
  if (club.isPlayer) {
    chem = {}
    const ids = [...lineup.starters, ...lineup.bench].filter((id) => state.players[id])
    for (let i = 0; i < ids.length; i++)
      for (let j = i + 1; j < ids.length; j++) {
        const v = state.chem[chemKey(ids[i], ids[j])]
        if (v && v > CHEM_FLOOR) chem[chemKey(ids[i], ids[j])] = v
      }
  }
  return {
    chem,
    chemBase: club.isPlayer ? CHEM_FLOOR : CHEM_AI,
    cohesion: club.isPlayer ? teamCohesion(state, lineup.starters, f.id) : CHEM_AI,
    clubId,
    name: club.name,
    short: club.short,
    colors: { ...club.colors },
    gkColor: '#111827',
    formation: f.id,
    tactics: { ...club.tactics },
    style: mgr?.style,
    starters,
    bench,
    penaltyTaker: lineup.penaltyTaker,
    freeKickTaker: lineup.freeKickTaker,
    cornerTaker: lineup.cornerTaker,
    captain: lineup.captain,
    ai,
  }
}

function rgb(hex: string): [number, number, number] {
  const n = parseInt(hex.replace('#', ''), 16)
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255]
}

/** 色の近さ（0 = 同じ） */
export function colorDistance(a: string, b: string): number {
  const [r1, g1, b1] = rgb(a)
  const [r2, g2, b2] = rgb(b)
  return Math.hypot((r1 - r2) * 0.9, (g1 - g2) * 1.2, (b1 - b2) * 0.8)
}

/** アウェイのユニフォームがホームと見分けにくければ替える（GK も） */
export function resolveKitClash(home: TeamSetup, away: TeamSetup) {
  const CLOSE = 130
  if (colorDistance(home.colors.primary, away.colors.primary) < CLOSE) {
    const swapped = { primary: away.colors.secondary, secondary: away.colors.primary }
    if (colorDistance(home.colors.primary, swapped.primary) >= CLOSE) away.colors = swapped
    else {
      const white = colorDistance(home.colors.primary, '#f8fafc') > colorDistance(home.colors.primary, '#111827')
      away.colors = white ? { primary: '#f8fafc', secondary: away.colors.primary } : { primary: '#111827', secondary: away.colors.primary }
    }
  }
  const gkOptions = ['#111827', '#f97316', '#84cc16', '#a855f7', '#ec4899', '#22d3ee']
  const pick = (avoid: string[]) => gkOptions.find((c) => avoid.every((x) => colorDistance(c, x) > 110)) ?? '#f97316'
  home.gkColor = pick([home.colors.primary, away.colors.primary])
  away.gkColor = pick([home.colors.primary, away.colors.primary, home.gkColor])
}

export function buildMatchSetup(state: GameState, fixtureId: number, homeId: number, awayId: number, opts: { knockout?: boolean; neutral?: boolean } = {}): MatchSetup {
  const venueH = opts.neutral ? 'neutral' : 'home'
  const venueA = opts.neutral ? 'neutral' : 'away'
  // 自クラブにも AI 監督（コーチ）が付く。観戦中にプレイヤーが指示を出したら、そのチームは手動になる
  const home = buildTeamSetup(state, homeId, venueH, true)
  const away = buildTeamSetup(state, awayId, venueA, true)
  resolveKitClash(home, away)
  return {
    seed: hashSeed(state.seed, fixtureId, 0xba11),
    home,
    away,
    neutral: opts.neutral,
    knockout: opts.knockout,
  }
}
