/**
 * 速い試合計算（AI 同士の試合）。LiveSim と同じ強さの物差しから得点の期待値を出し、ポアソン分布で得点を引く。
 * 係数は tools/calibrate.ts が LiveSim の結果に回帰して calib.generated.ts に書き出す。
 * 得点者・アシスト・カード・ケガも、LiveSim と同じくらいの頻度になるように割り振る。
 */
import type { Rng } from '../core/prng'
import { POSITION_DEFS } from '../data/positions'
import { CALIB } from './calib.generated'
import { features, teamRatings } from './ratings'
import type { MatchEvent, MatchPlayerSetup, MatchSetup, MatchSummary, PlayerMatchStats, TeamSetup, TeamStats } from './live/types'
import { CLOCK_SCALE } from './live/types'

function poisson(rng: Rng, lambda: number): number {
  const L = Math.exp(-lambda)
  let k = 0
  let p = 1
  do {
    k++
    p *= rng.next()
  } while (p > L && k < 15)
  return k - 1
}

/** ガンマ分布（Marsaglia-Tsang, shape >= 1） */
function gamma(rng: Rng, shape: number): number {
  const d = shape - 1 / 3
  const c = 1 / Math.sqrt(9 * d)
  for (;;) {
    let x: number
    let v: number
    do {
      x = rng.normal(0, 1)
      v = 1 + c * x
    } while (v <= 0)
    v = v * v * v
    const u = rng.next()
    if (u < 1 - 0.0331 * x ** 4 || Math.log(u) < 0.5 * x * x + d * (1 - v + Math.log(v))) return d * v
  }
}

/** 得点のばらつき（大差の試合も出るように、ポアソンより広げる）。小さいほど広い */
const DISPERSION = 6

export function expectedGoals(setup: MatchSetup, leagueId?: string): [number, number] {
  const h = teamRatings(setup.home)
  const a = teamRatings(setup.away)
  const c = CALIB
  const dot = (x: number[]) => x.reduce((s, v, k) => s + v * (c.b[k + 1] ?? 0), c.b[0])
  const home = setup.neutral ? 0 : c.home
  const adj = (leagueId && c.league[leagueId]) || [0, 0]
  const lh = Math.exp(dot(features(h, a)) + home + adj[0])
  const la = Math.exp(dot(features(a, h)) + adj[1])
  return [Math.min(8, lh), Math.min(8, la)]
}

/** 得点者の重み（FW ほど、決定力が高いほど） */
function scorerWeight(p: MatchPlayerSetup): number {
  const line = POSITION_DEFS[p.pos].line
  const base = line === 'FW' ? 5 : p.pos === 'AM' ? 3 : line === 'MF' ? 1.4 : line === 'DF' ? 0.45 : 0.01
  return base * (0.4 + (p.attr.finish + p.attr.shoot) / 160) * (p.skills.includes('goalHunter') ? 1.4 : 1)
}

function assistWeight(p: MatchPlayerSetup): number {
  const line = POSITION_DEFS[p.pos].line
  const base = p.pos === 'AM' || p.pos === 'WG' ? 3 : line === 'MF' ? 2.2 : line === 'FW' ? 1.8 : line === 'DF' ? 0.9 : 0.05
  return base * (0.4 + (p.attr.pass + p.attr.vision + p.attr.cross) / 240)
}

function pickWeighted<T>(rng: Rng, items: T[], w: (t: T) => number): T {
  const ws = items.map(w)
  return items[rng.weighted(ws)]
}

function emptyStats(): TeamStats {
  return { goals: 0, shots: 0, onTarget: 0, xg: 0, passes: 0, passesOk: 0, possession: 0, fouls: 0, corners: 0, offsides: 0, yellows: 0, reds: 0, saves: 0 }
}

export function fastSim(setup: MatchSetup, rng: Rng, leagueId?: string): MatchSummary {
  const [lh, la] = expectedGoals(setup, leagueId)
  let gh = poisson(rng, (lh * gamma(rng, DISPERSION)) / DISPERSION)
  let ga = poisson(rng, (la * gamma(rng, DISPERSION)) / DISPERSION)
  const teams: [TeamSetup, TeamSetup] = [setup.home, setup.away]
  const events: MatchEvent[] = []
  const players: PlayerMatchStats[] = []
  const stats: [TeamStats, TeamStats] = [emptyStats(), emptyStats()]
  const goals: MatchSummary['goals'] = []
  const ratingAdd = new Map<number, number>()
  const addRate = (id: number, v: number) => ratingAdd.set(id, (ratingAdd.get(id) ?? 0) + v)

  for (const side of [0, 1] as const) {
    const t = teams[side]
    const n = side === 0 ? gh : ga
    const xg = side === 0 ? lh : la
    stats[side].goals = n
    stats[side].xg = xg
    // 見た目の数字は LiveSim（M14 のテンポ）にそろえる: 1 チームあたりシュート 12・パス 180・ファウル 6・コーナー 3
    stats[side].shots = Math.max(n, Math.round(xg * 6 + rng.range(2, 7)))
    stats[side].onTarget = Math.max(n, Math.round(stats[side].shots * rng.range(0.35, 0.5)))
    stats[side].passes = Math.round(150 + rng.range(0, 70))
    stats[side].passesOk = Math.round(stats[side].passes * rng.range(0.68, 0.84))
    stats[side].fouls = poisson(rng, 6)
    stats[side].corners = poisson(rng, 3.1)
    stats[side].offsides = poisson(rng, 1.6)
    const field = t.starters.filter((p) => p.pos !== 'GK')
    for (let g = 0; g < n; g++) {
      const minute = rng.int(1, 90)
      const scorer = pickWeighted(rng, field, scorerWeight)
      const others = field.filter((p) => p !== scorer)
      const assist = rng.chance(0.72) && others.length ? pickWeighted(rng, others, assistWeight) : undefined
      goals.push({ team: side, player: scorer.id, assist: assist?.id, minute })
      addRate(scorer.id, 1)
      if (assist) addRate(assist.id, 0.6)
      events.push({ t: (minute * 60) / CLOCK_SCALE, minute, type: 'goal', team: side, player: scorer.id, other: assist?.id, text: `${scorer.short} のゴール` })
    }
    // カード（LiveSim と同じくらい: 1 チーム 1.5 枚）
    const yellows = poisson(rng, 1.5)
    for (let k = 0; k < yellows; k++) {
      const p = pickWeighted(rng, field, (q) => 0.5 + q.aggression / 10)
      stats[side].yellows++
      events.push({ t: 0, minute: rng.int(10, 90), type: 'yellow', team: side, player: p.id, text: `${p.short} にイエローカード` })
      addRate(p.id, -0.3)
    }
    if (rng.chance(0.085)) {
      const p = pickWeighted(rng, field, (q) => 0.5 + q.aggression / 10)
      stats[side].reds++
      events.push({ t: 0, minute: rng.int(20, 90), type: 'red', team: side, player: p.id, text: `${p.short} が退場` })
      addRate(p.id, -1.5)
    }
    if (rng.chance(0.06)) {
      const p = rng.pick(field)
      events.push({ t: 0, minute: rng.int(5, 85), type: 'injury', team: side, player: p.id, text: `${p.short} が負傷` })
    }
  }
  // 支配率は中盤の差から
  const hr = teamRatings(setup.home)
  const ar = teamRatings(setup.away)
  const share = Math.max(0.3, Math.min(0.7, 0.5 + (hr.mid - ar.mid) * 0.008 + (setup.neutral ? 0 : 0.02)))
  stats[0].possession = 540 * share
  stats[1].possession = 540 * (1 - share)

  for (const side of [0, 1] as const) {
    const t = teams[side]
    const conceded = side === 0 ? ga : gh
    const won = side === 0 ? gh > ga : ga > gh
    for (const p of t.starters) {
      const isGk = p.pos === 'GK'
      const base = 6 + (won ? 0.3 : 0) + (isGk || POSITION_DEFS[p.pos].line === 'DF' ? -0.25 * conceded + (conceded === 0 ? 0.5 : 0) : 0)
      const st: PlayerMatchStats = {
        id: p.id,
        team: side,
        minutes: 90,
        started: true,
        goals: goals.filter((g) => g.player === p.id).length,
        assists: goals.filter((g) => g.assist === p.id).length,
        shots: 0,
        passes: 0,
        passesOk: 0,
        tackles: 0,
        saves: 0,
        yellow: events.filter((e) => e.type === 'yellow' && e.player === p.id).length,
        red: events.some((e) => e.type === 'red' && e.player === p.id),
        injured: events.some((e) => e.type === 'injury' && e.player === p.id),
        rating: Math.max(3, Math.min(10, Math.round((base + (ratingAdd.get(p.id) ?? 0) + rng.normal(0, 0.45)) * 10) / 10)),
        stamina: Math.round(Math.max(20, p.stamina - rng.range(28, 45))),
      }
      players.push(st)
    }
  }
  events.sort((a, b) => a.minute - b.minute)
  // 延長・PK（ノックアウトで同点）
  let pens: [number, number] | undefined
  let et = false
  if (setup.knockout && gh === ga) {
    et = true
    const eh = poisson(rng, lh / 3)
    const ea = poisson(rng, la / 3)
    gh += eh
    ga += ea
    stats[0].goals = gh
    stats[1].goals = ga
    if (gh === ga) {
      const ph = 3 + poisson(rng, 0.9)
      let pa = 3 + poisson(rng, 0.9)
      if (pa === ph) pa += rng.chance(0.5) ? 1 : -1
      pens = [ph, Math.max(0, pa)]
    }
  }
  const mom = [...players].sort((a, b) => b.rating - a.rating)[0]?.id
  return { score: [gh, ga], et, pens, stats, players, events, goals, mom }
}
