export function familyEvent(id: string): CareerEventDef | undefined {
  const [, key, kids] = id.split(':')
  const f = FAMILY[key]
  if (!f) return undefined
  const k = kids === '1'
  const lines: TalkLineDef[] = [
    { s: 'nar', t: f.nar },
    { s: 'partner', t: k ? f.kid : f.couple },
    { s: 'me', t: k ? f.meKid : f.meCouple },
  ]
  return { id, char: 'partner', title: f.title, trigger: 'system', lines, effect: { bond: 3, condition: 10, exp: { mental: 6 } } }
}
