/**
 * 世代をつなぐ物語（M17）: 引退した主人公の息子（サッカーをしている子）が、次の主人公になる。
 *   見守り期（watch）: 息子が 15 歳になるまで。親として月ごとに練習の方針を選ぶ（世界は 4 週ずつ進む）
 *   ユース期（youth）: 15〜17 歳。息子が主人公（高校のサッカー部かクラブのユース）。練習・試合・大会・選抜
 *   プロ（pro）: 18 歳の入団から。今のキャリアと同じ
 * 一族の記録は career.lineage。新しい世代の登場人物は data/career.ts の GEN2_CAST（名前は世代ごとに saga.names）。
 * 孫の世代も同じ仕組みで続く。乱数は種と週から作る専用の流れ（ほかの処理の並びを変えない）。
 */
import { absWeekOf, WEEKS_PER_SEASON } from '../core/calendar'
import { createRng, hashSeed, type Rng } from '../core/prng'
import { advanceWeek } from '../core/advanceWeek'
import { BOY_NAMES, GIRL_NAMES, PLAY_STYLE_BY_ID } from '../data/career'
import { ATTR_KEYS, type AttrKey } from '../data/attributes'
import type { GameState } from '../models/game'
import type { Child, ExpKind, LineageEntry, PlayStyle, SagaState } from '../models/career'
import { EXP_KINDS } from '../models/career'
import { buildAttrs, generatePlayer } from '../gen/playerGen'
import { generateName } from '../data/nations'
import { FORMATIONS, formationOf } from '../data/formations'
import type { Position } from '../data/positions'
import { matchPlayer, resolveKitClash } from '../match/setup'
import type { MatchPlayerSetup, MatchSetup, MatchSummary, TeamSetup } from '../match/live/types'
import { ovr } from '../player/overall'
import { careerAge, castName, clamp, genNames, report } from './core'
import { queueTalk } from './events'
import { childAge, childrenWeek } from './children'
import { careerSummary } from './retire'
import { gainExp } from './growth'
import { makeRookieOffers } from './create'

const sagaRng = (state: GameState, salt: number): Rng => createRng(hashSeed(state.seed, absWeekOf(state.season, state.week), 0x5a6a + salt))

const KANJI = ['', '', '二', '三', '四', '五', '六', '七', '八', '九', '十']

/** 世代の呼び名（初代・二代目・三代目…） */
export function genLabel(gen: number): string {
  return gen <= 1 ? '初代' : `${KANJI[gen] ?? gen}代目`
}

/** 子どもの性別（古いセーブは名前から推し量る。サッカーをしていれば息子として扱う） */
export function childSex(k: Child): 'boy' | 'girl' {
  if (k.sex) return k.sex
  if (GIRL_NAMES.includes(k.name) && !k.soccer) return 'girl'
  return BOY_NAMES.includes(k.name) || k.soccer ? 'boy' : 'girl'
}

/** 次の主人公になれる子（サッカーをしている息子） */
export function heirs(state: GameState): { idx: number; child: Child; age: number }[] {
  const c = state.career!
  return (c.children ?? []).map((child, idx) => ({ idx, child, age: childAge(state, child) })).filter((x) => x.child.soccer && childSex(x.child) === 'boy')
}

/** 引退した主人公の記録 */
function lineageEntry(state: GameState): LineageEntry {
  const c = state.career!
  const p = state.players[c.playerId]
  const sum = c.summary ?? careerSummary(state)
  const clubs: string[] = []
  for (const l of c.log) {
    const n = state.clubs[l.clubId]?.name
    if (n && clubs[clubs.length - 1] !== n) clubs.push(n)
  }
  return {
    gen: c.saga?.gen ?? 1,
    playerId: p.id,
    name: p.name,
    photo: p.face?.photo,
    bornAbsWeek: p.birthAbsWeek,
    retiredAge: sum.retiredAge,
    grade: sum.grade,
    apps: sum.apps,
    goals: sum.goals,
    titles: sum.titles,
    caps: sum.caps,
    clubs,
    spouse: c.spouse,
    spouseName: c.spouse ? castName(state, c.spouse) : undefined,
    children: (c.children ?? []).map((k) => k.name),
  }
}

/** 引退のあと、次の世代へ（息子が 15 歳未満なら見守り期、15 歳からユース期、18 歳からプロ） */
export function beginNextGeneration(state: GameState, heirIdx: number, style: PlayStyle) {
  const c = state.career!
  if (!c.retired) return
  const heir = (c.children ?? [])[heirIdx]
  if (!heir) return
  c.lineage = [...(c.lineage ?? []), lineageEntry(state)]
  const gen = c.saga?.gen ?? 1
  // 親の世代の名前・親（祖父母）の記録は残す（見守り期の会話でも使う）
  c.saga = { ...c.saga, gen, phase: 'watch', startSeason: state.season, heirIdx, focus: {}, youth: undefined }
  c.style = style
  if (childAge(state, heir) >= 15) becomeHeir(state)
  else {
    queueTalk(state, 'saga_watch', { child: heir.name })
    report(state, `${heir.name}の物語が始まった。15 歳になるまで、親として見守る。`)
  }
}

/** 見守り期の 1 か月: 練習の方針を選び、4 週進める。15 歳になったら息子が主人公になる */
export function watchMonth(state: GameState, focus: ExpKind | 'rest') {
  const c = state.career!
  const saga = c.saga
  if (!saga || saga.phase !== 'watch') return
  const heir = (c.children ?? [])[saga.heirIdx ?? 0]
  if (!heir) return
  const rng = sagaRng(state, 1)
  if (focus === 'rest') report(state, `${heir.name}はのびのびと過ごした。`)
  else {
    saga.focus = { ...saga.focus, [focus]: (saga.focus?.[focus] ?? 0) + 1 }
    // 方針を続けると、ときどき才能が伸びる（教えた分だけ）
    if (rng.chance(0.08 + (saga.focus[focus] ?? 0) * 0.01)) heir.talent = clamp((heir.talent ?? 0) + 1, 0, 5)
    report(state, `${heir.name}の練習: ${focus === 'power' ? '体づくり' : focus === 'speed' ? '走り込み' : focus === 'tech' ? 'ボール扱い' : focus === 'tactics' ? '試合を見て学ぶ' : '心を鍛える'}。`)
  }
  for (let i = 0; i < 4; i++) {
    advanceWeek(state)
    // 親は引退しているので、子どもの節目と家族の行事はここで（careerWeek は動かない）
    childrenWeek(state)
  }
  if (childAge(state, heir) >= 15 && !c.talks.length) becomeHeir(state)
}

/** 次の主人公の写真: 主人公の顔のうち、父とは違うもの（種と世代で決める。年齢で @12・@15 の姿になる） */
export function heirFace(state: GameState, gen: number, fatherPhoto?: string): string {
  const faces = Array.from({ length: 12 }, (_, i) => `p${String(i + 1).padStart(2, '0')}`).filter((id) => id !== fatherPhoto)
  return faces[hashSeed(state.seed, gen, 0xface) % faces.length]
}

/** 見守り期で、息子が 15 歳になった（会話を読み終えたら主人公になれる） */
export function heirReady(state: GameState): boolean {
  const c = state.career!
  if (c.saga?.phase !== 'watch') return false
  const heir = (c.children ?? [])[c.saga.heirIdx ?? 0]
  return !!heir && childAge(state, heir) >= 15
}


/** 息子が主人公になる（ユース期。18 歳を過ぎていればプロの入団から） */
export function becomeHeir(state: GameState) {
  const old = state.career!
  const saga = old.saga!
  const heir = (old.children ?? [])[saga.heirIdx ?? 0]
  const father = state.players[old.playerId]
  const rng = sagaRng(state, 2)
  const style = PLAY_STYLE_BY_ID[old.style]
  const talent = heir.talent ?? 1
  const age = childAge(state, heir)
  // 能力: 15 歳で総合 40 前後（才能と見守り期の方針）。プレースタイルの得意と、方針に合う能力を少し上げる。
  // 18 歳の卒業で 50〜56（ふつうのルーキーより少し上）になるように
  const target = 27 + talent * 2 + Math.min(8, (age - 15) * 4)
  const p = generatePlayer(state, rng, { clubId: -1, pos: style.pos, targetOvr: target, age, nation: 'JP', country: 'JP', contractYears: -1, potentialOvr: 70 + talent * 3 })
  const FOCUS_ATTRS: Record<ExpKind, AttrKey[]> = { power: ['strength', 'stamina', 'jump'], speed: ['speed', 'agility'], tech: ['dribble', 'trap', 'shoot', 'pass'], tactics: ['vision', 'decision', 'offBall'], mental: ['composure', 'decision'] }
  for (const k of ATTR_KEYS) p.attr[k] = Math.round(clamp(p.attr[k] + (style.bias[k] ?? 0) * 0.7, 5, 70) * 10) / 10
  for (const kind of EXP_KINDS) for (const k of FOCUS_ATTRS[kind]) if (p.attr[k] !== undefined) p.attr[k] = Math.round(clamp(p.attr[k] + Math.min(6, (saga.focus?.[kind] ?? 0) * 0.25), 5, 72) * 10) / 10
  for (const k of ATTR_KEYS) p.cap[k] = Math.min(99, Math.max(p.cap[k], p.attr[k] + 25))
  const family = father.name.split(/\s+/)[0]
  p.name = `${family} ${heir.name}`
  p.short = family
  p.birthAbsWeek = heir.bornAbsWeek
  p.isYouth = age < 18
  p.growth = father.growth
  p.personality = 'effort'
  p.skills = []
  p.condition = 60
  p.morale = 75
  p.face = { photo: heirFace(state, saga.gen + 1, father.face?.photo) }
  state.players[p.id] = p
  const gen = saga.gen + 1
  const path = heir.path ?? 'clubYouth'
  const nextSaga: SagaState = {
    gen,
    phase: age >= 18 ? 'pro' : 'youth',
    startSeason: state.season,
    names: genNames(state.seed, gen),
    father: { name: father.name, playerId: father.id, photo: father.face?.photo },
    mother: old.spouse,
    motherName: old.spouse ? castName(state, old.spouse) : undefined,
    youth: { team: youthTeamName(state, path), path, year: 1, apps: 0, goals: 0, titles: [], strength: path === 'clubYouth' ? 60 + rng.int(0, 8) : 52 + rng.int(0, 10) },
  }
  state.career = {
    playerId: p.id,
    saga: nextSaga,
    lineage: old.lineage,
    style: old.style,
    exp: { power: 20, speed: 20, tech: 20, tactics: 20, mental: 20 },
    stamina: 100,
    trust: 50,
    fame: Math.round(old.fame * 0.25),
    money: 100,
    objectives: [],
    kotsu: { [style.kotsu]: 1 },
    bonds: {},
    done: {},
    talks: [],
    offers: [],
    log: [],
    report: [`${p.name}の物語が始まった。`],
    growthMode: old.growthMode ?? 'easy',
    nextObjectiveId: 1,
    nextOfferId: old.nextOfferId,
  }
  if (nextSaga.phase === 'pro') {
    makeRookieOffers(state, rng)
    queueTalk(state, 'saga_pro', { team: nextSaga.youth!.team })
  } else queueTalk(state, 'saga_youth', { team: nextSaga.youth!.team })
}

/** ユースのチームの名前（高校かクラブのユース。架空） */
function youthTeamName(state: GameState, path: 'school' | 'clubYouth'): string {
  if (path === 'clubYouth') {
    const home = state.career?.homeClubId ?? state.career?.log[0]?.clubId
    const club = home !== undefined ? state.clubs[home] : undefined
    return club ? `${club.short} U-18` : '地元クラブ U-18'
  }
  const towns = ['湘南', '青葉', '桜台', '星ヶ丘', '旭', '若葉']
  return `${towns[state.seed % towns.length]}学園高校`
}

// ---------------------------------------------------------------- ユース期（毎週）

/** ユースの試合の週（リーグは偶数週、夏の大会 42〜46 週、冬の大会 16〜21 週） */
function youthFixture(week: number): 'league' | 'summer' | 'winter' | null {
  if (week >= 42 && week <= 46) return 'summer'
  if (week >= 16 && week <= 21) return 'winter'
  if (week >= 4 && week <= 40 && week % 2 === 0) return 'league'
  return null
}

export function tourneyName(path: 'school' | 'clubYouth', kind: 'summer' | 'winter'): string {
  if (path === 'school') return kind === 'summer' ? 'インターハイ' : '高校サッカー選手権'
  return kind === 'summer' ? 'クラブユース選手権' : 'ユースカップ'
}

/** 今週のユースの試合（大会で負けていたら、ケガなら、観戦して済ませたなら無し） */
function youthFixtureNow(state: GameState): { kind: 'league' | 'summer' | 'winter'; round: number; key: string } | null {
  const c = state.career!
  const kind = youthFixture(state.week)
  if (!kind || state.players[c.playerId].injury) return null
  const key = `${kind}-${state.season}`
  if (kind !== 'league' && c.done[`yt_out_${key}`] !== undefined) return null
  if (c.done[`yt_played_${absWeekOf(state.season, state.week)}`] !== undefined) return null
  const round = kind === 'league' ? 0 : state.week - (kind === 'summer' ? 42 : 16)
  return { kind, round, key }
}

const lastRound = (kind: 'summer' | 'winter') => (kind === 'summer' ? 4 : 5)

function youthLabel(path: 'school' | 'clubYouth', kind: 'league' | 'summer' | 'winter', round: number): string {
  if (kind === 'league') return 'リーグ戦'
  const last = lastRound(kind)
  return `${tourneyName(path, kind)}${round === last ? ' 決勝' : round === last - 1 ? ' 準決勝' : ` ${round + 1} 回戦`}`
}

/** 相手の強さ（大会は勝ち進むほど強い） */
function youthOpp(path: 'school' | 'clubYouth', kind: 'league' | 'summer' | 'winter', round: number, rng: Rng): number {
  return (kind === 'league' ? 50 + rng.int(-8, 10) : 50 + round * 4 + rng.int(-6, 6)) + (path === 'clubYouth' ? 4 : 0)
}

/** ユースの試合の結果を反映する（抽象の結果か、観戦した結果） */
function applyYouthResult(state: GameState, fx: { kind: 'league' | 'summer' | 'winter'; round: number; key: string }, result: 'win' | 'draw' | 'lose', goals: number, rating: number, score?: string) {
  const c = state.career!
  const y = c.saga!.youth!
  const { kind, round, key } = fx
  const now = absWeekOf(state.season, state.week)
  y.apps++
  y.goals += goals
  gainExp(state, { tech: 4, tactics: 4, mental: 3, speed: 2, power: 2 }, 0.6 + rating / 25)
  c.fame = clamp(c.fame + goals * 0.15 + (kind !== 'league' && result === 'win' ? 0.3 : 0), 0, 100)
  const label = youthLabel(y.path, kind, round)
  report(state, `${label}: ${result === 'win' ? '勝ち' : result === 'draw' ? '引き分け' : '負け'}${score ? ` ${score}` : ''}・評価 ${rating}${goals ? `・${goals} 得点` : ''}`)
  c.done[`yt_played_${now}`] = now
  if (kind === 'league') return
  if (result === 'lose') {
    c.done[`yt_out_${key}`] = now
    if (round >= 2) queueTalk(state, 'saga_tourney_lose', { tourney: tourneyName(y.path, kind), round: label })
  } else if (round === lastRound(kind)) {
    y.titles = [...y.titles, `${tourneyName(y.path, kind)} 優勝`]
    c.fame = clamp(c.fame + 4, 0, 100)
    queueTalk(state, 'saga_tourney_win', { tourney: tourneyName(y.path, kind) })
  }
}

/** ユース期の 1 週（careerWeek の過ごし方のあとに呼ぶ）: チーム練習・試合・大会・選抜 */
export function youthWeek(state: GameState) {
  const c = state.career!
  const saga = c.saga!
  const y = saga.youth!
  const p = state.players[c.playerId]
  const rng = sagaRng(state, 3)
  // チーム練習（プロより少なめ）
  gainExp(state, { power: 2, speed: 2, tech: 3, tactics: 2, mental: 1 })
  c.stamina = clamp(c.stamina + 8, 0, 100)
  const mine = ovr(p)
  const fx = youthFixtureNow(state)
  if (fx) {
    const team = y.strength + (mine - 50) * 0.25
    const opp = youthOpp(y.path, fx.kind, fx.round, rng)
    const win = clamp(0.5 + (team - opp) * 0.03, 0.08, 0.92)
    const r = rng.next()
    const result = r < win ? 'win' : r < win + 0.18 && fx.kind === 'league' ? 'draw' : 'lose'
    // 主人公の出来: 評価点とゴール（ポジションと能力）
    const scoreRate = { ST: 0.55, WG: 0.35, AM: 0.35, SM: 0.25, CM: 0.15, DM: 0.08, WB: 0.08, SB: 0.06, CB: 0.05, GK: 0 }[p.pos] ?? 0.1
    let goals = 0
    for (let i = 0; i < 3; i++) if (rng.chance((scoreRate * (0.6 + mine / 120)) / 3)) goals++
    const rating = Math.round(clamp(6 + (mine - 50) / 25 + goals * 0.6 + (result === 'win' ? 0.3 : result === 'lose' ? -0.3 : 0) + rng.range(-0.5, 0.5), 4, 10) * 10) / 10
    applyYouthResult(state, fx, result, goals, rating)
  }
  // 年代別の代表（U-17）: 2 年目の冬までに総合 58 で一度だけ
  if (!y.selected && mine >= 58 && careerAge(state) <= 17 && state.week === 30) {
    y.selected = true
    c.fame = clamp(c.fame + 5, 0, 100)
    queueTalk(state, 'saga_u17')
  }
}

// ---------------------------------------------------------------- ユースの大一番（観戦）

const SCHOOLS = ['船橋北', '青葉台', '流山', '静岡南', '博多', '大津', '前橋', '長岡', '国見', '会津']
const YOUTH_CLUBS = ['横浜', '大阪', '名古屋', '広島', '鹿島', '浦和', '川崎', '神戸', '福岡', '札幌']

function youthOppName(state: GameState, round: number): string {
  const y = state.career!.saga!.youth!
  const i = hashSeed(state.seed, state.season * 64 + state.week, round) % SCHOOLS.length
  return y.path === 'school' ? `${SCHOOLS[i]}高校` : `${YOUTH_CLUBS[i]} U-18`
}

/** ホームに出す、ユースの次の試合の目安 */
export function youthNextLabel(state: GameState): string {
  const c = state.career!
  const y = c.saga!.youth!
  const w = state.week
  const out = (kind: 'summer' | 'winter') => c.done[`yt_out_${kind}-${state.season}`] !== undefined
  const t = (kind: 'summer' | 'winter') => tourneyName(y.path, kind)
  if (w >= 16 && w <= 21) return out('winter') ? `${t('winter')}は敗退。次はリーグ戦（第 22 週から）` : `${t('winter')}（16〜21 週）`
  if (w >= 42 && w <= 46) return out('summer') ? `${t('summer')}は敗退` : `${t('summer')}（42〜46 週）`
  if (w < 4 || w > 46) return 'シーズン前。リーグ戦は第 4 週から'
  if (w >= 13 && w < 16) return `もうすぐ${t('winter')}（第 16 週から）`
  if (w >= 38 && w < 42) return `もうすぐ${t('summer')}（第 42 週から）`
  return `リーグ戦（${w % 2 === 0 ? '今週' : '来週'}）`
}

/** 今週が大会の準決勝か決勝なら、その試合（観戦できる） */
export function youthBigMatch(state: GameState): { label: string; opp: string; final: boolean } | null {
  const c = state.career!
  if (c.saga?.phase !== 'youth') return null
  const fx = youthFixtureNow(state)
  if (!fx || fx.kind === 'league' || fx.round < lastRound(fx.kind) - 1) return null
  const y = c.saga.youth!
  return { label: youthLabel(y.path, fx.kind, fx.round), opp: youthOppName(state, fx.round), final: fx.round === lastRound(fx.kind) }
}

/** 大一番の試合の設定（両チームの選手はその場で作る。世界の選手には足さない） */
export function youthMatchSetup(state: GameState): MatchSetup | null {
  const big = youthBigMatch(state)
  const fx = youthFixtureNow(state)
  if (!big || !fx) return null
  const c = state.career!
  const y = c.saga!.youth!
  const p = state.players[c.playerId]
  const now = absWeekOf(state.season, state.week)
  const rng = createRng(hashSeed(state.seed, now, 0x5a6a + 6))
  // 主人公のポジションがある陣形（4-2-3-1 を先に）
  const f = [formationOf('4-2-3-1'), ...FORMATIONS].find((x) => x.slots.some((sl) => sl.pos === p.pos)) ?? formationOf('4-2-3-1')
  const heroSlot = f.slots.findIndex((sl) => sl.pos === p.pos)
  let nextId = -5000
  const fake = (pos: Position, level: number, n: number): MatchPlayerSetup => {
    const nm = generateName('JP', rng)
    return { id: nextId--, name: nm.full, short: nm.short, number: n, pos, attr: buildAttrs(rng, pos, level), skills: [], stamina: 100, aggression: rng.int(6, 15), workRate: rng.int(8, 16) }
  }
  const tactics = { formation: f.id, mentality: 0, tempo: 50, width: 50, lineHeight: 50, pressing: 50, focus: 'balanced' as const, offsideTrap: false, counter: false }
  const team = (side: 0 | 1, level: number, name: string, short: string, colors: { primary: string; secondary: string }): TeamSetup => {
    // 背番号: 主人公は 10（GK なら 1）。ほかは 1 から順に（主人公のチームはその番号を飛ばす）
    const heroNum = p.pos === 'GK' ? 1 : 10
    let n = 0
    const num = () => (++n === heroNum && side === 0 ? ++n : n)
    const starters = f.slots.map((sl, i) => (side === 0 && i === heroSlot ? { ...matchPlayer(p, sl.pos, 'neutral'), number: heroNum } : fake(sl.pos, level, num())))
    const bench = (['GK', 'CB', 'CM', 'WG', 'ST'] as Position[]).map((pos) => fake(pos, level - 3, num()))
    return { clubId: -(900 + side), name, short, colors, gkColor: '#111827', formation: f.id, tactics: { ...tactics }, starters, bench, ai: true, chemBase: 55, cohesion: 55 }
  }
  // チームの力（y.strength は 45〜80）を選手の総合へ。相手は抽象の結果と同じ式
  const opp = youthOpp(y.path, fx.kind, fx.round, sagaRng(state, 3))
  const home = team(0, y.strength - 10, y.team, y.team.replace(/ U-18|学園高校|高校/g, ''), { primary: '#1d4ed8', secondary: '#ffffff' })
  const away = team(1, opp - 10, big.opp, big.opp.replace(/ U-18|高校/g, ''), { primary: '#dc2626', secondary: '#ffffff' })
  resolveKitClash(home, away)
  return { seed: hashSeed(state.seed, now, 0x7a17), home, away, neutral: true, knockout: true }
}

/** 観戦した大一番の結果を反映する（このあと週を進めても、抽象の試合はしない） */
export function playYouthWatched(state: GameState, summary: MatchSummary) {
  const fx = youthFixtureNow(state)
  if (!fx) return
  const c = state.career!
  const ps = summary.players.find((x) => x.id === c.playerId)
  const [gf, ga] = summary.score
  const pens = summary.pens
  const win = gf > ga || (gf === ga && !!pens && pens[0] > pens[1])
  const score = `${gf}-${ga}${pens ? `（PK ${pens[0]}-${pens[1]}）` : ''}`
  applyYouthResult(state, fx, win ? 'win' : 'lose', ps?.goals ?? 0, Math.round((ps?.rating ?? 6) * 10) / 10, score)
}

/** ユース期のシーズン末: 学年が上がり、18 歳になる年なら卒業してプロの入団の話 */
export function youthSeasonEnd(state: GameState) {
  const c = state.career!
  const saga = c.saga!
  if (saga.phase !== 'youth') return
  const y = saga.youth!
  const p = state.players[c.playerId]
  // 次のシーズンのはじめに 18 歳を過ぎていれば卒業
  const ageNext = (absWeekOf(state.season + 1, 0) - p.birthAbsWeek) / WEEKS_PER_SEASON
  if (ageNext >= 18 || y.year >= 3) {
    saga.phase = 'pro'
    p.isYouth = false
    const rng = sagaRng(state, 4)
    makeRookieOffers(state, rng)
    // 活躍した選手には、格上のクラブからも（大会の優勝・年代別代表・親の名前）
    const bonus = y.titles.length + (y.selected ? 1 : 0)
    if (bonus >= 1 && c.offers.length) {
      const npl1 = state.competitions.find((x) => x.id === 'NPL1')!.clubIds.filter((id) => !state.clubs[id].isPlayer)
      // 格上のクラブでは、まず有望株として
      c.offers[0] = { ...c.offers[0], clubId: npl1[hashSeed(state.seed, state.season, 0x18) % npl1.length], role: 'prospect' }
    }
    for (const o of c.offers) o.expiresAbsWeek = absWeekOf(state.season + 1, 6)
    queueTalk(state, 'saga_graduate', { team: y.team })
    report(state, `${y.team}を卒業。プロのクラブから入団の話が届いた。`)
  } else {
    y.year++
    y.strength = clamp(y.strength + (y.titles.length ? 2 : 0), 45, 80)
  }
}
