/**
 * キャリアのくらし: 住まい・装備・自己投資（サービス）・個人スポンサー・自宅の練習器具・趣味・オフの自主トレ合宿。
 *   住まい: 引っ越しの費用と毎週の家賃。休養の戻りと調子が良くなる（家族と暮らすにはアパート以上）。練習器具を置ける数も決まる
 *   装備: 特注スパイク（試合の経験点）、酸素カプセル（体力）
 *   自己投資（サービス）: 毎週の費用。格の高いスポンサーがつくと頼めるものが増える
 *   個人スポンサー: 知名度 20・45・70 で 1 枠ずつ（3 枠まで）。格（地元・全国・世界）で額が違い、目標を達成するとシーズン末にボーナス
 *   自宅の練習器具: 買い切り（Lv2 まで）。毎週の経験点・体力
 *   趣味: 「趣味の時間」で休みながら経験点。腕前 30・60・90 で出来事、60 でコツ
 * 家と車は career/homes.ts、オフの旅行は vacation.ts、テレビ・CM は media.ts（M12）。毎週とシーズン末はここから呼ぶ。
 * 貯金が足りなくなったら、サービス → 事業 → 車・別荘・住んでいる家（売る）→ 賃貸を下げる、の順。
 * 乱数: 申し出や出来事は、週ごとの専用の乱数（lifeRng）を使い、ほかの処理の乱数の並びを変えない。
 */
import type { Rng } from '../core/prng'
import { createRng, hashSeed } from '../core/prng'
import { absWeekOf, WEEKS_PER_SEASON } from '../core/calendar'
import {
  CAMP_COST,
  CAMP_PREMIUM_COST,
  LUXURIES,
  CLUB_SHARE_COSTS,
  GEAR,
  HOBBIES,
  HOME_GEAR,
  HOUSING_BY_ID,
  SERVICES,
  SPONSOR_SLOT_FAME,
  SPONSOR_TIERS,
  type HobbyDef,
} from '../data/career'
import { POSITION_DEFS } from '../data/positions'
import type { GameState } from '../models/game'
import type { ExpKind, GearId, HobbyId, HomeGearId, HousingId, LuxuryId, PersonalSponsor, ServiceId, SponsorTier } from '../models/career'
import { EXP_KINDS } from '../models/career'
import { clamp, report } from './core'
import { addFocus, gainExp } from './growth'
import { queueTalk } from './events'
import { bizWeek, bizSeasonEnd, sellWorstBusiness } from './business'
import { buyHome, carsWeek, carsWeeklyCost, homeGrade, homesWeek, homesWeeklyCost, housingOf, moveInto, ownedHomes, sellAssetForCash } from './homes'
import { mediaSeasonEnd, mediaWeek } from './media'
import { vacationSeasonEnd, vacationWeek } from './vacation'

export { housingOf } from './homes'

/** くらしの出来事の乱数（週ごと。ほかの処理の乱数とは別の流れ） */
export function lifeRng(state: GameState): Rng {
  return createRng(hashSeed(state.seed, absWeekOf(state.season, state.week), 0x1fe))
}

export function gearLevel(state: GameState, id: GearId): number {
  return state.career!.gear?.[id] ?? 0
}

export function hasService(state: GameState, id: ServiceId): boolean {
  return state.career!.services?.includes(id) ?? false
}

/** 引っ越す（買う家で、まだ持っていなければ買って住む） */
export function moveHouse(state: GameState, id: HousingId): boolean {
  if (HOUSING_BY_ID[id].kind === 'own' && !ownedHomes(state).includes(id)) return buyHome(state, id) && (state.career!.housing ?? 'dorm') === id
  return moveInto(state, id)
}

/** 装備の次のレベルの代金（最大なら null） */
export function gearNextCost(state: GameState, id: GearId): number | null {
  const def = GEAR.find((g) => g.id === id)!
  const lv = gearLevel(state, id)
  return lv < def.levels.length ? def.levels[lv] : null
}

export function buyGear(state: GameState, id: GearId): boolean {
  const c = state.career!
  const cost = gearNextCost(state, id)
  if (cost === null || c.money < cost) return false
  c.money -= cost
  c.gear = { ...c.gear, [id]: gearLevel(state, id) + 1 }
  report(state, `${GEAR.find((g) => g.id === id)!.name}を手に入れた。`)
  return true
}

// ---------------------------------------------------------------- スポンサー

/** 今の個人スポンサー（古いセーブの sponsor を 1 枠目に移す） */
export function sponsorsOf(state: GameState): PersonalSponsor[] {
  const c = state.career!
  if (c.sponsor) {
    c.sponsors = [...(c.sponsors ?? []), { ...c.sponsor, tier: c.sponsor.tier ?? 1 }]
    c.sponsor = undefined
  }
  return c.sponsors ?? []
}

/** 知名度で開いているスポンサーの枠の数（0〜3） */
export function sponsorSlots(state: GameState): number {
  const fame = state.career!.fame
  return SPONSOR_SLOT_FAME.filter((f) => fame >= f).length
}

/** 契約しているスポンサーのいちばん高い格（いなければ 0）。自己投資の選べるものが増える */
export function sponsorTier(state: GameState): 0 | SponsorTier {
  return sponsorsOf(state).reduce<0 | SponsorTier>((m, s) => Math.max(m, s.tier ?? 1) as 0 | SponsorTier, 0)
}

export function acceptSponsor(state: GameState): boolean {
  const c = state.career!
  const o = c.sponsorOffer
  if (!o || sponsorsOf(state).length >= sponsorSlots(state)) return false
  c.sponsors = [...sponsorsOf(state), { company: o.company, annual: o.annual, until: o.until, tier: o.tier, goal: o.goal }]
  c.sponsorOffer = undefined
  report(state, `${o.company}と個人スポンサー契約を結んだ（年 ${o.annual.toLocaleString()} 万円）。`)
  return true
}

export function declineSponsor(state: GameState) {
  state.career!.sponsorOffer = undefined
}

/** 申し出を作る: 届く格は知名度で決まり（ときどき 1 つ下）、海外のクラブにいると格の高い会社の額が上がる */
/** 個人スポンサーの申し出が届く週（シーズンのはじめと半ば） */
export const SPONSOR_OFFER_WEEKS = [1, 24]
/** 返事をするまで消えない（古いセーブの期限つきの申し出も、もう消さない） */
const NO_EXPIRY = 48 * 100

function makeSponsorOffer(state: GameState, rng: Rng): PersonalSponsor & { expiresAbsWeek: number } {
  const c = state.career!
  const p = state.players[c.playerId]
  const now = absWeekOf(state.season, state.week)
  const reachable = SPONSOR_TIERS.filter((t) => c.fame >= t.minFame)
  let def = reachable[reachable.length - 1]
  if (reachable.length > 1 && rng.chance(0.3)) def = reachable[reachable.length - 2]
  const abroad = p.clubId >= 0 && state.clubs[p.clubId].country !== 'JP'
  const taken = new Set(sponsorsOf(state).map((s) => s.company))
  const names = [...def.companies, ...(abroad && def.global ? def.global : [])].filter((n) => !taken.has(n))
  const company = names.length ? rng.pick(names) : def.companies[0]
  const annual = Math.round((c.fame * def.perFame * (0.85 + rng.next() * 0.3) * (abroad && def.tier >= 2 ? 1.25 : 1)) / 10) * 10
  // 目標: 攻撃の選手は得点、ほかは出場
  const attacker = ['FW'].includes(POSITION_DEFS[p.pos].line) || p.pos === 'AM' || p.pos === 'WG'
  const goal = attacker ? { kind: 'goals' as const, target: def.tier * 4 + 2, bonus: Math.round(annual * 0.25) } : { kind: 'apps' as const, target: 18 + def.tier * 4, bonus: Math.round(annual * 0.2) }
  return { company, annual, tier: def.tier, goal, until: state.season + (rng.chance(0.5) ? 1 : 0), expiresAbsWeek: now + NO_EXPIRY }
}

// ---------------------------------------------------------------- 自己投資（サービス）

/** そのサービスを頼めるか（格の高いスポンサーがつくと増える） */
export function serviceUnlocked(state: GameState, id: ServiceId): boolean {
  const def = SERVICES.find((s) => s.id === id)!
  return def.minTier <= sponsorTier(state)
}

export function toggleService(state: GameState, id: ServiceId) {
  const c = state.career!
  const list = c.services ?? []
  if (list.includes(id)) c.services = list.filter((x) => x !== id)
  else if (serviceUnlocked(state, id)) c.services = [...list, id]
}

/** オフシーズンの海外自主トレ合宿を申し込めるか（世界的ブランドのスポンサーがいる） */
export function canBookCamp(state: GameState, premium = false): boolean {
  const c = state.career!
  return sponsorTier(state) >= 3 && !c.camp && c.money >= (premium ? CAMP_PREMIUM_COST : CAMP_COST)
}

/** 申し込む（このシーズンの終わりに、選んだ系統の経験点がまとめて入る。一流のトレーナーつきは 2 倍） */
export function bookCamp(state: GameState, kind: ExpKind, premium = false): boolean {
  if (!canBookCamp(state, premium)) return false
  const c = state.career!
  c.money -= premium ? CAMP_PREMIUM_COST : CAMP_COST
  c.camp = { kind, season: state.season, premium }
  report(state, `オフシーズンの海外自主トレ合宿${premium ? '（一流のトレーナーつき）' : ''}を申し込んだ。`)
  return true
}

// ---------------------------------------------------------------- ぜいたく品・社会貢献

export function hasLuxury(state: GameState, id: LuxuryId): boolean {
  return state.career!.luxuries?.includes(id) ?? false
}

export function buyLuxury(state: GameState, id: LuxuryId): boolean {
  const c = state.career!
  const def = LUXURIES.find((l) => l.id === id)!
  if (hasLuxury(state, id) || c.money < def.cost) return false
  c.money -= def.cost
  c.luxuries = [...(c.luxuries ?? []), id]
  if (id === 'watch') c.fame = clamp(c.fame + 1, 0, 100)
  if (id === 'donation') {
    c.fame = clamp(c.fame + 6, 0, 100)
    gainExp(state, { mental: 30 })
    queueTalk(state, 'sys_donation')
  }
  report(state, `${def.name}${id === 'donation' ? 'を行った' : 'を手に入れた'}。`)
  return true
}

// ---------------------------------------------------------------- 自宅の練習器具

/** 住まいに置ける練習器具の数 */
export function homeSlots(state: GameState): number {
  return housingOf(state).slots
}

export function homeGearLevel(state: GameState, id: HomeGearId): number {
  return state.career!.homeGear?.[id] ?? 0
}

/** 置いている器具（住まいの枠を超えた分は、使えない） */
export function activeHomeGear(state: GameState): HomeGearId[] {
  return HOME_GEAR.filter((g) => homeGearLevel(state, g.id) > 0)
    .map((g) => g.id)
    .slice(0, homeSlots(state))
}

/** 次のレベルの代金（買えない・最大なら null） */
export function homeGearNextCost(state: GameState, id: HomeGearId): number | null {
  const def = HOME_GEAR.find((g) => g.id === id)!
  const lv = homeGearLevel(state, id)
  if (lv >= def.levels.length) return null
  if (lv === 0 && HOME_GEAR.filter((g) => homeGearLevel(state, g.id) > 0).length >= homeSlots(state)) return null
  return def.levels[lv]
}

export function buyHomeGear(state: GameState, id: HomeGearId): boolean {
  const c = state.career!
  const cost = homeGearNextCost(state, id)
  if (cost === null || c.money < cost) return false
  c.money -= cost
  c.homeGear = { ...c.homeGear, [id]: homeGearLevel(state, id) + 1 }
  report(state, `自宅に${HOME_GEAR.find((g) => g.id === id)!.name}を置いた。`)
  return true
}

// ---------------------------------------------------------------- 趣味

export const HOBBY_BY_ID = Object.fromEntries(HOBBIES.map((h) => [h.id, h])) as Record<HobbyId, HobbyDef>

/** 同時に続けられる趣味の数（一軒家なら 3、豪邸なら 4） */
export function hobbyMax(state: GameState): number {
  const g = homeGrade(state)
  return g >= 4 ? 4 : g === 3 ? 3 : 2
}

export function canStartHobby(state: GameState, id: HobbyId): { ok: boolean; reason?: string } {
  const c = state.career!
  const list = c.hobbies ?? []
  if (list.some((h) => h.id === id)) return { ok: false, reason: '続けている' }
  if (list.length >= hobbyMax(state)) return { ok: false, reason: `${hobbyMax(state)} つまで` }
  if (c.money < HOBBY_BY_ID[id].cost) return { ok: false, reason: '貯金が足りない' }
  return { ok: true }
}

export function startHobby(state: GameState, id: HobbyId): boolean {
  if (!canStartHobby(state, id).ok) return false
  const c = state.career!
  c.money -= HOBBY_BY_ID[id].cost
  c.hobbies = [...(c.hobbies ?? []), { id, skill: 0, startedAbsWeek: absWeekOf(state.season, state.week) }]
  report(state, `${HOBBY_BY_ID[id].name}を始めた。`)
  return true
}

export function quitHobby(state: GameState, id: HobbyId) {
  const c = state.career!
  c.hobbies = (c.hobbies ?? []).filter((h) => h.id !== id)
}

const HOBBY_MILESTONES = [30, 60, 90]

/** 腕前を上げ、30・60・90 を越えたら出来事を予約する（60 でコツ） */
function raiseHobby(state: GameState, id: HobbyId, amount: number) {
  const c = state.career!
  const h = c.hobbies?.find((x) => x.id === id)
  if (!h) return
  const before = h.skill
  h.skill = Math.min(100, h.skill + amount * (1 - h.skill / 160))
  for (const m of HOBBY_MILESTONES) {
    if (before < m && h.skill >= m) {
      queueTalk(state, `hobby_${id}_${m}`)
      const kotsu = HOBBY_BY_ID[id].kotsu
      if (m === 60 && kotsu) c.kotsu[kotsu] = Math.min(3, (c.kotsu[kotsu] ?? 0) + 1)
    }
  }
}

/** 過ごし方「趣味の時間」: 休みながら経験点と調子。腕前が大きく上がる */
export function doHobby(state: GameState, id: HobbyId) {
  const c = state.career!
  const p = state.players[c.playerId]
  const def = HOBBY_BY_ID[id]
  if (!c.hobbies?.some((h) => h.id === id)) {
    // やめた趣味が予定に残っていたら、ただの休養
    c.stamina += 30
    return
  }
  c.stamina += def.stamina
  p.condition = clamp(p.condition + def.condition, 0, 100)
  gainExp(state, def.exp)
  if (def.fame) c.fame = clamp(c.fame + def.fame, 0, 100)
  raiseHobby(state, id, 6)
  report(state, `${def.name}の時間を楽しんだ。`)
}

/** 趣味の腕前（その人と同じ趣味があると、デートや恋人の出来事で絆が多く上がる） */
export function hobbySkill(state: GameState, id: HobbyId): number {
  return state.career!.hobbies?.find((h) => h.id === id)?.skill ?? 0
}

// ---------------------------------------------------------------- 毎週の倍率と費用

/** 休養で余分に戻る体力 */
export function restBonus(state: GameState): number {
  return housingOf(state).rest
}

/** 練習の経験点の倍率 */
export function trainMul(state: GameState): number {
  return hasService(state, 'trainer') ? 1.15 : 1
}

/** 練習でケガをする危険の倍率 */
export function injuryRiskMul(state: GameState): number {
  return (hasService(state, 'trainer') ? 0.4 : 1) * (hasService(state, 'physio') ? 0.5 : 1) * (hasService(state, 'scienceLab') ? 0.7 : 1) * (hasService(state, 'medicalTeam') ? 0.6 : 1)
}

/** 試合の経験点の倍率 */
export function matchExpMul(state: GameState): number {
  return 1 + gearLevel(state, 'spikes') * 0.1 + (hasService(state, 'analyst') ? 0.1 : 0)
}

/**
 * 年俸の手取り（万円/年）: 税金（年俸が高いほど重い。おおよそ 2 割〜5 割）と代理人の手数料 5%
 */
export function netWage(wage: number): number {
  const tax = Math.min(0.5, 0.15 + 0.35 * (1 - Math.exp(-wage / 4000)))
  return Math.round(wage * (1 - tax) * 0.95)
}

/** 家族の生活費（毎週・万円）: 結婚して +3、子ども 1 人ごとに +2 */
export function familyCost(state: GameState): number {
  const c = state.career!
  return (c.spouse ? 3 : 0) + (c.children?.length ?? 0) * 2
}

/** 毎週の出費（家賃と家の維持費・車・サービス・家族・ぜいたく品の維持費） */
export function weeklyCost(state: GameState): number {
  const lux = LUXURIES.filter((l) => hasLuxury(state, l.id)).reduce((n, l) => n + (l.weekly ?? 0), 0)
  return homesWeeklyCost(state) + carsWeeklyCost(state) + SERVICES.filter((s) => hasService(state, s.id)).reduce((n, s) => n + s.weekly, 0) + familyCost(state) + lux
}

// ---------------------------------------------------------------- 故郷のクラブへの出資

/** 故郷のクラブ（入団したクラブ） */
export function homeClubId(state: GameState): number | undefined {
  const c = state.career!
  return c.homeClubId ?? c.log[0]?.clubId
}

/** 次の出資の費用（3 段まで。最大なら null） */
export function clubShareNextCost(state: GameState): number | null {
  const lv = state.career!.clubShare?.level ?? 0
  return lv < CLUB_SHARE_COSTS.length ? CLUB_SHARE_COSTS[lv] : null
}

/** 故郷のクラブに出資する: クラブの格 +6・施設（練習・医療）+1、知名度 +4 */
export function investHomeClub(state: GameState): boolean {
  const c = state.career!
  const id = homeClubId(state)
  const cost = clubShareNextCost(state)
  if (id === undefined || cost === null || c.money < cost) return false
  const club = state.clubs[id]
  c.money -= cost
  c.clubShare = { clubId: id, level: (c.clubShare?.level ?? 0) + 1 }
  club.rep = Math.min(88, club.rep + 6)
  club.facilities.training = Math.min(5, club.facilities.training + 1)
  club.facilities.medical = Math.min(5, club.facilities.medical + 1)
  club.budget += cost
  c.fame = clamp(c.fame + 4, 0, 100)
  queueTalk(state, 'sys_clubShare', { club: club.name, level: String(c.clubShare.level) })
  report(state, `故郷のクラブ「${club.name}」に出資した（${c.clubShare.level} 段目）。`)
  return true
}

/** 毎週の収入（スポンサーの手取り） */
export function weeklySponsorIncome(state: GameState): number {
  return sponsorsOf(state).reduce((n, s) => n + Math.round(netWage(s.annual) / WEEKS_PER_SEASON), 0)
}

// ---------------------------------------------------------------- 毎週・シーズン末

/** 毎週: 出費と収入、住まい・サービス・器具・趣味・事業の効果、スポンサーの申し出 */
export function lifeWeek(state: GameState) {
  const c = state.career!
  const p = state.players[c.playerId]
  const rng = lifeRng(state)
  // 格が下がって頼めなくなったサービスはやめる
  if (c.services?.some((id) => !serviceUnlocked(state, id))) c.services = c.services.filter((id) => serviceUnlocked(state, id))
  // 出費。足りなくなったらサービス → 事業 → 住まいの順にやめる
  c.money -= weeklyCost(state)
  if (c.money < 0 && c.services?.length) {
    c.services = []
    report(state, '貯金が足りなくなったので、トレーナーや栄養士などの契約をやめた。')
  }
  if (c.money < 0 && c.businesses?.length) sellWorstBusiness(state)
  // 車 → 別荘 → いつも乗る車 → 住んでいる家の順に売る
  for (let i = 0; i < 12 && c.money < 0 && sellAssetForCash(state); i++);
  if (c.money < 0 && housingOf(state).kind === 'rent' && housingOf(state).weekly > 0) {
    const cheaper: HousingId = c.housing === 'mansion' ? 'apartment' : 'dorm'
    c.housing = cheaper
    report(state, `家賃が払えなくなり、${HOUSING_BY_ID[cheaper].name}に移った。`)
  }
  // 住まいとサービスの効果
  const h = housingOf(state)
  const nutrition = hasService(state, 'nutrition')
  const chef = hasService(state, 'chef')
  p.condition = clamp(p.condition + h.condition + (nutrition ? 1 : 0) + (chef ? 1.5 : 0) + (c.spouse ? 0.5 : 0), 0, 100)
  c.stamina = clamp(c.stamina + gearLevel(state, 'capsule') * 4 + (nutrition ? 3 : 0) + (chef ? 3 : 0) + (hasService(state, 'physio') ? 4 : 0), 0, 100)
  if (hasService(state, 'mentalCoach')) gainExp(state, { mental: 4 })
  if (hasService(state, 'analyst')) gainExp(state, { tactics: 4 })
  if (hasService(state, 'sleep')) {
    c.stamina = clamp(c.stamina + 3, 0, 100)
    p.condition = clamp(p.condition + 0.5, 0, 100)
  }
  if (hasService(state, 'coach')) {
    gainExp(state, { tech: 5, tactics: 3 })
    addFocus(state, ['shoot', 'pass', 'dribble'], 0.2)
  }
  if (hasService(state, 'foundation')) {
    gainExp(state, { mental: 3 })
    c.fame = clamp(c.fame + 0.05, 0, 100)
  }
  if (hasLuxury(state, 'trainingCenter')) gainExp(state, { power: 4, speed: 4, tech: 4, tactics: 4, mental: 4 })
  if (hasLuxury(state, 'jet')) {
    c.stamina = clamp(c.stamina + 8, 0, 100)
    p.condition = clamp(p.condition + 0.5, 0, 100)
  }
  if (hasService(state, 'supportTeam')) {
    c.stamina = clamp(c.stamina + 3, 0, 100)
    p.condition = clamp(p.condition + 1, 0, 100)
    c.fame = clamp(c.fame + 0.03, 0, 100)
  }
  if (hasLuxury(state, 'villa') && state.week === 0) {
    c.stamina = 100
    p.condition = 100
  }
  // 自宅の練習器具
  for (const id of activeHomeGear(state)) {
    const def = HOME_GEAR.find((g) => g.id === id)!
    const lv = homeGearLevel(state, id)
    if (def.exp) gainExp(state, def.exp[lv - 1])
    if (def.stamina) c.stamina = clamp(c.stamina + def.stamina[lv - 1], 0, 100)
    if (def.condition) p.condition = clamp(p.condition + def.condition * lv, 0, 100)
    if (def.attrs) addFocus(state, def.attrs, 0.3 * lv)
  }
  // 家の特長・別荘・車
  homesWeek(state)
  carsWeek(state)
  // 旅行のあと（新しいシーズンのはじめ）・メディアの依頼と CM
  vacationWeek(state)
  mediaWeek(state)
  // 趣味の腕前は、ふだんも少しずつ上がる
  for (const hb of c.hobbies ?? []) raiseHobby(state, hb.id, 0.4)
  // 事業
  bizWeek(state, rng)
  // スポンサー
  const sponsors = sponsorsOf(state)
  if (sponsors.length) {
    c.money += weeklySponsorIncome(state)
    c.fame = clamp(c.fame + 0.03 * sponsors.length, 0, 100)
    for (const s of sponsors.filter((x) => x.until < state.season)) report(state, `${s.company}との個人スポンサー契約が終わった。`)
    c.sponsors = sponsors.filter((x) => x.until >= state.season)
  }
  // 申し出は、シーズンのはじめ（第 1 週）と半ば（第 24 週）に、空いた枠があれば必ず届く。返事をするまで消えない
  // （1 か月オートは申し出で止まる。advanceWeek）
  const free = sponsorSlots(state) - sponsorsOf(state).length
  if (free > 0 && !c.sponsorOffer && SPONSOR_OFFER_WEEKS.includes(state.week)) {
    c.sponsorOffer = makeSponsorOffer(state, rng)
    const tier = SPONSOR_TIERS.find((t) => t.tier === c.sponsorOffer!.tier)!
    report(state, `${c.sponsorOffer.company}（${tier.name}）から個人スポンサーの申し出が届いた（年 ${c.sponsorOffer.annual.toLocaleString()} 万円）。`)
  }
}

/** シーズン末: スポンサーの目標のボーナス、オフの自主トレ合宿、事業の決算 */
export function lifeSeasonEnd(state: GameState) {
  const c = state.career!
  const p = state.players[c.playerId]
  for (const s of sponsorsOf(state)) {
    if (!s.goal) continue
    const v = s.goal.kind === 'goals' ? p.stats.goals : p.stats.apps
    if (v >= s.goal.target) {
      c.money += netWage(s.goal.bonus)
      report(state, `${s.company}の目標（${s.goal.kind === 'goals' ? `${s.goal.target} 得点` : `${s.goal.target} 試合出場`}）を達成し、ボーナス ${s.goal.bonus.toLocaleString()} 万円。`)
    }
  }
  if (c.camp && c.camp.season === state.season) {
    const gain: Partial<Record<ExpKind, number>> = {}
    const m = c.camp.premium ? 2 : 1
    for (const k of EXP_KINDS) gain[k] = (k === c.camp.kind ? 150 : 30) * m
    gainExp(state, gain)
    report(state, 'オフシーズンの海外自主トレ合宿で、みっちり鍛えた。')
    c.camp = undefined
  }
  vacationSeasonEnd(state)
  mediaSeasonEnd(state)
  bizSeasonEnd(state)
}

