/** 開催国（決まっている年以外は順番に回す） */
const WC_HOSTS: Record<number, Nation> = { 2030: 'ES', 2034: 'SA', 2038: 'JP', 2042: 'BR', 2046: 'DE', 2050: 'US', 2054: 'FR', 2058: 'AR' }
const HOST_CYCLE: Nation[] = ['EN', 'KR', 'MX', 'IT', 'MA', 'NL', 'AU', 'BR', 'ES', 'JP', 'PT', 'US']

export function wcHost(year: number): Nation {
  const k = Math.floor((year - 2062) / 4) % HOST_CYCLE.length
  return WC_HOSTS[year] ?? HOST_CYCLE[(k + HOST_CYCLE.length) % HOST_CYCLE.length]
}

export function isWcYear(year: number): boolean {
  return year % 4 === 2
}
