/**
 * ホームタウンとのつながり（M19。クラブモード）: 4 週に 1 回、地域の活動をひとつ。
 *   人気・サッカー熱・地元企業・街の発展度が少しずつ上がる。発展度が 10 上がるごとに人口と経済が育つ。
 *   活動の回数で「つながり」の段が上がる（観客が少し増える）。乱数は使わない。
 */
import { absWeekOf } from '../core/calendar'
import type { GameState } from '../models/game'
import { fansCap } from './fans'

export type ActivityId = 'clinic' | 'shops' | 'visit' | 'clean' | 'fanday'

export interface ActivityDef {
  id: ActivityId
  name: string
  desc: string
  /** 費用（万円） */
  cost: number
  popularity?: number
  passion?: number
  economy?: number
  development?: number
  /** 選手のやる気 */
  morale?: number
  /** サポーターの増え方（割合） */
  fans?: number
  /** 1 シーズンに 1 回だけ */
  oncePerSeason?: boolean
}

export const ACTIVITIES: ActivityDef[] = [
  { id: 'clinic', name: 'サッカー教室', desc: '選手が地元の子どもたちに教える', cost: 50, popularity: 1.5, passion: 0.4, development: 0.3 },
  { id: 'shops', name: '商店街とのコラボ', desc: '商店街のイベントに選手が出る。地元企業との縁が深まる', cost: 100, popularity: 0.6, economy: 0.4, development: 0.5 },
  { id: 'visit', name: '学校・病院の訪問', desc: '子どもや患者さんを励ます。選手のやる気も上がる', cost: 0, popularity: 1, morale: 2, development: 0.2 },
  { id: 'clean', name: '街の清掃活動', desc: 'サポーターといっしょに街をきれいにする', cost: 0, passion: 0.2, development: 0.8 },
  { id: 'fanday', name: 'ファン感謝デー', desc: 'スタジアムを開放してファンと交流する（1 シーズンに 1 回）', cost: 300, popularity: 2.5, fans: 0.03, oncePerSeason: true },
]

export const ACTIVITY_GAP = 4

/** つながりの段（活動の回数）。段ごとに観客が 1% 増える */
export const TIE_STAGES: { min: number; name: string }[] = [
  { min: 0, name: 'これから' },
  { min: 5, name: '顔なじみ' },
  { min: 15, name: '街の誇り' },
  { min: 30, name: '街の象徴' },
]

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

export function communityOf(state: GameState) {
  state.community ??= { total: 0, count: {} }
  return state.community
}

export function tieStage(state: GameState): number {
  const total = state.community?.total ?? 0
  let i = 0
  TIE_STAGES.forEach((s, k) => total >= s.min && (i = k))
  return i
}

/** 次に活動できるまでの週（0 ならいま） */
export function activityWait(state: GameState): number {
  const last = state.community?.last
  return last === undefined ? 0 : Math.max(0, last + ACTIVITY_GAP - absWeekOf(state.season, state.week))
}

export function activityAvailable(state: GameState, id: ActivityId): boolean {
  const def = ACTIVITIES.find((a) => a.id === id)!
  const me = state.clubs[state.playerClubId]
  if (activityWait(state) > 0 || me.budget < def.cost) return false
  if (def.oncePerSeason && state.community?.fandaySeason === state.season) return false
  return true
}

/** 活動する（できなければ false） */
export function doActivity(state: GameState, id: ActivityId): boolean {
  if (state.mode === 'career' || !activityAvailable(state, id)) return false
  const def = ACTIVITIES.find((a) => a.id === id)!
  const me = state.clubs[state.playerClubId]
  const h = state.hometown
  const c = communityOf(state)
  const absWeek = absWeekOf(state.season, state.week)
  me.budget -= def.cost
  const last = state.finance[state.finance.length - 1]
  if (last) last.other -= def.cost
  if (def.popularity) me.popularity = clamp(me.popularity + def.popularity, 1, 100)
  if (def.passion) h.passion = clamp(h.passion + def.passion, 0, 100)
  if (def.economy) h.economy = clamp(h.economy + def.economy, 0, 100)
  if (def.fans) me.fans = Math.round(Math.min(fansCap(state, me), me.fans * (1 + def.fans)))
  if (def.morale) for (const p of Object.values(state.players)) if (p.clubId === me.id && !p.retired) p.morale = clamp(p.morale + def.morale, 0, 100)
  if (def.development) {
    const before = Math.floor(h.development / 10)
    h.development = clamp(h.development + def.development, 0, 100)
    // 発展度が 10 上がるごとに、人口と経済が育つ
    if (Math.floor(h.development / 10) > before) {
      h.population = Math.min(150, h.population + 1)
      h.economy = clamp(h.economy + 0.5, 0, 100)
      state.news.push({ absWeek, category: 'club', mine: true, text: `${h.city}の街が育っています（人口 ${h.population} 万人）。地域の活動の成果です。` })
    }
  }
  const stageBefore = tieStage(state)
  c.total++
  c.count = { ...c.count, [id]: (c.count[id] ?? 0) + 1 }
  c.last = absWeek
  if (def.oncePerSeason) c.fandaySeason = state.season
  const stage = tieStage(state)
  state.news.push({ absWeek, category: 'club', mine: true, text: `${def.name}を行いました。${stage > stageBefore ? `地域とのつながりが「${TIE_STAGES[stage].name}」になりました！` : ''}` })
  return true
}

/** つながりの段による観客の倍率（自クラブだけ） */
export function tieAttendanceMul(state: GameState): number {
  return 1 + tieStage(state) * 0.01
}
