/**
 * テレビ・雑誌・CM（M12）: 月に 1 回ほど依頼が来る。来やすさと種類は知名度・ランク・タイトルで決まり、3 週で消える。
 *   受けると出演料（税と手数料を引いた手取り）・知名度・体力・調子・監督の評価が動き、短い会話が出る。断ることもできる。
 *   CM は 1 シーズン契約で毎週の収入（2 本まで）。自伝は一度きり（28 歳から）で、印税が 3 シーズン入る。
 *   海外のクラブにいると、その国の番組からも依頼が来る。
 * 乱数は専用の流れ（ほかの処理の乱数の並びを変えない）。
 */
import type { Rng } from '../core/prng'
import { createRng, hashSeed } from '../core/prng'
import { absWeekOf, WEEKS_PER_SEASON } from '../core/calendar'
import { BOOK_MIN_AGE, CM_MAX, MEDIA, MEDIA_BY_KIND, OVERSEAS_SHOWS } from '../data/career'
import type { GameState } from '../models/game'
import type { MediaKind } from '../models/career'
import { careerAge, clamp, regionOf, report } from './core'
import { queueTalk } from './events'
import { gainExp } from './growth'
import { netWage } from './life'
import { myRank } from './rank'

function mediaRng(state: GameState): Rng {
  return createRng(hashSeed(state.seed, absWeekOf(state.season, state.week), 0x3c1))
}

/** 今の CM の契約 */
export function cmsOf(state: GameState) {
  return state.career!.cms ?? []
}

/** 依頼が来うる種類 */
export function mediaKinds(state: GameState): MediaKind[] {
  const c = state.career!
  const abroad = regionOf(state) !== 'JP'
  const titled = c.log.some((l) => l.titles.length > 0)
  return MEDIA.filter((m) => {
    if (c.fame < m.minFame) return false
    if (m.kind === 'overseas') return abroad && !!OVERSEAS_SHOWS[regionOf(state)]
    if (m.kind === 'book') return careerAge(state) >= BOOK_MIN_AGE && !c.book && !(c.media ?? []).some((r) => r.kind === 'book')
    if (m.kind === 'cm') return cmsOf(state).length < CM_MAX
    if (m.kind === 'documentary') return titled || (myRank(state)?.step ?? 0) >= 4
    return true
  }).map((m) => m.kind)
}

const WEIGHT: Record<MediaKind, number> = { news: 3, magazine: 3, variety: 2, documentary: 1, book: 1, cm: 2, overseas: 3 }

/** 依頼を作る（出演料は知名度で上がる。CM は年額で、海外にいると上がる） */
function makeOffer(state: GameState, rng: Rng, kind: MediaKind) {
  const c = state.career!
  const def = MEDIA_BY_KIND[kind]
  const names = kind === 'overseas' ? (OVERSEAS_SHOWS[regionOf(state)] ?? []) : def.names
  const taken = new Set(cmsOf(state).map((x) => x.company))
  const pool = names.filter((n) => !taken.has(n))
  const name = rng.pick(pool.length ? pool : names)
  const [lo, hi] = def.pay
  const t = clamp((c.fame - def.minFame) / Math.max(1, 100 - def.minFame), 0, 1)
  const abroad = regionOf(state) !== 'JP' && kind === 'cm' ? 1.3 : 1
  const pay = Math.round(((lo + (hi - lo) * t) * (0.85 + rng.next() * 0.3) * abroad) / 10) * 10
  // 1 か月オートで見落とさないように 6 週は残す
  return { kind, name, pay, expiresAbsWeek: absWeekOf(state.season, state.week) + 6 }
}

/** 毎週: 依頼の期限切れ・CM の収入と終わり・月に 1 回ほど新しい依頼 */
export function mediaWeek(state: GameState) {
  const c = state.career!
  const now = absWeekOf(state.season, state.week)
  if (c.mediaOffer && c.mediaOffer.expiresAbsWeek < now) c.mediaOffer = undefined
  const cms = cmsOf(state)
  if (cms.length) {
    c.money += cms.reduce((n, x) => n + Math.round(netWage(x.annual) / WEEKS_PER_SEASON), 0)
    c.fame = clamp(c.fame + 0.04 * cms.length, 0, 100)
    for (const x of cms.filter((x) => x.until < state.season)) report(state, `${x.company}の CM の契約が終わった。`)
    c.cms = cms.filter((x) => x.until >= state.season)
  }
  // 依頼は 2 か月に 1 度の機会に、知名度に応じて（知名度 50 で 1 シーズンに 2 回ほど、100 でも 3 回ほど。多すぎるとの声で減らした）
  if (c.mediaOffer || c.retired || state.week % 8 !== 2) return
  const rng = mediaRng(state)
  if (!rng.chance(0.15 + c.fame / 300)) return
  const kinds = mediaKinds(state)
  if (!kinds.length) return
  const weights = kinds.map((k) => WEIGHT[k])
  let r = rng.next() * weights.reduce((a, b) => a + b, 0)
  let kind = kinds[kinds.length - 1]
  for (let i = 0; i < kinds.length; i++) {
    r -= weights[i]
    if (r <= 0) {
      kind = kinds[i]
      break
    }
  }
  c.mediaOffer = makeOffer(state, rng, kind)
  report(state, `${c.mediaOffer.name}から${MEDIA_BY_KIND[kind].name}の依頼が届いた。`)
}

/** 依頼を受ける */
export function acceptMedia(state: GameState): boolean {
  const c = state.career!
  const o = c.mediaOffer
  if (!o) return false
  const def = MEDIA_BY_KIND[o.kind]
  if (o.kind === 'cm' && cmsOf(state).length >= CM_MAX) return false
  const p = state.players[c.playerId]
  c.mediaOffer = undefined
  if (o.kind === 'cm') {
    c.cms = [...cmsOf(state), { company: o.name, annual: o.pay, until: state.week >= 36 ? state.season + 1 : state.season }]
  } else if (o.kind === 'book') {
    c.book = { royalty: Math.round(o.pay / 3), until: state.season + 2 }
  } else {
    c.money += netWage(o.pay)
  }
  c.fame = clamp(c.fame + def.fame, 0, 100)
  c.stamina = clamp(c.stamina + def.stamina, 0, 100)
  if (def.condition) p.condition = clamp(p.condition + def.condition, 0, 100)
  if (def.trust) c.trust = clamp(c.trust + def.trust, 0, 100)
  if (def.exp) gainExp(state, def.exp)
  c.media = [...(c.media ?? []), { kind: o.kind, name: o.name, season: state.season, pay: o.pay }]
  queueTalk(state, `media:${o.kind}`, { name: o.name })
  report(state, o.kind === 'cm' ? `${o.name}の CM に出ることになった（年 ${o.pay.toLocaleString()} 万円）。` : `${o.name}の${def.name}を引き受けた。`)
  return true
}

export function declineMedia(state: GameState) {
  state.career!.mediaOffer = undefined
}

/** シーズン末: 自伝の印税 */
export function mediaSeasonEnd(state: GameState) {
  const c = state.career!
  if (!c.book) return
  c.money += netWage(c.book.royalty)
  report(state, `自伝の印税が入った（${c.book.royalty.toLocaleString()} 万円）。`)
  if (c.book.until <= state.season) c.book = undefined
}

/** 毎週の CM の収入（手取り。画面用） */
export function weeklyCmIncome(state: GameState): number {
  return cmsOf(state).reduce((n, x) => n + Math.round(netWage(x.annual) / WEEKS_PER_SEASON), 0)
}
