/**
 * ゲーム状態のストア。GameState 本体は mutable で、Zustand には参照と version だけ置く。
 * エンジンで state を書き換えたら bump() で再描画する。週送りと操作のあとに自動保存（まとめて、少し遅らせて）。
 */
import { create } from 'zustand'
import { createNewGame, dateLabel, rankOf, type GameState, type NewGameOptions } from '../engine'
import { advanceWeek, drawWeek, playPlayerMatch, playerFixtureThisWeek, type WeekReport } from '../engine/core/advanceWeek'
import type { MatchSummary } from '../engine/match/live/types'
import { loadGame, saveGame, saveSnapshot } from '../persistence/db'
import { useSettings } from './settingsStore'
import { setHasGameProbe } from './uiStore'
import type { StopKind } from '../engine/core/advanceWeek'
import { createCareerGame, type CareerNewOptions } from '../engine/career/create'
import { careerNationalFixture, playCareerNational } from '../engine/national/national'
import { assignPhotos } from '../engine/player/photos'

export type AdvanceMode = 'week' | 'nextMatch' | 'month'

/** 処理中に起きたエラー（画面に出して、直前のセーブに戻す） */
export interface GameError {
  where: string
  message: string
  stack: string
  season: number
  week: number
}

export interface AdvanceOutcome {
  /** 今週は自クラブの試合がある（試合前の画面へ） */
  needMatch: boolean
  /** キャリア: 今週は主人公の代表戦がある（代表戦の画面へ） */
  needNational?: boolean
  reports: WeekReport[]
  /** 止まった理由 */
  stopText?: string
  seasonEnded: boolean
}

interface GameStore {
  state: GameState | null
  version: number
  slotId: number
  busy: boolean
  newGame: (opts: NewGameOptions, slotId: number) => GameState
  /** キャリアモードを始める */
  newCareer: (opts: CareerNewOptions, slotId: number) => GameState
  load: (slotId: number) => Promise<boolean>
  bump: () => void
  /** state を書き換えて再描画・保存する（画面からの変更はここを通す） */
  mutate: (fn: (state: GameState) => void) => void
  persist: () => Promise<void>
  close: () => void
  /** 週を進める（自クラブの試合がある週では止まる。1か月モードは試合も自動で行う） */
  advance: (mode: AdvanceMode) => AdvanceOutcome
  /** 1 週ずつ、画面に進み具合（progress）を出しながら進める（1か月オート。画面が止まって見えないように） */
  advanceAsync: (mode: AdvanceMode) => Promise<AdvanceOutcome>
  /** advanceAsync の進み具合（進めた週 / 全部）。進めていなければ null */
  progress: { done: number; total: number } | null
  /**
   * 自クラブの試合を行う（観戦した結果を渡すか、自動で計算）。
   * その週にもう自クラブの試合がなければ週を進める。返り値は週を進めたときの報告
   */
  playWeek: (summary?: MatchSummary) => WeekReport | null
  /** キャリア: 主人公の代表戦を行い（観戦した結果か自動）、自クラブの試合が残っていなければ週を進める */
  playNational: (summary?: MatchSummary) => WeekReport | null
  error: GameError | null
  /** エラーを記録して、ゲームを直前のセーブに戻す（中途半端に書き換わった状態で続けないように）。restore=false なら戻さない */
  fail: (where: string, e: unknown, restore?: boolean) => void
  clearError: () => void
}

export function slotMeta(state: GameState) {
  if (state.mode === 'career' && state.career) {
    const p = state.players[state.career.playerId]
    const club = p.clubId >= 0 ? state.clubs[p.clubId] : undefined
    const comp = club ? state.competitions.find((c) => c.id === club.leagueId) : undefined
    return {
      clubName: `${p.name}${club ? `（${club.name}）` : ''}`,
      season: state.season,
      week: state.week,
      dateLabel: dateLabel(state.startYear, state.season, state.week),
      leagueName: comp?.name ?? '入団前',
      rank: club && comp ? Math.max(1, rankOf(comp, club.id)) : 0,
      budget: state.career.money,
      mode: 'career' as const,
    }
  }
  const club = state.clubs[state.playerClubId]
  const comp = state.competitions.find((c) => c.id === club.leagueId)!
  return {
    clubName: club.name,
    season: state.season,
    week: state.week,
    dateLabel: dateLabel(state.startYear, state.season, state.week),
    leagueName: comp.name,
    rank: Math.max(1, rankOf(comp, club.id)),
    budget: club.budget,
    mode: 'club' as const,
  }
}

/**
 * 自動保存をまとめる（M25 のあと「動作を軽く」）。セーブは 10 MB を超える JSON なので、操作のたびに作ると画面が止まる。
 * 操作が落ち着いてから 1 回だけ保存する（SAVE_DELAY）。アプリが裏に回る・閉じるとき、セーブの一覧を見るとき、
 * 別のセーブを読むときはすぐ保存する（flushSave）。エラーで直前のセーブに戻すときは捨てる（cancelSave）
 */
const SAVE_DELAY = 800
let pending: { timer: ReturnType<typeof setTimeout>; state: GameState; slotId: number } | null = null

function scheduleSave(state: GameState, slotId: number) {
  if (pending) clearTimeout(pending.timer)
  pending = { timer: setTimeout(() => void flushSave(), SAVE_DELAY), state, slotId }
}

/** まだ書いていない自動保存をすぐ書く */
export function flushSave(): Promise<void> {
  if (!pending) return Promise.resolve()
  const p = pending
  pending = null
  clearTimeout(p.timer)
  return saveGame(p.slotId, p.state, slotMeta(p.state)).catch((e) => console.error('[自動保存]', e))
}

function cancelSave() {
  if (pending) clearTimeout(pending.timer)
  pending = null
}

if (typeof document !== 'undefined') {
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') void flushSave()
  })
  window.addEventListener('pagehide', () => void flushSave())
}

export const useGame = create<GameStore>((set, get) => ({
  state: null,
  version: 0,
  slotId: 1,
  busy: false,
  error: null,
  fail: (where, e, restore = true) => {
    const err = e instanceof Error ? e : new Error(String(e))
    const st = get().state
    console.error(`[${where}]`, err)
    const stack = (err.stack ?? '').split('\n').slice(0, 8).join('\n')
    set({ error: { where, message: err.message, stack, season: st?.season ?? -1, week: st?.week ?? -1 } })
    // 中途半端に書き換わった状態は保存しない
    if (st && restore) {
      cancelSave()
      void get().load(get().slotId)
    }
  },
  clearError: () => set({ error: null }),
  newGame: (opts, slotId) => {
    const state = createNewGame(opts)
    set({ state, slotId, version: get().version + 1 })
    void get().persist().then(flushSave)
    return state
  },
  newCareer: (opts, slotId) => {
    const state = createCareerGame(opts)
    set({ state, slotId, version: get().version + 1 })
    void get().persist().then(flushSave)
    return state
  },
  load: async (slotId) => {
    // いまのゲームのまだ書いていない保存を先に（エラーで戻すときは fail で捨ててある）
    await flushSave()
    const state = await loadGame(slotId)
    if (!state) return false
    set({ state, slotId, version: get().version + 1 })
    return true
  },
  bump: () => set((s) => ({ version: s.version + 1 })),
  mutate: (fn) => {
    const { state } = get()
    if (!state) return
    try {
      fn(state)
      // 入団・移籍で顔ぶれが変わったら写真を割り当てる
      assignPhotos(state)
    } catch (e) {
      get().fail('画面の操作', e)
      return
    }
    get().bump()
    void get().persist()
  },
  persist: async () => {
    const { state, slotId } = get()
    if (!state) return
    scheduleSave(state, slotId)
  },
  close: () => {
    void flushSave()
    set({ state: null })
  },

  advance: (mode) => {
    try {
      return advanceImpl(get, mode)
    } catch (e) {
      get().fail('週を進める', e)
      return { needMatch: false, reports: [], seasonEnded: false, stopText: 'エラーが起きました' }
    }
  },

  progress: null,
  advanceAsync: async (mode) => {
    const out: AdvanceOutcome = { needMatch: false, reports: [], seasonEnded: false }
    const total = mode === 'week' ? 1 : mode === 'month' ? 4 : 48
    set({ progress: { done: 0, total } })
    try {
      await nextPaint()
      for (const done of advanceSteps(get, mode, out)) {
        set({ progress: { done, total } })
        await nextPaint()
      }
    } catch (e) {
      set({ progress: null })
      get().fail('週を進める', e)
      return { needMatch: false, reports: [], seasonEnded: false, stopText: 'エラーが起きました' }
    }
    set({ progress: null })
    get().bump()
    void get().persist()
    return out
  },

  playWeek: (summary) => {
    try {
      return playWeekImpl(get, summary)
    } catch (e) {
      get().fail('試合の結果を反映する', e)
      return null
    }
  },

  playNational: (summary) => {
    try {
      const { state } = get()
      if (!state) return null
      playCareerNational(state, summary)
      let r: WeekReport | null = null
      if (!playerFixtureThisWeek(state)) {
        r = advanceWeek(state)
        if (r.seasonEnded) void saveSnapshot(get().slotId, state)
      }
      get().bump()
      void get().persist()
      return r
    } catch (e) {
      get().fail('代表戦の結果を反映する', e)
      return null
    }
  },
}))

// 画面のスタックの「戻る」で、戻り先がないときにゲーム中ならホームへ
setHasGameProbe(() => !!useGame.getState().state)

type Get = () => GameStore

/** 週を 1 つずつ進める（1 週ごとに止まる。advanceImpl はまとめて、advanceAsync は画面に進み具合を出しながら） */
function* advanceSteps(get: Get, mode: AdvanceMode, out: AdvanceOutcome): Generator<number, void, void> {
  const { state } = get()
  if (!state) return
  const maxWeeks = mode === 'week' ? 1 : mode === 'month' ? 4 : 48
  const stopsOn = stopFilter()
  for (let i = 0; i < maxWeeks; i++) {
    // 古いセーブでは今週の組み合わせがまだのことがある（決めてから、自クラブの試合があるか見る）
    drawWeek(state)
    if (playerFixtureThisWeek(state) && mode !== 'month') {
      out.needMatch = true
      break
    }
    if (careerNationalFixture(state) && mode !== 'month') {
      out.needNational = true
      break
    }
    const r = advanceWeek(state)
    out.reports.push(r)
    const major = r.stops.find((s) => s.major && stopsOn(s.kind))
    if (r.seasonEnded) {
      out.seasonEnded = true
      out.stopText = 'シーズンが終わりました'
      void saveSnapshot(get().slotId, state)
      break
    }
    if (major && mode !== 'week') {
      out.stopText = major.text
      break
    }
    if (i < maxWeeks - 1) yield i + 1
  }
}

function advanceImpl(get: Get, mode: AdvanceMode): AdvanceOutcome {
  const out: AdvanceOutcome = { needMatch: false, reports: [], seasonEnded: false }
  for (const _ of advanceSteps(get, mode, out)) void _
  get().bump()
  void get().persist()
  return out
}

/** 画面に描かせてから次へ（1 週ごとに進み具合を出す） */
const nextPaint = () => new Promise<void>((r) => requestAnimationFrame(() => setTimeout(r, 0)))

/** 設定で外した出来事では止まらない（設定にない種類はいつも止まる） */
function stopFilter(): (kind: StopKind) => boolean {
  const a = useSettings.getState().autoStop
  return (kind) => {
    if (kind === 'injury') return a.injury
    if (kind === 'offer') return a.offer
    if (kind === 'event' || kind === 'encounter') return a.event
    return true
  }
}

function playWeekImpl(get: Get, summary?: MatchSummary): WeekReport | null {
  {
    const { state } = get()
    if (!state) throw new Error('ゲームが始まっていない')
    playPlayerMatch(state, summary)
    let r: WeekReport | null = null
    // キャリアで今週まだ代表戦があれば、週は進めない（代表戦の画面へ）
    if (!playerFixtureThisWeek(state) && !careerNationalFixture(state)) {
      r = advanceWeek(state)
      if (r.seasonEnded) void saveSnapshot(get().slotId, state)
    }
    get().bump()
    void get().persist()
    return r
  }
}

/** 画面用: state を必ず返す（ゲーム中の画面だけで使う） */
export function useGameState(): GameState {
  const state = useGame((s) => s.state)
  useGame((s) => s.version)
  if (!state) throw new Error('ゲームが始まっていない')
  return state
}
