const C = [
  ['#c8102e', '#ffffff'],
  ['#1d428a', '#ffffff'],
  ['#111827', '#f5c542'],
  ['#047857', '#ffffff'],
  ['#6b21a8', '#f8fafc'],
  ['#f97316', '#111827'],
  ['#0ea5e9', '#ffffff'],
  ['#facc15', '#1e3a8a'],
  ['#7f1d1d', '#93c5fd'],
  ['#ffffff', '#111827'],
  ['#be123c', '#1e3a8a'],
  ['#15803d', '#facc15'],
] as const

function foreign(list: [string, string, number][]): ClubDef[] {
  return list.map(([name, short, rep], i) => [name, short, C[i % C.length][0], C[i % C.length][1], rep])
}

