/** 新クラブのホームタウン候補（人口は万人。発展度・観客の上限に効く） */
export interface HometownDef {
  city: string
  pref: string
  population: number
  /** 地元企業の多さ（スポンサー収入の基準） */
  economy: number
  /** サッカー熱（観客動員の基準） */
  passion: number
  /** 街の特色（M19） */
  trait: TownTrait
}

