/**
 * 合宿（キャンプ）。プレシーズン（8月）とウインターブレイク（1月）に 1〜2 週。
 * 成長が伸び、連携が深まる（M5）。海外の合宿では有名な選手・スタッフと出会うことがある。
 */
import type { Rng } from '../core/prng'
import { absWeekOf, phaseOfWeek } from '../core/calendar'
import { CAMP_PLACES, type CampPlace } from '../data/training'
import type { Club } from '../models/club'
import type { GameState } from '../models/game'
import { STAR_PLAYERS, STAR_STAFF } from '../data/cast'
import { bizLevel } from '../economy/business'

/** 今から合宿を組めるか（プレシーズンかウインターブレイクで、まだ組んでいない） */
export function canPlanCamp(state: GameState, club: Club): boolean {
  const ph = phaseOfWeek(state.week)
  if (ph !== 'preseason' && ph !== 'winter') return false
  const now = absWeekOf(state.season, state.week)
  return !club.camp || club.camp.startAbsWeek + club.camp.weeks <= now - 8
}

export function campCost(state: GameState, club: Club, place: CampPlace, weeks: number): number {
  const lodge = place.abroad ? 1 : 1 - club.facilities.lodge * 0.1
  // クラブホテルがあると泊まりの費用が安くなる
  const hotel = 1 - bizLevel(state, club, 'hotel') * 0.08
  return Math.round(place.costPerWeek * weeks * lodge * hotel)
}

export function planCamp(state: GameState, club: Club, placeId: string, weeks: number): boolean {
  const place = CAMP_PLACES.find((c) => c.id === placeId)
  if (!place || !canPlanCamp(state, club)) return false
  const cost = campCost(state, club, place, weeks)
  if (club.budget < cost) return false
  club.budget -= cost
  club.camp = { place: place.name, startAbsWeek: absWeekOf(state.season, state.week), weeks }
  const w = state.finance[state.finance.length - 1]
  if (w) w.other -= cost
  state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'club', mine: true, text: `${place.name}で ${weeks} 週間の合宿を行います（費用 ${cost.toLocaleString()} 万円）。` })
  return true
}

/** 合宿中の出会い（有名な選手・スタッフがクラブに興味を持つ）。週の処理で呼ぶ */
export function campEncounter(state: GameState, club: Club, rng: Rng): string | null {
  const now = absWeekOf(state.season, state.week)
  if (!club.camp || now < club.camp.startAbsWeek || now >= club.camp.startAbsWeek + club.camp.weeks) return null
  const place = CAMP_PLACES.find((c) => c.name === club.camp!.place)
  if (!place || !rng.chance(place.encounter)) return null
  // フリーの固有キャラ（スタッフ優先）
  const freeStaff = Object.values(state.staff).filter((s) => s.starId && s.clubId < 0 && s.role !== 'owner')
  if (freeStaff.length) {
    const s = rng.pick(freeStaff)
    const cast = STAR_STAFF.find((c) => c.id === s.starId)
    const text = `合宿先の${place.name}で ${s.name}（${cast?.role ?? ''}）と出会いました。クラブに興味があるようです。スタッフ画面から声をかけられます。`
    state.news.push({ absWeek: now, category: 'staff', mine: true, text })
    return text
  }
  const freeStars = Object.values(state.players).filter((p) => p.starId && p.clubId < 0 && !p.retired)
  if (freeStars.length) {
    const p = rng.pick(freeStars)
    const cast = STAR_PLAYERS.find((c) => c.id === p.starId)
    const text = `合宿先の${place.name}で ${p.name}（${cast?.line ?? ''}）と出会いました。移籍画面からオファーを出せます。`
    state.news.push({ absWeek: now, category: 'transfer', mine: true, text })
    return text
  }
  return null
}
