/**
 * 昇格プレーオフ（NPL2・NPL3 の 3〜6 位）。準決勝 3位-6位・4位-5位、決勝は上位のホーム。1 試合勝負（延長・PK あり）。
 */
import { absWeekOf } from '../core/calendar'
import type { Competition, Fixture } from '../models/competition'
import { allocId, type GameState } from '../models/game'

export const PLAYOFF_SEMI_WEEK = 41
export const PLAYOFF_FINAL_WEEK = 43

export function playoffId(leagueId: string): string {
  return `${leagueId}PO`
}

export function createPlayoffs(state: GameState) {
  for (const league of state.competitions.filter((c) => c.kind === 'league' && c.playoff)) {
    const id = playoffId(league.id)
    if (state.competitions.some((c) => c.id === id && c.season === state.season)) continue
    state.competitions = state.competitions.filter((c) => c.id !== id)
    const seeds = league.table.slice(2, 6).map((r) => r.clubId)
    if (seeds.length < 4) continue
    const comp: Competition = {
      id,
      kind: 'cup',
      name: `${league.name} 昇格プレーオフ`,
      short: `${league.short}PO`,
      country: league.country,
      tier: league.tier,
      season: state.season,
      clubIds: seeds,
      fixtures: [],
      table: [],
      promotion: 1,
      relegation: 0,
      playoff: false,
      simulated: 'full',
    }
    const mk = (round: number, home: number, away: number, week: number): Fixture => ({ id: allocId(state, 'fixture'), compId: id, round, absWeek: absWeekOf(state.season, week), slot: 'weekend', home, away })
    comp.fixtures.push(mk(0, seeds[0], seeds[3], PLAYOFF_SEMI_WEEK), mk(0, seeds[1], seeds[2], PLAYOFF_SEMI_WEEK))
    state.competitions.push(comp)
  }
}

/** 勝者（PK 戦を含む） */
export function winnerOf(f: Fixture): number | null {
  const r = f.result
  if (!r) return null
  if (r.hg !== r.ag) return r.hg > r.ag ? f.home : f.away
  if (r.pens) return r.pens[0] > r.pens[1] ? f.home : f.away
  return f.home
}

export function createPlayoffFinals(state: GameState) {
  for (const comp of state.competitions.filter((c) => c.id.endsWith('PO'))) {
    if (comp.fixtures.some((f) => f.round === 1)) continue
    const semis = comp.fixtures.filter((f) => f.round === 0)
    const w = semis.map(winnerOf)
    if (w.some((x) => x === null)) continue
    // 上位シードがホーム
    const [a, b] = (w as number[]).sort((x, y) => comp.clubIds.indexOf(x) - comp.clubIds.indexOf(y))
    comp.fixtures.push({ id: allocId(state, 'fixture'), compId: comp.id, round: 1, absWeek: absWeekOf(state.season, PLAYOFF_FINAL_WEEK), slot: 'weekend', home: a, away: b })
  }
}

export function playoffWinner(state: GameState, leagueId: string): number | null {
  const comp = state.competitions.find((c) => c.id === playoffId(leagueId))
  const final = comp?.fixtures.find((f) => f.round === 1)
  return final ? winnerOf(final) : null
}
