/**
 * スタッフの効果。
 * - ヘッドコーチ: 全体の成長、各コーチ: 担当の能力グループの成長
 * - フィジカルコーチ: 疲労の回復、トレーナー: ケガの回復と予防
 * - 監督: 能力（試合の実効能力を少し上げる）と、フォーメーションの熟練度
 */
import type { AttrGroup } from '../data/attributes'
import type { Club } from '../models/club'
import type { GameState } from '../models/game'
import type { Staff, StaffRole } from '../models/staff'

export function staffOf(state: GameState, club: Club, role: StaffRole): Staff | undefined {
  for (const id of club.staff) {
    const s = state.staff[id]
    if (s && s.role === role) return s
  }
  return undefined
}

const lvl = (s: Staff | undefined, base = 0.9) => (s ? 0.9 + s.ability / 500 + (base - 0.9) : base)

export interface CoachEffects {
  /** 全体の成長倍率 */
  all: number
  /** 能力グループごとの倍率 */
  group: Record<AttrGroup, number>
  /** 疲労回復の上乗せ（週） */
  recover: number
  /** ケガの回復・予防（0-1） */
  medical: number
}

export function coachEffects(state: GameState, club: Club): CoachEffects {
  const head = staffOf(state, club, 'headCoach')
  const g = (role: StaffRole) => {
    const s = staffOf(state, club, role)
    return s ? 0.94 + s.ability / 400 : 0.94
  }
  const phys = staffOf(state, club, 'physicalCoach')
  const physio = staffOf(state, club, 'physio')
  return {
    all: lvl(head),
    group: { tech: g('attackCoach'), def: g('defenseCoach'), body: g('physicalCoach'), mind: g('mentalCoach'), gk: g('gkCoach') },
    recover: phys ? phys.ability / 25 : 0,
    medical: physio ? physio.ability / 100 : 0,
  }
}

/** 監督のフォーメーション熟練度（0-100、監督がいなければ 50） */
export function formationFamiliarity(state: GameState, club: Club, formation: string): number {
  const m = staffOf(state, club, 'manager')
  return m?.formations?.[formation] ?? 50
}

export function managerAbility(state: GameState, club: Club): number {
  return staffOf(state, club, 'manager')?.ability ?? 40
}
