/**
 * クラブのイベント。週にときどき起き、選択肢で結果が変わる。
 * {p} = 対象の選手、{c} = クラブ名、{t} = ホームタウン。
 * business の付いたイベントは、その事業が営業しているときだけ起きる（ブーム・トラブル）。
 */
import type { BusinessId } from '../models/club'

export interface EventEffect {
  budget?: number
  popularity?: number
  fans?: number
  /** チーム全体のやる気 */
  morale?: number
  /** 対象選手のやる気 */
  playerMorale?: number
  /** チーム全体の調子 */
  condition?: number
  /** 対象選手の調子 */
  playerCondition?: number
  /** 対象選手の疲労 */
  playerFatigue?: number
  /** 街の発展度 */
  development?: number
  /** チーム全体の連携 */
  chem?: number
  /** イベントの事業の売上を一定期間 mul 倍にする */
  bizBoost?: { mul: number; weeks: number; label: string }
  /** 海外アカデミーの特待生（将来性の上乗せ） */
  prospect?: number
}

export interface EventOption {
  label: string
  effect: EventEffect
  result: string
}

export type EventSpeaker = 'secretary' | 'owner' | 'player'

export interface ClubEventDef {
  id: string
  title: string
  body: string
  speaker: EventSpeaker
  /** 対象の選手を選ぶ（若手・主力など） */
  target?: 'any' | 'young' | 'star' | 'bench'
  weight: number
  options: EventOption[]
  /** この事業を営業しているときだけ起きる */
  business?: BusinessId
}

