/**
 * サポーター数と人気。勝つほど増え、負けが続くと減る。広報室・街の熱気・リーグの格で増え方が変わる。
 * サポーター数の上限は、ホームタウンの人口とリーグの格から。
 */
import type { Club } from '../models/club'
import type { GameState } from '../models/game'
import { hasTrait } from './town'
import { ticketLevel } from '../economy/sales'

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

function tierOf(state: GameState, club: Club): number {
  return state.competitions.find((c) => c.id === club.leagueId)?.tier ?? 3
}

/** 人気の上限（リーグの格で頭打ち） */
export function popularityCap(tier: number): number {
  return tier === 1 ? 100 : tier === 2 ? 70 : 45
}

/** サポーター数の上限 */
export function fansCap(state: GameState, club: Club): number {
  const tier = tierOf(state, club)
  const pop = club.isPlayer ? state.hometown.population : 60
  return Math.round(pop * 10000 * (club.leagueId === 'WL' ? 0.15 : tier === 1 ? 0.12 : tier === 2 ? 0.07 : 0.04) + club.rep * 400)
}

/** 試合の結果による変化（自クラブのみ）。derby はダービーの強さ（0〜1。増減が最大で 2 倍になる） */
export function afterMatch(state: GameState, club: Club, goalsFor: number, goalsAgainst: number, home: boolean, derby = 0) {
  const tier = tierOf(state, club)
  const pr = club.facilities.pr
  const passion = club.isPlayer ? state.hometown.passion / 50 : 1
  const win = goalsFor > goalsAgainst
  const draw = goalsFor === goalsAgainst
  // 城下町（M19）: 負けても人気とサポーターが下がりにくい。サッカーどころ: サポーターが増えやすい
  const castle = hasTrait(state, 'castle', club)
  const soccer = hasTrait(state, 'soccer', club) ? 1.2 : 1
  const dPop = ((win ? 0.6 : draw ? 0.1 : -0.35 * (castle ? 0.5 : 1)) * (1 + pr * 0.12) + (goalsFor >= 3 ? 0.2 : 0)) * (1 + derby)
  // チケットの値段（M19）: 安いと人気が少し上がり、高いと少し下がる（ホームの試合）
  const price = home && club.isPlayer ? ticketLevel(club).pop : 0
  club.popularity = clamp(club.popularity + dPop + price, 1, popularityCap(tier))
  const growth = (win ? 0.006 : draw ? 0.0015 : -0.002 * (castle ? 0.5 : 1)) * passion * (home ? 1.2 : 0.8) * (1 + derby)
  const add = (club.fans * growth + club.popularity * (1 + pr * 0.25) * passion * (win ? 3 : 1)) * (growth > 0 ? soccer : 1)
  club.fans = Math.round(clamp(club.fans + add, 300, fansCap(state, club)))
}

/** シーズン末（昇格・優勝で大きく増える） */
export function afterSeason(state: GameState, club: Club, rank: number, promoted: boolean, relegated: boolean) {
  if (promoted) {
    club.popularity = clamp(club.popularity + 8, 1, 100)
    club.fans = Math.round(club.fans * 1.18)
  }
  if (rank === 1) {
    club.popularity = clamp(club.popularity + 5, 1, 100)
    club.fans = Math.round(club.fans * 1.1)
  }
  if (relegated) {
    club.popularity = clamp(club.popularity - 6, 1, 100)
    club.fans = Math.round(club.fans * 0.9)
  }
  club.fans = Math.round(clamp(club.fans, 300, fansCap(state, club)))
  // 街の発展（クラブの成績で少しずつ）
  if (club.isPlayer) {
    const h = state.hometown
    h.development = clamp(h.development + (promoted ? 4 : 0) + (rank <= 3 ? 2 : rank <= 9 ? 1 : 0) + club.facilities.pr * 0.3, 0, 100)
  }
}
