/** クラブ。 */
import type { Position } from '../data/positions'
import type { Nation } from '../data/nations'
import type { MerchLineId } from '../economy/sales'
import type { AcademyPolicy } from '../data/academies'

export interface EmblemSpec {
  shape: number
  charge: number
  pattern: number
}

export type KitPattern = 'solid' | 'stripes' | 'hoops' | 'sash' | 'halves'

export type FacilityId = 'training' | 'medical' | 'dorm' | 'analysis' | 'youth' | 'pr' | 'lodge' | 'scoutOffice'

export const FACILITY_IDS: FacilityId[] = ['training', 'medical', 'dorm', 'analysis', 'youth', 'pr', 'lodge', 'scoutOffice']

export const FACILITY_LABEL: Record<FacilityId, string> = {
  training: '練習場',
  medical: 'メディカルセンター',
  dorm: '選手寮',
  analysis: '分析室',
  youth: 'ユースアカデミー',
  pr: '広報室',
  lodge: '合宿所',
  scoutOffice: 'スカウト事務所',
}

export interface Stadium {
  name: string
  capacity: number
  /** 1-5（屋根・照明・座席・ピッチの総合） */
  grade: number
  build?: { doneAbsWeek: number; addCapacity: number; addGrade: number; label: string }
}

/** 戦術（試合エンジンが読む） */
export interface Tactics {
  formation: string
  /** -2（超守備的）〜 +2（超攻撃的） */
  mentality: number
  /** 以下 0-100 */
  tempo: number
  width: number
  lineHeight: number
  pressing: number
  /** 攻撃の主な方向 */
  focus: 'balanced' | 'left' | 'right' | 'center'
  offsideTrap: boolean
  counter: boolean
}

/** 先発（フォーメーションのスロット順の選手 id）と控え */
export interface Lineup {
  starters: number[]
  bench: number[]
  captain?: number
  penaltyTaker?: number
  freeKickTaker?: number
  cornerTaker?: number
  /** 自分で組んだ（false なら試合前に自動で組み直す） */
  manual: boolean
}

/** 練習の計画 */
export type TrainingIntensity = 0 | 1 | 2

export interface TrainingPlan {
  /** 0 = 軽め、1 = 普通、2 = 厳しめ */
  intensity: TrainingIntensity
  /** メニュー id → 配分（0-5） */
  weights: Record<string, number>
  /** 個別練習: 選手 id → メニュー id、またはコンバート先のポジション */
  individual: Record<number, { menu?: string; convert?: Position }>
}

/** 建設中の工事 */
export interface Construction {
  kind: 'facility' | 'stadium'
  /** 施設 id、またはスタジアムの工事の種類 */
  target: FacilityId | 'seats' | 'grade'
  label: string
  doneAbsWeek: number
  cost: number
  /** 完成時の変化 */
  amount: number
}

export type SponsorSlot = 'shirt' | 'sleeve' | 'stadium' | 'global'

export interface SponsorContract {
  slot: SponsorSlot
  company: string
  /** 年額（万円） */
  annual: number
  /** このシーズンの終わりまで */
  until: number
  /** 成績のボーナス */
  bonus?: { kind: 'rank' | 'promotion'; value: number; amount: number }
}

export type BusinessId = 'cafe' | 'school' | 'clinic' | 'hotel' | 'media' | 'esports' | 'realestate' | 'academy'

/** 事業の方針: 地域密着（薄利で人気が上がる）・標準・利益重視（儲かるが人気が少し下がる） */
export type BusinessPolicy = 'local' | 'normal' | 'profit'

/** クラブが持つ事業（サイドビジネス） */
export interface Business {
  id: BusinessId
  /** 1-5（準備中・拡大中は pending） */
  level: number
  /** この週から営業する（開業の準備中はそれまで売上なし） */
  openAbsWeek: number
  /** 拡大の工事中（完成の週にレベルが上がる） */
  pending?: { level: number; doneAbsWeek: number }
  policy: BusinessPolicy
  /** これまでに注ぎ込んだ額（売却額の基準） */
  invested: number
  /** 今シーズンの売上・利益 */
  sales: number
  profit: number
  /** 開業からの利益の合計 */
  total: number
  history: { season: number; sales: number; profit: number }[]
  /** ブーム・トラブルで売上が変わっている期間 */
  boost?: { mul: number; untilAbsWeek: number; label: string }
  /** 海外アカデミーの国 */
  nation?: Nation
}

/** 合宿の予定 */
export interface CampPlan {
  place: string
  startAbsWeek: number
  weeks: number
}

export interface Club {
  id: number
  name: string
  short: string
  country: string
  city: string
  /** ワールドリーグのクラブが戻るリーグ（M24） */
  homeLeague?: string
  colors: { primary: string; secondary: string }
  emblem: EmblemSpec
  kit: KitPattern
  /** クラブ格 0-100 */
  rep: number
  /** 所属リーグの大会 id */
  leagueId: string
  /** 資金（万円） */
  budget: number
  facilities: Record<FacilityId, number>
  stadium: Stadium
  /** 最後に全体ミーティングをした週（M19） */
  lastTeamMeeting?: number
  /** 今季の海外遠征（M19。シーズンに 1 回） */
  tour?: { season: number; id: string }
  /** チケットとグッズ（M19。自クラブだけ）。ticket は値段の段（0〜4、2 がふつう） */
  sales?: { ticket: number; seasonTickets: boolean; sold?: { season: number; count: number; revenue: number }; merch?: Partial<Record<MerchLineId, number>>; globalStore?: number }
  /** 海外のファン（M24 の 2 回目。ワールドリーグにいると増える。club/worldClass.ts） */
  worldFans?: number
  /** サポーター数（人） */
  fans: number
  /** 人気 0-100 */
  popularity: number
  tactics: Tactics
  lineup: Lineup
  /** スタッフ id（役割ごと） */
  staff: number[]
  isPlayer: boolean
  /** 前シーズンの最終順位（0 = 未定） */
  lastRank: number
  training?: TrainingPlan
  construction?: Construction[]
  sponsors?: SponsorContract[]
  camp?: CampPlan
  /** サイドビジネス（自クラブだけ） */
  businesses?: Business[]
  /** 海外アカデミー（M25。自クラブだけ。club/academy.ts） */
  academies?: Academy[]
}

/** 海外アカデミー（M25）: 国ごとに 1 つ。Lv1〜5 */
export interface Academy {
  nation: Nation
  level: number
  /** この週から動く（開業の準備中はそれまで子どもが入らない） */
  openAbsWeek: number
  /** 拡大の工事中（完成の週にレベルが上がる） */
  pending?: { level: number; doneAbsWeek: number }
  policy: AcademyPolicy
  /** これまでに注ぎ込んだ額（閉じるときの払い戻しの基準） */
  invested: number
  /** ここからユースに入った子の数 */
  produced: number
}
