/**
 * サイドビジネス: 開業・拡大・売却・方針、毎週の損益、景気の波、シーズン末の決算と事業ごとの効果。
 * 自クラブだけが持つ。乱数は週ごと（weekRng）・シーズンごとのシードで、ほかの処理の乱数の並びを変えない。
 */
import { absWeekOf, WEEKS_PER_SEASON } from '../core/calendar'
import { createRng, hashSeed, weekRng, type Rng } from '../core/prng'
import { BUSINESS_BY_ID, ESPORTS_PRIZE, FIXED_MUL, MAX_BUSINESS_LEVEL, POLICY_SALES, SALES_MUL, UPGRADE_MUL, type DemandKind } from '../data/business'
import type { Business, BusinessId, BusinessPolicy, Club } from '../models/club'
import type { GameState, SeasonSummary } from '../models/game'
import { fansCap, popularityCap } from '../club/fans'
import { recordCost } from './facilities'
import { academyTopLevel } from '../club/academy'

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

function tierOf(state: GameState, club: Club): number {
  return state.competitions.find((c) => c.id === club.leagueId)?.tier ?? 3
}

function now(state: GameState): number {
  return absWeekOf(state.season, state.week)
}

export function findBusiness(club: Club, id: BusinessId): Business | undefined {
  return club.businesses?.find((b) => b.id === id)
}

/** 営業中の事業のレベル（持っていない・開業前なら 0）。事業ごとの効果に使う */
export function bizLevel(state: GameState, club: Club, id: BusinessId): number {
  // 海外アカデミーは M25 からユースアカデミーの画面（club/academy.ts）
  if (id === 'academy') return academyTopLevel(state, club)
  const b = findBusiness(club, id)
  return b && now(state) >= b.openAbsWeek ? b.level : 0
}

/** 大陸大会・世界大会に出ているか（ホテルの客が増える） */
function inContinental(state: GameState, club: Club): boolean {
  return state.competitions.some((c) => (c.id === 'ACC' || c.id === 'WCC') && c.clubIds.includes(club.id))
}

/** 需要（1 がふつうのクラブ。大きくなるほど伸びが鈍る） */
export function demandOf(state: GameState, club: Club, kind: DemandKind): number {
  const fans = (club.fans / 30000) ** 0.8
  const pop = club.popularity / 50
  const town = state.hometown.population / 30
  const econ = state.hometown.economy / 50
  const dev = state.hometown.development / 50
  let d: number
  switch (kind) {
    case 'fans':
      d = 0.6 * fans + 0.4 * pop
      break
    case 'town':
      d = 0.7 * town + 0.3 * pop
      break
    case 'health':
      d = 0.5 * town + 0.5 * econ
      break
    case 'tourism':
      d = (0.45 * pop + 0.35 * fans + 0.2 * town) * (inContinental(state, club) ? 1.3 : 1)
      break
    case 'media':
      d = pop ** 1.5
      break
    case 'esports':
      d = pop
      break
    case 'land':
      d = 0.5 * dev + 0.5 * econ
      break
    case 'rep':
      d = club.rep / 60
      break
  }
  if (d > 1) d = 1 + (d - 1) * 0.6
  return clamp(d, 0.1, 3)
}

/** 景気（0.75〜1.3） */
export function cycleOf(state: GameState): number {
  return state.bizCycle ?? 1
}

export function cycleLabel(v: number): string {
  return v >= 1.12 ? '好景気' : v >= 1.04 ? 'やや好調' : v > 0.96 ? 'ふつう' : v > 0.88 ? 'やや不調' : '不景気'
}

export interface BizEstimate {
  sales: number
  cost: number
  profit: number
}

/** 1 シーズンの見込み（ぶれ・ブームなし。今の景気で） */
export function estimate(state: GameState, club: Club, id: BusinessId, level: number, policy: BusinessPolicy = 'normal'): BizEstimate {
  const def = BUSINESS_BY_ID[id]
  const sales = def.sales * SALES_MUL[level] * demandOf(state, club, def.demand) * POLICY_SALES[policy] * cycleOf(state) ** def.cycle
  const cost = def.fixed * FIXED_MUL[level] + sales * def.varRatio
  return { sales: Math.round(sales), cost: Math.round(cost), profit: Math.round(sales - cost) }
}

export function canOpen(state: GameState, club: Club, id: BusinessId): { ok: boolean; reason?: string } {
  const def = BUSINESS_BY_ID[id]
  if (findBusiness(club, id)) return { ok: false, reason: '開業済み' }
  const u = def.unlock
  if (u) {
    if ((u.popularity !== undefined && club.popularity < u.popularity) || (u.tier !== undefined && tierOf(state, club) > u.tier) || (u.rep !== undefined && club.rep < u.rep)) return { ok: false, reason: `条件: ${u.label}` }
  }
  if (club.budget < def.openCost) return { ok: false, reason: '資金が足りない' }
  return { ok: true }
}

export function openBusiness(state: GameState, club: Club, id: BusinessId): boolean {
  if (!canOpen(state, club, id).ok) return false
  const def = BUSINESS_BY_ID[id]
  club.budget -= def.openCost
  recordCost(state, club, def.openCost)
  const b: Business = { id, level: 1, openAbsWeek: now(state) + def.weeks, policy: 'normal', invested: def.openCost, sales: 0, profit: 0, total: 0, history: [] }
  ;(club.businesses ??= []).push(b)
  state.news.push({ absWeek: now(state), category: 'club', mine: true, text: `${def.name}の開業準備を始めました（${def.weeks} 週後に開業）。` })
  return true
}

/** そのレベルへ拡大する費用 */
export function upgradeCost(id: BusinessId, toLevel: number): number {
  return Math.round(BUSINESS_BY_ID[id].openCost * (UPGRADE_MUL[toLevel] ?? 0))
}

export function canUpgrade(state: GameState, club: Club, id: BusinessId): { ok: boolean; reason?: string } {
  const b = findBusiness(club, id)
  if (!b) return { ok: false, reason: '未開業' }
  if (b.level >= MAX_BUSINESS_LEVEL) return { ok: false, reason: '最大レベル' }
  if (b.pending) return { ok: false, reason: '拡大の工事中' }
  if (now(state) < b.openAbsWeek) return { ok: false, reason: '開業の準備中' }
  if (club.budget < upgradeCost(id, b.level + 1)) return { ok: false, reason: '資金が足りない' }
  return { ok: true }
}

export function upgradeBusiness(state: GameState, club: Club, id: BusinessId): boolean {
  if (!canUpgrade(state, club, id).ok) return false
  const b = findBusiness(club, id)!
  const cost = upgradeCost(id, b.level + 1)
  club.budget -= cost
  recordCost(state, club, cost)
  b.invested += cost
  b.pending = { level: b.level + 1, doneAbsWeek: now(state) + Math.ceil(BUSINESS_BY_ID[id].weeks / 2) }
  return true
}

/** 売却額: つぎ込んだ額の半分強＋前のシーズンの利益の 1.5 倍 */
export function sellValue(b: Business): number {
  const last = b.history[b.history.length - 1]?.profit ?? b.profit
  return Math.round(b.invested * 0.55 + Math.max(0, last) * 1.5)
}

export function sellBusiness(state: GameState, club: Club, id: BusinessId): number {
  const b = findBusiness(club, id)
  if (!b) return 0
  const v = sellValue(b)
  club.budget += v
  club.businesses = (club.businesses ?? []).filter((x) => x.id !== id)
  state.news.push({ absWeek: now(state), category: 'club', mine: true, text: `${BUSINESS_BY_ID[id].name}を ${v.toLocaleString()} 万円で売却しました。` })
  return v
}

export function setPolicy(club: Club, id: BusinessId, policy: BusinessPolicy) {
  const b = findBusiness(club, id)
  if (b) b.policy = policy
}

/** 月の頭に景気が動く（ゆっくり 1 に戻る） */
function updateCycle(state: GameState, rng: Rng, absWeek: number) {
  if (state.week % 4 !== 0) return
  const before = cycleOf(state)
  const v = clamp(before + rng.normal(0, 0.05) + (1 - before) * 0.15, 0.75, 1.3)
  state.bizCycle = Math.round(v * 1000) / 1000
  if ((state.clubs[state.playerClubId].businesses ?? []).length && cycleLabel(v) !== cycleLabel(before))
    state.news.push({ absWeek, category: 'club', mine: false, text: `景気が「${cycleLabel(v)}」になりました。事業の売上に影響します。` })
}

/** 1 週間の事業の損益（自クラブ）。返り値は利益の合計（赤字ならマイナス） */
export function businessWeek(state: GameState, club: Club, absWeek: number, homeGame: boolean): number {
  const rng = weekRng(state.seed, absWeek, 0xb12)
  updateCycle(state, rng, absWeek)
  const list = club.businesses
  if (!list?.length) return 0
  const tier = tierOf(state, club)
  let net = 0
  for (const b of list) {
    const def = BUSINESS_BY_ID[b.id]
    if (b.pending && b.pending.doneAbsWeek <= absWeek) {
      b.level = b.pending.level
      b.pending = undefined
      state.news.push({ absWeek, category: 'club', mine: true, text: `${def.name}が Lv${b.level} に拡大しました！` })
    }
    if (absWeek < b.openAbsWeek) continue
    if (absWeek === b.openAbsWeek) state.news.push({ absWeek, category: 'club', mine: true, text: `${def.name}が開業しました！` })
    if (b.boost && b.boost.untilAbsWeek < absWeek) b.boost = undefined
    let sales = (estimate(state, club, b.id, b.level, b.policy).sales / WEEKS_PER_SEASON) * Math.max(0, 1 + rng.normal(0, def.vol))
    if (b.id === 'cafe') sales *= homeGame ? 1.6 : 0.7
    if (b.pending) sales *= 0.7
    if (b.boost) sales *= b.boost.mul
    sales = Math.round(sales)
    const profit = sales - Math.round((def.fixed * FIXED_MUL[b.level]) / WEEKS_PER_SEASON + sales * def.varRatio)
    b.sales += sales
    b.profit += profit
    b.total += profit
    net += profit
    if (b.policy === 'local') {
      club.popularity = Math.min(popularityCap(tier), club.popularity + 0.012 * b.level)
      club.fans = Math.min(fansCap(state, club), club.fans + 4 * b.level)
    } else if (b.policy === 'profit') club.popularity = Math.max(1, club.popularity - 0.01 * b.level)
  }
  return net
}

/** シーズン末: e スポーツの大会、事業ごとの効果、決算 */
export function businessSeasonEnd(state: GameState, club: Club, absWeek: number): SeasonSummary['business'] {
  const list = club.businesses
  if (!list?.length) return undefined
  const rng = createRng(hashSeed(state.seed, state.season, 0xb12e))
  const tier = tierOf(state, club)
  const h = state.hometown
  const last = state.finance[state.finance.length - 1]
  const out: NonNullable<SeasonSummary['business']> = []
  for (const b of list) {
    const lv = absWeek >= b.openAbsWeek ? b.level : 0
    if (lv > 0) {
      switch (b.id) {
        case 'esports': {
          const k = rng.weighted([0.03 + 0.035 * lv, 0.05 + 0.03 * lv, 0.12 + 0.03 * lv, Math.max(0.1, 0.8 - 0.095 * lv)])
          if (k < 3) {
            const prize = Math.round(ESPORTS_PRIZE[k] * (1 + 0.6 * (lv - 1)))
            b.sales += prize
            b.profit += prize
            b.total += prize
            club.budget += prize
            if (last) last.business = (last.business ?? 0) + prize
            club.popularity = Math.min(popularityCap(tier), club.popularity + [2, 1, 0.5][k])
            club.fans = Math.min(fansCap(state, club), club.fans + [800, 300, 100][k] * lv)
            state.news.push({ absWeek, category: 'club', mine: true, text: `eスポーツチームが大会で${['優勝', '準優勝', 'ベスト4'][k]}！ 賞金 ${prize.toLocaleString()} 万円` })
          }
          break
        }
        case 'school':
          club.fans = Math.min(fansCap(state, club), club.fans + 80 * lv)
          break
        case 'media':
          club.popularity = Math.min(popularityCap(tier), club.popularity + 0.5 * lv)
          break
        case 'realestate':
          h.population = Math.min(150, h.population + Math.max(1, Math.round(0.6 * lv)))
          h.economy = Math.min(100, h.economy + 0.5 * lv)
          h.development = Math.min(100, h.development + 1.5 * lv)
          state.news.push({ absWeek, category: 'club', mine: true, text: `駅前の再開発で${h.city}の街が育っています（人口 ${h.population} 万人）。` })
          break
      }
    }
    out.push({ id: b.id, sales: Math.round(b.sales), profit: Math.round(b.profit) })
    b.history.push({ season: state.season, sales: Math.round(b.sales), profit: Math.round(b.profit) })
    if (b.history.length > 10) b.history.splice(0, b.history.length - 10)
    b.sales = 0
    b.profit = 0
  }
  const total = out.reduce((s, x) => s + x.profit, 0)
  state.news.push({ absWeek, category: 'club', mine: true, text: `事業の決算: ${out.length} 事業で ${total >= 0 ? '+' : ''}${total.toLocaleString()} 万円` })
  return out
}

/** 事業のイベントの効果: 売上の倍率を一定期間かける */
export function boostBusiness(state: GameState, club: Club, id: BusinessId, mul: number, weeks: number, label: string) {
  const b = findBusiness(club, id)
  if (b) b.boost = { mul, untilAbsWeek: now(state) + weeks - 1, label }
}
