export interface GeneratedName {
  full: string
  /** 試合中の表示などに使う短い名前（日本人は姓、外国人はファミリーネーム） */
  short: string
}

/** 日本の姓と名の候補（キャリアの主人公の名前をランダムに決めるとき） */
export function jpNamePool(): { family: string[]; given: string[] } {
  return { family: BANK.JP.family, given: BANK.JP.given }
}

export function generateName(nation: Nation, rng: Rng): GeneratedName {
  const b = BANK[nation]
  const family = rng.pick(b.family)
  const given = rng.pick(b.given)
  if (b.familyFirst) return { full: nation === 'JP' ? `${family} ${given}` : `${family}・${given}`, short: family }
  return { full: `${given}・${family}`, short: family }
}

