/**
 * 移籍のおすすめ。スカウトが知っている範囲（推定の能力）だけで選ぶ。
 *   即戦力: 先発の弱いポジションを、今の先発より明らかに上回る選手
 *   将来性: 安く取れて、伸びしろのある若手
 *   フリー: 移籍金がいらない選手（移籍期間外でも獲得できる）
 * 予算（移籍金と年俸）と、本人が来てくれそうか（乗り気）で絞る。
 */
import { absWeekOf } from '../core/calendar'
import { formationOf } from '../data/formations'
import type { Position } from '../data/positions'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import { FOREIGN_BIG_GAIN, foreignRoster, isForeign, squadOf } from '../match/lineup'
import { ageOf, ratingAt, rawRating } from '../player/overall'
import { estimate, type Estimate } from '../scout/knowledge'
import { affordable, squadRanks, wageDemand, willingness, windowOpen } from './market'
import { clubAsk } from './negotiation'

export type RecommendKind = 'upgrade' | 'prospect' | 'free'

export interface Recommendation {
  player: Player
  kind: RecommendKind
  /** 補強するポジション（即戦力・フリー） */
  pos?: Position
  /** 推定で、今の先発をどれだけ上回るか */
  gain: number
  fee: number
  wage: number
  /** 乗り気（0-1） */
  will: number
  /** 移籍期間外なので今は交渉できない */
  waitWindow: boolean
  /** 外国籍（日本のクラブで外国人枠を使う） */
  foreign: boolean
}

export interface SquadNeed {
  pos: Position
  /** 今の先発（いなければ -1） */
  starter: number
  rating: number
}

/** 先発の各ポジションの評価（低い順） */
export function squadNeeds(state: GameState): SquadNeed[] {
  const me = state.clubs[state.playerClubId]
  const f = formationOf(me.tactics.formation)
  const out: SquadNeed[] = f.slots.map((s, i) => {
    const id = me.lineup.starters[i] ?? -1
    const p = state.players[id]
    return { pos: s.pos, starter: p ? id : -1, rating: p ? ratingAt(p, s.pos) : 0 }
  })
  return out.sort((a, b) => a.rating - b.rating)
}

/** チームの弱点（補強したいポジション）: 先発の平均より弱い（または空いている）ところと、いちばん弱い 3 つ。ポジションごとに一番弱い先発 */
export interface WeakSpots {
  /** ポジション → 今の先発の評価 */
  weak: Map<Position, number>
  /** ポジション → 今の先発（いなければ -1） */
  starter: Map<Position, number>
  teamAvg: number
}

export function weakSpots(state: GameState): WeakSpots {
  const needs = squadNeeds(state)
  const teamAvg = needs.reduce((s, n) => s + n.rating, 0) / Math.max(1, needs.length)
  const weak = new Map<Position, number>()
  const starter = new Map<Position, number>()
  const add = (n: SquadNeed) => {
    weak.set(n.pos, n.rating)
    starter.set(n.pos, n.starter)
  }
  for (const n of needs) if (n.rating < teamAvg - 0.5 && !weak.has(n.pos)) add(n)
  for (const n of needs.slice(0, 3)) if (!weak.has(n.pos)) add(n)
  return { weak, starter, teamAvg }
}

export interface Upgrade {
  pos: Position
  /** 推定で、今の先発をどれだけ上回るか */
  gain: number
  /** 今の先発の評価 → その選手の推定の評価 */
  from: number
  to: number
}

/** その選手が弱点を埋めるか（スカウトの推定で。3 以上上回るときだけ） */
export function upgradeOf(state: GameState, p: Player, spots: WeakSpots, e: Estimate = estimate(state, p)): Upgrade | null {
  let best: Upgrade | null = null
  for (const [pos, from] of spots.weak) {
    if (p.pos !== pos && (p.apt[pos] ?? 0) < 75) continue
    const to = rawRating(e.attr, pos) * (0.75 + (0.25 * (p.apt[pos] ?? 0)) / 100)
    const gain = to - from
    if (gain >= 3 && (!best || gain > best.gain)) best = { pos, gain, from, to }
  }
  return best
}

export function recommendSignings(state: GameState, limit = 24): Recommendation[] {
  const me = state.clubs[state.playerClubId]
  const now = absWeekOf(state.season, state.week)
  const open = windowOpen(state)
  const spots = weakSpots(state)
  const { weak, teamAvg } = spots
  const squadSize = squadOf(state, me.id).length

  const out: Recommendation[] = []
  const levelStars = Math.max(1, (teamAvg - 45) / 9)
  const ranks = squadRanks(state)
  const foreignFull = foreignRoster(state, me).full
  for (const id in state.players) {
    const p = state.players[id]
    if (p.retired || p.isYouth || p.loan || p.clubId === me.id) continue
    const age = ageOf(p, now)
    if (age > 33) continue
    // 安い条件から: 補強したいポジションに入れるか、若手か
    const fits = [...weak.keys()].filter((pos) => p.pos === pos || (p.apt[pos] ?? 0) >= 75)
    if (!fits.length && age > 21) continue
    const e = estimate(state, p)
    const best = upgradeOf(state, p, spots, e)
    const stars = (e.potLo + e.potHi) / 2
    const prospect = !best && age <= 21 && stars >= levelStars + 1 && squadSize < 30
    if (!best && !prospect) continue
    // お金と乗り気（重いので最後に）
    const fee = clubAsk(state, p, ranks)
    const wage = wageDemand(state, p, me)
    if (!affordable(me, fee, wage) || fee > me.budget * (prospect ? 0.3 : 0.8)) continue
    const will = willingness(state, p, me, 'regular')
    if (will < 0.3) continue
    const waitWindow = p.clubId >= 0 && !open
    // 外国人枠（日本のクラブ）: 在籍の外国籍が 5 人以上なら、外国籍は先発を大きく上回るときだけ
    const foreign = isForeign(p, me)
    if (foreign && foreignFull && !(best && best.gain >= FOREIGN_BIG_GAIN)) continue
    if (best) out.push({ player: p, kind: p.clubId < 0 ? 'free' : 'upgrade', pos: best.pos, gain: best.gain, fee, wage, will, waitWindow, foreign })
    else out.push({ player: p, kind: 'prospect', gain: (stars - levelStars) * 3, fee, wage, will, waitWindow, foreign })
  }
  // 並び: すぐ交渉できる → 補強の大きさ ÷ 費用（費用は年俸 2 年分を含める）
  // 外国籍は少し下げる（同じくらいなら日本人を先に）
  const value = (r: Recommendation) => ((r.gain + 2) / Math.sqrt(1 + (r.fee + r.wage * 2) / 1000)) * (r.foreign ? (foreignFull ? 0.6 : 0.85) : 1)
  out.sort((a, b) => Number(a.waitWindow) - Number(b.waitWindow) || value(b) - value(a))
  // 種類とポジションが偏らないように: 同じポジションの即戦力は 3 人まで、将来性は 6 人まで
  const perPos = new Map<string, number>()
  const picked: Recommendation[] = []
  for (const r of out) {
    const key = r.kind === 'prospect' ? 'prospect' : `pos:${r.pos}`
    const n = perPos.get(key) ?? 0
    if (n >= (r.kind === 'prospect' ? 6 : 3)) continue
    perPos.set(key, n + 1)
    picked.push(r)
    if (picked.length >= limit) break
  }
  return picked
}
