/**
 * 主人公のクラブの試合のあと: 評価点・得点・見せ場から、経験点・監督の評価・知名度・課題・体力を動かす。
 * results.ts の applyPlayerMatch から呼ぶ（キャリアのときだけ）。
 */
import type { Competition, Fixture } from '../models/competition'
import type { GameState } from '../models/game'
import type { MatchSummary } from '../match/live/types'
import { clamp, report } from './core'
import { gainExp } from './growth'
import { countObjectives } from './manager'
import { queueTalk } from './events'
import { matchExpMul } from './life'
import { lastGameCheck } from './retire'
import { easyGrowth } from './growth'

/** 大会の格（知名度の伸び方） */
function prestige(comp: Competition): number {
  if (comp.id === 'WCC') return 3
  if (comp.kind === 'continental') return 2
  if (comp.kind === 'cup') return 1.2
  return comp.country === 'JP' ? (comp.tier === 1 ? 1.4 : comp.tier === 2 ? 1 : 0.7) : 2
}

/** 代表戦のあと: 経験点・知名度（大会の格で）・初めての代表戦の会話 */
export function careerAfterNational(state: GameState, kind: 'friendly' | 'qualifier' | 'worldCup', compShort: string, opp: string, side: 0 | 1, s: MatchSummary) {
  const c = state.career!
  const ps = s.players.find((x) => x.id === c.playerId)
  const gf = s.score[side]
  const ga = s.score[side === 0 ? 1 : 0]
  c.lastNational = { opp, compShort, gf, ga, rating: ps?.rating ?? 0, goals: ps?.goals ?? 0, minutes: Math.round(ps?.minutes ?? 0) }
  if (!ps || ps.minutes <= 0.5) return
  const share = Math.min(1, ps.minutes / 90)
  const prestigeN = kind === 'worldCup' ? 3 : kind === 'qualifier' ? 2 : 1.4
  gainExp(state, { tech: 8 * share + ps.goals * 10, tactics: 8 * share, mental: 8 * share + (ps.rating >= 7.5 ? 8 : 0), power: 4 * share, speed: 4 * share }, matchExpMul(state))
  c.fame = clamp(c.fame + (1 + ps.goals * 1.5 + (ps.rating >= 7.5 ? 1 : 0)) * prestigeN * (c.fame > 70 ? 0.5 : 1), 0, 100)
  c.stamina = clamp(c.stamina - share * 10, 0, 100)
  if (c.done.sys_natDebut === undefined && !c.talks.some((t) => t.eventId === 'sys_natDebut')) queueTalk(state, 'sys_natDebut')
  report(state, `代表戦（${compShort}）に出場${ps.goals ? `、${ps.goals} 得点！` : '。'}（評価点 ${ps.rating.toFixed(1)}）`)
}

export function careerAfterMatch(state: GameState, comp: Competition, f: Fixture, s: MatchSummary) {
  const c = state.career!
  const ps = s.players.find((x) => x.id === c.playerId)
  const side = f.home === state.players[c.playerId].clubId ? 0 : 1
  const conceded = s.score[side === 0 ? 1 : 0]
  const played = !!ps && ps.minutes > 0.5
  if (!played) {
    c.lastMatch = { rating: 0, goals: 0, assists: 0, started: false, minutes: 0, expGain: {}, trustDelta: 0, moments: [] }
    return
  }
  const share = Math.min(1, ps.minutes / 90)
  const moments = s.moments ?? []
  const okMoments = moments.filter((m) => m.ok).length
  const expGain = gainExp(
    state,
    {
      tech: 6 * share + ps.goals * 8 + Math.max(0, ps.rating - 6) * 5,
      tactics: 6 * share + ps.assists * 6 + Math.max(0, ps.rating - 6) * 4,
      mental: 4 * share + okMoments * 4 + (ps.rating >= 7.5 ? 6 : 0),
      power: 4 * share,
      speed: 4 * share,
    },
    matchExpMul(state),
  )
  const trustDelta = ps.rating >= 7.5 ? 4 : ps.rating >= 7 ? 2 : ps.rating >= 6.2 ? 0.5 : ps.rating >= 5.5 ? -1.5 : -3
  c.trust = clamp(c.trust + trustDelta, 0, 100)
  c.fame = clamp(c.fame + (ps.goals * 1.2 + ps.assists * 0.6 + (ps.rating >= 7.5 ? 1 : 0)) * prestige(comp) * (c.fame > 70 ? 0.5 : 1), 0, 100)
  c.stamina = clamp(c.stamina - share * 12, 0, 100)
  countObjectives(state, true, ps.goals, ps.assists, ps.rating, conceded === 0)
  c.lastMatch = { rating: ps.rating, goals: ps.goals, assists: ps.assists, started: ps.started, minutes: Math.round(ps.minutes), expGain, trustDelta, moments }
  if (c.done.sys_firstMatch === undefined && !c.talks.some((t) => t.eventId === 'sys_firstMatch')) queueTalk(state, 'sys_firstMatch')
  if (ps.goals > 0 && c.done.sys_firstGoal === undefined && !c.talks.some((t) => t.eventId === 'sys_firstGoal')) queueTalk(state, 'sys_firstGoal')
  if (ps.goals > 0) report(state, `${comp.name}で ${ps.goals} 得点！（評価点 ${ps.rating.toFixed(1)}）`)
  // 簡単モード: 試合で入った経験点もすぐ能力に
  easyGrowth(state, '試合の経験')
  lastGameCheck(state, comp, f)
}
