/** 先発と控えの自動選択。 */
import { formationOf } from '../data/formations'
import { POSITIONS, type Position } from '../data/positions'
import type { Club, Lineup } from '../models/club'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import { ratingAt } from '../player/overall'

export function squadOf(state: GameState, clubId: number): Player[] {
  const out: Player[] = []
  for (const id in state.players) {
    const p = state.players[id]
    if (p.clubId === clubId && !p.retired && !p.isYouth) out.push(p)
  }
  return out
}

export function isAvailable(p: Player): boolean {
  return !p.injury && p.suspension <= 0
}

/** 試合に出すときの評価（調子と疲労を含む） */
export function selectionScore(p: Player, pos: Position): number {
  return baseSelectionScore(p, pos)
}

function baseSelectionScore(p: Player, pos: Position): number {
  const cond = 0.94 + (p.condition / 100) * 0.12
  const tired = p.fatigue > 60 ? 1 - (p.fatigue - 60) / 200 : 1
  return ratingAt(p, pos) * cond * tired
}

/** 外国人枠: 日本のクラブは先発＋ベンチに入れる外国籍の選手を 5 人まで */
export const FOREIGN_LIMIT = 5

export function isForeign(p: Player, club: Club): boolean {
  return club.country === 'JP' && club.leagueId !== 'WL' && p.nation !== 'JP'
}

export function foreignLimit(club: Club): number {
  // ワールドリーグ（M24）は外国人枠なし
  return club.country === 'JP' && club.leagueId !== 'WL' ? FOREIGN_LIMIT : Infinity
}

/** 枠がいっぱいでも獲る値打ちのある外国籍の選手: 今の先発を推定でこれだけ上回る */
export const FOREIGN_BIG_GAIN = 8

/** 外国人枠の状況: 在籍している外国籍の人数（日本のクラブだけ。5 人以上なら、ベンチに入れられない選手が出る） */
export function foreignRoster(state: GameState, club: Club): { limit: number; roster: number; full: boolean } {
  const limit = foreignLimit(club)
  if (limit === Infinity) return { limit, roster: 0, full: false }
  const roster = squadOf(state, club.id).filter((p) => isForeign(p, club)).length
  return { limit, roster, full: roster >= limit }
}

/** 先発＋ベンチの外国籍の人数 */
export function foreignCount(state: GameState, club: Club, lineup: Lineup = club.lineup): number {
  return [...lineup.starters, ...lineup.bench].filter((id) => state.players[id] && isForeign(state.players[id], club)).length
}

/** ポジションの番号（autoLineup の点のメモのキー） */
const POS_INDEX = Object.fromEntries(POSITIONS.map((p, i) => [p, i])) as Record<Position, number>

/** 埋める順番（代わりのききにくいポジションから） */
const SLOT_PRIORITY: Record<Position, number> = { GK: 0, CB: 1, ST: 2, DM: 3, SB: 4, WB: 4, CM: 5, AM: 6, WG: 7, SM: 8 }

export function autoLineup(state: GameState, club: Club, squad?: Player[]): Lineup {
  const f = formationOf(club.tactics.formation)
  // キャリアの主人公は、監督の評価で選考の点が上下する（評価 50 で等倍）
  const meId = state.career?.playerId
  // 同じ選手・同じポジションの点は 1 回だけ計算する（毎週全クラブで組むので、並べ替えのたびに計算し直さない）
  const memo = new Map<number, number>()
  const selectionScore = (p: Player, pos: Position) => {
    const key = p.id * 16 + POS_INDEX[pos]
    let v = memo.get(key)
    if (v === undefined) {
      v = baseSelectionScore(p, pos) * (p.id === meId ? 0.9 + (state.career!.trust / 100) * 0.2 : 1)
      memo.set(key, v)
    }
    return v
  }
  const pool = (squad ?? squadOf(state, club.id)).filter((p) => isAvailable(p) && !p.isYouth)
  const used = new Set<number>()
  const starters: number[] = new Array(f.slots.length).fill(-1)
  const order = f.slots.map((s, i) => ({ s, i })).sort((a, b) => SLOT_PRIORITY[a.s.pos] - SLOT_PRIORITY[b.s.pos])
  const limit = foreignLimit(club)
  let foreign = 0
  const blocked = (p: Player) => foreign >= limit && isForeign(p, club)
  for (const { s, i } of order) {
    let best: Player | null = null
    let bestScore = -1
    for (const p of pool) {
      if (used.has(p.id) || blocked(p)) continue
      const sc = selectionScore(p, s.pos)
      if (sc > bestScore) {
        bestScore = sc
        best = p
      }
    }
    if (best) {
      starters[i] = best.id
      used.add(best.id)
      if (isForeign(best, club)) foreign++
    }
  }
  // 控え 9 人（GK 1 人を含める）
  const rest = pool.filter((p) => !used.has(p.id))
  const bench: number[] = []
  const gk = rest.filter((p) => p.pos === 'GK' && !blocked(p)).sort((a, b) => selectionScore(b, 'GK') - selectionScore(a, 'GK'))[0]
  if (gk) {
    bench.push(gk.id)
    if (isForeign(gk, club)) foreign++
  }
  const others = rest.filter((p) => p !== gk).sort((a, b) => selectionScore(b, b.pos) - selectionScore(a, a.pos))
  for (const p of others) {
    if (bench.length >= 9) break
    if (blocked(p)) continue
    bench.push(p.id)
    if (isForeign(p, club)) foreign++
  }
  const startersP = starters.map((id) => state.players[id]).filter(Boolean)
  const byTrait = (k: 'leadership') => [...startersP].sort((a, b) => b.traits[k] - a.traits[k])[0]?.id
  const bestAt = (score: (p: Player) => number) => [...startersP].filter((p) => p.pos !== 'GK').sort((a, b) => score(b) - score(a))[0]?.id
  return {
    starters,
    bench,
    captain: byTrait('leadership'),
    penaltyTaker: bestAt((p) => p.attr.shoot + p.attr.composure),
    freeKickTaker: bestAt((p) => p.attr.shoot + p.attr.cross + (p.skills.includes('fkSpecialist') ? 30 : 0)),
    cornerTaker: bestAt((p) => p.attr.cross * 2 + p.attr.pass),
    manual: false,
  }
}

/** チームの平均（先発の配置での評価） */
export function teamStrength(state: GameState, club: Club): number {
  const f = formationOf(club.tactics.formation)
  const l = club.lineup.starters.length ? club.lineup : autoLineup(state, club)
  let s = 0
  let n = 0
  l.starters.forEach((id, i) => {
    const p = state.players[id]
    if (!p) return
    s += ratingAt(p, f.slots[i].pos)
    n++
  })
  return n ? s / n : 0
}

/** フォーメーションを変えたとき、今の先発 11 人を新しいスロットに当てはめ直す */
export function refitLineup(state: GameState, club: Club, formationId: string): Lineup {
  const f = formationOf(formationId)
  const current = club.lineup.starters.map((id) => state.players[id]).filter(Boolean)
  const used = new Set<number>()
  const starters: number[] = new Array(f.slots.length).fill(-1)
  const order = f.slots.map((s, i) => ({ s, i })).sort((a, b) => SLOT_PRIORITY[a.s.pos] - SLOT_PRIORITY[b.s.pos])
  for (const { s, i } of order) {
    let best: Player | null = null
    let bs = -1
    for (const p of current) {
      if (used.has(p.id)) continue
      const sc = selectionScore(p, s.pos)
      if (sc > bs) {
        bs = sc
        best = p
      }
    }
    if (best) {
      starters[i] = best.id
      used.add(best.id)
    }
  }
  return { ...club.lineup, starters, manual: true }
}
