/**
 * オフの旅行の会話（その場で組み立てる。career/vacation.ts）。id は trip:<行き先>:<連れ>:<そのほか>
 *   そのほか: 家族なら子どもがいるか（1/0）、仲間なら一緒に行った仲間の id
 *   行き先の地の文 2 行 ＋ 連れの台詞（恋人・妻は個性ごと）＋ 主人公の締め
 * 全年齢向け。飲酒の描写なし。
 */
import type { CareerEventDef, TalkLineDef } from '../events'
import type { Companion, PartnerTrait, VacationId } from '../../models/career'

/** 行き先の地の文（{place} は行き先の名前） */
const INTRO: Record<VacationId, [string, string]> = {
  hakone: ['紅葉に囲まれた露天風呂。湯気の向こうで、赤い葉がゆっくり落ちていく。', 'シーズンの疲れが、お湯の中に溶けていくようだった。'],
  hokkaido: ['一面の雪景色。ログハウスの暖炉で、薪がぱちぱちと鳴る。', '音のない夜。久しぶりに、何も考えずに眠った。'],
  okinawa: ['白い砂浜と、どこまでも透きとおる青い海。', 'ハンモックに揺られながら、波の音だけを聞いていた。'],
  hawaii: ['ヤシの木の並ぶビーチに、大きな夕日が沈んでいく。', '朝は海沿いを軽く走り、昼はのんびりと泳いだ。'],
  newyork: ['摩天楼の明かりが、川面に映ってきらめいている。', 'ミュージカルにバスケットボール。街じゅうが刺激でいっぱいだった。'],
  paris: ['石畳の街を歩き、美術館で名画の前に立ち止まった。', '南仏の海辺では、テラスで朝ごはんを食べた。'],
  swiss: ['アルプスの山小屋。雪をかぶった峰の下に、緑の草原が広がる。', '澄んだ空気の中を、ゆっくりと山道を歩いた。'],
  maldives: ['海の上に建つコテージ。床のガラス越しに、魚の群れが見える。', 'デッキから海に飛び込むと、時間の感覚がなくなった。'],
  cruise: ['豪華客船で、世界の港をめぐる長い旅。', '朝が来るたびに、窓の外に違う国の景色が広がっていた。'],
  home: ['久しぶりに{place}で過ごすオフ。', '自分の家なのに、ここに来ると旅をしている気分になる。'],
}

/** 恋人・妻の台詞（個性ごと） */
const PARTNER: Record<PartnerTrait, string> = {
  cook: 'ここの名物、帰ったら作ってみるね。{place}の味、ふたりの思い出にしよう。',
  sport: 'ねえ、明日の朝も一緒に走ろう！ {place}を走れるなんて最高だよ！',
  study: '{place}のこと、いろいろ調べてきたの。……でも今日は、案内よりあなたと話したいかな。',
  art: 'この景色、ずっと覚えていたい。{place}に来られて、ほんとうによかった。',
  cheer: '{place}、ほんとうに来られたんだね！ 一緒にいられるだけで、すっごく楽しい！',
  care: 'シーズンおつかれさま。{place}では、何も考えずに休んでくださいね。',
}

const SOLO = [
  'ひとりで来るのもいいな。来季に向けて、頭の中がすっきりした。',
  'サッカーから少し離れてみて、やっぱりサッカーが好きなんだと分かった。',
  'ここで見た景色を、来季の苦しいときに思い出そう。',
]

const CLOSE: Record<Exclude<Companion, 'solo'>, string> = {
  partner: 'また来年も、一緒に来よう。',
  family: '来年も、みんなで来よう。',
  friends: 'ああ。来季は、もっと上を目指そう。',
}

/** その場で組み立てる */
export function tripEvent(id: string): CareerEventDef | undefined {
  const [, dest, w, extra] = id.split(':') as [string, VacationId, Companion, string | undefined]
  const intro = INTRO[dest]
  if (!intro) return undefined
  const lines: TalkLineDef[] = [
    { s: 'nar', t: intro[0] },
    { s: 'nar', t: intro[1] },
  ]
  if (w === 'solo') lines.push({ s: 'me', t: SOLO[dest.length % SOLO.length] })
  else if (w === 'friends') {
    if (extra) lines.push({ s: extra, t: 'たまにはピッチの外で一緒にいるのもいいな。来季もよろしく頼むぜ。' })
    lines.push({ s: 'me', t: CLOSE.friends })
  } else {
    if (w === 'family' && extra === '1') {
      lines.push({ s: 'partner', t: '{child}、はしゃぎすぎて寝ちゃったね。……家族で来られて、ほんとうによかった。' })
    } else lines.push({ s: 'partner', t: '{trait}' })
    lines.push({ s: 'me', t: CLOSE[w] })
  }
  return { id, char: w === 'partner' || w === 'family' ? 'partner' : undefined, title: 'オフの旅行', trigger: 'system', lines }
}

/** 恋人・妻の台詞（個性で選ぶ。vacation.ts が予約のときに差し込む） */
export function tripPartnerLine(trait: PartnerTrait): string {
  return PARTNER[trait]
}
