/**
 * 入団会見（M16、クラブモード）: 大型補強（移籍金 3 億円以上か、自クラブの上位 3 人に入る選手）で会見を開く。
 * 背番号を選び、選手の一言（性格ごと）と記者の質問。終えると期待で人気とサポーターが少し上がる。
 */
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import type { Personality } from '../data/personality'
import { ovr } from '../player/overall'

/** 会見を開く移籍金（万円） */
const BIG_FEE = 30000

export function maybeQueuePress(state: GameState, p: Player, fee: number) {
  const me = state.clubs[state.playerClubId]
  if (state.mode !== 'club' || p.clubId !== me.id) return
  const squad = Object.values(state.players).filter((x) => x.clubId === me.id && !x.retired && x.id !== p.id)
  const top3 = squad.map(ovr).sort((a, b) => b - a)[2] ?? 0
  if (fee < BIG_FEE && ovr(p) <= top3 && !p.starId) return
  state.press = [...(state.press ?? []), { playerId: p.id, fee }]
}

/** 選べる背番号（人気の番号のうち空いているもの。今の番号も） */
export function freeNumbers(state: GameState, p: Player): number[] {
  const used = new Set(Object.values(state.players).filter((x) => x.clubId === p.clubId && !x.retired && x.id !== p.id).map((x) => x.number))
  return [7, 8, 9, 10, 11, 13, 14, 17, 18, 19, 20, 22, 23, 24, 25, 27, 30, 33, 77, 99].filter((n) => !used.has(n) || n === p.number).slice(0, 10)
}

/** 選手の一言（性格ごと） */
export const PRESS_LINES: Record<Personality, string> = {
  hot: 'このクラブを優勝させるために来ました！ 毎試合、全力で走ります！',
  cool: '自分の役割を果たすだけです。結果で答えます。',
  mood: 'チームを明るくして、スタジアムをもっと盛り上げたいです！',
  effort: '一日一日、積み上げていきます。期待に応えられるよう、努力を続けます。',
  genius: 'ゴールは任せてください。見ている人が驚くプレーを見せます。',
  mypace: '自分らしいサッカーができれば、自然と結果はついてくると思います。',
  leader: '若い選手も多いクラブ。ピッチの内でも外でも、チームを引っ張りたい。',
  shy: '……緊張しています。でも、サポーターの皆さんのために頑張ります。',
}

/** 会見を終える（背番号を決め、期待で人気とサポーターが上がる）。上がった人気を返す */
export function finishPress(state: GameState, number?: number): number {
  const item = state.press?.[0]
  state.press = (state.press ?? []).slice(1)
  if (!item) return 0
  const p = state.players[item.playerId]
  const me = state.clubs[state.playerClubId]
  if (!p || p.clubId !== me.id) return 0
  if (number !== undefined && freeNumbers(state, p).includes(number)) p.number = number
  const squad = Object.values(state.players).filter((x) => x.clubId === me.id && !x.retired)
  const avg = squad.reduce((n, x) => n + ovr(x), 0) / Math.max(1, squad.length)
  const up = Math.max(1, Math.min(5, Math.round((ovr(p) - avg) / 4)))
  me.popularity = Math.min(100, me.popularity + up)
  me.fans += Math.round(me.fans * 0.01 * up)
  return up
}
