/** キャリアモードの共通の小道具。 */
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import type { CareerState, PlaceId, Region } from '../models/career'
import { OVERSEAS } from '../models/career'
import { CAREER_CAST, CAST_BY_ID, DECLINE_SERVICES, GEN2_ABROAD, GEN2_ABROAD_NAMES, GEN2_CAST, GEN2_NAMES, OVERSEAS_PLACE_NAMES, OVERSEAS_PLACES, PLACES, type PlaceDef } from '../data/career'
import { createRng, hashSeed } from '../core/prng'
import { ageOf } from '../player/overall'
import { absWeekOf } from '../core/calendar'

export function isCareer(state: GameState): boolean {
  return state.mode === 'career' && !!state.career
}

export function career(state: GameState): CareerState {
  if (!state.career) throw new Error('キャリアモードではない')
  return state.career
}

/** 主人公（キャリアでなければ undefined） */
export function protagonist(state: GameState): Player | undefined {
  return state.career ? state.players[state.career.playerId] : undefined
}

export function isProtagonist(state: GameState, p: Player | number): boolean {
  const id = typeof p === 'number' ? p : p.id
  return !!state.career && state.career.playerId === id
}

/** 主人公の年齢 */
export function careerAge(state: GameState): number {
  const p = protagonist(state)
  return p ? ageOf(p, absWeekOf(state.season, state.week)) : 0
}

/** その人の今の年齢（キャリア開始時の年齢に経過年数を足す） */
export function castAge(state: GameState, id: string): number {
  const c = CAST_BY_ID[id]
  if (!c) return 0
  // 子どもの世代の人は、主人公との年の差（M17）
  if (c.gen) return careerAge(state) + c.age
  return c.age + state.season
}

/** 今の世代（M17。1 = 最初の主人公） */
export function currentGen(state: GameState): number {
  return state.career?.saga?.gen ?? 1
}

/** 世代の名前を選ぶ（役ごと。種と世代から。日本の役と海外の役は別の乱数の流れ） */
export function genNames(seed: number, gen: number): Record<string, string> {
  const rng = createRng(hashSeed(seed, gen, 0x9e2))
  const fam = rng.shuffle([...GEN2_NAMES.family])
  const girls = rng.shuffle([...GEN2_NAMES.girl])
  const boys = rng.shuffle([...GEN2_NAMES.boy])
  const out: Record<string, string> = {}
  let f = 0
  let g = 0
  let b = 0
  for (const x of GEN2_CAST) {
    if (x.id === 'g2_coach') out[x.id] = `${fam[f++]}監督`
    else if (x.kind === 'heroine') out[x.id] = `${fam[f++]}${girls[g++]}`
    else out[x.id] = `${fam[f++]}${boys[b++]}`
  }
  // 海外の人（国ごとに名前の候補から。同じ国の人どうしで名字が重ならないように）
  const abroad = createRng(hashSeed(seed, gen, 0x9e3))
  const fams = new Map<string, string[]>()
  for (const x of GEN2_ABROAD) {
    const pool = GEN2_ABROAD_NAMES[x.region as keyof typeof GEN2_ABROAD_NAMES]
    let fam = fams.get(x.region!)
    if (!fam) fams.set(x.region!, (fam = abroad.shuffle([...pool.family])))
    out[x.id] = `${abroad.pick(x.kind === 'heroine' ? pool.girl : pool.boy)}・${fam.shift()}`
  }
  return out
}

/** 登場人物の名前（子どもの世代の人は、世代ごとに選んだ名前。古いセーブにない役は種と世代から） */
export function castName(state: GameState | undefined, id: string): string {
  const saga = state?.career?.saga
  const named = saga?.names?.[id]
  if (named) return named
  if (state && saga?.names && CAST_BY_ID[id]?.gen) return genNames(state.seed, saga.gen)[id] ?? CAST_BY_ID[id].name
  return CAST_BY_ID[id]?.name ?? ''
}

/** 恋愛が進められる相手か（全年齢向けの決まり: 大人どうしで、相談相手でない人だけ） */
export function canRomance(state: GameState, id: string): boolean {
  const c = CAST_BY_ID[id]
  return !!c && c.romance && castAge(state, id) >= 18 && careerAge(state) >= 18
}

export const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

/** 先週の出来事に 1 行足す */
export function report(state: GameState, text: string) {
  const c = career(state)
  c.report.push(text)
  if (c.report.length > 12) c.report.splice(0, c.report.length - 12)
}

// ---------------------------------------------------------------- 地域（M10）

/** 暮らしている地域: 所属クラブの国（欧州 5 か国とブラジルなら海外）。入団前・日本・アジアは日本 */
export function regionOf(state: GameState): Region {
  const p = protagonist(state)
  const country = p && p.clubId >= 0 ? state.clubs[p.clubId]?.country : 'JP'
  return (OVERSEAS as string[]).includes(country ?? '') ? (country as Region) : 'JP'
}

/** その人に、今いる地域で会えるか（恋人・結婚相手と代理人はどこでも） */
export function canMeet(state: GameState, id: string): boolean {
  const c = state.career
  if (id === 'kato_misaki' || id === c?.partner || id === c?.spouse) return true
  const cast = CAST_BY_ID[id]
  if (!cast) return false
  // 世代が違う人には会えない（M17。代理人の加藤と、海外の通訳のフセインはどの世代でも）
  // （子どもの世代の役 gen 2 は、孫より先の世代でも使う）
  if (id !== 'hussein_alsalam' && ((cast.gen ?? 1) === 1 ? currentGen(state) !== 1 : currentGen(state) < 2)) return false
  // 孫の世代からは、子どもの世代の役を名前を変えて使い回す。母になった人の役は出さない（同じ顔になるので）
  if (id === c?.saga?.mother) return false
  const region = regionOf(state)
  const r = cast.region ?? 'JP'
  return r === region || (r === 'abroad' && region !== 'JP')
}

/** 今いる地域のおでかけ先（海外は国ごとの名前と、その国で会える人） */
export function placesFor(state: GameState): PlaceDef[] {
  const region = regionOf(state)
  if (region === 'JP') {
    const gen = currentGen(state)
    if (gen === 1) return PLACES
    // 子どもの世代: その世代の人を、決まった場所に
    return PLACES.map((pl) => ({ ...pl, people: GEN2_CAST.filter((x) => x.places?.includes(pl.id)).map((x) => x.id) }))
  }
  const names = OVERSEAS_PLACE_NAMES[region]
  return OVERSEAS_PLACES.map((pl) => ({
    ...pl,
    name: names[pl.id] ?? pl.name,
    // 子どもの世代からは、その世代の海外の人（と通訳）
    people: (currentGen(state) >= 2 ? [...GEN2_ABROAD, CAST_BY_ID.hussein_alsalam] : CAREER_CAST).filter((x) => x.places?.includes(pl.id) && (x.region === region || x.region === 'abroad')).map((x) => x.id),
  }))
}

/** おでかけ先を id で（今の地域の名前と人で） */
export function placeById(state: GameState, id: PlaceId): PlaceDef {
  return placesFor(state).find((p) => p.id === id) ?? [...PLACES, ...OVERSEAS_PLACES].find((p) => p.id === id)!
}

/** 主人公の年齢による衰えの倍率（専属のスポーツ科学チームなどでゆっくりに） */
export function careerDeclineMul(state: GameState): number {
  const services = state.career?.services ?? []
  return services.reduce((m, id) => m * (DECLINE_SERVICES[id] ?? 1), 1)
}
