/**
 * 引退: 考える → ラストゲーム → セレモニー → キャリアの総括（G〜S）。
 *   33 歳から（力が落ちていれば 31 歳から）、毎季の第 38 週に代理人と引退の話をする。続けるか、今季限りか
 *   39 歳になったら今季限り。契約が切れて行き先がないまま 34 歳を過ぎたら引退
 *   今季限りと決めたら、リーグ戦の最後の試合のあとにラストゲームの会話、シーズン末に引退のセレモニーと総括
 *   殿堂入り: 1 つのクラブで 150 試合か 60 得点
 */
import { absWeekOf } from '../core/calendar'
import { starterOvrForRep } from '../gen/playerGen'
import type { Competition, Fixture } from '../models/competition'
import type { GameState } from '../models/game'
import type { CareerSummary } from '../models/career'
import { ovr } from '../player/overall'
import { careerAge, report } from './core'
import { queueTalk } from './events'

const RETIRE_TALK_WEEK = 38

const queued = (state: GameState, id: string) => state.career!.talks.some((t) => t.eventId === id)

/** 毎週: 引退を考える時期なら会話を予約する */
export function retireWeek(state: GameState) {
  const c = state.career!
  if (c.retired || c.retirePlanned || state.week !== RETIRE_TALK_WEEK || c.retireAskedSeason === state.season) return
  const p = state.players[c.playerId]
  if (p.clubId < 0) return
  const age = careerAge(state)
  const level = starterOvrForRep(state.clubs[p.clubId].rep, state.clubs[p.clubId].country)
  if (age >= 39) {
    c.retireAskedSeason = state.season
    c.retirePlanned = true
    queueTalk(state, 'sys_retireForced')
  } else if (age >= 33 || (age >= 31 && ovr(p) < level - 6)) {
    c.retireAskedSeason = state.season
    if (!queued(state, 'sys_retireThink')) queueTalk(state, 'sys_retireThink')
  }
}

/** 39 歳からは今季限りが決まっていて、取り消せない */
export const FORCED_RETIRE_AGE = 39

/** 自分で引退を決められるか（何歳でも。プロのクラブに所属していて、まだ決めていない） */
export function canPlanRetirement(state: GameState): boolean {
  const c = state.career
  if (!c || c.retired || c.retirePlanned || c.saga?.phase === 'youth') return false
  return state.players[c.playerId].clubId >= 0
}

/** 今季限りで引退すると決める（シーズン末に引退。最後のリーグ戦がラストゲーム） */
export function planRetirement(state: GameState): boolean {
  if (!canPlanRetirement(state)) return false
  const c = state.career!
  c.retirePlanned = true
  c.retireAskedSeason = state.season
  queueTalk(state, 'sys_retireDecide')
  report(state, '今季限りでの引退を決めた。')
  return true
}

/** 引退の決定を取り消せるか（シーズンが終わるまで。39 歳からは取り消せない） */
export function canCancelRetirement(state: GameState): boolean {
  const c = state.career
  return !!c && !!c.retirePlanned && !c.retired && careerAge(state) < FORCED_RETIRE_AGE
}

export function cancelRetirement(state: GameState): boolean {
  if (!canCancelRetirement(state)) return false
  state.career!.retirePlanned = false
  report(state, '引退を思いとどまった。来季も現役を続ける。')
  return true
}

/** 所属クラブのリーグ戦の、今季の最後の試合か */
export function isLastLeagueMatch(state: GameState, comp: Competition, f: Fixture): boolean {
  if (comp.kind !== 'league') return false
  const club = state.players[state.career!.playerId].clubId
  const mine = comp.fixtures.filter((x) => x.home === club || x.away === club)
  return mine.length > 0 && mine.every((x) => x.id === f.id || x.absWeek < f.absWeek)
}

/** 試合のあと: 引退を決めていて、リーグ戦の最後の試合ならラストゲームの会話 */
export function lastGameCheck(state: GameState, comp: Competition, f: Fixture) {
  const c = state.career!
  if (c.retirePlanned && !c.done.sys_lastGame && !queued(state, 'sys_lastGame') && isLastLeagueMatch(state, comp, f)) queueTalk(state, 'sys_lastGame')
}

const GRADES: [string, number][] = [
  ['S', 2400],
  ['A', 1600],
  ['B', 1000],
  ['C', 600],
  ['D', 330],
  ['E', 160],
  ['F', 60],
]

/** キャリアの総括（今季の成績も含める） */
export function careerSummary(state: GameState): CareerSummary {
  const c = state.career!
  const p = state.players[c.playerId]
  const logs = c.log
  const apps = logs.reduce((n, l) => n + l.apps, 0)
  const goals = logs.reduce((n, l) => n + l.goals, 0)
  const assists = logs.reduce((n, l) => n + l.assists, 0)
  const titles = logs.flatMap((l) => l.titles)
  const peakOvr = Math.max(ovr(p), ...logs.map((l) => l.ovr))
  // クラブごとの通算で殿堂入り
  const byClub = new Map<number, { apps: number; goals: number }>()
  for (const l of logs) {
    const x = byClub.get(l.clubId) ?? { apps: 0, goals: 0 }
    x.apps += l.apps
    x.goals += l.goals
    byClub.set(l.clubId, x)
  }
  const hallOfFame = [...byClub].filter(([id, x]) => id >= 0 && (x.apps >= 150 || x.goals >= 60)).map(([id]) => id)
  const caps = p.intl?.caps ?? 0
  const intlGoals = p.intl?.goals ?? 0
  const worldCups = p.intl?.wc ?? 0
  const points = Math.round(apps + goals * 3 + assists * 2 + titles.length * 40 + caps * 4 + intlGoals * 6 + worldCups * 40 + Math.max(0, peakOvr - 60) * 8 + hallOfFame.length * 60)
  const grade = GRADES.find(([, min]) => points >= min)?.[0] ?? 'G'
  return { grade, points, apps, goals, assists, titles, caps, intlGoals, worldCups, peakOvr, hallOfFame, retiredAge: careerAge(state) }
}

/**
 * シーズン末（記録を残したあと）: 引退するなら引退して true。
 * 今季限りと決めていた・40 歳になった・契約が切れて行き先がないまま 34 歳を過ぎた
 */
export function retireAtSeasonEnd(state: GameState): boolean {
  const c = state.career!
  const p = state.players[c.playerId]
  const age = careerAge(state)
  const noClub = p.contract.until <= state.season && !c.offers.some((o) => o.kind === 'renewal' || o.kind === 'transfer')
  if (!c.retirePlanned && age < 40 && !(noClub && age >= 34)) return false
  c.retired = true
  c.retiredAbsWeek = absWeekOf(state.season, state.week)
  c.summary = careerSummary(state)
  c.offers = []
  c.objectives = []
  p.retired = true
  p.clubId = -1
  queueTalk(state, 'sys_retire')
  queueTalk(state, c.spouse || c.partner ? 'sys_epilogueFamily' : 'sys_epilogue')
  return true
}
