/**
 * キャリアの個人の事業: 開業・Lv3 まで拡大・売却（かけたお金の 6 割）、毎週の損益、シーズン末の決算。
 *   毎週の損益 = 売上の基本 × レベルの倍率 × 知名度の倍率 × 景気 × ゆらぎ − 経費 × レベル
 *   景気はクラブモードの事業と同じ波（economy/business.ts の cycleOf）を使う
 * 乱数は呼び出し元の lifeRng（くらし専用の流れ）を使う。
 */
import type { Rng } from '../core/prng'
import { absWeekOf } from '../core/calendar'
import { CAREER_BIZ, type CareerBizDef } from '../data/career'
import { cycleOf } from '../economy/business'
import type { GameState } from '../models/game'
import type { CareerBizId, CareerBusiness } from '../models/career'
import { clamp, report } from './core'
import { gainExp } from './growth'

export const BIZ_BY_ID = Object.fromEntries(CAREER_BIZ.map((b) => [b.id, b])) as Record<CareerBizId, CareerBizDef>

const LEVEL_SALES = [1, 1.9, 2.8]

export function findBiz(state: GameState, id: CareerBizId): CareerBusiness | undefined {
  return state.career!.businesses?.find((b) => b.id === id)
}

/** 知名度の倍率（知名度しだいの事業ほど大きく動く） */
function fameMul(state: GameState, def: CareerBizDef): number {
  return 1 + def.fameSens * (state.career!.fame / 100 - 0.4)
}

/** 毎週の損益の見込み（ゆらぎなし） */
export function bizEstimate(state: GameState, id: CareerBizId, level: number): number {
  const def = BIZ_BY_ID[id]
  return Math.round(def.base * LEVEL_SALES[level - 1] * fameMul(state, def) * cycleOf(state) - def.upkeep * level)
}

export function canOpenBiz(state: GameState, id: CareerBizId): { ok: boolean; reason?: string } {
  if (findBiz(state, id)) return { ok: false, reason: '営業中' }
  if (state.career!.money < BIZ_BY_ID[id].cost) return { ok: false, reason: '貯金が足りない' }
  return { ok: true }
}

export function openBiz(state: GameState, id: CareerBizId): boolean {
  if (!canOpenBiz(state, id).ok) return false
  const c = state.career!
  const def = BIZ_BY_ID[id]
  c.money -= def.cost
  c.businesses = [...(c.businesses ?? []), { id, level: 1, openedAbsWeek: absWeekOf(state.season, state.week), invested: def.cost, total: 0, season: 0 }]
  report(state, `${def.name}を始めた。`)
  return true
}

/** 次のレベルにする費用（最大なら null） */
export function bizUpgradeCost(state: GameState, id: CareerBizId): number | null {
  const b = findBiz(state, id)
  if (!b || b.level >= 3) return null
  return BIZ_BY_ID[id].upgrade[b.level - 1]
}

export function upgradeBiz(state: GameState, id: CareerBizId): boolean {
  const c = state.career!
  const b = findBiz(state, id)
  const cost = bizUpgradeCost(state, id)
  if (!b || cost === null || c.money < cost) return false
  c.money -= cost
  b.level++
  b.invested += cost
  report(state, `${BIZ_BY_ID[id].name}を広げた（Lv${b.level}）。`)
  return true
}

export function bizSellValue(b: CareerBusiness): number {
  return Math.round((b.invested * 0.6) / 10) * 10
}

export function sellBiz(state: GameState, id: CareerBizId): number {
  const c = state.career!
  const b = findBiz(state, id)
  if (!b) return 0
  const v = bizSellValue(b)
  c.money += v
  c.bizTotal = (c.bizTotal ?? 0) + b.total
  c.businesses = (c.businesses ?? []).filter((x) => x.id !== id)
  report(state, `${BIZ_BY_ID[id].name}を手放した（${v.toLocaleString()} 万円）。`)
  return v
}

/** 貯金が足りなくなったとき: このシーズンの損益がいちばん悪い事業を売る */
export function sellWorstBusiness(state: GameState) {
  const list = state.career!.businesses ?? []
  if (!list.length) return
  const worst = [...list].sort((a, b) => a.season - b.season)[0]
  sellBiz(state, worst.id)
}

/** 景気の波（キャリアでも月の頭に動く。クラブモードと同じ式） */
function careerCycle(state: GameState, rng: Rng) {
  if (state.week % 4 !== 0) return
  const before = cycleOf(state)
  state.bizCycle = Math.round(clamp(before + rng.normal(0, 0.05) + (1 - before) * 0.15, 0.75, 1.3) * 1000) / 1000
}

/** 毎週の損益と効果。ときどきブーム・トラブル */
export function bizWeek(state: GameState, rng: Rng) {
  const c = state.career!
  const p = state.players[c.playerId]
  careerCycle(state, rng)
  for (const b of c.businesses ?? []) {
    const def = BIZ_BY_ID[b.id]
    let v = Math.round(def.base * LEVEL_SALES[b.level - 1] * fameMul(state, def) * cycleOf(state) * (0.85 + rng.next() * 0.3) - def.upkeep * b.level)
    if (rng.chance(0.012)) {
      const boom = Math.round(def.base * b.level * (4 + rng.next() * 4))
      v += boom
      report(state, `${def.name}が評判になり、臨時の売上 ${boom.toLocaleString()} 万円。`)
    } else if (rng.chance(0.008)) {
      const loss = Math.round(def.upkeep * b.level * (3 + rng.next() * 3))
      v -= loss
      report(state, `${def.name}でトラブルがあり、${loss.toLocaleString()} 万円の出費。`)
    }
    c.money += v
    b.total += v
    b.season += v
    const e = def.effect
    if (e?.fame) c.fame = clamp(c.fame + e.fame * b.level, 0, 100)
    if (e?.condition) p.condition = clamp(p.condition + e.condition * b.level, 0, 100)
    if (e?.exp) {
      const gain: Partial<Record<keyof typeof e.exp, number>> = {}
      for (const [k, n] of Object.entries(e.exp)) gain[k as keyof typeof e.exp] = (n ?? 0) * b.level
      gainExp(state, gain)
    }
  }
}

/** シーズン末の決算（最近の出来事に出す） */
export function bizSeasonEnd(state: GameState) {
  const c = state.career!
  const list = c.businesses ?? []
  if (!list.length) return
  const sum = list.reduce((n, b) => n + b.season, 0)
  report(state, `事業の決算: ${list.map((b) => `${BIZ_BY_ID[b.id].name} ${b.season >= 0 ? '+' : ''}${b.season.toLocaleString()}`).join('・')}（計 ${sum >= 0 ? '+' : ''}${sum.toLocaleString()} 万円）`)
  for (const b of list) b.season = 0
}

/** 事業の通算の損益（売った事業も含む） */
export function bizLifetime(state: GameState): number {
  const c = state.career!
  return (c.bizTotal ?? 0) + (c.businesses ?? []).reduce((n, b) => n + b.total, 0)
}
