/**
 * オフの旅行（M12）: シーズン中に予約し（費用は予約のときに払う。取り消せば全額戻る）、シーズン末に出かける。
 *   精神の経験点・知名度（SNS）・恋人や妻との絆。新しいシーズンのはじめに調子が上がる（vacationBoost）。
 *   連れ: ひとり・恋人（妻）・家族・チームの仲間。費用は人数ぶん（仲間とは割り勘で 1 人ぶん。監督の評価が少し上がる）。
 *   別荘（住んでいない持ち家）で過ごすなら、交通費だけ。
 *   旅の会話は trip:<行き先>:<連れ> をその場で組み立てる（dialogue/trips.ts）。思い出のアルバム（memories）に残る。
 * オフの自主トレ合宿（camp）と両方行ける。
 */
import { CAST_BY_ID, COMPANION_NAME, HOUSING_BY_ID, TRAINING_PARTNERS_BY_REGION, VACATION_BY_ID, VILLA_TRIP_COST } from '../data/career'
import type { GameState } from '../models/game'
import type { Companion, HousingId, VacationId } from '../models/career'
import { clamp, regionOf, report } from './core'
import { queueTalk } from './events'
import { partnerId, partnerName } from './family'
import { gainExp } from './growth'
import { villaHomes } from './homes'
import { tripPartnerLine } from './dialogue/trips'

/** 別荘で過ごすときの効果 */
const HOME_TRIP = { mental: 15, boost: 18, fame: 0.3, bond: 10 }

/** 連れて行ける人 */
export function companionsOf(state: GameState): Companion[] {
  const c = state.career!
  const out: Companion[] = ['solo']
  if (partnerId(state)) out.push(c.spouse ? 'family' : 'partner')
  out.push('friends')
  return out
}

/** 人数（費用の倍率） */
export function partySize(state: GameState, w: Companion): number {
  if (w === 'partner') return 2
  if (w === 'family') return 2 + (state.career!.children?.length ?? 0)
  return 1
}

/** 旅行の費用（別荘は、今の国にある家なら近場の交通費） */
export function vacationCost(state: GameState, id: VacationId, w: Companion, home?: HousingId): number {
  if (id === 'home') {
    const h = home ? HOUSING_BY_ID[home] : undefined
    const near = !h?.region || h.region.includes(regionOf(state))
    return (near ? VILLA_TRIP_COST.near : VILLA_TRIP_COST.far) * partySize(state, w)
  }
  return VACATION_BY_ID[id].cost * partySize(state, w)
}

export function canBookVacation(state: GameState, id: VacationId, w: Companion, home?: HousingId): { ok: boolean; reason?: string } {
  const c = state.career!
  if (c.retired || c.retirePlanned) return { ok: false, reason: '引退するシーズン' }
  if (c.vacation) return { ok: false, reason: '予約済み' }
  if (!companionsOf(state).includes(w)) return { ok: false, reason: '一緒に行く人がいない' }
  if (id === 'home' && (!home || !villaHomes(state).includes(home))) return { ok: false, reason: '別荘がない' }
  if (c.money < vacationCost(state, id, w, home)) return { ok: false, reason: '貯金が足りない' }
  return { ok: true }
}

export function bookVacation(state: GameState, id: VacationId, w: Companion, home?: HousingId): boolean {
  if (!canBookVacation(state, id, w, home).ok) return false
  const c = state.career!
  const cost = vacationCost(state, id, w, home)
  c.money -= cost
  c.vacation = { id, with: w, season: state.season, home, cost }
  report(state, `オフの旅行（${placeName(id, home)}・${COMPANION_NAME[w]}）を予約した。`)
  return true
}

export function cancelVacation(state: GameState) {
  const c = state.career!
  if (!c.vacation) return
  c.money += c.vacation.cost
  c.vacation = undefined
}

export function placeName(id: VacationId, home?: HousingId): string {
  return id === 'home' ? `別荘（${home ? HOUSING_BY_ID[home].name : ''}）` : VACATION_BY_ID[id].name
}

/** シーズン末: 予約した旅行に出かける */
export function vacationSeasonEnd(state: GameState) {
  const c = state.career!
  const v = c.vacation
  if (!v || v.season !== state.season) return
  c.vacation = undefined
  const def = v.id === 'home' ? HOME_TRIP : VACATION_BY_ID[v.id]
  const pid = partnerId(state)
  gainExp(state, { mental: def.mental })
  c.fame = clamp(c.fame + def.fame, 0, 100)
  if ((v.with === 'partner' || v.with === 'family') && pid) {
    const b = (c.bonds[pid] ??= { value: 0, lastAbsWeek: 0 })
    b.value = clamp(b.value + def.bond, 0, 100)
  }
  if (v.with === 'friends') c.trust = clamp(c.trust + 2, 0, 100)
  c.vacationBoost = def.boost + (v.with === 'family' ? 4 : 0)
  c.memories = [...(c.memories ?? []), { season: state.season, dest: v.id, with: v.with, partner: v.with === 'partner' || v.with === 'family' ? pid : undefined, home: v.home }]
  const place = placeName(v.id, v.home)
  const kids = c.children ?? []
  const extra = v.with === 'family' ? (kids.length ? '1' : '0') : v.with === 'friends' ? (TRAINING_PARTNERS_BY_REGION[regionOf(state)][0] ?? '') : ''
  const trait = tripPartnerLine((pid && CAST_BY_ID[pid]?.trait) || 'cheer').replace(/\{place\}/g, place)
  queueTalk(state, `trip:${v.id}:${v.with}:${extra}`, { partner: partnerName(state), place, trait, child: kids[kids.length - 1]?.name ?? '' })
  report(state, `オフに${placeName(v.id, v.home)}へ出かけた（${COMPANION_NAME[v.with]}）。`)
}

/** 新しいシーズンのはじめ: 旅行でリフレッシュした分の調子と体力 */
export function vacationWeek(state: GameState) {
  const c = state.career!
  if (state.week !== 0 || !c.vacationBoost) return
  const p = state.players[c.playerId]
  p.condition = clamp(p.condition + c.vacationBoost, 0, 100)
  c.stamina = 100
  c.vacationBoost = undefined
}
