/**
 * シーズンの表彰（リーグごと。国内・欧州・南米）: 最優秀選手・得点王・アシスト王・新人賞・最優秀GK・最優秀監督。
 * ベストイレブン（リーグごと）と、世界の年間最優秀選手「ピッチクラウン賞」（上位 10 人の投票）も決める。
 */
import { WEEKS_PER_SEASON } from '../core/calendar'
import type { Award, GameState } from '../models/game'
import type { Player } from '../models/player'
import { POSITION_DEFS } from '../data/positions'
import { ovr } from '../player/overall'

const avg = (p: Player) => (p.stats.apps ? p.stats.ratingSum / p.stats.apps : 0)

export function computeAwards(state: GameState): Award[] {
  const out: Award[] = []
  const endWeek = state.season * WEEKS_PER_SEASON + WEEKS_PER_SEASON - 1
  for (const comp of state.competitions.filter((c) => c.kind === 'league' && !c.hidden)) {
    const players = Object.values(state.players).filter((p) => !p.retired && comp.clubIds.includes(p.clubId))
    const rankOf = (clubId: number) => comp.table.findIndex((r) => r.clubId === clubId) + 1
    const best = (list: Player[], score: (p: Player) => number) => list.sort((a, b) => score(b) - score(a))[0]
    const regulars = players.filter((p) => p.stats.apps >= 20)
    const mvp = best(regulars, (p) => avg(p) + (19 - rankOf(p.clubId)) * 0.03 + p.stats.goals * 0.01)
    if (mvp) out.push({ key: 'mvp', compId: comp.id, playerId: mvp.id, clubId: mvp.clubId, name: mvp.name, value: Math.round(avg(mvp) * 100) / 100 })
    const scorer = best(players, (p) => p.stats.goals * 100 - p.stats.apps)
    if (scorer?.stats.goals) out.push({ key: 'scorer', compId: comp.id, playerId: scorer.id, clubId: scorer.clubId, name: scorer.name, value: scorer.stats.goals })
    const assist = best(players, (p) => p.stats.assists * 100 - p.stats.apps)
    if (assist?.stats.assists) out.push({ key: 'assist', compId: comp.id, playerId: assist.id, clubId: assist.clubId, name: assist.name, value: assist.stats.assists })
    const young = best(
      players.filter((p) => p.stats.apps >= 12 && (endWeek - p.birthAbsWeek) / WEEKS_PER_SEASON < 22),
      avg,
    )
    if (young) out.push({ key: 'young', compId: comp.id, playerId: young.id, clubId: young.clubId, name: young.name, value: Math.round(avg(young) * 100) / 100 })
    const keeper = best(
      players.filter((p) => p.pos === 'GK' && p.stats.apps >= 15),
      (p) => p.stats.cleanSheets * 0.3 + avg(p),
    )
    if (keeper) out.push({ key: 'keeper', compId: comp.id, playerId: keeper.id, clubId: keeper.clubId, name: keeper.name, value: keeper.stats.cleanSheets })
    const champ = state.clubs[comp.table[0].clubId]
    const mgr = champ.staff.map((id) => state.staff[id]).find((s) => s?.role === 'manager')
    if (mgr) out.push({ key: 'manager', compId: comp.id, staffId: mgr.id, clubId: champ.id })
  }
  return out
}

export const AWARD_LABEL: Record<Award['key'], string> = {
  mvp: '最優秀選手',
  scorer: '得点王',
  assist: 'アシスト王',
  young: '新人賞',
  keeper: '最優秀GK',
  manager: '最優秀監督',
  world: 'ピッチクラウン賞',
}

/** ベストイレブン（リーグごと）: 15 試合以上に出た選手から、評価点の高い順に GK 1・DF 4・MF 3・FW 3 */
export function computeBestEleven(state: GameState): Record<string, { playerId: number; name: string; short: string; pos: string; clubId: number }[]> {
  const out: Record<string, { playerId: number; name: string; short: string; pos: string; clubId: number }[]> = {}
  const LINES: [string, number][] = [
    ['GK', 1],
    ['DF', 4],
    ['MF', 3],
    ['FW', 3],
  ]
  for (const comp of state.competitions.filter((c) => c.kind === 'league' && !c.hidden)) {
    const players = Object.values(state.players).filter((p) => !p.retired && comp.clubIds.includes(p.clubId) && p.stats.apps >= 15)
    const ids: { playerId: number; name: string; short: string; pos: string; clubId: number }[] = []
    for (const [line, n] of LINES) {
      const best = players
        .filter((p) => POSITION_DEFS[p.pos].line === line)
        .sort((a, b) => avg(b) + b.stats.goals * 0.02 - (avg(a) + a.stats.goals * 0.02))
        .slice(0, n)
      ids.push(...best.map((p) => ({ playerId: p.id, name: p.name, short: p.short, pos: p.pos, clubId: p.clubId })))
    }
    if (ids.length === 11) out[comp.id] = ids
  }
  return out
}

/** リーグの強さ（ピッチクラウン賞の投票で効く） */
function leagueWeight(state: GameState, compId: string): number {
  const comp = state.competitions.find((c) => c.id === compId)
  if (!comp) return -6
  if (comp.country === 'JP') return comp.tier === 1 ? 0.5 : comp.tier === 2 ? -2.5 : -5
  return comp.country === 'BR' ? 2 : 4
}

/**
 * ピッチクラウン賞（世界の年間最優秀選手）の投票: 評価点・得点・アシスト・リーグの強さ・タイトル・総合力で点数をつけ、上位 10 人。
 * champions は今季の優勝（リーグ・カップ・大陸大会）
 */
export function computeWorldRanking(state: GameState, champions: { compId: string; clubId: number }[]): { playerId: number; clubId: number; score: number; name: string }[] {
  const leagueOfClub = new Map<number, string>()
  for (const comp of state.competitions.filter((c) => c.kind === 'league' && !c.hidden)) for (const id of comp.clubIds) leagueOfClub.set(id, comp.id)
  const titleBonus = (clubId: number) =>
    champions.filter((c) => c.clubId === clubId).reduce((n, c) => n + (c.compId === 'EUC' || c.compId === 'WCC' ? 4 : c.compId === 'ACC' ? 1.5 : c.compId === 'CUP' ? 0.5 : 2.5), 0)
  return Object.values(state.players)
    .filter((p) => !p.retired && p.stats.apps >= 15 && leagueOfClub.has(p.clubId))
    .map((p) => {
      const perGame = (p.stats.goals * (p.pos === 'ST' ? 0.8 : 1) + p.stats.assists * 0.6) / p.stats.apps
      const score = avg(p) * 6 + perGame * 6 + leagueWeight(state, leagueOfClub.get(p.clubId)!) + titleBonus(p.clubId) + (ovr(p) - 75) * 0.15
      return { playerId: p.id, clubId: p.clubId, score: Math.round(score * 100) / 100, name: p.name }
    })
    .sort((a, b) => b.score - a.score)
    .slice(0, 10)
}
