/**
 * キャリアのオファー: 移籍期間に、主人公の能力・活躍・知名度に合うクラブから届く。
 * 契約が切れる年は、更改の話（第 44 週）と、移籍先の話（フリー移籍）が届く。
 * シーズン末までに選ばなければ、更改があれば更改、なければいちばん良い話を受ける。
 */
import type { Rng } from '../core/prng'
import { absWeekOf, windowPace } from '../core/calendar'
import { jpScale } from '../data/clubs'
import { starterOvrForRep } from '../gen/playerGen'
import type { GameState } from '../models/game'
import type { CareerOffer } from '../models/career'
import { ageOf, fairWage, ovr } from '../player/overall'
import { askingPrice, windowOpen } from '../transfer/market'
import { RENEWAL_WEEK } from '../transfer/contracts'
import { acceptOffer, expectedRole } from './create'
import { queueTalk } from './events'
import { report } from './core'
import { CAREER_EUROPE } from './rank'

/** 今季の平均評価点 */
export function seasonRating(state: GameState): number {
  const p = state.players[state.career!.playerId]
  return p.stats.apps ? p.stats.ratingSum / p.stats.apps : 6.2
}

/** オファーを出してくれそうなクラブ（主人公を先発級として使える格で、今より上か同じくらい） */
function suitors(state: GameState, freeAgent: boolean): number[] {
  const c = state.career!
  const p = state.players[c.playerId]
  const o = ovr(p) + (seasonRating(state) - 6.5) * 3
  const cur = p.clubId >= 0 ? state.clubs[p.clubId] : undefined
  return state.clubs
    .filter((club) => {
      // リーグ戦をしない隠れリーグ（アマ・アジア）と、日本・欧州のほかのリーグ（南米）のクラブは移籍先にしない
      if (club.isPlayer || club.id === p.clubId || state.competitions.find((x) => x.id === club.leagueId)?.hidden) return false
      if (club.country !== 'JP' && !CAREER_EUROPE.includes(club.country)) return false
      const level = starterOvrForRep(club.rep, club.country)
      if (level > o + 3 || level < o - 9) return false
      // 海外は知名度が要る（アジア 30・欧州と南米 45）
      if (!jpScale(club.country) && c.fame < 45) return false
      if (club.country !== 'JP' && jpScale(club.country) && c.fame < 30) return false
      // 下のクラブへは行かない（フリーのときは同じくらいまで）
      if (cur && club.rep < cur.rep - (freeAgent ? 6 : 2)) return false
      return true
    })
    .map((club) => club.id)
}

function makeOffer(state: GameState, clubId: number, kind: CareerOffer['kind'], rng: Rng, fee: number): CareerOffer {
  const c = state.career!
  const p = state.players[c.playerId]
  const club = state.clubs[clubId]
  const now = absWeekOf(state.season, state.week)
  const wage = Math.round((fairWage(ovr(p), ageOf(p, now), club.country) * (1 + c.fame / 250) * (0.95 + rng.next() * 0.2)) / 10) * 10
  return { id: c.nextOfferId++, kind, clubId, fee, wage: Math.max(wage, Math.round(p.contract.wage * 1.05)), years: rng.int(2, 4), role: expectedRole(state, p, clubId), expiresAbsWeek: now + 3 }
}

/** 週ごと: 移籍期間ならオファーが届くことがある。契約最終年の第 44 週には更改の話 */
export function careerOffersWeek(state: GameState, rng: Rng) {
  const c = state.career!
  const p = state.players[c.playerId]
  const now = absWeekOf(state.season, state.week)
  c.offers = c.offers.filter((o) => o.expiresAbsWeek >= now)
  if (p.clubId < 0) return
  const lastYear = p.contract.until <= state.season
  // 更改の話（評価がそれなりにあれば）
  if (lastYear && state.week === RENEWAL_WEEK && !c.offers.some((o) => o.kind === 'renewal') && c.trust >= 30) {
    const o = makeOffer(state, p.clubId, 'renewal', rng, 0)
    o.expiresAbsWeek = absWeekOf(state.season, 47)
    o.role = c.trust >= 65 ? 'star' : c.trust >= 50 ? 'regular' : 'rotation'
    c.offers.push(o)
    queueTalk(state, 'sys_offer', { club: state.clubs[p.clubId].name })
  }
  // フリー移籍の話（契約最終年の終盤）
  const freeWindow = lastYear && state.week >= RENEWAL_WEEK
  if (!windowOpen(state) && !freeWindow) return
  // 入団・移籍したばかり（半シーズン）は話が来ない
  if (!freeWindow && c.joinedAbsWeek !== undefined && now - c.joinedAbsWeek < 24) return
  if (c.offers.filter((o) => o.kind === 'transfer').length >= 3) return
  const chance = 0.18 + c.fame / 250 + (c.wantsMove ? 0.25 : 0) + (seasonRating(state) - 6.5) * 0.15
  // 移籍期間を延ばしても 1 回の期間での回数は前と同じに（フリー移籍の話は前のまま）
  if (!rng.chance(Math.max(0.05, chance) * (freeWindow ? 1 : windowPace(state.week)))) return
  const list = suitors(state, freeWindow).filter((id) => !c.offers.some((o) => o.clubId === id))
  if (!list.length) return
  // 格の高いクラブほど選ばれやすい
  const weights = list.map((id) => state.clubs[id].rep ** 2)
  const clubId = list[rng.weighted(weights)]
  const buyer = state.clubs[clubId]
  const fee = freeWindow ? 0 : askingPrice(state, p)
  if (fee > buyer.budget * 0.6) return
  const offer = makeOffer(state, clubId, 'transfer', rng, fee)
  if (freeWindow) offer.expiresAbsWeek = absWeekOf(state.season, 47)
  c.offers.push(offer)
  queueTalk(state, 'sys_offer', { club: buyer.name })
  report(state, `${buyer.name}からオファーが届いた。`)
}

/** オファーを断る（入団のオファーは最後の 1 つは断れない） */
export function declineOffer(state: GameState, offerId: number): boolean {
  const c = state.career!
  const o = c.offers.find((x) => x.id === offerId)
  if (!o || (o.kind === 'rookie' && c.offers.filter((x) => x.kind === 'rookie').length <= 1)) return false
  c.offers = c.offers.filter((x) => x.id !== offerId)
  return true
}

/** シーズン末: 契約が切れるのに決めていなければ、更改かいちばん良い話を受ける */
export function settleExpiringContract(state: GameState) {
  const c = state.career!
  const p = state.players[c.playerId]
  if (p.contract.until > state.season) return
  const renewal = c.offers.find((o) => o.kind === 'renewal')
  if (renewal) {
    acceptOffer(state, renewal.id)
    return
  }
  const best = c.offers.filter((o) => o.kind === 'transfer').sort((a, b) => state.clubs[b.clubId].rep - state.clubs[a.clubId].rep)[0]
  if (best) {
    best.fee = 0
    acceptOffer(state, best.id)
    return
  }
  // 話がなければ、今のクラブと 1 年だけ延長（クラブが拾ってくれた形）
  p.contract = { ...p.contract, until: state.season + 1 }
  report(state, '契約を 1 年だけ延長した。来季が勝負だ。')
}
