/**
 * 自クラブの契約更改。今季で契約が切れる選手は、シーズン末までに更新しないとフリーになって退団する。
 * 7 月（オフシーズン）に更改の時期を知らせる。
 */
import { absWeekOf } from '../core/calendar'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import { squadOf } from '../match/lineup'
import { ovr, fairWage, ageOf } from '../player/overall'
import { finalizeRenewal } from './negotiation'
import { wageNeed } from './talks'
import { MIN_SQUAD, completeTransfer } from './market'
import { weekRng } from '../core/prng'
import { SQUAD_TEMPLATE, generatePlayer, starterOvrForRep } from '../gen/playerGen'

export const RENEWAL_WEEK = 44

export function expiringPlayers(state: GameState): Player[] {
  return squadOf(state, state.playerClubId).filter((p) => p.contract.until <= state.season)
}

/** 選手が受け入れる年俸（年数 2 年で聞いたとき） */
export function renewalDemand(state: GameState, p: Player): number {
  return wageNeed(state, p, 2, p.contract.role, true).need
}

/** 求められた額で 2 年更新 */
export function quickRenew(state: GameState, p: Player, years = 2) {
  finalizeRenewal(state, p, renewalDemand(state, p), years, p.contract.role)
}

/** 全員を求められた額で更新（おまかせ） */
export function renewAllExpiring(state: GameState) {
  for (const p of expiringPlayers(state)) quickRenew(state, p)
}

/** 人数が足りないとき、秘書がフリーの選手で緊急補強する */
export function emergencySign(state: GameState) {
  const me = state.clubs[state.playerClubId]
  let sq = squadOf(state, me.id)
  const now = absWeekOf(state.season, state.week)
  const signed: string[] = []
  while (sq.length < MIN_SQUAD) {
    const needGk = sq.filter((p) => p.pos === 'GK').length < 2
    const free = Object.values(state.players)
      .filter((p) => !p.retired && p.clubId < 0 && p.id !== state.career?.playerId && (!needGk || p.pos === 'GK'))
      .sort((a, b) => ovr(b) - ovr(a))
    let p = free.find((x) => fairWage(ovr(x), ageOf(x, now), 'JP') < me.budget * 0.2) ?? free[free.length - 1]
    if (!p) {
      // フリーの選手がいなければ、無名の選手を連れてくる（足りないポジションから）
      const rng = weekRng(state.seed, now, 0xe5 + sq.length)
      const lack = SQUAD_TEMPLATE.find((t) => sq.filter((q) => q.pos === t.pos).length < t.count)
      const pos = needGk ? 'GK' : (lack?.pos ?? 'CM')
      p = generatePlayer(state, rng, { clubId: -1, pos, targetOvr: starterOvrForRep(me.rep, 'JP') - rng.range(6, 12), age: rng.int(19, 30), country: 'JP', contractYears: -1 })
      state.players[p.id] = p
    }
    completeTransfer(state, p, me.id, 0, { wage: fairWage(ovr(p), ageOf(p, now), 'JP'), until: state.season + 1 }, 'free')
    signed.push(p.name)
    sq = squadOf(state, me.id)
  }
  if (signed.length) state.news.push({ absWeek: now, category: 'transfer', mine: true, text: `選手が足りないため、秘書がフリーの ${signed.join('、')} と契約しました。` })
}
