/**
 * ワールドリーグ（M24。クラブモードだけ）: 国内 1 部の上の新しいリーグ。日本 4・欧州 12・南米 2 の 18 クラブ・34 節。外国人枠なし。
 *   できるとき（新しいゲーム・古いセーブの次のシーズンのはじめ）: 各リーグの格の高いクラブが移る。
 *     NPL は 2 部・3 部から繰り上げて 18 クラブのまま（3 部には新しいクラブ）。海外のリーグは少ない数のまま続ける
 *   シーズン末: 下位 3 クラブは自分の国のリーグへ戻り、その国のリーグの上位と入れ替え（国ごとに 1 対 1 なので、どのリーグも数は変わらない）
 *     日本は NPL1 の優勝（自クラブは申請していなければ飛ばす）
 *   自クラブ: NPL1 の通算優勝回数とクラブの格で申請できる。申請するとシーズン末に参入（日本勢の最下位と入れ替え）
 */
import { absWeekOf, WEEKS_PER_SEASON } from '../core/calendar'
import { createRng, hashSeed, type Rng } from '../core/prng'
import { HOMETOWNS, type LeagueDef } from '../data/clubs'
import type { Club } from '../models/club'
import type { Competition } from '../models/competition'
import type { GameState } from '../models/game'
import { autoLineup } from '../match/lineup'
import { generateSquad } from '../gen/playerGen'
import { CLUB_STAFF_ROLES, generateStaff } from '../gen/staffGen'
import { makeClub, tacticsForStyle } from '../gen/worldGen'

export const WL_ID = 'WL'
export const WL_NAME = 'ワールドリーグ'
/** 顔ぶれ: もとのリーグ → クラブ数 */
export const WL_QUOTA: [string, number][] = [
  ['NPL1', 4],
  ['ENG1', 3],
  ['ESP1', 3],
  ['ITA1', 2],
  ['GER1', 2],
  ['FRA1', 2],
  ['BRA1', 2],
]
/** シーズン末に自分の国のリーグへ戻るクラブの数 */
export const WL_DOWN = 3
/** 申請の条件: NPL1 の通算優勝回数とクラブの格 */
export const APPLY_TITLES = 2
export const APPLY_REP = 70
/** 申請できるのはこの週まで（リーグの最終節） */
export const APPLY_LAST_WEEK = 40

const HOME_BY_COUNTRY: Record<string, string> = { JP: 'NPL1', EN: 'ENG1', ES: 'ESP1', IT: 'ITA1', DE: 'GER1', FR: 'FRA1', BR: 'BRA1' }

export interface LeagueMove {
  club: number
  from: Competition
  to: Competition
  /** 上がる・下がる（ワールドリーグとの入れ替え。国内の昇降格は段で決める） */
  dir?: 'up' | 'down'
}

export function worldLeague(state: GameState): Competition | undefined {
  return state.competitions.find((c) => c.id === WL_ID)
}

/** ワールドリーグのクラブが戻るリーグ */
export function homeLeagueOf(club: Club): string {
  return club.homeLeague ?? HOME_BY_COUNTRY[club.country] ?? 'NPL1'
}

/** NPL1 の通算優勝回数 */
export function npl1Titles(state: GameState): number {
  return (state.trophies ?? []).filter((t) => t.compId === 'NPL1').length
}

export interface WorldEligibility {
  titles: number
  rep: number
  inNpl1: boolean
  /** もうワールドリーグにいる */
  member: boolean
  applied: boolean
  /** 申請できる週か */
  open: boolean
  ok: boolean
}

export function worldEligibility(state: GameState): WorldEligibility {
  const me = state.clubs[state.playerClubId]
  const titles = npl1Titles(state)
  const inNpl1 = me.leagueId === 'NPL1'
  const member = me.leagueId === WL_ID
  const applied = state.worldApply?.season === state.season
  const open = state.week <= APPLY_LAST_WEEK
  return { titles, rep: me.rep, inNpl1, member, applied, open, ok: !!worldLeague(state) && !member && inNpl1 && titles >= APPLY_TITLES && me.rep >= APPLY_REP && open }
}

/** 申請する（シーズン末に参入する） */
export function applyWorldLeague(state: GameState): boolean {
  const e = worldEligibility(state)
  if (!e.ok || e.applied) return false
  state.worldApply = { season: state.season }
  state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'club', mine: true, text: `${WL_NAME}への参入を申請し、受理されました。シーズン末に参入します（NPL1 から降格しなければ）。` })
  return true
}

/** 申請を取り下げる */
export function withdrawWorldLeague(state: GameState) {
  if (state.worldApply?.season === state.season) state.worldApply = undefined
}

const COLORS: [string, string][] = [
  ['#0f766e', '#ffffff'],
  ['#7c2d12', '#fde68a'],
  ['#1e3a8a', '#f8fafc'],
  ['#be185d', '#ffffff'],
  ['#14532d', '#facc15'],
  ['#334155', '#f97316'],
]
const SUFFIX = ['FC', 'ユナイテッド', 'シティ', 'アスレチック', 'ヴィクトリー', 'ローヴァーズ']

/** 新しい日本のクラブ（NPL3 の空きを埋める） */
function newJapanClub(state: GameState, rng: Rng, rep: number): Club {
  const used = new Set(state.clubs.filter((c) => c.country === 'JP').map((c) => c.city))
  used.add(state.hometown.city)
  const town = HOMETOWNS.find((h) => !used.has(h.city)) ?? rng.pick(HOMETOWNS)
  const suffix = rng.pick(SUFFIX)
  const name = suffix === 'FC' ? `FC ${town.city}` : `${town.city}${suffix}`
  const [primary, secondary] = rng.pick(COLORS)
  const def: LeagueDef = { id: 'NPL3', name: '', short: 'NPL3', country: 'JP', tier: 3, clubs: [[name, town.city, primary, secondary, rep]] }
  const club = makeClub(state.clubs.length, def, 0, rng)
  club.city = town.city
  state.clubs.push(club)
  for (const role of CLUB_STAFF_ROLES) {
    const s = generateStaff(state, rng, role, club.id, rep * 0.75 + 12 + rng.normal(0, 7), 'JP')
    state.staff[s.id] = s
    club.staff.push(s.id)
  }
  const mgr = state.staff[club.staff[0]]
  const fav = Object.entries(mgr.formations ?? {}).sort((a, b) => b[1] - a[1])[0]?.[0] ?? '4-4-2'
  club.tactics = tacticsForStyle(mgr.style, fav)
  for (const p of generateSquad(state, rng, club.id)) state.players[p.id] = p
  club.lineup = autoLineup(state, club)
  return club
}

const avgRep = (state: GameState, ids: number[]) => ids.reduce((s, id) => s + state.clubs[id].rep, 0) / Math.max(1, ids.length)

/** ワールドリーグをつくる（クラブモード。日程を組む前に呼ぶ） */
export function formWorldLeague(state: GameState) {
  if (state.mode !== 'club' || worldLeague(state)) return
  const rng = createRng(hashSeed(state.seed, 0x7a11, state.season))
  const me = state.playerClubId
  const comp = (id: string) => state.competitions.find((c) => c.id === id)
  const wl: Competition = { id: WL_ID, kind: 'league', name: WL_NAME, short: 'WL', country: 'WORLD', tier: 1, season: state.season, clubIds: [], fixtures: [], table: [], promotion: 0, relegation: WL_DOWN, playoff: false, simulated: 'full' }
  const byRep = (ids: number[]) => ids.filter((id) => id !== me).sort((a, b) => state.clubs[b].rep - state.clubs[a].rep || a - b)
  const names: string[] = []
  for (const [lid, n] of WL_QUOTA) {
    const src = comp(lid)
    if (!src) continue
    for (const id of byRep(src.clubIds).slice(0, n)) {
      src.clubIds = src.clubIds.filter((x) => x !== id)
      const c = state.clubs[id]
      c.homeLeague = lid
      c.leagueId = WL_ID
      wl.clubIds.push(id)
      names.push(c.short)
    }
  }
  // NPL は 18 クラブのまま: 2 部・3 部の格の高いクラブを繰り上げ、3 部には新しいクラブ
  const [n1, n2, n3] = ['NPL1', 'NPL2', 'NPL3'].map((id) => comp(id)!)
  const moveUp = (from: Competition, to: Competition, k: number) => {
    for (const id of byRep(from.clubIds).slice(0, k)) {
      from.clubIds = from.clubIds.filter((x) => x !== id)
      to.clubIds.push(id)
      state.clubs[id].leagueId = to.id
    }
  }
  const lost = WL_QUOTA[0][1]
  moveUp(n2, n1, lost)
  moveUp(n3, n2, lost)
  const newRep = Math.round(avgRep(state, n3.clubIds) - 4)
  const added: string[] = []
  for (let i = 0; i < lost; i++) {
    const c = newJapanClub(state, rng, newRep)
    c.leagueId = n3.id
    n3.clubIds.push(c.id)
    added.push(c.name)
  }
  // ワールドリーグは国内のリーグのすぐあとに並べる
  const idx = state.competitions.findIndex((c) => c.id === 'NPL3')
  state.competitions.splice(idx + 1, 0, wl)
  // 格の戻り先（強いクラブが抜けたリーグは低く、ワールドリーグは高く）
  const anchors: Record<string, number> = { ...(state.repAnchors ?? {}) }
  for (const c of state.competitions) if (c.kind === 'league' && !c.hidden && c.id !== 'AMA') anchors[c.id] = avgRep(state, c.clubIds.filter((id) => id !== me))
  state.repAnchors = anchors
  const absWeek = absWeekOf(state.season, state.week)
  state.news.push({ absWeek, category: 'league', mine: true, text: `${WL_NAME}が発足！ 日本・欧州・南米の 18 クラブが世界一を争う（${names.join('・')}）。外国人枠はありません。` })
  state.news.push({ absWeek, category: 'league', mine: false, text: `リーグ再編: NPL の 2 部・3 部から 4 クラブずつ繰り上がり、NPL3 に ${added.join('・')} が加わった。` })
}

/**
 * シーズン末の入れ替え（国内の昇降格を決めたあと、移す前に呼ぶ）。
 * domestic: 国内の昇降格（自クラブが NPL1 から落ちるなら、申請は無効）
 */
export function planWorldLeague(state: GameState, domestic: LeagueMove[]): LeagueMove[] {
  const wl = worldLeague(state)
  if (!wl || state.mode !== 'club' || wl.table.length < WL_DOWN) return []
  const comp = (id: string) => state.competitions.find((c) => c.id === id)
  const npl1 = comp('NPL1')!
  const me = state.playerClubId
  const moving = new Set(domestic.map((m) => m.club))
  const playerJoins = state.worldApply?.season === state.season && state.clubs[me].leagueId === 'NPL1' && !moving.has(me)
  const out: LeagueMove[] = []
  const up = new Set<number>()
  let placed = false
  const down = wl.table.slice(-WL_DOWN).map((r) => r.clubId)
  for (const id of down) {
    const home = comp(homeLeagueOf(state.clubs[id]))
    if (!home) continue
    out.push({ club: id, from: wl, to: home, dir: 'down' })
    let upId: number | undefined
    if (home.id === 'NPL1' && playerJoins && !placed) {
      upId = me
      placed = true
    } else upId = home.table.map((r) => r.clubId).find((c) => c !== me && !up.has(c) && !moving.has(c) && home.clubIds.includes(c))
    if (upId !== undefined) {
      up.add(upId)
      out.push({ club: upId, from: home, to: wl, dir: 'up' })
    }
  }
  // 申請した自クラブ: 日本勢の最下位（残る中で）と入れ替え
  if (playerJoins && !placed) {
    const worstJp = [...wl.table]
      .reverse()
      .map((r) => r.clubId)
      .find((c) => state.clubs[c].country === 'JP' && !down.includes(c))
    if (worstJp !== undefined) {
      out.push({ club: worstJp, from: wl, to: npl1, dir: 'down' })
      out.push({ club: me, from: npl1, to: wl, dir: 'up' })
    }
  }
  return out
}

/** 入れ替えのあと: 戻るリーグを覚え、知らせる */
export function settleWorldMoves(state: GameState, moves: LeagueMove[]) {
  const absWeek = state.season * WEEKS_PER_SEASON + WEEKS_PER_SEASON - 1
  const me = state.playerClubId
  for (const m of moves) {
    const c = state.clubs[m.club]
    if (m.dir === 'up') c.homeLeague = m.from.id
    const mine = m.club === me
    if (m.dir === 'up') state.news.push({ absWeek, category: 'league', mine, text: mine ? `${c.name}、${WL_NAME}への参入が決定！ 来季は世界の強豪と戦う。` : `${c.name}（${m.from.short}）が来季の${WL_NAME}へ。` })
    else state.news.push({ absWeek, category: 'league', mine, text: mine ? `${c.name} は${WL_NAME}から${m.to.name}へ…。再び世界を目指す。` : `${c.name} は${WL_NAME}から${m.to.name}へ戻る。` })
  }
  state.worldApply = undefined
}

/** 今のリーグの格の戻り先（ワールドリーグができてからは、できたときの平均） */
export function repAnchorOf(state: GameState, leagueId: string, fallback: number | undefined): number | undefined {
  return state.repAnchors?.[leagueId] ?? fallback
}

/** 日本のクラブか（ワールドリーグの日本勢も含む。カップ戦の出場など） */
export function isJapanClub(club: Club): boolean {
  return club.country === 'JP' && club.leagueId !== 'AMA'
}

