/**
 * スポンサー契約。胸（shirt）・袖（sleeve）・スタジアム命名権（stadium）の 3 枠。
 * プレシーズンに空いている枠へ申し出が来る。額はクラブの格・人気・リーグ・街の経済力で決まる。
 */
import type { Rng } from '../core/prng'
import { absWeekOf } from '../core/calendar'
import { SPONSOR_COMPANIES, WORLD_SPONSOR_COMPANIES } from '../data/training'
import { WL_SPONSOR_MUL, inWorld } from '../club/worldClass'
import type { Club, SponsorContract, SponsorSlot } from '../models/club'
import { allocId, type GameState, type Offer } from '../models/game'
import { hasTrait } from '../club/town'

export const SLOT_LABEL: Record<SponsorSlot, string> = { shirt: '胸スポンサー', sleeve: '袖スポンサー', stadium: 'スタジアム命名権', global: 'グローバルパートナー' }
const SLOT_SHARE: Record<SponsorSlot, number> = { shirt: 1, sleeve: 0.35, stadium: 0.6, global: 1.4 }

/** 申し出が来る枠（グローバルパートナーはワールドリーグにいるときだけ） */
export function sponsorSlots(club: Club): SponsorSlot[] {
  return inWorld(club) ? ['shirt', 'sleeve', 'stadium', 'global'] : ['shirt', 'sleeve', 'stadium']
}

/** 枠の基準額（年額・万円） */
export function sponsorBase(state: GameState, club: Club, slot: SponsorSlot): number {
  const comp = state.competitions.find((c) => c.id === club.leagueId)
  const tierMul = inWorld(club) ? WL_SPONSOR_MUL : comp?.tier === 1 ? 2.2 : comp?.tier === 2 ? 1.3 : 1
  const town = club.isPlayer ? state.hometown.economy : 50
  // 工業の街（M19）: 1 割増
  const industry = hasTrait(state, 'industry', club) ? 1.1 : 1
  return Math.round(((1200 + club.rep * 90 + club.popularity * 70 + town * 25) * tierMul * SLOT_SHARE[slot] * industry) / 10) * 10
}

/** 契約からの年額の合計（スポンサーがいない枠はなし） */
export function sponsorIncome(club: Club): number {
  return (club.sponsors ?? []).reduce((s, c) => s + c.annual, 0)
}

/** 地元の小口スポンサー（いつもある少額の収入、年額） */
export function localSupport(state: GameState, club: Club): number {
  const town = club.isPlayer ? state.hometown.economy : 50
  return Math.round((800 + town * 20 + club.popularity * 25) * (hasTrait(state, 'industry', club) ? 1.1 : 1))
}

/** プレシーズンに空いている枠への申し出を作る */
export function makeSponsorOffers(state: GameState, club: Club, rng: Rng) {
  const now = absWeekOf(state.season, state.week)
  const taken = new Set((club.sponsors ?? []).filter((c) => c.until >= state.season).map((c) => c.slot))
  for (const slot of sponsorSlots(club)) {
    if (taken.has(slot)) continue
    if (state.offers.some((o) => o.kind === 'sponsor' && o.slot === slot)) continue
    const base = sponsorBase(state, club, slot)
    // ワールドリーグでは世界の企業から
    const names = rng.shuffle([...(inWorld(club) ? WORLD_SPONSOR_COMPANIES : SPONSOR_COMPANIES)]).slice(0, 3)
    // 安定型・成績ボーナス型・長期型
    const offers: Offer[] = [
      { kind: 'sponsor', slot, company: names[0], annual: Math.round((base * rng.range(0.95, 1.08)) / 10) * 10, years: 1, expiresAbsWeek: now + 4, id: allocId(state, 'offer') },
      { kind: 'sponsor', slot, company: names[1], annual: Math.round((base * rng.range(0.7, 0.8)) / 10) * 10, years: 1, bonus: { kind: 'rank', value: 3, amount: Math.round((base * 0.8) / 10) * 10 }, expiresAbsWeek: now + 4, id: allocId(state, 'offer') },
      { kind: 'sponsor', slot, company: names[2], annual: Math.round((base * rng.range(0.85, 0.92)) / 10) * 10, years: 3, expiresAbsWeek: now + 4, id: allocId(state, 'offer') },
    ]
    state.offers.push(...offers)
  }
}

export function acceptSponsor(state: GameState, club: Club, offerId: number): boolean {
  const o = state.offers.find((x) => x.id === offerId)
  if (!o || o.kind !== 'sponsor') return false
  const c: SponsorContract = { slot: o.slot, company: o.company, annual: o.annual, until: state.season + o.years - 1, bonus: o.bonus }
  club.sponsors = [...(club.sponsors ?? []).filter((x) => x.slot !== o.slot), c]
  state.offers = state.offers.filter((x) => !(x.kind === 'sponsor' && x.slot === o.slot))
  state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'club', mine: true, text: `${o.company}と${SLOT_LABEL[o.slot]}の契約を結びました（年 ${o.annual.toLocaleString()} 万円）。` })
  if (o.slot === 'stadium') club.stadium.name = `${o.company.replace(/(ホールディングス|食品|建設|電機|製菓|通信|自動車|不動産|運輸|航空|薬品|銀行|水産|旅行|化粧品|アパレル|乳業|エナジー|ゲームス)$/, '')}スタジアム${club.city}`
  return true
}

/** シーズン末: 成績ボーナスを払い、切れた契約を外す */
export function settleSponsors(state: GameState, club: Club, rank: number, promoted: boolean): number {
  let bonus = 0
  for (const c of club.sponsors ?? []) {
    if (!c.bonus) continue
    if ((c.bonus.kind === 'rank' && rank <= c.bonus.value) || (c.bonus.kind === 'promotion' && promoted)) bonus += c.bonus.amount
  }
  club.sponsors = (club.sponsors ?? []).filter((c) => c.until > state.season)
  if (!club.sponsors.some((c) => c.slot === 'stadium')) club.stadium.name = `${club.city}市民スタジアム`
  return bonus
}
