/**
 * キャリアの開始: 世界をつくり（自分のクラブはない）、主人公を生み出し、入団のオファーを 3 つ用意する。
 * 世界はクラブモードと同じ生成で、新クラブの枠は普通の AI クラブにする（NPL3 は 18 クラブのまま）。
 */
import { createRng, hashSeed, type Rng } from '../core/prng'
import { absWeekOf, WEEKS_PER_SEASON } from '../core/calendar'
import { createNewGame } from '../gen/worldGen'
import { generatePlayer, starterOvrForRep } from '../gen/playerGen'
import { ATTR_KEYS, type AttrKey } from '../data/attributes'
import type { GrowthType } from '../data/growth'
import type { Position } from '../data/positions'
import { PLAY_STYLE_BY_ID, REGION_NAME } from '../data/career'
import type { GameState } from '../models/game'
import type { FaceSpec } from '../models/face'
import type { Foot, Player, SquadRole } from '../models/player'
import type { CareerOffer, GrowthMode, PlayStyle } from '../models/career'
import { autoLineup, squadOf } from '../match/lineup'
import { ratingAt } from '../player/overall'
import { completeTransfer } from '../transfer/market'
import { castName, clamp, currentGen, regionOf, report } from './core'
import { newObjectives } from './manager'
import { assignPhotos } from '../player/photos'
import { relocateForRegion } from './homes'

export interface CareerNewOptions {
  seed: number
  startYear?: number
  /** 姓と名（空白区切り） */
  name: string
  style: PlayStyle
  pos: Position
  foot: Foot
  heightCm: number
  /** 体重（kg。省略時は身長からの目安） */
  weightKg?: number
  face?: FaceSpec
  /** 育成のしかた（省略時は easy） */
  growthMode?: GrowthMode
  /** 成長タイプ（ピーク年齢）。'random' はおまかせ（省略時は標準） */
  growthType?: GrowthType | 'random'
}

/** おまかせの成長タイプ（標準と晩成が多め） */
function randomGrowthType(seed: number): GrowthType {
  const r = createRng(hashSeed(seed, 0x6a0)).next()
  return r < 0.1 ? 'ultraEarly' : r < 0.3 ? 'early' : r < 0.65 ? 'normal' : r < 0.9 ? 'late' : 'ultraLate'
}

/** 新クラブの枠を置き換える AI クラブ */
const EXTRA_CLUB = { name: '小田原シーガルズ', short: '小田原', city: '小田原', colors: { primary: '#0e7490', secondary: '#ffffff' }, rep: 26 }

export function createCareerGame(opt: CareerNewOptions): GameState {
  const state = createNewGame({ seed: opt.seed, startYear: opt.startYear, clubName: EXTRA_CLUB.name, clubShort: EXTRA_CLUB.short, hometownIndex: 0, colors: EXTRA_CLUB.colors, noWorldLeague: true })
  // 自分のクラブの枠を、普通の AI クラブにする
  const extra = state.clubs[state.playerClubId]
  Object.assign(extra, { isPlayer: false, city: EXTRA_CLUB.city, rep: EXTRA_CLUB.rep, budget: 16000 })
  extra.stadium = { ...extra.stadium, name: `${EXTRA_CLUB.short}スタジアム` }
  extra.lineup = autoLineup(state, extra)
  state.news = []
  state.mode = 'career'

  const rng = createRng(hashSeed(opt.seed, 0xca7ee7))
  const p = makeProtagonist(state, rng, opt)
  state.players[p.id] = p
  const style = PLAY_STYLE_BY_ID[opt.style]
  state.career = {
    playerId: p.id,
    style: opt.style,
    exp: { power: 30, speed: 30, tech: 30, tactics: 30, mental: 30 },
    stamina: 100,
    trust: 50,
    fame: 3,
    money: 300,
    objectives: [],
    kotsu: { [style.kotsu]: 1 },
    bonds: {},
    done: {},
    talks: [{ eventId: 'sys_intro' }],
    offers: [],
    log: [],
    report: [],
    growthMode: opt.growthMode ?? 'easy',
    nextObjectiveId: 1,
    nextOfferId: 1,
  }
  makeRookieOffers(state, rng)
  assignPhotos(state)
  return state
}

/** 体格による最初の能力の差（身長 176cm・BMI 22 が基準） */
export function bodyBias(heightCm: number, weightKg: number): Partial<Record<AttrKey, number>> {
  const h = heightCm - 176
  const bmi = weightKg / (heightCm / 100) ** 2 - 22
  const r = (v: number) => Math.round(v * 10) / 10
  return {
    header: r(h * 0.35),
    jump: r(h * 0.2),
    agility: r(-h * 0.12 - bmi * 1.2),
    strength: r(bmi * 2.5 + h * 0.1),
    speed: r(-bmi * 1.4),
    stamina: r(-Math.max(0, bmi - 2) * 1.5),
  }
}

function makeProtagonist(state: GameState, rng: Rng, opt: CareerNewOptions): Player {
  const style = PLAY_STYLE_BY_ID[opt.style]
  const p = generatePlayer(state, rng, { clubId: -1, pos: opt.pos, targetOvr: 44, age: 18, nation: 'JP', country: 'JP', contractYears: -1, potentialOvr: 70 })
  for (const k of ATTR_KEYS) p.attr[k] = Math.round(clamp(p.attr[k] + (style.bias[k] ?? 0), 5, 72) * 10) / 10
  // 上限は表示用（主人公は経験点で伸びるので、実際の上限は使わない）
  for (const k of ATTR_KEYS) p.cap[k] = Math.min(99, Math.max(p.cap[k], p.attr[k] + 25))
  const [family, given] = opt.name.trim().split(/\s+/)
  p.name = given ? `${family} ${given}` : family
  p.short = family
  p.foot = opt.foot
  p.heightCm = opt.heightCm
  p.weightKg = opt.weightKg ?? Math.round(22 * (opt.heightCm / 100) ** 2)
  // 体格で最初の能力を少し変える（背が高いほど空中戦、重いほど当たりが強く、軽いほど速い）
  for (const [k, v] of Object.entries(bodyBias(opt.heightCm, p.weightKg)) as [AttrKey, number][]) p.attr[k] = Math.round(clamp(p.attr[k] + v, 5, 75) * 10) / 10
  p.face = opt.face
  p.growth = opt.growthType === 'random' ? randomGrowthType(opt.seed) : (opt.growthType ?? 'normal')
  p.personality = 'effort'
  p.traits = { ...p.traits, ambition: 16, professionalism: 15, workRate: 14, loyalty: 10, injuryProne: 6, consistency: 12, bigMatch: 12 }
  p.skills = []
  p.birthAbsWeek = absWeekOf(state.season, state.week) - 18 * WEEKS_PER_SEASON - rng.int(0, WEEKS_PER_SEASON - 1)
  p.condition = 60
  p.morale = 75
  return p
}

/** そのクラブでの立場の見込み（主人公のポジションの先発と比べる） */
export function expectedRole(state: GameState, p: Player, clubId: number): SquadRole {
  const club = state.clubs[clubId]
  const mine = ratingAt(p, p.pos)
  const rivals = squadOf(state, clubId)
    .filter((x) => x.id !== p.id && (x.pos === p.pos || (x.apt[p.pos] ?? 0) >= 80))
    .map((x) => ratingAt(x, p.pos))
    .sort((a, b) => b - a)
  const level = starterOvrForRep(club.rep, club.country)
  const best = rivals[0] ?? level - 10
  if (mine >= best + 3) return 'star'
  if (mine >= best - 2) return 'regular'
  if (mine >= best - 7) return 'rotation'
  return 'backup'
}

/** 入団のオファー（3 部から 2 つ、2 部から 1 つ） */
export function makeRookieOffers(state: GameState, rng: Rng) {
  const c = state.career!
  const p = state.players[c.playerId]
  const pick = (id: string, n: number) => rng.shuffle(state.competitions.find((x) => x.id === id)!.clubIds.filter((cid) => !state.clubs[cid].isPlayer)).slice(0, n)
  const clubs = [...pick('NPL3', 2), ...pick('NPL2', 1)]
  const now = absWeekOf(state.season, state.week)
  c.offers = clubs.map((clubId) => {
    const role = expectedRole(state, p, clubId)
    const tier = state.competitions.find((x) => x.id === state.clubs[clubId].leagueId)?.tier ?? 3
    const wage = Math.round(((tier === 2 ? 480 : 360) + (role === 'star' ? 120 : role === 'regular' ? 60 : 0) + rng.int(0, 6) * 10) / 10) * 10
    return { id: c.nextOfferId++, kind: 'rookie', clubId, fee: 0, wage, years: 3, role, expiresAbsWeek: now + 4 } satisfies CareerOffer
  })
}

const ROLE_TRUST: Record<SquadRole, number> = { star: 62, regular: 54, rotation: 46, backup: 38, prospect: 42 }

/** オファーを受けてクラブに入る（入団・移籍・更改の共通） */
/** ひとつ前の主人公（父）が海外のクラブでプレーしたか（一族の記録のクラブ名から） */
function parentAbroad(state: GameState): boolean {
  const last = state.career?.lineage?.[state.career.lineage.length - 1]
  return !!last?.clubs.some((name) => state.clubs.some((cl) => cl.name === name && cl.country !== 'JP'))
}

export function acceptOffer(state: GameState, offerId: number): boolean {
  const c = state.career!
  const o = c.offers.find((x) => x.id === offerId)
  const p = state.players[c.playerId]
  if (!o || !p) return false
  const until = state.season + o.years - (state.week >= 40 ? 0 : 1)
  if (o.kind === 'renewal') {
    p.contract = { ...p.contract, wage: o.wage, until, role: o.role }
    c.offers = c.offers.filter((x) => x.kind !== 'renewal')
    report(state, `${state.clubs[o.clubId].name}と契約を更新しました（年俸 ${o.wage.toLocaleString()} 万円・${o.years} 年）。`)
    return true
  }
  const fromClub = p.clubId
  const fromRegion = regionOf(state)
  completeTransfer(state, p, o.clubId, o.kind === 'rookie' ? 0 : o.fee, { wage: o.wage, until, role: o.role })
  state.playerClubId = o.clubId
  c.joinedAbsWeek = absWeekOf(state.season, state.week)
  c.trust = ROLE_TRUST[o.role]
  c.offers = []
  c.objectives = []
  newObjectives(state)
  const club = state.clubs[o.clubId]
  club.lineup = autoLineup(state, club)
  if (o.kind === 'rookie') {
    c.homeClubId = o.clubId
    c.talks.push({ eventId: 'sys_join', vars: { club: club.name } })
    report(state, `${club.name}に入団しました。プロとしての第一歩です。`)
  } else {
    c.talks.push({ eventId: 'sys_transfer', vars: { club: club.name, from: fromClub >= 0 ? state.clubs[fromClub].name : '' } })
    report(state, `${club.name}へ移籍しました（移籍金 ${o.fee.toLocaleString()} 万円）。`)
    // 国が変わったとき: 海外へ・別の国へ・日本へ（会える人とおでかけ先が変わる）
    const toRegion = regionOf(state)
    const pid = c.spouse ?? c.partner
    if (fromRegion === 'JP' && toRegion !== 'JP') {
      const partnerLine = pid ? `${castName(state, pid) ?? ''}さんも、一緒に来てくれることになりましたね。` : '新しい出会いも、きっとありますよ。'
      c.talks.push({ eventId: 'sys_abroad', vars: { country: REGION_NAME[toRegion], partnerLine } })
      if (currentGen(state) >= 2) {
        // 子どもの世代: 親の代からの通訳のフセインが迎えに来る（欧州の名将の話は親の代だけ）
        if (c.done.g2o_hussein === undefined && !c.talks.some((t) => t.eventId === 'g2o_hussein')) {
          c.talks.push({ eventId: 'g2o_hussein', vars: { legacy: parentAbroad(state) ? '君のお父さんの通訳も、わたしがしたんだよ。' : '君のことは、日本のニュースで見ていたよ。' } })
          // 親の代の「はじめまして」はもう済んだことにする（このあとのおでかけは語学レッスンから）
          c.done.hussein_1 ??= absWeekOf(state.season, state.week)
        }
      } else if (toRegion !== 'BR' && c.done.sys_renoir === undefined) c.talks.push({ eventId: 'sys_renoir' })
    } else if (fromRegion !== 'JP' && toRegion !== 'JP' && fromRegion !== toRegion) c.talks.push({ eventId: 'sys_newcountry', vars: { country: REGION_NAME[toRegion] } })
    else if (fromRegion !== 'JP' && toRegion === 'JP') c.talks.push({ eventId: 'sys_homecoming' })
    // 国が変わったら、住める家へ引っ越す（欧州の家はその国だけ）
    if (fromRegion !== toRegion) relocateForRegion(state)
  }
  return true
}
