/** 古いセーブを今の形に直す。schemaVersion を上げたらここに変換を足す。 */
import { SCHEMA_VERSION, type GameState } from '../models/game'
import { createCup, ensureAmateurClubs } from '../competition/cup'
import { ACC_GROUP_WEEKS, createContinental } from '../competition/continental'
import { ensureAsiaClubs } from '../gen/worldGen'
import { emptyRecords } from '../models/game'
import { assignPhotos } from '../player/photos'
import { setOwnerGoals } from '../club/owner'
import { migrateScoutWatch, requalifyReports } from '../scout/reports'
import { backfillPower } from '../club/power'
import { migrateAcademyBusiness } from '../club/academy'

type Migration = (s: GameState) => void

/** MIGRATIONS[n] は version n → n+1 の変換 */
const MIGRATIONS: Record<number, Migration> = {
  // v1 → v2: 財務の帳簿とシーズンの記録
  1: (s) => {
    s.finance ??= []
    s.seasons ??= []
  },
  // v2 → v3: 資金難の管理と申し出
  2: (s) => {
    s.money ??= { negWeeks: 0, bailouts: 0 }
    s.offers ??= []
    s.nextId.offer ??= 1
  },
  // v3 → v4: スカウト・移籍・連携
  3: (s) => {
    s.scout ??= { knowledge: {}, missions: [], watch: [] }
    s.forSale ??= {}
    s.transfers ??= []
    s.chem ??= {}
    ensureAmateurClubs(s)
    if (!s.competitions.some((c) => c.id === 'CUP') && s.week < 6) createCup(s)
  },
  // v4 → v5: アジアのクラブ・大陸大会・記録と殿堂
  4: (s) => {
    s.records ??= emptyRecords()
    s.trophies ??= []
    s.hallOfFame ??= []
    ensureAsiaClubs(s)
    if (s.week < ACC_GROUP_WEEKS[0]) createContinental(s)
  },
  // v5 → v6: モード（クラブ経営／キャリア）
  5: (s) => {
    s.mode ??= 'club'
  },
}

export function migrate(state: GameState): GameState {
  let v = state.schemaVersion ?? 1
  while (v < SCHEMA_VERSION) {
    MIGRATIONS[v]?.(state)
    v++
  }
  state.schemaVersion = SCHEMA_VERSION
  // 優勝のセレモニー（M16）: 前からあるタイトルは祝い済みにする
  state.celebrated ??= state.trophies?.length ?? 0
  // スカウトの報告（M21）: スカウトが注目に自動で入れた選手を報告へ移す
  migrateScoutWatch(state)
  requalifyReports(state)
  // 海外アカデミー（M25）: 事業からユースアカデミーへ移す
  migrateAcademyBusiness(state)
  // クラブの総合力（M23）: 推移の記録がなければ、過去のシーズンを推定で埋める
  backfillPower(state)
  // オーナーの目標（M19）: 古いセーブは読み込んだときに今季の目標を決める
  if (!state.owner && state.mode !== 'career') setOwnerGoals(state)
  // ID カウンタが既存の最大値を下回っていたら直す（念のため）
  const maxP = Math.max(0, ...Object.keys(state.players).map(Number))
  const maxS = Math.max(0, ...Object.keys(state.staff).map(Number))
  if (state.nextId.player <= maxP) state.nextId.player = maxP + 1
  if (state.nextId.staff <= maxS) state.nextId.staff = maxS + 1
  // 生成した写真を割り当てる（写真が増えたあとに古いセーブを開いたときも）
  assignPhotos(state)
  return state
}
