/** リーグ戦: 日程（ホーム＆アウェイの総当たり）と順位表。 */
import type { Rng } from '../core/prng'
import { absWeekOf, weekOfMatchday } from '../core/calendar'
import type { Competition, Fixture, TableRow } from '../models/competition'
import { allocId, type GameState } from '../models/game'

/**
 * 円卓方式で総当たりの組み合わせを作る（n は偶数）。
 * 前半 n-1 節、後半はホームとアウェイを入れ替えて同じ順。
 */
export function roundRobin(clubIds: number[], rng: Rng): [number, number][][] {
  const ids = rng.shuffle([...clubIds])
  if (ids.length % 2 === 1) ids.push(-1)
  const n = ids.length
  const rounds: [number, number][][] = []
  const arr = [...ids]
  for (let r = 0; r < n - 1; r++) {
    const pairs: [number, number][] = []
    for (let i = 0; i < n / 2; i++) {
      const a = arr[i]
      const b = arr[n - 1 - i]
      if (a < 0 || b < 0) continue
      // ホームとアウェイが偏らないよう交互に
      pairs.push((r + i) % 2 === 0 ? [a, b] : [b, a])
    }
    rounds.push(pairs)
    // 先頭を固定して回す
    arr.splice(1, 0, arr.pop()!)
  }
  const second = rounds.map((rd) => rd.map(([h, a]) => [a, h] as [number, number]))
  return [...rounds, ...second]
}

export function scheduleLeague(state: GameState, comp: Competition, rng: Rng) {
  const rounds = roundRobin(comp.clubIds, rng)
  comp.fixtures = []
  rounds.forEach((pairs, round) => {
    const week = weekOfMatchday(Math.min(round, 33))
    for (const [home, away] of pairs) {
      const f: Fixture = {
        id: allocId(state, 'fixture'),
        compId: comp.id,
        round,
        absWeek: absWeekOf(comp.season, week),
        slot: 'weekend',
        home,
        away,
      }
      comp.fixtures.push(f)
    }
  })
  comp.table = comp.clubIds.map((clubId) => emptyRow(clubId))
}

export function emptyRow(clubId: number): TableRow {
  return { clubId, played: 0, won: 0, drawn: 0, lost: 0, gf: 0, ga: 0, points: 0, form: '' }
}

/** 試合結果を順位表に反映する */
export function applyResultToTable(comp: Competition, f: Fixture) {
  if (!f.result) return
  const { hg, ag } = f.result
  const h = comp.table.find((r) => r.clubId === f.home)
  const a = comp.table.find((r) => r.clubId === f.away)
  if (!h || !a) return
  h.played++
  a.played++
  h.gf += hg
  h.ga += ag
  a.gf += ag
  a.ga += hg
  if (hg > ag) {
    h.won++
    a.lost++
    h.points += 3
    h.form = (h.form + 'W').slice(-5)
    a.form = (a.form + 'L').slice(-5)
  } else if (hg < ag) {
    a.won++
    h.lost++
    a.points += 3
    h.form = (h.form + 'L').slice(-5)
    a.form = (a.form + 'W').slice(-5)
  } else {
    h.drawn++
    a.drawn++
    h.points++
    a.points++
    h.form = (h.form + 'D').slice(-5)
    a.form = (a.form + 'D').slice(-5)
  }
}

/** 勝点 → 得失点差 → 総得点 → クラブ id の順で並べる */
export function sortTable(comp: Competition) {
  comp.table.sort((x, y) => y.points - x.points || y.gf - y.ga - (x.gf - x.ga) || y.gf - x.gf || x.clubId - y.clubId)
}

export function rankOf(comp: Competition, clubId: number): number {
  return comp.table.findIndex((r) => r.clubId === clubId) + 1
}
