/**
 * 毎週の成長・衰え・調子・疲労・ケガの回復。
 * 成長: 上限までの残り（cap - attr）のうち、年齢カーブに応じた割合を毎週伸ばす。
 *   割合 = その年齢の伸び ÷ その年齢から先の伸びの合計（成長タイプの山の位置で自然に伸びる時期が決まる）
 *   × 練習の配分・コーチ・施設・性格・出場時間（M4 で練習メニューと合わせて本格化）
 * 衰え: 年齢カーブの衰え × 能力グループの係数（瞬発系は早く落ち、知性は 35 歳ごろまで伸びる）
 */
import { careerDeclineMul } from '../career/core'
import type { Rng } from '../core/prng'
import { WEEKS_PER_SEASON } from '../core/calendar'
import { ATTR_BY_KEY, ATTR_KEYS, type AttrKey, type GrowthGroup } from '../data/attributes'
import { GROWTH_TYPES, ageCurve, groupDownFactor, groupUpFactor, type GrowthType } from '../data/growth'
import { PERSONALITY_DEFS } from '../data/personality'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import type { TrainingPlan } from '../models/club'
import { CAMP_PLACES, INTENSITY, defaultTraining, trainingFocus, type CampPlace } from '../data/training'
import { coachEffects, type CoachEffects } from '../staff/effects'
import { bizLevel } from '../economy/business'
import { hasTrait } from '../club/town'
import { studyFocus } from '../club/academy'

/** 年齢 a から 37 歳までの伸びの合計（0.25 歳刻みの表） */
const REMAIN: Record<GrowthType, number[]> = (() => {
  const out = {} as Record<GrowthType, number[]>
  for (const g of GROWTH_TYPES) {
    const arr: number[] = []
    for (let i = 0; i <= 120; i++) {
      const age = 14 + i * 0.25
      let s = 0
      for (let a = age; a < 37; a += 0.25) s += ageCurve(g, a).up * 0.25
      arr.push(s)
    }
    out[g] = arr
  }
  return out
})()

function remainingUp(g: GrowthType, age: number): number {
  const i = Math.max(0, Math.min(120, Math.round((age - 14) * 4)))
  return REMAIN[g][i]
}

/** 練習メニュー（M4 で選べるようにする）。値は能力ごとの伸びやすさの倍率 */
export type TrainingFocus = Partial<Record<AttrKey, number>>

export interface GrowthContext {
  /** 練習の配分による倍率（能力ごと） */
  focus?: TrainingFocus
  /** コーチ・施設などをまとめた倍率 */
  mul: number
  /** 衰えの倍率（キャリアの主人公のスポーツ科学チームなど。省略時は 1） */
  declineMul?: number
}

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

/** 能力ごとの成長のグループ（ATTR_KEYS の順）と、グループごとの係数の置き場（growPlayer の中で使い回す） */
const ATTR_GROWTH: GrowthGroup[] = ATTR_KEYS.map((k) => ATTR_BY_KEY[k].growth)
const GROWTH_GROUPS: GrowthGroup[] = [...new Set(ATTR_GROWTH)]
const GROUP_CACHE_UP = {} as Record<GrowthGroup, number>
const GROUP_CACHE_DOWN = {} as Record<GrowthGroup, number>

/** 1 週間の成長と衰え */
export function growPlayer(p: Player, absWeek: number, ctx: GrowthContext, rng: Rng) {
  const age = (absWeek - p.birthAbsWeek) / WEEKS_PER_SEASON
  const { up, down } = ageCurve(p.growth, age)
  const remain = Math.max(0.6, remainingUp(p.growth, age))
  const pers = PERSONALITY_DEFS[p.personality].growthMul
  const skillMul = p.skills.includes('fastLearner') ? 1.12 : p.skills.includes('lazy') ? 0.85 : 1
  // 出場時間（直近の出場率）: 試合に出ているほど伸びる
  const play = p.stats.apps > 0 ? clamp(p.stats.minutes / Math.max(1, p.stats.apps * 90), 0.3, 1) : 0.5
  const playMul = 0.8 + 0.4 * play
  // その週に伸ばす割合（年齢カーブの形で、残りを伸ばし切る）
  const frac = clamp((up / WEEKS_PER_SEASON / remain) * 1.05, 0, 0.06)
  const noise = 0.85 + rng.next() * 0.3
  // 能力グループごとの年齢の係数は、選手ごとに 1 回だけ（計算の順番は前と同じ。結果は変わらない）
  const upF = GROUP_CACHE_UP
  const downF = GROUP_CACHE_DOWN
  for (const g of GROWTH_GROUPS) {
    upF[g] = groupUpFactor(g, age)
    downF[g] = groupDownFactor(g, age)
  }
  const focus = ctx.focus
  for (let i = 0; i < ATTR_KEYS.length; i++) {
    const k = ATTR_KEYS[i]
    const g = ATTR_GROWTH[i]
    const head = p.cap[k] - p.attr[k]
    let delta = 0
    if (head > 0) delta += head * frac * upF[g] * ctx.mul * (focus?.[k] ?? 1) * pers * skillMul * playMul * noise
    // 衰え（知性は負の係数 = 衰え期にも少し伸びる）
    if (down > 0) {
      const f = downF[g]
      delta -= (down / WEEKS_PER_SEASON) * f * (f > 0 ? (ctx.declineMul ?? 1) : 1)
    }
    if (delta !== 0) {
      let v = p.attr[k] + delta
      // 上限を超えて伸びない（知性の「衰え期の伸び」も上限まで）
      if (delta > 0) v = Math.min(v, Math.max(p.attr[k], p.cap[k]))
      p.attr[k] = Math.round(clamp(v, 1, 99) * 100) / 100
    }
  }
}

/** 調子・疲労・ケガ・出場停止などの週次の変化 */
export function weeklyCondition(p: Player, rng: Rng, medicalLevel: number) {
  const pd = PERSONALITY_DEFS[p.personality]
  // 調子: 50 に戻ろうとしながら揺れる
  p.condition = clamp(p.condition + rng.normal(0, 9 * pd.conditionVar) + (52 - p.condition) * 0.18, 5, 100)
  // 疲労の回復
  p.fatigue = clamp(p.fatigue - (13 + medicalLevel * 1.5 + pd.recover), 0, 100)
  // ケガの回復
  if (p.injury) {
    p.injury.weeks -= 1 + (medicalLevel >= 4 && rng.chance(0.15) ? 1 : 0)
    if (p.injury.weeks <= 0) p.injury = null
  }
  // やる気は 60 に少しずつ戻る
  p.morale = clamp(p.morale + (60 - p.morale) * 0.06, 0, 100)
}

/** 全選手の 1 週間（練習計画・コーチ・施設・合宿を反映） */
export function weeklyPlayers(state: GameState, rng: Rng, absWeek: number, squads?: Map<number, Player[]>) {
  // クラブごとの練習の効果を先にまとめる
  const clubCtx = new Map<number, { plan: TrainingPlan; coach: CoachEffects; camp?: CampPlace; focusField: Partial<Record<AttrKey, number>>; focusGk: Partial<Record<AttrKey, number>>; f: { gk?: Partial<Record<AttrKey, number>>; field?: Partial<Record<AttrKey, number>> }; onsen: boolean; highland: boolean }>()
  for (const club of state.clubs) {
    const plan = club.training ?? AI_PLAN
    const camp = club.camp && absWeek >= club.camp.startAbsWeek && absWeek < club.camp.startAbsWeek + club.camp.weeks ? CAMP_PLACES.find((c) => c.name === club.camp!.place) : undefined
    clubCtx.set(club.id, { plan, coach: coachEffects(state, club), camp, focusField: trainingFocus(plan, false), focusGk: trainingFocus(plan, true), f: {}, onsen: hasTrait(state, 'onsen', club), highland: hasTrait(state, 'highland', club) })
  }
  const list = squads ? [...squads.values()].flat().concat(Object.values(state.players).filter((p) => !p.retired && p.clubId < 0)) : Object.values(state.players)
  for (const p of list) {
    if (p.retired) continue
    const club = p.clubId >= 0 ? state.clubs[p.clubId] : undefined
    const age = (absWeek - p.birthAbsWeek) / WEEKS_PER_SEASON
    if (!club) {
      // キャリアの主人公（ユース期・入団前）は経験点で伸びるので、自動の伸びは 0（衰えだけ）
      const me = state.career?.playerId === p.id
      growPlayer(p, absWeek, me ? { mul: 0, declineMul: careerDeclineMul(state) } : { mul: 0.55 }, rng)
      weeklyCondition(p, rng, 0)
      continue
    }
    const ctx = clubCtx.get(club.id)!
    const fac = club.facilities
    const inten = INTENSITY[ctx.plan.intensity]
    const ind = ctx.plan.individual[p.id]
    const gk = p.pos === 'GK'
    const focus = ind?.menu ? trainingFocus(ctx.plan, gk, ind.menu) : gk ? ctx.focusGk : ctx.focusField
    // 能力グループごとのコーチの倍率を掛ける（個別練習のない選手はクラブ・GK かどうかで同じなので使い回す）
    const cacheKey = ind?.menu ? undefined : gk ? 'gk' : 'field'
    let f = cacheKey ? ctx.f[cacheKey] : undefined
    if (!f) {
      f = {}
      for (const k of ATTR_KEYS) f[k] = (focus[k] ?? 0.45) * ctx.coach.group[ATTR_BY_KEY[k].group]
      // 高原の街（M19）: スタミナとスピードが伸びやすい
      if (ctx.highland) {
        f.stamina = (f.stamina ?? 0) * 1.12
        f.speed = (f.speed ?? 0) * 1.08
      }
      if (cacheKey) ctx.f[cacheKey] = f
    }
    // 留学中（M25）: その国の得意の能力が伸びやすい
    const st = p.study ? studyFocus(state, p, absWeek) : null
    if (st) {
      f = { ...f }
      for (const k of st.attrs) f[k] = (f[k] ?? 0.45) * st.mul
    }
    const facMul = 0.82 + fac.training * 0.06 + (age < 22 ? fac.dorm * 0.025 + fac.youth * 0.02 : 0)
    // キャリアの主人公は経験点で伸びるので、自動の伸びは 0（衰えだけ当たる）
    const me = state.career?.playerId === p.id
    const mul = me ? 0 : facMul * ctx.coach.all * inten.growth * (ctx.camp?.growth ?? 1) * (p.injury ? 0.2 : 1)
    growPlayer(p, absWeek, { mul, focus: f, declineMul: me ? careerDeclineMul(state) : 1 }, rng)
    // 温泉の街（M19）: 疲れが抜けやすい（医療の Lv 1.5 ぶん）
    weeklyCondition(p, rng, fac.medical + ctx.coach.medical * 2 + (club.isPlayer ? bizLevel(state, club, 'clinic') * 0.3 : 0) + (ctx.onsen ? 1.5 : 0))
    p.fatigue = clamp(p.fatigue + inten.fatigue - ctx.coach.recover - (ctx.camp?.fatigue ?? 0), 0, 100)
    // コンバート（目標のポジションの適性が上がる）
    if (ind?.convert && !p.injury) {
      const cur = p.apt[ind.convert] ?? 0
      if (cur < 100) p.apt[ind.convert] = Math.min(100, cur + (1.1 + fac.training * 0.25) * (age < 24 ? 1.3 : age > 30 ? 0.6 : 1))
    }
    // 練習中のケガ
    if (!p.injury) {
      const risk = 0.0018 * inten.injury * (1 + p.fatigue / 60) * (p.skills.includes('glassBody') ? 2 : 1) * (p.skills.includes('tireless') ? 0.5 : 1) * (1 - fac.medical * 0.06)
      if (rng.chance(risk)) {
        p.injury = rollInjury(rng, fac.medical, p.skills.includes('glassBody'))
        if (p.injury.weeks > 4) p.injury.weeks = Math.ceil(p.injury.weeks / 2)
        if (club.isPlayer) state.news.push({ absWeek, category: 'injury', mine: true, text: `${p.name} が練習中に${p.injury.name}（全治 ${p.injury.weeks} 週）` })
      }
    }
  }
}

/** AI クラブの練習（均等） */
const AI_PLAN: TrainingPlan = defaultTraining()

/** ケガの種類と期間 */
const INJURIES: [string, number, number, number][] = [
  ['打撲', 1, 1, 40],
  ['捻挫', 2, 3, 25],
  ['肉離れ', 3, 6, 20],
  ['骨折', 8, 12, 8],
  ['靭帯損傷', 16, 30, 4],
  ['重傷', 30, 40, 3],
]

export function rollInjury(rng: Rng, medicalLevel: number, glass: boolean): { name: string; weeks: number } {
  const i = rng.weighted(INJURIES.map((x) => x[3] * (x[1] >= 8 && glass ? 1.8 : 1)))
  const [name, lo, hi] = INJURIES[i]
  const weeks = Math.max(1, Math.round(rng.int(lo, hi) * (1 - medicalLevel * 0.05)))
  return { name, weeks }
}
