/**
 * 家族: 恋人 → プロポーズ → 結婚 → 子ども。
 *   プロポーズ: 恋人になって 30 週以上・絆 95 以上・寮を出ている。断られる（先送り）と半シーズンあとにまた話が出る
 *   子ども: 結婚して 1 シーズン以上・マンションか一軒家。ときどき（2 人まで）
 * 会話の話し手 'partner' は、結婚相手（いなければ恋人）に読み替える。
 * 恋人・家族の出来事（M10）: 恋人なら約 5 週、家族なら約 4 週ごとに、能力につながる出来事を 1 つ（partnerEventsWeek）。
 *   恋人の個性で出やすい出来事と台詞が変わる。乱数は専用の流れ（ほかの処理の並びを変えない）
 */
import type { Rng } from '../core/prng'
import { createRng, hashSeed } from '../core/prng'
import { PARTNER_EVENTS, PARTNER_FLAVOR, TRAIT_WEIGHT } from './dialogue/partner_events'
import { absWeekOf } from '../core/calendar'
import { BOY_NAMES, CAST_BY_ID, GIRL_NAMES } from '../data/career'
import type { GameState } from '../models/game'
import { queueTalk } from './events'
import { castName, report } from './core'
import { childrenWeek, oldestChildAge } from './children'
import { homeGrade, housingOf, mainCarOf } from './homes'
import { CAR_BY_ID } from '../data/career'

/** 結婚相手（いなければ恋人）の id */
export function partnerId(state: GameState): string | undefined {
  const c = state.career
  return c?.spouse ?? c?.partner
}

export function partnerName(state: GameState): string {
  const id = partnerId(state)
  return id ? (castName(state, id) ?? '') : ''
}

const queued = (state: GameState, id: string) => state.career!.talks.some((t) => t.eventId === id)

/** 出来事を起こせる段階か（恋人 → 結婚 → 子ども）と、試合の週だけの出来事 */
function eligible(state: GameState, id: string, matchWeek: boolean): boolean {
  const c = state.career!
  if (id === 'pt_cheer' || id === 'fm_watch') return matchWeek && (id === 'pt_cheer' || !!c.spouse)
  // 子どもとボール遊びは 2 歳から、運動会は 5 歳から
  if (id === 'fm_kidball') return !!c.spouse && oldestChildAge(state) >= 2
  if (id === 'fm_sports') return !!c.spouse && oldestChildAge(state) >= 5
  if (id.startsWith('fm_')) return !!c.spouse
  return true
}

/** 恋人・家族の出来事を予約する（会話が残っているときは待つ。同じ出来事は 12 週あける） */
export function partnerEventsWeek(state: GameState) {
  const c = state.career!
  const pid = partnerId(state)
  if (!pid || c.talks.length) return
  const now = absWeekOf(state.season, state.week)
  // 庭のある家・ミニバンだと家族の出来事が少し早く来る
  const main = mainCarOf(state)
  const familyBoost = !!housingOf(state).perk?.kids || (!!main && !!CAR_BY_ID[main].family)
  const gap = c.spouse ? (familyBoost ? 3 : 4) : 5
  if (now - (c.partnerEventAbsWeek ?? c.loverAbsWeek ?? now) < gap) return
  const clubId = state.players[c.playerId].clubId
  const matchWeek = state.competitions.some((comp) => comp.fixtures.some((f) => f.absWeek === now && (f.home === clubId || f.away === clubId)))
  const trait = CAST_BY_ID[pid]?.trait ?? 'cheer'
  const cands = PARTNER_EVENTS.filter((e) => eligible(state, e.id, matchWeek) && (c.done[e.id] === undefined || now - c.done[e.id] >= 12))
  if (!cands.length) return
  const rng = createRng(hashSeed(state.seed, now, 0x2ad))
  const weights = cands.map((e) => (TRAIT_WEIGHT[trait][e.id] ?? 1) * (e.id === 'pt_cheer' || e.id === 'fm_watch' ? 2 : 1))
  let r = rng.next() * weights.reduce((a, b) => a + b, 0)
  let ev = cands[cands.length - 1]
  for (let i = 0; i < cands.length; i++) {
    r -= weights[i]
    if (r <= 0) {
      ev = cands[i]
      break
    }
  }
  const kids = c.children ?? []
  queueTalk(state, ev.id, { partner: castName(state, pid) ?? '', flavor: PARTNER_FLAVOR[ev.id]?.[trait] ?? '', child: kids[kids.length - 1]?.name ?? '' })
  c.partnerEventAbsWeek = now
}

export function familyWeek(state: GameState, rng: Rng) {
  const c = state.career!
  const now = absWeekOf(state.season, state.week)
  if (c.partner && c.loverAbsWeek === undefined) c.loverAbsWeek = now
  const pid = partnerId(state)
  if (!pid) return
  const vars = { partner: castName(state, pid) ?? '' }
  // 恋人ができて寮暮らしのままなら、代理人が引っ越しを勧める（一度だけ）
  if (c.partner && homeGrade(state) === 0 && now - (c.loverAbsWeek ?? now) >= 20 && c.done.sys_moveHint === undefined && !queued(state, 'sys_moveHint')) queueTalk(state, 'sys_moveHint', vars)
  // プロポーズ
  if (!c.spouse && c.partner) {
    const bond = c.bonds[c.partner]?.value ?? 0
    const asked = c.done.fam_propose
    const ready = now - (c.loverAbsWeek ?? now) >= 30 && bond >= 95 && homeGrade(state) > 0 && (asked === undefined || now - asked >= 24)
    if (ready && !queued(state, 'fam_propose')) queueTalk(state, 'fam_propose', vars)
  }
  // 子ども
  if (c.spouse && c.marriedAbsWeek !== undefined) {
    const kids = c.children ?? []
    const last = kids.length ? kids[kids.length - 1].bornAbsWeek : c.marriedAbsWeek
    const home = homeGrade(state) >= 2
    // 3 人目（M17）は別の乱数で決める（2 人までの家族の乱数の並びを変えない）
    const ready = home && now - c.marriedAbsWeek >= 48 && now - last >= 96
    const third = ready && kids.length === 2 && createRng(hashSeed(state.seed, now, 0xc41d)).chance(0.03)
    if ((kids.length < 2 && ready && rng.chance(0.05)) || third) {
      // 性別と名前（M17。乱数を使わず、種と週から決める）
      const h = hashSeed(state.seed, now, kids.length)
      const sex: 'boy' | 'girl' = h % 2 === 0 ? 'boy' : 'girl'
      const pool = (sex === 'boy' ? BOY_NAMES : GIRL_NAMES).filter((n) => !kids.some((k) => k.name === n))
      const name = pool[(h >>> 3) % pool.length]
      c.children = [...kids, { name, bornAbsWeek: now, sex }]
      queueTalk(state, 'fam_baby', { ...vars, child: name })
      report(state, `家族が増えた！ 子どもの名前は「${name}」。`)
    }
  }
  // 子どもの節目と家族の行事、恋人・家族の出来事（能力につながる）
  childrenWeek(state)
  partnerEventsWeek(state)
}

/** プロポーズを受けてもらった（会話の効果 marry） */
export function marry(state: GameState) {
  const c = state.career!
  if (!c.partner || c.spouse) return
  const now = absWeekOf(state.season, state.week)
  c.spouse = c.partner
  c.marriedAbsWeek = now
  queueTalk(state, 'fam_wedding', { partner: castName(state, c.partner) ?? '' })
  report(state, `${castName(state, c.partner) ?? ''}と結婚した。`)
}

/** その人との関係の呼び方（妻・恋人。どちらでもなければ undefined） */
export function relationLabel(state: GameState, id: string): string | undefined {
  const c = state.career
  if (!c) return undefined
  if (c.spouse === id) return '妻'
  if (c.partner === id) return '恋人'
  return undefined
}

/** その人の役どころ（結婚した相手は「妻」） */
export function roleLabel(state: GameState, id: string): string {
  return state.career?.spouse === id ? '妻' : (CAST_BY_ID[id]?.role ?? '')
}
