/**
 * 高校・ユース大会の有望株（M19。クラブモード）。
 *   第 21 週（冬の高校選手権のあと）に 5 人が話題になる（世界の選手にはまだ入れない。state.prospects）
 *   入団を申し込める（役割の約束と契約金）。ほかのクラブも狙っていて、第 30 週に本人が決める
 *   決め手: クラブの格・ユースの施設・地元出身・契約金・役割・ライバルの数。申し込まなかった子は AI のクラブか大学へ
 * 乱数は種とシーズンから（ほかの処理の並びを変えない）。
 */
import { absWeekOf } from '../core/calendar'
import { createRng, hashSeed } from '../core/prng'
import { generatePlayer } from '../gen/playerGen'
import { HOMETOWNS } from '../data/clubs'
import type { Position } from '../data/positions'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import { fairWage, ovr, potentialOvr } from '../player/overall'
import { trimSquad } from '../transfer/ai'
import { rosterInfo } from './roster'

export const PROSPECT_WEEK = 21
export const PROSPECT_DEADLINE = 30
export const PROSPECT_BONUSES = [0, 1000, 3000]

export interface Prospect {
  player: Player
  source: string
  team: string
  pref: string
  /** 狙っている AI のクラブ */
  interest: number[]
  applied?: { role: 'main' | 'develop'; bonus: number }
}

const SCHOOL_TOWNS = ['青葉', '桜丘', '星稜', '旭', '若葉', '光陵', '東陵', '南山', '北斗', '白鷺', '紅陵', '城北']
const POSITIONS: Position[] = ['ST', 'WG', 'AM', 'CM', 'DM', 'CB', 'SB', 'GK']

/** 有望株を発表する（第 21 週。クラブモード） */
export function announceProspects(state: GameState) {
  if (state.mode === 'career') return
  const me = state.clubs[state.playerClubId]
  const rng = createRng(hashSeed(state.seed, state.season, 0x9205))
  const tier = state.competitions.find((c) => c.id === me.leagueId)?.tier ?? 3
  const prefs = [...new Set(HOMETOWNS.map((h) => h.pref))]
  // ワールドリーグ（M24）の日本勢は世界から獲るので、高校・ユースの有望株は狙わない
  const ai = state.clubs.filter((c) => c.country === 'JP' && !c.isPlayer && c.leagueId !== 'AMA' && c.leagueId !== 'WL')
  const list: Prospect[] = []
  for (let i = 0; i < 5; i++) {
    const pos = POSITIONS[(i * 3 + state.season) % POSITIONS.length]
    const potential = rng.int(68, 86)
    const target = 40 + (3 - tier) * 3 + rng.int(0, 8)
    const p = generatePlayer(state, rng, { clubId: -1, pos, targetOvr: target, age: 18, nation: 'JP', country: 'JP', contractYears: -1, potentialOvr: potential })
    // 1 人は地元出身
    const pref = i === 0 ? state.hometown.pref : rng.pick(prefs)
    const school = rng.chance(0.6)
    const team = school ? `${rng.pick(SCHOOL_TOWNS)}${rng.pick(['高校', '学園', '高等学校'])}` : `${rng.pick(SCHOOL_TOWNS)} U-18`
    // 狙っているクラブ: 将来性が高いほど多く、格の高いクラブから
    const n = potential >= 80 ? 3 : potential >= 74 ? 2 : 1
    const cands = rng.shuffle(ai.filter((c) => c.rep >= me.rep - 10)).slice(0, 12).sort((a, b) => b.rep - a.rep)
    list.push({ player: p, source: school ? '高校選手権' : 'クラブユース選手権', team, pref, interest: cands.slice(0, n).map((c) => c.id) })
  }
  state.prospects = { season: state.season, list }
  state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'club', mine: true, text: `高校選手権とクラブユースで 5 人の有望株が話題に。入団の申し込みは第 ${PROSPECT_DEADLINE + 1} 週まで（移籍 → 有望株）。` })
}

/** 来てくれる見込み（0〜1） */
export function prospectChance(state: GameState, pr: Prospect, role: 'main' | 'develop', bonus: number): number {
  const me = state.clubs[state.playerClubId]
  const top = Math.max(me.rep - 5, ...pr.interest.map((id) => state.clubs[id]?.rep ?? 0))
  const local = pr.pref === state.hometown.pref ? 0.2 : 0
  const x = 0.35 + (me.rep - top) * 0.012 + me.facilities.youth * 0.04 + local + Math.min(0.3, bonus / 10000) + (role === 'main' ? 0.1 : 0) - pr.interest.length * 0.05
  return Math.max(0.05, Math.min(0.95, x))
}

export function chanceLabel(c: number): string {
  return c >= 0.7 ? '高い' : c >= 0.45 ? '五分五分' : c >= 0.25 ? '低い' : 'かなり低い'
}

/** 申し込む（取り消しは applied を消す） */
export function applyProspect(state: GameState, idx: number, role: 'main' | 'develop', bonus: number): boolean {
  const pr = state.prospects?.list[idx]
  if (!pr || state.week > PROSPECT_DEADLINE) return false
  pr.applied = { role, bonus }
  return true
}

/** 見せる総合の幅（スカウトの腕で狭くなる） */
export function prospectEstimate(state: GameState, pr: Prospect): { lo: number; hi: number; stars: number } {
  const me = state.clubs[state.playerClubId]
  const scout = me.staff.map((id) => state.staff[id]).filter((s) => s?.role === 'scout').length
  const o = ovr(pr.player)
  const w = Math.max(1, 4 - scout)
  const pot = potentialOvr(pr.player)
  return { lo: o - w, hi: o + w, stars: pot >= 82 ? 5 : pot >= 77 ? 4 : pot >= 72 ? 3 : 2 }
}

/** 第 30 週: 本人が決める */
export function decideProspects(state: GameState) {
  const ps = state.prospects
  if (!ps || ps.season !== state.season) return
  const me = state.clubs[state.playerClubId]
  const rng = createRng(hashSeed(state.seed, state.season, 0x9206))
  const absWeek = absWeekOf(state.season, state.week)
  const joined: string[] = []
  for (const pr of ps.list) {
    const p = pr.player
    const yes = pr.applied && rng.chance(prospectChance(state, pr, pr.applied.role, pr.applied.bonus)) && me.budget >= pr.applied.bonus
    if (yes && rosterInfo(state).full) {
      state.news.push({ absWeek, category: 'club', mine: true, text: `${p.name}は入団を望んだが、選手枠がいっぱいで迎えられなかった。` })
    } else if (yes && pr.applied) {
      p.clubId = me.id
      p.contract = { ...p.contract, wage: fairWage(ovr(p), 18, 'JP'), until: state.season + 3 }
      state.players[p.id] = p
      me.budget -= pr.applied.bonus
      const last = state.finance[state.finance.length - 1]
      if (last) last.other -= pr.applied.bonus
      joined.push(p.name)
      continue
    }
    // ほかのクラブか、大学へ
    const to = pr.interest[0]
    if (to !== undefined && rng.chance(0.7)) {
      p.clubId = to
      p.contract = { ...p.contract, wage: fairWage(ovr(p), 18, 'JP'), until: state.season + 3 }
      state.players[p.id] = p
      trimSquad(state, to)
      if (pr.applied) state.news.push({ absWeek, category: 'club', mine: true, text: `${p.name}（${pr.team}）は${state.clubs[to].name}への入団を選んだ。` })
    } else if (pr.applied) state.news.push({ absWeek, category: 'club', mine: true, text: `${p.name}（${pr.team}）は大学への進学を選んだ。` })
  }
  if (joined.length) state.news.push({ absWeek, category: 'club', mine: true, text: `${joined.join('・')}が入団を決めてくれました！` })
  state.prospects = undefined
}
