/**
 * クラブの総合力（M23）: 0〜100 の 1 つの数と、5 つの内訳。どのクラブにも同じ式なので、リーグの中で比べられる。
 *   戦力 45%（先発 11 人の力と控えの厚み）・人気 15%（人気とサポーター）・経営 15%（資金）・施設 15%（施設とスタジアム）・スタッフ 10%（監督とコーチ）
 *   段: S 85〜・A 75〜・B 65〜・C 55〜・D 45〜・E 35〜・F 25〜・G
 * 推移: 自クラブの総合力を月のはじめとシーズンの終わりに残す（state.powerLog。月ごとは直近 3 シーズン、シーズンの終わりはずっと）。
 * 乱数は使わない。
 */
import { WEEKS_PER_SEASON } from '../core/calendar'
import { formationOf } from '../data/formations'
import type { Club } from '../models/club'
import { FACILITY_IDS } from '../models/club'
import type { GameState } from '../models/game'
import { squadOf } from '../match/lineup'
import { ovr, ratingAt } from '../player/overall'
import { MAX_FACILITY } from '../economy/facilities'

export type PowerPart = 'team' | 'popularity' | 'finance' | 'facility' | 'staff'

export const POWER_PARTS: { id: PowerPart; name: string; weight: number; desc: string }[] = [
  { id: 'team', name: '戦力', weight: 0.45, desc: '先発 11 人の力と、控えの厚み' },
  { id: 'popularity', name: '人気', weight: 0.15, desc: '人気とサポーターの数' },
  { id: 'finance', name: '経営', weight: 0.15, desc: '使えるお金' },
  { id: 'facility', name: '施設', weight: 0.15, desc: '練習・ユースなどの施設とスタジアム' },
  { id: 'staff', name: 'スタッフ', weight: 0.1, desc: '監督とコーチの能力' },
]

export type PowerGrade = 'S' | 'A' | 'B' | 'C' | 'D' | 'E' | 'F' | 'G'

export interface ClubPower {
  total: number
  parts: Record<PowerPart, number>
}

export interface PowerLog extends ClubPower {
  season: number
  week: number
  leagueId: string
  /** 同じリーグでの総合力の順位と、リーグのクラブ数 */
  leagueRank: number
  leagueSize: number
  /** 古いセーブで、過去の記録から推定したシーズン（戦力と経営は記録から、ほかは今の値までの直線） */
  estimated?: boolean
}

const clamp100 = (v: number) => Math.max(0, Math.min(100, v))
const log10 = (v: number) => Math.log10(Math.max(1, v))

export function powerGrade(v: number): PowerGrade {
  return v >= 85 ? 'S' : v >= 75 ? 'A' : v >= 65 ? 'B' : v >= 55 ? 'C' : v >= 45 ? 'D' : v >= 35 ? 'E' : v >= 25 ? 'F' : 'G'
}

/** 次の段まであといくつ（S なら null） */
export function nextGrade(v: number): { grade: PowerGrade; need: number } | null {
  const steps: [number, PowerGrade][] = [
    [25, 'F'],
    [35, 'E'],
    [45, 'D'],
    [55, 'C'],
    [65, 'B'],
    [75, 'A'],
    [85, 'S'],
  ]
  const s = steps.find(([t]) => v < t)
  return s ? { grade: s[1], need: Math.ceil(s[0] - v) } : null
}

const COACH_ROLES = new Set(['headCoach', 'attackCoach', 'defenseCoach', 'physicalCoach', 'gkCoach', 'mentalCoach'])

export function clubPower(state: GameState, club: Club): ClubPower {
  // 戦力: 先発 11 人のその位置での評価の平均（8 割）＋ 12〜18 番手の総合の平均（2 割）
  const f = formationOf(club.tactics.formation)
  const xi = club.lineup.starters
    .map((id, i) => {
      const p = state.players[id]
      return p ? ratingAt(p, f.slots[i]?.pos ?? p.pos) : 0
    })
    .filter((v) => v > 0)
  const squad = squadOf(state, club.id)
    .map(ovr)
    .sort((a, b) => b - a)
  const xiAvg = xi.length ? xi.reduce((s, v) => s + v, 0) / 11 : squad.slice(0, 11).reduce((s, v) => s + v, 0) / 11
  const depth = squad.slice(11, 18)
  const depthAvg = depth.length ? depth.reduce((s, v) => s + v, 0) / 7 : xiAvg * 0.7
  const team = clamp100(((0.8 * xiAvg + 0.2 * depthAvg - 30) / 55) * 100)
  // 人気: 人気（6 割）とサポーターの数（1,000 人で 0 → 10 万人で 100、4 割）
  // 海外のファン（M24）は 10 人で国内のサポーター 1 人ぶん
  const fansAll = club.fans + (club.worldFans ?? 0) / 10
  const popularity = clamp100(0.6 * club.popularity + 0.4 * clamp100(((log10(fansAll) - 3) / 2) * 100))
  // 経営: 資金（1 億で 0 → 100 億で 100）
  const finance = club.budget <= 0 ? 0 : clamp100(((log10(club.budget) - 4) / 2) * 100)
  // 施設: 施設のレベル（6 割）とスタジアムの格と大きさ（4 割）
  // 施設: 国内の最大（Lv5）で 100。世界水準（Lv6〜8）はほかの施設の低さを埋める
  const fac = Math.min(1, FACILITY_IDS.reduce((s, id) => s + (club.facilities[id] ?? 0), 0) / (FACILITY_IDS.length * MAX_FACILITY))
  const stadium = Math.min(1, club.stadium.grade / 5) * 0.5 + Math.min(1, club.stadium.capacity / 60000) * 0.5
  const facility = clamp100((fac * 0.6 + stadium * 0.4) * 100)
  // スタッフ: 監督（半分）とコーチの平均（半分）。いなければ 0
  const staff = club.staff.map((id) => state.staff[id]).filter((s) => !!s)
  const manager = staff.find((s) => s.role === 'manager')
  const coaches = staff.filter((s) => COACH_ROLES.has(s.role))
  const coachAvg = coaches.length ? coaches.reduce((s, c) => s + c.ability, 0) / coaches.length : 0
  const staffScore = clamp100(0.5 * (manager?.ability ?? 0) + 0.5 * coachAvg)
  const parts: Record<PowerPart, number> = { team, popularity, finance, facility, staff: staffScore }
  const total = POWER_PARTS.reduce((s, p) => s + parts[p.id] * p.weight, 0)
  return { total, parts }
}

/** 同じリーグのクラブの総合力（高い順） */
export function leaguePower(state: GameState, leagueId: string): { clubId: number; power: ClubPower }[] {
  const comp = state.competitions.find((c) => c.id === leagueId)
  const ids = comp?.clubIds ?? state.clubs.filter((c) => c.leagueId === leagueId).map((c) => c.id)
  return ids.map((id) => ({ clubId: id, power: clubPower(state, state.clubs[id]) })).sort((a, b) => b.power.total - a.power.total)
}

/** 自クラブの総合力と、リーグでの順位（項目ごとの順位も） */
export function myPower(state: GameState): ClubPower & { leagueId: string; leagueRank: number; leagueSize: number; partRanks: Record<PowerPart, number> } {
  const me = state.clubs[state.playerClubId]
  const table = leaguePower(state, me.leagueId)
  const mine = table.find((x) => x.clubId === me.id)?.power ?? clubPower(state, me)
  const partRanks = Object.fromEntries(POWER_PARTS.map((p) => [p.id, 1 + table.filter((x) => x.clubId !== me.id && x.power.parts[p.id] > mine.parts[p.id]).length])) as Record<PowerPart, number>
  return { ...mine, leagueId: me.leagueId, leagueRank: 1 + table.findIndex((x) => x.clubId === me.id), leagueSize: table.length, partRanks }
}

/** 推移を残す（月のはじめとシーズンの終わり。クラブモード） */
export function logPower(state: GameState) {
  if (state.mode === 'career') return
  const p = myPower(state)
  const entry: PowerLog = { season: state.season, week: state.week, total: p.total, parts: p.parts, leagueId: p.leagueId, leagueRank: p.leagueRank, leagueSize: p.leagueSize }
  const log = (state.powerLog ?? []).filter((e) => !(e.season === entry.season && e.week === entry.week))
  log.push(entry)
  // 月ごとの記録は直近 3 シーズンだけ（シーズンの終わりの記録はずっと）
  state.powerLog = log.filter((e) => e.week === WEEKS_PER_SEASON - 1 || e.season >= state.season - 2)
}

/** 毎週（クラブモード）: 月のはじめとシーズンの最後の週に残す */
export function powerWeek(state: GameState) {
  if (state.week % 4 === 0 || state.week === WEEKS_PER_SEASON - 1) logPower(state)
}

/** 新しいクラブの人気・施設・スタッフの目安（推定の始まり） */
const START_PARTS = { popularity: 13, facility: 12, staff: 45 }

/**
 * 古いセーブ: 推移の記録がなければ、過去のシーズンを推定で埋める（読み込んだときに 1 回）。
 *   戦力: そのシーズンに在籍した選手の、シーズン末の総合（選手の記録から。上位 11 人と 12〜18 番手）
 *   経営: シーズン末の資金（シーズンの記録から）
 *   人気・施設・スタッフ: 記録がないので、新しいクラブの目安から今の値までの直線
 */
export function backfillPower(state: GameState) {
  if (state.mode === 'career' || state.powerLog?.length || !state.seasons.length) return
  const me = state.clubs[state.playerClubId]
  if (!me) return
  const now = clubPower(state, me)
  const span = Math.max(1, state.season)
  const out: PowerLog[] = []
  for (const sum of state.seasons) {
    if (sum.season >= state.season) continue
    const ovrs = Object.values(state.players)
      .flatMap((p) => p.history.filter((h) => h.season === sum.season && h.clubId === me.id).map((h) => h.ovr))
      .sort((a, b) => b - a)
    if (ovrs.length < 11) continue
    const xi = ovrs.slice(0, 11).reduce((a, v) => a + v, 0) / 11
    const depth = ovrs.slice(11, 18)
    const depthAvg = depth.length ? depth.reduce((a, v) => a + v, 0) / depth.length : xi * 0.7
    const team = clamp100(((0.8 * xi + 0.2 * depthAvg - 30) / 55) * 100)
    const finance = sum.budgetEnd <= 0 ? 0 : clamp100(((log10(sum.budgetEnd) - 4) / 2) * 100)
    const t = (sum.season + 1) / (span + 1)
    const lerp = (a: number, b: number) => a + (b - a) * t
    const parts: Record<PowerPart, number> = {
      team,
      popularity: lerp(START_PARTS.popularity, now.parts.popularity),
      finance,
      facility: lerp(START_PARTS.facility, now.parts.facility),
      staff: lerp(START_PARTS.staff, now.parts.staff),
    }
    const total = POWER_PARTS.reduce((s, p) => s + parts[p.id] * p.weight, 0)
    const size = state.competitions.find((c) => c.id === sum.leagueId)?.clubIds.length ?? 18
    out.push({ season: sum.season, week: WEEKS_PER_SEASON - 1, total, parts, leagueId: sum.leagueId, leagueRank: 0, leagueSize: size, estimated: true })
  }
  if (out.length) state.powerLog = out
}

/** シーズンごとの推移（シーズンの終わりの記録。なければそのシーズンの最後の記録） */
export function powerBySeason(state: GameState): PowerLog[] {
  const bySeason = new Map<number, PowerLog>()
  for (const e of state.powerLog ?? []) {
    const cur = bySeason.get(e.season)
    if (!cur || e.week >= cur.week) bySeason.set(e.season, e)
  }
  return [...bySeason.values()].sort((a, b) => a.season - b.season)
}
