/**
 * 海外アカデミー網（M25。クラブモードの自クラブ）。
 *   国ごとに 1 つ（12 か国。data/academies.ts）。得意の能力があり、入る子はその能力が高い
 *   開ける数はクラブの格で増える（50・62・74）。ワールドリーグに所属していれば +1
 *   Lv1〜5（拡大は 6 週の工事）・方針（標準・少数精鋭・数を重視）。毎週の運営費は帳簿の youth
 *   シーズン末にユースへ子どもが入る（seasonEnd の youthIntake のあと）
 * ユース留学: ユースの選手をアカデミーの国へ 8 週。その国の得意の能力が伸びやすい（growth/training.ts）
 * 古いセーブの事業「海外アカデミー」は読み込んだときにここへ移す（migrateAcademyBusiness）
 */
import { absWeekOf, WEEKS_PER_SEASON } from '../core/calendar'
import { createRng, hashSeed, type Rng } from '../core/prng'
import type { AttrKey } from '../data/attributes'
import { ACADEMY_BY_NATION, ACADEMY_DEFS, ACADEMY_INTAKE, ACADEMY_MAX_LEVEL, ACADEMY_OPEN_WEEKS, ACADEMY_RUN_MUL, ACADEMY_UPGRADE_MUL, type AcademyNationDef, type AcademyPolicy } from '../data/academies'
import { NATION_NAME, type Nation } from '../data/nations'
import type { Position } from '../data/positions'
import { assignNumbers, generatePlayer, starterOvrForRep } from '../gen/playerGen'
import type { Academy, Club } from '../models/club'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'

/** 開ける数が増えるクラブの格 */
export const ACADEMY_REP_STEPS = [50, 62, 74]
/** 拡大の工事（週） */
export const ACADEMY_UPGRADE_WEEKS = 6
/** 閉じたときに戻る割合 */
export const ACADEMY_REFUND = 0.3
/** 留学 */
export const STUDY_WEEKS = 8
export const STUDY_MAX = 3

const ANY_POS: Position[] = ['GK', 'CB', 'SB', 'DM', 'CM', 'AM', 'WG', 'ST']

function now(state: GameState): number {
  return absWeekOf(state.season, state.week)
}

/** 海外ユースの費用を払う（帳簿は今週の youth） */
export function chargeYouth(state: GameState, amount: number) {
  if (amount <= 0) return
  const me = state.clubs[state.playerClubId]
  me.budget -= amount
  const last = state.finance[state.finance.length - 1]
  if (last) last.youth = (last.youth ?? 0) + amount
}

export function academyDef(a: Academy | Nation): AcademyNationDef {
  return ACADEMY_BY_NATION[typeof a === 'string' ? a : a.nation] ?? ACADEMY_DEFS[0]
}

export function academiesOf(club: Club): Academy[] {
  return club.academies ?? []
}

export function findAcademy(club: Club, nation: Nation): Academy | undefined {
  return club.academies?.find((a) => a.nation === nation)
}

/** 動いている（開業の準備が終わった）か */
export function academyOpen(state: GameState, a: Academy): boolean {
  return now(state) >= a.openAbsWeek
}

/** 動いているアカデミーのいちばん高いレベル（事業のイベントの条件に使う） */
export function academyTopLevel(state: GameState, club: Club): number {
  return Math.max(0, ...academiesOf(club).filter((a) => academyOpen(state, a)).map((a) => a.level))
}

/** 開ける数（格とワールドリーグ） */
export function academySlots(club: Club): { slots: number; used: number; nextRep?: number; world: boolean } {
  const n = ACADEMY_REP_STEPS.filter((r) => club.rep >= r).length
  const world = club.leagueId === 'WL'
  return { slots: n + (world && n > 0 ? 1 : 0), used: academiesOf(club).length, nextRep: ACADEMY_REP_STEPS.find((r) => club.rep < r), world }
}

/** 1 シーズンの運営費（授業料を引いた分） */
export function academyRunCost(a: Academy): number {
  const pol = a.policy === 'elite' ? 1.15 : a.policy === 'mass' ? 0.9 : 1
  return Math.round(academyDef(a).run * ACADEMY_RUN_MUL[a.level] * pol)
}

export function academyUpgradeCost(nation: Nation, toLevel: number): number {
  return Math.round(academyDef(nation).openCost * (ACADEMY_UPGRADE_MUL[toLevel] ?? 0))
}

/** 毎季ユースに入る人数 */
export function academyIntakeCount(a: Academy): number {
  const n = ACADEMY_INTAKE[a.level] ?? 1
  return Math.max(1, n + (a.policy === 'mass' ? 1 : a.policy === 'elite' ? -1 : 0))
}

export function canOpenAcademy(club: Club, nation: Nation): { ok: boolean; reason?: string } {
  const def = ACADEMY_BY_NATION[nation]
  if (!def) return { ok: false, reason: '開けない国' }
  if (findAcademy(club, nation)) return { ok: false, reason: '開業済み' }
  const s = academySlots(club)
  if (s.slots === 0) return { ok: false, reason: `クラブの格 ${ACADEMY_REP_STEPS[0]} から開けます` }
  if (s.used >= s.slots) return { ok: false, reason: s.nextRep ? `枠がいっぱい（格 ${s.nextRep} で増える）` : '枠がいっぱい' }
  if (club.budget < def.openCost) return { ok: false, reason: '資金が足りない' }
  return { ok: true }
}

export function openAcademy(state: GameState, nation: Nation): boolean {
  const club = state.clubs[state.playerClubId]
  if (!canOpenAcademy(club, nation).ok) return false
  const def = academyDef(nation)
  chargeYouth(state, def.openCost)
  ;(club.academies ??= []).push({ nation, level: 1, openAbsWeek: now(state) + ACADEMY_OPEN_WEEKS, policy: 'normal', invested: def.openCost, produced: 0 })
  state.news.push({ absWeek: now(state), category: 'club', mine: true, text: `${NATION_NAME[nation]}・${def.city}に海外アカデミーの開校準備を始めました（${ACADEMY_OPEN_WEEKS} 週後に開校）。` })
  return true
}

export function canUpgradeAcademy(state: GameState, club: Club, nation: Nation): { ok: boolean; reason?: string } {
  const a = findAcademy(club, nation)
  if (!a) return { ok: false, reason: '開いていない' }
  if (a.level >= ACADEMY_MAX_LEVEL) return { ok: false, reason: '最大' }
  if (!academyOpen(state, a)) return { ok: false, reason: '開校の準備中' }
  if (a.pending) return { ok: false, reason: '工事中' }
  if (club.budget < academyUpgradeCost(nation, a.level + 1)) return { ok: false, reason: '資金が足りない' }
  return { ok: true }
}

export function upgradeAcademy(state: GameState, nation: Nation): boolean {
  const club = state.clubs[state.playerClubId]
  if (!canUpgradeAcademy(state, club, nation).ok) return false
  const a = findAcademy(club, nation)!
  const cost = academyUpgradeCost(nation, a.level + 1)
  chargeYouth(state, cost)
  a.invested += cost
  a.pending = { level: a.level + 1, doneAbsWeek: now(state) + ACADEMY_UPGRADE_WEEKS }
  return true
}

export function setAcademyPolicy(state: GameState, nation: Nation, policy: AcademyPolicy) {
  const a = findAcademy(state.clubs[state.playerClubId], nation)
  if (a) a.policy = policy
}

/** 閉じる（つぎ込んだ額の 3 割が戻る） */
export function closeAcademy(state: GameState, nation: Nation): number {
  const club = state.clubs[state.playerClubId]
  const a = findAcademy(club, nation)
  if (!a) return 0
  const refund = Math.round(a.invested * ACADEMY_REFUND)
  club.budget += refund
  const last = state.finance[state.finance.length - 1]
  if (last) last.youth = (last.youth ?? 0) - refund
  club.academies = academiesOf(club).filter((x) => x !== a)
  state.news.push({ absWeek: now(state), category: 'club', mine: true, text: `${NATION_NAME[nation]}の海外アカデミーを閉じました（${refund.toLocaleString()} 万円が戻りました）。` })
  return refund
}

/** 毎週: 開校・拡大の完成と、留学から戻る子。返り値はその週の運営費 */
export function academyWeek(state: GameState, club: Club, absWeek: number): number {
  let cost = 0
  for (const a of academiesOf(club)) {
    const def = academyDef(a)
    if (absWeek === a.openAbsWeek) state.news.push({ absWeek, category: 'club', mine: true, text: `${NATION_NAME[a.nation]}・${def.city}の海外アカデミーが開校しました！ シーズン末から子どもたちがユースに入ります。` })
    if (a.pending && a.pending.doneAbsWeek <= absWeek) {
      a.level = a.pending.level
      a.pending = undefined
      state.news.push({ absWeek, category: 'club', mine: true, text: `${def.city}の海外アカデミーが Lv${a.level} になりました。` })
    }
    if (absWeek >= a.openAbsWeek) cost += academyRunCost(a) / WEEKS_PER_SEASON
  }
  for (const p of Object.values(state.players)) {
    if (!p.study || p.clubId !== club.id) continue
    if (absWeek >= p.study.untilAbsWeek || !p.isYouth) {
      if (p.isYouth) state.news.push({ absWeek, category: 'club', mine: true, text: `${p.name}が${NATION_NAME[p.study.nation]}への留学から戻りました。ひと回りたくましくなっています。` })
      p.study = undefined
    }
  }
  return Math.round(cost)
}

/** アカデミーの子を 1 人作ってユースに入れる */
export function academyKid(state: GameState, club: Club, a: Academy, rng: Rng, potentialBonus = 0): Player {
  const def = academyDef(a)
  const nation: Nation = rng.chance(0.2) ? rng.pick(def.neighbors) : a.nation
  const pos = rng.chance(0.65) ? rng.pick(def.pos) : rng.pick(ANY_POS)
  const base = starterOvrForRep(club.rep, club.country)
  const pol = a.policy === 'elite' ? 4 : a.policy === 'mass' ? -3 : 0
  const potential = base + def.quality + rng.normal(1, def.spread * (a.policy === 'mass' ? 1.2 : 1)) + a.level * 2 + pol + potentialBonus
  const p = generatePlayer(state, rng, { clubId: club.id, pos, targetOvr: base - rng.range(10, 16), age: rng.int(15, 17), nation, potentialOvr: potential, contractYears: 3, isYouth: true })
  // 得意の能力: 今の力も上限も少し高い
  for (const k of def.attrs) {
    const up = rng.range(3, 6)
    p.attr[k] = Math.round(Math.min(99, p.attr[k] + up) * 10) / 10
    p.cap[k] = Math.round(Math.min(99, Math.max(p.cap[k], p.attr[k]) + 2) * 10) / 10
  }
  p.contract.wage = 0
  p.homegrown = club.id
  p.origin = `${NATION_NAME[a.nation]}・${def.city}校`
  state.players[p.id] = p
  a.produced++
  return p
}

/** シーズン末: 動いているアカデミーから子どもがユースに入る */
export function academyIntake(state: GameState) {
  if (state.mode !== 'club') return
  const club = state.clubs[state.playerClubId]
  const list = academiesOf(club).filter((a) => academyOpen(state, a))
  if (!list.length) return
  const rng = createRng(hashSeed(state.seed, state.season, 0xacad1))
  const absWeek = now(state)
  for (const a of list) {
    const names: string[] = []
    for (let i = 0; i < academyIntakeCount(a); i++) {
      const p = academyKid(state, club, a, rng)
      names.push(`${p.name}（${p.pos}）`)
    }
    state.news.push({ absWeek, category: 'club', mine: true, text: `${academyDef(a).city}の海外アカデミーから ${names.join('、')} がユースに加わりました。` })
  }
  assignNumbers(Object.values(state.players).filter((p) => p.clubId === club.id && !p.retired), rng)
}

/** 事業のイベント「アカデミーの逸材」: いちばん大きいアカデミーから特待生 */
export function academyGem(state: GameState, potentialBonus: number, rng: Rng): Player | null {
  const club = state.clubs[state.playerClubId]
  const a = [...academiesOf(club)].filter((x) => academyOpen(state, x)).sort((x, y) => y.level - x.level)[0]
  if (!a) return null
  const p = academyKid(state, club, a, rng, potentialBonus)
  assignNumbers(Object.values(state.players).filter((q) => q.clubId === club.id && !q.retired), rng)
  state.news.push({ absWeek: now(state), category: 'club', mine: true, text: `${academyDef(a).city}の海外アカデミーから特待生の ${p.name}（${p.pos}）がユースに加わりました。` })
  return p
}

/** 留学の費用（アカデミーのある国は安い） */
export function studyCost(club: Club, nation: Nation): number {
  return findAcademy(club, nation) ? 300 : 900
}

export function studying(state: GameState, club: Club): Player[] {
  return Object.values(state.players).filter((p) => p.study && p.clubId === club.id && p.isYouth && !p.retired)
}

export function canStudy(state: GameState, p: Player, nation: Nation): { ok: boolean; reason?: string } {
  const club = state.clubs[state.playerClubId]
  if (!p.isYouth || p.clubId !== club.id) return { ok: false, reason: 'ユースの選手だけ' }
  if (p.study) return { ok: false, reason: '留学中' }
  if (!ACADEMY_BY_NATION[nation]) return { ok: false, reason: '行けない国' }
  if (studying(state, club).length >= STUDY_MAX) return { ok: false, reason: `留学は ${STUDY_MAX} 人まで` }
  if (club.budget < studyCost(club, nation)) return { ok: false, reason: '資金が足りない' }
  return { ok: true }
}

export function sendStudy(state: GameState, playerId: number, nation: Nation): boolean {
  const p = state.players[playerId]
  if (!p || !canStudy(state, p, nation).ok) return false
  const club = state.clubs[state.playerClubId]
  chargeYouth(state, studyCost(club, nation))
  p.study = { nation, untilAbsWeek: now(state) + STUDY_WEEKS }
  state.news.push({ absWeek: now(state), category: 'club', mine: true, text: `${p.name}を${NATION_NAME[nation]}・${academyDef(nation).city}へ ${STUDY_WEEKS} 週の留学に送り出しました。` })
  return true
}

/** 留学中の伸びやすさ（得意の能力。アカデミーのある国はもっと伸びる） */
export function studyFocus(state: GameState, p: Player, absWeek: number): { attrs: AttrKey[]; mul: number } | null {
  if (!p.study || absWeek >= p.study.untilAbsWeek) return null
  const club = p.clubId >= 0 ? state.clubs[p.clubId] : undefined
  return { attrs: academyDef(p.study.nation).attrs, mul: club && findAcademy(club, p.study.nation) ? 1.9 : 1.5 }
}

/** 古いセーブ: 事業の「海外アカデミー」をアカデミー網へ移す */
export function migrateAcademyBusiness(state: GameState) {
  for (const club of state.clubs) {
    const i = club.businesses?.findIndex((b) => (b.id as string) === 'academy') ?? -1
    if (i < 0) continue
    const b = club.businesses![i]
    const nation: Nation = b.nation && ACADEMY_BY_NATION[b.nation] ? b.nation : 'BR'
    if (!findAcademy(club, nation)) (club.academies ??= []).push({ nation, level: b.level, openAbsWeek: b.openAbsWeek, pending: b.pending, policy: 'normal', invested: b.invested, produced: 0 })
    club.businesses!.splice(i, 1)
  }
}
