/**
 * AI クラブの移籍。移籍期間中に、先発の弱いポジションを格に合う選手で補強する。
 * 自クラブの選手には、売りに出した選手を中心にオファー（bid）を出す。
 */
import type { Rng } from '../core/prng'
import { absWeekOf, windowPace } from '../core/calendar'
import { formationOf } from '../data/formations'
import type { Club } from '../models/club'
import { allocId, type GameState } from '../models/game'
import type { Player } from '../models/player'
import { ageOf, fairWage, marketValue, ovr, ratingAt } from '../player/overall'
import { refillSquad } from '../competition/seasonEnd'
import { SQUAD_TEMPLATE, starterOvrForRep } from '../gen/playerGen'
import { MIN_SQUAD, askingPrice, completeTransfer, windowOpen } from './market'
import { squadOf } from '../match/lineup'

function tierOf(state: GameState, c: Club): number {
  return state.competitions.find((x) => x.id === c.leagueId)?.tier ?? 4
}

/** 先発でいちばん弱いスロット */
function weakestSlot(state: GameState, club: Club, squads: Map<number, Player[]>): { pos: Player['pos']; rating: number } | null {
  const f = formationOf(club.tactics.formation)
  let worst: { pos: Player['pos']; rating: number } | null = null
  club.lineup.starters.forEach((id, i) => {
    const p = state.players[id]
    if (!p) return
    const r = ratingAt(p, f.slots[i].pos)
    if (!worst || r < worst.rating) worst = { pos: f.slots[i].pos, rating: r }
  })
  void squads
  return worst
}

const SQUAD_MAX = SQUAD_TEMPLATE.reduce((s, t) => s + t.count, 0) + 2

/** 人数が多すぎたら、控えのいちばん弱い選手（同じなら年長）を放出 */
export function trimSquad(state: GameState, clubId: number) {
  const club = state.clubs[clubId]
  const squad = Object.values(state.players).filter((p) => p.clubId === clubId && !p.retired && !p.isYouth && !p.loan)
  const starters = new Set(club.lineup.starters)
  while (squad.length > SQUAD_MAX) {
    const pool = squad.filter((p) => !starters.has(p.id) && p.id !== state.career?.playerId)
    if (!pool.length) return
    const now = absWeekOf(state.season, state.week)
    pool.sort((a, b) => ovr(a) - ageOf(a, now) * 0.5 - (ovr(b) - ageOf(b, now) * 0.5))
    const out = pool[0]
    out.clubId = -1
    out.number = 0
    out.contract = { ...out.contract, until: state.season }
    squad.splice(squad.indexOf(out), 1)
  }
}

export function aiTransferWeek(state: GameState, rng: Rng, squads: Map<number, Player[]>) {
  if (!windowOpen(state)) return
  const now = absWeekOf(state.season, state.week)
  const all = Object.values(state.players).filter((p) => !p.retired && !p.loan && !p.isYouth)
  const sellers = new Set<number>()
  // クラブ内の序列（askingPrice の squadRank と同じ数え方）をクラブごとに覚える。移籍のあったクラブは数え直す
  // （前は候補の選手ごとに全選手を数え直していて、移籍期間の週が重かった）
  const rankCache = new Map<number, Map<number, number>>()
  const ranksOf = (clubId: number) => {
    let m = rankCache.get(clubId)
    if (!m) {
      m = new Map()
      const sq = squadOf(state, clubId).sort((a, b) => ovr(b) - ovr(a))
      for (let i = 0; i < sq.length; i++) m.set(sq[i].id, i + 1)
      rankCache.set(clubId, m)
    }
    return m
  }
  for (const club of state.clubs) {
    if (club.isPlayer || !rng.chance(0.1 * windowPace(state.week))) continue
    const weak = weakestSlot(state, club, squads)
    if (!weak) continue
    // 格に見合った先発がそろっていれば補強しない。格より上の選手は来てくれない
    // （上位リーグが下から強い選手を吸い上げ続けると、上位だけが年々インフレする）
    const level = starterOvrForRep(club.rep, club.country)
    if (weak.rating >= level - 2) continue
    const tier = tierOf(state, club)
    const budget = club.budget * 0.35
    let best: Player | null = null
    let bestGain = 3
    let bestFee = 0
    for (const p of all) {
      if (p.clubId === club.id || (state.mode !== 'career' && p.clubId === state.playerClubId) || p.id === state.career?.playerId) continue
      if (p.pos !== weak.pos && (p.apt[weak.pos] ?? 0) < 80) continue
      const r = ratingAt(p, weak.pos)
      const gain = r - weak.rating
      if (gain <= bestGain || r > level + 3) continue
      const from = p.clubId >= 0 ? state.clubs[p.clubId] : undefined
      // 格上のクラブからは引き抜かない（国をまたぐ移籍は、相手の格が自分以下のときだけ）
      if (from && (from.rep > club.rep + (from.country === club.country ? 6 : 0) || (from.country === club.country && tierOf(state, from) < tier))) continue
      if (from && (squads.get(from.id)?.length ?? 0) <= MIN_SQUAD + 2) continue
      const fee = from ? askingPrice(state, p, ranksOf(from.id)) : 0
      const wage = fairWage(ovr(p), ageOf(p, now), club.country)
      if (fee > budget || wage > budget * 0.6) continue
      best = p
      bestGain = gain
      bestFee = fee
    }
    if (!best) continue
    const from = best.clubId
    // 注目していた選手がよそへ（M20。クラブモード）
    if (state.mode !== 'career') {
      const watched = state.scout.watch.includes(best.id)
      if (watched || state.scout.reports?.some((r) => r.playerId === best!.id))
        state.news.push({ absWeek: now, category: 'transfer', mine: true, text: `${watched ? '注目していた' : 'スカウトの報告にあった'}${best.name}が${club.name}への移籍を決めた。先を越された……。` })
    }
    completeTransfer(state, best, club.id, bestFee, { wage: fairWage(ovr(best), ageOf(best, now), club.country), until: state.season + rng.int(1, 3) })
    if (from >= 0) sellers.add(from)
    trimSquad(state, club.id)
    rankCache.delete(from)
    rankCache.delete(club.id)
  }
  for (const id of sellers) if (!state.clubs[id].isPlayer) refillSquad(state, id, rng)
}

/** AI から自クラブの選手へのオファー */
export function aiBidsForPlayerClub(state: GameState, rng: Rng) {
  if (!windowOpen(state)) return
  const now = absWeekOf(state.season, state.week)
  const me = state.clubs[state.playerClubId]
  const mine = Object.values(state.players).filter((p) => p.clubId === me.id && !p.retired && !p.isYouth && !p.loan)
  const pending = new Set(state.offers.filter((o) => o.kind === 'bid').map((o) => (o.kind === 'bid' ? o.playerId : -1)))
  for (const p of mine) {
    if (pending.has(p.id)) continue
    const listed = p.id in state.forSale
    const o = ovr(p)
    // 売りに出した選手はよく声がかかる。主力にもときどき
    const chance = listed ? 0.35 : o >= 60 ? 0.02 * windowPace(state.week) : 0
    if (!rng.chance(chance)) continue
    const value = marketValue(p, now, state.season)
    const buyers = state.clubs.filter((c) => !c.isPlayer && c.leagueId !== 'AMA' && Math.abs(c.rep - me.rep) < 30 && c.budget > value * 0.8)
    // その選手が先発になれるクラブ
    const fit = buyers.filter((c) => {
      const f = formationOf(c.tactics.formation)
      return c.lineup.starters.some((id, i) => f.slots[i].pos === p.pos && state.players[id] && ovr(state.players[id]) < o)
    })
    if (!fit.length) continue
    const buyer = rng.pick(fit)
    const base = listed ? state.forSale[p.id] : value * 1.2
    // 相手が払える額まで（払えない額のオファーは、受けても成立しなかった）
    const fee = Math.min(Math.round((base * rng.range(0.75, 1.05)) / 100) * 100, Math.floor(buyer.budget / 100) * 100)
    state.offers.push({ kind: 'bid', playerId: p.id, clubId: buyer.id, fee, expiresAbsWeek: now + 2, id: allocId(state, 'offer') })
    state.news.push({ absWeek: now, category: 'transfer', mine: true, text: `${buyer.name}から ${p.name} に移籍金 ${fee.toLocaleString()} 万円のオファーが届きました。` })
  }
}

/** 自クラブがオファーを受けた */
export function acceptBid(state: GameState, offerId: number): boolean {
  const o = state.offers.find((x) => x.id === offerId)
  if (!o || o.kind !== 'bid') return false
  const p = state.players[o.playerId]
  const buyer = state.clubs[o.clubId]
  // もう自クラブにいない（ほかへ売った・解雇した）ならオファーは消す（残ると「受ける」を押しても何も起きない）
  if (!p || p.clubId !== state.playerClubId) {
    state.offers = state.offers.filter((x) => x.id !== offerId)
    return false
  }
  // 出したオファーは守る（そのあと相手の資金が減っていても。前はここで止まり、受けても何も起きなかった）
  const now = absWeekOf(state.season, state.week)
  completeTransfer(state, p, buyer.id, o.fee, { wage: Math.max(p.contract.wage, fairWage(ovr(p), ageOf(p, now), buyer.country)), until: state.season + 2 })
  state.offers = state.offers.filter((x) => x.id !== offerId)
  return true
}

export function rejectOffer(state: GameState, offerId: number) {
  state.offers = state.offers.filter((x) => x.id !== offerId)
}
