/**
 * 結果の確率（「結果はサイコロ、見た目は物理」）。
 * パス・シュート・1対1・空中戦の成否を、その瞬間の位置関係と能力から決める。
 * 定数 TUNE は較正（tools/calibrate）で調整する。
 */
import type { Attrs } from '../../data/attributes'
import { GOAL_W, PITCH_H, PITCH_W } from './types'

export const TUNE = {
  /** xG 全体の倍率（得点数の調整つまみ。M14 で試合の長さを 2 倍にしたので 1.3 → 0.38） */
  xgScale: 0.38,
  /** 1対1でボールを奪う確率の底上げ */
  tackleBias: 0.0,
  /** パスミスの基本率 */
  passErrBase: 0.025,
  /** ファウルの基本率 */
  foulBase: 0.19,
  /** シュートを選びやすくする底上げ（30m 以内。シュート数の調整つまみ） */
  shotBias: 0,
}

export const sigmoid = (x: number) => 1 / (1 + Math.exp(-x))
export const clamp = (v: number, lo: number, hi: number) => (v < lo ? lo : v > hi ? hi : v)

/** 攻める向き dir（+1 = 右のゴールを狙う）でのゴールまでの距離と、ポストの見える角度 */
export function goalGeometry(x: number, y: number, dir: 1 | -1): { d: number; angle: number } {
  const gx = dir === 1 ? PITCH_W : 0
  const dx = Math.abs(gx - x)
  const dy = y - PITCH_H / 2
  const d = Math.hypot(dx, dy)
  const half = GOAL_W / 2
  const a1 = Math.atan2(dy - half, dx)
  const a2 = Math.atan2(dy + half, dx)
  return { d, angle: Math.abs(a2 - a1) }
}

/** 位置だけで決まる xG の素点 */
export function xgGeom(x: number, y: number, dir: 1 | -1): number {
  const { d, angle } = goalGeometry(x, y, dir)
  return clamp(1.1 * Math.exp(-0.15 * Math.max(0, d - 5)) * (angle / (angle + 0.3)), 0.002, 0.8)
}

export interface ShotInput {
  x: number
  y: number
  dir: 1 | -1
  shooter: Attrs
  gk: Attrs | null
  /** 最も近い相手との距離 */
  pressure: number
  header: boolean
  /** 1対1（GK と 1対1、DF がいない） */
  oneOnOne: boolean
  /** スキルなどによる上乗せ（倍率 -0.2〜+0.3） */
  bonus: number
}

/** シュートの xG（決定率） */
export function shotXg(s: ShotInput): number {
  const { d } = goalGeometry(s.x, s.y, s.dir)
  const geom = xgGeom(s.x, s.y, s.dir)
  const near = d < 18
  const q = s.header ? s.shooter.header * 0.75 + s.shooter.jump * 0.25 : near ? s.shooter.finish * 0.6 + s.shooter.shoot * 0.2 + s.shooter.composure * 0.2 : s.shooter.shoot * 0.7 + s.shooter.finish * 0.15 + s.shooter.composure * 0.15
  const pressure = s.pressure < 1.5 ? 0.55 : s.pressure < 3 ? 0.75 : s.pressure < 5 ? 0.9 : 1
  const gkq = s.gk ? s.gk.reflex * 0.45 + s.gk.gkPos * 0.35 + s.gk.handling * 0.2 : 30
  const gkFactor = 1.3 - 0.55 * (gkq / 99)
  let xg = geom * (0.62 + 0.75 * (q / 99)) * pressure * gkFactor * (s.header ? 0.6 : 1) * (1 + s.bonus)
  if (s.oneOnOne) xg = Math.max(xg, 0.22 + 0.2 * (s.shooter.composure / 99))
  return clamp(xg * TUNE.xgScale, 0.005, 0.85)
}

/** 枠内に飛ぶ確率（xG を含む） */
export function onTargetProb(s: ShotInput, xg: number): number {
  const { d } = goalGeometry(s.x, s.y, s.dir)
  const q = s.header ? s.shooter.header : (s.shooter.shoot + s.shooter.finish) / 2
  return clamp(Math.max(xg + 0.05, 0.28 + 0.38 * (q / 99) - d * 0.006), 0.12, 0.92)
}

/** パスの成否（相手のインターセプトとミス） */
export interface PassRisk {
  success: number
  intercept: number
  error: number
  /** インターセプトしそうな相手の番号（-1 = なし） */
  interceptor: number
  /** その相手が触る位置（線上の割合 0-1） */
  interceptT: number
}

export interface Defender {
  idx: number
  x: number
  y: number
  speed: number
  skill: number
}

export function passRisk(fx: number, fy: number, tx: number, ty: number, lofted: boolean, passer: Attrs, pressure: number, defenders: Defender[], chemistry = 0): PassRisk {
  const dx = tx - fx
  const dy = ty - fy
  const d = Math.hypot(dx, dy) || 0.001
  const speed = lofted ? 17 : clamp(9.5 + d * 0.12, 9.5, 16)
  let keep = 1
  let best = -1
  let bestP = 0
  let bestT = 0
  for (const o of defenders) {
    const ox = o.x - fx
    const oy = o.y - fy
    const t = (ox * dx + oy * dy) / (d * d)
    if (t < 0.04 || t > 1.08) continue
    const pd = Math.abs(ox * dy - oy * dx) / d
    if (pd > 9) continue
    // ロングボールは落下点の近くでしか触れない
    const reach = lofted ? (t > 0.82 ? 1.7 : 0.35) : 1.05
    const ballT = (t * d) / speed
    const oT = Math.max(0, pd - reach) / o.speed + 0.28
    const p = sigmoid((ballT - oT) / 0.14) * (0.35 + 0.5 * (o.skill / 99))
    keep *= 1 - p
    if (p > bestP) {
      bestP = p
      best = o.idx
      bestT = t
    }
  }
  const intercept = 1 - keep
  const skill = lofted ? passer.pass * 0.5 + passer.cross * 0.3 + passer.vision * 0.2 : passer.pass * 0.75 + passer.vision * 0.15 + passer.composure * 0.1
  const error = clamp((TUNE.passErrBase + d * 0.0032 + (lofted ? 0.05 : 0)) * (1.38 - skill / 170) * (1 + pressure * 0.7) * (1 - chemistry * 0.25), 0.005, 0.6)
  return { success: (1 - intercept) * (1 - error), intercept, error, interceptor: best, interceptT: bestT }
}

/** 1対1: 守備側がボールを奪う確率 */
export function tackleWinProb(att: Attrs, def: Attrs, bonusAtt = 0, bonusDef = 0): number {
  const a = att.dribble * 0.55 + att.agility * 0.25 + att.strength * 0.1 + att.composure * 0.1
  const d = def.tackle * 0.55 + def.defPos * 0.2 + def.strength * 0.15 + def.agility * 0.1
  return clamp(sigmoid((d - a) * 0.055 + 0.15 + TUNE.tackleBias) * (1 + bonusDef) * (1 - bonusAtt), 0.08, 0.92)
}

/** タックルがファウルになる確率 */
export function foulProb(def: Attrs, aggression: number, fromBehind: boolean): number {
  return clamp(TUNE.foulBase + (aggression - 10) * 0.006 - (def.tackle - 50) * 0.0012 + (fromBehind ? 0.08 : 0), 0.02, 0.3)
}

/** 空中戦の強さ */
export function aerialScore(a: Attrs): number {
  return a.header * 0.45 + a.jump * 0.35 + a.strength * 0.2
}
