/**
 * チームの陣形と選手の判断。
 * - updateShape: フォーメーションの基準位置をボール位置・攻守・戦術でずらし、プレス・マーク・サポート・裏への走り込みを決める
 * - decideCarrier: ボール保持者の判断（シュート・パス・クロス・ドリブル・キープ・クリア）を効用のソフトマックスで選ぶ
 * - setPieceTargets: リスタートの立ち位置
 */
import { GOAL_W, PITCH_H, PITCH_W } from './types'
import { TUNE, clamp, passRisk, shotXg, tackleWinProb } from './resolve'
import type { MomentChoice } from './sim'
import type { Body, LiveMatch, Restart, TeamRT } from './sim'

const dist = (ax: number, ay: number, bx: number, by: number) => Math.hypot(ax - bx, ay - by)

/** その位置でボールを持つ価値（ゴールへの近さと中央寄り） */
export function threat(u: number, v: number): number {
  const side = Math.min(1, Math.abs(v - 0.5) * 2.2)
  let t = 0.01 + 0.3 * u ** 4 * (1 - 0.6 * side)
  if (u > 0.84 && Math.abs(v - 0.5) < 0.2) t += 0.06
  return t
}

/** その位置でボールを失ったときの危険 */
function danger(u: number): number {
  return 0.02 + 0.12 * (1 - u) ** 3
}

/** ボールを持ち続けること自体の価値 */
const KEEP = 0.04

// ------------------------------------------------------------------ 陣形

export function updateShape(m: LiveMatch, team: TeamRT) {
  const side = team.side
  const oppSide: 0 | 1 = side === 0 ? 1 : 0
  const b = m.ball
  const inPoss = m.possTeam === side
  const bu = m.u(team, b.x)
  const bv = m.v(team, b.y)
  const tac = team.tactics
  const f = team.formation
  const players = m.onPitch(side)
  const oppUs = m
    .onPitch(oppSide)
    .map((o) => m.u(team, o.x))
    .sort((a, c) => c - a)
  const lineU = oppUs[1] ?? 0.9
  const focusShift = tac.focus === 'left' ? -0.05 : tac.focus === 'right' ? 0.05 : 0

  for (const p of players) {
    if (b.owner === p.idx) continue
    if (b.flight && b.flight.resolver === p.idx) continue
    if (p.gk) {
      gkPosition(m, team, p)
      continue
    }
    const slot = f.slots[p.slot] ?? f.slots[1]
    let u: number
    let v: number
    let urg: number
    if (inPoss) {
      const push = 0.15 + 0.05 * tac.mentality + (bu - 0.4) * 0.62
      u = slot.u * (0.8 + 0.04 * tac.mentality) + push
      if (slot.u < 0.3) u = Math.min(u, bu + 0.03 + (slot.pos === 'SB' || slot.pos === 'WB' ? 0.14 : 0))
      u = clamp(u, 0.08, 0.93)
      // 走り込み中でなければオフサイドラインを越えない
      if (p.runT > 0) u = clamp(lineU + 0.07, u, 0.95)
      else u = Math.min(u, Math.max(lineU - 0.006, bu))
      const width = 0.82 + tac.width * 0.0042
      v = 0.5 + (slot.v - 0.5) * width + (bv - 0.5) * 0.12 + focusShift * (slot.u > 0.35 ? 1 : 0)
      urg = p.runT > 0 ? 1 : 0.55
    } else {
      // 最終ライン: ボールが中盤なら 25〜35m、ゴールに迫られたらボールの少し後ろ
      const line = clamp(Math.min(bu - 0.08, 0.1 + 0.45 * bu) + (tac.lineHeight - 50) * 0.0026, 0.05, 0.48)
      const depth = 0.7 - tac.pressing * 0.0012
      u = line + (slot.u - 0.18) * depth
      v = 0.5 + (slot.v - 0.5) * 0.74 + (bv - 0.5) * 0.32
      urg = 0.75
    }
    // 人ごとのゆらぎ（機械的に見えないように）
    const j = Math.sin(m.t * 0.6 + p.idx * 1.73) * 0.012
    p.tx = m.xOf(team, clamp(u + j, 0.02, 0.98))
    p.ty = m.yOf(team, clamp(v + j * 0.8, 0.03, 0.97))
    p.urgency = urg
  }

  const carrier = m.carrier()
  if (inPoss && carrier && carrier.team === side) supportAndRuns(m, team, carrier, lineU)
  else if (!inPoss && carrier && carrier.team !== side) pressAndMark(m, team, carrier)
  if (b.owner < 0 && !(b.flight && b.flight.resolver >= 0)) chaseLoose(m, team)
}

function gkPosition(m: LiveMatch, team: TeamRT, gk: Body) {
  const b = m.ball
  const gx = team.dir === 1 ? 0 : PITCH_W
  const gy = PITCH_H / 2
  const d = dist(b.x, b.y, gx, gy)
  let off = clamp(0.8 + d * 0.055, 0.8, 4.5)
  // 最終ラインが高くボールが遠いときは前に出る（スイーパー）
  if (m.u(team, b.x) > 0.55 && team.tactics.lineHeight > 60) off = Math.min(off + (gk.s.attr.rushing / 99) * 8, 14)
  const ang = Math.atan2(b.y - gy, b.x - gx)
  gk.tx = gx + Math.cos(ang) * off
  gk.ty = clamp(gy + Math.sin(ang) * off, gy - GOAL_W / 2 - 1.2, gy + GOAL_W / 2 + 1.2)
  gk.urgency = 0.8
}

/** 攻撃時: 近くの味方はパスコースを作り、前線は裏へ走る */
function supportAndRuns(m: LiveMatch, team: TeamRT, c: Body, lineU: number) {
  const mates = m.onPitch(team.side).filter((p) => p !== c && !p.gk)
  const opps = m.onPitch(team.side === 0 ? 1 : 0)
  const cu = m.u(team, c.x)
  // 近い 2 人がサポート
  const near = [...mates].sort((a, b) => dist(a.x, a.y, c.x, c.y) - dist(b.x, b.y, c.x, c.y)).slice(0, 2)
  const angles = [-1.1, -0.45, 0.45, 1.1, 2.4, -2.4]
  near.forEach((p, k) => {
    let best = { x: p.tx, y: p.ty, s: -1 }
    for (let i = 0; i < angles.length; i++) {
      const a = angles[(i + k * 3) % angles.length]
      const r = 11
      const ax = c.x + Math.cos(a) * r * team.dir
      const ay = c.y + Math.sin(a) * r
      if (ax < 2 || ax > PITCH_W - 2 || ay < 2 || ay > PITCH_H - 2) continue
      let open = 99
      for (const o of opps) open = Math.min(open, dist(o.x, o.y, ax, ay))
      const fwd = m.u(team, ax) - cu
      const s = Math.min(open, 8) + fwd * 10 - dist(p.x, p.y, ax, ay) * 0.15
      if (s > best.s) best = { x: ax, y: ay, s }
    }
    // オフサイドにならない位置に
    const u = m.u(team, best.x)
    if (u > Math.max(lineU - 0.006, cu)) best.x = m.xOf(team, Math.max(lineU - 0.006, cu))
    p.tx = best.x
    p.ty = best.y
    p.urgency = 0.75
  })
  // 前線の走り込み（保持者が前を向けていて、視野があるとき）
  if (cu > 0.3 && cu < 0.82 && m.tick % 5 === 0) {
    const vision = c.s.attr.vision / 99
    for (const p of mates) {
      const su = team.formation.slots[p.slot]?.u ?? 0
      if (su < 0.5 || p.runT > 0 || near.includes(p)) continue
      const pu = m.u(team, p.x)
      // オフサイドラインの手前にいる FW が、ときどき裏へ
      if (pu > lineU - 0.08 && pu <= lineU + 0.015 && m.rng.chance(0.1 + 0.2 * vision * (p.s.attr.offBall / 99))) {
        p.runT = 1.6 + m.rng.range(0, 0.6)
      }
    }
  }
}

/** 守備時: 1〜2 人がプレス、ほかは近くの相手をマーク */
function pressAndMark(m: LiveMatch, team: TeamRT, c: Body) {
  const players = m.onPitch(team.side).filter((p) => !p.gk)
  const own = team.dir === 1 ? 0 : PITCH_W
  const byTime = [...players].sort((a, b) => dist(a.x, a.y, c.x, c.y) / m.maxSpeed(a) - dist(b.x, b.y, c.x, c.y) / m.maxSpeed(b))
  const cu = m.u(team, c.x)
  const pressing = team.tactics.pressing
  const nPress = pressing > 62 && (cu < 0.45 || cu > 0.7) ? 2 : 1
  const pressers = byTime.slice(0, nPress)
  for (const p of pressers) {
    // 相手とゴールの間に入るように
    const gdx = own - c.x
    const gdy = PITCH_H / 2 - c.y
    const gd = Math.hypot(gdx, gdy) || 1
    p.tx = c.x + (gdx / gd) * 0.7
    p.ty = c.y + (gdy / gd) * 0.7
    p.urgency = clamp(0.8 + pressing * 0.003, 0.8, 1)
  }
  // マーク（各相手に 1 人まで）
  const attackers = m.onPitch(c.team).filter((a) => a !== c && !a.gk)
  const taken = new Set<number>()
  for (const p of players) {
    if (pressers.includes(p)) continue
    let best: Body | null = null
    let bd = 10
    for (const a of attackers) {
      if (taken.has(a.idx)) continue
      const d = dist(a.x, a.y, p.tx, p.ty)
      if (d < bd) {
        bd = d
        best = a
      }
    }
    if (!best) continue
    taken.add(best.idx)
    const marking = p.s.attr.marking / 99
    const gdx = own - best.x
    const gdy = PITCH_H / 2 - best.y
    const gd = Math.hypot(gdx, gdy) || 1
    const close = 2.6 - marking * 1.2
    const mx = best.x + (gdx / gd) * close
    const my = best.y + (gdy / gd) * close
    const w = 0.45 + marking * 0.3
    p.tx = p.tx * (1 - w) + mx * w
    p.ty = p.ty * (1 - w) + my * w
    p.urgency = 0.85
  }
}

/** こぼれ球: 各チームでいちばん早く着く選手が追う */
function chaseLoose(m: LiveMatch, team: TeamRT) {
  const b = m.ball
  const px = b.x + b.vx * 0.35
  const py = b.y + b.vy * 0.35
  let best: Body | null = null
  let bt = 1e9
  for (const p of m.onPitch(team.side)) {
    if (p.gk && !m.inOwnBox(p, px, py)) continue
    const t = dist(p.x, p.y, px, py) / m.maxSpeed(p) + (p.stun > 0 ? 1 : 0)
    if (t < bt) {
      bt = t
      best = p
    }
  }
  if (best) {
    best.tx = px
    best.ty = py
    best.urgency = 1
  }
}

// ------------------------------------------------------------------ 保持者の判断

interface Option {
  util: number
  run: () => void
  /** キャリアの見せ場で使う: 行動の種類・表示・成功の見込み */
  kind?: MomentChoice['kind']
  label?: string
  prob?: number
}

export function decideCarrier(m: LiveMatch, c: Body, opts: { passOnly?: boolean; maxDist?: number; throwIn?: boolean }) {
  const team = m.teams[c.team]
  const oppSide: 0 | 1 = c.team === 0 ? 1 : 0
  const a = c.s.attr
  const cu = m.u(team, c.x)
  const cv = m.v(team, c.y)
  const pressure = m.pressureOn(c)
  const pressLevel = pressure < 2 ? 1 : pressure < 4 ? 0.5 : 0
  const tac = team.tactics
  const options: Option[] = []
  const here = threat(cu, cv)
  const riskAversion = 1.25 - 0.12 * tac.mentality
  const defenders = m.defendersOf(c.team)

  // --- シュート
  if (!opts.passOnly && !c.gk) {
    const gx = m.oppGoalX(team)
    const d = dist(c.x, c.y, gx, PITCH_H / 2)
    if (d < 32) {
      const gk = m.gkOf(oppSide)
      const ahead = m.onPitch(oppSide).filter((o) => !o.gk && m.u(team, o.x) > cu).length
      const xg = shotXg({ x: c.x, y: c.y, dir: team.dir, shooter: a, gk: gk?.s.attr ?? null, pressure, header: false, oneOnOne: ahead === 0, bonus: 0 })
      const selfish = c.s.skills.includes('goalHunter') ? 0.3 : 0
      let util = xg * (2.0 + selfish) + KEEP * 0.3
      // シュート力のある選手はミドルを狙う
      if (d > 15 && d < 29) util += Math.max(0, a.shoot - 55) * 0.0011 + (c.s.skills.includes('cannonShot') ? 0.02 : 0)
      if (d < 30) util += TUNE.shotBias * (d < 20 ? 1 : 0.7)
      if (d > 28) util *= 0.7
      options.push({ util, run: () => (m.count('dec:shot'), m.doShot(c)), kind: 'shoot', label: d < 18 ? 'シュート' : 'ミドルシュート', prob: xg })
    }
  }

  // --- パス
  const maxD = opts.maxDist ?? (c.gk ? 60 : 45)
  for (const mate of m.onPitch(c.team)) {
    if (mate === c) continue
    if (mate.gk && (cu > 0.3 || opts.throwIn)) continue
    const d = dist(c.x, c.y, mate.x, mate.y)
    if (d < 4.5 || d > maxD) continue
    const offside = !opts.throwIn && m.isOffside(mate, m.ball.x)
    if (offside && m.rng.next() > 0.06 + (1 - a.decision / 99) * 0.5) continue
    const mu = m.u(team, mate.x)
    const mv = m.v(team, mate.y)
    let open = 99
    for (const o of defenders) open = Math.min(open, dist(o.x, o.y, mate.x, mate.y))
    const target = m.leadPoint(c, mate, false)
    const ground = passRisk(c.x, c.y, target.x, target.y, false, a, pressLevel, defenders)
    let risk = ground
    let lofted = false
    if (d > 18 && !opts.throwIn) {
      const lt = m.leadPoint(c, mate, true)
      const air = passRisk(c.x, c.y, lt.x, lt.y, true, a, pressLevel, defenders)
      if (air.success > ground.success + 0.08 || d > 34) {
        risk = air
        lofted = true
      }
    }
    const tu = m.u(team, target.x)
    const value = (threat(tu, mv) - here) * 1.6 + KEEP + Math.min(open, 8) * 0.004 + (tu - cu) * 0.12 * (1 + (tac.tempo - 50) / 100)
    const util = risk.success * value - (1 - risk.success) * danger(cu) * riskAversion
    void mu
    options.push({
      util,
      run: () => {
        m.count(lofted ? 'dec:long' : (tu - cu) > 0.05 ? 'dec:passFwd' : (tu - cu) < -0.05 ? 'dec:passBack' : 'dec:passSide')
        m.doPass(c, mate, lofted, opts.throwIn ? 'throw' : 'pass')
      },
      kind: 'pass',
      label: `${mate.s.short}へ${lofted ? '浮き球のパス' : (tu - cu) > 0.05 ? 'スルーパス' : 'パス'}`,
      prob: risk.success,
    })
  }

  // --- クロス
  if (!opts.passOnly && !c.gk && cu > 0.7 && Math.abs(cv - 0.5) > 0.24) {
    const inBox = m.onPitch(c.team).filter((p) => p !== c && m.u(team, p.x) > 0.83 && Math.abs(m.v(team, p.y) - 0.5) < 0.22).length
    const util = 0.05 + a.cross * 0.0013 + inBox * 0.035 + (team.tactics.width - 50) * 0.0006
    options.push({ util, run: () => (m.count('dec:cross'), m.doCross(c)), kind: 'cross', label: 'クロスを上げる', prob: clamp(0.25 + a.cross / 300 + inBox * 0.05, 0.2, 0.75) })
  }

  // --- ドリブル
  if (!opts.passOnly && !c.gk) {
    const fwd = 7
    const towardCenter = (PITCH_H / 2 - c.y) * (cu > 0.72 ? 0.25 : 0.06)
    const tx = clamp(c.x + team.dir * fwd, 1, PITCH_W - 1)
    const ty = clamp(c.y + towardCenter + (m.rng.next() - 0.5) * 4, 2, PITCH_H - 2)
    let nearest: Body | null = null
    let nd = 99
    for (const o of m.onPitch(oppSide)) {
      if (o.gk) continue
      const ahead = (o.x - c.x) * team.dir > -1
      const d = dist(o.x, o.y, c.x, c.y)
      if (ahead && d < nd) {
        nd = d
        nearest = o
      }
    }
    const pBeat = nearest && nd < 6 ? 1 - tackleWinProb(a, nearest.s.attr) * clamp(1.25 - nd * 0.12, 0.4, 1.1) : 0.95
    const gain = (threat(m.u(team, tx), m.v(team, ty)) - here) * 1.6
    const space = Math.min(nd, 10) * 0.004
    const util = pBeat * (gain + KEEP + space + (fwd / PITCH_W) * 0.12) - (1 - pBeat) * danger(cu) * 0.9 + (a.dribble - 60) * 0.0006
    options.push({
      util,
      kind: 'dribble',
      label: nearest && nd < 6 ? 'ドリブルで仕掛ける' : 'ドリブルで運ぶ',
      prob: pBeat,
      run: () => {
        m.count('dec:dribble')
        c.dribX = tx
        c.dribY = ty
        c.decideIn = 0.35 + m.rng.range(0, 0.4) * (1 - pressLevel * 0.5)
      },
    })
  }

  // --- キープ（向きを変えて時間を作る）
  if (!opts.passOnly) {
    options.push({
      util: pressure > 3 ? 0.0 : -0.03 + a.strength * 0.0002,
      run: () => {
        m.count('dec:hold')
        c.dribX = clamp(c.x - team.dir * 2, 1, PITCH_W - 1)
        c.dribY = clamp(c.y + (c.y < PITCH_H / 2 ? 3 : -3), 2, PITCH_H - 2)
        c.decideIn = 0.4
      },
    })
  }

  // --- クリア（自陣深くで追い込まれたとき）
  if (!opts.throwIn && cu < 0.25 && pressure < 2.5) options.push({ util: 0.03 + (2.5 - pressure) * 0.02, run: () => (m.count('dec:clear'), m.doClear(c)) })

  if (!options.length) {
    m.doClear(c)
    return
  }
  // キャリア: 主人公が敵陣でボールを持ったら見せ場（攻撃）。相手が主人公の GK と 1 対 1 なら GK の見せ場
  if (!opts.passOnly && !opts.throwIn && m.focusId >= 0) {
    if (m.isFocus(c) && cu > 0.58 && m.momentReady()) {
      const choices = momentChoices(options)
      if (m.offerMoment('attack', cu > 0.8 ? '決定機！' : 'チャンス！', choices)) return
    } else if (!m.isFocus(c) && cu > 0.78 && m.onPitch(oppSide).every((o) => o.gk || m.u(team, o.x) < cu) && m.keeperMoment(c)) {
      c.decideIn = 0.05
      return
    }
  }

  // ソフトマックス（判断力が高いほど最善を選ぶ）
  const cohesion = (team.setup.cohesion ?? 0) / 100
  const T = (0.008 + 0.04 * (1 - a.decision / 99)) * (1.1 - cohesion * 0.4)
  let maxU = -1e9
  for (const o of options) maxU = Math.max(maxU, o.util)
  let sum = 0
  const w = options.map((o) => {
    const e = Math.exp((o.util - maxU) / T)
    sum += e
    return e
  })
  let r = m.rng.next() * sum
  for (let i = 0; i < options.length; i++) {
    r -= w[i]
    if (r <= 0) {
      options[i].run()
      return
    }
  }
  options[options.length - 1].run()
}

// ------------------------------------------------------------------ セットプレー

export function setPieceTargets(m: LiveMatch, r: Restart) {
  // まず通常の陣形（リスタートするチームがボール保持）
  updateShape(m, m.teams[0])
  updateShape(m, m.teams[1])
  const atk = m.teams[r.team]
  const def = m.teams[r.team === 0 ? 1 : 0]
  const place = (p: Body, team: TeamRT, u: number, v: number) => {
    p.tx = m.xOf(team, u)
    p.ty = m.yOf(team, v)
    p.urgency = 0.6
  }
  if (r.kind === 'kickoff') {
    for (const team of m.teams) {
      for (const p of m.onPitch(team.side)) {
        const u = m.u(team, p.tx)
        if (u > 0.47) p.tx = m.xOf(team, 0.47)
        if (team.side !== r.team && Math.hypot(p.tx - PITCH_W / 2, p.ty - PITCH_H / 2) < 9.5) p.tx = m.xOf(team, 0.38)
      }
    }
    return
  }
  if (r.kind === 'penalty') {
    for (const team of m.teams) {
      for (const p of m.onPitch(team.side)) {
        if (p.gk && team === def) {
          place(p, def, 0.005, 0.5)
          continue
        }
        if (p.idx === r.taker) continue
        // ペナルティエリアの外
        const u = m.u(atk, p.tx)
        if (u > 0.8) p.tx = m.xOf(atk, 0.78)
      }
    }
    return
  }
  const ru = m.u(atk, r.x)
  if (r.kind === 'corner' || (r.kind === 'freekick' && ru > 0.66)) {
    // 攻撃側: 空中戦に強い選手をゴール前へ
    const aerial = m
      .onPitch(atk.side)
      .filter((p) => !p.gk && p.idx !== r.taker)
      .sort((a, b) => b.s.attr.header + b.s.attr.jump - (a.s.attr.header + a.s.attr.jump))
    const spots = [
      [0.95, 0.43],
      [0.94, 0.6],
      [0.89, 0.5],
      [0.84, 0.4],
      [0.82, 0.62],
    ]
    aerial.slice(0, r.kind === 'corner' ? 5 : 4).forEach((p, i) => place(p, atk, spots[i][0] + m.rng.range(-0.01, 0.01), spots[i][1] + m.rng.range(-0.02, 0.02)))
    // 守備側: ゾーンで固める
    const defs = m
      .onPitch(def.side)
      .filter((p) => !p.gk)
      .sort((a, b) => b.s.attr.header + b.s.attr.marking - (a.s.attr.header + a.s.attr.marking))
    const dspots = [
      [0.03, 0.45],
      [0.03, 0.56],
      [0.07, 0.4],
      [0.07, 0.6],
      [0.1, 0.5],
      [0.14, 0.44],
      [0.14, 0.58],
    ]
    defs.slice(0, 7).forEach((p, i) => place(p, def, dspots[i][0], dspots[i][1]))
    const gk = m.gkOf(def.side)
    if (gk) place(gk, def, 0.01, 0.5)
    // 直接狙える FK なら壁
    if (r.kind === 'freekick') {
      const gx = m.oppGoalX(atk)
      const d = Math.hypot(gx - r.x, PITCH_H / 2 - r.y)
      if (d < 32) {
        const wall = defs.slice(0, 3)
        const ux = (gx - r.x) / d
        const uy = (PITCH_H / 2 - r.y) / d
        wall.forEach((p, i) => {
          p.tx = r.x + ux * 9.15 - uy * (i - 1) * 0.7
          p.ty = r.y + uy * 9.15 + ux * (i - 1) * 0.7
        })
      }
    }
    return
  }
  // スローイン・ゴールキック・その他の FK: ボールから 9m は離れる（相手）
  for (const p of m.onPitch(def.side)) {
    const d = Math.hypot(p.tx - r.x, p.ty - r.y)
    if (d < 9 && d > 0.01) {
      p.tx = r.x + ((p.tx - r.x) / d) * 9
      p.ty = r.y + ((p.ty - r.y) / d) * 9
    }
  }
}

/** 見せ場の選択肢: 種類ごとにいちばん良いものを、良い順に 3 つまで（シュートがあれば必ず入れる） */
function momentChoices(options: Option[]): MomentChoice[] {
  const best = new Map<string, Option>()
  for (const o of options) {
    if (!o.kind || !o.label) continue
    const cur = best.get(o.kind)
    if (!cur || o.util > cur.util) best.set(o.kind, o)
  }
  const list = [...best.values()].sort((a, b) => b.util - a.util)
  const shot = best.get('shoot')
  const top = list.slice(0, 3)
  if (shot && !top.includes(shot)) top[top.length - 1] = shot
  return top.map((o) => ({ kind: o.kind!, label: o.label!, prob: o.prob ?? 0.5, util: o.util, run: o.run }))
}
