/**
 * 試合結果をゲームに反映する: 順位表、個人成績、疲労、ケガ、出場停止、ニュース。
 * LiveSim と FastSim のどちらの MatchSummary でも同じように扱う。
 */
import type { Rng } from '../core/prng'
import type { Competition, Fixture, GoalRecord } from '../models/competition'
import type { GameState } from '../models/game'
import type { MatchSummary } from '../match/live/types'
import type { Player } from '../models/player'
import { applyResultToTable, sortTable } from './league'
import { rollInjury } from '../growth/training'
import type { Rng as RngT } from '../core/prng'
import { attendanceFor } from '../economy/finance'
import { afterMatch } from '../club/fans'
import { chemAfterMatch } from '../club/chemistry'
import { learnFromMatch } from '../scout/knowledge'
import { noteMatch } from '../club/records'
import { derbyOf, noteRivalMatch } from '../club/derby'
import { squadOf } from '../match/lineup'
import { careerAfterMatch } from '../career/match'

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

/** 累積警告で出場停止になる枚数 */
export const YELLOW_LIMIT = 4

export function applyMatchResult(state: GameState, comp: Competition, f: Fixture, s: MatchSummary, rng: Rng, squads?: Map<number, Player[]>) {
  const goals: GoalRecord[] = s.goals.map((g) => ({
    playerId: g.player,
    clubId: g.team === 0 ? f.home : f.away,
    minute: g.minute,
    assistId: g.assist,
    penalty: g.penalty,
    ownGoal: g.ownGoal,
  }))
  f.result = { hg: s.score[0], ag: s.score[1], et: s.et, pens: s.pens, goals, live: s.events.some((e) => e.type === 'kickoff') }
  // リーグ戦と、大陸大会のグループ戦は順位表へ
  if (comp.kind === 'league' || f.group !== undefined) {
    applyResultToTable(comp, f)
    sortTable(comp)
  }

  // 出場停止の消化（この試合に出られなかった選手）
  const played = new Set(s.players.map((p) => p.id))
  for (const clubId of [f.home, f.away]) {
    const list = squads?.get(clubId) ?? Object.values(state.players).filter((p) => p.clubId === clubId)
    for (const p of list) {
      if (p.suspension <= 0 || played.has(p.id)) continue
      p.suspension--
    }
  }

  const mine = f.home === state.playerClubId || f.away === state.playerClubId
  for (const ps of s.players) {
    const p = state.players[ps.id]
    if (!p) continue
    if (ps.minutes > 0.5) {
      p.stats.apps++
      if (ps.started) p.stats.starts++
      p.stats.minutes += Math.round(ps.minutes)
      p.stats.ratingSum += ps.rating
    }
    p.stats.goals += ps.goals
    p.stats.assists += ps.assists
    // 疲労
    p.fatigue = clamp(p.fatigue + (ps.minutes / 90) * 14 + (100 - ps.stamina) * 0.12, 0, 100)
    // カード
    if (ps.yellow > 0 && !ps.red) {
      p.stats.yellow += ps.yellow
      if (comp.kind === 'league' && p.stats.yellow % YELLOW_LIMIT === 0) p.suspension += 1
    }
    if (ps.red) {
      p.stats.red++
      p.suspension += ps.yellow >= 2 ? 1 : rng.int(1, 3)
    }
    // ケガ
    if (ps.injured && !p.injury) {
      const club = state.clubs[p.clubId]
      p.injury = rollInjury(rng, club?.facilities.medical ?? 0, p.skills.includes('glassBody'))
      if (mine && p.clubId === state.playerClubId)
        state.news.push({ absWeek: f.absWeek, category: 'injury', mine: true, text: `${p.name} が${p.injury.name}で離脱（全治 ${p.injury.weeks} 週）` })
    }
    // やる気: 先発・勝利で上がる
    const won = (p.clubId === f.home && s.score[0] > s.score[1]) || (p.clubId === f.away && s.score[1] > s.score[0])
    p.morale = clamp(p.morale + (ps.started ? 2 : 1) + (won ? 2 : 0) + (ps.rating >= 7.5 ? 2 : 0), 0, 100)
  }
  // GK の無失点
  for (const side of [0, 1] as const) {
    const conceded = side === 0 ? s.score[1] : s.score[0]
    if (conceded > 0) continue
    const gk = s.players.find((p) => p.team === side && p.started && state.players[p.id]?.pos === 'GK')
    if (gk) state.players[gk.id].stats.cleanSheets++
  }

  if (mine) {
    const me = state.playerClubId
    const home = f.home === me
    const my = home ? s.score[0] : s.score[1]
    const op = home ? s.score[1] : s.score[0]
    const opp = state.clubs[home ? f.away : f.home]
    const res = my > op ? '勝利' : my < op ? '敗戦' : '引き分け'
    const derby = derbyOf(state, f.home, f.away)
    state.news.push({ absWeek: f.absWeek, category: 'match', mine: true, text: `${derby ? `【${derby.name}】` : ''}${comp.name} ${comp.kind === 'league' ? `第${f.round + 1}節` : ''} ${opp.name} に ${my}-${op} で${res}${s.pens ? `（PK ${home ? s.pens[0] : s.pens[1]}-${home ? s.pens[1] : s.pens[0]}）` : ''}` })
    state.lastMatch = { fixtureId: f.id, compId: comp.id, home: f.home, away: f.away, summary: s }
  }
}

/** 自クラブの試合を反映（観客・サポーター・連携・相手の情報も） */
export function applyPlayerMatch(state: GameState, comp: Competition, f: Fixture, s: MatchSummary, rng: RngT, squads?: Map<number, Player[]>) {
  const me = state.playerClubId
  const club = state.clubs[me]
  const home = f.home === me
  const starters = [...club.lineup.starters]
  const formation = club.tactics.formation
  applyMatchResult(state, comp, f, s, rng, squads)
  const opp = state.clubs[home ? f.away : f.home]
  // 中立地の試合（大陸大会の決勝・世界大会）は入場料が入らない
  // ダービーは観客が増え、勝ち負けで人気・サポーター・やる気が大きく動く
  const derby = derbyOf(state, f.home, f.away)
  const attendance = home && !(comp.neutralFrom !== undefined && f.round >= comp.neutralFrom) ? attendanceFor(state, club, opp, rng, 1 + (derby?.intensity ?? 0) * 0.35) : 0
  if (f.result) f.result.attendance = attendance || undefined
  if (state.mode === 'career' && state.career) careerAfterMatch(state, comp, f, s)
  else noteMatch(state, comp, f)
  noteRivalMatch(state, f)
  const gf = home ? s.score[0] : s.score[1]
  const ga = home ? s.score[1] : s.score[0]
  afterMatch(state, club, gf, ga, home, derby?.intensity ?? 0)
  if (derby && gf !== ga) for (const p of squadOf(state, me)) p.morale = Math.max(0, Math.min(100, p.morale + (gf > ga ? 3 : -2) * derby.intensity))
  chemAfterMatch(state, starters, formation)
  const mySide = home ? 0 : 1
  learnFromMatch(
    state,
    s.players.filter((p) => p.team !== mySide).map((p) => p.id),
  )
}
