import { WEEKS_PER_SEASON } from '../core/calendar'
import { ASIA_CLUBS, FOREIGN_LEAGUES, HOMETOWNS, NPL1, NPL2, NPL3, type LeagueDef } from '../data/clubs'
import { STAR_PLAYERS, STAR_STAFF } from '../data/cast'
import { FACILITY_IDS, type Club, type EmblemSpec, type FacilityId, type KitPattern, type Tactics } from '../models/club'
import type { Competition } from '../models/competition'
import { SCHEMA_VERSION, emptyRecords, type GameState } from '../models/game'
import type { Staff, TacticalStyle } from '../models/staff'
import { FORMATIONS } from '../data/formations'
import { POSITION_DEFS } from '../data/positions'
import { assignNumbers, buildAptitudes, buildCap, generatePlayer, generateSquad } from './playerGen'
import { CLUB_STAFF_ROLES, generateStaff, staffWage } from './staffGen'
import { STAR_PLAYER_GAME, STAR_STAFF_GAME } from './stars'
import { emptyRow, scheduleLeague } from '../competition/league'
import { ASIA_ID, createContinental } from '../competition/continental'
import { createCup, ensureAmateurClubs } from '../competition/cup'
