export interface NewGameOptions {
  seed: number
  startYear?: number
  clubName: string
  clubShort: string
  hometownIndex: number
  colors: { primary: string; secondary: string }
  emblem?: EmblemSpec
  kit?: KitPattern
  /** ワールドリーグをつくらない（キャリアモード） */
  noWorldLeague?: boolean
}

const KITS: KitPattern[] = ['solid', 'stripes', 'hoops', 'sash', 'halves']

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

/** 戦術の初期値（監督のスタイルから） */
export function tacticsForStyle(style: TacticalStyle | undefined, formation: string): Tactics {
  const t: Tactics = { formation, mentality: 0, tempo: 50, width: 50, lineHeight: 50, pressing: 50, focus: 'balanced', offsideTrap: false, counter: false }
  switch (style) {
    case 'possession':
      return { ...t, tempo: 35, width: 60, lineHeight: 62, pressing: 58 }
    case 'counter':
      return { ...t, mentality: -1, tempo: 72, lineHeight: 35, pressing: 40, counter: true }
    case 'wing':
      return { ...t, width: 80, tempo: 58, focus: 'balanced' }
    case 'pressing':
      return { ...t, mentality: 1, tempo: 65, lineHeight: 72, pressing: 85, offsideTrap: true }
    case 'defensive':
      return { ...t, mentality: -1, lineHeight: 30, pressing: 35, width: 42, counter: true }
    case 'longball':
      return { ...t, tempo: 75, width: 55, lineHeight: 45 }
    default:
      return t
  }
}

function facilitiesFor(rep: number, rng: Rng): Record<FacilityId, number> {
  const out = {} as Record<FacilityId, number>
  for (const f of FACILITY_IDS) out[f] = clamp(Math.round(rep / 20 + rng.normal(0, 0.7)), 0, 5)
  return out
}

function stadiumCapacity(country: string, tier: number, rep: number, rng: Rng): number {
  if (country === 'JP') {
    const base = tier === 1 ? 18000 + rep * 300 : tier === 2 ? 9000 + rep * 160 : 4000 + rep * 120
    return Math.round((base * rng.range(0.85, 1.15)) / 500) * 500
  }
  return Math.round(((15000 + rep * 600) * rng.range(0.8, 1.2)) / 1000) * 1000
}

export function makeClub(id: number, def: LeagueDef, idx: number, rng: Rng): Club {
  const [name, short, primary, secondary, rep] = def.clubs[idx]
  return {
    id,
    name,
    short,
    country: def.country,
    city: def.country === 'JP' ? short.replace(/[A-Z]+$/, '') : name.split('・')[0],
    colors: { primary, secondary },
    emblem: { shape: rng.int(0, 4), charge: rng.int(0, 7), pattern: rng.int(0, 4) },
    kit: rng.pick(KITS),
    rep,
    leagueId: def.id,
    budget: Math.round((def.country === 'JP' ? rep * 700 : rep * 2200) * rng.range(0.7, 1.3) / 100) * 100,
    facilities: facilitiesFor(rep, rng),
    stadium: { name: `${short}スタジアム`, capacity: stadiumCapacity(def.country, def.tier, rep, rng), grade: clamp(Math.round(rep / 22 + 0.5), 1, 5) },
    fans: Math.round(rep * rep * (def.country === 'JP' ? 12 : 40) * rng.range(0.8, 1.2)),
    popularity: clamp(Math.round(rep * 0.9 + rng.normal(0, 4)), 1, 100),
    tactics: tacticsForStyle(undefined, '4-4-2'),
    lineup: { starters: [], bench: [], manual: false },
    staff: [],
    isPlayer: false,
    lastRank: 0,
  }
}

export function createNewGame(opt: NewGameOptions): GameState {
  const rng = createRng(hashSeed(opt.seed, 0x77071d))
  const town = HOMETOWNS[opt.hometownIndex] ?? HOMETOWNS[0]
  const state: GameState = {
    schemaVersion: SCHEMA_VERSION,
    mode: 'club',
    seed: opt.seed >>> 0,
    startYear: opt.startYear ?? 2026,
    season: 0,
    week: 0,
    playerClubId: -1,
    nextId: { player: 1, staff: 1, fixture: 1, offer: 1 },
    players: {},
    staff: {},
    clubs: [],
    competitions: [],
    news: [],
    hometown: { ...town, development: 10 },
    finance: [],
    seasons: [],
    money: { negWeeks: 0, bailouts: 0 },
    offers: [],
    scout: { knowledge: {}, missions: [], watch: [] },
    forSale: {},
    transfers: [],
    chem: {},
    records: emptyRecords(),
    trophies: [],
    celebrated: 0,
    hallOfFame: [],
  }

  // ---- 大会とクラブ ----
  const domestic = [NPL1, NPL2, NPL3]
  for (const def of [...domestic, ...FOREIGN_LEAGUES]) {
    const comp: Competition = {
      id: def.id,
      kind: 'league',
      name: def.name,
      short: def.short,
      country: def.country,
      tier: def.tier,
      season: 0,
      clubIds: [],
      fixtures: [],
      table: [],
      promotion: def.country === 'JP' && def.tier > 1 ? 2 : 0,
      relegation: def.country === 'JP' && def.tier < 3 ? 2 : 0,
      playoff: def.country === 'JP' && def.tier > 1,
      simulated: def.country === 'JP' ? 'full' : 'fast',
    }
    state.competitions.push(comp)
    def.clubs.forEach((_, i) => {
      const c = makeClub(state.clubs.length, def, i, rng)
      state.clubs.push(c)
      comp.clubIds.push(c.id)
    })
    if (def.id === 'NPL3') {
      // プレイヤーの新クラブ
      const c: Club = {
        id: state.clubs.length,
        name: opt.clubName,
        short: opt.clubShort,
        country: 'JP',
        city: town.city,
        colors: opt.colors,
        emblem: opt.emblem ?? { shape: 0, charge: 0, pattern: 0 },
        kit: opt.kit ?? 'solid',
        rep: 22,
        leagueId: def.id,
        budget: 30000,
        facilities: { training: 1, medical: 1, dorm: 1, analysis: 0, youth: 1, pr: 0, lodge: 0, scoutOffice: 0 },
        stadium: { name: `${town.city}市民スタジアム`, capacity: 5000, grade: 1 },
        fans: 1500 + Math.round(town.population * 20 * (town.passion / 50)),
        popularity: 8,
        tactics: tacticsForStyle('balance', '4-4-2'),
        lineup: { starters: [], bench: [], manual: false },
        staff: [],
        isPlayer: true,
        lastRank: 0,
      }
      state.clubs.push(c)
      comp.clubIds.push(c.id)
      state.playerClubId = c.id
    }
  }

  // ---- スタッフ ----
  for (const club of state.clubs) {
    for (const role of CLUB_STAFF_ROLES) {
      const base = club.isPlayer ? 42 : club.rep * 0.75 + 12
      const s = generateStaff(state, rng, role, club.id, base + rng.normal(0, 7), club.country)
      state.staff[s.id] = s
      club.staff.push(s.id)
    }
    const mgr = state.staff[club.staff[0]]
    const fav = Object.entries(mgr.formations ?? {}).sort((a, b) => b[1] - a[1])[0]?.[0] ?? '4-4-2'
    club.tactics = tacticsForStyle(mgr.style, fav)
  }

  // ---- 選手 ----
  for (const club of state.clubs) {
    // 新クラブの選手は NPL3 の中位くらいの強さで作る（格そのものは 22 から）
    if (club.isPlayer) club.rep = 27
    for (const p of generateSquad(state, rng, club.id)) state.players[p.id] = p
    if (club.isPlayer) club.rep = 22
  }
  // ワールドリーグ（M24。クラブモードだけ）: スター選手は再編のあとのリーグに置く
  if (!opt.noWorldLeague) formWorldLeague(state)
  placeStarPlayers(state, rng)
  placeStarStaff(state, rng)
  {
    // 新クラブの作戦はバランス型。フォーメーションは、いまの選手の合い方と監督の慣れの両方で選ぶ
    // （試合エンジンで扱いやすいものから。4-4-2・4-3-3・5-3-2 は今の試合エンジンでは損をしやすい → M9 で調整）
    const me = state.clubs[state.playerClubId]
    const fam = state.staff[me.staff[0]]?.formations ?? {}
    let best = { id: '4-2-3-1', s: -1 }
    for (const f of FORMATIONS.filter((x) => ['4-4-2D', '4-2-3-1', '4-3-1-2', '4-1-4-1', '3-4-2-1'].includes(x.id))) {
      me.tactics = tacticsForStyle('balance', f.id)
      const s = teamStrength(state, { ...me, lineup: autoLineup(state, me) }) * (0.94 + 0.06 * ((fam[f.id] ?? 50) / 100))
      if (s > best.s) best = { id: f.id, s }
    }
    me.tactics = tacticsForStyle('balance', best.id)
  }

  // ---- フリーの選手とスタッフ ----
  for (let i = 0; i < 70; i++) {
    const pos = rng.pick(['GK', 'CB', 'CB', 'SB', 'DM', 'CM', 'CM', 'AM', 'WG', 'ST', 'ST'] as const)
    const age = rng.int(18, 34)
    const p = generatePlayer(state, rng, { clubId: -1, pos, targetOvr: rng.range(34, 55), age, country: rng.chance(0.75) ? 'JP' : rng.pick(['BR', 'ES', 'EN', 'FR', 'DE']), contractYears: -1 })
    state.players[p.id] = p
  }
  const freeRoles = ['manager', 'manager', 'manager', 'headCoach', 'headCoach', 'attackCoach', 'defenseCoach', 'physicalCoach', 'gkCoach', 'mentalCoach', 'physio', 'analyst', 'scout', 'scout', 'youthCoach'] as const
  for (let i = 0; i < 30; i++) {
    const s = generateStaff(state, rng, freeRoles[i % freeRoles.length], -1, rng.range(30, 70), rng.chance(0.7) ? 'JP' : rng.pick(['ES', 'BR', 'DE', 'EN']))
    state.staff[s.id] = s
  }

  // ---- 日程・先発 ----
  for (const comp of state.competitions) scheduleLeague(state, comp, createRng(hashSeed(state.seed, hashString(comp.id), 1)))
  ensureAmateurClubs(state)
  ensureAsiaClubs(state)
  createCup(state)
  createContinental(state)
  for (const club of state.clubs) club.lineup = autoLineup(state, club)

  const me = state.clubs[state.playerClubId]
  state.news.push({ absWeek: 0, category: 'club', mine: true, text: `${town.city}に新クラブ「${me.name}」が誕生！ NPL ディビジョン3 からの挑戦が始まる。` })
  // オーナーの最初のシーズンの目標（M19）
  setOwnerGoals(state)
  ensureRival(state)
  initNational(state)
  assignPhotos(state)
  return state
}

/** アジアのクラブ（アジアクラブカップにだけ出る。リーグ戦はしない）を用意する。古いセーブでも呼べる */
export function ensureAsiaClubs(state: GameState) {
  if (state.competitions.some((c) => c.id === ASIA_ID)) return
  const rng = createRng(hashSeed(state.seed, 0xa51a))
  const comp: Competition = { id: ASIA_ID, kind: 'league', name: 'アジアのクラブ', short: 'ASIA', country: 'AS', tier: 1, season: state.season, clubIds: [], fixtures: [], table: [], promotion: 0, relegation: 0, playoff: false, simulated: 'fast', hidden: true }
  for (const [name, short, primary, secondary, rep, country] of ASIA_CLUBS) {
    const def: LeagueDef = { id: ASIA_ID, name: comp.name, short: 'ASIA', country, tier: 1, clubs: [[name, short, primary, secondary, rep]] }
    const club = makeClub(state.clubs.length, def, 0, rng)
    // お金と人気の規模は日本と同じくらい
    club.budget = Math.round((rep * 900 * rng.range(0.8, 1.3)) / 100) * 100
    club.fans = Math.round(rep * rep * 10 * rng.range(0.8, 1.2))
    state.clubs.push(club)
    comp.clubIds.push(club.id)
    comp.table.push(emptyRow(club.id))
    for (const role of CLUB_STAFF_ROLES) {
      const s = generateStaff(state, rng, role, club.id, rep * 0.75 + 12 + rng.normal(0, 7), country)
      state.staff[s.id] = s
      club.staff.push(s.id)
    }
    const mgr = state.staff[club.staff[0]]
    const fav = Object.entries(mgr.formations ?? {}).sort((a, b) => b[1] - a[1])[0]?.[0] ?? '4-4-2'
    club.tactics = tacticsForStyle(mgr.style, fav)
    for (const p of generateSquad(state, rng, club.id)) state.players[p.id] = p
    club.lineup = autoLineup(state, club)
  }
  state.competitions.push(comp)
}

/** スター選手を格に応じたクラブに置き、同じポジションの一番弱い選手と入れ替える */
function placeStarPlayers(state: GameState, rng: Rng) {
  const absWeek = state.season * WEEKS_PER_SEASON + state.week
  for (const g of STAR_PLAYER_GAME) {
    const cast = STAR_PLAYERS.find((c) => c.id === g.id)!
    const comp = state.competitions.find((c) => c.id === g.league)
    let clubId = -1
    if (comp) {
      const clubs = comp.clubIds.map((id) => state.clubs[id]).filter((c) => !c.isPlayer).sort((a, b) => b.rep - a.rep)
      clubId = clubs[Math.min(clubs.length - 1, Math.round(g.clubTier * (clubs.length - 1)))].id
    }
    const srng = createRng(hashSeed(state.seed, hashString(g.id)))
    const p = generatePlayer(state, srng, { clubId, pos: g.pos, targetOvr: g.ovr, age: cast.age, nation: cast.nation, contractYears: srng.int(1, 3) })
    p.name = cast.name
    p.short = cast.name.includes('・') ? cast.name.split('・').pop()! : cast.name.slice(0, 2)
    p.starId = g.id
    p.growth = g.growth
    p.personality = g.personality
    p.skills = [...g.skills]
    p.heightCm = g.heightCm
    p.foot = g.foot
    p.apt = buildAptitudes(srng, g.pos)
    if (g.pos2) p.apt[g.pos2] = Math.max(p.apt[g.pos2], 82)
    // 将来の総合値が pot になるよう上限を作る
    p.cap = buildCap(srng, p.attr, g.pos, cast.age, g.growth)
    const potNow = rawRating(p.cap, g.pos)
    const scale = g.pot / Math.max(1, potNow)
    for (const k in p.cap) {
      const key = k as keyof typeof p.cap
      p.cap[key] = Math.round(Math.max(p.attr[key] + 0.5, Math.min(99, p.cap[key] * scale)) * 10) / 10
    }
    p.birthAbsWeek = absWeek - cast.age * WEEKS_PER_SEASON - srng.int(0, WEEKS_PER_SEASON - 1)
    const country = clubId >= 0 ? state.clubs[clubId].country : 'JP'
    p.contract.wage = fairWage(g.ovr, cast.age, country)
    p.number = 0
    state.players[p.id] = p
    if (clubId >= 0) {
      // 同じ列（FW/MF/DF/GK）の一番弱い選手を外してフリーにする
      const line = POSITION_DEFS[g.pos].line
      const mates = Object.values(state.players).filter((q) => q.clubId === clubId && q.id !== p.id && !q.starId && POSITION_DEFS[q.pos].line === line)
      const weakest = mates.sort((a, b) => rawRating(a.attr, a.pos) - rawRating(b.attr, b.pos))[0]
      if (weakest) {
        weakest.clubId = -1
        weakest.number = 0
      }
      // 背番号はシートの番号を優先
      const taken = new Set(Object.values(state.players).filter((q) => q.clubId === clubId && q.id !== p.id).map((q) => q.number))
      p.number = taken.has(cast.number) ? 0 : cast.number
      assignNumbers(Object.values(state.players).filter((q) => q.clubId === clubId), rng)
    }
  }
}

function placeStarStaff(state: GameState, rng: Rng) {
  const me = state.clubs[state.playerClubId]
  for (const g of STAR_STAFF_GAME) {
    const cast = STAR_STAFF.find((c) => c.id === g.id)!
    let clubId = -1
    if (g.where === 'PLAYER') clubId = me.id
    else if (g.where !== 'FREE') {
      const comp = state.competitions.find((c) => c.id === g.where)!
      clubId = comp.clubIds.map((id) => state.clubs[id]).sort((a, b) => b.rep - a.rep)[rng.int(0, 2)].id
    }
    const srng = createRng(hashSeed(state.seed, hashString(g.id)))
    const s: Staff = generateStaff(state, srng, g.role, clubId, g.ability, clubId >= 0 ? state.clubs[clubId].country : 'JP')
    s.name = cast.name
    s.nation = cast.nation
    s.starId = g.id
    s.personality = g.personality
    s.female = g.female
    s.birthAbsWeek = -cast.age * WEEKS_PER_SEASON - srng.int(0, 47)
    if (g.role === 'manager') {
      s.style = g.style
      s.formations = Object.fromEntries(FORMATIONS.map((f) => [f.id, g.formations?.includes(f.id) ? 95 : 60]))
    }
    s.wage = staffWage(g.role, g.ability, clubId >= 0 ? state.clubs[clubId].country : 'EN')
    s.until = state.season + 2
    state.staff[s.id] = s
    if (clubId >= 0) {
      const club = state.clubs[clubId]
      // 同じ役割のスタッフがいればフリーに戻す
      const same = club.staff.find((id) => state.staff[id].role === g.role)
      if (same !== undefined) {
        state.staff[same].clubId = -1
        club.staff = club.staff.filter((id) => id !== same)
      }
      club.staff.push(s.id)
    }
  }
}

/** プレイヤーのクラブの選手（テストや画面用） */
export function playerSquad(state: GameState): Player[] {
  return Object.values(state.players).filter((p) => p.clubId === state.playerClubId && !p.retired)
}
