/**
 * キャリアのクラブのランク（ステップアップの目安）。キャリアで行けるのは日本と欧州 5 か国のリーグだけ。
 *   E 国内 3 部 → D 国内 2 部 → C 国内 1 部 → B 欧州・中堅 → A 欧州・強豪 → S 欧州・ビッグクラブ
 * 欧州はクラブの格（rep）で分ける（格は年ごとに動くので、ランクも動く）。
 */
import type { Club } from '../models/club'
import type { GameState } from '../models/game'

export const CAREER_EUROPE = ['EN', 'ES', 'IT', 'DE', 'FR']

export type RankGrade = 'E' | 'D' | 'C' | 'B' | 'A' | 'S'

export interface RankDef {
  grade: RankGrade
  name: string
  /** ランクの段（0 = E 〜 5 = S） */
  step: number
}

export const RANKS: RankDef[] = [
  { grade: 'E', name: '国内3部', step: 0 },
  { grade: 'D', name: '国内2部', step: 1 },
  { grade: 'C', name: '国内1部', step: 2 },
  { grade: 'B', name: '欧州・中堅', step: 3 },
  { grade: 'A', name: '欧州・強豪', step: 4 },
  { grade: 'S', name: '欧州・ビッグクラブ', step: 5 },
]

/** 欧州のクラブの格の境目（強豪・ビッグクラブ） */
const EU_STRONG = 72
const EU_BIG = 81

export function clubRank(state: GameState, club: Club | undefined): RankDef | undefined {
  if (!club) return undefined
  if (club.country === 'JP') {
    const tier = state.competitions.find((c) => c.id === club.leagueId)?.tier
    return tier === 1 ? RANKS[2] : tier === 2 ? RANKS[1] : tier === 3 ? RANKS[0] : undefined
  }
  if (!CAREER_EUROPE.includes(club.country)) return undefined
  return club.rep >= EU_BIG ? RANKS[5] : club.rep >= EU_STRONG ? RANKS[4] : RANKS[3]
}

/** 主人公の今のランク */
export function myRank(state: GameState): RankDef | undefined {
  const p = state.career ? state.players[state.career.playerId] : undefined
  return p && p.clubId >= 0 ? clubRank(state, state.clubs[p.clubId]) : undefined
}

/** これまでに届いたいちばん上のランク（シーズンの記録と今のクラブから） */
export function bestRank(state: GameState): RankDef | undefined {
  const c = state.career
  if (!c) return undefined
  const steps = c.log.map((l) => l.rank ?? -1)
  const now = myRank(state)
  if (now) steps.push(now.step)
  const best = Math.max(-1, ...steps)
  return best >= 0 ? RANKS[best] : undefined
}
