/**
 * 子どもの成長と家族の行事（M12）。
 *   子ども: 年齢の節目で会話（1 歳 はじめての一歩 … 12 歳 卒業式とジュニアユースのセレクション。data/career.ts の CHILD_MILESTONES）。
 *     8 歳の「サッカーを始めたい」の選び方で、サッカーをするか・才能が決まる。誕生日は「最近の出来事」に一行。
 *     引退の総括に将来の一言（childFuture）。
 *   家族の行事: 結婚していれば、シーズンに 1 回ずつ（夏祭り・クリスマス会・お正月・こどもの日・父の日）。試合のない週に。
 * 会話が残っているときは待ち、1 週に 1 つまで。乱数は使わない。
 */
import { absWeekOf, monthOfWeek, WEEKS_PER_SEASON } from '../core/calendar'
import { CHILD_MILESTONES, FAMILY_EVENTS } from '../data/career'
import type { GameState } from '../models/game'
import type { Child } from '../models/career'
import { clamp, report } from './core'
import { queueTalk } from './events'
import { partnerName } from './family'

export function childAge(state: GameState, child: Child): number {
  return Math.floor((absWeekOf(state.season, state.week) - child.bornAbsWeek) / WEEKS_PER_SEASON)
}

/** いちばん上の子の年齢（子どもがいなければ -1） */
export function oldestChildAge(state: GameState): number {
  const kids = state.career!.children ?? []
  return kids.length ? Math.max(...kids.map((k) => childAge(state, k))) : -1
}

function matchThisWeek(state: GameState): boolean {
  const now = absWeekOf(state.season, state.week)
  const clubId = state.players[state.career!.playerId].clubId
  return state.competitions.some((comp) => comp.fixtures.some((f) => f.absWeek === now && (f.home === clubId || f.away === clubId)))
}

export function childrenWeek(state: GameState) {
  const c = state.career!
  // 見守り期（M17）は親が引退していても続ける
  if (!c.spouse || (c.retired && c.saga?.phase !== 'watch')) return
  const now = absWeekOf(state.season, state.week)
  const kids = c.children ?? []
  // 誕生日
  kids.forEach((k) => {
    const weeks = now - k.bornAbsWeek
    if (weeks > 0 && weeks % WEEKS_PER_SEASON === 0) {
      const p = state.players[c.playerId]
      p.condition = clamp(p.condition + 2, 0, 100)
      report(state, `${k.name}が ${weeks / WEEKS_PER_SEASON} 歳になった。家族でお祝いをした。`)
    }
  })
  if (c.talks.length) return
  const partner = partnerName(state)
  // 子どもの節目（古いセーブで、とうに過ぎた節目は飛ばす）
  for (let i = 0; i < kids.length; i++) {
    const k = kids[i]
    const age = childAge(state, k)
    for (const m of CHILD_MILESTONES) {
      if ((k.done ?? []).includes(m.id) || age < m.age) continue
      if (m.soccer && !k.soccer) continue
      k.done = [...(k.done ?? []), m.id]
      if (age >= m.age + 2) continue
      queueTalk(state, m.id, { child: k.name, childIdx: String(i), partner })
      return
    }
  }
  // 家族の行事（その月のうちの試合のない週。なければ月の最後の週）
  const month = monthOfWeek(state.week)
  const ev = FAMILY_EVENTS.find((e) => e.month === month && (!e.kids || kids.length > 0) && c.familyEvents?.[e.id] !== state.season)
  if (!ev) return
  // 見守り期は 1 シーズンに 1 つまで（1 か月ずつ進むので、行事ばかりにならないように）
  if (c.saga?.phase === 'watch' && Object.values(c.familyEvents ?? {}).includes(state.season)) return
  if (matchThisWeek(state) && state.week % 4 !== 3) return
  c.familyEvents = { ...c.familyEvents, [ev.id]: state.season }
  const youngest = kids[kids.length - 1]
  queueTalk(state, `fam_ev:${ev.id}:${kids.length ? 1 : 0}`, { child: youngest?.name ?? '', partner })
}

/** 引退の総括: 子どもの将来の一言（サッカーと才能、年齢で変わる） */
export function childFuture(state: GameState, child: Child): string {
  const age = childAge(state, child)
  const t = child.talent ?? 0
  if (age < 4) return `${child.name}（${age} 歳）は、ボールを追いかけるのが大好き。`
  if (age < 8) return `${child.name}（${age} 歳）は、毎朝パパの練習のまねをしている。`
  if (!child.soccer) return `${child.name}（${age} 歳）は、サッカーとは別の好きなことを見つけ、毎日夢中になっている。`
  if (t >= 4) return `${child.name}（${age} 歳）は、ジュニアユースで背番号 10 を背負い、プロのスカウトも注目している。`
  if (t >= 2) return `${child.name}（${age} 歳）は、地元の少年団でキャプテンを務めている。`
  return `${child.name}（${age} 歳）は、仲間と一緒に、楽しそうにボールを蹴っている。`
}
