export const SKILL_BY_ID = Object.fromEntries(SKILLS.map((s) => [s.id, s])) as Record<string, SkillDef>

/** 能力の条件を満たすか */
export function meetsSkillReq(s: SkillDef, attr: Attrs, pos: Position): boolean {
  if (!s.req) return false
  if (s.req.pos && !s.req.pos.includes(pos)) return false
  if (s.req.attrs) {
    for (const [k, v] of Object.entries(s.req.attrs)) if (attr[k as AttrKey] < (v as number)) return false
  }
  return true
}
