/**
 * ワールドリーグの世界級のバージョンアップ（M24 の 2 回目。クラブモードの自クラブ）。ワールドリーグに所属しているあいだに開く:
 *   施設 Lv6〜8（世界水準。費用は 1.6 倍）・スタジアム 10 万人とグレード 6〜7
 *   グローバルパートナー（4 つ目のスポンサー枠）・スポンサーの額 ×4（1 部は ×2.2）
 *   分配金 15 億（1 部は 3.5 億）・賞金（優勝 15 億）
 *   海外のファン（club.worldFans）: 毎週増え、海外向けオンラインストア（グッズ）と海外からの観戦（観客）に効く。WL を離れると少しずつ減る
 *   世界のスタッフ（シーズンのはじめに 6 人。WL のクラブとしか契約しない）・スカウトは 4 人まで
 * 一度建てた施設・スタジアムは WL を離れても残る（それ以上は上げられない）。
 */
import { absWeekOf } from '../core/calendar'
import { createRng, hashSeed } from '../core/prng'
import { generateStaff } from '../gen/staffGen'
import type { Club } from '../models/club'
import type { GameState } from '../models/game'
import type { StaffRole } from '../models/staff'
import { ovr } from '../player/overall'

export const WL = 'WL'

export function inWorld(club: Club): boolean {
  return club.leagueId === WL
}

/** 施設・スタジアムの上限（国内 / ワールドリーグ） */
export const DOMESTIC_FACILITY = 5
export const WORLD_FACILITY = 8
export const DOMESTIC_CAPACITY = 80000
export const WORLD_CAPACITY = 100000
export const DOMESTIC_GRADE = 5
export const WORLD_GRADE = 7

export function facilityMax(club: Club): number {
  return inWorld(club) ? WORLD_FACILITY : DOMESTIC_FACILITY
}
export function capacityMax(club: Club): number {
  return inWorld(club) ? WORLD_CAPACITY : DOMESTIC_CAPACITY
}
export function gradeMax(club: Club): number {
  return inWorld(club) ? WORLD_GRADE : DOMESTIC_GRADE
}

/** 分配金（シーズンあたり） */
export const WL_TV = 150000
/** 賞金: 優勝・3 位以内・6 位以内 */
export const WL_PRIZE = [150000, 60000, 25000]
export function worldPrize(rank: number): number {
  return rank === 1 ? WL_PRIZE[0] : rank <= 3 ? WL_PRIZE[1] : rank <= 6 ? WL_PRIZE[2] : 0
}
/** スポンサーの額の倍率（1 部は 2.2） */
export const WL_SPONSOR_MUL = 4

// ---------------------------------------------------------------- 海外のファン

export const WORLD_FANS_MAX = 5_000_000
/** 海外向けオンラインストアの Lv（0〜3）と費用 */
export const GLOBAL_STORE_MAX = 3
export const GLOBAL_STORE_COST = [0, 8000, 16000, 30000]

/** 毎週: 海外のファンが増える（WL にいれば。順位・人気・格・目玉の選手で）。離れると 2% ずつ減る */
export function worldFansWeek(state: GameState, club: Club) {
  const fans = club.worldFans ?? 0
  if (!inWorld(club)) {
    if (fans > 0) club.worldFans = Math.floor(fans * 0.98)
    return
  }
  const wl = state.competitions.find((c) => c.id === WL)
  const row = wl?.table.find((r) => r.clubId === club.id)
  const rank = row ? 1 + (wl?.table.filter((r) => r.points > row.points).length ?? 0) : 18
  let stars = 0
  for (const p of Object.values(state.players)) if (p.clubId === club.id && !p.retired && !p.isYouth && (p.starId || ovr(p) >= 80)) stars++
  const grow = 3000 + club.popularity * 60 + club.rep * 20 + (19 - rank) * 150 + Math.min(5, stars) * 400
  club.worldFans = Math.min(WORLD_FANS_MAX, fans + Math.round(grow))
}

export function globalStoreLevel(club: Club): number {
  return club.sales?.globalStore ?? 0
}

/** 海外のファンからのグッズ収入（シーズンあたり）。オンラインストアの Lv で増える */
export function worldGoods(club: Club): number {
  const fans = club.worldFans ?? 0
  if (!fans) return 0
  return Math.round(fans * 0.025 * (0.5 + club.popularity / 100) * (0.5 + 0.35 * globalStoreLevel(club)))
}

/** 海外から観に来る人（ホームの試合ごと） */
export function worldVisitors(club: Club): number {
  return Math.round((club.worldFans ?? 0) * 0.003)
}

export function canUpgradeStore(club: Club): { ok: boolean; reason?: string; cost?: number } {
  const lv = globalStoreLevel(club)
  if (lv >= GLOBAL_STORE_MAX) return { ok: false, reason: '最大' }
  if (!inWorld(club)) return { ok: false, reason: 'ワールドリーグで開く' }
  const cost = GLOBAL_STORE_COST[lv + 1]
  if (club.budget < cost) return { ok: false, reason: '資金が足りない', cost }
  return { ok: true, cost }
}

export function upgradeStore(state: GameState): boolean {
  const club = state.clubs[state.playerClubId]
  const chk = canUpgradeStore(club)
  if (!chk.ok || !chk.cost) return false
  club.budget -= chk.cost
  club.sales = { ticket: 2, seasonTickets: false, ...club.sales, globalStore: globalStoreLevel(club) + 1 }
  const last = state.finance[state.finance.length - 1]
  if (last) last.other -= chk.cost
  state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'club', mine: true, text: `海外向けオンラインストアを Lv${club.sales.globalStore} に広げました。` })
  return true
}

// ---------------------------------------------------------------- 世界のスタッフ

const WORLD_ROLES: StaffRole[] = ['manager', 'headCoach', 'attackCoach', 'defenseCoach', 'physicalCoach', 'scout']
const WORLD_COUNTRIES = ['ES', 'EN', 'IT', 'DE', 'FR', 'BR']

/** スカウトは何人まで（WL は 4 人） */
export function scoutLimit(club: Club): number {
  return inWorld(club) ? 4 : 3
}

/** シーズンのはじめ: 自クラブが WL にいれば、世界のスタッフ 6 人を入れ替える（契約しなかった人は去る） */
export function refreshWorldStaff(state: GameState) {
  if (state.mode !== 'club') return
  for (const id in state.staff) {
    const s = state.staff[id]
    if (s.world && s.clubId < 0) delete state.staff[id]
  }
  const me = state.clubs[state.playerClubId]
  if (!inWorld(me)) return
  const rng = createRng(hashSeed(state.seed, state.season, 0x3077))
  for (const role of WORLD_ROLES) {
    const s = generateStaff(state, rng, role, -1, rng.range(80, 94), rng.pick(WORLD_COUNTRIES))
    s.world = true
    state.staff[s.id] = s
  }
  state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'staff', mine: true, text: '世界の名伯楽たちが、ワールドリーグのクラブで働く先を探しています（クラブ → スタッフ → スタッフを探す）。' })
}
