/**
 * キャリアのイベント（会話）。台詞と効果はデータ（dialogue/*）で持つ。
 *   発生: おでかけで人に会ったとき（その人の次の段階のイベント）・節目（入団・初出場・初ゴール・移籍・シーズン終了）
 *   反映: 会話を見終わったとき（選択肢があれば選んだもの）に、絆・経験点・コツ・調子・評価・知名度・恋人を反映する
 * 全年齢向け: romance のイベントは canRomance（大人どうしで、相談相手でない人）のときだけ起きる。
 */
import { absWeekOf } from '../core/calendar'
import type { GameState } from '../models/game'
import { CAST_BY_ID, DATE_SPOT_BY_ID } from '../data/career'
import type { DateSpotId } from '../models/career'
import { canMeet, canRomance, castName, clamp, report } from './core'
import { dateLines } from './dialogue/dates'
import { tripEvent } from './dialogue/trips'
import { mediaEvent } from './dialogue/media'
import { familyEvent } from './dialogue/children'
import { PARTNER_FLAVOR } from './dialogue/partner_events'
import { gainExp, shiftGrowth, type ExpCost } from './growth'
import { ALL_EVENTS, CHATS } from './dialogue'
import { marry, partnerId, partnerName } from './family'

/** 台詞 1 行: s = 話し手（人の id・me＝主人公・nar＝地の文）、t = 本文（{me}{club}{from} を差し込む） */
export interface TalkLineDef {
  s: string
  t: string
}

export interface EventEffect {
  bond?: number
  exp?: ExpCost
  /** コツ（特殊能力の id） */
  kotsu?: string
  condition?: number
  trust?: number
  fame?: number
  stamina?: number
  /** お金（万円。マイナスは出費） */
  money?: number
  /** 成長タイプを 1 段ずらす（+1 = 晩成のほうへ、-1 = 早熟のほうへ） */
  growthShift?: number
  /** 恋人になる（canRomance のときだけ有効） */
  lover?: boolean
  /** 結婚する（プロポーズを受けてもらった） */
  marry?: boolean
  /** 今季限りで引退する */
  retirePlan?: boolean
  /** 引退は先にのばす（来季も続ける） */
  retireNot?: boolean
  /** 子ども（会話の childIdx の子）: サッカーをするか・才能を足す */
  child?: { soccer?: boolean; talent?: number; path?: 'school' | 'clubYouth' }
}

export interface EventOption {
  id: string
  label: string
  /** 選んだあとの台詞 */
  lines?: TalkLineDef[]
  effect: EventEffect
  /** 自動プレイで選ぶ */
  auto?: boolean
}

export interface CareerEventDef {
  id: string
  /** 主に関わる人（絆が動く） */
  char?: string
  title: string
  /** outing = おでかけで会う、system = 節目（コードから呼ぶ） */
  trigger: 'outing' | 'system'
  /** その人とのイベントの順番（1 から） */
  step?: number
  /** 起きるのに要る絆 */
  minBond?: number
  /** 恋愛のイベント（大人どうしで、相談相手でない人のときだけ） */
  romance?: boolean
  /** 何シーズン目から（0 始まり） */
  minSeason?: number
  lines: TalkLineDef[]
  options?: EventOption[]
  /** 選択肢がないときの効果 */
  effect?: EventEffect
}

export const EVENT_BY_ID: Record<string, CareerEventDef> = Object.fromEntries(ALL_EVENTS.map((e) => [e.id, e]))

/** イベントを引く（雑談は chat:<人>:<番号>、デートは date:<人>:<行き先>:<好き>:<回数> で、その場で作る） */
export function getEvent(id: string): CareerEventDef | undefined {
  if (id.startsWith('date:')) {
    const [, who, spot, like, n] = id.split(':')
    const cast = CAST_BY_ID[who]
    const def = DATE_SPOT_BY_ID[spot as DateSpotId]
    if (!cast || !def) return undefined
    // 相手の名前は {who} のまま残し、出すときに今の世代の名前で埋める（fillLine）
    return { id, char: who, title: `デート（${def.name}）`, trigger: 'outing', lines: dateLines(who, '{who}', def.name, def.id, cast.trait ?? 'cheer', like === '1', Number(n)) }
  }
  if (id.startsWith('trip:')) return tripEvent(id)
  if (id.startsWith('media:')) return mediaEvent(id)
  if (id.startsWith('fam_ev:')) return familyEvent(id)
  if (id.startsWith('chat:')) {
    const [, char, n] = id.split(':')
    const lines = CHATS[char]?.[Number(n)]
    return lines ? { id, char, title: 'ひと息', trigger: 'outing', lines, effect: { bond: 4 } } : undefined
  }
  return EVENT_BY_ID[id]
}

/** その人との雑談（イベントがないとき） */
export function chatId(char: string, roll: number): string | null {
  const pool = CHATS[char]
  return pool?.length ? `chat:${char}:${Math.floor(roll * pool.length) % pool.length}` : null
}

/** その人の次のイベント（おでかけで会ったとき） */
export function nextEventFor(state: GameState, char: string): CareerEventDef | null {
  const c = state.career!
  const bond = c.bonds[char]?.value ?? 0
  const chain = ALL_EVENTS.filter((e) => e.char === char && e.trigger === 'outing' && e.step !== undefined).sort((a, b) => a.step! - b.step!)
  for (const e of chain) {
    if (c.done[e.id] !== undefined) continue
    if (bond < (e.minBond ?? 0)) return null
    if ((e.minSeason ?? 0) > state.season) return null
    if (e.romance && (!canRomance(state, char) || (c.partner && c.partner !== char))) return null
    return e
  }
  return null
}

/** おでかけ先で会える人（その場所にいて、今会う理由がある人を優先） */
export function whoIsAt(state: GameState, people: string[], roll: number): string | null {
  const c = state.career!
  const cand = people.filter((id) => {
    const cast = CAST_BY_ID[id]
    if (!cast || !canMeet(state, id)) return false
    // ライバルは 2 シーズン目から
    if (id === 'ozora_shota' && state.season < 1) return false
    return true
  })
  if (!cand.length) return null
  // 次のイベントがある人を重く
  const weights = cand.map((id) => (nextEventFor(state, id) ? 3 : 1) * (c.bonds[id] ? 1 : 1.5))
  let r = roll * weights.reduce((s, w) => s + w, 0)
  for (let i = 0; i < cand.length; i++) {
    r -= weights[i]
    if (r <= 0) return cand[i]
  }
  return cand[cand.length - 1]
}

/** 会話を予約する */
export function queueTalk(state: GameState, eventId: string, vars?: Record<string, string>) {
  state.career!.talks.push({ eventId, vars })
}

/** 効果を反映する */
export function applyEffect(state: GameState, char: string | undefined, e: EventEffect) {
  const c = state.career!
  const p = state.players[c.playerId]
  const now = absWeekOf(state.season, state.week)
  if (char && e.bond) {
    const b = (c.bonds[char] ??= { value: 0, lastAbsWeek: now })
    b.value = clamp(b.value + e.bond, 0, 100)
    b.lastAbsWeek = now
  }
  if (e.exp) gainExp(state, e.exp, 1)
  if (e.kotsu) c.kotsu[e.kotsu] = Math.min(3, (c.kotsu[e.kotsu] ?? 0) + 1)
  if (e.condition) p.condition = clamp(p.condition + e.condition, 0, 100)
  if (e.trust) c.trust = clamp(c.trust + e.trust, 0, 100)
  if (e.fame) c.fame = clamp(c.fame + e.fame, 0, 100)
  if (e.stamina) c.stamina = clamp(c.stamina + e.stamina, 0, 100)
  if (e.money) c.money += e.money
  if (e.growthShift) shiftGrowth(state, e.growthShift)
  if (e.lover && char && canRomance(state, char) && !c.partner) {
    c.partner = char
    c.loverAbsWeek = now
    const b = (c.bonds[char] ??= { value: 0, lastAbsWeek: now })
    b.lover = true
    report(state, `${castName(state, char) ?? ''}と付き合うことになった。`)
  }
  if (e.marry) marry(state)
  if (e.retirePlan) {
    c.retirePlanned = true
    report(state, '今季限りでの引退を決めた。残りの試合に全てを懸ける。')
  }
}

/**
 * 会話を見終わった（選択肢があれば optionId を選んだ）。効果を反映して予約から外す。
 * 返り値は選択肢のあとの台詞（なければ空）
 */
export function finishTalk(state: GameState, optionId?: string): TalkLineDef[] {
  const c = state.career!
  const t = c.talks.shift()
  if (!t) return []
  const ev = getEvent(t.eventId)
  if (!ev) return []
  // その場で組み立てる会話（雑談・旅行・メディア・家族の行事）は、済んだ記録に残さない
  if (!/^(chat|trip|media|fam_ev):/.test(ev.id)) c.done[ev.id] = absWeekOf(state.season, state.week)
  // 'partner' は結婚相手（いなければ恋人）
  const char = ev.char === 'partner' ? partnerId(state) : ev.char
  if (char) {
    const now = absWeekOf(state.season, state.week)
    c.bonds[char] ??= { value: 0, lastAbsWeek: now }
  }
  if (ev.options?.length) {
    const opt = ev.options.find((o) => o.id === optionId) ?? ev.options.find((o) => o.auto) ?? ev.options[0]
    applyEffect(state, char, opt.effect)
    applyChild(state, t.vars?.childIdx, opt.effect)
    return opt.lines ?? []
  }
  if (ev.effect) {
    applyEffect(state, char, ev.effect)
    applyChild(state, t.vars?.childIdx, ev.effect)
  }
  return []
}

/** 子どもの節目の効果（サッカーをするか・才能） */
function applyChild(state: GameState, idx: string | undefined, e: EventEffect) {
  if (!e.child || idx === undefined) return
  const k = state.career!.children?.[Number(idx)]
  if (!k) return
  if (e.child.soccer !== undefined) k.soccer = e.child.soccer
  if (e.child.talent) k.talent = clamp((k.talent ?? 0) + e.child.talent, 0, 5)
  if (e.child.path) k.path = e.child.path
}

/** 自動プレイ用: 予約された会話を全部済ませる */
export function finishAllTalks(state: GameState) {
  for (let i = 0; i < 50 && state.career!.talks.length; i++) finishTalk(state)
}

/** 台詞の差し込み */
export function fillLine(state: GameState, text: string, vars?: Record<string, string>): string {
  const c = state.career!
  const p = state.players[c.playerId]
  const club = p && p.clubId >= 0 ? state.clubs[p.clubId]?.name : undefined
  // 恋人・家族の出来事の個性の 1 行（予約のときに入れ忘れても、今の会話と恋人の個性から出す）
  const pid = partnerId(state)
  const cur = c.talks[0]?.eventId ?? ''
  const flavor = PARTNER_FLAVOR[cur]?.[(pid && CAST_BY_ID[pid]?.trait) || 'cheer'] ?? ''
  const kids = c.children ?? []
  // 世代をつなぐ物語（M17）: 親の名前
  const saga = c.saga
  const dateWho = cur.startsWith('date:') ? cur.split(':')[1] : undefined
  const all: Record<string, string> = { club: club ?? 'クラブ', partner: partnerName(state), flavor, child: kids[kids.length - 1]?.name ?? '', father: saga?.father?.name ?? '', mother: saga?.motherName ?? '', who: dateWho ? castName(state, dateWho) : '', ...vars }
  return (
    text
      .replace(/\{me\}/g, p?.short ?? '')
      .replace(/\{fullname\}/g, p?.name ?? '')
      // 分からない差し込みは消す（{xxx} のまま見せない）
      .replace(/\{(\w+)\}/g, (_m, k: string) => all[k] ?? '')
  )
}
