export const FORMATION_BY_ID = Object.fromEntries(FORMATIONS.map((f) => [f.id, f])) as Record<string, Formation>

/**
 * フォーメーションごとの補正（試合で先発の能力に掛ける）。試合エンジンの癖で、サイドの選手が多い形は弱く、
 * 中央に人の多い 2 トップは強く出るので、同じ選手で 4-2-3-1 と戦ったときの勝点がそろうように合わせる。
 * 測り方: npx tsx tools/formfit.ts 600 1 "<今の値の JSON>"（試合エンジンを変えたら測り直す）
 */
export const FORMATION_BALANCE: Record<string, number> = {
  '4-4-2': 1.076,
  '4-3-3': 1.006,
  '4-4-2D': 0.956,
  '4-1-4-1': 0.976,
  '4-3-1-2': 0.969,
  '3-5-2': 0.99,
  '3-4-3': 1.013,
  '3-4-2-1': 0.978,
  '5-3-2': 1.048,
}

export function formationBalance(id: string): number {
  return FORMATION_BALANCE[id] ?? 1
}

export function formationOf(id: string): Formation {
  return FORMATION_BY_ID[id] ?? FORMATIONS[0]
}

/** スロット同士の隣接（連携が育つ組み合わせ）。距離の近いスロットを結ぶ */
export function adjacency(f: Formation): [number, number][] {
  const out: [number, number][] = []
  for (let i = 0; i < f.slots.length; i++) {
    for (let j = i + 1; j < f.slots.length; j++) {
      const a = f.slots[i]
      const b = f.slots[j]
      const d = Math.hypot((a.u - b.u) * 1.5, a.v - b.v)
      if (d < 0.36) out.push([i, j])
    }
  }
  return out
}
