const pick = <T>(list: T[], n: number): T => list[n % list.length]

/** デートの会話を組み立てる */
export function dateLines(who: string, whoName: string, spotName: string, spot: DateSpotId, trait: PartnerTrait, like: boolean, n: number): TalkLineDef[] {
  const fill = (t: string) => t.replace(/\{who\}/g, whoName).replace(/\{spot\}/g, spotName)
  const [a, b] = DATE_INTRO[spot]
  const lines: TalkLineDef[] = [
    { s: 'nar', t: fill(a) },
    { s: 'nar', t: fill(b) },
    { s: who, t: fill(pick(like ? LIKE[trait] : NORMAL[trait], n)) },
  ]
  if (n === 3 && DATE3[who]) lines.push({ s: who, t: DATE3[who] })
  lines.push({ s: 'me', t: pick(CLOSE, n) })
  return lines
}
