/**
 * 選手枠と選手の整理（M22。クラブモードの自クラブ）。
 *   トップチームは 35 人まで（ユースアカデミーは別。レンタルで出している選手は数えない）
 *   枠がいっぱいだと新しく獲れない（獲得の交渉・高校とユースの有望株・ユースからの昇格）
 *   超えたとき（レンタルからの復帰など）と、シーズンのはじめ（選手登録）に知らせる
 * 選手の整理: 放出の候補（能力が低い・年長・出番がない）を上から並べ、まとめて解雇・売りに出す。
 *   ポジションごとの最低人数（GK 2・DF 6・MF 5・FW 3）と、全体の最低人数（18 人）は残す
 */
import { absWeekOf, WEEKS_PER_SEASON } from '../core/calendar'
import type { Position } from '../data/positions'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import { squadOf } from '../match/lineup'
import { marketValue, ovr, potentialOvr } from '../player/overall'
import { MIN_SQUAD, releaseCost, releasePlayer } from '../transfer/market'

export const ROSTER_LIMIT = 35

export interface RosterInfo {
  count: number
  limit: number
  /** あと何人入れられるか */
  free: number
  /** 何人超えているか */
  over: number
  full: boolean
}

export function rosterInfo(state: GameState): RosterInfo {
  const count = squadOf(state, state.playerClubId).length
  return { count, limit: ROSTER_LIMIT, free: Math.max(0, ROSTER_LIMIT - count), over: Math.max(0, count - ROSTER_LIMIT), full: count >= ROSTER_LIMIT }
}

/** 枠がいっぱいのときの知らせ */
export function rosterFullText(state: GameState): string {
  const r = rosterInfo(state)
  return `選手枠がいっぱいです（${r.count}/${r.limit}）。先に選手を整理してください。`
}

type Line = 'GK' | 'DF' | 'MF' | 'FW'
const LINE_OF: Record<Position, Line> = { GK: 'GK', CB: 'DF', SB: 'DF', WB: 'DF', DM: 'MF', CM: 'MF', AM: 'MF', SM: 'MF', WG: 'FW', ST: 'FW' }
/** 残さないといけない人数 */
export const LINE_MIN: Record<Line, number> = { GK: 2, DF: 6, MF: 5, FW: 3 }
export const LINE_LABEL: Record<Line, string> = { GK: 'GK', DF: 'DF', MF: 'MF', FW: 'FW' }

export interface ReleaseCandidate {
  p: Player
  ovr: number
  age: number
  role: 'starter' | 'bench' | 'out'
  /** 解雇の違約金（万円） */
  cost: number
  /** 今季で契約が切れる（待てばシーズン末にお金をかけずに退団） */
  expiring: boolean
  /** 大きいほど放出の候補 */
  score: number
  note: string
}

/** 放出の候補（候補らしい順） */
export function releaseCandidates(state: GameState): ReleaseCandidate[] {
  const me = state.clubs[state.playerClubId]
  const now = absWeekOf(state.season, state.week)
  const squad = squadOf(state, me.id)
  const starters = new Set(me.lineup.starters)
  const bench = new Set(me.lineup.bench)
  // チームの水準: 総合の上位 11 人の平均
  const top = squad.map(ovr).sort((a, b) => b - a).slice(0, 11)
  const level = top.reduce((s, x) => s + x, 0) / Math.max(1, top.length)
  return squad
    .map((p) => {
      const o = ovr(p)
      const age = Math.floor((now - p.birthAbsWeek) / WEEKS_PER_SEASON)
      const role: ReleaseCandidate['role'] = starters.has(p.id) ? 'starter' : bench.has(p.id) ? 'bench' : 'out'
      const upside = age <= 21 ? Math.min(15, potentialOvr(p) - o) : 0
      const expiring = p.contract.until <= state.season
      const score = (level - o) * 2 + Math.max(0, age - 29) * 3 - Math.max(0, upside) + (role === 'starter' ? -60 : role === 'bench' ? -15 : 0) + (p.loan ? -100 : 0)
      const notes: string[] = []
      if (role === 'starter') notes.push('先発')
      else if (role === 'bench') notes.push('ベンチ')
      if (level - o >= 5) notes.push(`チームの水準より ${Math.round(level - o)} 低い`)
      if (age >= 31) notes.push(`${age} 歳`)
      if (upside >= 8) notes.push('伸びしろあり')
      if (expiring) notes.push('今季で契約満了')
      return { p, ovr: o, age, role, cost: releaseCost(state, p), expiring, score, note: notes.join('・') }
    })
    .sort((a, b) => b.score - a.score)
}

/** まとめて外したあとに残る人数の確かめ（足りなくなるなら理由） */
export function releaseWarnings(state: GameState, ids: number[]): string[] {
  const squad = squadOf(state, state.playerClubId)
  const out = new Set(ids)
  const left = squad.filter((p) => !out.has(p.id))
  const warnings: string[] = []
  if (left.length < MIN_SQUAD) warnings.push(`選手が ${MIN_SQUAD} 人より少なくなります（残り ${left.length} 人）`)
  for (const line of Object.keys(LINE_MIN) as Line[]) {
    const n = left.filter((p) => LINE_OF[p.pos] === line).length
    if (n < LINE_MIN[line]) warnings.push(`${LINE_LABEL[line]} が ${n} 人になります（${LINE_MIN[line]} 人は残してください）`)
  }
  if (ids.some((id) => state.players[id]?.loan)) warnings.push('レンタルで来ている選手は外せません')
  return warnings
}

/** おすすめの放出: 候補の上から n 人（先発・レンタルで来ている選手は除き、最低人数は残す） */
export function suggestRelease(state: GameState, n: number): number[] {
  const picked: number[] = []
  for (const c of releaseCandidates(state)) {
    if (picked.length >= n) break
    if (c.role === 'starter' || c.p.loan) continue
    if (releaseWarnings(state, [...picked, c.p.id]).length) continue
    picked.push(c.p.id)
  }
  return picked
}

/** まとめて解雇する（違約金を払う）。外せた人数と違約金の合計 */
export function releaseMany(state: GameState, ids: number[]): { count: number; cost: number } {
  if (releaseWarnings(state, ids).length) return { count: 0, cost: 0 }
  let count = 0
  let cost = 0
  for (const id of ids) {
    const p = state.players[id]
    if (!p || p.clubId !== state.playerClubId) continue
    const c = releaseCost(state, p)
    if (releasePlayer(state, p)) {
      count++
      cost += c
    }
  }
  return { count, cost }
}

/** まとめて売りに出す（市場価値で。移籍期間に声がかかる） */
export function listMany(state: GameState, ids: number[]): number {
  let n = 0
  for (const id of ids) {
    const p = state.players[id]
    if (!p || p.clubId !== state.playerClubId || p.loan) continue
    state.forSale[p.id] = Math.max(100, Math.round(marketValue(p, absWeekOf(state.season, state.week), state.season) / 100) * 100)
    n++
  }
  return n
}
