/**
 * 経験点で能力・特殊能力を上げる（サクセス風）。
 *   能力: 1 上げるのに要る経験点は今の値が高いほど増える。種類の内訳は ATTR_EXP
 *   特殊能力: 金 360・青 180（コツ 1 段ごとに 2 割引き）。ポジションの条件があり、能力の条件はコツがあれば無視できる
 *   年齢: ピーク年齢のタイプ（p.growth）の年齢カーブで経験点の入り方が変わる（expMul）。衰えもタイプで始まる年齢が違う
 *   余った経験点は振り替えられる（3 → 2。convertExp）。かんたん育成では自動で振り替える
 *   簡単モード（growthMode = 'easy'）: 毎週と試合のあとに easyGrowth が、最近の練習で鍛えた能力（focus）を中心に自動で上げる
 */
import { ATTR_BY_KEY, ATTR_KEYS, type AttrKey } from '../data/attributes'
import { ATTR_EXP, PLAY_STYLE_BY_ID } from '../data/career'
import { SKILLS, type SkillDef, type SkillHook } from '../data/skills'
import type { GameState } from '../models/game'
import type { ExpKind } from '../models/career'
import { EXP_KINDS } from '../models/career'
import { report } from './core'
import { POSITION_DEFS } from '../data/positions'
import { ageCurve, GROWTH_DEFS, GROWTH_TYPES, type GrowthType } from '../data/growth'
import { absWeekOf, WEEKS_PER_SEASON } from '../core/calendar'

export type ExpCost = Partial<Record<ExpKind, number>>

/** 能力を 1 上げる費用 */
export function attrCost(key: AttrKey, value: number): ExpCost {
  const total = 6 + (value / 10) ** 2 * 1.9
  const out: ExpCost = {}
  for (const [k, r] of Object.entries(ATTR_EXP[key]) as [ExpKind, number][]) out[k] = Math.ceil(total * r)
  return out
}

/** 払えるか。reserve は種類ごとに残しておく量（数なら全種類同じ） */
export function canAfford(state: GameState, cost: ExpCost, reserve: number | ExpCost = 0): boolean {
  const c = state.career!
  const keep = (k: ExpKind) => (typeof reserve === 'number' ? reserve : (reserve[k] ?? 0))
  return EXP_KINDS.every((k) => !(cost[k] ?? 0) || c.exp[k] - (cost[k] ?? 0) >= keep(k))
}

function pay(state: GameState, cost: ExpCost) {
  const c = state.career!
  for (const k of EXP_KINDS) c.exp[k] -= cost[k] ?? 0
}

/** 能力を 1 上げる（足りなければ false） */
export function raiseAttr(state: GameState, key: AttrKey): boolean {
  const p = state.players[state.career!.playerId]
  const v = p.attr[key]
  if (v >= 99) return false
  const cost = attrCost(key, v)
  if (!canAfford(state, cost)) return false
  pay(state, cost)
  p.attr[key] = Math.min(99, Math.floor(v) + 1)
  p.cap[key] = Math.max(p.cap[key], p.attr[key])
  return true
}

const HOOK_EXP: Record<SkillHook, ExpKind[]> = {
  shot: ['tech', 'mental'],
  pass: ['tech', 'tactics'],
  dribble: ['tech', 'speed'],
  tackle: ['power', 'tactics'],
  aerial: ['power', 'speed'],
  gk: ['speed', 'tech'],
  setpiece: ['tech', 'mental'],
  late: ['mental', 'power'],
  bigMatch: ['mental', 'tactics'],
  growth: ['mental', 'tactics'],
  injury: ['power', 'mental'],
  team: ['mental', 'tactics'],
  speed: ['speed', 'power'],
  stamina: ['power', 'mental'],
  penalty: ['mental', 'tech'],
}

export function skillCost(state: GameState, s: SkillDef): ExpCost {
  const lv = state.career!.kotsu[s.id] ?? 0
  const total = (s.tier === 'gold' ? 360 : 180) * (1 - 0.2 * lv)
  const [a, b] = HOOK_EXP[s.hook]
  return { [a]: Math.ceil(total * 0.6), [b]: Math.ceil(total * 0.4) }
}

/** 覚えられる特殊能力か（赤は覚えない。ポジションの条件は必須、能力の条件はコツがあれば無視） */
export function skillLearnable(state: GameState, s: SkillDef): boolean {
  const p = state.players[state.career!.playerId]
  if (s.tier === 'red' || p.skills.includes(s.id)) return false
  if (s.req?.pos && !s.req.pos.includes(p.pos)) return false
  if (state.career!.kotsu[s.id]) return true
  for (const [k, v] of Object.entries(s.req?.attrs ?? {})) if (p.attr[k as AttrKey] < (v as number) - 12) return false
  return true
}

export function learnSkill(state: GameState, id: string): boolean {
  const s = SKILLS.find((x) => x.id === id)
  if (!s || !skillLearnable(state, s)) return false
  const cost = skillCost(state, s)
  if (!canAfford(state, cost)) return false
  pay(state, cost)
  const p = state.players[state.career!.playerId]
  p.skills = [...p.skills, s.id].slice(-6)
  delete state.career!.kotsu[s.id]
  return true
}

/** 経験点の全体の倍率（成長の速さの調整つまみ。build/growth_curve.ts で測る） */
export const EXP_SCALE = 1.2

/** タイプの年齢カーブの形（伸び盛りで 1.45、外れると 0.3） */
function curveShape(type: GrowthType, age: number): number {
  return 0.3 + 1.15 * (ageCurve(type, age).up / GROWTH_DEFS[type].rise)
}

/** 18〜33 歳の平均が 1.1 になるようにそろえる（どのタイプも生涯で入る経験点はほぼ同じ。違うのは時期） */
const TYPE_NORM: Record<GrowthType, number> = Object.fromEntries(
  GROWTH_TYPES.map((t) => {
    let sum = 0
    for (let a = 18; a < 34; a += 0.25) sum += curveShape(t, a)
    return [t, 1.1 / (sum / 64)]
  }),
) as Record<GrowthType, number>

/**
 * ピーク年齢のタイプと年齢による経験点の倍率: そのタイプの伸びの年齢カーブ（data/growth.ts の ageCurve）の形。
 * 早熟は若いうちに多く入り、晩成は 20 代後半に多く入る
 */
export function expMulAt(type: GrowthType, age: number): number {
  return curveShape(type, age) * TYPE_NORM[type]
}

export function expMul(state: GameState): number {
  const c = state.career!
  const p = state.players[c.playerId]
  const age = (absWeekOf(state.season, state.week) - p.birthAbsWeek) / WEEKS_PER_SEASON
  return expMulAt(p.growth, age) * EXP_SCALE
}

/** 成長タイプを dir だけずらしたときのピークの変化（例「ピーク 26〜29歳 → 29〜32歳」。変わらなければ null） */
export function growthShiftHint(state: GameState, dir: number): string | null {
  const p = state.players[state.career!.playerId]
  const i = GROWTH_TYPES.indexOf(p.growth)
  const next = GROWTH_TYPES[Math.max(0, Math.min(GROWTH_TYPES.length - 1, i + dir))]
  if (next === p.growth) return null
  return `ピーク ${GROWTH_DEFS[p.growth].peak} → ${GROWTH_DEFS[next].peak}`
}

/** ピーク年齢のタイプを 1 段ずらす（+1 = 晩成のほうへ、-1 = 早熟のほうへ）。変わったら新しいタイプを返す */
export function shiftGrowth(state: GameState, dir: number): GrowthType | null {
  const p = state.players[state.career!.playerId]
  const i = GROWTH_TYPES.indexOf(p.growth)
  const next = GROWTH_TYPES[Math.max(0, Math.min(GROWTH_TYPES.length - 1, i + dir))]
  if (next === p.growth) return null
  p.growth = next
  report(state, `成長タイプが「${GROWTH_DEFS[next].name}」に変わった（ピークは ${GROWTH_DEFS[next].peak}）。`)
  return next
}

// ---------------------------------------------------------------- 経験点の振り替え

/** 振り替えの比率: 3 を 2 に */
export const CONVERT_RATE = 2 / 3

/** 余った経験点を別の種類に振り替える（from を amount 使って、to が amount × 2/3 増える） */
export function convertExp(state: GameState, from: ExpKind, to: ExpKind, amount: number): boolean {
  const c = state.career!
  if (from === to || amount <= 0 || c.exp[from] < amount) return false
  c.exp[from] -= amount
  c.exp[to] += Math.floor(amount * CONVERT_RATE)
  return true
}

/**
 * かんたん育成の自動の振り替え: ほかより大きく余っている種類（keep を超えた分）を、
 * 重みのある能力を上げるのにいちばん足りない種類へ回す
 */
function autoConvert(state: GameState, weights: Partial<Record<AttrKey, number>>, reserve: ExpCost) {
  const c = state.career!
  const p = state.players[c.playerId]
  // 種類ごとの「欲しさ」: 重みのある能力の次の 1 段の費用 × 重み
  const need: Record<ExpKind, number> = { power: 0, speed: 0, tech: 0, tactics: 0, mental: 0 }
  for (const [k, w] of Object.entries(weights) as [AttrKey, number][]) {
    if (p.attr[k] >= 99) continue
    for (const [kind, n] of Object.entries(attrCost(k, p.attr[k])) as [ExpKind, number][]) need[kind] += n * w
  }
  const keep = 150
  for (let guard = 0; guard < 10; guard++) {
    const from = EXP_KINDS.filter((k) => c.exp[k] - (reserve[k] ?? 0) > keep * 2).sort((a, b) => c.exp[b] - c.exp[a])[0]
    if (!from) return
    const to = EXP_KINDS.filter((k) => k !== from).sort((a, b) => need[b] / (c.exp[b] + 20) - need[a] / (c.exp[a] + 20))[0]
    if (!to || need[to] <= 0) return
    convertExp(state, from, to, Math.floor(c.exp[from] - (reserve[from] ?? 0) - keep))
  }
}

/** 経験点を足す（年齢の倍率つき）。足した量を返す */
export function gainExp(state: GameState, gain: ExpCost, mul = 1): ExpCost {
  const c = state.career!
  const m = expMul(state) * mul
  const out: ExpCost = {}
  for (const k of EXP_KINDS) {
    const v = Math.round((gain[k] ?? 0) * m)
    if (v) {
      c.exp[k] += v
      out[k] = v
    }
  }
  return out
}

/** おまかせで経験点を使う（今のポジションの重みで） */
export function autoSpendForPosition(state: GameState) {
  const p = state.players[state.career!.playerId]
  autoSpend(state, POSITION_DEFS[p.pos].weights)
}

/** おまかせで経験点を使う（自動プレイ用）: ポジションの重みが大きい能力から順に上げる。reserve は種類ごとに残しておく量 */
export function autoSpend(state: GameState, weights: Partial<Record<AttrKey, number>>, reserve: number | ExpCost = 0) {
  const p = state.players[state.career!.playerId]
  const keys = ATTR_KEYS.filter((k) => (weights[k] ?? 0) > 0)
  for (let guard = 0; guard < 400; guard++) {
    // 重み ÷ 費用 がいちばん得な能力
    let best: AttrKey | null = null
    let bestScore = 0
    for (const k of keys) {
      const cost = attrCost(k, p.attr[k])
      if (p.attr[k] >= 99 || !canAfford(state, cost, reserve)) continue
      const total = Object.values(cost).reduce((s, v) => s + (v ?? 0), 0)
      const score = (weights[k] ?? 0) / total
      if (score > bestScore) {
        bestScore = score
        best = k
      }
    }
    if (!best || !raiseAttr(state, best)) break
  }
}

// ---------------------------------------------------------------- 簡単モード


/** 鍛えた能力の重みを足す（練習・自主トレ・自宅の器具）。先頭の能力がいちばん重い */
export function addFocus(state: GameState, attrs: AttrKey[], amount = 1) {
  const c = state.career!
  const f = (c.focus ??= {})
  attrs.forEach((k, i) => (f[k] = (f[k] ?? 0) + amount * (i === 0 ? 1 : 0.6)))
}

/** 週ごとに重みを減らす（最近の練習ほど効く） */
export function decayFocus(state: GameState) {
  const f = state.career!.focus
  if (!f) return
  for (const k of Object.keys(f) as AttrKey[]) {
    f[k] = (f[k] ?? 0) * 0.7
    if ((f[k] ?? 0) < 0.05) delete f[k]
  }
}

export function isEasy(state: GameState): boolean {
  return state.career?.growthMode === 'easy'
}

/**
 * 簡単モードで目ざす特殊能力: コツのあるものと、プレースタイルの看板の特殊能力だけ（ほかは手で覚える）。
 * いちばんコツの段が高く、安いもの
 */
export function easySkillTarget(state: GameState): SkillDef | null {
  const c = state.career!
  const p = state.players[c.playerId]
  const styleKotsu = PLAY_STYLE_BY_ID[c.style].kotsu
  const cands = SKILLS.filter((s) => ((c.kotsu[s.id] ?? 0) > 0 || s.id === styleKotsu) && skillLearnable(state, s) && p.skills.length < 6)
  if (!cands.length) return null
  const total = (s: SkillDef) => Object.values(skillCost(state, s)).reduce((n, v) => n + (v ?? 0), 0)
  return [...cands].sort((a, b) => (c.kotsu[b.id] ?? 0) - (c.kotsu[a.id] ?? 0) || total(a) - total(b))[0]
}

/**
 * 簡単モード: 最近の練習で鍛えた能力を中心に、経験点で自動で能力を上げる（ほかの能力もポジションに合わせて少しずつ）。
 * 目ざす特殊能力（easySkillTarget）の分の経験点は残し、たまったら覚える。上がった能力を「最近の出来事」に出す
 */
export function easyGrowth(state: GameState, label = '練習の成果'): void {
  if (!isEasy(state)) return
  const c = state.career!
  const p = state.players[c.playerId]
  // 目ざす特殊能力があれば、払えるときに覚える。まだなら、その分の経験点を残して能力に使う
  const target = easySkillTarget(state)
  let skill: string | null = null
  if (target && canAfford(state, skillCost(state, target)) && learnSkill(state, target.id)) skill = target.name
  const next = skill ? easySkillTarget(state) : target
  const reserve: ExpCost = next ? skillCost(state, next) : {}
  const before = { ...p.attr }
  const pos = POSITION_DEFS[p.pos].weights
  const weights: Partial<Record<AttrKey, number>> = {}
  for (const k of ATTR_KEYS) {
    const w = (c.focus?.[k] ?? 0) * 2.5 + (pos[k] ?? 0) * 0.25
    if (w > 0) weights[k] = w
  }
  autoSpend(state, weights, reserve)
  // 大きく余った経験点は、足りない種類へ振り替えてから、もう一度使う
  autoConvert(state, weights, reserve)
  autoSpend(state, weights, reserve)
  const ups = ATTR_KEYS.filter((k) => Math.floor(p.attr[k]) > Math.floor(before[k])).map((k) => `${ATTR_BY_KEY[k].name}+${Math.floor(p.attr[k]) - Math.floor(before[k])}`)
  if (ups.length) report(state, `${label}: ${ups.slice(0, 5).join('・')}${ups.length > 5 ? ' ほか' : ''}`)
  if (skill) report(state, `特殊能力「${skill}」を覚えた！`)
}
