/**
 * 選手の自動生成。ポジションと目標の総合値（OVR）から能力を組み立て、
 * 成長タイプと年齢から上限（隠し）を決める。
 */
import type { Rng } from '../core/prng'
import { WEEKS_PER_SEASON } from '../core/calendar'
import { ATTR_BY_KEY, ATTR_KEYS, GK_KEYS, TRAIT_KEYS, type AttrKey, type Attrs, type Traits } from '../data/attributes'
import { POSITIONS, POSITION_DEFS, RELATED_APT, type Position } from '../data/positions'
import { GROWTH_TYPES, maturity, type GrowthType } from '../data/growth'
import { PERSONALITIES } from '../data/personality'
import { SKILLS, meetsSkillReq } from '../data/skills'
import { generateName, NATION_MIX, type Nation } from '../data/nations'
import { jpScale } from '../data/clubs'
import { emptyStats, type Foot, type Player } from '../models/player'
import { allocId, type GameState } from '../models/game'
import { fairWage, potentialOvr, rawRating } from '../player/overall'

const clamp = (v: number, lo = 1, hi = 99) => Math.max(lo, Math.min(hi, v))
const round1 = (v: number) => Math.round(v * 10) / 10

/** 能力の下地（目標 OVR に対する倍率）。重みの大きい能力ほど高い */
function baseFactor(key: AttrKey, pos: Position): number {
  const isGk = pos === 'GK'
  const group = ATTR_BY_KEY[key].group
  const w = POSITION_DEFS[pos].weights[key] ?? 0
  if (isGk) {
    if (group === 'gk') return 0.86 + 0.06 * w
    if (key === 'agility' || key === 'jump' || key === 'decision' || key === 'composure') return 0.8 + 0.06 * w
    if (key === 'strength' || key === 'stamina' || key === 'pass' || key === 'vision') return 0.62
    return 0.38
  }
  if (group === 'gk') return 0.16
  if (w > 0) return 1 + 0.07 * (w - AVG_WEIGHT[pos])
  return group === 'body' || group === 'mind' ? 0.78 : group === 'def' ? 0.52 : 0.64
}

const AVG_WEIGHT = Object.fromEntries(
  Object.values(POSITION_DEFS).map((d) => {
    const ws = Object.values(d.weights) as number[]
    return [d.id, ws.reduce((s, w) => s + w, 0) / ws.length]
  }),
) as Record<Position, number>

/** 目標 OVR に合うよう能力を作る */
export function buildAttrs(rng: Rng, pos: Position, target: number, spread = 6): Attrs {
  const a = {} as Attrs
  for (const k of ATTR_KEYS) a[k] = clamp(target * baseFactor(k, pos) + rng.normal(0, spread), 3, 97)
  // 目標に合わせて全体をずらす（2回）
  const keys = pos === 'GK' ? ATTR_KEYS : ATTR_KEYS.filter((k) => !GK_KEYS.includes(k))
  for (let it = 0; it < 3; it++) {
    const r = rawRating(a, pos)
    const diff = target - r
    for (const k of keys) {
      const w = POSITION_DEFS[pos].weights[k] ?? 0
      a[k] = clamp(a[k] + diff * (w > 0 ? 1 : 0.6), 3, 99)
    }
  }
  for (const k of ATTR_KEYS) a[k] = round1(a[k])
  return a
}

function rollGrowth(rng: Rng): GrowthType {
  return GROWTH_TYPES[rng.weighted([8, 22, 40, 22, 8])]
}

function rollTraits(rng: Rng): Traits {
  const t = {} as Traits
  for (const k of TRAIT_KEYS) t[k] = Math.round(clamp(rng.normal(10.5, 3.8), 1, 20))
  return t
}

function rollFoot(rng: Rng, pos: Position): Foot {
  const left = pos === 'SB' || pos === 'WB' || pos === 'SM' || pos === 'WG' ? 0.32 : 0.22
  const r = rng.next()
  return r < 0.07 ? 'B' : r < 0.07 + left ? 'L' : 'R'
}

function rollHeight(rng: Rng, pos: Position, nation: Nation): number {
  const base = pos === 'GK' ? 188 : pos === 'CB' ? 185 : pos === 'ST' ? 181 : pos === 'DM' ? 179 : 175
  const nationAdj = nation === 'NL' || nation === 'DE' || nation === 'DK' || nation === 'HR' ? 3 : nation === 'JP' || nation === 'KR' || nation === 'MX' ? -2 : 0
  return Math.round(clamp(rng.normal(base + nationAdj, 5), 160, 202))
}

export function buildAptitudes(rng: Rng, pos: Position): Record<Position, number> {
  const apt = {} as Record<Position, number>
  for (const p of POSITIONS) {
    if (p === pos) apt[p] = 100
    else if (p === 'GK' || pos === 'GK') apt[p] = Math.round(rng.range(0, 8))
    else {
      const rel = RELATED_APT[pos][p]
      apt[p] = Math.round(clamp(rel !== undefined ? rel + rng.normal(0, 10) : rng.range(8, 34), 0, 95))
    }
  }
  return apt
}

/**
 * 各能力の上限を、上限の総合値がちょうど pot になるようにそろえる。
 * 能力ごとのばらつきを足したあと「現在値より下げない」と切るだけだと伸びしろが底上げされ、
 * 世界全体が年々インフレするので、総合値で伸びしろを縮め直す。
 */
function fitCap(attr: Attrs, cap: Attrs, pos: Position, pot: number): Attrs {
  for (const k of ATTR_KEYS) cap[k] = Math.max(attr[k], cap[k])
  const cur = rawRating(attr, pos)
  const got = rawRating(cap, pos)
  const want = Math.max(cur, pot)
  const s = got - cur > 0.01 ? Math.min(1.5, (want - cur) / (got - cur)) : 1
  for (const k of ATTR_KEYS) cap[k] = round1(clamp(attr[k] + (cap[k] - attr[k]) * s, 1, 99))
  return cap
}

/** 能力の上限。年齢と成長タイプから、まだ伸びる量を決める */
export function buildCap(rng: Rng, attr: Attrs, pos: Position, age: number, growth: GrowthType, potentialBoost = 0): Attrs {
  const cur = rawRating(attr, pos)
  const m = maturity(growth, age)
  const potOvr = clamp(Math.max(cur, (cur / m) * rng.range(0.95, 1.05) + potentialBoost), 1, 96)
  const ratio = potOvr / Math.max(1, cur)
  const cap = {} as Attrs
  for (const k of ATTR_KEYS) cap[k] = attr[k] * ratio + rng.normal(0, 2.5)
  return fitCap(attr, cap, pos, potOvr)
}

/** 上限の総合値が pot になるよう、各能力の上限を作る */
export function capForPotential(rng: Rng, attr: Attrs, pos: Position, pot: number): Attrs {
  const cur = rawRating(attr, pos)
  const ratio = Math.max(cur, pot) / Math.max(1, cur)
  const cap = {} as Attrs
  for (const k of ATTR_KEYS) cap[k] = attr[k] * ratio + rng.normal(0, 2)
  return fitCap(attr, cap, pos, Math.min(96, pot))
}

function rollSkills(rng: Rng, attr: Attrs, cap: Attrs, pos: Position): string[] {
  const out: string[] = []
  for (const s of SKILLS) {
    if (s.tier === 'red') continue
    // 現在の能力か、上限が条件を満たす（将来）
    if (meetsSkillReq(s, attr, pos)) {
      if (rng.chance(s.tier === 'gold' ? 0.55 : 0.45)) out.push(s.id)
    } else if (meetsSkillReq(s, cap, pos) && rng.chance(0.08)) out.push(s.id)
  }
  // 条件なしの能力（大舞台・ジョーカーなど）とマイナス能力
  for (const s of SKILLS) {
    if (s.req || out.includes(s.id)) continue
    const p = s.tier === 'gold' ? 0.015 : s.tier === 'blue' ? 0.04 : 0.035
    if (rng.chance(p)) out.push(s.id)
  }
  rng.shuffle(out)
  return out.slice(0, 4)
}

export interface GenPlayerOptions {
  clubId: number
  pos: Position
  targetOvr: number
  age: number
  nation?: Nation
  /** 国籍の構成を引くリーグの国（nation 未指定時） */
  country?: string
  /** 将来性の上乗せ（若手有望株など） */
  potentialBoost?: number
  /** 上限の総合値を直接決める（指定があれば potentialBoost より優先） */
  potentialOvr?: number
  isYouth?: boolean
  contractYears?: number
}

export function generatePlayer(state: GameState, rng: Rng, opt: GenPlayerOptions): Player {
  const mix = NATION_MIX[opt.country ?? 'JP'] ?? NATION_MIX.JP
  const nation = opt.nation ?? mix.codes[rng.weighted(mix.weights)]
  const name = generateName(nation, rng)
  const growth = rollGrowth(rng)
  const attr = buildAttrs(rng, opt.pos, opt.targetOvr)
  const heightCm = rollHeight(rng, opt.pos, nation)
  // 身長を空中戦の能力に少し反映
  attr.header = round1(clamp(attr.header + (heightCm - 180) * 0.35))
  attr.jump = round1(clamp(attr.jump + (heightCm - 180) * 0.2))
  const cap = opt.potentialOvr !== undefined ? capForPotential(rng, attr, opt.pos, opt.potentialOvr) : buildCap(rng, attr, opt.pos, opt.age, growth, opt.potentialBoost ?? 0)
  const absWeek = state.season * WEEKS_PER_SEASON + state.week
  const ovr = rawRating(attr, opt.pos)
  const club = opt.clubId >= 0 ? state.clubs[opt.clubId] : undefined
  return {
    id: allocId(state, 'player'),
    name: name.full,
    short: name.short,
    nation,
    birthAbsWeek: absWeek - opt.age * WEEKS_PER_SEASON - rng.int(0, WEEKS_PER_SEASON - 1),
    heightCm,
    foot: rollFoot(rng, opt.pos),
    pos: opt.pos,
    apt: buildAptitudes(rng, opt.pos),
    attr,
    cap,
    growth,
    traits: rollTraits(rng),
    personality: rng.pick(PERSONALITIES),
    skills: rollSkills(rng, attr, cap, opt.pos),
    condition: Math.round(clamp(rng.normal(52, 10), 20, 85)),
    fatigue: 0,
    injury: null,
    morale: Math.round(clamp(rng.normal(68, 8), 35, 95)),
    suspension: 0,
    clubId: opt.clubId,
    isYouth: opt.isYouth ?? false,
    contract: {
      wage: fairWage(ovr, opt.age, club?.country ?? 'JP'),
      until: state.season + (opt.contractYears ?? rng.int(0, 3)),
    },
    number: 0,
    retired: false,
    stats: emptyStats(),
    history: [],
  }
}

/** クラブの選手構成（26人）。starters はその中の先発の目安人数 */
export const SQUAD_TEMPLATE: { pos: Position; count: number; starters: number }[] = [
  { pos: 'GK', count: 3, starters: 1 },
  { pos: 'CB', count: 5, starters: 2 },
  { pos: 'SB', count: 4, starters: 2 },
  { pos: 'DM', count: 2, starters: 1 },
  { pos: 'CM', count: 4, starters: 2 },
  { pos: 'AM', count: 2, starters: 1 },
  { pos: 'WG', count: 3, starters: 1 },
  { pos: 'ST', count: 3, starters: 1 },
]

/** クラブ格から先発の平均 OVR（海外の主要リーグは国内より一段強い） */
export function starterOvrForRep(rep: number, country = 'JP'): number {
  return jpScale(country) ? 30 + 0.55 * rep : 38 + 0.48 * rep
}

/** クラブ 1 つ分の選手を生成する */
export function generateSquad(state: GameState, rng: Rng, clubId: number): Player[] {
  const club = state.clubs[clubId]
  const base = starterOvrForRep(club.rep, club.country)
  const out: Player[] = []
  for (const t of SQUAD_TEMPLATE) {
    for (let i = 0; i < t.count; i++) {
      const starter = i < t.starters
      const prospect = !starter && i === t.count - 1 && rng.chance(0.55)
      const age = prospect
        ? rng.int(17, 20)
        : Math.round(clamp(rng.normal(starter ? 27 : 25, starter ? 3.4 : 4.5), 18, 35))
      const target = clamp(prospect ? base - rng.range(8, 14) : starter ? base + rng.normal(0, 3) : base - rng.range(3, 9), 30, 92)
      // 将来性はクラブの格に寄せる（若い控えが全員スターに育つと、数年で世界がインフレする）
      const anchor = prospect ? base + rng.normal(0.5, 5) : Math.max(target + 0.5, base + rng.normal(starter ? 1.5 : -0.5, 4))
      const p = generatePlayer(state, rng, { clubId, pos: t.pos, targetOvr: target, age, country: club.country })
      if (prospect || potentialOvr(p) > anchor) p.cap = capForPotential(rng, p.attr, p.pos, anchor)
      out.push(p)
    }
  }
  assignNumbers(out, rng)
  return out
}

const PREFERRED_NUMBERS: Record<Position, number[]> = {
  GK: [1, 21, 31, 12, 41],
  CB: [4, 5, 3, 15, 22, 24, 33],
  SB: [2, 3, 13, 16, 26, 23],
  WB: [2, 3, 13, 16, 26],
  DM: [6, 14, 25, 28],
  CM: [8, 6, 14, 17, 18, 27],
  SM: [7, 11, 16, 19],
  AM: [10, 20, 29],
  WG: [7, 11, 19, 30, 17],
  ST: [9, 9, 18, 20, 32],
}

/** 背番号を割り振る（ポジションらしい番号を優先、重複なし） */
export function assignNumbers(players: Player[], rng?: Rng) {
  const used = new Set(players.filter((p) => p.number > 0).map((p) => p.number))
  for (const p of players) {
    if (p.number > 0) continue
    const pref = PREFERRED_NUMBERS[p.pos].find((n) => !used.has(n))
    let n = pref ?? 0
    // 乱数で 2〜45 から選ぶ。見つからなければ（乱数がなければ）空いている番号を小さい順に。
    // ユースを含めて 44 人を超えると 2〜45 が埋まるので、乱数だけで探すと終わらない
    for (let t = 0; rng && t < 40 && (!n || used.has(n)); t++) n = rng.int(2, 45)
    for (let next = 2; !n || used.has(n); next++) n = next
    p.number = n
    used.add(n)
  }
}
