const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

const NAT_TACTICS: Tactics = { formation: '4-2-3-1', mentality: 0, tempo: 50, width: 50, lineHeight: 50, pressing: 50, focus: 'balanced', offsideTrap: false, counter: false }

/** そのシーズンが終わる年（W 杯の年かを見る） */
export function endYear(state: GameState, season = state.season): number {
  return state.startYear + season + 1
}

/** 国ごとの選手（引退していない） */
function byNation(state: GameState): Map<Nation, Player[]> {
  const out = new Map<Nation, Player[]>()
  for (const id in state.players) {
    const p = state.players[id]
    if (p.retired) continue
    const list = out.get(p.nation)
    if (list) list.push(p)
    else out.set(p.nation, [p])
  }
  return out
}

/** 国の今の強さ（上位 23 人の総合の平均） */
function strengthOf(list: Player[]): number {
  const top = list.map(ovr).sort((a, b) => b - a).slice(0, SQUAD_SIZE)
  return top.length ? top.reduce((s, v) => s + v, 0) / top.length : 55
}

function baseElo(strength: number): number {
  return Math.round(1500 + (strength - 72) * 25)
}

export function initNational(state: GameState) {
  const by = byNation(state)
  const elo = {} as Record<Nation, number>
  for (const n of NATIONS) elo[n] = baseElo(strengthOf(by.get(n) ?? []))
  state.national = { elo, squads: {}, calledAbsWeek: -1, comps: [], worldCups: [], japanLog: [] }
  planSeason(state)
}

/** 古いセーブには代表がないので作る（今の週から先の予定を組む） */
export function ensureNational(state: GameState): NationalState {
  if (!state.national) initNational(state)
  return state.national!
}

/** 代表の順位（Elo の高い順） */
export function nationRanking(state: GameState): Nation[] {
  const elo = ensureNationalRead(state)
  return [...NATIONS].sort((a, b) => elo[b] - elo[a] || NATIONS.indexOf(a) - NATIONS.indexOf(b))
}

function ensureNationalRead(state: GameState): Record<Nation, number> {
  return state.national?.elo ?? (Object.fromEntries(NATIONS.map((n) => [n, 1500])) as Record<Nation, number>)
}

// ---------------------------------------------------------------- 招集

/** 代表の 23 人を選ぶ（ポジションの内訳を守り、足りなければほかの上位で埋める） */
export function selectSquad(state: GameState, n: Nation, by?: Map<Nation, Player[]>): number[] {
  const now = absWeekOf(state.season, state.week)
  const pool = (by?.get(n) ?? byNation(state).get(n) ?? []).filter((p) => !p.retired && !p.isYouth && ageOf(p, now) >= 17 && (!p.injury || p.injury.weeks <= 1))
  // キャリアの主人公は、知名度と所属クラブでの評価が少しだけ効く
  const me = state.career && !state.career.retired ? state.career : undefined
  const score = (p: Player) => ovr(p) + (p.condition - 60) / 20 + (me && p.id === me.playerId ? me.fame / 25 + (me.trust - 50) / 25 : 0)
  const sorted = [...pool].sort((a, b) => score(b) - score(a) || a.id - b.id)
  const picked: Player[] = []
  for (const [line, count] of Object.entries(SQUAD_LINES)) picked.push(...sorted.filter((p) => POSITION_DEFS[p.pos].line === line).slice(0, count))
  for (const p of sorted) {
    if (picked.length >= SQUAD_SIZE) break
    if (!picked.includes(p)) picked.push(p)
  }
  return picked.slice(0, SQUAD_SIZE).map((p) => p.id)
}

/** 代表戦の週の招集（自クラブの選手が選ばれたらニュースと人気） */
function callUps(state: GameState, absWeek: number, wc?: NatComp) {
  const nat = state.national!
  nat.calledAbsWeek = absWeek
  const by = byNation(state)
  for (const n of NATIONS) nat.squads[n] = selectSquad(state, n, by)
  const me = state.clubs[state.playerClubId]
  const tier = state.competitions.find((c) => c.id === me.leagueId)?.tier ?? 3
  const jp: string[] = []
  const other: string[] = []
  for (const n of NATIONS) {
    for (const id of nat.squads[n] ?? []) {
      const p = state.players[id]
      if (wc && wc.nations.includes(n)) p.intl = { caps: p.intl?.caps ?? 0, goals: p.intl?.goals ?? 0, wc: (p.intl?.wc ?? 0) + 1 }
      if (p.clubId !== me.id) continue
      p.morale = clamp(p.morale + 3, 0, 100)
      if (n === 'JP') jp.push(p.name)
      else if (!wc || wc.nations.includes(n)) other.push(`${p.name}（${NATION_NAME[n]}）`)
    }
  }
  // キャリア: 主人公が選ばれた
  const cp = state.career && !state.career.retired ? state.players[state.career.playerId] : undefined
  if (cp && nat.squads[cp.nation]?.includes(cp.id)) {
    const c = state.career!
    if (c.done.sys_callup === undefined && !c.talks.some((t) => t.eventId === 'sys_callup')) queueTalk(state, 'sys_callup', { nation: NATION_NAME[cp.nation] })
    else if (wc && wc.nations.includes(cp.nation) && (c.done.sys_worldCup ?? -1) < absWeekOf(state.season, 0)) queueTalk(state, 'sys_worldCup', { nation: NATION_NAME[cp.nation], year: String(wc.year) })
    c.report.push(wc ? `W杯のメンバーに選ばれた！` : `${NATION_NAME[cp.nation]}代表に選ばれた！`)
  }
  if (wc) {
    const jpIn = wc.nations.includes('JP')
    if ((jpIn && jp.length) || other.length)
      state.news.push({ absWeek, category: 'national', mine: true, text: `W杯のメンバーに選ばれました: ${[jpIn && jp.length ? `日本代表 ${jp.join('・')}` : '', ...other].filter(Boolean).join('、')}` })
    const count = (jpIn ? jp.length : 0) + other.length
    me.popularity = Math.min(popularityCap(tier), me.popularity + count * 0.5)
    me.fans = Math.min(fansCap(state, me), me.fans + count * 200)
  } else if (jp.length || other.length) {
    state.news.push({ absWeek, category: 'national', mine: true, text: `代表に選ばれました: ${[jp.length ? `日本代表 ${jp.join('・')}` : '', ...other].filter(Boolean).join('、')}` })
    me.popularity = Math.min(popularityCap(tier), me.popularity + jp.length * 0.15)
    me.fans = Math.min(fansCap(state, me), me.fans + jp.length * 60)
  }
}

// ---------------------------------------------------------------- 試合

/** 代表の試合の設定（招集メンバーから先発を組む） */
export function nationalTeamSetup(state: GameState, n: Nation, venue: 'home' | 'away' | 'neutral'): TeamSetup {
  const nat = ensureNational(state)
  const ids = nat.squads[n]?.length ? nat.squads[n]! : selectSquad(state, n)
  const squad = ids.map((id) => state.players[id]).filter((p) => p && !p.retired)
  const pseudo = { id: -1, country: 'INT', tactics: { ...NAT_TACTICS }, isPlayer: false } as unknown as Club
  const lineup = autoLineup(state, pseudo, squad)
  const f = formationOf(NAT_TACTICS.formation)
  const starters = lineup.starters.flatMap((id, i) => (id >= 0 && state.players[id] ? [matchPlayer(state.players[id], f.slots[i].pos, venue)] : []))
  const bench = lineup.bench.map((id) => state.players[id]).filter(Boolean).map((p) => matchPlayer(p, p.pos, venue))
  return {
    chemBase: CHEM_AI,
    cohesion: CHEM_AI,
    clubId: -(10 + NATIONS.indexOf(n)),
    name: `${NATION_NAME[n]}代表`,
    short: NATION_NAME[n],
    colors: { ...NATION_KIT[n] },
    gkColor: '#111827',
    formation: f.id,
    tactics: { ...NAT_TACTICS },
    starters,
    bench,
    penaltyTaker: lineup.penaltyTaker,
    freeKickTaker: lineup.freeKickTaker,
    cornerTaker: lineup.cornerTaker,
    captain: lineup.captain,
    ai: true,
  }
}

export function nationalMatchSetup(state: GameState, f: NatFixture): MatchSetup {
  const home = nationalTeamSetup(state, f.home, f.neutral ? 'neutral' : 'home')
  const away = nationalTeamSetup(state, f.away, f.neutral ? 'neutral' : 'away')
  resolveKitClash(home, away)
  return { seed: hashSeed(state.seed, f.id, 0x4a7), home, away, neutral: f.neutral, knockout: f.knockout }
}

function emptyNatRow(nation: Nation, group: number): NatRow {
  return { nation, group, played: 0, won: 0, drawn: 0, lost: 0, gf: 0, ga: 0, points: 0 }
}

function applyRow(comp: NatComp, f: NatFixture) {
  const r = f.result!
  const h = comp.table.find((x) => x.nation === f.home)
  const a = comp.table.find((x) => x.nation === f.away)
  if (!h || !a) return
  h.played++
  a.played++
  h.gf += r.hg
  h.ga += r.ag
  a.gf += r.ag
  a.ga += r.hg
  if (r.hg > r.ag) {
    h.won++
    a.lost++
    h.points += 3
  } else if (r.hg < r.ag) {
    a.won++
    h.lost++
    a.points += 3
  } else {
    h.drawn++
    a.drawn++
    h.points++
    a.points++
  }
}

const rowOrder = (state: GameState) => (x: NatRow, y: NatRow) =>
  y.points - x.points || y.gf - y.ga - (x.gf - x.ga) || y.gf - x.gf || (state.national?.elo[y.nation] ?? 0) - (state.national?.elo[x.nation] ?? 0)

/** グループの順位（1 位から） */
export function natGroupStandings(state: GameState, comp: NatComp, group: number): NatRow[] {
  return comp.table.filter((r) => r.group === group).sort(rowOrder(state))
}

/** 勝った国（PK を含む） */
export function natWinner(f: NatFixture): Nation | null {
  const r = f.result
  if (!r) return null
  if (r.hg !== r.ag) return r.hg > r.ag ? f.home : f.away
  if (r.pens) return r.pens[0] > r.pens[1] ? f.home : f.away
  return f.home
}

function updateElo(nat: NationalState, f: NatFixture, kind: NatComp['kind']) {
  const r = f.result!
  const k = kind === 'worldCup' ? 50 : kind === 'qualifier' ? 30 : 20
  const ra = nat.elo[f.home] + (f.neutral ? 0 : 60)
  const rb = nat.elo[f.away]
  const ea = 1 / (1 + 10 ** ((rb - ra) / 400))
  const sa = r.hg > r.ag ? 1 : r.hg < r.ag ? 0 : r.pens ? (r.pens[0] > r.pens[1] ? 0.75 : 0.25) : 0.5
  const gd = Math.abs(r.hg - r.ag)
  const mult = gd <= 1 ? 1 : gd === 2 ? 1.5 : (11 + gd) / 8
  const d = Math.round(k * mult * (sa - ea))
  nat.elo[f.home] += d
  nat.elo[f.away] -= d
}

function roundLabel(comp: NatComp, f: NatFixture): string {
  if (comp.kind === 'worldCup') return WC_ROUND_NAMES[f.round] ?? ''
  if (comp.kind === 'qualifier') return `第${f.round + 1}節`
  return ''
}

/** キャリアの主人公が出る試合か（主人公の国の試合で、招集されている） */
function protagonistIn(state: GameState, f: NatFixture): number | undefined {
  const c = state.career
  if (!c || c.retired) return undefined
  const p = state.players[c.playerId]
  if (f.home !== p.nation && f.away !== p.nation) return undefined
  return state.national!.squads[p.nation]?.includes(p.id) ? p.id : undefined
}

function playFixture(state: GameState, comp: NatComp, f: NatFixture, summary?: MatchSummary) {
  const nat = state.national!
  // 主人公が出る試合は LiveSim（見せ場は自動で選ぶ）。観戦した結果があればそれを使う
  const focus = protagonistIn(state, f)
  const s = summary ?? (focus !== undefined ? new LiveMatch(nationalMatchSetup(state, f), { headless: true, focus }).runToEnd() : fastSim(nationalMatchSetup(state, f), createRng(hashSeed(state.seed, f.id, 0xfa57))))
  f.result = { hg: s.score[0], ag: s.score[1], et: s.et, pens: s.pens, goals: s.goals.map((g) => ({ playerId: g.player, side: g.team, minute: g.minute })) }
  if (f.group !== undefined && comp.kind !== 'friendly') applyRow(comp, f)
  updateElo(nat, f, comp.kind)
  const me = state.playerClubId
  const rng: Rng = createRng(hashSeed(state.seed, f.id, 0x1a7))
  for (const ps of s.players) {
    const p = state.players[ps.id]
    if (!p) continue
    if (ps.minutes > 0.5) {
      p.intl = { caps: (p.intl?.caps ?? 0) + 1, goals: (p.intl?.goals ?? 0) + ps.goals, wc: p.intl?.wc ?? 0 }
      p.fatigue = clamp(p.fatigue + (ps.minutes / 90) * 10, 0, 100)
    }
    if (ps.injured && !p.injury) {
      p.injury = rollInjury(rng, 0, p.skills.includes('glassBody'))
      if (p.injury.weeks > 8) p.injury.weeks = 8
      if (p.clubId === me) state.news.push({ absWeek: f.absWeek, category: 'injury', mine: true, text: `${p.name} が${NATION_NAME[p.nation]}代表の試合で${p.injury.name}（全治 ${p.injury.weeks} 週）` })
    }
  }
  // キャリア: 主人公の代表の試合（経験点・知名度）
  if (focus !== undefined) {
    const side = f.home === state.players[focus].nation ? 0 : 1
    careerAfterNational(state, comp.kind, comp.short, side === 0 ? f.away : f.home, side, s)
  }
  const mineIn = (n: Nation) => (nat.squads[n] ?? []).some((id) => state.players[id]?.clubId === me)
  // 日本の試合
  if (f.home === 'JP' || f.away === 'JP') {
    const home = f.home === 'JP'
    const side = home ? 0 : 1
    const gf = home ? f.result.hg : f.result.ag
    const ga = home ? f.result.ag : f.result.hg
    const scorers = f.result.goals.filter((g) => g.side === side).map((g) => state.players[g.playerId]?.short ?? '')
    const opp = home ? f.away : f.home
    const pens = f.result.pens ? ((home ? f.result.pens : [f.result.pens[1], f.result.pens[0]]) as [number, number]) : undefined
    nat.japanLog.push({ absWeek: f.absWeek, compId: comp.id, compShort: comp.short, round: roundLabel(comp, f), opp, home, neutral: f.neutral, gf, ga, pens, scorers })
    if (nat.japanLog.length > 40) nat.japanLog.splice(0, nat.japanLog.length - 40)
    state.news.push({
      absWeek: f.absWeek,
      category: 'national',
      mine: mineIn('JP'),
      text: `【${comp.short}${comp.kind === 'worldCup' ? ` ${roundLabel(comp, f)}` : ''}】日本 ${gf}-${ga} ${NATION_NAME[opp]}${pens ? `（PK ${pens[0]}-${pens[1]}）` : ''}${scorers.length ? `（得点: ${scorers.join('、')}）` : ''}`,
    })
  }
  // W 杯で自クラブの選手が点を取った（日本以外）
  if (comp.kind === 'worldCup') {
    for (const g of f.result.goals) {
      const p = state.players[g.playerId]
      if (p && p.clubId === me && p.nation !== 'JP') state.news.push({ absWeek: f.absWeek, category: 'national', mine: true, text: `${p.name} が W杯で${NATION_NAME[p.nation]}代表のゴール！` })
    }
  }
}

// ---------------------------------------------------------------- 予選・親善試合

/** 予選を組む（windows = 代表戦の絶対週。足りなければ総当たりを 1 回にする） */
function createQualifiers(state: GameState, year: number, windows: number[]) {
  const nat = state.national!
  if (!windows.length || nat.comps.some((c) => c.kind === 'qualifier' && c.year === year)) return
  const host = wcHost(year)
  const rng = createRng(hashSeed(state.seed, year, 0x9c1))
  for (const cf of CONFEDS) {
    const members = NATIONS.filter((n) => CONFED_OF[n] === cf && n !== host).sort((a, b) => nat.elo[b] - nat.elo[a])
    const quota = WC_QUOTA[cf] - (CONFED_OF[host] === cf ? 1 : 0)
    if (quota <= 0 || members.length === 0) continue
    const groupCount = members.length >= 8 ? 2 : 1
    const groups: Nation[][] = Array.from({ length: groupCount }, () => [])
    // 強い順にヘビの順で振り分ける
    members.forEach((n, i) => {
      const lap = Math.floor(i / groupCount)
      const k = lap % 2 === 0 ? i % groupCount : groupCount - 1 - (i % groupCount)
      groups[k].push(n)
    })
    const comp: NatComp = { id: `WCQ${year}-${cf}`, kind: 'qualifier', name: `W杯予選 ${CONFED_NAME[cf]}`, short: 'W杯予選', year, confed: cf, quota, nations: members, fixtures: [], table: [] }
    groups.forEach((g, gi) => {
      for (const n of g) comp.table.push(emptyNatRow(n, gi))
      let rounds = roundRobin(
        g.map((_, i) => i),
        rng,
      )
      if (rounds.length > windows.length) rounds = rounds.slice(0, rounds.length / 2)
      rounds.slice(0, windows.length).forEach((pairs, r) => {
        for (const [h, a] of pairs) comp.fixtures.push({ id: allocId(state, 'fixture'), compId: comp.id, round: r, absWeek: windows[r], home: g[h], away: g[a], group: gi })
      })
    })
    nat.comps.push(comp)
  }
}

/** 予選の結果（足りない分・予選がなかった大陸は強さの順）から、W 杯の 16 か国 */
export function wcQualified(state: GameState, year: number): Nation[] {
  const nat = state.national!
  const host = wcHost(year)
  const out: Nation[] = [host]
  for (const cf of CONFEDS) {
    const quota = WC_QUOTA[cf] - (CONFED_OF[host] === cf ? 1 : 0)
    if (quota <= 0) continue
    const comp = nat.comps.find((c) => c.kind === 'qualifier' && c.year === year && c.confed === cf)
    let picks: Nation[]
    if (comp && comp.fixtures.some((f) => f.result)) {
      const groups = [...new Set(comp.table.map((r) => r.group))].sort()
      const standings = groups.map((g) => natGroupStandings(state, comp, g))
      const per = Math.floor(quota / groups.length)
      picks = standings.flatMap((s) => s.slice(0, per).map((r) => r.nation))
      const rest = standings
        .map((s) => s[per])
        .filter(Boolean)
        .sort(rowOrder(state))
      picks.push(...rest.slice(0, quota - picks.length).map((r) => r.nation))
      comp.qualified = picks
    } else {
      picks = NATIONS.filter((n) => CONFED_OF[n] === cf && n !== host)
        .sort((a, b) => nat.elo[b] - nat.elo[a])
        .slice(0, quota)
    }
    out.push(...picks)
  }
  return out
}

/** 親善試合: 予選のない国どうしを組む（日本はなるべく毎回） */
function createFriendlies(state: GameState, windows: number[]) {
  const nat = state.national!
  const id = `FR${state.season}`
  let comp = nat.comps.find((c) => c.id === id)
  if (!comp) {
    comp = { id, kind: 'friendly', name: '国際親善試合', short: '親善試合', year: state.season, nations: [...NATIONS], fixtures: [], table: [] }
    nat.comps.push(comp)
  }
  for (const w of windows) {
    if (comp.fixtures.some((f) => f.absWeek === w)) continue
    const busy = new Set(nat.comps.flatMap((c) => c.fixtures.filter((f) => f.absWeek === w).flatMap((f) => [f.home, f.away])))
    const rng = createRng(hashSeed(state.seed, w, 0xf1e))
    const free = rng.shuffle(NATIONS.filter((n) => !busy.has(n)))
    // 日本が余らないように先頭へ
    const jp = free.indexOf('JP')
    if (jp > 0) [free[0], free[jp]] = [free[jp], free[0]]
    for (let i = 0; i + 1 < free.length; i += 2) {
      const [h, a] = rng.chance(0.5) ? [free[i], free[i + 1]] : [free[i + 1], free[i]]
      comp.fixtures.push({ id: allocId(state, 'fixture'), compId: id, round: 0, absWeek: w, home: h, away: a })
    }
  }
}

/** シーズンの代表の予定（新しいシーズンの頭か、初めて代表を作ったとき） */
export function planSeason(state: GameState) {
  const nat = state.national!
  const y = endYear(state)
  // 終わった大会を片付ける（W 杯の記録は worldCups に残っている）
  nat.comps = nat.comps.filter((c) => (c.kind === 'friendly' ? c.year === state.season : c.year >= y))
  const windows = INTL_WEEKS.filter((w) => w >= state.week).map((w) => absWeekOf(state.season, w))
  if (isWcYear(y + 1)) createQualifiers(state, y + 1, [...windows, ...INTL_WEEKS.map((w) => absWeekOf(state.season + 1, w))])
  if (isWcYear(y)) createQualifiers(state, y, windows)
  createFriendlies(state, windows)
}

/** 新しいシーズンの頭: 強さを今の選手の顔ぶれへ少し寄せ、予定を組む */
export function nationalSeasonStart(state: GameState) {
  if (!state.national) return initNational(state)
  const by = byNation(state)
  for (const n of NATIONS) state.national.elo[n] = Math.round(state.national.elo[n] * 0.85 + baseElo(strengthOf(by.get(n) ?? [])) * 0.15)
  planSeason(state)
}

// ---------------------------------------------------------------- W 杯

function confedCountOk(group: Nation[]): boolean {
  const count = new Map<Confed, number>()
  for (const n of group) count.set(CONFED_OF[n], (count.get(CONFED_OF[n]) ?? 0) + 1)
  return [...count].every(([cf, c]) => c <= (cf === 'UEFA' ? 2 : 1))
}

function addWcFixture(state: GameState, comp: NatComp, round: number, home: Nation, away: Nation, group?: number) {
  const host = comp.host!
  // 開催国はいつもホーム。ほかは中立地
  if (away === host) [home, away] = [away, home]
  comp.fixtures.push({
    id: allocId(state, 'fixture'),
    compId: comp.id,
    round,
    absWeek: absWeekOf(state.season, WC_WEEKS[round]),
    home,
    away,
    group,
    neutral: home !== host,
    knockout: round >= WC_QF,
  })
}

function createWorldCup(state: GameState, year: number) {
  const nat = state.national!
  const teams = wcQualified(state, year)
  const host = wcHost(year)
  const rng = createRng(hashSeed(state.seed, year, 0x3c))
  const others = teams.filter((n) => n !== host).sort((a, b) => nat.elo[b] - nat.elo[a])
  const pots = [others.slice(0, 3), others.slice(3, 7), others.slice(7, 11), others.slice(11, 15)]
  let groups: Nation[][] = []
  for (let attempt = 0; attempt < 300; attempt++) {
    const p1 = rng.shuffle(pots[0])
    groups = [[host], [p1[0]], [p1[1]], [p1[2]]]
    for (const pot of pots.slice(1)) {
      const sh = rng.shuffle(pot)
      sh.forEach((n, i) => groups[i]?.push(n))
    }
    if (groups.every(confedCountOk)) break
  }
  const comp: NatComp = { id: `WC${year}`, kind: 'worldCup', name: `ワールドカップ ${year}`, short: 'W杯', year, host, nations: teams, fixtures: [], table: [] }
  groups.forEach((g, gi) => {
    for (const n of g) comp.table.push(emptyNatRow(n, gi))
    const [a, b, c, d] = g
    const plan: [Nation, Nation][][] = [
      [
        [a, b],
        [c, d],
      ],
      [
        [a, c],
        [d, b],
      ],
      [
        [d, a],
        [b, c],
      ],
    ]
    plan.forEach((pairs, r) => pairs.forEach(([h, aw]) => h && aw && addWcFixture(state, comp, r, h, aw, gi)))
  })
  nat.comps.push(comp)
  const absWeek = absWeekOf(state.season, state.week)
  if (teams.includes('JP')) {
    const gi = groups.findIndex((g) => g.includes('JP'))
    const opps = groups[gi].filter((n) => n !== 'JP').map((n) => NATION_NAME[n])
    state.news.push({ absWeek, category: 'national', mine: true, text: `W杯 ${year}（${NATION_NAME[host]}開催）の組み合わせが決まりました。日本は${String.fromCharCode(65 + gi)}組で ${opps.join('・')} と戦います！` })
  } else state.news.push({ absWeek, category: 'national', mine: true, text: `日本代表は W杯 ${year}（${NATION_NAME[host]}開催）への出場を逃しました…。` })
}

/** 決勝トーナメントの組み合わせ（前の回戦が終わっていれば） */
function drawWcKnockout(state: GameState, comp: NatComp, week: number) {
  const round = WC_WEEKS.indexOf(week)
  if (round < WC_QF || comp.fixtures.some((f) => f.round === round)) return
  if (round === WC_QF) {
    const group = comp.fixtures.filter((f) => f.group !== undefined)
    if (!group.length || group.some((f) => !f.result)) return
    const st = [0, 1, 2, 3].map((g) => natGroupStandings(state, comp, g))
    const pairs: [Nation, Nation][] = [
      [st[0][0].nation, st[1][1].nation],
      [st[2][0].nation, st[3][1].nation],
      [st[1][0].nation, st[0][1].nation],
      [st[3][0].nation, st[2][1].nation],
    ]
    for (const [h, a] of pairs) addWcFixture(state, comp, round, h, a)
    return
  }
  const prev = comp.fixtures.filter((f) => f.round === round - 1)
  if (!prev.length || prev.some((f) => !f.result)) return
  const w = prev.map(natWinner).filter((x): x is Nation => !!x)
  // 隣どうしの勝者が当たる（準々決勝 1・2 試合目の勝者 → 準決勝 1 試合目）
  for (let i = 0; i + 1 < w.length; i += 2) addWcFixture(state, comp, round, w[i], w[i + 1])
}

/** 国がどこまで勝ち上がったか */
function wcStage(comp: NatComp, n: Nation): string {
  if (!comp.nations.includes(n)) return '不出場'
  const final = comp.fixtures.find((f) => f.round === WC_ROUNDS_LAST)
  if (final && (final.home === n || final.away === n)) return natWinner(final) === n ? '優勝' : '準優勝'
  if (comp.fixtures.some((f) => f.round === WC_QF + 1 && (f.home === n || f.away === n))) return 'ベスト4'
  if (comp.fixtures.some((f) => f.round === WC_QF && (f.home === n || f.away === n))) return 'ベスト8'
  return 'グループ敗退'
}

const WC_ROUNDS_LAST = WC_WEEKS.length - 1
const STAGE_BONUS: Record<string, number> = { 優勝: 5, 準優勝: 3, ベスト4: 2, ベスト8: 1 }

export function wcStageOf(comp: NatComp, n: Nation): string {
  return wcStage(comp, n)
}

function finalizeWorldCup(state: GameState, comp: NatComp) {
  const nat = state.national!
  const final = comp.fixtures.find((f) => f.round === WC_ROUNDS_LAST)!
  const champion = natWinner(final)!
  const runnerUp = champion === final.home ? final.away : final.home
  const semis = comp.fixtures.filter((f) => f.round === WC_QF + 1).map((f) => (natWinner(f) === f.home ? f.away : f.home))
  const goals = new Map<number, number>()
  for (const f of comp.fixtures) for (const g of f.result?.goals ?? []) goals.set(g.playerId, (goals.get(g.playerId) ?? 0) + 1)
  const top = [...goals].sort((a, b) => b[1] - a[1] || a[0] - b[0])[0]
  const champSquad = (nat.squads[champion] ?? []).map((id) => state.players[id]).filter(Boolean)
  const mvpP = [...champSquad].sort((a, b) => (goals.get(b.id) ?? 0) * 3 + ovr(b) - ((goals.get(a.id) ?? 0) * 3 + ovr(a)))[0]
  const me = state.clubs[state.playerClubId]
  const mine = comp.nations.flatMap((n) => (nat.squads[n] ?? []).map((id) => state.players[id]).filter((p) => p && p.clubId === me.id).map((p) => ({ playerId: p.id, name: p.name, nation: n, goals: goals.get(p.id) ?? 0 })))
  const japan = wcStage(comp, 'JP')
  const rec: WorldCupRecord = {
    year: comp.year,
    host: comp.host!,
    champion,
    runnerUp,
    semis,
    japan,
    topScorer: top ? { playerId: top[0], name: state.players[top[0]]?.name ?? '', nation: state.players[top[0]]?.nation ?? champion, goals: top[1] } : undefined,
    mvp: mvpP ? { playerId: mvpP.id, name: mvpP.name, nation: champion } : undefined,
    mine,
  }
  nat.worldCups.push(rec)
  const absWeek = absWeekOf(state.season, state.week)
  state.news.push({ absWeek, category: 'national', mine: true, text: `W杯 ${comp.year} は ${NATION_NAME[champion]} が優勝！ 日本は${japan}。` })
  if (rec.topScorer) state.news.push({ absWeek, category: 'national', mine: state.players[rec.topScorer.playerId]?.clubId === me.id, text: `W杯 得点王: ${rec.topScorer.name}（${NATION_NAME[rec.topScorer.nation]}）${rec.topScorer.goals} 点` })
  // 日本の活躍でサッカー人気が上がる。自クラブの選手が W 杯に出るとクラブの人気も上がる
  const tier = state.competitions.find((c) => c.id === me.leagueId)?.tier ?? 3
  const bonus = STAGE_BONUS[japan] ?? 0
  if (bonus > 0) {
    me.popularity = Math.min(popularityCap(tier), me.popularity + bonus)
    me.fans = Math.min(fansCap(state, me), Math.round(me.fans * (1 + bonus * 0.015)))
    if (bonus >= 2) state.hometown.passion = Math.min(100, state.hometown.passion + 1)
    state.news.push({ absWeek, category: 'national', mine: true, text: `日本代表の${japan}で、日本中がサッカーに沸いています！ クラブの人気も上がりました。` })
  }
  for (const m of mine) {
    const p = state.players[m.playerId]
    if (p) p.morale = clamp(p.morale + 5, 0, 100)
  }
}

// ---------------------------------------------------------------- 週の処理

/**
 * 今週の準備（何度呼んでもよい）: W 杯の抽選・決勝トーナメントの組み合わせ・招集。
 * 前の週の終わり（drawWeek）にも呼ぶので、キャリアの主人公は招集を知ってから代表戦を観戦できる
 */
export function nationalPrepare(state: GameState) {
  const nat = ensureNational(state)
  const week = state.week
  const absWeek = absWeekOf(state.season, week)
  const y = endYear(state)
  let wc = nat.comps.find((c) => c.kind === 'worldCup' && c.year === y)
  if (isWcYear(y) && !wc && week >= WC_DRAW_WEEK && week <= WC_WEEKS[0]) {
    createWorldCup(state, y)
    wc = nat.comps.find((c) => c.kind === 'worldCup' && c.year === y)
  }
  if (wc) drawWcKnockout(state, wc, week)
  const due = nat.comps.some((c) => c.fixtures.some((f) => f.absWeek === absWeek && !f.result))
  if (!due) return
  const wcStart = absWeekOf(state.season, WC_WEEKS[0])
  if (wc && absWeek >= wcStart) {
    if (nat.calledAbsWeek < wcStart) callUps(state, absWeek, wc)
  } else if (nat.calledAbsWeek !== absWeek) callUps(state, absWeek)
}

/** 毎週（クラブの試合のあと）: 準備・代表戦・W 杯の締め */
export function nationalWeek(state: GameState) {
  const nat = ensureNational(state)
  nationalPrepare(state)
  const absWeek = absWeekOf(state.season, state.week)
  const wc = nat.comps.find((c) => c.kind === 'worldCup' && c.year === endYear(state))
  const due = nat.comps.flatMap((c) => c.fixtures.filter((f) => f.absWeek === absWeek && !f.result).map((f) => ({ c, f })))
  for (const { c, f } of due) playFixture(state, c, f)
  if (wc && wc.fixtures.some((f) => f.round === WC_ROUNDS_LAST && f.result && f.absWeek === absWeek)) finalizeWorldCup(state, wc)
}

/** キャリア: 今週、主人公が出る代表戦（まだ終わっていないもの） */
export function careerNationalFixture(state: GameState): { comp: NatComp; f: NatFixture } | null {
  const nat = state.national
  if (!nat || !state.career || state.career.retired) return null
  const absWeek = absWeekOf(state.season, state.week)
  for (const c of nat.comps) for (const f of c.fixtures) if (f.absWeek === absWeek && !f.result && protagonistIn(state, f) !== undefined) return { comp: c, f }
  return null
}

/** キャリア: 主人公の代表戦を行う（観戦した結果を渡すか、自動）。W 杯の決勝なら締める */
export function playCareerNational(state: GameState, summary?: MatchSummary): boolean {
  const fx = careerNationalFixture(state)
  if (!fx) return false
  playFixture(state, fx.comp, fx.f, summary)
  if (fx.comp.kind === 'worldCup' && fx.f.round === WC_ROUNDS_LAST) finalizeWorldCup(state, fx.comp)
  return true
}

/** 日本代表の次の試合 */
export function nextJapanFixture(state: GameState): { comp: NatComp; f: NatFixture } | null {
  const nat = state.national
  if (!nat) return null
  const now = absWeekOf(state.season, state.week)
  let best: { comp: NatComp; f: NatFixture } | null = null
  for (const c of nat.comps)
    for (const f of c.fixtures)
      if (!f.result && f.absWeek >= now && (f.home === 'JP' || f.away === 'JP') && (!best || f.absWeek < best.f.absWeek)) best = { comp: c, f }
  return best
}

export function natRoundName(comp: NatComp, f: NatFixture): string {
  return roundLabel(comp, f)
}
