/**
 * ホームタウンの特色（M19）。自クラブ（クラブモード）にだけ効く。
 * 効き目は小さく、街を選ぶ楽しみになる程度（data/clubs.ts の TOWN_TRAITS）。
 */
import type { TownTrait } from '../data/clubs'
import type { Club } from '../models/club'
import type { GameState } from '../models/game'

/** そのクラブのホームタウンの特色（自クラブでなければなし。古いセーブもなし） */
export function townTrait(state: GameState, club?: Club): TownTrait | undefined {
  if (state.mode === 'career') return undefined
  if (club && !club.isPlayer) return undefined
  return state.hometown.trait
}

export const hasTrait = (state: GameState, trait: TownTrait, club?: Club) => townTrait(state, club) === trait
