/**
 * 2D リアルタイム試合エンジン（LiveSim）の型。
 * 座標はメートル: x = 0〜105（左→右）、y = 0〜68（上→下）。前半はホームが右に攻める。
 */
import type { Attrs } from '../../data/attributes'
import type { Position } from '../../data/positions'
import type { Tactics } from '../../models/club'
import type { TacticalStyle } from '../../models/staff'

export const PITCH_W = 105
export const PITCH_H = 68
export const GOAL_W = 7.32
export const GOAL_H = 2.44
export const BOX_DEPTH = 16.5
export const BOX_WIDTH = 40.32
export const SIX_DEPTH = 5.5
export const SIX_WIDTH = 18.32
/** 1 ステップの秒数（10Hz） */
export const DT = 0.1
/** 前後半それぞれのシミュレーション秒数。表示の時計はこの 10 倍（270 秒 → 45 分） */
export const HALF_SECONDS = 540
export const CLOCK_SCALE = 5
/**
 * 時間あたりで決まる量の倍率（M14 で前後半を 270 秒から 540 秒にした）。
 * 体力の減り・ケガ・評価点の加点・一発退場・見せ場の間隔は、試合あたりで前と同じになるようにこれを掛ける
 */
export const TIME_K = 270 / HALF_SECONDS

export interface MatchPlayerSetup {
  id: number
  name: string
  short: string
  number: number
  /** スロットのポジション（先発）／本来のポジション（控え） */
  pos: Position
  /** 調子・やる気・ホームなどを反映した実効能力 */
  attr: Attrs
  skills: string[]
  /** 試合開始時のスタミナ（0-100、疲労から） */
  stamina: number
  aggression: number
  workRate: number
  starId?: string
}

export interface TeamSetup {
  clubId: number
  name: string
  short: string
  colors: { primary: string; secondary: string }
  /** GK のユニフォーム色 */
  gkColor: string
  formation: string
  tactics: Tactics
  style?: TacticalStyle
  starters: MatchPlayerSetup[]
  bench: MatchPlayerSetup[]
  penaltyTaker?: number
  freeKickTaker?: number
  cornerTaker?: number
  captain?: number
  /** AI 監督が交代・戦術変更を行うか（自クラブも true。観戦中に指示を出すと、そのチームは手動になる） */
  ai: boolean
  /** 連携（"小さい id:大きい id" → 0-100）。ない組み合わせは chemBase */
  chem?: Record<string, number>
  chemBase?: number
  /** チームのまとまり（先発の隣り合う組み合わせの連携の平均、0-100） */
  cohesion?: number
}

export interface MatchSetup {
  seed: number
  home: TeamSetup
  away: TeamSetup
  /** 中立地（ホームアドバンテージなし） */
  neutral?: boolean
  /** 引き分けなら延長・PK */
  knockout?: boolean
}

export type MatchEventType =
  | 'kickoff'
  | 'goal'
  | 'shot'
  | 'save'
  | 'post'
  | 'miss'
  | 'block'
  | 'chance'
  | 'foul'
  | 'yellow'
  | 'red'
  | 'corner'
  | 'offside'
  | 'sub'
  | 'injury'
  | 'halftime'
  | 'fulltime'
  | 'penalty'
  | 'tactic'
  | 'pk'

export interface MatchEvent {
  /** 経過シミュレーション秒（前後半を通算） */
  t: number
  /** 表示用の分（45+2 なら 47 ではなく minute=45, added=2） */
  minute: number
  added?: number
  type: MatchEventType
  team: 0 | 1
  /** 主体の選手 id */
  player?: number
  /** 相手・アシスト・交代で入る選手など */
  other?: number
  xg?: number
  text: string
  /** 得点後のスコア */
  score?: [number, number]
}

export interface TeamStats {
  goals: number
  shots: number
  onTarget: number
  xg: number
  passes: number
  passesOk: number
  /** ボール保持の秒数 */
  possession: number
  fouls: number
  corners: number
  offsides: number
  yellows: number
  reds: number
  saves: number
}

export interface PlayerMatchStats {
  id: number
  team: 0 | 1
  minutes: number
  started: boolean
  goals: number
  assists: number
  shots: number
  passes: number
  passesOk: number
  tackles: number
  saves: number
  yellow: number
  red: boolean
  injured: boolean
  rating: number
  /** 試合終了時のスタミナ */
  stamina: number
}

export interface MatchSummary {
  score: [number, number]
  /** 延長戦をしたか */
  et: boolean
  pens?: [number, number]
  stats: [TeamStats, TeamStats]
  players: PlayerMatchStats[]
  events: MatchEvent[]
  /** 得点者（エンジンの GoalRecord 形式に変換しやすいよう） */
  goals: { team: 0 | 1; player: number; assist?: number; minute: number; penalty?: boolean; ownGoal?: boolean }[]
  mom?: number
  /** キャリア: 主人公の見せ場（選んだ行動と成否） */
  moments?: { label: string; ok: boolean }[]
}

/** 試合中の操作（交代は次のプレー中断時に反映） */
export type MatchCommand =
  | { kind: 'sub'; team: 0 | 1; out: number; in: number }
  | { kind: 'tactics'; team: 0 | 1; tactics: Partial<Tactics> }
  | { kind: 'formation'; team: 0 | 1; formation: string }
