/**
 * チームの強さ（FastSim と AI の判断に使う共通の物差し）。
 * 試合の実効能力（MatchPlayerSetup.attr）とスロットのポジションから、攻撃・守備・中盤・GK を出す。
 */
import { POSITION_DEFS } from '../data/positions'
import type { Attrs } from '../data/attributes'
import type { TeamSetup } from './live/types'

export interface TeamRatings {
  att: number
  def: number
  mid: number
  gk: number
  /** 戦術の姿勢（-2〜+2）とプレス（0-100） */
  ment: number
  press: number
}

const mean = (xs: number[]) => (xs.length ? xs.reduce((s, x) => s + x, 0) / xs.length : 50)

const attOf = (a: Attrs) => a.finish * 0.3 + a.shoot * 0.2 + a.dribble * 0.15 + a.offBall * 0.15 + a.speed * 0.1 + a.composure * 0.1
const creOf = (a: Attrs) => a.pass * 0.4 + a.vision * 0.3 + a.dribble * 0.3
const defOf = (a: Attrs) => a.tackle * 0.3 + a.marking * 0.25 + a.defPos * 0.25 + a.header * 0.1 + a.speed * 0.1
const midOf = (a: Attrs) => a.pass * 0.35 + a.decision * 0.25 + a.vision * 0.2 + a.stamina * 0.1 + a.tackle * 0.1
const gkOf = (a: Attrs) => a.reflex * 0.4 + a.gkPos * 0.3 + a.handling * 0.3

export function teamRatings(t: TeamSetup): TeamRatings {
  const fw: Attrs[] = []
  const mf: Attrs[] = []
  const df: Attrs[] = []
  let gk: Attrs | null = null
  for (const p of t.starters) {
    const line = POSITION_DEFS[p.pos].line
    if (line === 'GK') gk = p.attr
    else if (line === 'FW' || p.pos === 'AM') fw.push(p.attr)
    else if (line === 'MF') mf.push(p.attr)
    else df.push(p.attr)
    if (p.pos === 'DM') df.push(p.attr)
  }
  const g = gk ? gkOf(gk) : 35
  return {
    att: mean(fw.map(attOf)) * 0.6 + mean(mf.map(creOf)) * 0.4,
    def: mean(df.map(defOf)) * 0.75 + g * 0.25,
    mid: mean([...mf, ...df.slice(0, 1)].map(midOf)),
    gk: g,
    ment: t.tactics.mentality,
    press: t.tactics.pressing,
  }
}

/** FastSim の説明変数（攻める側から見た値）。並びは calib.generated.ts の b[1..] と対応 */
export const FEATURE_NAMES = ['攻撃−守備', '中盤の差', '水準', '攻める側の姿勢', '守る側の姿勢', '守る側のプレス'] as const

export function features(atk: TeamRatings, def: TeamRatings): number[] {
  return [(atk.att - def.def) / 10, (atk.mid - def.mid) / 10, ((atk.att + def.def) / 2 - 60) / 10, atk.ment / 2, def.ment / 2, (def.press - 50) / 50]
}
