/**
 * 一般の選手・スタッフに生成した写真を割り当てる（固有キャラ・主人公・キャリアの OB は除く）。
 * 写真の数には限りがあるので、目に入りやすい人だけ:
 *   - 自クラブ（キャリアでは主人公の所属クラブ）の選手とスタッフ
 *   - 同じリーグの各クラブの主力（総合値の上位 3 人）
 * 一度付けた写真は変えない。同じクラブの中では同じ写真を使わず、世界全体で使われた回数の少ないものから選ぶ。
 * 乱数は使わない（id のハッシュで選ぶ）ので、試合やワールドの結果には影響しない。
 */
import { hashSeed } from '../core/prng'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import type { Staff } from '../models/staff'
import { FACE_POOL } from '../data/facePool.generated'
import { ovr } from './overall'

/** 見た目の系統（写真のセットの分け方。tools/gen/jobs.py の POOL と同じ） */
export type FaceGroup = 'east' | 'europe' | 'mixed' | 'africa' | 'mideast'

const REGION: Record<string, FaceGroup | 'latin'> = {
  JP: 'east', KR: 'east', CN: 'east',
  BR: 'latin', AR: 'europe', UY: 'europe', CO: 'latin', MX: 'latin',
  NG: 'africa', SN: 'africa', GH: 'africa',
  SA: 'mideast', QA: 'mideast', MA: 'mideast',
}

/** 国籍と id から見た目の系統を決める（多民族の国はハッシュで振り分ける） */
export function faceGroupOf(nation: string, id: number): FaceGroup {
  const r = REGION[nation] ?? 'europe'
  const roll = hashSeed(id, 0xface) % 10
  if (r === 'latin') return roll < 3 ? 'africa' : roll < 7 ? 'mixed' : 'europe'
  if (r === 'europe' && ['FR', 'EN', 'NL', 'BE', 'PT', 'US'].includes(nation)) return roll < 2 ? 'africa' : roll < 3 ? 'mixed' : 'europe'
  if (r === 'europe') return roll < 1 ? 'mixed' : 'europe'
  return r
}

/** スタッフの写真のセット（男性は国籍で日本と海外に分ける） */
function staffGroup(s: Staff): string {
  if (s.female) return 'staffF'
  return faceGroupOf(s.nation, s.id) === 'east' ? 'staffJ' : 'staffW'
}

function pick(pool: string[], used: Map<string, number>, taken: Set<string>, key: number): string | undefined {
  const free = pool.filter((id) => !taken.has(id))
  if (!free.length) return undefined
  const least = Math.min(...free.map((id) => used.get(id) ?? 0))
  const cands = free.filter((id) => (used.get(id) ?? 0) === least)
  return cands[hashSeed(key, 0x9e37) % cands.length]
}

function give(person: Player | Staff, id: string, used: Map<string, number>, taken: Set<string>) {
  person.face = { ...(person.face ?? {}), photo: id }
  used.set(id, (used.get(id) ?? 0) + 1)
  taken.add(id)
}

function eligible(p: Player | Staff, protagonist: number): boolean {
  return !p.starId && !p.legend && !p.face?.photo && p.id !== protagonist
}

/** 写真を割り当てる。新規作成・読み込みのあとと、毎週の終わりに呼ぶ（何度呼んでもよい） */
export function assignPhotos(state: GameState): void {
  const protagonist = state.career?.playerId ?? -1
  const players = Object.values(state.players).filter((p) => !p.retired)
  // 世界全体での使用回数と、クラブごとの使用中の写真
  const used = new Map<string, number>()
  const byClub = new Map<number, Set<string>>()
  for (const p of players) {
    const ph = p.face?.photo
    if (!ph || p.id === protagonist) continue
    used.set(ph, (used.get(ph) ?? 0) + 1)
    if (!byClub.has(p.clubId)) byClub.set(p.clubId, new Set())
    byClub.get(p.clubId)!.add(ph)
  }
  const me = state.clubs[state.playerClubId]
  if (!me) return
  const league = state.clubs.filter((c) => c && c.leagueId === me.leagueId)
  const squads = new Map<number, Player[]>()
  for (const p of players) if (p.clubId >= 0) (squads.get(p.clubId) ?? squads.set(p.clubId, []).get(p.clubId)!).push(p)
  for (const club of league) {
    const squad = squads.get(club.id) ?? []
    const targets = club.id === me.id ? squad : [...squad].sort((a, b) => ovr(b) - ovr(a)).slice(0, 3)
    const taken = byClub.get(club.id) ?? new Set<string>()
    for (const p of targets) {
      if (!eligible(p, protagonist)) continue
      const pool = FACE_POOL[faceGroupOf(p.nation, p.id)] ?? []
      const id = pick(pool, used, taken, p.id)
      if (id) give(p, id, used, taken)
    }
  }
  // 自クラブのスタッフ
  const staffTaken = new Set(me.staff.map((id) => state.staff[id]?.face?.photo).filter((x): x is string => !!x))
  for (const sid of me.staff) {
    const s = state.staff[sid]
    if (!s || !eligible(s, -1)) continue
    const id = pick(FACE_POOL[staffGroup(s)] ?? [], new Map(), staffTaken, s.id)
    if (id) give(s, id, new Map(), staffTaken)
  }
}
