const TITLE: Record<MediaKind, string> = {
  news: 'テレビ出演',
  magazine: '雑誌の撮影',
  variety: 'バラエティ番組',
  documentary: 'ドキュメンタリー',
  book: '自伝の出版',
  cm: 'CM の撮影',
  overseas: '現地のテレビ番組',
}

export function mediaEvent(id: string): CareerEventDef | undefined {
  const kind = id.split(':')[1] as MediaKind
  const lines = LINES[kind]
  return lines ? { id, title: TITLE[kind], trigger: 'system', lines } : undefined
}
