/**
 * 移籍市場の基本: 希望額、年俸の要求、移籍の成立、契約解除、レンタル。
 * 金額は万円。移籍期間（夏・冬）以外はフリーの選手だけ獲得できる。
 */
import { noteTransfer } from '../club/records'
import { absWeekOf, isTransferWindow } from '../core/calendar'
import { hashSeed } from '../core/prng'
import type { Club } from '../models/club'
import type { GameState } from '../models/game'
import type { Contract, Player, SquadRole } from '../models/player'
import { SQUAD_ROLE_LABEL } from '../models/player'
import { ageOf, fairWage, marketValue, ovr, potentialOvr } from '../player/overall'
import { assignNumbers, starterOvrForRep } from '../gen/playerGen'
import { autoLineup, squadOf } from '../match/lineup'
import { maybeQueuePress } from '../club/press'
import { hasTrait } from '../club/town'

export const MIN_SQUAD = 18
export const MAX_SQUAD = 32

export function windowOpen(state: GameState): boolean {
  return isTransferWindow(state.week)
}

/** 0-1 の決まった乱数（選手とシーズンごとに固定。交渉のたびにぶれないように） */
export function fixedRand(state: GameState, p: Player, salt: number): number {
  return (hashSeed(state.seed, p.id, state.season, salt) % 10000) / 10000
}

/** クラブの中での序列（1 = いちばん良い） */
export function squadRank(state: GameState, p: Player): number {
  if (p.clubId < 0) return 99
  const sq = squadOf(state, p.clubId).sort((a, b) => ovr(b) - ovr(a))
  return sq.findIndex((x) => x.id === p.id) + 1
}

/** 全クラブのクラブ内順位（多くの選手の希望額をまとめて出すとき用） */
export function squadRanks(state: GameState): Map<number, number> {
  const byClub = new Map<number, Player[]>()
  for (const id in state.players) {
    const p = state.players[id]
    if (p.retired || p.isYouth || p.clubId < 0) continue
    const list = byClub.get(p.clubId) ?? []
    list.push(p)
    byClub.set(p.clubId, list)
  }
  const out = new Map<number, number>()
  for (const list of byClub.values()) list.sort((a, b) => ovr(b) - ovr(a)).forEach((p, i) => out.set(p.id, i + 1))
  return out
}

/** 売る側のクラブが求める額（最低ライン）。ranks を渡すとクラブ内順位を数え直さない */
export function askingPrice(state: GameState, p: Player, ranks?: Map<number, number>): number {
  if (p.clubId < 0) return 0
  if (p.clubId === state.playerClubId) return state.forSale[p.id] ?? Math.round(marketValue(p, absWeekOf(state.season, state.week), state.season) * 1.3)
  const now = absWeekOf(state.season, state.week)
  const club = state.clubs[p.clubId]
  const rank = ranks?.get(p.id) ?? squadRank(state, p)
  let v = marketValue(p, now, state.season) * (1.1 + club.rep / 250)
  if (rank <= 3) v *= 1.3
  else if (rank <= 11) v *= 1.1
  else v *= 0.85
  v *= 0.9 + fixedRand(state, p, 1) * 0.2
  return Math.max(100, Math.round(v / 100) * 100)
}

/** その選手が新しいクラブに求める年俸 */
export function wageDemand(state: GameState, p: Player, buyer: Club): number {
  const age = ageOf(p, absWeekOf(state.season, state.week))
  const fair = fairWage(ovr(p), age, buyer.country)
  const ambition = 1 + (p.traits.ambition - 10) * 0.025
  const keep = Math.max(1, (p.contract.wage * 1.05) / fair)
  return Math.round((fair * ambition * keep) / 10) * 10
}

/** クラブごとの国籍 → 選手（同じ国の仲間を探す用。移籍の記録が増えるか週が変わったら作り直す） */
const mateCache = new WeakMap<GameState, { key: string; byClub: Map<number, Map<string, Player[]>> }>()
function nationMates(state: GameState, clubId: number): Map<string, Player[]> {
  const key = `${state.season}:${state.week}:${state.transfers.length}`
  let c = mateCache.get(state)
  if (!c || c.key !== key) {
    c = { key, byClub: new Map() }
    mateCache.set(state, c)
  }
  let m = c.byClub.get(clubId)
  if (!m) {
    m = new Map()
    for (const q of squadOf(state, clubId)) m.set(q.nation, [...(m.get(q.nation) ?? []), q])
    c.byClub.set(clubId, m)
  }
  return m
}

/** 乗り気の決め手（交渉の画面に出す。value はロジスティックの入力への足し引き） */
export interface WillFactor {
  key: string
  label: string
  value: number
}

/** 選手の乗り気（0-1）: 格上のクラブ・上のリーグ・起用の約束で上がる、忠誠心が高いと下がる */
export function willingness(state: GameState, p: Player, buyer: Club, role?: SquadRole): number {
  return willFactors(state, p, buyer, role).will
}

/** 乗り気とその内訳 */
export function willFactors(state: GameState, p: Player, buyer: Club, role?: SquadRole): { will: number; factors: WillFactor[] } {
  const cur = p.clubId >= 0 ? state.clubs[p.clubId] : undefined
  const tierOf = (c?: Club) => state.competitions.find((x) => x.id === c?.leagueId)?.tier ?? (c && c.country !== 'JP' ? 0 : 4)
  const repDiff = (buyer.rep - (cur?.rep ?? buyer.rep - 10)) / 18
  const tierDiff = cur ? (tierOf(cur) - tierOf(buyer)) * 0.25 : 0.3
  const roleBonus = role === 'star' ? 0.35 : role === 'regular' ? 0.2 : role === 'rotation' ? 0.05 : role === 'prospect' ? 0.1 : 0
  const loyalty = cur ? -(p.traits.loyalty - 10) * 0.04 : 0
  const morale = cur ? (50 - p.morale) * 0.008 : 0
  // 自分よりずっと格下のクラブには行きたがらない（フリーの選手ほど強く。序盤にフリーの好選手を集め放題にしない）
  const gap = ovr(p) - starterOvrForRep(buyer.rep, buyer.country)
  const levelPenalty = Math.max(0, gap - (cur ? 8 : 4)) * (cur ? 0.06 : 0.12)
  // 港町（M19）: 外国籍の選手が来たがる
  const port = p.nation !== 'JP' && buyer.country === 'JP' && hasTrait(state, 'port', buyer) ? 0.25 : 0
  // 古巣への復帰・同じ国の仲間（M20。自クラブの交渉の決め手。AI の補強は乗り気を使わない）
  const homecoming = cur?.id !== buyer.id && p.history.some((h) => h.clubId === buyer.id) ? 0.35 : 0
  const mate = p.nation !== buyer.country ? nationMates(state, buyer.id).get(p.nation)?.find((q) => q.id !== p.id) : undefined
  const compatriot = mate ? 0.15 : 0
  const x = 0.2 + repDiff + tierDiff + roleBonus + loyalty + morale + port - levelPenalty + homecoming + compatriot
  const will = Math.max(0.02, Math.min(0.98, 1 / (1 + Math.exp(-x * 2.2))))
  const factors: WillFactor[] = cur
    ? [
        { key: 'rep', label: repDiff >= 0 ? `格上のクラブ（${cur.short}より）` : `格下のクラブ（${cur.short}より）`, value: repDiff },
        { key: 'tier', label: tierDiff >= 0 ? '上のリーグへ' : '下のリーグへ', value: tierDiff },
      ]
    : [{ key: 'free', label: 'フリーで所属先を探している', value: repDiff + tierDiff }]
  if (role) factors.push({ key: 'role', label: `起用の約束（${SQUAD_ROLE_LABEL[role]}）`, value: roleBonus })
  if (cur) factors.push({ key: 'loyalty', label: loyalty < 0 ? `${cur.short}への忠誠心` : '今のクラブにこだわらない', value: loyalty })
  if (cur) factors.push({ key: 'morale', label: morale > 0 ? '今のクラブに不満がある' : '今のクラブで満足している', value: morale })
  factors.push({ key: 'level', label: 'クラブとの実力差（格下と見ている）', value: -levelPenalty })
  factors.push({ key: 'port', label: '港町（外国籍の選手に人気）', value: port })
  factors.push({ key: 'home', label: '古巣への復帰', value: homecoming })
  factors.push({ key: 'mate', label: mate ? `同じ国の仲間（${mate.short}）` : '同じ国の仲間', value: compatriot })
  return { will, factors: factors.filter((f) => Math.abs(f.value) >= 0.02) }
}

export function recordTransfer(state: GameState, p: Player, from: number, to: number, fee: number, kind: 'transfer' | 'free' | 'loan' | 'loanEnd' | 'release') {
  state.transfers.push({ absWeek: absWeekOf(state.season, state.week), playerId: p.id, name: p.name, from, to, fee, kind })
  if (state.transfers.length > 400) state.transfers.splice(0, state.transfers.length - 400)
}

/** 先発・控えから外す */
function removeFromLineup(state: GameState, clubId: number, playerId: number) {
  if (clubId < 0) return
  const club = state.clubs[clubId]
  if (club.lineup.starters.includes(playerId) || club.lineup.bench.includes(playerId)) {
    club.lineup = { ...autoLineup(state, club), manual: club.lineup.manual && club.isPlayer ? false : club.lineup.manual }
  }
}

/** 移籍を成立させる（お金・契約・背番号・記録・ニュース） */
export function completeTransfer(state: GameState, p: Player, toClubId: number, fee: number, contract: Contract, kind: 'transfer' | 'free' = fee > 0 ? 'transfer' : 'free') {
  const from = p.clubId
  const to = state.clubs[toClubId]
  if (from >= 0) {
    state.clubs[from].budget += fee
    if (state.clubs[from].isPlayer) bookPlayerMoney(state, 'transferIn', fee)
  }
  to.budget -= fee
  if (to.isPlayer) bookPlayerMoney(state, 'transferOut', fee)
  p.clubId = toClubId
  p.contract = contract
  p.loan = undefined
  p.isYouth = false
  p.number = 0
  p.morale = Math.min(100, p.morale + 15)
  delete state.forSale[p.id]
  state.offers = state.offers.filter((o) => !('playerId' in o && o.playerId === p.id))
  if (to.isPlayer) state.scout.knowledge[p.id] = 100
  assignNumbers(squadOf(state, toClubId))
  removeFromLineup(state, from, p.id)
  recordTransfer(state, p, from, toClubId, fee, kind)
  noteTransfer(state, p, from, toClubId, fee)
  const mine = from === state.playerClubId || toClubId === state.playerClubId
  const fromName = from >= 0 ? state.clubs[from].name : 'フリー'
  state.news.push({
    absWeek: absWeekOf(state.season, state.week),
    category: 'transfer',
    mine,
    text: `${p.name}（総合 ${ovr(p)}）が${fromName}から${to.name}へ移籍${fee > 0 ? `（移籍金 ${fee.toLocaleString()} 万円）` : '（フリー）'}`,
  })
  // 大型補強なら入団会見（M16）
  if (to.isPlayer) maybeQueuePress(state, p, fee)
}

/** 自クラブの帳簿に記録 */
export function bookPlayerMoney(state: GameState, key: 'transferIn' | 'transferOut', amount: number) {
  const now = absWeekOf(state.season, state.week)
  let w = state.finance[state.finance.length - 1]
  if (!w || w.absWeek !== now) {
    w = { absWeek: now, ticket: 0, tv: 0, sponsor: 0, goods: 0, prize: 0, transferIn: 0, wages: 0, staffWages: 0, maintenance: 0, construction: 0, transferOut: 0, other: 0 }
    state.finance.push(w)
  }
  w[key] += amount
}

/** 契約解除（残りの年俸の半分を払う） */
export function releaseCost(state: GameState, p: Player): number {
  const years = Math.max(0.5, p.contract.until - state.season + 0.5)
  return Math.round(p.contract.wage * years * 0.5)
}

export function releasePlayer(state: GameState, p: Player): boolean {
  const club = state.clubs[p.clubId]
  if (!club || squadOf(state, club.id).length <= MIN_SQUAD) return false
  const cost = releaseCost(state, p)
  club.budget -= cost
  if (club.isPlayer) bookPlayerMoney(state, 'transferOut', cost)
  recordTransfer(state, p, club.id, -1, 0, 'release')
  removeFromLineup(state, club.id, p.id)
  p.clubId = -1
  p.number = 0
  delete state.forSale[p.id]
  state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'transfer', mine: club.isPlayer, text: `${p.name} との契約を解除しました（${cost.toLocaleString()} 万円）。` })
  return true
}

/** レンタルに出す（下のリーグで出場機会を得る。シーズン末に戻る） */
export function loanOut(state: GameState, p: Player): Club | null {
  const me = state.clubs[p.clubId]
  if (!me || squadOf(state, me.id).length <= MIN_SQUAD) return null
  const tierOf = (c: Club) => state.competitions.find((x) => x.id === c.leagueId)?.tier ?? 9
  const myTier = tierOf(me)
  const level = ovr(p)
  // 同じか下のリーグで、その選手が先発になれるクラブ
  const cands = state.clubs
    .filter((c) => !c.isPlayer && c.country === 'JP' && tierOf(c) >= myTier && c.leagueId !== 'AMA')
    .map((c) => ({ c, worst: Math.min(...squadOf(state, c.id).filter((q) => q.pos === p.pos).map(ovr), 99) }))
    .filter((x) => x.worst < level)
    .sort((a, b) => b.c.rep - a.c.rep)
  const target = cands[0]?.c
  if (!target) return null
  const from = p.clubId
  removeFromLineup(state, from, p.id)
  p.loan = { fromClubId: from, until: state.season, wageShare: 0.5 }
  p.clubId = target.id
  p.number = 0
  assignNumbers(squadOf(state, target.id))
  recordTransfer(state, p, from, target.id, 0, 'loan')
  state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'transfer', mine: true, text: `${p.name} を${target.name}へレンタルに出しました（シーズン末まで）。` })
  return target
}

/** シーズン末: レンタル中の選手を戻す */
export function returnLoans(state: GameState) {
  for (const id in state.players) {
    const p = state.players[id]
    if (!p.loan || p.loan.until > state.season || p.retired) continue
    const from = p.loan.fromClubId
    const at = p.clubId
    p.clubId = from
    p.loan = undefined
    p.number = 0
    recordTransfer(state, p, at, from, 0, 'loanEnd')
    if (from === state.playerClubId) state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'transfer', mine: true, text: `レンタル先から ${p.name} が戻ってきました（今季 ${p.history[p.history.length - 1]?.apps ?? 0} 試合出場）。` })
  }
}

/** 年俸の合計が予算を圧迫していないか（獲得前の確認用） */
export function affordable(buyer: Club, fee: number, wage: number): boolean {
  return buyer.budget - fee >= Math.max(0, wage * 0.5)
}

export function potentialHint(p: Player): number {
  return potentialOvr(p)
}
