/**
 * 交渉（M20）: 成立の見込み（確率）・交渉の決め手・ドラマ。
 *   獲得: ① 所属クラブと移籍金（3 回。ライバルが割り込むと 2 回）→ ② 選手と条件（3 回）→ 代理人の要求・メディカルチェック（出たときだけ）→ 獲得
 *   更改: ② だけ（ドラマはなし）
 * 見込みは提示額と相手の求める額の比で決まる。判定のサイコロは選手・シーズン・交渉を始めた週・回で固定（同じ条件を出し直しても同じ結果）。
 * 逆提案の額をそのまま受ければ必ずまとまる。
 * 交渉は state.talks に持つので、閉じて開き直しても続きから（やり直して結果を選べない）。
 * 決裂すると 6 週は話を聞いてもらえない（state.talkBlock）。ライバルが割り込んでいたら、決裂した選手はライバルへ行く。
 */
import { absWeekOf } from '../core/calendar'
import { hashSeed } from '../core/prng'
import type { Personality } from '../data/personality'
import { starterOvrForRep } from '../gen/playerGen'
import type { Club } from '../models/club'
import type { GameState } from '../models/game'
import type { Player, SquadRole } from '../models/player'
import { SQUAD_ROLE_LABEL } from '../models/player'
import { squadOf } from '../match/lineup'
import { ageOf, fairWage, ovr } from '../player/overall'
import { trimSquad } from './ai'
import { MAX_SQUAD, MIN_SQUAD, affordable, askingPrice, bookPlayerMoney, completeTransfer, fixedRand, wageDemand, willFactors, windowOpen, type WillFactor } from './market'
import { clubAsk, finalizeRenewal, finalizeSigning } from './negotiation'
import { rosterFullText, rosterInfo } from '../club/roster'

export type TalkMode = 'buy' | 'renew'
export type TalkStage = 'club' | 'player' | 'agent' | 'medical' | 'done'
export type TalkOutcome = 'signed' | 'failed' | 'walked' | 'lost'

export interface TalkTwist {
  /** rival: ほかのクラブが割り込む / eager: 本人が移籍を強く望む / agent: 代理人の土壇場の要求 / medical: メディカルチェックで古傷 */
  kind: 'rival' | 'eager' | 'agent' | 'medical'
  clubId?: number
  /** 代理人の求める契約金（万円） */
  amount?: number
  /** もう出た（代理人・メディカル） */
  used?: boolean
  /** 値下げを頼んだ（メディカル） */
  asked?: boolean
}

export interface TalkLine {
  who: 'me' | 'club' | 'player' | 'agent' | 'event'
  text: string
  tone?: 'good' | 'bad' | 'info'
}

export interface Talk {
  playerId: number
  mode: TalkMode
  /** 始めたときの所属（ほかへ移ったら交渉は流れる） */
  fromClubId: number
  startAbsWeek: number
  stage: TalkStage
  /** 移籍金の交渉で使った回数 */
  round: number
  /** 条件の交渉で使った回数 */
  attempts: number
  /** 相手クラブの逆提案（この額なら必ず受ける） */
  counterFee?: number
  /** 選手の逆提案（同じ年数・起用の約束で、この年俸なら必ず受ける） */
  counter?: { wage: number; years: number; role?: SquadRole }
  agreed?: { fee: number; wage: number; years: number; role?: SquadRole; bonus?: number }
  twists: TalkTwist[]
  outcome?: TalkOutcome
  log: TalkLine[]
}

/** 提示の結果（画面の演出に使う） */
export interface TalkResult {
  /** accept: 合意して次へ / counter: 逆提案 / reject: 断られた（回は進む） / event: 出来事 / signed: 獲得・更新 / fail: 決裂 / lost: 決裂してライバルへ / none: 提示できない */
  kind: 'accept' | 'counter' | 'reject' | 'event' | 'signed' | 'fail' | 'lost' | 'none'
  chance: number
  text: string
  /** 判定のサイコロの目（0〜1。見込みより小さければ成立。画面の針の止まる位置） */
  roll?: number
}

export const CLUB_ROUNDS = 3
export const RIVAL_ROUNDS = 2
export const PLAYER_ATTEMPTS = 3
export const BLOCK_WEEKS = 6
export const RENEW_BLOCK_WEEKS = 2
/** これより長く放っておいた交渉は流れる */
export const TALK_WEEKS = 8
/** 代理人の要求を断ったとき、本人が折れて契約してくれる見込み */
export const AGENT_REFUSE_CHANCE = 0.55
export const MEDICAL_DISCOUNT_CHANCE = 0.5

const nowOf = (state: GameState) => absWeekOf(state.season, state.week)
const logistic = (x: number) => 1 / (1 + Math.exp(-x))
const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))
const r100 = (v: number) => Math.round(v / 100) * 100
const r10 = (v: number) => Math.round(v / 10) * 10
const man = (v: number) => `${v.toLocaleString()} 万円`
const pct = (c: number) => `${Math.round(c * 100)}%`
const twistOf = (talk: Talk, kind: TalkTwist['kind']) => talk.twists.find((t) => t.kind === kind)

/** 判定のサイコロ（選手・シーズン・交渉を始めた週・回で固定） */
function dice(state: GameState, p: Player, talk: Talk, salt: number): number {
  return (hashSeed(state.seed, p.id, state.season, talk.startAbsWeek, salt) % 10000) / 10000
}

/** 見込みのことば */
export function oddsLabel(c: number): string {
  return c >= 0.9 ? 'ほぼ確実' : c >= 0.7 ? '有望' : c >= 0.45 ? '五分五分' : c >= 0.2 ? '厳しい' : c > 0 ? 'かなり厳しい' : '無理'
}

export function findTalk(state: GameState, playerId: number, mode?: TalkMode): Talk | undefined {
  return state.talks?.find((t) => t.playerId === playerId && (!mode || t.mode === mode))
}

/** 決裂して話を聞いてもらえない残りの週 */
export function blockedWeeks(state: GameState, p: Player): number {
  return Math.max(0, (state.talkBlock?.[p.id] ?? 0) - nowOf(state))
}

/** 交渉を始められるか（できないときは理由） */
export function talkBlocker(state: GameState, p: Player, mode: TalkMode): string | null {
  const me = state.clubs[state.playerClubId]
  const b = blockedWeeks(state, p)
  if (b > 0) return `交渉が決裂したばかりです（あと ${b} 週は話を聞いてもらえません）。`
  if (mode === 'renew') return p.clubId === me.id ? null : '自クラブの選手ではありません。'
  if (p.clubId === me.id) return '自クラブの選手です。'
  if (state.mode === 'club' && rosterInfo(state).full) return rosterFullText(state)
  if (p.retired) return '引退しています。'
  if (p.clubId >= 0 && !windowOpen(state)) return '移籍期間ではありません（夏は 8〜9 月、冬は 1〜2 月）。フリーの選手はいつでも獲得できます。'
  if (willFactors(state, p, me, 'star').will < 0.12) return `${p.short}は今のクラブを離れる気がありません。`
  return null
}

// ---------- 始める ----------

/** 交渉を開く（続きがあればそれを、なければ新しく。始められなければ null）。forced は出来事を決めて始める（開発用・試験用） */
export function openTalk(state: GameState, p: Player, mode: TalkMode, forced?: TalkTwist[]): Talk | null {
  const cur = findTalk(state, p.id, mode)
  if (cur && cur.stage !== 'done') return cur
  if (cur) state.talks = state.talks!.filter((t) => t !== cur)
  if (talkBlocker(state, p, mode)) return null
  const me = state.clubs[state.playerClubId]
  const talk: Talk = { playerId: p.id, mode, fromClubId: p.clubId, startAbsWeek: nowOf(state), stage: mode === 'renew' || p.clubId < 0 ? 'player' : 'club', round: 0, attempts: 0, twists: [], log: [] }
  if (mode === 'buy') {
    talk.twists = forced ?? makeTwists(state, p, me, talk)
    openingLines(state, p, me, talk)
  }
  state.talks = [...(state.talks ?? []), talk]
  return talk
}

/** 割り込んでくるクラブ（宿命のライバルを先に） */
function pickRival(state: GameState, p: Player, me: Club, talk: Talk): Club | undefined {
  const fee = p.clubId >= 0 ? askingPrice(state, p) : 0
  const ok = (c: Club | undefined): c is Club => !!c && rivalCanSign(state, p, c, fee) && c.rep >= me.rep - 8
  const rival = state.rival ? state.clubs[state.rival.clubId] : undefined
  if (ok(rival)) return rival
  const cands = state.clubs.filter((c) => c.country === 'JP' && c.leagueId !== 'AMA' && ok(c)).sort((a, b) => b.rep - a.rep)
  if (!cands.length) return undefined
  const top = cands.slice(0, 5)
  return top[Math.floor(dice(state, p, talk, 70) * top.length)]
}

function rivalCanSign(state: GameState, p: Player, c: Club, fee: number): boolean {
  if (c.isPlayer || c.id === p.clubId || p.retired || p.clubId === state.playerClubId) return false
  if (squadOf(state, c.id).length >= MAX_SQUAD) return false
  if (c.budget < fee + fairWage(ovr(p), 25, c.country)) return false
  if (p.clubId >= 0 && squadOf(state, p.clubId).length <= MIN_SQUAD + 2) return false
  return true
}

function makeTwists(state: GameState, p: Player, me: Club, talk: Talk): TalkTwist[] {
  const out: TalkTwist[] = []
  const age = ageOf(p, nowOf(state))
  const good = ovr(p) >= starterOvrForRep(me.rep, me.country) - 3
  if (dice(state, p, talk, 71) < (good ? 0.3 : 0.12)) {
    const rival = pickRival(state, p, me, talk)
    if (rival) out.push({ kind: 'rival', clubId: rival.id })
  }
  if (p.clubId >= 0 && willFactors(state, p, me, 'regular').will >= 0.55 && dice(state, p, talk, 72) < 0.35) out.push({ kind: 'eager' })
  if (dice(state, p, talk, 73) < 0.22) out.push({ kind: 'agent', amount: Math.max(300, r100(wageDemand(state, p, me) * 0.5)) })
  if (age >= 27 && dice(state, p, talk, 74) < 0.12) out.push({ kind: 'medical' })
  return out
}

/** 交渉の始まりの知らせ（横やり・本人の希望・古巣・同じ国の仲間） */
function openingLines(state: GameState, p: Player, me: Club, talk: Talk) {
  const club = p.clubId >= 0 ? state.clubs[p.clubId] : undefined
  const rival = twistOf(talk, 'rival')
  if (rival) {
    const rc = state.clubs[rival.clubId!]
    talk.log.push({
      who: 'event',
      tone: 'bad',
      text: club ? `速報: ${rc.name}も${p.name}の獲得に名乗り！ 移籍金の交渉は ${RIVAL_ROUNDS} 回まで。決裂すれば${rc.short}に取られる。` : `速報: ${rc.name}も${p.name}に条件を出している！ 決裂すれば${rc.short}へ行ってしまう。`,
    })
  }
  if (twistOf(talk, 'eager') && club) talk.log.push({ who: 'event', tone: 'good', text: `${p.short}本人が「どうしても${me.short}でやりたい」と${club.short}に直訴している。相手も強くは出られない（希望額 −10%）。` })
  const { factors } = willFactors(state, p, me, 'regular')
  if (factors.some((f) => f.key === 'home')) talk.log.push({ who: 'player', tone: 'good', text: `${p.short}「${me.short}は古巣です。いつか戻りたいと思っていました。」` })
  const mate = factors.find((f) => f.key === 'mate')
  if (mate) talk.log.push({ who: 'event', tone: 'good', text: `${mate.label.replace(/^同じ国の仲間（(.+)）$/, '$1')}がいることを、${p.short}は心強く思っているようだ。` })
}

// ---------- ① 移籍金 ----------

export function clubRounds(talk: Talk): number {
  return twistOf(talk, 'rival') ? RIVAL_ROUNDS : CLUB_ROUNDS
}

/** 相手クラブが求める額（横やりで上がり、本人の希望で下がる） */
export function feeNeed(state: GameState, talk: Talk, p: Player): number {
  return r100(clubAsk(state, p) * (twistOf(talk, 'rival') ? 1.08 : 1) * (twistOf(talk, 'eager') ? 0.9 : 1))
}

/** 移籍金の提示が受け入れられる見込み */
export function feeChance(state: GameState, talk: Talk, p: Player, fee: number): number {
  if (p.clubId < 0) return 1
  if (talk.counterFee !== undefined && fee >= talk.counterFee) return 1
  const ratio = fee / Math.max(1, feeNeed(state, talk, p))
  if (ratio < 0.6) return 0
  if (ratio >= 1.15) return 0.99
  return clamp(logistic((ratio - 0.96) * 22), 0.01, 0.99)
}

/** 移籍金を提示する */
export function offerFee(state: GameState, talk: Talk, fee: number): TalkResult {
  const p = state.players[talk.playerId]
  const me = state.clubs[state.playerClubId]
  if (talk.stage !== 'club' || p.clubId < 0) return { kind: 'none', chance: 0, text: '' }
  const club = state.clubs[p.clubId]
  if (!windowOpen(state)) return { kind: 'none', chance: 0, text: '移籍期間ではありません。' }
  if (me.budget < fee) return { kind: 'none', chance: 0, text: '資金が足りません。' }
  if (rosterInfo(state).full) return { kind: 'none', chance: 0, text: rosterFullText(state) }
  const chance = feeChance(state, talk, p, fee)
  const need = feeNeed(state, talk, p)
  talk.log.push({ who: 'me', text: `移籍金 ${man(fee)} を提示（見込み ${pct(chance)}）` })
  const roll = dice(state, p, talk, 40 + talk.round)
  const hit = roll < chance
  talk.round++
  if (hit) {
    talk.agreed = { fee, wage: 0, years: 2 }
    talk.counterFee = undefined
    talk.stage = 'player'
    const text = `${club.short}「${fee >= need ? 'その条件なら応じましょう。' : '……いいでしょう。手を打ちます。'}」`
    talk.log.push({ who: 'club', tone: 'good', text })
    return { kind: 'accept', chance, text, roll }
  }
  if (talk.round >= clubRounds(talk)) {
    const text = `${club.short}「残念ですが、この話はなかったことにしましょう。」`
    talk.log.push({ who: 'club', tone: 'bad', text })
    return { kind: endTalk(state, talk, 'failed') === 'lost' ? 'lost' : 'fail', chance, text, roll }
  }
  if (fee < need * 0.6) {
    const text = `${club.short}「話になりません。${p.short}の価値を分かっていますか？」`
    talk.log.push({ who: 'club', tone: 'bad', text })
    return { kind: 'reject', chance, text, roll }
  }
  const left = clubRounds(talk) - talk.round
  const counter = r100(Math.max(need * 1.02, (need * (1 + 0.08 * left) + fee) / 2))
  talk.counterFee = counter
  const text = left === 1 ? `${club.short}の会長「これが最後の提示です。${man(counter)}。これで決めてください。」` : `${club.short}「${man(counter)}なら考えましょう。」`
  talk.log.push({ who: 'club', tone: 'info', text })
  return { kind: 'counter', chance, text, roll }
}

// ---------- ② 条件 ----------

export interface WageNeed {
  need: number
  will: number
  yearsOk: boolean
  factors: WillFactor[]
}

/** 選手が求める年俸（乗り気なら安くても受ける）と、乗り気の内訳 */
export function wageNeed(state: GameState, p: Player, years: number, role: SquadRole | undefined, renewal: boolean, talk?: Talk): WageNeed {
  const me = state.clubs[state.playerClubId]
  const age = ageOf(p, nowOf(state))
  let demand: number
  let will: number
  let factors: WillFactor[]
  if (renewal) {
    demand = Math.max(p.contract.wage, fairWage(ovr(p), age, me.country) * (1 + (p.traits.ambition - 10) * 0.025))
    will = Math.min(0.95, 0.35 + p.morale / 160 + (p.traits.loyalty - 10) * 0.03)
    factors = [
      { key: 'morale', label: p.morale >= 60 ? 'クラブでのやる気が高い' : p.morale < 40 ? 'やる気が下がっている' : 'やる気はふつう', value: ((p.morale - 50) / 160) * 2 },
      { key: 'loyalty', label: p.traits.loyalty >= 10 ? 'クラブへの忠誠心' : 'クラブにこだわらない', value: (p.traits.loyalty - 10) * 0.06 },
      { key: 'ambition', label: p.traits.ambition >= 12 ? '野心家（年俸にこだわる）' : '年俸にこだわらない', value: -(p.traits.ambition - 10) * 0.05 },
    ].filter((f) => Math.abs(f.value) >= 0.02)
  } else {
    demand = wageDemand(state, p, me)
    ;({ will, factors } = willFactors(state, p, me, role))
  }
  demand = demand * (1.18 - 0.36 * will)
  // フリーの選手には、割り込んだクラブも条件を出している
  if (talk && p.clubId < 0 && twistOf(talk, 'rival')) demand *= 1.08
  const noise = 0.97 + fixedRand(state, p, renewal ? 31 : 21) * 0.06
  const need = Math.round((demand * noise) / 10) * 10
  return { need, will, yearsOk: age >= 31 ? years >= 2 : true, factors }
}

/** 条件の提示が受け入れられる見込み */
export function termsChance(state: GameState, talk: Talk, p: Player, wage: number, years: number, role?: SquadRole): number {
  const renewal = talk.mode === 'renew'
  const { need, will, yearsOk } = wageNeed(state, p, years, role, renewal, talk)
  if (!renewal && will < 0.12) return 0
  const c0 = talk.counter
  if (c0 && wage >= c0.wage && years === c0.years && role === c0.role && yearsOk) return 1
  const ratio = wage / Math.max(1, need)
  const c = ratio >= 1.12 ? 0.99 : clamp(logistic((ratio - 0.97) * 30), 0.01, 0.99)
  return yearsOk ? c : c * 0.25
}

type Lines = { accept: string; counter: (w: string) => string; reject: string }
const PLAYER_LINES: Record<Personality, Lines> = {
  hot: { accept: '燃えてきました！ このクラブで暴れてやります！', counter: (w) => `気持ちは乗ってます。でも、${w}は譲れません！`, reject: '……すみません。今回は気持ちが乗りませんでした。' },
  cool: { accept: '条件に不満はありません。結果で応えます。', counter: (w) => `評価に見合う額を。${w}です。`, reject: 'この条件では、話を進められません。' },
  mood: { accept: 'やった！ みんなと早く会いたいな！', counter: (w) => `うーん、${w}だったら気持ちよくサインできるんだけどな〜。`, reject: 'ごめんなさい、今回はやめておきます！' },
  effort: { accept: 'ありがとうございます。毎日の練習で恩返しします。', counter: (w) => `家族のこともあるので……${w}でお願いできませんか。`, reject: 'すみません。今回は見送らせてください。' },
  genius: { accept: 'ボクを選ぶなんて、見る目あるね。', counter: (w) => `ボクの価値は${w}。安売りはしないよ。`, reject: 'つまらない話だね。帰らせてもらうよ。' },
  mypace: { accept: 'いいですよ〜。のんびり、でもしっかりやります。', counter: (w) => `${w}くらいだと、ちょうどいいかなあ。`, reject: 'うーん、なんか違うかな。やめときます。' },
  leader: { accept: 'このクラブを勝たせるために来ました。よろしく頼みます。', counter: (w) => `覚悟を持って行く以上、${w}は必要です。`, reject: '残念ですが、今回の話はお断りします。' },
  shy: { accept: 'ほ、本当にいいんですか……！ がんばります……！', counter: (w) => `あ、あの……${w}だと、うれしいです……。`, reject: 'す、すみません……やっぱり、今回は……。' },
}

/** 条件を提示する */
export function offerTerms(state: GameState, talk: Talk, wage: number, years: number, role?: SquadRole): TalkResult {
  const p = state.players[talk.playerId]
  if (talk.stage !== 'player') return { kind: 'none', chance: 0, text: '' }
  const renewal = talk.mode === 'renew'
  if (!renewal && state.mode === 'club' && rosterInfo(state).full) return { kind: 'none', chance: 0, text: rosterFullText(state) }
  const lines = PLAYER_LINES[p.personality] ?? PLAYER_LINES.cool
  const chance = termsChance(state, talk, p, wage, years, role)
  if (chance <= 0) return { kind: 'none', chance, text: `${p.short}「今のクラブを離れる気はありません。」` }
  talk.log.push({ who: 'me', text: `年俸 ${man(wage)}・${years} 年${role ? `・${SQUAD_ROLE_LABEL[role]}として起用` : ''}（見込み ${pct(chance)}）` })
  const roll = dice(state, p, talk, (renewal ? 60 : 50) + talk.attempts)
  const hit = roll < chance
  talk.attempts++
  if (hit) {
    talk.agreed = { ...(talk.agreed ?? { fee: 0 }), wage, years, role }
    talk.counter = undefined
    if (renewal) {
      finalizeRenewal(state, p, wage, years, role)
      talk.stage = 'done'
      talk.outcome = 'signed'
      const text = `${p.short}「これからも、このクラブで戦います。」`
      talk.log.push({ who: 'player', tone: 'good', text })
      return { kind: 'signed', chance, text, roll }
    }
    const text = `${p.short}「${lines.accept}」`
    talk.log.push({ who: 'player', tone: 'good', text })
    const next = proceed(state, talk)
    return next.kind === 'signed' ? { ...next, chance, roll, text: `${text}\n${next.text}` } : { ...next, chance, roll }
  }
  if (talk.attempts >= PLAYER_ATTEMPTS) {
    const text = `${p.short}「${lines.reject}」`
    talk.log.push({ who: 'player', tone: 'bad', text })
    return { kind: endTalk(state, talk, 'failed') === 'lost' ? 'lost' : 'fail', chance, text, roll }
  }
  const { need, yearsOk } = wageNeed(state, p, years, role, renewal, talk)
  if (!yearsOk) {
    talk.counter = { wage: Math.max(wage, need), years: 2, role }
    const text = `${p.short}「この年齢なので、2 年以上の契約を希望します。」`
    talk.log.push({ who: 'player', tone: 'info', text })
    return { kind: 'counter', chance, text, roll }
  }
  const left = PLAYER_ATTEMPTS - talk.attempts
  const w = r10(Math.max(need * 1.01, (need * (1 + 0.04 * left) + wage) / 2))
  talk.counter = { wage: w, years, role }
  const text = `${p.short}「${lines.counter(`年俸 ${man(w)}`)}」`
  talk.log.push({ who: 'player', tone: 'info', text })
  return { kind: 'counter', chance, text, roll }
}

// ---------- 合意のあと（代理人・メディカル）----------

/** 代理人の要求・メディカルチェックがあれば止め、なければ獲得 */
function proceed(state: GameState, talk: Talk): TalkResult {
  const agent = twistOf(talk, 'agent')
  if (agent && !agent.used) {
    talk.stage = 'agent'
    const text = `代理人「最後に 1 つだけ。契約金として ${man(agent.amount!)} をお願いしたい。」`
    talk.log.push({ who: 'agent', tone: 'info', text })
    return { kind: 'event', chance: 1, text }
  }
  const med = twistOf(talk, 'medical')
  if (med && !med.used) {
    talk.stage = 'medical'
    const text = 'メディカルチェックで、ひざの古傷が見つかった。2 週ほどの別メニューが必要そうだ。'
    talk.log.push({ who: 'event', tone: 'bad', text })
    return { kind: 'event', chance: 1, text }
  }
  return sign(state, talk)
}

/** 代理人の要求を断ったときに本人が折れる見込み（乗り気なほど高い） */
export function agentRefuseChance(state: GameState, talk: Talk): number {
  const p = state.players[talk.playerId]
  const me = state.clubs[state.playerClubId]
  return Math.min(0.85, AGENT_REFUSE_CHANCE + (willFactors(state, p, me, talk.agreed?.role).will >= 0.6 ? 0.2 : 0))
}

/** 代理人の要求に答える */
export function answerAgent(state: GameState, talk: Talk, pay: boolean): TalkResult {
  const p = state.players[talk.playerId]
  const me = state.clubs[state.playerClubId]
  const agent = twistOf(talk, 'agent')
  if (talk.stage !== 'agent' || !agent || !talk.agreed) return { kind: 'none', chance: 0, text: '' }
  if (pay) {
    if (me.budget < talk.agreed.fee + agent.amount!) return { kind: 'none', chance: 0, text: '資金が足りません。' }
    agent.used = true
    talk.agreed.bonus = agent.amount
    talk.log.push({ who: 'me', text: `契約金 ${man(agent.amount!)} を払う` })
    talk.log.push({ who: 'agent', tone: 'good', text: '代理人「話が早くて助かります。」' })
    return proceed(state, talk)
  }
  agent.used = true
  const chance = agentRefuseChance(state, talk)
  talk.log.push({ who: 'me', text: `契約金は払えない（本人が折れる見込み ${pct(chance)}）` })
  const roll = dice(state, p, talk, 75)
  if (roll < chance) {
    const text = `${p.short}「お金のために来るんじゃない。このクラブでやりたいんです。」`
    talk.log.push({ who: 'player', tone: 'good', text })
    const next = proceed(state, talk)
    return next.kind === 'signed' ? { ...next, chance, roll, text: `${text}\n${next.text}` } : { ...next, chance, roll }
  }
  const text = '代理人「それでは、この話はなかったことに。」代理人は席を立った……'
  talk.log.push({ who: 'agent', tone: 'bad', text })
  return { kind: endTalk(state, talk, 'failed') === 'lost' ? 'lost' : 'fail', chance, text, roll }
}

/** メディカルチェックの結果に答える（このまま獲得・移籍金の値下げを頼む・見送る） */
export function answerMedical(state: GameState, talk: Talk, choice: 'sign' | 'discount' | 'walk'): TalkResult {
  const p = state.players[talk.playerId]
  const med = twistOf(talk, 'medical')
  if (talk.stage !== 'medical' || !med || !talk.agreed) return { kind: 'none', chance: 0, text: '' }
  if (choice === 'discount') {
    if (med.asked || p.clubId < 0 || talk.agreed.fee <= 0) return { kind: 'none', chance: 0, text: '' }
    med.asked = true
    const club = state.clubs[p.clubId]
    talk.log.push({ who: 'me', text: `古傷を理由に、移籍金の値下げを頼む（見込み ${pct(MEDICAL_DISCOUNT_CHANCE)}）` })
    const roll = dice(state, p, talk, 76)
    if (roll < MEDICAL_DISCOUNT_CHANCE) {
      talk.agreed.fee = r100(talk.agreed.fee * 0.85)
      const text = `${club.short}「……わかりました。${man(talk.agreed.fee)}でどうでしょう。」`
      talk.log.push({ who: 'club', tone: 'good', text })
      return { kind: 'accept', chance: MEDICAL_DISCOUNT_CHANCE, text, roll }
    }
    const text = `${club.short}「値下げには応じられません。この条件のままです。」`
    talk.log.push({ who: 'club', tone: 'bad', text })
    return { kind: 'reject', chance: MEDICAL_DISCOUNT_CHANCE, text, roll }
  }
  med.used = true
  if (choice === 'walk') {
    const text = `${p.name}の獲得を見送った。`
    talk.log.push({ who: 'me', text: '獲得を見送る' })
    return { kind: endTalk(state, talk, 'walked') === 'lost' ? 'lost' : 'fail', chance: 0, text }
  }
  talk.log.push({ who: 'me', text: 'このまま獲得する' })
  const r = proceed(state, talk)
  if (r.kind === 'signed' && !p.injury) p.injury = { name: 'ひざの古傷のケア', weeks: 2 }
  return r
}

/** 獲得をまとめる */
function sign(state: GameState, talk: Talk): TalkResult {
  const p = state.players[talk.playerId]
  const me = state.clubs[state.playerClubId]
  const a = talk.agreed!
  const fee = p.clubId < 0 ? 0 : a.fee
  const bonus = a.bonus ?? 0
  // 合意のあとに枠が埋まっていたら、整理するまで待ってもらう（交渉は続く）
  if (state.mode === 'club' && rosterInfo(state).full) return { kind: 'none', chance: 0, text: rosterFullText(state) }
  if (me.budget < fee + bonus || !finalizeSigning(state, p, fee, a.wage, a.years, a.role)) {
    const text = '資金が足りず、契約をまとめられなかった。'
    talk.log.push({ who: 'event', tone: 'bad', text })
    return { kind: endTalk(state, talk, 'walked') === 'lost' ? 'lost' : 'fail', chance: 0, text }
  }
  if (bonus > 0) {
    me.budget -= bonus
    bookPlayerMoney(state, 'transferOut', bonus)
  }
  talk.stage = 'done'
  talk.outcome = 'signed'
  const text = `${p.name}の獲得が決まりました！`
  talk.log.push({ who: 'event', tone: 'good', text })
  return { kind: 'signed', chance: 1, text }
}

// ---------- 終わり ----------

/** 交渉を終える。決裂なら話を聞いてもらえなくなり、割り込んだクラブがいれば取られる */
export function endTalk(state: GameState, talk: Talk, outcome: TalkOutcome): TalkOutcome {
  const p = state.players[talk.playerId]
  talk.stage = 'done'
  talk.outcome = outcome
  if (outcome === 'failed') state.talkBlock = { ...(state.talkBlock ?? {}), [p.id]: nowOf(state) + (talk.mode === 'renew' ? RENEW_BLOCK_WEEKS : BLOCK_WEEKS) }
  const rival = twistOf(talk, 'rival')
  if (talk.mode === 'buy' && rival && (outcome === 'failed' || outcome === 'walked')) {
    const rc = state.clubs[rival.clubId!]
    const fee = p.clubId >= 0 ? askingPrice(state, p) : 0
    if (rc && rivalCanSign(state, p, rc, fee)) {
      completeTransfer(state, p, rc.id, fee, { wage: fairWage(ovr(p), ageOf(p, nowOf(state)), rc.country), until: state.season + 2 })
      trimSquad(state, rc.id)
      talk.outcome = 'lost'
      talk.log.push({ who: 'event', tone: 'bad', text: `${rc.name}が${p.name}の獲得を発表。競り負けた……。` })
      state.news.push({ absWeek: nowOf(state), category: 'transfer', mine: true, text: `${p.name}は${rc.name}へ。獲得を争ったが、競り負けた。` })
    }
  }
  return talk.outcome
}

/** 終わった交渉を片づける（シートを閉じたとき） */
export function closeTalk(state: GameState, playerId: number) {
  if (!state.talks) return
  state.talks = state.talks.filter((t) => !(t.playerId === playerId && t.stage === 'done'))
  if (!state.talks.length) state.talks = undefined
}

/** 毎週: 流れた交渉と、決裂の期限を片づける（クラブモード） */
export function talkWeek(state: GameState) {
  const now = nowOf(state)
  if (state.talks) {
    const keep: Talk[] = []
    for (const talk of state.talks) {
      const p = state.players[talk.playerId]
      if (talk.stage === 'done' || !p || p.retired) continue
      if (talk.mode === 'buy') {
        if (p.clubId === state.playerClubId) continue
        if (p.clubId !== talk.fromClubId) {
          const to = p.clubId >= 0 ? `${state.clubs[p.clubId].name}へ移籍` : '退団'
          state.news.push({ absWeek: now, category: 'transfer', mine: true, text: `交渉中だった${p.name}が${to}。話は流れた。` })
          continue
        }
        if (talk.fromClubId >= 0 && !windowOpen(state)) {
          state.news.push({ absWeek: now, category: 'transfer', mine: true, text: `移籍期間が終わり、${p.name}との交渉は打ち切りになった。` })
          continue
        }
      }
      if (now - talk.startAbsWeek > TALK_WEEKS) continue
      keep.push(talk)
    }
    state.talks = keep.length ? keep : undefined
  }
  if (state.talkBlock) {
    for (const id in state.talkBlock) if (state.talkBlock[id] <= now) delete state.talkBlock[id]
    if (!Object.keys(state.talkBlock).length) state.talkBlock = undefined
  }
}

// ---------- 一覧の札 ----------

export type SignStatus = 'talking' | 'blocked' | 'refuse' | 'role' | 'money' | 'window' | 'eager' | 'ok' | 'hard'

export interface Signability {
  status: SignStatus
  label: string
  tone: 'good' | 'info' | 'warn' | 'bad' | 'mute'
  /** いま交渉を始められる（続きを含む） */
  canTalk: boolean
  will: number
  fee: number
  wage: number
}

/**
 * 選手枠がいっぱいか。一覧では ranks（一覧ごとに 1 回作る）に結びつけて覚え、選手ごとに全選手を数え直さない
 * （前は 1 行ごとに 5,000 人あまりを数えていて、移籍の「探す」を開くと止まっていた）
 */
const fullMemo = new WeakMap<Map<number, number>, boolean>()
function rosterFull(state: GameState, ranks?: Map<number, number>): boolean {
  if (state.mode !== 'club') return false
  if (!ranks) return rosterInfo(state).full
  let v = fullMemo.get(ranks)
  if (v === undefined) {
    v = rosterInfo(state).full
    fullMemo.set(ranks, v)
  }
  return v
}

/** 獲得できそうか（一覧と選手の画面に出す札）。ranks を渡すとクラブ内順位と選手枠を数え直さない */
export function signability(state: GameState, p: Player, ranks?: Map<number, number>): Signability {
  const me = state.clubs[state.playerClubId]
  const fee = p.clubId >= 0 ? clubAsk(state, p, ranks) : 0
  const wage = wageDemand(state, p, me)
  const will = willFactors(state, p, me, 'regular').will
  const base = { will, fee, wage }
  // 移籍期間（札に出す）と、選手枠（いっぱいなら札は乗り気のまま、交渉のボタンだけ押せない）
  const windowOk = p.clubId < 0 || windowOpen(state)
  const roomy = !rosterFull(state, ranks)
  const open = windowOk && roomy
  const talk = findTalk(state, p.id, 'buy')
  if (talk && talk.stage !== 'done') return { ...base, status: 'talking', label: '交渉中', tone: 'info', canTalk: open }
  const b = blockedWeeks(state, p)
  if (b > 0) return { ...base, status: 'blocked', label: `決裂（あと ${b} 週）`, tone: 'mute', canTalk: false }
  if (will < 0.12) {
    const star = willFactors(state, p, me, 'star').will >= 0.12
    return star ? { ...base, status: 'role', label: '主力の約束が条件', tone: 'warn', canTalk: open } : { ...base, status: 'refuse', label: '来る気なし', tone: 'bad', canTalk: false }
  }
  if (!affordable(me, fee, wage) || me.budget < fee) return { ...base, status: 'money', label: '資金不足', tone: 'bad', canTalk: false }
  if (!windowOk) return { ...base, status: 'window', label: '移籍期間に交渉', tone: 'mute', canTalk: false }
  if (will >= 0.6) return { ...base, status: 'eager', label: '乗り気', tone: 'good', canTalk: roomy }
  if (will >= 0.35) return { ...base, status: 'ok', label: '狙える', tone: 'info', canTalk: roomy }
  return { ...base, status: 'hard', label: '難しい', tone: 'warn', canTalk: roomy }
}

/** 獲れる見込みがない（一覧で薄く出す） */
export function outOfReach(s: Signability): boolean {
  return s.status === 'refuse' || s.status === 'money' || s.status === 'blocked'
}
