/**
 * 国際ユースカップ（M25。クラブモード）: ウインターブレイクに開く 8 クラブの U-18 の大会。
 *   第 12 週に招待（クラブの格 40 から。ユースと 18 歳以下の選手が 3 人以上。足りないところはアカデミーの控えの子）。第 20 週までに参加か辞退（参加は遠征費）
 *   第 21 週 準々決勝・第 22 週 準決勝・第 23 週 決勝（中立地。引き分けは PK）
 *   自クラブの試合はユースの選手で（足りなければその場で作る控え）。観戦もできる（YouthCupScreen）。結果だけなら FastSim
 *   ほかの試合はチームの力から（抽象の結果）
 *   出た選手は少し伸びる。優勝・準優勝で人気とサポーター
 *   相手の目立った選手（評価点 7.0 以上）は、冬の海外の有望株に並ぶ（overseasYouth.ts）
 * 相手の選手は世界の選手に足さない（チームごとの種から、毎回同じ顔ぶれを作る）。
 */
import { absWeekOf, ageAt } from '../core/calendar'
import { createRng, hashSeed, type Rng } from '../core/prng'
import { ATTR_KEYS } from '../data/attributes'
import { YOUTH_CUP_HOSTS } from '../data/academies'
import { FORMATIONS, formationOf } from '../data/formations'
import { FLAGS, NATION_NAME, generateName, type Nation } from '../data/nations'
import type { Position } from '../data/positions'
import { buildAttrs, starterOvrForRep } from '../gen/playerGen'
import { fastSim } from '../match/fastSim'
import { selectionScore } from '../match/lineup'
import type { MatchPlayerSetup, MatchSetup, MatchSummary, TeamSetup } from '../match/live/types'
import { matchPlayer, resolveKitClash } from '../match/setup'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import { ovr } from '../player/overall'
import { fansCap, popularityCap } from './fans'
import { chargeYouth } from './academy'

export const YC_INVITE_WEEK = 12
export const YC_REPLY_WEEK = 20
export const YC_WEEKS = [21, 22, 23]
export const YC_FEE = 800
export const YC_MIN_REP = 40
/** 出られる年齢（ユースでなくても） */
export const YC_MAX_AGE = 18
/** 招待されるのに要る、出られる選手の数 */
export const YC_MIN_PLAYERS = 3
export const YC_ROUND = ['準々決勝', '準決勝', '決勝']
/** 成績（自クラブが最後に戦った回戦）の名前: 0 ベスト8 … 3 優勝 */
export const YC_RESULT = ['ベスト8', 'ベスト4', '準優勝', '優勝']

export interface YouthCupTeam {
  name: string
  short: string
  nation: Nation
  /** チームの力（選手の総合の目安） */
  level: number
  colors: { primary: string; secondary: string }
  clubId?: number
}

export interface YouthCupMatch {
  a: number
  b: number
  score?: [number, number]
  pens?: [number, number]
  winner?: number
  /** 観戦した */
  watched?: boolean
}

export interface Standout {
  name: string
  short: string
  nation: Nation
  pos: Position
  level: number
  team: string
  rating: number
}

export interface YouthCup {
  season: number
  host: { city: string; nation: Nation }
  status: 'invited' | 'entered' | 'declined' | 'done'
  /** 0 が自クラブ */
  teams: YouthCupTeam[]
  /** 準々決勝 4・準決勝 2・決勝 1（前の回戦が終わったら組む） */
  rounds: YouthCupMatch[][]
  /** 自クラブの選手の大会の成績 */
  ours: Record<number, { apps: number; goals: number; ratingSum: number }>
  /** 相手の目立った選手（評価点の高い順） */
  standouts: Standout[]
  /** 自クラブの成績（YC_RESULT の添え字） */
  result?: number
}

export interface YouthCupRecord {
  season: number
  host: string
  result: number
  mvp?: string
}

function now(state: GameState): number {
  return absWeekOf(state.season, state.week)
}

function asNation(country: string): Nation {
  return (FLAGS as Record<string, unknown>)[country] !== undefined ? (country as Nation) : 'EN'
}

/** 出られる選手: ユースと、18 歳以下のトップの選手（ケガ・留学中は出ない） */
export function cupSquad(state: GameState): Player[] {
  const me = state.playerClubId
  const t = now(state)
  return Object.values(state.players)
    .filter((p) => p.clubId === me && !p.retired && !p.loan && (p.isYouth || ageAt(t, p.birthAbsWeek) <= YC_MAX_AGE) && !p.injury && !(p.study && t < p.study.untilAbsWeek))
    .sort((a, b) => ovr(b) - ovr(a))
}

/** 控えの子（ユースの有望株のほかのアカデミーの子）の力: クラブの格とユース施設から */
export function fillLevel(state: GameState): number {
  const me = state.clubs[state.playerClubId]
  return starterOvrForRep(me.rep, me.country) - 20 + me.facilities.youth * 1.5
}

/** 大会の陣形（トップと同じ。使えなければ 4-2-3-1） */
export function cupFormation(state: GameState): string {
  const f = state.clubs[state.playerClubId].tactics?.formation
  return f && FORMATIONS.some((x) => x.id === f) ? f : '4-2-3-1'
}

/** 先発: 強い組み合わせから順に、合うポジションへ（控えの子より弱ければ入れない）。null は控えの子 */
export function cupLineup(state: GameState, formation = cupFormation(state)): (Player | null)[] {
  const f = formationOf(formation)
  const fl = fillLevel(state)
  const pairs: { p: Player; i: number; s: number }[] = []
  for (const p of cupSquad(state)) f.slots.forEach((sl, i) => pairs.push({ p, i, s: selectionScore(p, sl.pos) }))
  pairs.sort((a, b) => b.s - a.s)
  const slots: (Player | null)[] = f.slots.map(() => null)
  const used = new Set<number>()
  for (const x of pairs) {
    if (used.has(x.p.id) || slots[x.i] || x.s <= fl) continue
    slots[x.i] = x.p
    used.add(x.p.id)
  }
  return slots
}

/** 自クラブのチームの力（先発のポジションでの評価の平均。控えの子は fillLevel） */
export function ourLevel(state: GameState): number {
  const f = formationOf(cupFormation(state))
  const fl = fillLevel(state)
  const lu = cupLineup(state, f.id)
  return lu.reduce((s, p, i) => s + (p ? selectionScore(p, f.slots[i].pos) : fl), 0) / lu.length
}

/** 第 12 週: 招待（クラブの格 40 から） */
export function inviteYouthCup(state: GameState): boolean {
  if (state.mode !== 'club') return false
  const me = state.clubs[state.playerClubId]
  if (me.rep < YC_MIN_REP || state.youthCup?.season === state.season || cupSquad(state).length < YC_MIN_PLAYERS) return false
  const rng = createRng(hashSeed(state.seed, state.season, 0x7c01))
  const host = YOUTH_CUP_HOSTS[state.season % YOUTH_CUP_HOSTS.length]
  const ai = state.clubs.filter((c) => !c.isPlayer && c.rep >= 60 && c.leagueId !== 'AMA')
  const score = (rep: number) => rep + rng.range(0, 20)
  const pick = (pool: typeof ai, n: number) =>
    pool
      .map((c) => ({ c, s: score(c.rep) }))
      .sort((a, b) => b.s - a.s)
      .slice(0, n)
      .map((x) => x.c)
  const europe = ai.filter((c) => ['EN', 'ES', 'IT', 'DE', 'FR'].includes(c.country))
  const chosen = [
    ...pick(europe, 4),
    ...pick(
      ai.filter((c) => c.country === 'BR'),
      1,
    ),
    ...pick(
      ai.filter((c) => c.leagueId === 'ASIA'),
      1,
    ),
    ...pick(
      ai.filter((c) => c.country === 'JP'),
      1,
    ),
  ]
  // 足りなければ欧州から
  for (const c of pick(europe, 12)) if (chosen.length < 7 && !chosen.includes(c)) chosen.push(c)
  const teams: YouthCupTeam[] = [
    { name: `${me.short} U-18`, short: me.short, nation: 'JP', level: 0, colors: me.colors, clubId: me.id },
    ...chosen.slice(0, 7).map((c) => ({ name: `${c.short} U-18`, short: c.short, nation: asNation(c.country), level: Math.round((starterOvrForRep(c.rep, c.country) - 17 + rng.range(-2, 2)) * 10) / 10, colors: c.colors, clubId: c.id })),
  ]
  // 組み合わせ（自クラブの相手はくじ）
  const order = [0, ...rng.shuffle([1, 2, 3, 4, 5, 6, 7])]
  const qf: YouthCupMatch[] = [0, 2, 4, 6].map((i) => ({ a: order[i], b: order[i + 1] }))
  state.youthCup = { season: state.season, host, status: 'invited', teams, rounds: [qf], ours: {}, standouts: [] }
  state.news.push({ absWeek: now(state), category: 'club', mine: true, text: `国際ユースカップ（${NATION_NAME[host.nation]}・${host.city}）に招待されました。欧州・南米・アジアの強豪の U-18 と戦います。返事は第 ${YC_REPLY_WEEK + 1} 週まで（ユースアカデミー → 国際ユースカップ）。` })
  return true
}

export function canEnterYouthCup(state: GameState): { ok: boolean; reason?: string } {
  const cup = state.youthCup
  if (!cup || cup.season !== state.season || cup.status !== 'invited') return { ok: false, reason: '招待されていない' }
  if (state.week > YC_REPLY_WEEK) return { ok: false, reason: '締め切りを過ぎた' }
  if (state.clubs[state.playerClubId].budget < YC_FEE) return { ok: false, reason: '資金が足りない' }
  return { ok: true }
}

export function replyYouthCup(state: GameState, enter: boolean): boolean {
  const cup = state.youthCup
  if (!cup || cup.status !== 'invited') return false
  if (enter) {
    if (!canEnterYouthCup(state).ok) return false
    chargeYouth(state, YC_FEE)
    cup.status = 'entered'
    state.news.push({ absWeek: now(state), category: 'club', mine: true, text: `国際ユースカップへの参加を決めました。ウインターブレイク（第 ${YC_WEEKS[0] + 1}〜${YC_WEEKS[2] + 1} 週）に${cup.host.city}で戦います。` })
  } else {
    cup.status = 'declined'
  }
  return true
}

/** 今週の回戦（大会の週でなければ -1） */
export function cupRoundNow(state: GameState): number {
  const cup = state.youthCup
  if (!cup || cup.season !== state.season || cup.status !== 'entered') return -1
  return YC_WEEKS.indexOf(state.week)
}

/** 前の回戦の勝者で次の回戦を組む */
function ensureRound(cup: YouthCup, r: number) {
  if (cup.rounds[r]) return
  const prev = cup.rounds[r - 1]
  if (!prev || prev.some((m) => m.winner === undefined)) return
  const out: YouthCupMatch[] = []
  for (let i = 0; i < prev.length; i += 2) out.push({ a: prev[i].winner!, b: prev[i + 1].winner! })
  cup.rounds[r] = out
}

/** 今週の自クラブの試合（もう済んでいれば null） */
export function ourCupMatch(state: GameState): { round: number; match: YouthCupMatch; opp: YouthCupTeam } | null {
  const r = cupRoundNow(state)
  if (r < 0) return null
  const cup = state.youthCup!
  ensureRound(cup, r)
  const m = cup.rounds[r]?.find((x) => x.a === 0 || x.b === 0)
  if (!m || m.score) return null
  return { round: r, match: m, opp: cup.teams[m.a === 0 ? m.b : m.a] }
}

/** 相手のチームの選手（チームごとの種から毎回同じ顔ぶれ） */
function oppPlayers(state: GameState, cup: YouthCup, ti: number, formation: string): { starters: MatchPlayerSetup[]; bench: MatchPlayerSetup[] } {
  const t = cup.teams[ti]
  const rng = createRng(hashSeed(state.seed, cup.season, 0x7c00 + ti))
  const f = formationOf(formation)
  let id = -(20000 + ti * 40)
  const make = (pos: Position, level: number, number: number): MatchPlayerSetup => {
    const nm = generateName(t.nation, rng)
    return { id: id--, name: nm.full, short: nm.short, number, pos, attr: buildAttrs(rng, pos, level), skills: [], stamina: 100, aggression: rng.int(6, 15), workRate: rng.int(8, 16) }
  }
  const starters = f.slots.map((sl, i) => make(sl.pos, t.level + rng.range(-3, 3), i + 1))
  const bench = (['GK', 'CB', 'CM', 'WG', 'ST'] as Position[]).map((pos, i) => make(pos, t.level - 3, 12 + i))
  return { starters, bench }
}

const TACTICS = { mentality: 0, tempo: 50, width: 50, lineHeight: 50, pressing: 50, focus: 'balanced' as const, offsideTrap: false, counter: false }

/** 自クラブの今週の試合の設定（観戦にも結果だけにも使う） */
export function youthCupSetup(state: GameState): MatchSetup | null {
  const cur = ourCupMatch(state)
  if (!cur) return null
  const cup = state.youthCup!
  const me = state.clubs[state.playerClubId]
  const oi = cur.match.a === 0 ? cur.match.b : cur.match.a
  const f = formationOf(cupFormation(state))
  // 自クラブ: ポジションに合うユースの選手から。合う選手がいなければ、その場で作る控えの子
  const rng = createRng(hashSeed(state.seed, cup.season, 0x7c50 + cur.round))
  const pool = cupSquad(state)
  const fl = fillLevel(state)
  let fakeId = -19000
  const fake = (pos: Position, n: number): MatchPlayerSetup => {
    const nm = generateName('JP', rng)
    return { id: fakeId--, name: nm.full, short: nm.short, number: n, pos, attr: buildAttrs(rng, pos, fl), skills: [], stamina: 100, aggression: 10, workRate: 12 }
  }
  const lineup = cupLineup(state, f.id)
  const used = new Set(lineup.flatMap((p) => (p ? [p.id] : [])))
  const starters = f.slots.map((sl, i) => {
    const p = lineup[i]
    return p ? { ...matchPlayer(p, sl.pos, 'neutral'), number: p.number || i + 1 } : fake(sl.pos, 90 + i)
  })
  const bench = pool
    .filter((p) => !used.has(p.id))
    .slice(0, 5)
    .map((p) => ({ ...matchPlayer(p, p.pos, 'neutral'), number: p.number || 30 }))
  while (bench.length < 5) bench.push(fake((['GK', 'CB', 'CM', 'WG', 'ST'] as Position[])[bench.length], 80 + bench.length))
  const home: TeamSetup = { clubId: -(900 + 0), name: cup.teams[0].name, short: cup.teams[0].short, colors: me.colors, gkColor: '#111827', formation: f.id, tactics: { formation: f.id, ...TACTICS }, starters, bench, ai: true, chemBase: 55, cohesion: 55 }
  const oppF = formationOf('4-2-3-1')
  const opp = oppPlayers(state, cup, oi, oppF.id)
  const t = cup.teams[oi]
  const away: TeamSetup = { clubId: -(900 + oi), name: t.name, short: t.short, colors: t.colors, gkColor: '#111827', formation: oppF.id, tactics: { formation: oppF.id, ...TACTICS }, starters: opp.starters, bench: opp.bench, ai: true, chemBase: 55, cohesion: 55 }
  resolveKitClash(home, away)
  return { seed: hashSeed(state.seed, cup.season, 0x7c77 + cur.round), home, away, neutral: true, knockout: true }
}

/** 自クラブの試合の結果を入れる（観戦でも結果だけでも。setup は試合に使ったもの） */
function applyOurCupResult(state: GameState, setup: MatchSetup, summary: MatchSummary, watched: boolean) {
  const cur = ourCupMatch(state)
  if (!cur) return
  const cup = state.youthCup!
  const m = cur.match
  const [gf, ga] = summary.score
  const pens = summary.pens
  const win = gf > ga || (gf === ga && !!pens && pens[0] > pens[1])
  const weA = m.a === 0
  m.score = weA ? [gf, ga] : [ga, gf]
  if (pens) m.pens = weA ? pens : [pens[1], pens[0]]
  m.winner = win ? 0 : weA ? m.b : m.a
  m.watched = watched
  // 自クラブの選手: 大会の成績・少し伸びる・やる気
  for (const ps of summary.players) {
    if (ps.team !== 0 || ps.minutes <= 0) continue
    const p = state.players[ps.id]
    if (!p) continue
    const o = (cup.ours[p.id] ??= { apps: 0, goals: 0, ratingSum: 0 })
    o.apps++
    o.goals += ps.goals
    o.ratingSum += ps.rating
    const k = Math.max(0.7, Math.min(1.4, ps.rating / 6.5)) * 0.02
    for (const a of ATTR_KEYS) {
      const head = p.cap[a] - p.attr[a]
      if (head > 0) p.attr[a] = Math.round((p.attr[a] + head * k) * 100) / 100
    }
    p.morale = Math.min(100, p.morale + (win ? 6 : 2))
  }
  // 相手の目立った選手
  const oi = weA ? m.b : m.a
  const t = cup.teams[oi]
  for (const ps of summary.players) {
    if (ps.team !== 1 || ps.rating < 7) continue
    const mp = setup.away.starters.find((x) => x.id === ps.id) ?? setup.away.bench.find((x) => x.id === ps.id)
    if (!mp || cup.standouts.some((s) => s.name === mp.name)) continue
    cup.standouts.push({ name: mp.name, short: mp.short, nation: t.nation, pos: mp.pos, level: Math.round(t.level), team: t.name, rating: Math.round(ps.rating * 10) / 10 })
  }
  cup.standouts.sort((a, b) => b.rating - a.rating)
  cup.standouts = cup.standouts.slice(0, 3)
  const score = `${gf}-${ga}${pens ? `（PK ${pens[0]}-${pens[1]}）` : ''}`
  state.news.push({ absWeek: now(state), category: 'club', mine: true, text: `国際ユースカップ ${YC_ROUND[cur.round]}: ${cup.teams[0].name} ${score} ${t.name}。${win ? (cur.round === 2 ? '優勝！' : '勝ち上がり！') : '敗退。'}` })
}

/** 結果だけ（FastSim）で自クラブの試合をする */
export function playOurCupMatch(state: GameState): MatchSummary | null {
  const setup = youthCupSetup(state)
  if (!setup) return null
  const s = fastSim(setup, createRng(hashSeed(setup.seed, 0xfa57)))
  applyOurCupResult(state, setup, s, false)
  return s
}

/** 観戦した試合の結果を入れる（setup は観戦に使ったもの） */
export function playYouthCupWatched(state: GameState, setup: MatchSetup, summary: MatchSummary) {
  applyOurCupResult(state, setup, summary, true)
}

function poisson(rng: Rng, lambda: number): number {
  const l = Math.exp(-lambda)
  let k = 0
  let p = 1
  do {
    k++
    p *= rng.next()
  } while (p > l && k < 10)
  return k - 1
}

/** ほかの試合（チームの力から） */
function abstractMatch(cup: YouthCup, m: YouthCupMatch, rng: Rng) {
  const la = cup.teams[m.a].level
  const lb = cup.teams[m.b].level
  const ga = poisson(rng, 1.35 * Math.exp((la - lb) / 14))
  const gb = poisson(rng, 1.35 * Math.exp((lb - la) / 14))
  m.score = [ga, gb]
  if (ga !== gb) {
    m.winner = ga > gb ? m.a : m.b
    return
  }
  const pa = 1 / (1 + Math.exp(-(la - lb) / 10))
  const aWins = rng.chance(pa)
  m.pens = aWins ? [rng.int(3, 5), rng.int(1, 3)] : [rng.int(1, 3), rng.int(3, 5)]
  if (m.pens[0] === m.pens[1]) m.pens[aWins ? 0 : 1]++
  m.winner = aWins ? m.a : m.b
}

/** 毎週（クラブモード）: 招待・締め切り・試合。招待の週は 'invite'、自クラブの試合をした週は 'match' */
export function youthCupWeek(state: GameState): 'invite' | 'match' | null {
  if (state.mode !== 'club') return null
  if (state.week === YC_INVITE_WEEK) return inviteYouthCup(state) ? 'invite' : null
  const cup = state.youthCup
  if (!cup || cup.season !== state.season) return null
  // 返事がなければ辞退
  if (state.week === YC_REPLY_WEEK + 1 && cup.status === 'invited') {
    cup.status = 'declined'
    state.news.push({ absWeek: now(state), category: 'club', mine: true, text: '国際ユースカップは返事をしなかったので、今回は見送りになりました。' })
  }
  const r = cupRoundNow(state)
  if (r < 0) return null
  // 自クラブのユースの水準（初戦の前に決める）
  if (r === 0 && !cup.teams[0].level) cup.teams[0].level = Math.round(ourLevel(state) * 10) / 10
  ensureRound(cup, r)
  let played: 'match' | null = null
  if (ourCupMatch(state)) {
    playOurCupMatch(state)
    played = 'match'
  }
  const rng = createRng(hashSeed(state.seed, cup.season, 0x7ca0 + r))
  for (const m of cup.rounds[r] ?? []) if (!m.score) abstractMatch(cup, m, rng)
  if (r === YC_WEEKS.length - 1) finishYouthCup(state)
  return played
}

/** 自クラブが最後に戦った回戦から成績（3 = 優勝） */
export function ourResult(cup: YouthCup): number {
  let res = 0
  cup.rounds.forEach((ms, r) => {
    const m = ms.find((x) => x.a === 0 || x.b === 0)
    if (m?.winner === 0) res = r + 1
  })
  return res
}

function finishYouthCup(state: GameState) {
  const cup = state.youthCup!
  const me = state.clubs[state.playerClubId]
  cup.status = 'done'
  const res = ourResult(cup)
  cup.result = res
  const tier = state.competitions.find((c) => c.id === me.leagueId)?.tier ?? 3
  const mvpId = Object.entries(cup.ours).sort((a, b) => b[1].ratingSum / b[1].apps - a[1].ratingSum / a[1].apps)[0]?.[0]
  const mvp = mvpId !== undefined ? state.players[Number(mvpId)]?.name : undefined
  if (res === 3) {
    me.popularity = Math.min(popularityCap(tier), me.popularity + 3)
    me.fans = Math.min(fansCap(state, me), me.fans + 600)
    me.rep = Math.min(100, me.rep + 0.5)
  } else if (res === 2) {
    me.popularity = Math.min(popularityCap(tier), me.popularity + 1.5)
    me.fans = Math.min(fansCap(state, me), me.fans + 250)
  } else if (res === 1) me.popularity = Math.min(popularityCap(tier), me.popularity + 0.5)
  const champ = cup.rounds[2]?.[0]?.winner
  state.youthCupLog = [...(state.youthCupLog ?? []), { season: cup.season, host: cup.host.city, result: res, mvp: res === 3 ? mvp : undefined }]
  state.news.push({
    absWeek: now(state),
    category: 'club',
    mine: true,
    text: res === 3 ? `国際ユースカップで優勝！ ${cup.teams[0].name}が世界の強豪を破りました。大会 MVP は ${mvp ?? '—'}。` : `国際ユースカップは${YC_RESULT[res]}。優勝は${champ !== undefined ? cup.teams[champ].name : '—'}。`,
  })
}
