/**
 * 大陸大会と世界大会。
 *   ACC アジアクラブカップ: 16 クラブ（日本 4・アジア 12）。4 組の総当たり（平日 6 節）→ 準々決勝 → 準決勝 → 決勝（中立地）
 *   EUC 欧州チャンピオンズカップ: 欧州 5 リーグの上位 16 クラブのトーナメント（自クラブは出ない。世界大会の欧州代表を決める）
 *   WCC 世界クラブ選手権: 8 クラブ、すべて中立地。第 45〜47 週
 * 出場クラブは前のシーズン末に decideQualifiers で決めておく（最初のシーズンはクラブ格の順）。
 */
import { createRng, hashSeed, type Rng } from '../core/prng'
import { absWeekOf } from '../core/calendar'
import type { Competition, Fixture } from '../models/competition'
import { allocId, type GameState, type SeasonSummary } from '../models/game'
import { emptyRow, roundRobin, sortTable } from './league'
import { winnerOf } from './playoff'
import { CUP_ID, CUP_ROUND_NAME, cupStage } from './cup'

export const ACC_ID = 'ACC'
export const EUC_ID = 'EUC'
export const WCC_ID = 'WCC'
export const ASIA_ID = 'ASIA'
export const CONTINENTAL_IDS = [ACC_ID, EUC_ID, WCC_ID]

/** ACC: グループ 6 節の週と、準々決勝・準決勝・決勝の週 */
export const ACC_GROUP_WEEKS = [8, 12, 16, 25, 29, 33]
export const ACC_KO_WEEKS = [37, 39, 44]
/** ACC の回戦番号: 0-5 = グループ第 1〜6 節、6 = 準々決勝、7 = 準決勝、8 = 決勝 */
export const ACC_QF = 6
export const ACC_FINAL = 8
export const EUC_WEEKS = [25, 33, 37, 44]
export const WCC_WEEKS = [45, 46, 47]
export const GROUP_LETTERS = ['A', 'B', 'C', 'D']

const ACC_ROUND_NAMES = ['グループ第1節', 'グループ第2節', 'グループ第3節', 'グループ第4節', 'グループ第5節', 'グループ第6節', '準々決勝', '準決勝', '決勝']
const EUC_ROUND_NAMES = ['1回戦', '準々決勝', '準決勝', '決勝']
const WCC_ROUND_NAMES = ['準々決勝', '準決勝', '決勝']

/** 自クラブの賞金（万円）: ACC はグループ敗退・準々決勝・準決勝・準優勝・優勝 */
export const ACC_PRIZE = [3000, 5000, 8000, 12000, 20000]
/** WCC は準々決勝・準決勝・準優勝・優勝 */
export const WCC_PRIZE = [10000, 20000, 30000, 50000]
/** 格の上がり幅（参加したクラブすべて） */
const ACC_REP = [1, 2, 3, 4, 6]
const WCC_REP = [3, 4, 6, 10]

/** 回戦の名前（リーグは「第 n 節」） */
export function roundName(comp: Competition, round: number): string {
  if (comp.roundNames?.[round]) return comp.roundNames[round]
  if (comp.id === CUP_ID) return CUP_ROUND_NAME[round] ?? ''
  if (comp.id.endsWith('PO')) return round === 1 ? '決勝' : '準決勝'
  if (comp.kind === 'league') return `第${round + 1}節`
  return `${round + 1}回戦`
}

/** 中立地の試合か */
export function isNeutral(comp: Competition, f: Fixture): boolean {
  return comp.neutralFrom !== undefined && f.round >= comp.neutralFrom
}

/** 延長・PK まで決着をつける試合か（グループ戦とリーグ戦は引き分けで終わる） */
export function isKnockoutFixture(comp: Competition, f: Fixture): boolean {
  return comp.kind !== 'league' && f.group === undefined
}

/** buildMatchSetup に渡す試合の条件 */
export function matchOptions(comp: Competition, f: Fixture): { knockout: boolean; neutral: boolean } {
  return { knockout: isKnockoutFixture(comp, f), neutral: isNeutral(comp, f) }
}

const byRep = (state: GameState) => (a: number, b: number) => state.clubs[b].rep - state.clubs[a].rep || a - b

function asiaTop(state: GameState, n: number): number[] {
  const pool = state.competitions.find((c) => c.id === ASIA_ID)?.clubIds ?? []
  return [...pool].sort(byRep(state)).slice(0, n)
}

function leagueTop(state: GameState, id: string, n: number, byTable: boolean): number[] {
  const comp = state.competitions.find((c) => c.id === id)
  if (!comp) return []
  if (byTable && comp.table.some((r) => r.played > 0)) {
    sortTable(comp)
    return comp.table.slice(0, n).map((r) => r.clubId)
  }
  return [...comp.clubIds].sort(byRep(state)).slice(0, n)
}

const EUC_QUOTA: [string, number][] = [
  ['ENG1', 4],
  ['ESP1', 4],
  ['ITA1', 3],
  ['GER1', 3],
  ['FRA1', 2],
]

/** シーズン末（順位表を消す前）に、来季の大陸大会の出場クラブを決める */
export function decideQualifiers(state: GameState) {
  // 日本: NPL1 の 1〜3 位＋カップ優勝（重なれば NPL1 の 4 位）
  const npl = leagueTop(state, 'NPL1', 6, true)
  const jp = npl.slice(0, 3)
  const cupChamp = cupStage(state)?.champion ?? -1
  if (cupChamp >= 0 && !jp.includes(cupChamp)) jp.push(cupChamp)
  for (const id of npl) if (jp.length < 4 && !jp.includes(id)) jp.push(id)
  const acc = [...jp.slice(0, 4), ...asiaTop(state, 12)]
  const euc = EUC_QUOTA.flatMap(([id, n]) => leagueTop(state, id, n, true))
  state.qualified = { acc, euc }
}

function accQualifiers(state: GameState): number[] {
  const q = state.qualified?.acc
  if (q && q.length === 16 && q.every((id) => state.clubs[id])) return q
  return [...leagueTop(state, 'NPL1', 4, false), ...asiaTop(state, 12)]
}

function eucQualifiers(state: GameState): number[] {
  const q = state.qualified?.euc
  if (q && q.length === 16 && q.every((id) => state.clubs[id])) return q
  return EUC_QUOTA.flatMap(([id, n]) => leagueTop(state, id, n, false))
}

function newComp(state: GameState, id: string, name: string, short: string, clubIds: number[], roundNames: string[], neutralFrom: number): Competition {
  return { id, kind: id === WCC_ID ? 'worldClub' : 'continental', name, short, country: id === EUC_ID ? 'EU' : id === ACC_ID ? 'AS' : 'WORLD', tier: 0, season: state.season, clubIds, fixtures: [], table: [], promotion: 0, relegation: 0, playoff: false, simulated: 'full', roundNames, neutralFrom }
}

function addFixture(state: GameState, comp: Competition, round: number, week: number, home: number, away: number, group?: number) {
  comp.fixtures.push({ id: allocId(state, 'fixture'), compId: comp.id, round, absWeek: absWeekOf(state.season, week), slot: 'midweek', home, away, ...(group !== undefined ? { group } : {}) })
}

/** 開幕時に ACC と EUC を作る（WCC は第 45 週に組む） */
export function createContinental(state: GameState) {
  state.competitions = state.competitions.filter((c) => !CONTINENTAL_IDS.includes(c.id))
  if (!state.competitions.some((c) => c.id === ASIA_ID)) return
  const rng = createRng(hashSeed(state.seed, state.season, 0xacc))
  createAcc(state, rng)
  createEuc(state, rng)
}

function createAcc(state: GameState, rng: Rng) {
  const ids = accQualifiers(state)
  const comp = newComp(state, ACC_ID, 'アジアクラブカップ', 'ACC', ids, ACC_ROUND_NAMES, ACC_FINAL)
  // 組分け: 日本のクラブは別々の組に。アジアは格の順に 3 つのポットから 1 クラブずつ
  const jp = rng.shuffle(ids.slice(0, 4))
  const asia = [...ids.slice(4)].sort(byRep(state))
  const pots = [0, 1, 2].map((k) => rng.shuffle(asia.slice(k * 4, k * 4 + 4)))
  for (let g = 0; g < 4; g++) {
    const members = [jp[g], pots[0][g], pots[1][g], pots[2][g]].filter((x) => x !== undefined)
    for (const id of members) comp.table.push({ ...emptyRow(id), group: g })
    roundRobin(members, rng).forEach((pairs, r) => {
      for (const [h, a] of pairs) addFixture(state, comp, r, ACC_GROUP_WEEKS[r], h, a, g)
    })
  }
  state.competitions.push(comp)
}

function createEuc(state: GameState, rng: Rng) {
  const ids = eucQualifiers(state)
  const comp = newComp(state, EUC_ID, '欧州チャンピオンズカップ', 'EUC', ids, EUC_ROUND_NAMES, 3)
  // シード（格の上位 8）と、それ以外の対戦。シードがホーム
  const sorted = [...ids].sort(byRep(state))
  const seeds = sorted.slice(0, 8)
  const others = rng.shuffle(sorted.slice(8))
  seeds.forEach((h, i) => addFixture(state, comp, 0, EUC_WEEKS[0], h, others[i]))
  state.competitions.push(comp)
}

/** 組ごとの順位（1 位から） */
export function groupStandings(comp: Competition, group: number) {
  sortTable(comp)
  return comp.table.filter((r) => r.group === group)
}

/** 前の回戦の勝者で次の回戦を組む（i 番目と i + 半分を当てる。格の高い方がホーム） */
function drawNext(state: GameState, comp: Competition, round: number, week: number) {
  const prev = comp.fixtures.filter((f) => f.round === round - 1)
  if (!prev.length || prev.some((f) => !f.result)) return
  const w = prev.map(winnerOf).filter((x): x is number => x !== null)
  const half = w.length / 2
  for (let i = 0; i < half; i++) {
    let [h, a] = [w[i], w[i + half]]
    if (state.clubs[a].rep > state.clubs[h].rep) [h, a] = [a, h]
    addFixture(state, comp, round, week, h, a)
  }
}

/** 週の頭に呼ぶ: 決勝トーナメントの組み合わせと、世界クラブ選手権 */
export function advanceContinental(state: GameState) {
  const w = state.week
  const acc = state.competitions.find((c) => c.id === ACC_ID)
  if (acc) {
    const k = ACC_KO_WEEKS.indexOf(w)
    const round = ACC_QF + k
    if (k >= 0 && !acc.fixtures.some((f) => f.round === round)) {
      if (k === 0) {
        const group = acc.fixtures.filter((f) => f.group !== undefined)
        if (group.length && group.every((f) => f.result)) {
          const st = [0, 1, 2, 3].map((g) => groupStandings(acc, g))
          // A1-B2, C1-D2, B1-A2, D1-C2（準決勝で A1 と B1 が当たらない並び）
          const pairs: [number, number][] = [
            [st[0][0].clubId, st[1][1].clubId],
            [st[2][0].clubId, st[3][1].clubId],
            [st[1][0].clubId, st[0][1].clubId],
            [st[3][0].clubId, st[2][1].clubId],
          ]
          for (const [h, a] of pairs) addFixture(state, acc, round, w, h, a)
        }
      } else drawNext(state, acc, round, w)
    }
  }
  const euc = state.competitions.find((c) => c.id === EUC_ID)
  if (euc) {
    const k = EUC_WEEKS.indexOf(w)
    if (k > 0 && !euc.fixtures.some((f) => f.round === k)) drawNext(state, euc, k, w)
  }
  const k = WCC_WEEKS.indexOf(w)
  if (k === 0 && !state.competitions.some((c) => c.id === WCC_ID)) createWcc(state)
  const wcc = state.competitions.find((c) => c.id === WCC_ID)
  if (wcc && k > 0 && !wcc.fixtures.some((f) => f.round === k)) drawNext(state, wcc, k, w)
}

function finalOf(comp: Competition | undefined): Fixture | undefined {
  if (!comp?.roundNames) return undefined
  const last = comp.roundNames.length - 1
  return comp.fixtures.find((f) => f.round === last)
}

/** 大会の優勝クラブ（決勝が終わっていなければ -1） */
export function championOf(comp: Competition | undefined): number {
  const f = finalOf(comp)
  return f?.result ? (winnerOf(f) ?? -1) : -1
}

function loserOf(f: Fixture | undefined): number {
  if (!f?.result) return -1
  const w = winnerOf(f)
  return w === f.home ? f.away : f.home
}

/** WCC の出場 8 クラブ */
export function wccQualifiers(state: GameState): { id: number; slot: string }[] {
  const find = (id: string) => state.competitions.find((c) => c.id === id)
  const acc = find(ACC_ID)
  const euc = find(EUC_ID)
  const out: { id: number; slot: string }[] = []
  const add = (id: number, slot: string) => {
    if (id >= 0 && state.clubs[id] && !out.some((o) => o.id === id) && out.length < 8) out.push({ id, slot })
  }
  // ワールドリーグ（M24）の優勝と 2 位
  const wl = leagueTop(state, 'WL', 2, true)
  add(wl[0] ?? -1, 'ワールドリーグ王者')
  add(wl[1] ?? -1, 'ワールドリーグ2位')
  add(championOf(euc), '欧州王者')
  add(championOf(acc), 'アジア王者')
  add(loserOf(finalOf(euc)), '欧州準優勝')
  add(loserOf(finalOf(acc)), 'アジア準優勝')
  const bra = leagueTop(state, 'BRA1', 4, true)
  add(bra[0], '南米王者')
  // 開催国枠: NPL1 優勝（出場済みなら 2 位）
  for (const id of leagueTop(state, 'NPL1', 4, true)) {
    if (!out.some((o) => o.id === id)) {
      add(id, '開催国代表')
      break
    }
  }
  // 欧州のベスト 4（格が上の方）、南米 2 位
  const sfLosers = (euc?.fixtures.filter((f) => f.round === 2) ?? []).map(loserOf).filter((x) => x >= 0).sort(byRep(state))
  add(sfLosers[0] ?? -1, '欧州ベスト4')
  add(bra[1], '南米2位')
  // 足りなければ欧州リーグの上位から
  for (const [id] of EUC_QUOTA) for (const c of leagueTop(state, id, 3, true)) add(c, '推薦')
  return out
}

function createWcc(state: GameState) {
  if (!state.competitions.some((c) => c.id === ASIA_ID)) return
  const q = wccQualifiers(state)
  if (q.length < 8) return
  const comp = newComp(state, WCC_ID, '世界クラブ選手権', 'WCC', q.map((x) => x.id), WCC_ROUND_NAMES, 0)
  // 同じ大陸の 1 位と 2 位は決勝まで当たらない。準決勝は 1 試合目と 3 試合目、2 試合目と 4 試合目の勝者（drawNext）
  const [eu1, as1, eu2, as2, sa1, host, eu3, sa2] = q.map((x) => x.id)
  const pairs: [number, number][] = [
    [eu1, sa2],
    [as1, eu3],
    [host, as2],
    [sa1, eu2],
  ]
  for (const [h, a] of pairs) addFixture(state, comp, 0, WCC_WEEKS[0], h, a)
  state.competitions.push(comp)
  const me = state.playerClubId
  if (comp.clubIds.includes(me)) {
    const slot = q.find((x) => x.id === me)?.slot
    state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'league', mine: true, text: `${state.clubs[me].name} が世界クラブ選手権に出場！（${slot}）` })
  }
}

/**
 * クラブがどこまで勝ち上がったか。
 * 戻り値の reach: ACC は 0 = グループ敗退・1 = 準々決勝・2 = 準決勝・3 = 準優勝・4 = 優勝、
 * WCC は 0 = 準々決勝・1 = 準決勝・2 = 準優勝・3 = 優勝。出ていなければ -1
 */
export function reachOf(comp: Competition, clubId: number): number {
  if (!comp.clubIds.includes(clubId)) return -1
  const ko = comp.fixtures.filter((f) => f.group === undefined && (f.home === clubId || f.away === clubId)).sort((a, b) => a.round - b.round)
  const base = comp.id === ACC_ID ? ACC_QF : 0
  const offset = comp.id === ACC_ID ? 1 : 0
  if (!ko.length) return 0
  const last = ko[ko.length - 1]
  const won = !!last.result && winnerOf(last) === clubId
  const final = comp.roundNames ? comp.roundNames.length - 1 : last.round
  return last.round - base + offset + (won && last.round === final ? 1 : 0)
}

const ACC_STAGE = ['グループ敗退', 'ベスト8', 'ベスト4', '準優勝', '優勝']
const WCC_STAGE = ['ベスト8', 'ベスト4', '準優勝', '優勝']

/** 自クラブの成績の文言 */
export function stageLabel(comp: Competition, reach: number): string {
  if (reach < 0) return '―'
  return (comp.id === ACC_ID ? ACC_STAGE : WCC_STAGE)[reach] ?? '―'
}

/**
 * シーズン末: 大陸大会の賞金と格の変化。自クラブの成績を返す。
 * 呼んだあとで decideQualifiers と片付けを行う
 */
export function settleContinental(state: GameState, absWeek: number): NonNullable<SeasonSummary['continental']> {
  const me = state.clubs[state.playerClubId]
  const out: NonNullable<SeasonSummary['continental']> = []
  for (const id of [ACC_ID, WCC_ID]) {
    const comp = state.competitions.find((c) => c.id === id)
    if (!comp) continue
    const prizes = id === ACC_ID ? ACC_PRIZE : WCC_PRIZE
    const reps = id === ACC_ID ? ACC_REP : WCC_REP
    for (const clubId of comp.clubIds) {
      const r = reachOf(comp, clubId)
      if (r < 0) continue
      const club = state.clubs[clubId]
      // 格が上がるのは自クラブと海外のクラブだけ（日本の AI クラブが毎年上がり続けると国内がインフレする）
      if (club.isPlayer || club.country !== 'JP') club.rep = Math.min(95, club.rep + (reps[r] ?? 0))
      if (club.isPlayer) {
        const prize = prizes[r] ?? 0
        me.budget += prize
        const last = state.finance[state.finance.length - 1]
        if (last) last.prize += prize
      }
    }
    const champ = championOf(comp)
    if (champ >= 0) state.news.push({ absWeek, category: 'league', mine: champ === me.id, text: `${comp.name}は ${state.clubs[champ].name} が優勝！` })
    const r = reachOf(comp, me.id)
    if (r >= 0) out.push({ compId: id, stage: stageLabel(comp, r), champion: champ })
  }
  const euc = state.competitions.find((c) => c.id === EUC_ID)
  const ec = championOf(euc)
  if (ec >= 0) state.news.push({ absWeek, category: 'league', text: `欧州チャンピオンズカップは ${state.clubs[ec].name} が優勝。` })
  // アジアのクラブの格は少し揺れる（毎年同じ顔ぶれにならないように）
  const rng = createRng(hashSeed(state.seed, state.season, 0xa5))
  for (const id of state.competitions.find((c) => c.id === ASIA_ID)?.clubIds ?? []) {
    const c = state.clubs[id]
    c.rep = Math.max(30, Math.min(85, c.rep + rng.normal(0, 1.5)))
  }
  return out
}

/** 大陸大会・世界大会の優勝クラブ（シーズンの記録用） */
export function continentalChampions(state: GameState): { compId: string; clubId: number }[] {
  return CONTINENTAL_IDS.flatMap((id) => {
    const c = championOf(state.competitions.find((x) => x.id === id))
    return c >= 0 ? [{ compId: id, clubId: c }] : []
  })
}
