/**
 * キャリアの 1 週間（advanceWeek の最初に呼ぶ）。
 *   過ごし方（練習・休養・自主トレ・おでかけ・取材）を反映し、チーム練習の経験点・給料・体力の回復・課題・オファーを進める。
 *   過ごし方が選ばれていなければ、おまかせ（autoAction）。
 */
import type { Rng } from '../core/prng'
import { ATTR_EXP, DATE_SPOT_BY_ID, GEN2_ABROAD, PLACE_BY_ID, PLAY_STYLE_BY_ID, TRAIN_MENU_BY_ID, TRAINING_PARTNERS_BY_REGION, CAST_BY_ID } from '../data/career'
import type { GameState } from '../models/game'
import type { ExpKind, PlaceId, PlayStyle, TrainMenu, WeekAction } from '../models/career'
import { EXP_KINDS } from '../models/career'
import { POSITION_DEFS, type Position } from '../data/positions'
import type { AttrKey } from '../data/attributes'
import { absWeekOf } from '../core/calendar'
import { rollInjury } from '../growth/training'
import { canMeet, canRomance, careerAge, castName, clamp, currentGen, placeById, placesFor, regionOf, report } from './core'
import { dateCandidates, doDate, spotOpen } from './dates'
import { addFocus, decayFocus, easyGrowth, gainExp } from './growth'
import { chatId, getEvent, nextEventFor, queueTalk, whoIsAt } from './events'
import { objectivesWeek } from './manager'
import { ALL_EVENTS } from './dialogue'
import { careerOffersWeek } from './offers'
import { doHobby, HOBBY_BY_ID, injuryRiskMul, lifeWeek, netWage, restBonus, trainMul } from './life'
import { familyWeek } from './family'
import { retireWeek } from './retire'
import { youthWeek } from './saga'

/** 過ごし方の表示名（おでかけ先の名前は、state があれば今の地域の言い方） */
export function actionLabel(a: WeekAction, state?: GameState): string {
  switch (a.kind) {
    case 'train':
      return TRAIN_MENU_BY_ID[a.menu].name
    case 'rest':
      return '休養'
    case 'selfTrain':
      return `自主トレ（${castName(state, a.partner) || '仲間'}）`
    case 'outing':
      return `おでかけ（${state ? placeById(state, a.place).name : (PLACE_BY_ID[a.place]?.name ?? '街')}）`
    case 'media':
      return '取材・ファンサービス'
    case 'hobby':
      return `趣味の時間（${HOBBY_BY_ID[a.hobby]?.name ?? '趣味'}）`
    case 'date':
      return `デート（${castName(state, a.who)}・${DATE_SPOT_BY_ID[a.spot]?.name ?? ''}）`
  }
}

/** 自主トレの相手になれる人（今の地域の仲間。会ったことのある人だけ誘える） */
export function trainingPartners(state: GameState): string[] {
  // 子どもの世代（M17）は、その世代の仲間
  if (currentGen(state) >= 2) {
    const r = regionOf(state)
    return r === 'JP' ? ['g2_friend', 'g2_rival', 'g2_captain'] : GEN2_ABROAD.filter((x) => x.region === r && x.kind !== 'heroine').map((x) => x.id)
  }
  return TRAINING_PARTNERS_BY_REGION[regionOf(state)]
}

/** おまかせの練習の既定（プレースタイルごと。得意な練習と、足りなくなりがちな系統を交互に） */
const DEFAULT_PLAN: Record<PlayStyle, TrainMenu[]> = {
  speedster: ['speed', 'passDribble'],
  technician: ['passDribble', 'speed'],
  striker: ['shoot', 'speed'],
  playmaker: ['tactics', 'passDribble'],
  defender: ['defense', 'strength'],
  keeper: ['gkSave', 'gkFeet'],
}

export function defaultTrainPlan(style: PlayStyle): TrainMenu[] {
  return DEFAULT_PLAN[style]
}

/** チーム練習の毎週の経験点（合計 13）: ポジションの能力の重み × 能力ごとの経験点の内訳で配る */
export function teamTrainingExp(pos: Position): Partial<Record<ExpKind, number>> {
  const need: Record<ExpKind, number> = { power: 0, speed: 0, tech: 0, tactics: 0, mental: 0 }
  for (const [k, w] of Object.entries(POSITION_DEFS[pos].weights) as [AttrKey, number][]) for (const [kind, r] of Object.entries(ATTR_EXP[k]) as [ExpKind, number][]) need[kind] += w * r
  const total = Object.values(need).reduce((a, b) => a + b, 0)
  const out: Partial<Record<ExpKind, number>> = {}
  // 半分は均等、半分はポジションの必要に合わせる
  for (const k of EXP_KINDS) out[k] = 13 * (0.5 / EXP_KINDS.length + (0.5 * need[k]) / total)
  return out
}

/** おまかせのときの練習の順番 */
export function trainPlanOf(state: GameState): TrainMenu[] {
  const c = state.career!
  return c.trainPlan?.length ? c.trainPlan : defaultTrainPlan(c.style)
}

/** おまかせの過ごし方: 疲れていれば休み、月に 1 回はおでかけ、あとは練習の順番どおり */
export function autoAction(state: GameState): WeekAction {
  const c = state.career!
  if (c.stamina < 35) return { kind: 'rest' }
  if (state.week % 4 === 2) return autoDate(state) ?? { kind: 'outing', place: bestPlace(state) }
  const plan = trainPlanOf(state)
  return { kind: 'train', menu: plan[absWeekOf(state.season, state.week) % plan.length] }
}

/**
 * おまかせのデート: 月 1 回のおでかけの週に、2 回に 1 回はデートにする。
 * 相手は恋人（いれば）か、いちばん仲の良い人。行き先は、一度デートした人なら好きな所、まだなら公園でピクニック
 */
export function autoDate(state: GameState): WeekAction | null {
  const c = state.career!
  if (Math.floor(absWeekOf(state.season, state.week) / 4) % 2 === 0) return null
  const cands = dateCandidates(state)
  if (!cands.length) return null
  const who = [...cands].sort((a, b) => (c.bonds[b]?.value ?? 0) - (c.bonds[a]?.value ?? 0))[0]
  const b = c.bonds[who]
  const likes = (CAST_BY_ID[who]?.likes ?? []).filter((sp) => spotOpen(state, sp))
  const spot = (b?.dates ?? 0) > 0 && likes.length ? likes[(b?.dates ?? 0) % likes.length] : 'picnic'
  return { kind: 'date', who, spot }
}

/** その人の出来事の数 */
function chainLength(who: string): number {
  return ALL_EVENTS.filter((e) => e.char === who && e.trigger === 'outing' && e.step !== undefined).length
}

/**
 * 会う理由のある人がいる場所: 出来事の進んでいない人がいる場所を優先する（ひとりに偏らないように）。
 * 次は、絆が足りなくて出来事が止まっている人（話して仲良くなる）、まだ会っていない人。それもなければクラブハウス
 */
export function bestPlace(state: GameState): PlaceId {
  const c = state.career!
  const doneOf = (who: string) => Object.keys(c.done).filter((id) => getEvent(id)?.char === who).length
  let best: PlaceId = 'clubhouse'
  let bestScore = 0
  for (const pl of placesFor(state)) {
    let score = 0
    for (const who of pl.people) {
      if (!CAST_BY_ID[who] || !canMeet(state, who)) continue
      const done = doneOf(who)
      // 恋愛が進められるヒロインを先に（国を移ると会える期間が短いので）
      const romance = canRomance(state, who) && !(c.partner && c.partner !== who)
      if (nextEventFor(state, who)) score = Math.max(score, 10 - done + (romance ? 2 : -2))
      // 次の出来事が絆待ちでも、恋愛が進められるヒロインには会いに行く（会うと絆が上がる）
      else if (romance && !c.partner && done < chainLength(who)) score = Math.max(score, 8 - done * 0.3)
      else if (!c.bonds[who]) score = Math.max(score, 3)
      else if (done < chainLength(who)) score = Math.max(score, 4 - done * 0.5)
    }
    if (score > bestScore) {
      bestScore = score
      best = pl.id
    }
  }
  return best
}

export function careerWeek(state: GameState, rng: Rng) {
  const c = state.career!
  if (c.retired) return
  const p = state.players[c.playerId]
  const action = c.action ?? autoAction(state)
  c.action = undefined
  const condMul = 0.85 + (p.condition / 100) * 0.3
  decayFocus(state)
  if (action.kind === 'train') {
    const m = TRAIN_MENU_BY_ID[action.menu]
    const fav = PLAY_STYLE_BY_ID[c.style].favorite === action.menu ? 1.2 : 1
    gainExp(state, m.exp, fav * condMul * trainMul(state))
    addFocus(state, m.attrs)
    c.stamina -= m.stamina
    c.trust = clamp(c.trust + 0.3, 0, 100)
    // 疲れたまま練習するとケガをすることがある
    if (c.stamina < 25 && !p.injury && rng.chance(((25 - c.stamina) / 120) * injuryRiskMul(state))) {
      p.injury = rollInjury(rng, state.clubs[p.clubId]?.facilities.medical ?? 0, false)
      report(state, `練習中に${p.injury.name}をしてしまった（全治 ${p.injury.weeks} 週）。`)
    }
  } else if (action.kind === 'rest') {
    c.stamina += 35 + restBonus(state)
    p.condition = clamp(p.condition + 6, 0, 100)
  } else if (action.kind === 'selfTrain') {
    const bond = c.bonds[action.partner]?.value ?? 0
    gainExp(state, { power: 8, speed: 8, tech: 8, tactics: 4 }, (1 + bond / 150) * condMul)
    addFocus(state, ['speed', 'strength', 'dribble', 'shoot'], 0.5)
    c.stamina -= 14
    const b = (c.bonds[action.partner] ??= { value: 0, lastAbsWeek: 0 })
    b.value = clamp(b.value + 4, 0, 100)
    report(state, `${castName(state, action.partner) ?? '仲間'}と自主トレをした。`)
  } else if (action.kind === 'outing') {
    const place = placeById(state, action.place)
    c.stamina += place.stamina
    if (place.exp) gainExp(state, place.exp)
    const who = whoIsAt(state, place.people, rng.next())
    if (who) {
      const ev = nextEventFor(state, who)
      const id = ev?.id ?? chatId(who, rng.next())
      if (id) queueTalk(state, id)
      report(state, `${place.name}で${castName(state, who) ?? '知り合い'}に会った。`)
    }
  } else if (action.kind === 'date') {
    doDate(state, action.who, action.spot)
  } else if (action.kind === 'hobby') {
    doHobby(state, action.hobby)
  } else if (action.kind === 'media') {
    c.fame = clamp(c.fame + (c.fame < 30 ? 3 : 2), 0, 100)
    gainExp(state, { mental: 5 })
    c.stamina -= 4
    report(state, '取材とファンサービスで、名前が少し知られた。')
  }
  // ユース期（M17）: チームの練習・試合・大会。プロの給料・課題・オファー・くらしはない
  if (c.saga?.phase === 'youth') {
    youthWeek(state)
    if (c.stamina < 30) p.condition = clamp(p.condition - 4, 0, 100)
    easyGrowth(state)
    familyWeek(state, rng)
    return
  }
  // チーム練習（毎週）: ポジションに合わせた内容（必要な経験点の種類に合わせて 13 を配る）
  gainExp(state, teamTrainingExp(p.pos), condMul)
  // 体力の自然な回復と、疲れの影響
  c.stamina = clamp(c.stamina + 8, 0, 100)
  if (c.stamina < 30) p.condition = clamp(p.condition - 4, 0, 100)
  // 給料（週割り）。税金と代理人の手数料を引いた手取り
  c.money += Math.round(netWage(p.contract.wage) / 48)
  // 長いケガ（12 週以上）をしたら、再起の道を選ぶ出来事（一度きり。21 歳から）
  if (p.injury && p.injury.weeks >= 12 && careerAge(state) >= 21 && c.done.gt_injury === undefined && !c.talks.some((t) => t.eventId === 'gt_injury')) queueTalk(state, 'gt_injury')
  // 簡単モード: 練習した能力が自動で上がる
  easyGrowth(state)
  objectivesWeek(state)
  careerOffersWeek(state, rng)
  // くらし・家族・引退の話
  lifeWeek(state)
  familyWeek(state, rng)
  retireWeek(state)
}
