/**
 * 施設の建設・拡張とスタジアムの増築。工事は同時に施設 1 件・スタジアム 1 件まで。
 * 費用は着工時に払い、完成の週に効果が出る。維持費はレベルとともに上がる（finance.ts）。
 */
import { absWeekOf } from '../core/calendar'
import { FACILITY_LABEL, type Club, type Construction, type FacilityId } from '../models/club'
import type { GameState } from '../models/game'
import { DOMESTIC_GRADE, WORLD_FACILITY, WORLD_GRADE, capacityMax, facilityMax, gradeMax, inWorld } from '../club/worldClass'

export const MAX_FACILITY = 5

export const FACILITY_EFFECT: Record<FacilityId, string> = {
  training: '全選手の成長が速くなる',
  medical: 'ケガが減り、治りが早くなる。疲労も抜けやすい',
  dorm: '若手（22 歳以下）の成長が速くなる',
  analysis: '試合で相手の弱点を突ける（チーム全体が少し強くなる）',
  youth: 'ユースから上がる若手の人数と質が上がる',
  pr: '人気とサポーターが増えやすくなり、スポンサー収入も上がる',
  lodge: '国内の合宿の効果が上がり、費用が安くなる',
  scoutOffice: 'スカウトの精度と、見つけられる選手が増える',
}

/** Lv6〜8 は世界水準（ワールドリーグで開く。費用は 1.6 倍） */
export function facilityCost(level: number): number {
  return Math.round(3000 * level ** 1.5 * (level > MAX_FACILITY ? 1.6 : 1))
}

export function facilityWeeks(level: number): number {
  return 4 + level * 2
}

export interface StadiumPlan {
  target: 'seats' | 'grade'
  label: string
  amount: number
  cost: number
  weeks: number
}

export function stadiumPlans(club: Club): StadiumPlan[] {
  const out: StadiumPlan[] = [
    { target: 'seats', label: '客席を 3,000 席増やす', amount: 3000, cost: 12000, weeks: 10 },
    { target: 'seats', label: '客席を 8,000 席増やす', amount: 8000, cost: 34000, weeks: 20 },
    { target: 'seats', label: '客席を 15,000 席増やす', amount: 15000, cost: 70000, weeks: 32 },
  ]
  // ワールドリーグ（M24 の 2 回目）: 10 万人まで・グレード 7 まで
  if (inWorld(club)) out.push({ target: 'seats', label: '客席を 20,000 席増やす（世界水準のスタジアム）', amount: 20000, cost: 100000, weeks: 40 })
  const g = club.stadium.grade
  if (g < gradeMax(club)) out.push({ target: 'grade', label: `設備を改装（グレード ${g} → ${g + 1}${g >= DOMESTIC_GRADE ? '・世界水準' : ''}）`, amount: 1, cost: (g >= DOMESTIC_GRADE ? 30000 : 15000) * g, weeks: g >= DOMESTIC_GRADE ? 24 : 16 })
  return out.filter((p) => p.target === 'grade' || club.stadium.capacity + p.amount <= capacityMax(club))
}

export function busy(club: Club, kind: Construction['kind']): Construction | undefined {
  return (club.construction ?? []).find((c) => c.kind === kind)
}

export function canBuildFacility(club: Club, f: FacilityId): { ok: boolean; reason?: string } {
  if (club.facilities[f] >= WORLD_FACILITY) return { ok: false, reason: '最大レベル' }
  if (club.facilities[f] >= facilityMax(club)) return { ok: false, reason: 'Lv6 からはワールドリーグで' }
  if (busy(club, 'facility')) return { ok: false, reason: 'ほかの施設を工事中' }
  const cost = facilityCost(club.facilities[f] + 1)
  if (club.budget < cost) return { ok: false, reason: '資金が足りない' }
  return { ok: true }
}

export function startFacility(state: GameState, club: Club, f: FacilityId): boolean {
  if (!canBuildFacility(club, f).ok) return false
  const lv = club.facilities[f] + 1
  const cost = facilityCost(lv)
  club.budget -= cost
  const now = absWeekOf(state.season, state.week)
  ;(club.construction ??= []).push({ kind: 'facility', target: f, label: `${FACILITY_LABEL[f]} Lv${lv}`, doneAbsWeek: now + facilityWeeks(lv), cost, amount: 1 })
  recordCost(state, club, cost)
  return true
}

export function startStadium(state: GameState, club: Club, plan: StadiumPlan): boolean {
  if (busy(club, 'stadium') || club.budget < plan.cost) return false
  club.budget -= plan.cost
  const now = absWeekOf(state.season, state.week)
  ;(club.construction ??= []).push({ kind: 'stadium', target: plan.target, label: plan.label, doneAbsWeek: now + plan.weeks, cost: plan.cost, amount: plan.amount })
  recordCost(state, club, plan.cost)
  return true
}

/** 工事・出店の費用をその週の帳簿に付ける */
export function recordCost(state: GameState, club: Club, cost: number) {
  if (!club.isPlayer) return
  const w = state.finance[state.finance.length - 1]
  if (w && w.absWeek === absWeekOf(state.season, state.week) - 1) w.construction += cost
}

/** 完成した工事を反映（週の処理で呼ぶ） */
export function completeConstruction(state: GameState, absWeek: number) {
  for (const club of state.clubs) {
    if (!club.construction?.length) continue
    const done = club.construction.filter((c) => c.doneAbsWeek <= absWeek)
    if (!done.length) continue
    for (const c of done) {
      if (c.kind === 'facility') club.facilities[c.target as FacilityId] = Math.min(WORLD_FACILITY, club.facilities[c.target as FacilityId] + 1)
      else if (c.target === 'seats') club.stadium.capacity += c.amount
      else club.stadium.grade = Math.min(WORLD_GRADE, club.stadium.grade + c.amount)
      if (club.isPlayer) state.news.push({ absWeek, category: 'club', mine: true, text: `${c.label}の工事が完成しました！` })
    }
    club.construction = club.construction.filter((c) => c.doneAbsWeek > absWeek)
  }
}
