/**
 * デート（M10）: 仲良くなったヒロインを誘い、行き先を選ぶ。
 *   誘える人: 恋愛が進められる大人どうしで（canRomance）、今の地域で会え、絆 30 以上。
 *            恋人・結婚相手がいるときは、その人だけ（恋人は 1 人だけの決まり）
 *   効果: 費用・経験点・調子・体力・知名度は行き先ごと。好きな行き先なら絆と経験点が 1.6 倍、
 *         同じ趣味（HOBBY_FOR_TRAIT）があると絆が少し多く上がる
 *   会話: date:<人>:<行き先>:<好き 1/0>:<回数> を予約し、events.ts の getEvent がその場で組み立てる
 *   そのあと、その人の次の出来事が起きる絆に届いていれば、続けて予約する
 */
import { absWeekOf } from '../core/calendar'
import { CAST_BY_ID, DATE_MIN_BOND, DATE_SPOT_BY_ID, HOBBY_FOR_TRAIT } from '../data/career'
import type { GameState } from '../models/game'
import type { DateSpotId } from '../models/career'
import { canMeet, canRomance, castName, clamp, report } from './core'
import { gainExp } from './growth'
import { nextEventFor, queueTalk } from './events'
import { partnerId } from './family'
import { hobbySkill } from './life'
import { hasCar, mainCarOf } from './homes'

export function canDate(state: GameState, who: string): { ok: boolean; reason?: string } {
  const c = state.career!
  const cast = CAST_BY_ID[who]
  if (!cast || cast.kind !== 'heroine' || !canRomance(state, who)) return { ok: false, reason: '誘えない' }
  if (!canMeet(state, who)) return { ok: false, reason: 'いまは会えない' }
  const pid = partnerId(state)
  if (pid) return pid === who ? { ok: true } : { ok: false, reason: '恋人がいる' }
  if ((c.bonds[who]?.value ?? 0) < DATE_MIN_BOND) return { ok: false, reason: `絆 ${DATE_MIN_BOND} から` }
  return { ok: true }
}

/** 今、デートに誘える人 */
export function dateCandidates(state: GameState): string[] {
  return Object.values(CAST_BY_ID).filter((x) => canDate(state, x.id).ok).map((x) => x.id)
}

/** その人と同じ趣味を続けているか（腕前 10 以上） */
export function sharedHobby(state: GameState, who: string): boolean {
  const trait = CAST_BY_ID[who]?.trait
  return !!trait && HOBBY_FOR_TRAIT[trait].some((h) => hobbySkill(state, h) >= 10)
}

export function likesSpot(who: string, spot: DateSpotId): boolean {
  return CAST_BY_ID[who]?.likes?.includes(spot) ?? false
}

/** その行き先に行けるか（ドライブは車があるときだけ） */
export function spotOpen(state: GameState, spot: DateSpotId): boolean {
  return !DATE_SPOT_BY_ID[spot].needCar || hasCar(state)
}

/** スポーツカー・クラシックカー・スーパーカーでのドライブは、好きな行き先と同じくらい喜ばれる */
function fancyDrive(state: GameState, spot: DateSpotId): boolean {
  const car = mainCarOf(state)
  return spot === 'drive' && (car === 'sports' || car === 'classic' || car === 'supercar')
}

/** デートの効果を反映して、会話を予約する */
export function doDate(state: GameState, who: string, spot: DateSpotId) {
  const c = state.career!
  const p = state.players[c.playerId]
  // 車を手放していたら、ピクニックにする
  if (!spotOpen(state, spot)) spot = 'picnic'
  const def = DATE_SPOT_BY_ID[spot]
  if (!canDate(state, who).ok) {
    // 誘えなくなっていたら、ひとりで休む
    c.stamina += 20
    return
  }
  const like = likesSpot(who, spot) || fancyDrive(state, spot)
  const mul = like ? 1.6 : 1
  const now = absWeekOf(state.season, state.week)
  c.money -= Math.min(def.cost, Math.max(0, c.money))
  const b = (c.bonds[who] ??= { value: 0, lastAbsWeek: now })
  b.value = clamp(b.value + Math.round((6 + (sharedHobby(state, who) ? 2 : 0)) * mul), 0, 100)
  b.lastAbsWeek = now
  b.dates = (b.dates ?? 0) + 1
  if (def.exp) gainExp(state, def.exp, mul)
  p.condition = clamp(p.condition + def.condition, 0, 100)
  c.stamina += def.stamina
  if (def.fame) c.fame = clamp(c.fame + def.fame, 0, 100)
  queueTalk(state, `date:${who}:${spot}:${like ? 1 : 0}:${b.dates}`)
  report(state, `${castName(state, who) ?? ''}と${def.name}へ出かけた${like ? '（とても喜んでくれた）' : ''}。`)
  // 次の出来事が起きる絆に届いていれば、そのまま
  const ev = nextEventFor(state, who)
  if (ev) queueTalk(state, ev.id)
}
