/**
 * キャリアのシーズン末（processSeasonEnd から、個人成績を履歴に移す前に呼ぶ）。
 * 1 シーズンの記録・タイトル・表彰を残し、契約が切れるなら行き先を決め、振り返りの会話を予約する。
 */
import type { GameState } from '../models/game'
import { ovr } from '../player/overall'
import { AWARD_LABEL } from '../competition/awards'
import { careerAge, clamp } from './core'
import { queueTalk } from './events'
import { settleExpiringContract } from './offers'
import { retireAtSeasonEnd } from './retire'
import { lifeSeasonEnd } from './life'
import { clubRank } from './rank'
import { youthSeasonEnd } from './saga'

/** シーズン末: 年齢と活躍・ケアへの投資で、成長タイプが変わる出来事をひとつ予約する（どれも一度きり） */
function growthTypeEvent(state: GameState) {
  const c = state.career!
  const p = state.players[c.playerId]
  const age = careerAge(state)
  const type = p.growth
  const rating = p.stats.apps ? p.stats.ratingSum / p.stats.apps : 0
  const once = (id: string) => c.done[id] === undefined && !c.talks.some((t) => t.eventId === id)
  const careInvest = (c.services ?? []).some((x) => x === 'physio' || x === 'trainer' || x === 'chef') || (c.homeGear?.sauna ?? 0) > 0 || (c.homeGear?.yogaRoom ?? 0) > 0
  if (age >= 19 && age <= 21 && ['normal', 'late', 'ultraLate'].includes(type) && p.stats.apps >= 15 && rating >= 6.8 && once('gt_bloom')) queueTalk(state, 'gt_bloom')
  else if (age >= 24 && age <= 27 && ['ultraEarly', 'early', 'normal'].includes(type) && (c.trust >= 60 || rating >= 7) && once('gt_awaken')) queueTalk(state, 'gt_awaken')
  else if (age >= 27 && age <= 31 && type !== 'ultraLate' && careInvest && once('gt_care')) queueTalk(state, 'gt_care')
}

const COMP_TITLE: Record<string, string> = { CUP: 'ナショナルカップ優勝', ACC: 'アジアクラブカップ優勝', WCC: '世界クラブ選手権優勝', EUC: '欧州チャンピオンズカップ優勝' }

export function careerSeasonEnd(state: GameState) {
  const c = state.career!
  if (c.retired) return
  // ユース期（M17）: 学年が上がる・卒業してプロの入団の話
  if (c.saga?.phase === 'youth') return youthSeasonEnd(state)
  const p = state.players[c.playerId]
  const summary = state.seasons[state.seasons.length - 1]
  const titles: string[] = []
  // チームのタイトルは、そのシーズンに 5 試合以上出ていれば自分のものに数える
  for (const ch of summary?.champions ?? []) {
    if (ch.clubId !== p.clubId || p.stats.apps < 5) continue
    const comp = state.competitions.find((x) => x.id === ch.compId)
    titles.push(COMP_TITLE[ch.compId] ?? `${comp?.name ?? ch.compId} 優勝`)
  }
  const leagueName = (id: string) => state.competitions.find((x) => x.id === id)?.name ?? ''
  for (const a of summary?.awards ?? []) if (a.playerId === p.id) titles.push(a.key === 'world' ? 'ピッチクラウン賞（世界最優秀選手）' : `${leagueName(a.compId)} ${AWARD_LABEL[a.key]}`)
  for (const [compId, list] of Object.entries(summary?.bestEleven ?? {})) if (list.some((x) => x.playerId === p.id)) titles.push(`${leagueName(compId)} ベストイレブン`)
  const worldRank = (summary?.worldRanking ?? []).findIndex((r) => r.playerId === p.id) + 1
  c.fame = clamp(c.fame + titles.length * 4 + (worldRank === 1 ? 10 : worldRank ? 3 : 0), 0, 100)
  // 年間表彰式（キャリアのホームで見せる）
  c.ceremony = { season: state.season }
  c.log.push({
    season: state.season,
    clubId: p.clubId,
    leagueId: state.clubs[p.clubId]?.leagueId ?? '',
    apps: p.stats.apps,
    goals: p.stats.goals,
    assists: p.stats.assists,
    rating: p.stats.apps ? Math.round((p.stats.ratingSum / p.stats.apps) * 100) / 100 : 0,
    ovr: ovr(p),
    wage: p.contract.wage,
    titles,
    rank: clubRank(state, state.clubs[p.clubId])?.step,
    worldRank: worldRank || undefined,
  })
  // くらし: スポンサーの目標のボーナス・オフの自主トレ合宿・事業の決算
  lifeSeasonEnd(state)
  // 成長タイプが変わる出来事（ひとつだけ）
  growthTypeEvent(state)
  // 引退（今季限りと決めていた・年齢・行き先がない）
  if (retireAtSeasonEnd(state)) return
  settleExpiringContract(state)
  c.wantsMove = false
  queueTalk(state, 'sys_seasonEnd')
}
