/**
 * 監督の評価と課題（FC キャリア風）。
 *   評価 0-100: 先発の選考に効く（selectionBonus）。試合の評価点・課題の達成・練習の姿勢で上下する
 *   課題: 2 か月ごとに 1〜2 個（得点・アシスト・好評価の試合・出場・無失点）
 */
import { absWeekOf } from '../core/calendar'
import { POSITION_DEFS } from '../data/positions'
import type { GameState } from '../models/game'
import type { Objective } from '../models/career'
import { clamp, report } from './core'

/** 先発選考の点に掛ける倍率（評価 50 で 1.0、100 で 1.1、0 で 0.9） */
export function selectionBonus(trust: number): number {
  return 0.9 + (trust / 100) * 0.2
}

export type CareerStatus = 'key' | 'regular' | 'rotation' | 'fringe'
export const STATUS_LABEL: Record<CareerStatus, string> = { key: '主力', regular: 'レギュラー', rotation: '控え', fringe: '構想外' }

/** 今の立場（直近の先発の状況と評価から） */
export function careerStatus(state: GameState): CareerStatus {
  const c = state.career!
  const club = state.clubs[state.playerClubId]
  const starter = club?.lineup.starters.includes(c.playerId)
  const bench = club?.lineup.bench.includes(c.playerId)
  if (starter && c.trust >= 65) return 'key'
  if (starter) return 'regular'
  if (bench || c.trust >= 35) return 'rotation'
  return 'fringe'
}

const OBJ_LABEL: Record<Objective['kind'], (n: number) => string> = {
  goals: (n) => `${n} 得点`,
  assists: (n) => `${n} アシスト`,
  goodGames: (n) => `評価点 7.0 以上を ${n} 試合`,
  apps: (n) => `${n} 試合に出場`,
  cleanSheets: (n) => `無失点に抑えた試合に ${n} 回出場`,
}

export function objectiveLabel(o: Objective): string {
  return OBJ_LABEL[o.kind](o.target)
}

/** 新しい課題（ポジションと立場に合わせる） */
export function newObjectives(state: GameState) {
  const c = state.career!
  const p = state.players[c.playerId]
  const line = POSITION_DEFS[p.pos].line
  const now = absWeekOf(state.season, state.week)
  const until = now + 8
  const status = careerStatus(state)
  const list: Omit<Objective, 'id' | 'progress' | 'untilAbsWeek'>[] = []
  if (status === 'fringe' || status === 'rotation') list.push({ kind: 'apps', target: 2 })
  if (line === 'FW') list.push({ kind: 'goals', target: status === 'key' ? 3 : 2 })
  else if (line === 'MF') list.push(p.pos === 'DM' ? { kind: 'goodGames', target: 2 } : { kind: 'assists', target: 2 })
  else if (line === 'DF' || line === 'GK') list.push({ kind: 'cleanSheets', target: 2 })
  if (list.length < 2) list.push({ kind: 'goodGames', target: 2 })
  c.objectives = list.slice(0, 2).map((o) => ({ ...o, id: c.nextObjectiveId++, progress: 0, untilAbsWeek: until }))
}

/** 試合の結果を課題に数える */
export function countObjectives(state: GameState, played: boolean, goals: number, assists: number, rating: number, cleanSheet: boolean) {
  const c = state.career!
  for (const o of c.objectives) {
    if (o.kind === 'goals') o.progress += goals
    else if (o.kind === 'assists') o.progress += assists
    else if (o.kind === 'goodGames' && played && rating >= 7) o.progress++
    else if (o.kind === 'apps' && played) o.progress++
    else if (o.kind === 'cleanSheets' && played && cleanSheet) o.progress++
  }
}

/** 週ごと: 達成した課題・期限切れの課題を片付ける。全部片付いたら次の課題 */
export function objectivesWeek(state: GameState) {
  const c = state.career!
  const now = absWeekOf(state.season, state.week)
  const keep = []
  for (const o of c.objectives) {
    if (o.progress >= o.target) {
      c.trust = clamp(c.trust + 6, 0, 100)
      c.exp.mental += 10
      report(state, `監督の課題「${objectiveLabel(o)}」を達成！ 評価が上がった。`)
    } else if (now > o.untilAbsWeek) {
      c.trust = clamp(c.trust - 3, 0, 100)
      report(state, `監督の課題「${objectiveLabel(o)}」は達成できなかった。`)
    } else keep.push(o)
  }
  c.objectives = keep
  if (!keep.length && state.playerClubId >= 0 && state.players[c.playerId]?.clubId === state.playerClubId) newObjectives(state)
}
