/**
 * 2D リアルタイム試合エンジン（LiveSim）の本体。
 * 10Hz の固定ステップで 22 人とボールを動かす。パス・シュートなどの結果は放つ瞬間に確率で決め（resolve.ts）、
 * ボールの軌道と選手の動きをその結果に合わせる。チームの陣形と判断は brain.ts。
 */
import { createRng, type Rng } from '../../core/prng'
import { formationBalance, formationOf, type Formation } from '../../data/formations'
import { ATTR_KEYS, type Attrs } from '../../data/attributes'
import { rawRating } from '../../player/overall'
import type { Tactics } from '../../models/club'
import { fillText } from '../../data/commentary'
import {
  CLOCK_SCALE,
  DT,
  GOAL_H,
  GOAL_W,
  HALF_SECONDS,
  TIME_K,
  PITCH_H,
  PITCH_W,
  BOX_DEPTH,
  BOX_WIDTH,
  type MatchCommand,
  type MatchEvent,
  type MatchEventType,
  type MatchPlayerSetup,
  type MatchSetup,
  type MatchSummary,
  type PlayerMatchStats,
  type TeamSetup,
  type TeamStats,
} from './types'
import { aerialScore, clamp, foulProb, onTargetProb, passRisk, shotXg, tackleWinProb, type Defender } from './resolve'
import { decideCarrier, setPieceTargets, updateShape } from './brain'

export interface Body {
  idx: number
  team: 0 | 1
  /** フォーメーションのスロット番号（ピッチ上のとき） */
  slot: number
  s: MatchPlayerSetup
  gk: boolean
  x: number
  y: number
  px: number
  py: number
  vx: number
  vy: number
  /** 移動の目標と、目標へ向かう速さの割合（0-1） */
  tx: number
  ty: number
  urgency: number
  stamina: number
  /** ボール保持者の次の判断までの秒数 */
  decideIn: number
  /** 抜かれた・倒れたなどで動けない秒数 */
  stun: number
  tackleCd: number
  /** 前線への走り込みの残り秒数 */
  runT: number
  yellow: number
  onPitch: boolean
  st: PlayerMatchStats
  /** 評価点の加点（試合後に 6.0 に足す） */
  rate: number
  /** ドリブルの目標（保持者のとき） */
  dribX: number
  dribY: number
}

export interface TeamRT {
  side: 0 | 1
  setup: TeamSetup
  /** +1 = 右のゴールを攻める */
  dir: 1 | -1
  formation: Formation
  tactics: Tactics
  /** スロット順のピッチ上の選手（退場で抜けたスロットは -1） */
  slots: number[]
  bench: MatchPlayerSetup[]
  subsUsed: number
  subWindows: number
  pendingSubs: { out: number; in: number }[]
  stats: TeamStats
  /** スコアに応じて AI が変えた戦術の段階 */
  aiMentalityShift: number
  /** 観戦中にプレイヤーが交代・作戦を指示した（以後は AI 監督が手を出さない） */
  manual: boolean
}

export type FlightKind = 'pass' | 'long' | 'cross' | 'shot' | 'clear' | 'throw'
export type FlightOutcome = 'ok' | 'intercept' | 'astray' | 'goal' | 'save' | 'miss' | 'post' | 'block' | 'aerialAtk' | 'aerialDef' | 'free'

export interface Flight {
  kind: FlightKind
  from: number
  team: 0 | 1
  /** 到着時にボールを受ける選手（-1 = 誰でも） */
  resolver: number
  rx: number
  ry: number
  outcome: FlightOutcome
  intended: number
  xg?: number
  header?: boolean
  penalty?: boolean
  offside?: boolean
  elapsed: number
  maxT: number
}

export type RestartKind = 'kickoff' | 'throw' | 'goalkick' | 'corner' | 'freekick' | 'penalty'

export interface Restart {
  kind: RestartKind
  team: 0 | 1
  x: number
  y: number
  taker: number
  wait: number
  /** 待ちが長引いたときの保険 */
  timeout: number
}

export interface Ball {
  x: number
  y: number
  z: number
  vx: number
  vy: number
  vz: number
  px: number
  py: number
  pz: number
  owner: number
  lastTouch: number
  flight: Flight | null
  /** 直前にボールに触れた選手が再び触れない秒数（こぼれ球の取り合い用） */
  noTouch: number
  noTouchIdx: number
}

/** 転がるボールの減速（m/s²）: 転がり抵抗 + 空気抵抗 */
function rollDecel(v: number): number {
  return 1.6 + 0.012 * v * v
}

/** 初速 v0 で転がったときの距離の表（パスの強さを決める） */
const ROLL_TABLE: number[] = (() => {
  const out: number[] = []
  for (let i = 0; i <= 80; i++) {
    let v = i * 0.5
    let d = 0
    while (v > 0.3) {
      d += v * DT
      v -= rollDecel(v) * DT
    }
    out.push(d)
  }
  return out
})()

/** グラウンダーのパスの平均速度の目安 */
export function groundAvgSpeed(d: number): number {
  return clamp(9.5 + d * 0.12, 9.5, 16)
}

/** 距離 d を転がって到着時に va 程度の速さになる初速 */
export function groundSpeedFor(d: number, va: number): number {
  const want = d + ROLL_TABLE[Math.min(80, Math.round(va * 2))]
  for (let i = 1; i <= 80; i++) if (ROLL_TABLE[i] >= want) return i * 0.5
  return 40
}

const dist = (ax: number, ay: number, bx: number, by: number) => Math.hypot(ax - bx, ay - by)

function emptyTeamStats(): TeamStats {
  return { goals: 0, shots: 0, onTarget: 0, xg: 0, passes: 0, passesOk: 0, possession: 0, fouls: 0, corners: 0, offsides: 0, yellows: 0, reds: 0, saves: 0 }
}

/**
 * 試合の水準そろえ: 両チームの先発の平均（ポジション別の総合値）が基準より高い／低いぶん、
 * 試合中だけ全員の能力を同じだけずらす。チーム間の差はそのまま残る。
 * 能力の絶対値で決まる部分（パスミス・ミドルを狙う頻度など）のせいで、
 * 上位リーグほど点が入り下位ほど入らない偏りが出るのを抑える。
 */
export const LEVEL_REF = 62
const LEVEL_KEEP = 0.2

export function levelShiftOf(setup: MatchSetup): number {
  const all = [...setup.home.starters, ...setup.away.starters]
  if (!all.length) return 0
  const lv = all.reduce((s, p) => s + rawRating(p.attr, p.pos), 0) / all.length
  return (LEVEL_REF - lv) * (1 - LEVEL_KEEP)
}

function shiftAttrs(a: Attrs, d: number): Attrs {
  const out = {} as Attrs
  for (const k of ATTR_KEYS) out[k] = clamp(a[k] + d, 1, 99)
  return out
}

/** キャリア: 主人公の見せ場の選択肢 */
export interface MomentChoice {
  kind: 'shoot' | 'pass' | 'cross' | 'dribble' | 'hold' | 'tackle' | 'contain' | 'rush' | 'stay'
  label: string
  /** 成功の見込み 0-1（画面では ◎○△） */
  prob: number
  util: number
  run: () => void
}

/** 画面に出す見せ場（選ぶまで試合は止まる） */
export interface Moment {
  type: 'attack' | 'defend' | 'keeper'
  title: string
  choices: { kind: MomentChoice['kind']; label: string; prob: number }[]
}

/** 1 試合の見せ場の上限と間隔（シミュレーション秒） */
const MAX_MOMENTS = 6
const MOMENT_GAP = 200 / TIME_K

/** フォーメーションの補正を掛けたチーム（先発と控えの能力） */
function withFormationBalance(t: TeamSetup): TeamSetup {
  const k = formationBalance(t.formation)
  if (k === 1) return t
  const scale = (p: MatchPlayerSetup): MatchPlayerSetup => ({ ...p, attr: Object.fromEntries(Object.entries(p.attr).map(([a, v]) => [a, Math.min(99, v * k)])) as MatchPlayerSetup['attr'] })
  return { ...t, starters: t.starters.map(scale), bench: t.bench.map(scale) }
}

export class LiveMatch {
  readonly setup: MatchSetup
  /** 試合中だけ能力に足す値（水準そろえ） */
  readonly levelShift: number
  readonly rng: Rng
  readonly headless: boolean
  bodies: Body[] = []
  teams: [TeamRT, TeamRT]
  ball: Ball
  /** 試合開始からのシミュレーション秒 */
  t = 0
  tick = 0
  /** 1, 2 = 前後半、3, 4 = 延長 */
  half = 1
  halfT = 0
  halfLen = HALF_SECONDS
  /** ロスタイム（表示の分） */
  added = 0
  score: [number, number] = [0, 0]
  possTeam: 0 | 1 = 0
  mode: 'play' | 'restart' | 'over' = 'restart'
  restart: Restart | null = null
  events: MatchEvent[] = []
  finished = false
  pens?: [number, number]
  et = false
  /** 直前にパスを出した選手（アシストの判定用） */
  lastPass: { idx: number; t: number } = { idx: -1, t: -99 }
  /** 前半のキックオフをしたチーム */
  private firstKick: 0 | 1
  private stopCount = 0
  /** 調整用の集計（判断の種類・ボール位置・ボールを失った理由） */
  dbg: Record<string, number> = {}
  count(key: string, n = 1) {
    this.dbg[key] = (this.dbg[key] ?? 0) + n
  }
  /** 描画用: 直近に何かが起きた（演出のトリガー） */
  flash: { kind: 'goal' | 'save' | 'post' | 'card' | 'whistle'; t: number; team: 0 | 1 } | null = null

  // ---- キャリア: 主人公（focus）の見せ場 ----
  /** 追いかける選手の id（-1 = なし） */
  readonly focusId: number
  /** 見せ場で止めて選ばせる（false なら自動で選ぶ） */
  interactive: boolean
  /** 選ぶのを待っている見せ場（あいだは step() が進まない） */
  pendingMoment: Moment | null = null
  private momentChoices: MomentChoice[] = []
  private momentType: Moment['type'] = 'attack'
  /** 見せ場の結果 */
  momentLog: { label: string; ok: boolean }[] = []
  private nextMomentT = 45 / TIME_K
  /** 結果を見届ける見せ場（ドリブル・守備・GK） */
  private momentWatch: { kind: MomentChoice['kind']; label: string; until: number; team: 0 | 1 } | null = null

  constructor(setup: MatchSetup, opts: { headless?: boolean; focus?: number; interactive?: boolean } = {}) {
    // フォーメーションの補正は LiveSim だけ（試合エンジンの癖を打ち消すため。FastSim には掛けない）
    setup = { ...setup, home: withFormationBalance(setup.home), away: withFormationBalance(setup.away) }
    this.setup = setup
    this.headless = opts.headless ?? false
    this.focusId = opts.focus ?? -1
    this.interactive = !!opts.interactive
    this.rng = createRng(setup.seed)
    this.levelShift = levelShiftOf(setup)
    this.teams = [this.makeTeam(0, setup.home), this.makeTeam(1, setup.away)]
    this.ball = { x: PITCH_W / 2, y: PITCH_H / 2, z: 0, vx: 0, vy: 0, vz: 0, px: PITCH_W / 2, py: PITCH_H / 2, pz: 0, owner: -1, lastTouch: -1, flight: null, noTouch: 0, noTouchIdx: -1 }
    this.firstKick = this.rng.chance(0.5) ? 0 : 1
    this.startKickoff(this.firstKick, true)
    this.event('kickoff', this.firstKick, undefined, undefined, fillText('kickoff', this.rng, { t: this.teams[this.firstKick].setup.name }))
  }

  // ------------------------------------------------------------------ 準備

  private makeTeam(side: 0 | 1, setup: TeamSetup): TeamRT {
    const formation = formationOf(setup.formation)
    const team: TeamRT = {
      side,
      setup,
      dir: side === 0 ? 1 : -1,
      formation,
      tactics: { ...setup.tactics },
      slots: [],
      bench: [...setup.bench],
      subsUsed: 0,
      subWindows: 0,
      pendingSubs: [],
      stats: emptyTeamStats(),
      aiMentalityShift: 0,
      manual: false,
    }
    setup.starters.forEach((ps, i) => {
      const b = this.makeBody(ps, side, i, true)
      team.slots.push(b.idx)
    })
    return team
  }

  private makeBody(ps: MatchPlayerSetup, team: 0 | 1, slot: number, started: boolean): Body {
    const b: Body = {
      idx: this.bodies.length,
      team,
      slot,
      s: Math.abs(this.levelShift) > 0.05 ? { ...ps, attr: shiftAttrs(ps.attr, this.levelShift) } : ps,
      gk: ps.pos === 'GK',
      x: PITCH_W / 2,
      y: PITCH_H / 2,
      px: PITCH_W / 2,
      py: PITCH_H / 2,
      vx: 0,
      vy: 0,
      tx: PITCH_W / 2,
      ty: PITCH_H / 2,
      urgency: 0.5,
      stamina: ps.stamina,
      decideIn: 0,
      stun: 0,
      tackleCd: 0,
      runT: 0,
      yellow: 0,
      onPitch: true,
      st: { id: ps.id, team, minutes: 0, started, goals: 0, assists: 0, shots: 0, passes: 0, passesOk: 0, tackles: 0, saves: 0, yellow: 0, red: false, injured: false, rating: 6, stamina: ps.stamina },
      rate: 0,
      dribX: 0,
      dribY: 0,
    }
    this.bodies.push(b)
    return b
  }

  // ------------------------------------------------------------------ 便利関数

  /** チームから見た縦の位置（0 = 自陣ゴール、1 = 相手ゴール） */
  u(team: TeamRT, x: number): number {
    return team.dir === 1 ? x / PITCH_W : (PITCH_W - x) / PITCH_W
  }
  /** チームから見た横の位置（0 = 攻める向きの左） */
  v(team: TeamRT, y: number): number {
    return team.dir === 1 ? y / PITCH_H : (PITCH_H - y) / PITCH_H
  }
  xOf(team: TeamRT, u: number): number {
    return team.dir === 1 ? u * PITCH_W : PITCH_W - u * PITCH_W
  }
  yOf(team: TeamRT, v: number): number {
    return team.dir === 1 ? v * PITCH_H : PITCH_H - v * PITCH_H
  }
  oppGoalX(team: TeamRT): number {
    return team.dir === 1 ? PITCH_W : 0
  }

  onPitch(team: 0 | 1): Body[] {
    const out: Body[] = []
    for (const i of this.teams[team].slots) if (i >= 0 && this.bodies[i].onPitch) out.push(this.bodies[i])
    return out
  }

  gkOf(team: 0 | 1): Body | undefined {
    return this.onPitch(team).find((b) => b.gk)
  }

  /** スタミナを反映した能力（試合中に呼ぶ） */
  attr(b: Body): Attrs {
    return b.s.attr
  }

  /** スタミナによる能力の倍率 */
  fatigueMul(b: Body): number {
    return 0.86 + 0.14 * (b.stamina / 100)
  }

  maxSpeed(b: Body): number {
    const a = b.s.attr
    let v = (5.4 + 3.4 * (a.speed / 99)) * (0.8 + 0.2 * (b.stamina / 100))
    if (b.s.skills.includes('speedStar')) v *= 1.05
    if (this.ball.owner === b.idx) v *= 0.82 + 0.12 * (a.dribble / 99)
    return v
  }

  carrier(): Body | undefined {
    return this.ball.owner >= 0 ? this.bodies[this.ball.owner] : undefined
  }

  minuteNow(): { minute: number; added?: number } {
    const base = this.half === 1 ? 0 : this.half === 2 ? 45 : this.half === 3 ? 90 : 105
    const len = this.half <= 2 ? HALF_SECONDS : HALF_SECONDS / 3
    const m = Math.floor((Math.min(this.halfT, len) * CLOCK_SCALE) / 60)
    const halfMinutes = this.half <= 2 ? 45 : 15
    if (this.halfT > len) return { minute: base + halfMinutes, added: Math.min(this.added, Math.floor(((this.halfT - len) * CLOCK_SCALE) / 60) + 1) }
    return { minute: base + Math.min(halfMinutes, m) }
  }

  /** 表示用の時計「67:12」 */
  clockLabel(): string {
    const base = this.half === 1 ? 0 : this.half === 2 ? 45 : this.half === 3 ? 90 : 105
    const secs = this.halfT * CLOCK_SCALE
    const total = base * 60 + secs
    const mm = Math.floor(total / 60)
    const ss = Math.floor(total % 60)
    return `${mm}:${String(ss).padStart(2, '0')}`
  }

  event(type: MatchEventType, team: 0 | 1, player?: number, other?: number, text = '', extra: Partial<MatchEvent> = {}) {
    const { minute, added } = this.minuteNow()
    this.events.push({ t: this.t, minute, added, type, team, player, other, text, ...extra })
  }

  nameOf(idx: number): string {
    return idx >= 0 ? this.bodies[idx].s.short : ''
  }

  // ------------------------------------------------------------------ 進行

  step() {
    // 見せ場で選ぶのを待っている間は止まる
    if (this.pendingMoment) return
    if (this.finished) return
    this.tick++
    this.t += DT
    this.halfT += DT
    for (const b of this.bodies) {
      b.px = b.x
      b.py = b.y
    }
    this.ball.px = this.ball.x
    this.ball.py = this.ball.y
    this.ball.pz = this.ball.z

    if (this.mode === 'restart') this.updateRestart()
    else if (this.mode === 'play') {
      if (this.tick % 5 === 0 || this.tick === 1) {
        updateShape(this, this.teams[0])
        updateShape(this, this.teams[1])
      }
      this.updateCarrier()
      this.updateBallFlight()
      if (this.mode === 'play') this.checkControl()
      if (this.mode === 'play') this.checkDuels()
    }
    this.moveBodies()
    if (this.mode === 'play') {
      this.moveBall()
      this.checkOut()
    }
    this.updateStamina()
    this.updateStats()
    if (this.tick % 300 === 0) this.aiManager()
    this.updateClock()
    if (this.momentWatch && this.t >= this.momentWatch.until) this.closeWatch(this.momentWatch.kind !== 'tackle')
  }

  runToEnd(): MatchSummary {
    this.setAuto()
    let guard = 0
    while (!this.finished && guard++ < 40000) this.step()
    return this.summary()
  }

  // ------------------------------------------------------------------ 時計

  private updateClock() {
    const len = this.half <= 2 ? HALF_SECONDS : HALF_SECONDS / 3
    if (this.halfT >= len && this.added === 0) {
      // ロスタイムは中断の回数から
      this.added = clamp(1 + Math.floor(this.stopCount / 6) + (this.rng.chance(0.4) ? 1 : 0), 1, this.half === 2 ? 6 : 4)
      this.halfLen = len + (this.added * 60) / CLOCK_SCALE
    }
    if (this.halfT < this.halfLen || this.halfLen <= len) return
    // ボールが危険な位置にあるときは少しだけ待つ
    if (this.mode === 'play' && this.halfT < this.halfLen + 4) {
      const c = this.carrier()
      if (c) {
        const tm = this.teams[c.team]
        if (this.u(tm, c.x) > 0.75) return
      }
      if (this.ball.flight && this.ball.flight.kind === 'shot') return
    }
    this.endHalf()
  }

  private endHalf() {
    this.flash = { kind: 'whistle', t: this.t, team: 0 }
    if (this.half === 1 || this.half === 3) {
      this.event('halftime', 0, undefined, undefined, this.half === 1 ? fillText('halftime', this.rng, {}) : '延長前半終了。')
      this.half++
      this.halfT = 0
      this.halfLen = this.half <= 2 ? HALF_SECONDS : HALF_SECONDS / 3
      this.added = 0
      this.stopCount = 0
      for (const t of this.teams) t.dir = t.dir === 1 ? -1 : 1
      // ハーフタイムは交代のタイミング（回数に数えない）
      for (const t of this.teams) this.applySubs(t, true)
      const kick: 0 | 1 = this.firstKick === 0 ? 1 : 0
      this.startKickoff(this.half === 4 ? this.firstKick : kick, true)
      this.event('kickoff', kick, undefined, undefined, fillText('kickoff2', this.rng, { t: this.teams[kick].setup.name }))
      return
    }
    // 試合終了（ノックアウトで同点なら延長・PK）
    if (this.setup.knockout && this.score[0] === this.score[1] && this.half === 2) {
      this.et = true
      this.event('halftime', 0, undefined, undefined, '90分で決着つかず、延長戦へ！')
      this.half = 3
      this.halfT = 0
      this.halfLen = HALF_SECONDS / 3
      this.added = 0
      for (const t of this.teams) t.dir = t.dir === 1 ? -1 : 1
      this.startKickoff(this.firstKick, true)
      return
    }
    if (this.setup.knockout && this.score[0] === this.score[1]) this.shootout()
    this.event('fulltime', 0, undefined, undefined, `${fillText('fulltime', this.rng, {})} ${this.score[0]}-${this.score[1]}`)
    this.mode = 'over'
    this.finished = true
    for (const b of this.bodies) {
      b.vx = 0
      b.vy = 0
    }
  }

  /** PK 戦（確率だけで決める） */
  private shootout() {
    const kickers = (team: 0 | 1) =>
      this.onPitch(team)
        .filter((b) => !b.gk)
        .sort((a, b) => b.s.attr.shoot + b.s.attr.composure - (a.s.attr.shoot + a.s.attr.composure))
    const ks = [kickers(0), kickers(1)]
    const gks = [this.gkOf(1), this.gkOf(0)]
    const sc: [number, number] = [0, 0]
    const kick = (team: 0 | 1, n: number) => {
      const k = ks[team][n % ks[team].length]
      const gk = gks[team]
      const p = clamp(0.74 + (k.s.attr.composure - 60) * 0.003 + (k.s.attr.shoot - 60) * 0.002 - (gk ? (gk.s.attr.reflex - 60) * 0.0025 : 0) + (k.s.skills.includes('pkSpecialist') ? 0.08 : 0) - (gk?.s.skills.includes('pkStopper') ? 0.08 : 0), 0.45, 0.93)
      if (this.rng.chance(p)) sc[team]++
    }
    for (let n = 0; n < 5; n++) {
      kick(0, n)
      kick(1, n)
    }
    let n = 5
    while (sc[0] === sc[1] && n < 30) {
      kick(0, n)
      kick(1, n)
      n++
    }
    this.pens = sc
    this.event('pk', sc[0] > sc[1] ? 0 : 1, undefined, undefined, `PK戦 ${sc[0]}-${sc[1]}、${this.teams[sc[0] > sc[1] ? 0 : 1].setup.name} の勝利！`)
  }

  // ------------------------------------------------------------------ リスタート

  startKickoff(team: 0 | 1, teleport: boolean) {
    this.beginRestart('kickoff', team, PITCH_W / 2, PITCH_H / 2, teleport)
  }

  beginRestart(kind: RestartKind, team: 0 | 1, x: number, y: number, teleport = false) {
    this.mode = 'restart'
    this.stopCount++
    const b = this.ball
    b.x = clamp(x, 0, PITCH_W)
    b.y = clamp(y, 0, PITCH_H)
    b.z = 0
    b.vx = b.vy = b.vz = 0
    b.owner = -1
    b.flight = null
    this.possTeam = team
    // 交代はプレーが止まったときに入る
    for (const t of this.teams) this.applySubs(t, false)
    const taker = this.pickTaker(kind, team, x, y)
    const wait = { kickoff: 1.6, throw: 1.0, goalkick: 1.8, corner: 2.2, freekick: 2.2, penalty: 2.6 }[kind]
    this.restart = { kind, team, x: b.x, y: b.y, taker: taker.idx, wait, timeout: wait + 4 }
    setPieceTargets(this, this.restart)
    if (teleport) {
      for (const p of this.bodies) {
        if (!p.onPitch) continue
        p.x = p.px = p.tx
        p.y = p.py = p.ty
        p.vx = p.vy = 0
      }
    }
  }

  private pickTaker(kind: RestartKind, team: 0 | 1, x: number, y: number): Body {
    const mates = this.onPitch(team)
    const ts = this.teams[team].setup
    const byId = (id?: number) => (id !== undefined ? mates.find((b) => b.s.id === id && !b.gk) : undefined)
    if (kind === 'goalkick') return mates.find((b) => b.gk) ?? mates[0]
    if (kind === 'penalty') return byId(ts.penaltyTaker) ?? [...mates].filter((b) => !b.gk).sort((a, b) => b.s.attr.shoot + b.s.attr.composure - a.s.attr.shoot - a.s.attr.composure)[0]
    if (kind === 'corner') return byId(ts.cornerTaker) ?? [...mates].filter((b) => !b.gk).sort((a, b) => b.s.attr.cross - a.s.attr.cross)[0]
    if (kind === 'freekick') {
      const tm = this.teams[team]
      if (this.u(tm, x) > 0.6) return byId(ts.freeKickTaker) ?? [...mates].filter((b) => !b.gk).sort((a, b) => b.s.attr.shoot + b.s.attr.cross - a.s.attr.shoot - a.s.attr.cross)[0]
    }
    if (kind === 'kickoff') {
      const fw = [...mates].filter((b) => !b.gk).sort((a, b) => this.teams[team].formation.slots[b.slot].u - this.teams[team].formation.slots[a.slot].u)
      return fw[0] ?? mates[0]
    }
    // スローイン・自陣のフリーキック: 近い選手（GK 以外）
    let best = mates[0]
    let bd = 1e9
    for (const m of mates) {
      if (m.gk && kind !== 'freekick') continue
      const d = dist(m.x, m.y, x, y)
      if (d < bd) {
        bd = d
        best = m
      }
    }
    return best
  }

  private updateRestart() {
    const r = this.restart!
    r.wait -= DT
    r.timeout -= DT
    const taker = this.bodies[r.taker]
    if (!taker.onPitch) {
      r.taker = this.pickTaker(r.kind, r.team, r.x, r.y).idx
      return
    }
    taker.tx = r.x - this.teams[r.team].dir * (r.kind === 'throw' ? 0 : 0.6)
    taker.ty = r.y
    taker.urgency = 0.7
    const near = dist(taker.x, taker.y, r.x, r.y) < 1.4
    if (r.wait > 0 || (!near && r.timeout > 0)) return
    if (!near) {
      taker.x = r.x
      taker.y = r.y
    }
    this.mode = 'play'
    this.restart = null
    this.ball.owner = taker.idx
    this.ball.lastTouch = taker.idx
    this.possTeam = r.team
    this.executeRestart(r, taker)
  }

  private executeRestart(r: Restart, taker: Body) {
    const team = this.teams[r.team]
    switch (r.kind) {
      case 'kickoff': {
        // 後ろの味方へ
        const mates = this.onPitch(r.team).filter((b) => b !== taker && !b.gk)
        const back = mates.sort((a, b) => dist(a.x, a.y, r.x - team.dir * 12, r.y) - dist(b.x, b.y, r.x - team.dir * 12, r.y))[0]
        if (back) this.doPass(taker, back, false, 'pass')
        break
      }
      case 'penalty':
        this.doShot(taker, { penalty: true })
        break
      case 'corner':
        this.doCross(taker, true)
        break
      case 'freekick': {
        const { d } = this.goalDist(team, r.x, r.y)
        const central = Math.abs(r.y - PITCH_H / 2) < 16
        if (d < 30 && central && this.rng.chance(0.75)) {
          this.event('chance', r.team, taker.s.id, undefined, fillText('freekickShot', this.rng, { p: taker.s.short }))
          this.doShot(taker, { freekick: true })
        } else if (this.u(team, r.x) > 0.66) this.doCross(taker, true)
        else {
          taker.decideIn = 0
          decideCarrier(this, taker, { passOnly: true })
        }
        break
      }
      case 'goalkick':
      case 'throw':
        taker.decideIn = 0
        decideCarrier(this, taker, { passOnly: true, maxDist: r.kind === 'throw' ? (taker.s.skills.includes('longThrow') && this.u(team, r.x) > 0.7 ? 32 : 22) : 60, throwIn: r.kind === 'throw' })
        break
    }
  }

  goalDist(team: TeamRT, x: number, y: number): { d: number } {
    return { d: dist(x, y, this.oppGoalX(team), PITCH_H / 2) }
  }

  // ------------------------------------------------------------------ 保持者

  private updateCarrier() {
    const c = this.carrier()
    if (!c) return
    const b = this.ball
    this.possTeam = c.team
    // ボールは保持者の少し前
    const sp = Math.hypot(c.vx, c.vy)
    const team = this.teams[c.team]
    const fx = sp > 0.5 ? c.vx / sp : team.dir
    const fy = sp > 0.5 ? c.vy / sp : 0
    b.x = c.x + fx * 0.55
    b.y = c.y + fy * 0.55
    b.z = 0
    b.vx = c.vx
    b.vy = c.vy
    c.decideIn -= DT
    if (c.decideIn <= 0 && c.stun <= 0) decideCarrier(this, c, {})
    // ドリブルの目標へ
    c.tx = c.dribX
    c.ty = c.dribY
  }

  /** 保持者がボールを離す（パス・シュートなど） */
  private release(from: Body) {
    this.ball.owner = -1
    this.ball.lastTouch = from.idx
    this.ball.noTouch = 0.25
    this.ball.noTouchIdx = from.idx
    from.decideIn = 0.6
  }

  /** 二人の連携（0-1） */
  chemistry(a: Body, b: Body): number {
    const t = this.teams[a.team].setup
    const k = a.s.id < b.s.id ? `${a.s.id}:${b.s.id}` : `${b.s.id}:${a.s.id}`
    return (t.chem?.[k] ?? t.chemBase ?? 0) / 100
  }

  /** 相手の守備者のリスト（パスのリスク計算用） */
  defendersOf(team: 0 | 1): Defender[] {
    return this.onPitch(team === 0 ? 1 : 0).map((o) => ({
      idx: o.idx,
      x: o.x,
      y: o.y,
      speed: this.maxSpeed(o) * (o.stun > 0 ? 0.3 : 1),
      skill: o.s.attr.defPos * 0.5 + o.s.attr.marking * 0.2 + o.s.attr.tackle * 0.15 + o.s.attr.agility * 0.15,
    }))
  }

  /** 最も近い相手との距離 */
  pressureOn(b: Body): number {
    let best = 99
    for (const o of this.onPitch(b.team === 0 ? 1 : 0)) {
      const d = dist(o.x, o.y, b.x, b.y)
      if (d < best) best = d
    }
    return best
  }

  /** 受け手の前に出すパスの目標点 */
  leadPoint(from: Body, to: Body, lofted: boolean): { x: number; y: number } {
    const d = dist(from.x, from.y, to.x, to.y)
    const t = lofted ? d / 17 : d / groundAvgSpeed(d)
    return { x: clamp(to.x + to.vx * t * 0.8, 1, PITCH_W - 1), y: clamp(to.y + to.vy * t * 0.8, 1, PITCH_H - 1) }
  }

  isOffside(receiver: Body, passX: number): boolean {
    const team = this.teams[receiver.team]
    const ru = this.u(team, receiver.x)
    if (ru <= 0.5) return false
    if (ru <= this.u(team, passX)) return false
    // 後ろから 2 人目の相手
    const opp = this.onPitch(receiver.team === 0 ? 1 : 0)
      .map((o) => this.u(team, o.x))
      .sort((a, b) => b - a)
    const second = opp[1] ?? 1
    return ru > second + 0.006
  }

  doPass(from: Body, to: Body, lofted: boolean, kind: FlightKind) {
    const team = this.teams[from.team]
    const target = this.leadPoint(from, to, lofted)
    const pressure = this.pressureOn(from) < 2 ? 1 : this.pressureOn(from) < 4 ? 0.5 : 0
    const risk = passRisk(from.x, from.y, target.x, target.y, lofted, from.s.attr, pressure, this.defendersOf(from.team), this.chemistry(from, to))
    const offside = kind !== 'throw' && this.isOffside(to, this.ball.x)
    const r = this.rng.next()
    let outcome: FlightOutcome
    let resolver = -1
    let rx = target.x
    let ry = target.y
    if (r < risk.success) {
      outcome = 'ok'
      resolver = to.idx
    } else if (risk.interceptor >= 0 && r < risk.success + (1 - risk.success) * (risk.intercept / Math.max(0.001, risk.intercept + risk.error))) {
      outcome = 'intercept'
      resolver = risk.interceptor
      rx = from.x + (target.x - from.x) * risk.interceptT
      ry = from.y + (target.y - from.y) * risk.interceptT
    } else {
      outcome = 'astray'
      const ang = (this.rng.chance(0.5) ? 1 : -1) * this.rng.range(0.25, 0.6)
      const dx = target.x - from.x
      const dy = target.y - from.y
      const k = this.rng.range(0.75, 1.3)
      rx = from.x + (dx * Math.cos(ang) - dy * Math.sin(ang)) * k
      ry = from.y + (dx * Math.sin(ang) + dy * Math.cos(ang)) * k
    }
    team.stats.passes++
    from.st.passes++
    this.lastPass = { idx: from.idx, t: this.t }
    this.kick(from, rx, ry, lofted, kind === 'throw' ? 'throw' : lofted ? 'long' : 'pass', outcome, resolver, to.idx)
    if (this.ball.flight) this.ball.flight.offside = offside && outcome === 'ok'
    if (resolver >= 0) {
      const rb = this.bodies[resolver]
      rb.tx = rx
      rb.ty = ry
      rb.urgency = 1
    }
  }

  /** ボールを蹴る（物理の初速を決める） */
  kick(from: Body, tx: number, ty: number, lofted: boolean, kind: FlightKind, outcome: FlightOutcome, resolver: number, intended: number, speedOverride?: number) {
    this.release(from)
    const b = this.ball
    const dx = tx - b.x
    const dy = ty - b.y
    const d = Math.hypot(dx, dy) || 0.01
    if (lofted) {
      const vxy = speedOverride ?? clamp(10 + d * 0.22, 12, 24)
      const T = d / vxy
      b.vx = (dx / d) * vxy
      b.vy = (dy / d) * vxy
      b.vz = (9.81 * T) / 2
    } else {
      // 実際のパスに近い強さ（到着時もまだ速い）
      const v0 = speedOverride ?? Math.min(27, groundSpeedFor(d, kind === 'throw' ? 3 : kind === 'clear' ? 6 : 8 + d * 0.1))
      b.vx = (dx / d) * v0
      b.vy = (dy / d) * v0
      b.vz = kind === 'throw' ? 2.5 : 0
    }
    b.flight = { kind, from: from.idx, team: from.team, resolver, rx: tx, ry: ty, outcome, intended, elapsed: 0, maxT: lofted ? 6 : 4 }
  }

  doShot(from: Body, opt: { header?: boolean; penalty?: boolean; freekick?: boolean } = {}) {
    const team = this.teams[from.team]
    const oppSide: 0 | 1 = from.team === 0 ? 1 : 0
    const gk = this.gkOf(oppSide)
    const pressure = opt.penalty || opt.freekick ? 9 : this.pressureOn(from)
    const defendersAhead = this.onPitch(oppSide).filter((o) => !o.gk && this.u(team, o.x) > this.u(team, from.x)).length
    let bonus = 0
    const sk = from.s.skills
    if (sk.includes('goalHunter')) bonus += 0.15
    if (sk.includes('cannonShot') && this.goalDist(team, from.x, from.y).d > 18) bonus += 0.12
    if (sk.includes('calm')) bonus += 0.05
    if (gk?.s.skills.includes('superSave')) bonus -= 0.1
    let xg = shotXg({ x: from.x, y: from.y, dir: team.dir, shooter: from.s.attr, gk: gk?.s.attr ?? null, pressure, header: !!opt.header, oneOnOne: defendersAhead === 0 && !opt.header, bonus })
    if (opt.penalty) xg = clamp(0.76 + (from.s.attr.composure - 60) * 0.0025 + (sk.includes('pkSpecialist') ? 0.08 : 0) - (gk ? (gk.s.attr.reflex - 60) * 0.002 : 0) - (gk?.s.skills.includes('pkStopper') ? 0.08 : 0), 0.55, 0.92)
    if (opt.freekick) xg = clamp(xg * 0.5 * (sk.includes('fkSpecialist') ? 1.8 : 1) * (0.6 + from.s.attr.cross / 150), 0.02, 0.2)
    const onT = opt.penalty ? Math.max(xg + 0.06, 0.9) : onTargetProb({ x: from.x, y: from.y, dir: team.dir, shooter: from.s.attr, gk: null, pressure, header: !!opt.header, oneOnOne: false, bonus: 0 }, xg)
    // ブロック: シュートコースにいる相手
    let blocker: Body | undefined
    if (!opt.penalty && !opt.freekick) {
      const gx = this.oppGoalX(team)
      for (const o of this.onPitch(oppSide)) {
        if (o.gk) continue
        const dx = gx - from.x
        const dy = PITCH_H / 2 - from.y
        const d = Math.hypot(dx, dy)
        const t = ((o.x - from.x) * dx + (o.y - from.y) * dy) / (d * d)
        if (t <= 0.02 || t > 0.6) continue
        const pd = Math.abs((o.x - from.x) * dy - (o.y - from.y) * dx) / d
        if (pd < 1.6 && t * d < 11 && this.rng.chance(0.45 * (1 - pd / 1.6) + 0.05)) {
          blocker = o
          break
        }
      }
    }
    // キャリア: GK の見せ場（飛び出す／構える）
    if (gk && this.keeperStance && this.isFocus(gk) && !opt.penalty) {
      xg = this.keeperStance === 'rush' ? xg * (1.25 - gk.s.attr.rushing / 160) : xg * (1.05 - gk.s.attr.reflex / 400)
    }
    const r = this.rng.next()
    let outcome: FlightOutcome
    if (blocker && !opt.header) outcome = 'block'
    else if (r < xg) outcome = 'goal'
    else if (r < onT) outcome = 'save'
    else if (this.rng.chance(0.07)) outcome = 'post'
    else outcome = 'miss'
    this.count('res:' + outcome)
    team.stats.shots++
    team.stats.xg += xg
    this.count(opt.header ? 'shot:header' : opt.penalty ? 'shot:pk' : opt.freekick ? 'shot:fk' : this.inOwnBox(this.gkOf(oppSide) ?? from, from.x, from.y) ? 'shot:box' : 'shot:out')
    this.count('shot:' + (blocker && !opt.header ? 'block' : 'x'))
    from.st.shots++
    if (outcome === 'goal' || outcome === 'save') team.stats.onTarget++
    // 目標点（ゴールライン上）
    const gx = this.oppGoalX(team)
    const half = GOAL_W / 2
    const gkY = gk ? gk.y : PITCH_H / 2
    let ty = PITCH_H / 2
    let tz = this.rng.range(0.2, 1.8)
    if (outcome === 'goal') {
      // GK から遠い側のポスト寄り
      const side = gkY > PITCH_H / 2 ? -1 : 1
      ty = PITCH_H / 2 + side * this.rng.range(half - 1.4, half - 0.35)
    } else if (outcome === 'save') {
      ty = clamp(gkY + this.rng.range(-1.6, 1.6), PITCH_H / 2 - half + 0.3, PITCH_H / 2 + half - 0.3)
      tz = this.rng.range(0.2, 1.6)
    } else if (outcome === 'post') {
      ty = PITCH_H / 2 + (this.rng.chance(0.5) ? -half : half)
    } else if (outcome === 'miss') {
      if (this.rng.chance(0.35)) {
        ty = PITCH_H / 2 + this.rng.range(-half + 0.5, half - 0.5)
        tz = this.rng.range(2.7, 4.5)
      } else ty = PITCH_H / 2 + (this.rng.chance(0.5) ? -1 : 1) * this.rng.range(half + 0.4, half + 4)
    }
    const speed = opt.header ? 14 + from.s.attr.header * 0.06 : 20 + from.s.attr.shoot * 0.1 + (sk.includes('cannonShot') ? 3 : 0)
    this.release(from)
    // 外れるシュートの一部は相手に当たってコーナーになる
    if (outcome === 'miss' && !opt.penalty && this.rng.chance(0.22)) {
      const near = this.onPitch(oppSide).filter((o) => !o.gk && dist(o.x, o.y, from.x, from.y) < 9)
      if (near.length) this.ball.lastTouch = near[0].idx
    }
    const b = this.ball
    let tx = gx
    if (outcome === 'block' && blocker) {
      tx = blocker.x
      ty = blocker.y
      tz = 0.6
    }
    const dx = tx - b.x
    const dy = ty - b.y
    const d = Math.hypot(dx, dy) || 0.01
    const T = d / speed
    const z0 = opt.header ? 1.9 : 0.15
    b.vx = (dx / d) * speed
    b.vy = (dy / d) * speed
    b.vz = (tz - z0 + 4.905 * T * T) / T
    b.z = z0
    const resolver = outcome === 'save' && gk ? gk.idx : outcome === 'block' && blocker ? blocker.idx : -1
    b.flight = { kind: 'shot', from: from.idx, team: from.team, resolver, rx: tx, ry: ty, outcome, intended: -1, xg, header: opt.header, penalty: opt.penalty, elapsed: 0, maxT: 3 }
    if (gk) {
      // GK は反応してボールの来る位置へ（得点のときは届かない）
      gk.stun = 0.18 + (1 - gk.s.attr.reflex / 99) * 0.25
      gk.tx = gx - team.dir * 0.4
      gk.ty = outcome === 'goal' ? gkY + (ty - gkY) * 0.55 : ty
      gk.urgency = 1
    }
    if (blocker) {
      blocker.tx = blocker.x
      blocker.ty = blocker.y
    }
    const ev: MatchEventType = 'shot'
    if (outcome !== 'goal') this.pendingShotEvent = { type: ev, shooter: from.idx, outcome, xg }
    else this.pendingShotEvent = null
    this.watchShot(from, outcome)
  }

  private pendingShotEvent: { type: MatchEventType; shooter: number; outcome: FlightOutcome; xg: number } | null = null

  /** クロス: 落下点で空中戦の勝敗を決める */
  doCross(from: Body, setPiece = false) {
    const team = this.teams[from.team]
    const oppSide: 0 | 1 = from.team === 0 ? 1 : 0
    const gx = this.oppGoalX(team)
    // 狙い: ニア・ファー・PK スポット
    const zone = this.rng.weighted([3, 3, 2])
    const nearY = from.y < PITCH_H / 2 ? PITCH_H / 2 - 3 : PITCH_H / 2 + 3
    const farY = from.y < PITCH_H / 2 ? PITCH_H / 2 + 4 : PITCH_H / 2 - 4
    const tx = gx - team.dir * (zone === 2 ? 11 : this.rng.range(5, 8))
    const ty = zone === 0 ? nearY : zone === 1 ? farY : PITCH_H / 2 + this.rng.range(-2, 2)
    const skill = from.s.attr.cross * 0.8 + from.s.attr.vision * 0.2 + (from.s.skills.includes('preciseCross') ? 10 : 0)
    const accurate = this.rng.chance(clamp(0.45 + skill * 0.0055, 0.4, 0.95))
    const atk = this.onPitch(from.team).filter((b) => !b.gk && b !== from && dist(b.x, b.y, tx, ty) < 7)
    const def = this.onPitch(oppSide).filter((b) => dist(b.x, b.y, tx, ty) < 6.5)
    const gk = this.gkOf(oppSide)
    let outcome: FlightOutcome = 'astray'
    let resolver = -1
    let rx = tx
    let ry = ty
    if (!accurate) {
      rx = tx + team.dir * this.rng.range(-4, 6)
      ry = ty + this.rng.range(-8, 8)
      // GK が出てきてキャッチ
      if (gk && dist(gk.x, gk.y, rx, ry) < 9 && this.rng.chance(0.3 + gk.s.attr.rushing / 250)) {
        outcome = 'aerialDef'
        resolver = gk.idx
      }
    } else {
      const bestA = atk.sort((a, b) => aerialScore(b.s.attr) - aerialScore(a.s.attr))[0]
      const bestD = def.sort((a, b) => aerialScore(b.s.attr) - aerialScore(a.s.attr))[0]
      if (gk && this.rng.chance(clamp((gk.s.attr.rushing - 40) / 220, 0.03, 0.25))) {
        outcome = 'aerialDef'
        resolver = gk.idx
      } else if (bestA && (!bestD || this.rng.chance(clamp(0.5 + (aerialScore(bestA.s.attr) - aerialScore(bestD.s.attr)) * 0.025 - (def.length - atk.length) * 0.08 + (bestA.s.skills.includes('aerialKing') ? 0.12 : 0) - (bestD.s.skills.includes('aerialKing') ? 0.12 : 0), 0.12, 0.8)))) {
        outcome = 'aerialAtk'
        resolver = bestA.idx
      } else if (bestD) {
        outcome = 'aerialDef'
        resolver = bestD.idx
      }
    }
    team.stats.passes++
    from.st.passes++
    this.lastPass = { idx: from.idx, t: this.t }
    this.kick(from, rx, ry, true, 'cross', outcome, resolver, -1, setPiece ? 19 : undefined)
    if (resolver >= 0) {
      const rb = this.bodies[resolver]
      rb.tx = rx
      rb.ty = ry
      rb.urgency = 1
    }
  }

  /** 自陣のゴールラインの外へ逃げる（コーナーになる） */
  clearOut(from: Body) {
    const team = this.teams[from.team]
    const gx = team.dir === 1 ? -2 : PITCH_W + 2
    const ty = clamp(from.y + (from.y < PITCH_H / 2 ? -1 : 1) * this.rng.range(6, 16), -1, PITCH_H + 1)
    this.kick(from, gx, ty, this.rng.chance(0.5), 'clear', 'free', -1, -1, 14)
  }

  /** 大きくクリア */
  doClear(from: Body) {
    const team = this.teams[from.team]
    const tx = clamp(from.x + team.dir * this.rng.range(25, 45), 3, PITCH_W - 3)
    const ty = clamp(from.y + this.rng.range(-22, 22), 3, PITCH_H - 3)
    this.kick(from, tx, ty, true, 'clear', 'free', -1, -1)
  }

  // ------------------------------------------------------------------ ボールの飛行と受け取り

  private updateBallFlight() {
    const b = this.ball
    const f = b.flight
    if (!f || b.owner >= 0) return
    f.elapsed += DT
    if (f.resolver >= 0) {
      const r = this.bodies[f.resolver]
      if (!r.onPitch) {
        f.resolver = -1
        return
      }
      // 受け手はボールの来る位置へ（ボールが近づいたらボールに寄る）
      const bd = segDist(r.x, r.y, b.x, b.y, b.x + b.vx * DT, b.y + b.vy * DT)
      if (bd < 6) {
        r.tx = b.x + b.vx * 0.15
        r.ty = b.y + b.vy * 0.15
      } else if (f.kind !== 'shot') {
        r.tx = f.rx
        r.ty = f.ry
      }
      r.urgency = 1
      const reachZ = r.gk ? 2.7 : f.kind === 'cross' || f.kind === 'long' || f.kind === 'clear' ? 2.6 : 1.6
      const reach = r.gk && f.kind === 'shot' ? 1.9 : 1.15
      if (bd < reach && b.z < reachZ) this.arrive(r, f)
    }
    if (b.flight && b.flight.elapsed > b.flight.maxT) {
      this.count('flightTimeout:' + b.flight.kind + ':' + b.flight.outcome)
      b.flight = null
    }
  }

  /** 決まっていた受け手にボールが届いた */
  private arrive(r: Body, f: Flight) {
    const b = this.ball
    this.count('arr:' + f.kind + ':' + f.outcome)
    this.count('arrT:' + f.kind + ':' + f.outcome, f.elapsed)
    const team = this.teams[r.team]
    switch (f.outcome) {
      case 'ok': {
        if (f.offside) {
          this.teams[r.team].stats.offsides++
          this.event('offside', r.team, r.s.id, undefined, fillText('offside', this.rng, { p: r.s.short }))
          this.beginRestart('freekick', r.team === 0 ? 1 : 0, r.x, r.y)
          return
        }
        const passer = this.bodies[f.from]
        if (passer.team === r.team) {
          this.teams[r.team].stats.passesOk++
          passer.st.passesOk++
          passer.rate += 0.012 * TIME_K
        }
        this.take(r, true)
        return
      }
      case 'intercept': {
        const passer = this.bodies[f.from]
        passer.rate -= 0.06 * TIME_K
        r.rate += 0.08 * TIME_K
        r.st.tackles++
        // 触っただけでこぼれることも
        if (this.rng.chance(0.3)) this.deflect(r, 7)
        else this.take(r, false)
        return
      }
      case 'aerialAtk': {
        // ヘディングでシュート（ゴールに近ければ）
        const { d } = this.goalDist(team, r.x, r.y)
        b.flight = null
        if (d < 15) {
          b.owner = r.idx
          this.doShot(r, { header: true })
        } else this.take(r, false)
        return
      }
      case 'aerialDef': {
        b.flight = null
        if (r.gk) {
          this.take(r, false)
          r.st.saves++
          return
        }
        b.owner = r.idx
        r.rate += 0.06 * TIME_K
        if (this.rng.chance(0.3)) this.clearOut(r)
        else this.doClear(r)
        return
      }
      case 'save': {
        const gk = r
        const shooter = this.bodies[f.from]
        const catchP = clamp(0.35 + gk.s.attr.handling * 0.006, 0.4, 0.9)
        gk.st.saves++
        gk.rate += 0.3 * TIME_K
        this.teams[gk.team].stats.saves++
        this.flash = { kind: 'save', t: this.t, team: gk.team }
        this.event('save', shooter.team, shooter.s.id, gk.s.id, fillText('save', this.rng, { p: shooter.s.short, o: gk.s.short }), { xg: f.xg })
        this.pendingShotEvent = null
        if (this.rng.chance(catchP)) this.take(gk, false)
        else {
          // はじく（コーナーになることも）
          b.flight = null
          b.owner = -1
          b.lastTouch = gk.idx
          // 40% はゴールラインの外へ（コーナー）、残りは前へこぼれる
          const out = this.rng.chance(0.4)
          const sideY = b.y < PITCH_H / 2 ? -1 : 1
          b.vx = out ? -team.dir * 3 : team.dir * this.rng.range(5, 10)
          b.vy = sideY * this.rng.range(3, 10)
          b.vz = this.rng.range(0.5, 3)
          b.noTouch = 0.3
          b.noTouchIdx = gk.idx
        }
        return
      }
      case 'block': {
        this.event('block', this.bodies[f.from].team, this.bodies[f.from].s.id, r.s.id, fillText('block', this.rng, { p: this.bodies[f.from].s.short, o: r.s.short }))
        this.pendingShotEvent = null
        r.rate += 0.12 * TIME_K
        if (this.rng.chance(0.45)) {
          b.owner = r.idx
          this.clearOut(r)
        } else this.deflect(r, 9)
        return
      }
      default:
        b.flight = null
    }
  }

  /** ボールを足元に収める */
  take(r: Body, firstTouchCheck: boolean) {
    const b = this.ball
    b.flight = null
    if (firstTouchCheck && !r.gk) {
      // トラップが乱れてこぼれることがある（相手が近いほど）
      const pressure = this.pressureOn(r)
      const pBad = clamp((0.06 + (pressure < 2 ? 0.06 : 0)) * (1.6 - r.s.attr.trap / 99), 0.01, 0.2)
      if (this.rng.chance(pBad)) {
        this.deflect(r, 4)
        return
      }
    }
    b.owner = r.idx
    b.lastTouch = r.idx
    b.vz = 0
    b.z = 0
    this.possTeam = r.team
    r.decideIn = r.gk ? 1.2 : this.rng.range(0.15, 0.4)
    r.dribX = r.x
    r.dribY = r.y
  }

  /** ボールを弾く（こぼれ球にする） */
  deflect(r: Body, speed: number) {
    const b = this.ball
    b.flight = null
    b.owner = -1
    b.lastTouch = r.idx
    const a = this.rng.range(0, Math.PI * 2)
    b.vx = Math.cos(a) * speed
    b.vy = Math.sin(a) * speed
    b.vz = this.rng.range(0, 2)
    b.noTouch = 0.35
    b.noTouchIdx = r.idx
  }

  /** こぼれ球: 近い選手が拾う */
  private checkControl() {
    const b = this.ball
    if (b.owner >= 0) return
    if (b.flight && b.flight.resolver >= 0) return
    // シュートは決められた選手（GK・ブロック）以外は触れない
    if (b.flight && b.flight.kind === 'shot') return
    if (b.noTouch > 0) b.noTouch -= DT
    const sp = Math.hypot(b.vx, b.vy)
    if (b.z > 1.8) return
    let best: Body | null = null
    let bd = 1.05
    for (const p of this.bodies) {
      if (!p.onPitch || p.stun > 0) continue
      if (b.noTouch > 0 && p.idx === b.noTouchIdx) continue
      const d = dist(p.x, p.y, b.x, b.y)
      const reach = p.gk && this.inOwnBox(p, b.x, b.y) ? 1.6 : 1.05
      if (d < reach && d < bd + (p.gk ? 0.6 : 0)) {
        bd = d
        best = p
      }
    }
    if (!best) return
    // 速いボールは収めにくい
    if (sp > 10 && !best.gk && this.rng.chance(clamp((sp - 10) * 0.05, 0, 0.5))) {
      this.deflect(best, sp * 0.4)
      return
    }
    this.take(best, false)
  }

  inOwnBox(p: Body, x: number, y: number): boolean {
    const team = this.teams[p.team]
    return this.u(team, x) < BOX_DEPTH / PITCH_W && Math.abs(y - PITCH_H / 2) < BOX_WIDTH / 2
  }

  // ------------------------------------------------------------------ 1対1

  private checkDuels() {
    const c = this.carrier()
    if (!c || c.gk && this.inOwnBox(c, c.x, c.y)) return
    for (const o of this.onPitch(c.team === 0 ? 1 : 0)) {
      if (o.tackleCd > 0 || o.stun > 0) continue
      const d = dist(o.x, o.y, c.x, c.y)
      if (d > 1.45) continue
      o.tackleCd = 1.0 + this.rng.range(0, 0.4)
      if (this.isFocus(o) && this.defendMoment(c, o)) return
      this.duel(c, o)
      return
    }
  }

  private duel(c: Body, o: Body, extraDef = 0) {
    const team = this.teams[c.team]
    const bonusAtt = c.s.skills.includes('dribbleMaestro') ? 0.12 : 0
    const bonusDef = (o.s.skills.includes('ironWall') ? 0.12 : 0) + (o.s.skills.includes('interceptor') ? 0.04 : 0) + extraDef
    // 自陣深くの守備は少し強い
    const deep = 1 - this.u(this.teams[o.team], o.x)
    const pWin = clamp(tackleWinProb(c.s.attr, o.s.attr, bonusAtt, bonusDef) * (0.92 + deep * 0.15) * this.fatigueMul(o) / this.fatigueMul(c), 0.06, 0.95)
    // 後ろから来たか
    const tdx = c.x - o.x
    const fromBehind = (tdx * team.dir) < -0.3
    // 自分のペナルティエリアでは慎重になる（PK が 1 試合 0.3 本ほど。エリア内の競り合いは前の 2 倍以上あるので強めに）
    const pFoul = foulProb(o.s.attr, o.s.aggression, fromBehind) * (o.s.skills.includes('hotHead') ? 1.5 : 1) * (this.inOwnBox(o, c.x, c.y) ? 0.3 : 1)
    const r = this.rng.next()
    if (r < pFoul) {
      this.foul(o, c)
      return
    }
    if (this.momentWatch?.kind === 'dribble' && this.isFocus(c)) this.closeWatch(!(r >= pFoul && r < pFoul + pWin * (1 - pFoul)))
    if (r < pFoul + pWin * (1 - pFoul)) {
      o.st.tackles++
      o.rate += 0.12 * TIME_K
      c.rate -= 0.06 * TIME_K
      if (this.rng.chance(0.6)) this.take(o, false)
      else this.deflect(o, 5)
      c.stun = 0.4
      // まれに倒れてケガ
      if (this.rng.chance(0.004 * TIME_K * 1.4)) this.injure(c)
    } else {
      // 抜かれた
      o.stun = 0.9
      c.rate += 0.06 * TIME_K
      c.decideIn = Math.min(c.decideIn, 0.3)
    }
  }

  private foul(fouler: Body, victim: Body) {
    const ft = this.teams[fouler.team]
    ft.stats.fouls++
    fouler.rate -= 0.08 * TIME_K
    const vt = this.teams[victim.team]
    const inBox = this.inOwnBox(fouler, victim.x, victim.y)
    // カード
    const goalChance = this.u(vt, victim.x) > 0.72 && Math.abs(victim.y - PITCH_H / 2) < 20 && this.onPitch(fouler.team).filter((b) => !b.gk && this.u(vt, b.x) > this.u(vt, victim.x)).length === 0
    let card: 'none' | 'yellow' | 'red' = 'none'
    const r = this.rng.next()
    // 一発退場は試合あたりの数が変わらないように（ファウルの数は前の 2 倍）
    if (goalChance && this.rng.chance(0.55 * TIME_K)) card = 'red'
    else if (r < 0.006 * TIME_K) card = 'red'
    // 警告を受けている選手は慎重になる（2 枚目の警告での退場が増えすぎないように）
    else if (r < 0.006 * TIME_K + (0.26 + (fouler.s.aggression - 10) * 0.01) * (fouler.yellow ? 0.3 : 1)) card = 'yellow'
    this.event('foul', fouler.team, fouler.s.id, victim.s.id, fillText('foul', this.rng, { p: fouler.s.short, o: victim.s.short }))
    if (card === 'yellow') {
      fouler.yellow++
      fouler.st.yellow++
      ft.stats.yellows++
      fouler.rate -= 0.3
      if (fouler.yellow >= 2) {
        this.event('red', fouler.team, fouler.s.id, undefined, fillText('secondYellow', this.rng, { p: fouler.s.short }))
        this.sendOff(fouler)
      } else this.event('yellow', fouler.team, fouler.s.id, undefined, fillText('yellow', this.rng, { p: fouler.s.short }))
      this.flash = { kind: 'card', t: this.t, team: fouler.team }
    } else if (card === 'red') {
      this.event('red', fouler.team, fouler.s.id, undefined, fillText('red', this.rng, { p: fouler.s.short, t: ft.setup.name }))
      this.sendOff(fouler)
      this.flash = { kind: 'card', t: this.t, team: fouler.team }
    }
    if (this.rng.chance(0.012 * TIME_K * 1.4)) this.injure(victim)
    if (inBox) {
      this.event('penalty', victim.team, fouler.s.id, victim.s.id, fillText('penalty', this.rng, { p: fouler.s.short, o: victim.s.short, t: vt.setup.name }))
      this.beginRestart('penalty', victim.team, this.oppGoalX(vt) - vt.dir * 11, PITCH_H / 2)
    } else this.beginRestart('freekick', victim.team, victim.x, victim.y)
  }

  private sendOff(b: Body) {
    b.onPitch = false
    b.st.red = true
    this.teams[b.team].stats.reds++
    b.rate -= 1.5
    const tm = this.teams[b.team]
    tm.slots = tm.slots.map((i) => (i === b.idx ? -1 : i))
    if (this.ball.owner === b.idx) this.ball.owner = -1
    // GK が退場したら控えの GK を入れる（なければフィールドの選手が GK になる）
    if (b.gk) {
      const benchGk = tm.bench.find((p) => p.pos === 'GK')
      const field = this.onPitch(b.team).filter((p) => !p.gk)
      if (benchGk && tm.subsUsed < 5 && field.length) {
        const out = field.sort((x, y) => x.s.attr.defPos - y.s.attr.defPos)[0]
        tm.pendingSubs.push({ out: out.s.id, in: benchGk.id })
      } else if (field.length) {
        const ng = field.sort((x, y) => y.s.attr.jump - x.s.attr.jump)[0]
        ng.gk = true
        tm.slots = tm.slots.map((i) => (i === ng.idx ? -1 : i))
        tm.slots[0] = ng.idx
        ng.slot = 0
      }
    }
  }

  private injure(b: Body) {
    if (b.st.injured) return
    b.st.injured = true
    this.event('injury', b.team, b.s.id, undefined, fillText('injury', this.rng, { p: b.s.short }))
    const tm = this.teams[b.team]
    const sub = this.bestBenchFor(tm, b)
    if (sub && tm.subsUsed < 5) tm.pendingSubs.push({ out: b.s.id, in: sub.id })
  }

  // ------------------------------------------------------------------ ライン・ゴール

  private checkOut() {
    const b = this.ball
    if (b.owner >= 0) {
      // 保持者がラインを割った
      const c = this.carrier()!
      c.x = clamp(c.x, 0.3, PITCH_W - 0.3)
      c.y = clamp(c.y, 0.3, PITCH_H - 0.3)
      return
    }
    const last = b.lastTouch >= 0 ? this.bodies[b.lastTouch] : null
    const lastTeam: 0 | 1 = last ? last.team : 0
    // ゴールライン
    if (b.x <= 0 || b.x >= PITCH_W) {
      const gx = b.x <= 0 ? 0 : PITCH_W
      // ラインを越えた点を前の位置から補間（速いボールは 1 歩で数 m 進むため）
      const k = Math.abs(b.x - b.px) > 1e-6 ? (gx - b.px) / (b.x - b.px) : 1
      const cy = b.py + (b.y - b.py) * clamp(k, 0, 1)
      const cz = b.pz + (b.z - b.pz) * clamp(k, 0, 1)
      b.y = cy
      const inGoal = Math.abs(cy - PITCH_H / 2) < GOAL_W / 2 && cz < GOAL_H
      // ポストに当たって跳ね返る
      const f = b.flight
      if (f && f.kind === 'shot' && f.outcome === 'post' && Math.abs(Math.abs(b.y - PITCH_H / 2) - GOAL_W / 2) < 0.8) {
        b.x = gx === 0 ? 0.2 : PITCH_W - 0.2
        b.vx = -b.vx * 0.5
        b.vy = this.rng.range(-6, 6)
        b.flight = null
        const shooter = this.bodies[f.from]
        this.event('post', shooter.team, shooter.s.id, undefined, fillText('post', this.rng, { p: shooter.s.short }), { xg: f.xg })
        this.flash = { kind: 'post', t: this.t, team: shooter.team }
        this.pendingShotEvent = null
        return
      }
      // どちらのゴールか: x=0 のゴールを守るのは dir=+1 のチーム
      const defending: 0 | 1 = this.teams[0].dir === 1 ? (gx === 0 ? 0 : 1) : gx === 0 ? 1 : 0
      const attacking: 0 | 1 = defending === 0 ? 1 : 0
      if (inGoal) {
        // 結果が「得点」以外のシュートは GK が止めたことにする（物理のずれで入らないように）
        if (f && f.kind === 'shot' && f.outcome !== 'goal') {
          const gk = this.gkOf(defending)
          if (gk) {
            b.x = gx === 0 ? 0.3 : PITCH_W - 0.3
            gk.x = b.x
            gk.y = b.y
            this.arrive(gk, { ...f, outcome: 'save' })
            return
          }
        }
        this.goal(attacking, f)
        return
      }
      this.flushShotEvent()
      if (lastTeam === attacking) this.beginRestart('goalkick', defending, gx === 0 ? 5.5 : PITCH_W - 5.5, PITCH_H / 2 + (b.y < PITCH_H / 2 ? -9 : 9))
      else {
        this.teams[attacking].stats.corners++
        const taker = this.onPitch(attacking).filter((p) => !p.gk).sort((a, c) => c.s.attr.cross - a.s.attr.cross)[0]
        this.event('corner', attacking, taker?.s.id, undefined, fillText('corner', this.rng, { t: this.teams[attacking].setup.name, p: taker?.s.short }))
        this.beginRestart('corner', attacking, gx === 0 ? 0.5 : PITCH_W - 0.5, b.y < PITCH_H / 2 ? 0.5 : PITCH_H - 0.5)
      }
      return
    }
    if (b.y <= 0 || b.y >= PITCH_H) {
      this.flushShotEvent()
      const team: 0 | 1 = lastTeam === 0 ? 1 : 0
      this.beginRestart('throw', team, clamp(b.x, 1, PITCH_W - 1), b.y <= 0 ? 0 : PITCH_H)
    }
  }

  /** 外れたシュートの実況をまとめて出す */
  private flushShotEvent() {
    const e = this.pendingShotEvent
    if (!e) return
    this.pendingShotEvent = null
    const s = this.bodies[e.shooter]
    if (e.outcome === 'miss') this.event('miss', s.team, s.s.id, undefined, fillText('miss', this.rng, { p: s.s.short }), { xg: e.xg })
  }

  private goal(attacking: 0 | 1, f: Flight | null) {
    const b = this.ball
    const last = b.lastTouch >= 0 ? this.bodies[b.lastTouch] : null
    this.pendingShotEvent = null
    this.count(f ? 'goalBy:' + f.kind + ':' + f.outcome : 'goalBy:loose')
    this.score[attacking]++
    this.teams[attacking].stats.goals++
    const ownGoal = !!last && last.team !== attacking
    const scorer = last
    let assist: Body | undefined
    if (!ownGoal && scorer && this.lastPass.idx >= 0 && this.lastPass.idx !== scorer.idx && this.t - this.lastPass.t < 9) {
      const ap = this.bodies[this.lastPass.idx]
      if (ap.team === attacking) assist = ap
    }
    if (scorer && !ownGoal) {
      scorer.st.goals++
      scorer.rate += 1.0
    }
    if (assist) {
      assist.st.assists++
      assist.rate += 0.6
    }
    // 失点した側の GK と DF
    for (const p of this.onPitch(attacking === 0 ? 1 : 0)) p.rate -= p.gk ? 0.35 : 0.08
    const key = ownGoal ? 'ownGoal' : f?.penalty ? 'penaltyGoal' : f?.header ? 'goalHeader' : assist ? 'goalAssist' : 'goal'
    const text = fillText(key, this.rng, { p: scorer?.s.short, o: assist?.s.short })
    this.event('goal', attacking, scorer?.s.id, assist?.s.id, text, { score: [this.score[0], this.score[1]], xg: f?.xg })
    const ev = this.events[this.events.length - 1] as MatchEvent & { ownGoal?: boolean; penalty?: boolean }
    if (ownGoal) ev.ownGoal = true
    if (f?.penalty) ev.penalty = true
    this.flash = { kind: 'goal', t: this.t, team: attacking }
    this.startKickoff(attacking === 0 ? 1 : 0, false)
    // ゴール後はキックオフまで少し長めに待つ
    if (this.restart) this.restart.wait = 4.5
  }

  // ------------------------------------------------------------------ 移動・物理

  private moveBodies() {
    const n = this.bodies.length
    for (let i = 0; i < n; i++) {
      const p = this.bodies[i]
      if (!p.onPitch) continue
      if (p.stun > 0) p.stun -= DT
      if (p.tackleCd > 0) p.tackleCd -= DT
      if (p.runT > 0) p.runT -= DT
      let dx = p.tx - p.x
      let dy = p.ty - p.y
      const d = Math.hypot(dx, dy)
      const vmax = this.maxSpeed(p) * (p.stun > 0 ? 0.25 : 1)
      // 到着が近いほど減速（arrive）
      let want = Math.min(vmax * clamp(p.urgency, 0.15, 1), d * 1.8)
      if (d < 0.15) want = 0
      if (d > 0) {
        dx /= d
        dy /= d
      }
      const dvx = dx * want - p.vx
      const dvy = dy * want - p.vy
      const acc = (3.6 + 3.2 * (p.s.attr.agility / 99)) * DT
      const dv = Math.hypot(dvx, dvy)
      if (dv > acc) {
        p.vx += (dvx / dv) * acc
        p.vy += (dvy / dv) * acc
      } else {
        p.vx += dvx
        p.vy += dvy
      }
    }
    // 味方同士が重ならないよう少し離す
    for (let i = 0; i < n; i++) {
      const a = this.bodies[i]
      if (!a.onPitch) continue
      for (let j = i + 1; j < n; j++) {
        const b = this.bodies[j]
        if (!b.onPitch || a.team !== b.team) continue
        const dx = b.x - a.x
        const dy = b.y - a.y
        const d2 = dx * dx + dy * dy
        if (d2 < 2.6 && d2 > 1e-6) {
          const d = Math.sqrt(d2)
          const push = ((1.6 - d) / d) * 0.6
          a.vx -= dx * push
          a.vy -= dy * push
          b.vx += dx * push
          b.vy += dy * push
        }
      }
    }
    for (let i = 0; i < n; i++) {
      const p = this.bodies[i]
      if (!p.onPitch) continue
      p.x = clamp(p.x + p.vx * DT, -2, PITCH_W + 2)
      p.y = clamp(p.y + p.vy * DT, -2, PITCH_H + 2)
    }
  }

  private moveBall() {
    const b = this.ball
    if (b.owner >= 0) return
    if (b.z > 0 || b.vz !== 0) {
      b.vz -= 9.81 * DT
      b.z += b.vz * DT
      if (b.z <= 0) {
        b.z = 0
        if (b.vz < -1.6) {
          b.vz = -b.vz * 0.42
          b.vx *= 0.72
          b.vy *= 0.72
        } else b.vz = 0
      }
    }
    if (b.z <= 0.02) {
      const sp = Math.hypot(b.vx, b.vy)
      if (sp > 0) {
        const nsp = Math.max(0, sp - rollDecel(sp) * DT)
        b.vx *= nsp / sp
        b.vy *= nsp / sp
      }
      // 止まりかけたら飛行は終わり（誰でも拾える）
      if (b.flight && nsp(b) < 1.0 && b.flight.kind !== 'shot') {
        this.count('flightStop:' + b.flight.kind + ':' + b.flight.outcome)
        b.flight = null
      }
    }
    b.x += b.vx * DT
    b.y += b.vy * DT
  }

  private updateStamina() {
    for (const p of this.bodies) {
      if (!p.onPitch) continue
      const sp = Math.hypot(p.vx, p.vy)
      const frac = sp / 8.5
      const resist = 1.55 - p.s.attr.stamina / 100
      const work = p.s.skills.includes('hardWorker') ? 0.8 : 1
      p.stamina -= (0.034 * frac * frac * 6 + 0.006) * resist * work * DT * 2.4 * TIME_K
      if (sp < 1.5) p.stamina += 0.004 * DT * 10 * TIME_K
      p.stamina = clamp(p.stamina, 5, 100)
      p.st.minutes = p.st.minutes + (DT * CLOCK_SCALE) / 60
    }
  }

  private updateStats() {
    if (this.mode !== 'play') return
    this.teams[this.possTeam].stats.possession += DT
    const c = this.carrier()
    if (c) {
      const u = this.u(this.teams[c.team], c.x)
      this.count(u < 0.33 ? 'zone:def' : u < 0.66 ? 'zone:mid' : u < 0.84 ? 'zone:att' : 'zone:box')
    } else this.count(this.ball.flight ? 'zone:flight' : 'zone:loose')
  }

  // ------------------------------------------------------------------ 交代・戦術

  command(c: MatchCommand) {
    const tm = this.teams[c.team]
    tm.manual = true
    if (c.kind === 'sub') {
      if (tm.subsUsed + tm.pendingSubs.length >= 5) return
      tm.pendingSubs.push({ out: c.out, in: c.in })
      if (this.mode === 'restart') this.applySubs(tm, false)
    } else if (c.kind === 'tactics') {
      tm.tactics = { ...tm.tactics, ...c.tactics }
    } else if (c.kind === 'formation') {
      this.changeFormation(tm, c.formation)
    }
  }

  changeFormation(tm: TeamRT, id: string) {
    const f = formationOf(id)
    tm.formation = f
    tm.tactics.formation = id
    const players = tm.slots.filter((i) => i >= 0).map((i) => this.bodies[i])
    const gk = players.find((p) => p.gk)
    const field = players.filter((p) => !p.gk)
    const newSlots: number[] = new Array(f.slots.length).fill(-1)
    if (gk) {
      newSlots[0] = gk.idx
      gk.slot = 0
    }
    // 元のスロットの位置に近い新しいスロットへ（貪欲に）
    const used = new Set<number>()
    const old = tm.formation
    for (const p of field.sort((a, b) => b.s.attr.decision - a.s.attr.decision)) {
      let best = -1
      let bd = 1e9
      for (let i = 1; i < f.slots.length; i++) {
        if (used.has(i)) continue
        const s = f.slots[i]
        const os = old.slots[p.slot] ?? s
        const fit = Math.hypot(s.u - os.u, s.v - os.v) * 2 - (p.s.pos === s.pos ? 0.3 : 0)
        if (fit < bd) {
          bd = fit
          best = i
        }
      }
      if (best >= 0) {
        used.add(best)
        newSlots[best] = p.idx
        p.slot = best
      }
    }
    tm.slots = newSlots
  }

  private bestBenchFor(tm: TeamRT, out: Body): MatchPlayerSetup | undefined {
    const pos = tm.formation.slots[out.slot]?.pos ?? out.s.pos
    const cands = tm.bench.filter((p) => (pos === 'GK' ? p.pos === 'GK' : p.pos !== 'GK'))
    const score = (p: MatchPlayerSetup) => {
      const a = p.attr
      const sameLine = p.pos === pos ? 8 : 0
      return a.speed * 0.1 + a.pass * 0.15 + a.finish * 0.1 + a.tackle * 0.1 + a.decision * 0.15 + a.stamina * 0.05 + a.dribble * 0.1 + a.marking * 0.1 + a.defPos * 0.15 + sameLine + (p.skills.includes('joker') ? 5 : 0)
    }
    return cands.sort((a, b) => score(b) - score(a))[0]
  }

  /** 交代を反映（プレーが止まっているときに呼ぶ） */
  applySubs(tm: TeamRT, halftime: boolean) {
    if (!tm.pendingSubs.length) return
    if (!halftime) tm.subWindows++
    for (const sub of tm.pendingSubs) {
      if (tm.subsUsed >= 5) break
      const outBody = this.bodies.find((b) => b.onPitch && b.team === tm.side && b.s.id === sub.out)
      const inSetup = tm.bench.find((p) => p.id === sub.in)
      if (!outBody || !inSetup) continue
      tm.bench = tm.bench.filter((p) => p.id !== sub.in)
      const nb = this.makeBody(inSetup, tm.side, outBody.slot, false)
      nb.x = nb.px = outBody.x
      nb.y = nb.py = outBody.y
      nb.tx = outBody.tx
      nb.ty = outBody.ty
      nb.gk = inSetup.pos === 'GK' || outBody.gk
      if (inSetup.skills.includes('joker')) nb.rate += 0.1
      outBody.onPitch = false
      tm.slots = tm.slots.map((i) => (i === outBody.idx ? nb.idx : i))
      if (this.ball.owner === outBody.idx) this.ball.owner = -1
      if (this.restart && this.restart.taker === outBody.idx) this.restart.taker = nb.idx
      tm.subsUsed++
      this.event('sub', tm.side, inSetup.id, outBody.s.id, fillText('sub', this.rng, { p: inSetup.short, o: outBody.s.short, t: tm.setup.name }))
    }
    tm.pendingSubs = []
  }

  /** AI 監督: 疲れた選手の交代、スコアに応じた戦術変更 */
  private aiManager() {
    const minute = this.minuteNow().minute
    for (const tm of this.teams) {
      if (!tm.setup.ai || tm.manual) continue
      const side = tm.side
      if (minute >= 55 && tm.subsUsed + tm.pendingSubs.length < 5 && tm.subWindows < 3) {
        const tired = this.onPitch(side)
          .filter((p) => !p.gk && (p.stamina < 52 || (p.yellow > 0 && minute > 65)))
          .sort((a, b) => a.stamina - b.stamina)
        const n = minute >= 75 ? 2 : 1
        for (const p of tired.slice(0, n)) {
          const sub = this.bestBenchFor(tm, p)
          if (sub && !tm.pendingSubs.some((s) => s.in === sub.id)) tm.pendingSubs.push({ out: p.s.id, in: sub.id })
        }
      }
      const diff = this.score[side] - this.score[side === 0 ? 1 : 0]
      const want = minute >= 70 && diff < 0 ? 1 : minute >= 78 && diff > 0 ? -1 : 0
      if (want !== tm.aiMentalityShift) {
        tm.tactics.mentality = clamp(tm.setup.tactics.mentality + want, -2, 2)
        tm.aiMentalityShift = want
        if (want !== 0) this.event('tactic', side, undefined, undefined, fillText('tactic', this.rng, { t: tm.setup.name }))
      }
    }
  }

  // ------------------------------------------------------------------ 結果

  // ------------------------------------------------------------------ 見せ場（キャリア）

  private keeperStance: 'rush' | 'stay' | null = null

  isFocus(b: Body): boolean {
    return this.focusId >= 0 && b.s.id === this.focusId
  }

  /** 見せ場を出せる状態か（上限と間隔） */
  momentReady(): boolean {
    return this.focusId >= 0 && this.mode === 'play' && !this.pendingMoment && !this.momentWatch && this.momentLog.length < MAX_MOMENTS && this.t >= this.nextMomentT
  }

  /**
   * 見せ場を出す。選べる画面なら止めて待つ（true を返し、呼んだ側は行動を決めない）。
   * 自動なら、いちばん良さそうなものをすぐ選ぶ
   */
  offerMoment(type: Moment['type'], title: string, choices: MomentChoice[]): boolean {
    if (choices.length < 2) return false
    this.nextMomentT = this.t + MOMENT_GAP
    if (!this.interactive) {
      const best = choices.reduce((a, b) => (b.util > a.util ? b : a))
      this.executeMoment(type, best)
      return true
    }
    this.momentChoices = choices
    this.momentType = type
    this.pendingMoment = { type, title, choices: choices.map((c) => ({ kind: c.kind, label: c.label, prob: c.prob })) }
    return true
  }

  /** 見せ場を自動で選ぶようにする（結果だけ見る・スキップのとき） */
  setAuto() {
    this.interactive = false
    if (this.pendingMoment) {
      const best = this.momentChoices.reduce((a, b) => (b.util > a.util ? b : a), this.momentChoices[0])
      this.resolveMoment(this.momentChoices.indexOf(best))
    }
  }

  /** 画面で選んだ（i 番目） */
  resolveMoment(i: number) {
    const ch = this.momentChoices[i] ?? this.momentChoices[0]
    this.pendingMoment = null
    this.momentChoices = []
    if (ch) this.executeMoment(this.momentType, ch)
  }

  private executeMoment(type: Moment['type'], ch: MomentChoice) {
    ch.run()
    const focusTeam = this.bodies.find((b) => this.isFocus(b))?.team ?? 0
    if (ch.kind === 'shoot' || ch.kind === 'pass' || ch.kind === 'cross') {
      // シュート・パス・クロスの成否は放った瞬間に決まっている
      const o = this.ball.flight?.outcome
      this.momentLog.push({ label: ch.label, ok: ch.kind === 'shoot' ? o === 'goal' : o === 'ok' || o === 'aerialAtk' })
    } else if (ch.kind === 'tackle') {
      const owner = this.ball.owner
      this.momentLog.push({ label: ch.label, ok: owner >= 0 && this.bodies[owner].team === focusTeam })
    } else {
      // ドリブル・キープ・間合い・GK は、少しのあいだ結果を見届ける
      this.momentWatch = { kind: ch.kind, label: ch.label, until: this.t + (type === 'keeper' ? 5 : 4), team: focusTeam }
    }
  }

  private closeWatch(ok: boolean) {
    if (!this.momentWatch) return
    this.momentLog.push({ label: this.momentWatch.label, ok })
    this.momentWatch = null
    this.keeperStance = null
  }

  /** シュートのあと: 守備・GK の見せ場の結果 */
  private watchShot(from: Body, outcome: FlightOutcome) {
    const w = this.momentWatch
    if (!w) return
    if (w.kind === 'contain' && from.team !== w.team) this.closeWatch(false)
    else if ((w.kind === 'rush' || w.kind === 'stay') && from.team !== w.team) this.closeWatch(outcome !== 'goal')
  }

  /** 守備の見せ場: 主人公が相手と 1 対 1 になる直前（自陣で）。true なら今は奪いに行かない */
  private defendMoment(c: Body, o: Body): boolean {
    if (!this.momentReady() || this.u(this.teams[o.team], o.x) > 0.5) return false
    const pWin = clamp(tackleWinProb(c.s.attr, o.s.attr, 0, 0.08), 0.06, 0.95)
    return this.offerMoment('defend', `${c.s.short}が仕掛けてくる！`, [
      { kind: 'tackle', label: 'タックルに行く', prob: pWin, util: pWin - 0.45, run: () => this.duel(c, o, 0.08) },
      {
        kind: 'contain',
        label: '間合いを取る',
        prob: 0.6,
        util: 0.05,
        run: () => {
          o.tackleCd = 0.8
          c.stun = Math.max(c.stun, 0.3)
        },
      },
    ])
  }

  /** GK の見せ場: 相手が GK と 1 対 1（brain から呼ぶ）。true なら相手は今は決めない */
  keeperMoment(c: Body): boolean {
    const gk = this.gkOf(c.team === 0 ? 1 : 0)
    if (!gk || !this.isFocus(gk) || !this.momentReady()) return false
    return this.offerMoment('keeper', `${c.s.short}と 1 対 1！`, [
      { kind: 'rush', label: '飛び出す', prob: clamp(0.35 + gk.s.attr.rushing / 200, 0.2, 0.85), util: gk.s.attr.rushing - gk.s.attr.reflex, run: () => (this.keeperStance = 'rush') },
      { kind: 'stay', label: '構える', prob: clamp(0.3 + gk.s.attr.reflex / 200, 0.2, 0.85), util: gk.s.attr.reflex - gk.s.attr.rushing, run: () => (this.keeperStance = 'stay') },
    ])
  }

  summary(): MatchSummary {
    const players: PlayerMatchStats[] = this.bodies.map((b) => ({ ...b.st, stamina: Math.round(b.stamina), rating: clamp(Math.round((6 + b.rate) * 10) / 10, 3, 10) }))
    // 勝ったチームは少し加点
    const winner = this.score[0] === this.score[1] ? -1 : this.score[0] > this.score[1] ? 0 : 1
    for (const p of players) if (p.team === winner) p.rating = clamp(Math.round((p.rating + 0.3) * 10) / 10, 3, 10)
    for (const side of [0, 1] as const) {
      if (this.score[side === 0 ? 1 : 0] === 0) for (const p of players) if (p.team === side && (this.bodies.find((b) => b.st.id === p.id)?.gk ?? false)) p.rating = clamp(p.rating + 0.5, 3, 10)
    }
    const mom = [...players].sort((a, b) => b.rating - a.rating)[0]?.id
    const goals = this.events
      .filter((e) => e.type === 'goal')
      .map((e) => {
        const ex = e as MatchEvent & { ownGoal?: boolean; penalty?: boolean }
        return { team: e.team, player: e.player ?? -1, assist: e.other, minute: e.minute + (e.added ?? 0), penalty: ex.penalty, ownGoal: ex.ownGoal }
      })
    return {
      moments: this.momentLog.length ? this.momentLog : undefined,
      score: [this.score[0], this.score[1]],
      et: this.et,
      pens: this.pens,
      stats: [{ ...this.teams[0].stats }, { ...this.teams[1].stats }],
      players,
      events: this.events,
      goals,
      mom,
    }
  }
}

function nsp(b: Ball): number {
  return Math.hypot(b.vx, b.vy)
}

/** 点 (px,py) と線分 (ax,ay)-(bx,by) の距離 */
function segDist(px: number, py: number, ax: number, ay: number, bx: number, by: number): number {
  const dx = bx - ax
  const dy = by - ay
  const l2 = dx * dx + dy * dy
  if (l2 < 1e-9) return Math.hypot(px - ax, py - ay)
  const t = Math.max(0, Math.min(1, ((px - ax) * dx + (py - ay) * dy) / l2))
  return Math.hypot(px - (ax + dx * t), py - (ay + dy * t))
}
