/**
 * 自クラブの記録・タイトル・殿堂。
 *   noteMatch     公式戦の通算と、大勝・大敗・最多観客などの記録（試合のたび）
 *   noteTransfer  最高額の獲得・売却（移籍のたび）
 *   seasonRecords 1 シーズンの最多得点（シーズン末、個人成績を消す前）
 *   addTrophies   獲ったタイトル（シーズン末）
 *   inductHallOfFame 引退した選手の殿堂入り（シーズン末）
 */
import { absWeekOf } from '../core/calendar'
import type { Competition, Fixture } from '../models/competition'
import { emptyRecords, type GameState, type MatchRecord } from '../models/game'
import type { Player } from '../models/player'

function rec(state: GameState) {
  state.records ??= emptyRecords()
  return state.records
}

export function noteMatch(state: GameState, comp: Competition, f: Fixture) {
  const me = state.playerClubId
  if (!f.result || (f.home !== me && f.away !== me)) return
  const home = f.home === me
  const gf = home ? f.result.hg : f.result.ag
  const ga = home ? f.result.ag : f.result.hg
  const r = rec(state)
  const t = r.total
  t.played++
  t.gf += gf
  t.ga += ga
  if (gf > ga) t.won++
  else if (gf < ga) t.lost++
  else t.drawn++
  const m: MatchRecord = { season: state.season, absWeek: f.absWeek, compId: comp.id, opponent: home ? f.away : f.home, gf, ga, home }
  const d = gf - ga
  if (d > 0 && (!r.biggestWin || d > r.biggestWin.gf - r.biggestWin.ga || (d === r.biggestWin.gf - r.biggestWin.ga && gf > r.biggestWin.gf))) r.biggestWin = m
  if (d < 0 && (!r.worstLoss || d < r.worstLoss.gf - r.worstLoss.ga || (d === r.worstLoss.gf - r.worstLoss.ga && ga > r.worstLoss.ga))) r.worstLoss = m
  if (gf > 0 && (!r.mostGoalsMatch || gf > r.mostGoalsMatch.gf)) r.mostGoalsMatch = m
  const att = f.result.attendance ?? 0
  if (home && att > (r.topAttendance?.value ?? 0)) r.topAttendance = { season: state.season, absWeek: f.absWeek, opponent: f.away, value: att }
}

export function noteTransfer(state: GameState, p: Player, from: number, to: number, fee: number) {
  const me = state.playerClubId
  if (fee <= 0 || (from !== me && to !== me)) return
  const r = rec(state)
  if (to === me && fee > (r.recordSigning?.fee ?? 0)) r.recordSigning = { season: state.season, playerId: p.id, name: p.name, fee, from }
  if (from === me && fee > (r.recordSale?.fee ?? 0)) r.recordSale = { season: state.season, playerId: p.id, name: p.name, fee, to }
}

/** シーズン末（個人成績を履歴に移す前）に呼ぶ */
export function seasonRecords(state: GameState) {
  const me = state.playerClubId
  const r = rec(state)
  for (const id in state.players) {
    const p = state.players[id]
    if (p.clubId !== me || p.retired) continue
    if (p.stats.goals > (r.mostGoalsSeason?.goals ?? 0)) r.mostGoalsSeason = { season: state.season, playerId: p.id, name: p.name, goals: p.stats.goals }
  }
}

/** 獲ったタイトルを記録する（league はその季の各リーグの優勝、cups は大会 id → 優勝クラブ） */
export function addTrophies(state: GameState, champions: { compId: string; clubId: number }[]) {
  const me = state.playerClubId
  state.trophies ??= []
  for (const c of champions) {
    if (c.clubId !== me) continue
    const comp = state.competitions.find((x) => x.id === c.compId)
    const name = comp ? (comp.kind === 'league' ? `${comp.name} 優勝` : comp.name) : c.compId
    state.trophies.push({ season: state.season, compId: c.compId, name })
  }
}

/** 自クラブでの通算（履歴＋今季） */
export function clubCareer(state: GameState, p: Player, clubId = state.playerClubId): { apps: number; goals: number; assists: number; seasons: number } {
  let apps = 0
  let goals = 0
  let assists = 0
  let seasons = 0
  for (const h of p.history) {
    if (h.clubId !== clubId) continue
    apps += h.apps
    goals += h.goals
    assists += h.assists
    seasons++
  }
  if (p.clubId === clubId) {
    apps += p.stats.apps
    goals += p.stats.goals
    assists += p.stats.assists
  }
  return { apps, goals, assists, seasons }
}

/** 殿堂入りの条件を満たしていれば理由を返す */
export function hallOfFameReason(state: GameState, p: Player): string | null {
  const me = state.playerClubId
  const c = clubCareer(state, p)
  const honors = state.seasons.flatMap((s) => s.awards ?? []).filter((a) => a.playerId === p.id && a.clubId === me && (a.key === 'mvp' || a.key === 'scorer'))
  if (c.apps >= 120) return `通算 ${c.apps} 試合出場`
  if (c.goals >= 50) return `通算 ${c.goals} 得点`
  if (honors.length && c.apps >= 40) return honors.some((a) => a.key === 'mvp') ? 'リーグ MVP' : 'リーグ得点王'
  return null
}

/** 引退した選手の殿堂入り。入った選手の id を返す */
export function inductHallOfFame(state: GameState, retired: Player[]): number[] {
  state.hallOfFame ??= []
  const out: number[] = []
  for (const p of retired) {
    if (state.hallOfFame.some((h) => h.playerId === p.id)) continue
    const reason = hallOfFameReason(state, p)
    if (!reason) continue
    const c = clubCareer(state, p)
    state.hallOfFame.push({ playerId: p.id, name: p.name, season: state.season, pos: p.pos, nation: p.nation, apps: c.apps, goals: c.goals, reason })
    state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'club', mine: true, text: `${p.name} がクラブの殿堂入り（${reason}）。` })
    out.push(p.id)
  }
  return out
}
