/** キャリアモード（1 人の選手として成り上がる）の状態。GameState.career に入る。 */
import type { SquadRole } from './player'
import type { AttrKey } from '../data/attributes'

/** 経験点の種類（サクセス風）: 筋力・敏捷・技術・戦術・精神 */
export type ExpKind = 'power' | 'speed' | 'tech' | 'tactics' | 'mental'
export const EXP_KINDS: ExpKind[] = ['power', 'speed', 'tech', 'tactics', 'mental']
export const EXP_LABEL: Record<ExpKind, string> = { power: '筋力', speed: '敏捷', tech: '技術', tactics: '戦術', mental: '精神' }

export type PlayStyle = 'speedster' | 'technician' | 'striker' | 'playmaker' | 'defender' | 'keeper'

export type TrainMenu = 'shoot' | 'passDribble' | 'physical' | 'speed' | 'strength' | 'defense' | 'tactics' | 'gkSave' | 'gkFeet'

/** 育成のしかた: easy = 練習した能力が自動で上がる、normal = 経験点を自分で振る */
export type GrowthMode = 'easy' | 'normal'

export type PlaceId =
  | 'clubhouse'
  | 'cafe'
  | 'gym'
  | 'park'
  | 'library'
  | 'shop'
  | 'mall'
  | 'golf'
  | 'konbini'
  | 'dining'
  // 海外（名前は国ごと）
  | 'o_club'
  | 'o_cafe'
  | 'o_school'
  | 'o_park'
  | 'o_market'
  | 'o_museum'

/** 暮らしている地域: 日本か、海外の国（欧州 5 か国とブラジル） */
export type Region = 'JP' | 'EN' | 'ES' | 'IT' | 'DE' | 'FR' | 'BR'
export const OVERSEAS: Region[] = ['EN', 'ES', 'IT', 'DE', 'FR', 'BR']

/** デートの行き先 */
export type DateSpotId = 'movie' | 'aquarium' | 'amusement' | 'beach' | 'nightview' | 'museum' | 'picnic' | 'shopping' | 'cooking' | 'stadium' | 'drive'

/** ヒロインの個性（恋人・家族の出来事の出やすさと、台詞の味付け） */
export type PartnerTrait = 'cook' | 'sport' | 'study' | 'art' | 'cheer' | 'care'

/** 住まい（寮・アパート・マンションは賃貸、ほかは買う家） */
export type HousingId = 'dorm' | 'apartment' | 'mansion' | 'house' | 'seaview' | 'penthouse' | 'estate' | 'forest' | 'seaside' | 'london' | 'medVilla'

/** 車 */
export type CarId = 'compact' | 'minivan' | 'suv' | 'ev' | 'sedan' | 'sports' | 'classic' | 'limo' | 'supercar'

export interface OwnedCar {
  id: CarId
  /** 買ったシーズン（値段の上がり下がり） */
  season: number
}

/** オフの旅行の行き先（home = 持っている別荘） */
export type VacationId = 'hakone' | 'okinawa' | 'hokkaido' | 'hawaii' | 'maldives' | 'paris' | 'swiss' | 'newyork' | 'cruise' | 'home'
/** 旅行の連れ */
export type Companion = 'solo' | 'partner' | 'family' | 'friends'

export interface TripMemory {
  season: number
  dest: VacationId
  with: Companion
  /** 一緒に行った恋人・妻 */
  partner?: string
  /** 別荘で過ごしたときの家 */
  home?: HousingId
}

/** テレビ・雑誌・CM などの依頼 */
export type MediaKind = 'news' | 'magazine' | 'variety' | 'documentary' | 'book' | 'cm' | 'overseas'

export interface MediaOffer {
  kind: MediaKind
  /** 番組・雑誌・会社の名前（架空） */
  name: string
  /** 出演料（万円。CM は年額） */
  pay: number
  expiresAbsWeek: number
}

export interface MediaRecord {
  kind: MediaKind
  name: string
  season: number
  pay: number
}

export interface CmContract {
  company: string
  annual: number
  /** このシーズンまで */
  until: number
}

export interface Child {
  name: string
  bornAbsWeek: number
  /** 性別（M17。古いセーブは名前から推し量る: career/saga.ts の childSex） */
  sex?: 'boy' | 'girl'
  /** 高校のサッカー部か、クラブのユースか（15 歳の進路。M17） */
  path?: 'school' | 'clubYouth'
  /** サッカーをしている */
  soccer?: boolean
  /** サッカーの才能（0〜5） */
  talent?: number
  /** 済んだ節目（出来事の id） */
  done?: string[]
}

/** 装備（買い切り。レベルあり）と、毎週お金のかかるサービス */
export type GearId = 'spikes' | 'capsule'
export type ServiceId = 'trainer' | 'nutrition' | 'sleep' | 'chef' | 'mentalCoach' | 'analyst' | 'physio' | 'coach' | 'foundation' | 'scienceLab' | 'medicalTeam' | 'supportTeam'

/** ぜいたく品・社会貢献（買い切り） */
export type LuxuryId = 'watch' | 'car' | 'villa' | 'donation' | 'trainingCenter' | 'jet'

/** 自宅の練習器具（置ける数は住まいで決まる） */
export type HomeGearId = 'treadmill' | 'homeGym' | 'kickNet' | 'videoRoom' | 'sauna' | 'yogaRoom' | 'pool' | 'oxygen' | 'miniPitch'

/** 趣味 */
export type HobbyId = 'golf' | 'reading' | 'cooking' | 'guitar' | 'fishing' | 'photo' | 'shogi' | 'yoga'

export interface HobbyState {
  id: HobbyId
  /** 腕前 0-100 */
  skill: number
  startedAbsWeek: number
}

/** 個人の事業 */
export type CareerBizId = 'school' | 'apparel' | 'cafe' | 'gym' | 'channel' | 'realestate'

export interface CareerBusiness {
  id: CareerBizId
  /** 1-3 */
  level: number
  openedAbsWeek: number
  /** これまでにかけたお金（開業と拡大。売るときの値の元） */
  invested: number
  /** 通算の損益 */
  total: number
  /** このシーズンの損益 */
  season: number
}

/** スポンサーの格: 1 = 地元企業、2 = 全国企業、3 = 世界的ブランド */
export type SponsorTier = 1 | 2 | 3

/** 個人スポンサー */
export interface PersonalSponsor {
  company: string
  /** 年額（万円） */
  annual: number
  /** このシーズンの終わりまで */
  until: number
  /** 格（古いセーブは未設定 = 1） */
  tier?: SponsorTier
  /** シーズンの目標（得点か出場）と、達成したときのボーナス（万円） */
  goal?: { kind: 'goals' | 'apps'; target: number; bonus: number }
}

/** 今週の過ごし方 */
export type WeekAction =
  | { kind: 'train'; menu: TrainMenu }
  | { kind: 'rest' }
  /** 仲間と自主トレ（partner は男性キャラの id） */
  | { kind: 'selfTrain'; partner: string }
  | { kind: 'outing'; place: PlaceId }
  /** 取材・ファンサービス（知名度） */
  | { kind: 'media' }
  /** 趣味の時間（休養の代わり） */
  | { kind: 'hobby'; hobby: HobbyId }
  /** デートに誘う（相手と行き先） */
  | { kind: 'date'; who: string; spot: DateSpotId }

/** 監督からの課題 */
export interface Objective {
  id: number
  kind: 'goals' | 'assists' | 'goodGames' | 'apps' | 'cleanSheets'
  target: number
  progress: number
  /** この絶対週までに */
  untilAbsWeek: number
}

/** 人との関係（0-100）。恋人・結婚は大人どうしで、相談相手でない人だけ */
export interface Bond {
  value: number
  lastAbsWeek: number
  lover?: boolean
  /** デートした回数 */
  dates?: number
}

/** キャリアのオファー（入団・移籍・契約更改） */
export interface CareerOffer {
  id: number
  kind: 'rookie' | 'transfer' | 'renewal'
  clubId: number
  /** 移籍金（今のクラブへ。主人公は払わない） */
  fee: number
  /** 年俸（万円） */
  wage: number
  years: number
  role: SquadRole
  expiresAbsWeek: number
}

/** 会話の予約（画面で順に見せる）。台詞は dialogue のデータから引く */
export interface PendingTalk {
  eventId: string
  /** 台詞の差し込み（{club} など） */
  vars?: Record<string, string>
}

/** 1 シーズンの記録 */
export interface CareerSeasonLog {
  season: number
  clubId: number
  leagueId: string
  apps: number
  goals: number
  assists: number
  /** 平均評価点 */
  rating: number
  ovr: number
  wage: number
  titles: string[]
  /** そのシーズンのクラブのランクの段（0 = E 〜 5 = S。career/rank.ts） */
  rank?: number
  /** ピッチクラウン賞（世界の年間最優秀選手）の順位（10 位以内のとき） */
  worldRank?: number
}

/** 引退したときのキャリアの総括 */
export interface CareerSummary {
  grade: string
  points: number
  apps: number
  goals: number
  assists: number
  titles: string[]
  caps: number
  intlGoals: number
  worldCups: number
  peakOvr: number
  /** 殿堂入りしたクラブ */
  hallOfFame: number[]
  retiredAge: number
}

/** 世代をつなぐ物語（M17）: 引退した主人公の記録 */
export interface LineageEntry {
  gen: number
  playerId: number
  name: string
  /** 写真の id（生成した写真） */
  photo?: string
  bornAbsWeek: number
  retiredAge: number
  grade: string
  apps: number
  goals: number
  titles: string[]
  caps: number
  /** 歩んだクラブ（名前） */
  clubs: string[]
  spouse?: string
  /** 結婚相手の名前（子どもの世代の人は世代ごとに名前が変わるので、記録したときの名前） */
  spouseName?: string
  children: string[]
}

/** 世代の段階: watch = 見守り期（息子が 15 歳になるまで、親として月ごとに）、youth = ユース期（息子が主人公。15〜17 歳）、pro = プロ */
export interface SagaState {
  gen: number
  phase: 'watch' | 'youth' | 'pro'
  /** この世代が始まったシーズン（新しい世代の登場人物の年齢の起点） */
  startSeason: number
  /** 見守り期: 次の主人公になる子（親の children の番号） */
  heirIdx?: number
  /** 見守り期: 練習の方針の積み重ね（主人公になるときの能力に効く） */
  focus?: Partial<Record<ExpKind, number>>
  /** ユース期: チーム（高校かクラブのユース）と学年・成績 */
  youth?: { team: string; path: 'school' | 'clubYouth'; year: number; apps: number; goals: number; titles: string[]; selected?: boolean; strength: number }
  /** 新しい世代の登場人物の名前（役の id → 名前。世代ごとに選び直す） */
  names?: Record<string, string>
  /** 親（ひとつ前の主人公）と母 */
  father?: { name: string; playerId: number; photo?: string }
  mother?: string
  /** 母の名前（記録したときの名前。子どもの世代の人は世代ごとに名前が変わる） */
  motherName?: string
}

export interface CareerState {
  playerId: number
  /** 世代をつなぐ物語（M17。未設定は 1 世代目のプロ） */
  saga?: SagaState
  /** 一族の記録（M17。引退した主人公を世代順に） */
  lineage?: LineageEntry[]
  style: PlayStyle
  exp: Record<ExpKind, number>
  /** 体力ゲージ 0-100（練習で減り、休養で戻る。低いとケガの危険） */
  stamina: number
  /** 監督の評価 0-100（先発争いに効く） */
  trust: number
  /** 知名度 0-100（オファーの格に効く） */
  fame: number
  /** 貯金（万円） */
  money: number
  objectives: Objective[]
  /** コツ（特殊能力 id → 割引の段階 1-3） */
  kotsu: Record<string, number>
  bonds: Record<string, Bond>
  /** 済んだイベント（id → 絶対週） */
  done: Record<string, number>
  talks: PendingTalk[]
  offers: CareerOffer[]
  log: CareerSeasonLog[]
  /** 恋人（ヒロインの id） */
  partner?: string
  /** 今週の過ごし方（画面で選ぶ。未設定ならおまかせ） */
  action?: WeekAction
  /** 先週の出来事（ホームに出す） */
  report: string[]
  /** 育成のしかた（未設定は normal。新しいキャリアは作成画面で選ぶ） */
  growthMode?: GrowthMode
  /** おまかせのときの練習（週ごとに順に回す。未設定なら得意練習とフィジカル） */
  trainPlan?: TrainMenu[]
  /** 最近の練習で鍛えた能力の重み（簡単モードで自動で上げる。毎週 0.7 倍に減る） */
  focus?: Partial<Record<AttrKey, number>>
  /** 直近の試合での主人公（試合後の画面用） */
  lastMatch?: { rating: number; goals: number; assists: number; started: boolean; minutes: number; expGain: Partial<Record<ExpKind, number>>; trustDelta: number; moments: { label: string; ok: boolean }[] }
  /** 次の課題の id */
  nextObjectiveId: number
  nextOfferId: number
  /** 引退した */
  retired?: boolean
  /** 移籍を志願している（オファーが届きやすくなる） */
  wantsMove?: boolean
  /** 今のクラブに入った週（入ってすぐは移籍の話が来ない） */
  joinedAbsWeek?: number
  // ---- M8: くらし・家族・代表・引退 ----
  /** 住まい（未設定なら寮） */
  housing?: HousingId
  gear?: Partial<Record<GearId, number>>
  services?: ServiceId[]
  sponsor?: PersonalSponsor
  /** 個人スポンサーの申し出（期限つき） */
  sponsorOffer?: PersonalSponsor & { expiresAbsWeek: number }
  /** 自宅の練習器具（レベル） */
  homeGear?: Partial<Record<HomeGearId, number>>
  /** 続けている趣味 */
  hobbies?: HobbyState[]
  /** 個人スポンサー（知名度で 3 枠まで。古いセーブの sponsor は 1 枠目に移す） */
  sponsors?: PersonalSponsor[]
  /** 個人の事業 */
  businesses?: CareerBusiness[]
  /** 売った事業も含めた、事業の通算の損益 */
  bizTotal?: number
  /** 恋人・家族の出来事を最後に予約した週 */
  partnerEventAbsWeek?: number
  /** 申し込んだオフシーズンの海外自主トレ（このシーズンの終わりに行く。premium は一流のトレーナーつき） */
  camp?: { kind: ExpKind; season: number; premium?: boolean }
  /** 持っているぜいたく品・社会貢献 */
  luxuries?: LuxuryId[]
  /** 故郷のクラブ（入団したクラブ）への出資の段階（1〜3） */
  clubShare?: { clubId: number; level: number }
  /** 入団したクラブ（故郷のクラブ） */
  homeClubId?: number
  /** まだ見ていない年間表彰式（そのシーズン） */
  ceremony?: { season: number }
  /** 結婚した相手（ヒロインの id） */
  spouse?: string
  marriedAbsWeek?: number
  /** 恋人になった週 */
  loverAbsWeek?: number
  children?: Child[]
  // ---- M12: 家と車・休暇・メディア ----
  /** 持っている家（住まいの housing は、持っている家か賃貸） */
  ownedHomes?: HousingId[]
  /** 持っている車といつも乗る車 */
  cars?: OwnedCar[]
  mainCar?: CarId
  /** 予約したオフの旅行（このシーズンの終わりに行く。費用は予約のときに払う） */
  vacation?: { id: VacationId; with: Companion; season: number; home?: HousingId; cost: number }
  /** 旅行のあと、新しいシーズンのはじめに戻る調子 */
  vacationBoost?: number
  /** 思い出のアルバム */
  memories?: TripMemory[]
  /** メディアの依頼（期限つき）と出演歴 */
  mediaOffer?: MediaOffer
  media?: MediaRecord[]
  /** CM の契約（2 本まで） */
  cms?: CmContract[]
  /** 自伝の印税（このシーズンまで、毎シーズン末に入る） */
  book?: { royalty: number; until: number }
  /** 家族の行事（行事の id → 済んだシーズン） */
  familyEvents?: Record<string, number>
  /** 代表の直近の試合（試合後の表示用） */
  lastNational?: { opp: string; compShort: string; gf: number; ga: number; rating: number; goals: number; minutes: number }
  /** 今季限りで引退する */
  retirePlanned?: boolean
  /** 引退を考える話をしたシーズン */
  retireAskedSeason?: number
  retiredAbsWeek?: number
  /** キャリアの総括（引退したとき） */
  summary?: CareerSummary
  /** クラブモードへ書き出した */
  exported?: boolean
}
