export const OUTFIELD_KEYS = ATTR_KEYS.filter((k) => ATTR_BY_KEY[k].group !== 'gk')
export const GK_KEYS = ATTR_KEYS.filter((k) => ATTR_BY_KEY[k].group === 'gk')

export function emptyAttrs(v = 0): Attrs {
  return Object.fromEntries(ATTR_KEYS.map((k) => [k, v])) as Attrs
}

