/** 6つの要約値（リスト表示用） */
export const SUMMARY_KEYS = ['att', 'tec', 'pas', 'def', 'phy', 'men'] as const
export type SummaryKey = (typeof SUMMARY_KEYS)[number]
export const SUMMARY_LABEL: Record<SummaryKey, string> = {
  att: '攻撃',
  tec: '技術',
  pas: 'パス',
  def: '守備',
  phy: '身体',
  men: '精神',
}
const SUMMARY_PARTS: Record<SummaryKey, [AttrKey, number][]> = {
  att: [
    ['finish', 3],
    ['shoot', 2],
    ['offBall', 2],
    ['header', 1],
  ],
  tec: [
    ['dribble', 2],
    ['trap', 2],
    ['agility', 1],
  ],
  pas: [
    ['pass', 3],
    ['vision', 2],
    ['cross', 1],
  ],
  def: [
    ['tackle', 2],
    ['marking', 2],
    ['defPos', 2],
  ],
  phy: [
    ['speed', 2],
    ['stamina', 2],
    ['strength', 2],
    ['jump', 1],
  ],
  men: [
    ['decision', 2],
    ['composure', 2],
  ],
}

export function summaryOf(a: Attrs): Record<SummaryKey, number> {
  const out = {} as Record<SummaryKey, number>
  for (const k of SUMMARY_KEYS) {
    let s = 0
    let w = 0
    for (const [key, wt] of SUMMARY_PARTS[k]) {
      s += a[key] * wt
      w += wt
    }
    out[k] = Math.round(s / w)
  }
  return out
}

/** GK の要約値 */
export function gkSummaryOf(a: Attrs): Record<SummaryKey, number> {
  return {
    att: Math.round((a.reflex * 2 + a.agility) / 3),
    tec: Math.round(a.handling),
    pas: Math.round((a.kicking * 2 + a.pass) / 3),
    def: Math.round(a.gkPos),
    phy: Math.round((a.jump + a.strength + a.rushing) / 3),
    men: Math.round((a.decision + a.composure) / 2),
  }
}
