/**
 * 国内カップ戦「ナショナルカップ」。NPL の 54 クラブ＋アマチュア 10 クラブの 64 チームによるトーナメント。
 * 平日（midweek）に 1 試合勝負（延長・PK あり）。次の回戦は前の回戦が終わってから抽選する。
 */
import { createRng, hashSeed, type Rng } from '../core/prng'
import { absWeekOf } from '../core/calendar'
import type { Competition, Fixture } from '../models/competition'
import { allocId, type GameState } from '../models/game'
import type { Club } from '../models/club'
import { generateSquad } from '../gen/playerGen'
import { CLUB_STAFF_ROLES, generateStaff } from '../gen/staffGen'
import { autoLineup } from '../match/lineup'
import { winnerOf } from './playoff'

export const CUP_ID = 'CUP'
export const CUP_NAME = 'ナショナルカップ'
/** 各回戦の週（R64・R32・R16・準々決勝・準決勝・決勝） */
export const CUP_WEEKS = [6, 10, 14, 18, 27, 42]
export const CUP_ROUND_NAME = ['1回戦', '2回戦', '3回戦', '準々決勝', '準決勝', '決勝']
/** 自クラブの賞金（その回戦で負けたとき） */
export const CUP_PRIZE = [0, 200, 500, 1000, 2000, 4000]
export const CUP_WIN_PRIZE = 10000

const AMATEUR: [string, string, string, string][] = [
  ['北見FCアマ', '北見', '#0f766e', '#ffffff'],
  ['弘前シティ', '弘前', '#7c2d12', '#fde68a'],
  ['桐生ユナイテッド', '桐生', '#1e3a8a', '#f97316'],
  ['伊勢SC', '伊勢', '#991b1b', '#ffffff'],
  ['舞鶴マリーンズ', '舞鶴', '#0369a1', '#ffffff'],
  ['出雲FC', '出雲', '#365314', '#fef08a'],
  ['宇和島SC', '宇和島', '#c2410c', '#111827'],
  ['唐津ウェーブ', '唐津', '#1d4ed8', '#e0f2fe'],
  ['延岡FC', '延岡', '#6b21a8', '#ffffff'],
  ['石垣ブルー', '石垣', '#0891b2', '#fde047'],
]

/** アマチュアクラブ（カップ戦にだけ出る）を用意する。古いセーブでも呼べる */
export function ensureAmateurClubs(state: GameState) {
  if (state.competitions.some((c) => c.id === 'AMA')) return
  const rng = createRng(hashSeed(state.seed, 0xa3a))
  const comp: Competition = { id: 'AMA', kind: 'league', name: 'アマチュア', short: 'AMA', country: 'JP', tier: 4, season: state.season, clubIds: [], fixtures: [], table: [], promotion: 0, relegation: 0, playoff: false, simulated: 'fast', hidden: true }
  for (const [name, short, primary, secondary] of AMATEUR) {
    const club: Club = {
      id: state.clubs.length,
      name,
      short,
      country: 'JP',
      city: short,
      colors: { primary, secondary },
      emblem: { shape: rng.int(0, 4), charge: rng.int(0, 7), pattern: rng.int(0, 4) },
      kit: 'solid',
      rep: rng.int(8, 16),
      leagueId: 'AMA',
      budget: 2000,
      facilities: { training: 0, medical: 0, dorm: 0, analysis: 0, youth: 0, pr: 0, lodge: 0, scoutOffice: 0 },
      stadium: { name: `${short}市営競技場`, capacity: 3000, grade: 1 },
      fans: 500,
      popularity: 3,
      tactics: { formation: '4-4-2', mentality: 0, tempo: 50, width: 50, lineHeight: 45, pressing: 45, focus: 'balanced', offsideTrap: false, counter: false },
      lineup: { starters: [], bench: [], manual: false },
      staff: [],
      isPlayer: false,
      lastRank: 0,
    }
    state.clubs.push(club)
    comp.clubIds.push(club.id)
    comp.table.push({ clubId: club.id, played: 0, won: 0, drawn: 0, lost: 0, gf: 0, ga: 0, points: 0, form: '' })
    for (const role of CLUB_STAFF_ROLES.slice(0, 3)) {
      const s = generateStaff(state, rng, role, club.id, 25 + rng.range(0, 10), 'JP')
      state.staff[s.id] = s
      club.staff.push(s.id)
    }
    for (const p of generateSquad(state, rng, club.id)) state.players[p.id] = p
    club.lineup = autoLineup(state, club)
  }
  state.competitions.push(comp)
}

const CUP_SIZE = 64

/** シーズンの初めにカップ戦を作る（1 回戦の抽選まで） */
export function createCup(state: GameState) {
  ensureAmateurClubs(state)
  state.competitions = state.competitions.filter((c) => c.id !== CUP_ID)
  // NPL とワールドリーグ（M24）の日本勢、残りはアマチュアで 64 クラブ
  const pro = [
    ...state.competitions.filter((c) => c.country === 'JP' && c.kind === 'league' && c.id !== 'AMA').flatMap((c) => c.clubIds),
    ...(state.competitions.find((c) => c.id === 'WL')?.clubIds.filter((id) => state.clubs[id].country === 'JP') ?? []),
  ]
  const ama = state.competitions.find((c) => c.id === 'AMA')?.clubIds ?? []
  const ids = [...pro, ...ama].slice(0, CUP_SIZE)
  const comp: Competition = { id: CUP_ID, kind: 'cup', name: CUP_NAME, short: 'CUP', country: 'JP', tier: 0, season: state.season, clubIds: ids, fixtures: [], table: [], promotion: 0, relegation: 0, playoff: false, simulated: 'full' }
  state.competitions.push(comp)
  drawRound(state, comp, 0, ids, createRng(hashSeed(state.seed, state.season, 0xc0b)))
}

function tierOf(state: GameState, clubId: number): number {
  return state.competitions.find((c) => c.id === state.clubs[clubId].leagueId)?.tier ?? 4
}

function drawRound(state: GameState, comp: Competition, round: number, ids: number[], rng: Rng) {
  const pool = rng.shuffle([...ids])
  for (let i = 0; i + 1 < pool.length; i += 2) {
    let [h, a] = [pool[i], pool[i + 1]]
    // 下のカテゴリーのクラブがホーム
    if (tierOf(state, a) > tierOf(state, h)) [h, a] = [a, h]
    const f: Fixture = { id: allocId(state, 'fixture'), compId: comp.id, round, absWeek: absWeekOf(state.season, CUP_WEEKS[round]), slot: 'midweek', home: h, away: a }
    comp.fixtures.push(f)
  }
}

/** 次の回戦の抽選（前の回戦が全部終わっていれば）。週の処理の最初に呼ぶ */
export function advanceCup(state: GameState) {
  const comp = state.competitions.find((c) => c.id === CUP_ID)
  if (!comp) return
  const round = CUP_WEEKS.indexOf(state.week)
  if (round <= 0 || comp.fixtures.some((f) => f.round === round)) return
  const prev = comp.fixtures.filter((f) => f.round === round - 1)
  if (!prev.length || prev.some((f) => !f.result)) return
  const winners = prev.map(winnerOf).filter((x): x is number => x !== null)
  drawRound(state, comp, round, winners, createRng(hashSeed(state.seed, state.season, round, 0xc0b)))
}

/** 自クラブがどこまで勝ち上がったか */
export function cupStage(state: GameState): { stage: string; champion: number } | null {
  const comp = state.competitions.find((c) => c.id === CUP_ID)
  if (!comp) return null
  const me = state.playerClubId
  const mine = comp.fixtures.filter((f) => f.home === me || f.away === me).sort((a, b) => a.round - b.round)
  const final = comp.fixtures.find((f) => f.round === 5)
  const champion = final ? (winnerOf(final) ?? -1) : -1
  if (!mine.length) return { stage: '―', champion }
  const last = mine[mine.length - 1]
  const won = last.result && winnerOf(last) === me
  return { stage: last.round === 5 && won ? '優勝' : won ? `${CUP_ROUND_NAME[last.round]}突破` : `${CUP_ROUND_NAME[last.round]}敗退`, champion }
}
