import { createRng, hashSeed, hashString, type Rng } from '../core/prng'
import { WEEKS_PER_SEASON } from '../core/calendar'
import type { GameState, SeasonSummary } from '../models/game'
import { emptyStats, type Player } from '../models/player'
import type { Position } from '../data/positions'
import { assignNumbers, generatePlayer, SQUAD_TEMPLATE, starterOvrForRep } from '../gen/playerGen'
import { fairWage, ovr, rawRating } from '../player/overall'
import { playoffWinner } from './playoff'
import { scheduleLeague, sortTable } from './league'
import { prizeMoney } from '../economy/finance'
import { autoLineup } from '../match/lineup'
import { settleSponsors } from '../economy/sponsors'
import { afterSeason } from '../club/fans'
import { computeAwards, computeBestEleven, computeWorldRanking } from './awards'
import { CUP_ID, CUP_PRIZE, CUP_ROUND_NAME, CUP_WIN_PRIZE, createCup, cupStage } from './cup'
import { WL_ID, formWorldLeague, planWorldLeague, repAnchorOf, settleWorldMoves, type LeagueMove } from './worldLeague'
import { CONTINENTAL_IDS, continentalChampions, createContinental, decideQualifiers, settleContinental } from './continental'
import { addTrophies, inductHallOfFame, seasonRecords } from '../club/records'
import { careerSeasonEnd } from '../career/season'
import { returnLoans } from '../transfer/market'
import { emergencySign } from '../transfer/contracts'
