const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

/** シーズン末の処理（state.season はまだ終わるシーズン） */
export function processSeasonEnd(state: GameState, rng: Rng) {
  const absWeek = state.season * WEEKS_PER_SEASON + WEEKS_PER_SEASON - 1
  const me = state.clubs[state.playerClubId]
  const leagues = state.competitions.filter((c) => c.kind === 'league' && !c.hidden)
  for (const c of leagues) sortTable(c)
  // オーナーの評価（M19。昇降格でリーグが変わる前に、今季の順位と収支で）
  ownerSeasonEnd(state)

  // ---- 1. 昇格・降格 ----
  const byId = (id: string) => leagues.find((c) => c.id === id)!
  const domestic = ['NPL1', 'NPL2', 'NPL3'].map(byId)
  const moves: LeagueMove[] = []
  for (let i = 0; i < domestic.length - 1; i++) {
    const upper = domestic[i]
    const lower = domestic[i + 1]
    const down = upper.table.slice(-3).map((r) => r.clubId)
    const up = lower.table.slice(0, 2).map((r) => r.clubId)
    const po = playoffWinner(state, lower.id) ?? lower.table[2]?.clubId
    if (po !== undefined && !up.includes(po)) up.push(po)
    for (const c of down) moves.push({ club: c, from: upper, to: lower })
    for (const c of up.slice(0, down.length)) moves.push({ club: c, from: lower, to: upper })
  }
  // ワールドリーグ（M24）: 下位 3 クラブと、それぞれの国のリーグの上位の入れ替え・自クラブの参入
  const world = planWorldLeague(state, moves)
  moves.push(...world)
  const isUp = (m: LeagueMove) => (m.dir ? m.dir === 'up' : m.to.tier < m.from.tier)
  const promoted = moves.filter(isUp).map((m) => m.club)
  const relegated = moves.filter((m) => !isUp(m)).map((m) => m.club)

  // ---- 2. 記録・賞金 ----
  const myLeague = leagues.find((c) => c.id === me.leagueId) ?? state.competitions.find((c) => c.id === me.leagueId)!
  const myRow = myLeague.table.findIndex((r) => r.clubId === me.id)
  const topScorers: SeasonSummary['topScorers'] = []
  for (const c of [...domestic, ...leagues.filter((x) => x.id === WL_ID)]) {
    let best: Player | null = null
    for (const id in state.players) {
      const p = state.players[id]
      if (p.retired || !c.clubIds.includes(p.clubId)) continue
      if (!best || p.stats.goals > best.stats.goals) best = p
    }
    if (best) topScorers.push({ compId: c.id, playerId: best.id, goals: best.stats.goals })
  }
  // カップ戦の賞金
  const cup = cupStage(state)
  if (cup) {
    const stageIdx = CUP_ROUND_NAME.findIndex((n) => cup.stage.startsWith(n))
    const cupPrize = cup.stage === '優勝' ? CUP_WIN_PRIZE : stageIdx >= 0 ? CUP_PRIZE[stageIdx] : 0
    if (cupPrize > 0) {
      me.budget += cupPrize
      const last = state.finance[state.finance.length - 1]
      if (last) last.prize += cupPrize
    }
    if (cup.champion >= 0) state.news.push({ absWeek, category: 'league', mine: cup.champion === me.id, text: `ナショナルカップは ${state.clubs[cup.champion].name} が優勝！` })
  }
  // 大陸大会・世界大会の賞金と格、来季の出場クラブ（順位表を消す前に）
  const continental = settleContinental(state, absWeek)
  decideQualifiers(state)
  if (state.qualified?.acc.includes(me.id)) state.news.push({ absWeek, category: 'club', mine: true, text: `${me.name}、来季のアジアクラブカップ出場が決定！` })
  const career = state.mode === 'career' && !!state.career
  const prize = career ? 0 : myLeague.id === WL_ID ? worldPrize(myRow + 1) : prizeMoney(myLeague.tier, myRow + 1)
  if (prize > 0) {
    me.budget += prize
    const last = state.finance[state.finance.length - 1]
    if (last) last.prize += prize
  }
  state.seasons.push({
    season: state.season,
    leagueId: me.leagueId,
    rank: myRow + 1,
    points: myLeague.table[myRow]?.points ?? 0,
    champions: [
      ...leagues.map((c) => ({ compId: c.id, clubId: c.table[0].clubId })),
      ...(cup && cup.champion >= 0 ? [{ compId: CUP_ID, clubId: cup.champion }] : []),
      ...continentalChampions(state),
    ],
    promoted,
    relegated,
    topScorers,
    budgetEnd: me.budget,
    awards: computeAwards(state),
    cup: cup ? { compId: 'CUP', stage: cup.stage, champion: cup.champion } : undefined,
    continental: continental.length ? continental : undefined,
  })
  // ベストイレブンと、世界の年間最優秀選手（ピッチクラウン賞）
  const sum = state.seasons[state.seasons.length - 1]
  sum.bestEleven = computeBestEleven(state)
  sum.worldRanking = computeWorldRanking(state, sum.champions)
  const top = sum.worldRanking[0]
  if (top) sum.awards = [...(sum.awards ?? []), { key: 'world', compId: 'WORLD', playerId: top.playerId, clubId: top.clubId, value: top.score, name: top.name }]
  if (!career) {
    addTrophies(state, state.seasons[state.seasons.length - 1].champions)
    seasonRecords(state)
  } else careerSeasonEnd(state)
  // スポンサーの成績ボーナス・サポーター
  const bonus = career ? 0 : settleSponsors(state, me, myRow + 1, promoted.includes(me.id))
  if (bonus > 0) {
    me.budget += bonus
    const last = state.finance[state.finance.length - 1]
    if (last) last.sponsor += bonus
    state.news.push({ absWeek, category: 'club', mine: true, text: `スポンサーから成績ボーナス ${bonus.toLocaleString()} 万円が支払われました。` })
  }
  if (!career) {
    afterSeason(state, me, myRow + 1, promoted.includes(me.id), relegated.includes(me.id))
    // サイドビジネスの決算・ライバルとの順位
    const summary = state.seasons[state.seasons.length - 1]
    summary.business = businessSeasonEnd(state, me, absWeek)
    summary.rival = rivalSeasonEnd(state, myLeague, absWeek)
  }
  // スタッフの契約は M5 まで自動で 1 年延長
  for (const id in state.staff) {
    const st = state.staff[id]
    if (st.clubId < 0 || st.until > state.season) continue
    st.until = state.season + 1
  }
  for (const c of [...leagues.filter((x) => x.id === WL_ID), ...domestic]) {
    const champ = state.clubs[c.table[0].clubId]
    state.news.push({ absWeek, category: 'league', mine: champ.isPlayer, text: `${c.name} は ${champ.name} が優勝！` })
  }
  const worldMine = world.some((m) => m.club === me.id)
  if (promoted.includes(me.id) && !worldMine) state.news.push({ absWeek, category: 'club', mine: true, text: `${me.name}、${myLeague.tier - 1 === 1 ? 'NPL ディビジョン1' : 'NPL ディビジョン2'} への昇格が決定！` })
  if (relegated.includes(me.id) && !worldMine) state.news.push({ absWeek, category: 'club', mine: true, text: `${me.name} は降格…。来季は下のカテゴリーで再起を図る。` })

  // ---- 3. 個人成績を履歴へ・引退・契約 ----
  for (const id in state.players) {
    const p = state.players[id]
    if (p.retired) continue
    if (p.stats.apps > 0 || p.clubId >= 0) p.history.push({ ...p.stats, season: state.season, clubId: p.clubId, ovr: ovr(p) })
    // 経歴は 25 シーズンまで。自クラブでプレーしたことのない選手は 8 シーズンまで（セーブを軽く。古い経歴を読むのは自クラブの記録だけ）
    const keep = p.starId || p.legend || p.id === state.career?.playerId || p.history.some((h) => h.clubId === state.playerClubId) ? 25 : HISTORY_OTHERS
    if (p.history.length > keep) p.history.splice(0, p.history.length - keep)
    p.stats = emptyStats()
  }
  returnLoans(state)
  const retired = retireAndContracts(state, rng, absWeek)
  const hof = career ? [] : inductHallOfFame(state, retired)
  if (hof.length) state.seasons[state.seasons.length - 1].hallOfFame = hof

  // ---- 4. 補充 ----
  for (const club of state.clubs) if (!club.isPlayer) refillSquad(state, club.id, rng)
  if (!career) {
    youthIntake(state, rng)
    academyIntake(state)
  }
  topUpFreeAgents(state, rng)
  if (!career) emergencySign(state)

  // ---- 5. クラブの移動と格 ----
  for (const m of moves) {
    m.from.clubIds = m.from.clubIds.filter((c) => c !== m.club)
    m.to.clubIds.push(m.club)
    const club = state.clubs[m.club]
    club.leagueId = m.to.id
    club.rep = clamp(club.rep + (isUp(m) ? 5 : -5), 5, 95)
  }
  settleWorldMoves(state, world)
  for (const c of leagues) {
    c.table.forEach((r, i) => {
      const club = state.clubs[r.clubId]
      club.lastRank = i + 1
      // 期待より上なら格が上がる
      const expected = c.clubIds.length / 2
      club.rep = clamp(club.rep + (expected - (i + 1)) * 0.12, 5, 95)
    })
  }
  // 格は所属リーグの基準へ少しずつ戻る（上位だけが強くなり続け、下位だけが弱くなり続けるのを防ぐ）
  for (const club of state.clubs) {
    const anchor = repAnchorOf(state, club.leagueId, LEAGUE_REP_ANCHOR[club.leagueId])
    if (club.isPlayer || anchor === undefined) continue
    club.rep = clamp(club.rep + (anchor - club.rep) * 0.08, 5, 95)
  }
  // プレーオフ・カップ戦は片付ける（新シーズンに作り直す）
  state.competitions = state.competitions.filter((c) => !c.id.endsWith('PO') && c.id !== 'CUP' && !CONTINENTAL_IDS.includes(c.id))
  // 古いニュースを捨てる
  if (state.news.length > 300) state.news.splice(0, state.news.length - 300)
}

/** 新しいシーズンの準備（state.season は新しいシーズン） */
export function startNewSeason(state: GameState) {
  // ワールドリーグ（M24）: 古いセーブは次のシーズンのはじめにつくる（クラブモードだけ）
  formWorldLeague(state)
  // 世界のスタッフ（M24 の 2 回目）: 自クラブが WL にいれば入れ替える
  refreshWorldStaff(state)
  for (const comp of state.competitions) {
    if (comp.kind !== 'league' || comp.hidden) continue
    comp.season = state.season
    scheduleLeague(state, comp, createRng(hashSeed(state.seed, hashString(comp.id), state.season + 1)))
  }
  createCup(state)
  createContinental(state)
  // オーナーの今季の目標（M19）
  setOwnerGoals(state)
  // 手動で組んだ先発は試合前に有効か確かめる（buildTeamSetup）。それ以外は組み直す
  for (const club of state.clubs) if (!club.lineup.manual) club.lineup = autoLineup(state, club)
  // リーグが分かれたらライバルを選び直す
  ensureRival(state)
  // 代表の強さの見直しと、今季の代表戦の予定
  nationalSeasonStart(state)
}

function ageOfP(p: Player, absWeek: number): number {
  return (absWeek - p.birthAbsWeek) / WEEKS_PER_SEASON
}

/** 引退・契約満了。自クラブにいたことのある引退選手を返す（殿堂入りの判定用） */
function retireAndContracts(state: GameState, rng: Rng, absWeek: number): Player[] {
  const next = state.season + 1
  let freeCount = 0
  const retiredMine: Player[] = []
  for (const id in state.players) {
    const p = state.players[id]
    if (p.retired || p.id === state.career?.playerId) continue
    const age = ageOfP(p, absWeek)
    const club = p.clubId >= 0 ? state.clubs[p.clubId] : undefined
    const level = club ? starterOvrForRep(club.rep, club.country) : 50
    const o = ovr(p)
    // 引退
    let pRetire = 0
    if (age >= 35) pRetire = 0.35 + (age - 35) * 0.15
    else if (age >= 32) pRetire = 0.05 + (o < level - 10 ? 0.15 : 0)
    if (!club && age >= 30) pRetire += 0.25
    if (rng.chance(clamp(pRetire, 0, 0.95))) {
      p.retired = true
      if (p.history.some((h) => h.clubId === state.playerClubId)) retiredMine.push(p)
      if (club?.isPlayer) state.news.push({ absWeek, category: 'club', mine: true, text: `${p.name}（${Math.floor(age)}歳）が現役引退を発表。` })
      p.clubId = -1
      continue
    }
    if (!club) {
      freeCount++
      continue
    }
    // 契約満了
    if (p.contract.until >= next) continue
    if (club.isPlayer) {
      // 更新しなかった選手はフリーになって退団
      p.clubId = -1
      p.number = 0
      delete state.forSale[p.id]
      state.news.push({ absWeek, category: 'transfer', mine: true, text: `${p.name} が契約満了で退団しました。` })
      freeCount++
      continue
    }
    const keep = (age < 31 || o >= level - 3) && rng.chance(0.75)
    if (keep) {
      p.contract = { ...p.contract, until: next + rng.int(0, 2), wage: fairWage(o, Math.floor(age), club.country) }
    } else {
      p.clubId = -1
      p.number = 0
      freeCount++
    }
  }
  // フリーの選手が多すぎたら、年長で弱い順に引退（キャリアの主人公は除く。ユース期・入団前はクラブに入っていない）
  const hero = state.career?.playerId
  if (freeCount > 260) {
    const free = Object.values(state.players)
      .filter((p) => !p.retired && p.clubId < 0 && p.id !== hero)
      .sort((a, b) => ageOfP(b, absWeek) * 2 - ovr(b) - (ageOfP(a, absWeek) * 2 - ovr(a)))
    for (const p of free.slice(0, freeCount - 260)) p.retired = true
  }
  // 引退した選手は、自クラブに在籍したことのある選手と固有キャラ、キャリアの一族（M17）だけ残す
  const family = new Set((state.career?.lineage ?? []).map((l) => l.playerId))
  for (const id in state.players) {
    const p = state.players[id]
    if (!p.retired || p.starId || family.has(p.id) || p.id === hero) continue
    if (p.history.some((h) => h.clubId === state.playerClubId)) continue
    delete state.players[id]
  }
  return retiredMine
}

/** AI クラブのポジションの穴を埋める（フリーの選手か、若手を生成） */
export function refillSquad(state: GameState, clubId: number, rng: Rng) {
  const club = state.clubs[clubId]
  const squad = Object.values(state.players).filter((p) => p.clubId === clubId && !p.retired)
  const base = starterOvrForRep(club.rep, club.country)
  const added: Player[] = []
  for (const t of SQUAD_TEMPLATE) {
    let have = squad.filter((p) => p.pos === t.pos).length
    while (have < t.count) {
      // フリーの選手から（格に合う中でいちばん良い選手）
      // （キャリアの主人公は、入団前・ユース期にクラブがなくても取らない）
      const cands = Object.values(state.players).filter((p) => !p.retired && p.clubId < 0 && p.id !== state.career?.playerId && p.pos === t.pos && rawRating(p.attr, p.pos) <= base + 2 && rawRating(p.attr, p.pos) >= base - 9)
      cands.sort((a, b) => rawRating(b.attr, b.pos) - rawRating(a.attr, a.pos))
      let np: Player
      if (cands.length && rng.chance(0.6)) {
        np = cands[0]
        np.clubId = clubId
        np.contract = { wage: fairWage(ovr(np), 25, club.country), until: state.season + 1 + rng.int(0, 2) }
      } else {
        np = generatePlayer(state, rng, { clubId, pos: t.pos as Position, targetOvr: base - rng.range(6, 12), age: rng.int(17, 20), country: club.country, potentialOvr: base + rng.normal(-2.5, 4.5), contractYears: 3 })
        state.players[np.id] = np
      }
      np.number = 0
      squad.push(np)
      added.push(np)
      have++
    }
  }
  if (added.length) assignNumbers(squad, rng)
}

/** フリーの選手が少なくなりすぎないように補充する（補充や緊急補強で吸い尽くされて市場が枯れるのを防ぐ） */
export const FREE_AGENT_MIN = 90

export function topUpFreeAgents(state: GameState, rng: Rng, min = FREE_AGENT_MIN) {
  let n = 0
  for (const id in state.players) {
    const p = state.players[id]
    if (!p.retired && p.clubId < 0) n++
  }
  for (; n < min; n++) {
    const pos = rng.pick(['GK', 'CB', 'CB', 'SB', 'DM', 'CM', 'CM', 'AM', 'WG', 'ST', 'ST'] as Position[])
    const p = generatePlayer(state, rng, { clubId: -1, pos, targetOvr: rng.range(36, 58), age: rng.int(19, 31), country: rng.chance(0.75) ? 'JP' : rng.pick(['BR', 'ES', 'EN', 'FR', 'DE']), contractYears: -1 })
    state.players[p.id] = p
  }
}

/** 自クラブでプレーしたことのない選手の経歴の長さ（シーズン） */
export const HISTORY_OTHERS = 8

/** 自クラブのユースから若手が上がってくる（ユース施設のレベルで質と人数） */
function youthIntake(state: GameState, rng: Rng) {
  const club = state.clubs[state.playerClubId]
  const lv = club.facilities.youth
  const coach = club.staff.map((id) => state.staff[id]).find((s) => s?.role === 'youthCoach')
  // サッカースクールがあると質が上がり、Lv3 から人数も増える
  const school = bizLevel(state, club, 'school')
  // 学園都市（M19）: 毎年 1 人多い
  const n = 2 + Math.floor(lv / 2) + (coach ? 1 : 0) + (state.hometown.population >= 40 ? 1 : 0) + (school >= 3 ? 1 : 0) + (hasTrait(state, 'campus', club) ? 1 : 0)
  const base = starterOvrForRep(club.rep, club.country)
  const names: string[] = []
  for (let i = 0; i < n; i++) {
    const pos = rng.pick(['CB', 'SB', 'CM', 'AM', 'WG', 'ST', 'DM', 'GK'] as Position[])
    const p = generatePlayer(state, rng, { clubId: club.id, pos, targetOvr: base - rng.range(12, 18), age: rng.int(15, 17), country: 'JP', nation: 'JP', potentialOvr: base + rng.normal(0, 6) + lv * 2 + (coach ? coach.ability / 20 : 0) + school * 1.2, contractYears: 3, isYouth: true })
    p.contract.wage = 0
    p.homegrown = club.id
    state.players[p.id] = p
    names.push(`${p.name}（${pos}）`)
  }
  assignNumbers(Object.values(state.players).filter((p) => p.clubId === club.id && !p.retired), rng)
  // 19 歳を過ぎたユースの選手は退団（トップに上げなかった）
  for (const id in state.players) {
    const q = state.players[id]
    if (q.isYouth && q.clubId === club.id && (state.season * WEEKS_PER_SEASON + WEEKS_PER_SEASON - q.birthAbsWeek) / WEEKS_PER_SEASON >= 19.5) {
      q.isYouth = false
      q.clubId = -1
    }
  }
  state.news.push({ absWeek: state.season * WEEKS_PER_SEASON + WEEKS_PER_SEASON - 1, category: 'club', mine: true, text: `ユースアカデミーに ${names.join('、')} が入団しました。` })
}
