/**
 * 子どもの世代の登場人物の出来事（M17）。役ごとに 1 人で、名前は世代ごとに変わる（{name} ではなく話し手の id で出す）。
 *   ヒロイン 6 人: 4 段（出会い → 友達 → 特別 → 告白。告白は 18 歳から＝romance）
 *   親友・ライバル・主将・監督: 3 段
 * ユース期は同じ年ごろの友達どうし。恋愛は大人になってから。全年齢向け（手をつなぐ程度まで、飲酒なし）。
 */
import type { CareerEventDef, TalkLineDef } from '../events'

type Line = [string, string]
const L = (who: string, rows: Line[]): TalkLineDef[] => rows.map(([s, t]) => ({ s: s === 'H' ? who : s, t }))

export function heroine(id: string, title: string[], steps: Line[][], lover: { yes: string; no: string; reply: string }): CareerEventDef[] {
  const bonds = [0, 20, 45, 70]
  return steps.map((rows, i) => ({
    id: `${id}_${i + 1}`,
    char: id,
    title: title[i],
    trigger: 'outing' as const,
    step: i + 1,
    minBond: bonds[i],
    romance: i === 3 ? true : undefined,
    lines: L(id, rows),
    ...(i === 3
      ? {
          options: [
            { id: 'yes', label: lover.yes, lines: L(id, [['H', lover.reply]]), effect: { bond: 15, lover: true, condition: 20 }, auto: true },
            { id: 'no', label: lover.no, lines: L(id, [['H', 'うん……わかった。でも、これからも友達でいてね。']]), effect: { bond: -5 } },
          ],
        }
      : { effect: { bond: 8, condition: 6, exp: { mental: 4 } } }),
  }))
}

export function friendChain(id: string, title: string[], steps: Line[][], exps: CareerEventDef['effect'][]): CareerEventDef[] {
  const bonds = [0, 25, 50]
  return steps.map((rows, i) => ({ id: `${id}_${i + 1}`, char: id, title: title[i], trigger: 'outing' as const, step: i + 1, minBond: bonds[i], lines: L(id, rows), effect: exps[i] }))
}

