/**
 * 連携（自クラブの選手どうしの相性、0-100）。サカつくの目玉。
 * - 隣り合うポジションで一緒に先発すると育つ（性格の相性・同じ国籍で育ちやすい）
 * - 戦術理解の練習と合宿でも育つ。一緒に出ないと少しずつ下がる
 * - 試合では、パスの精度とチームのまとまり（判断のぶれ）に効く
 * AI クラブは一定の値（CHEM_AI）として扱う。
 */
import { adjacency, formationOf } from '../data/formations'
import { chemistryAffinity } from '../data/personality'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'

export const CHEM_AI = 45
/**
 * 試合で使う自クラブの連携の下限。AI（一定の 45）と同じ水準から始め、育てた連携はそれより上に効く。
 * 下限が AI より低いと、同じ戦力でも自クラブだけ 1 シーズンで勝点が 10 ほど少なくなっていた（M9 で 30 → 45）
 */
export const CHEM_FLOOR = CHEM_AI

export function chemKey(a: number, b: number): string {
  return a < b ? `${a}:${b}` : `${b}:${a}`
}

export function chemOf(state: GameState, a: number, b: number): number {
  return state.chem[chemKey(a, b)] ?? 0
}

function grow(state: GameState, a: Player, b: Player, amount: number) {
  if (a.id === b.id) return
  let mul = chemistryAffinity(a.personality, b.personality)
  if (a.nation === b.nation) mul *= 1.15
  if (a.skills.includes('loneWolf') || b.skills.includes('loneWolf')) mul *= 0.5
  if (a.personality === 'leader' || b.personality === 'leader') mul *= 1.08
  const k = chemKey(a.id, b.id)
  state.chem[k] = Math.min(100, (state.chem[k] ?? 0) + amount * mul)
}

/** 試合のあと: 先発の隣り合うスロットの組み合わせ */
export function chemAfterMatch(state: GameState, starters: number[], formation: string) {
  const f = formationOf(formation)
  for (const [i, j] of adjacency(f)) {
    const a = state.players[starters[i]]
    const b = state.players[starters[j]]
    if (a && b) grow(state, a, b, 1.4)
  }
}

/** 毎週: 戦術理解の練習・合宿で育ち、出ていない組み合わせは下がる */
export function chemWeekly(state: GameState, squad: Player[], tacticsWeight: number, campBonus: number) {
  const core = [...squad].sort((a, b) => b.stats.minutes - a.stats.minutes).slice(0, 16)
  const add = tacticsWeight * 0.08 + campBonus
  if (add > 0) {
    for (let i = 0; i < core.length; i++) for (let j = i + 1; j < core.length; j++) grow(state, core[i], core[j], add)
  }
  const ids = new Set(squad.map((p) => p.id))
  for (const k of Object.keys(state.chem)) {
    const [a, b] = k.split(':').map(Number)
    if (!ids.has(a) || !ids.has(b)) {
      delete state.chem[k]
      continue
    }
    state.chem[k] = Math.max(0, state.chem[k] - 0.25)
    if (state.chem[k] < 0.5) delete state.chem[k]
  }
}

/** 先発の隣り合う組み合わせの平均（チームのまとまり、0-100） */
/** チームのまとまり（試合用。隣り合う先発どうしの連携の平均、下限 CHEM_FLOOR） */
export function teamCohesion(state: GameState, starters: number[], formation: string): number {
  const f = formationOf(formation)
  const adj = adjacency(f)
  if (!adj.length) return CHEM_FLOOR
  let s = 0
  for (const [i, j] of adj) s += Math.max(CHEM_FLOOR, chemOf(state, starters[i], starters[j]))
  return s / adj.length
}

/** 連携技（表示用）: 条件を満たすコンビ */
export interface Combo {
  name: string
  a: number
  b: number
}

export function combosOf(state: GameState, squad: Player[]): Combo[] {
  const out: Combo[] = []
  for (let i = 0; i < squad.length; i++) {
    for (let j = i + 1; j < squad.length; j++) {
      const a = squad[i]
      const b = squad[j]
      const c = chemOf(state, a.id, b.id)
      if (c < 60) continue
      const fw = (p: Player) => p.pos === 'ST' || p.pos === 'WG' || p.pos === 'AM'
      if (c >= 80 && ((a.attr.vision >= 70 && fw(b) && b.attr.offBall >= 70) || (b.attr.vision >= 70 && fw(a) && a.attr.offBall >= 70))) out.push({ name: 'ホットライン', a: a.id, b: b.id })
      else if (c >= 70 && a.attr.pass >= 62 && b.attr.pass >= 62 && (a.attr.dribble >= 62 || b.attr.dribble >= 62)) out.push({ name: 'ワンツー', a: a.id, b: b.id })
      else if (c >= 80 && a.pos === 'CB' && b.pos === 'CB') out.push({ name: '鉄壁コンビ', a: a.id, b: b.id })
      else if (c >= 60 && a.pos === 'ST' && b.pos === 'ST' && a.heightCm >= 185 && b.heightCm >= 185) out.push({ name: 'ツインタワー', a: a.id, b: b.id })
    }
  }
  return out
}
