/**
 * ダービーとライバル。
 *   ダービー: 同じ県のクラブとの試合（強い）、同じ地方のクラブとの試合（弱い）。観客と、勝ち負けでの人気・サポーターの増減が大きくなる
 *   宿命のライバル: 同じリーグの近くのクラブを 1 つ選ぶ。対戦成績を数え、シーズン末に順位で人気が動く。リーグが分かれたら選び直す
 */
import type { Club } from '../models/club'
import type { Competition, Fixture } from '../models/competition'
import type { GameState } from '../models/game'
import { absWeekOf } from '../core/calendar'
import { fansCap, popularityCap } from './fans'

