/**
 * スカウトの報告（M21。クラブモード）。
 * 派遣中のスカウトが調べた選手から、獲る値打ちのある選手を「報告」に載せる（注目リストには入れない）。
 *   弱点を埋める（今の先発を上回る）> 伸びしろが大きい若手 > 移籍金なしで獲れる、の順で、1 人のスカウトが 1 週に 1 人まで
 *   獲れる見込みのない選手（来る気なし・資金不足・決裂）は載せない
 * 掲載は 8 週。残したい選手は注目（★）へ移す。報告は最大 24 件（古いものから消える）。
 * 乱数は使わない（ほかの処理の乱数の並びを変えない）。
 */
import { absWeekOf } from '../core/calendar'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import type { Position } from '../data/positions'
import { ageOf, potentialOvr, rawRating } from '../player/overall'
import { squadRanks } from '../transfer/market'
import { upgradeOf, weakSpots, type Upgrade } from '../transfer/recommend'
import { rankRange, strengthsOf } from '../player/profile'
import { outOfReach, signability } from '../transfer/talks'
import { FOREIGN_BIG_GAIN, foreignRoster, isForeign } from '../match/lineup'
import { REGION_LABEL, estimate, type ScoutFind } from './knowledge'

export const REPORT_WEEKS = 8
export const MAX_REPORTS = 24

export type ReportReason = 'need' | 'gem' | 'bargain'

export interface ScoutReport {
  playerId: number
  /** 見つけたスカウト（古いセーブから移したものは -1、選び直したあとは -2） */
  staffId: number
  foundAbsWeek: number
  /** 掲載期限（この週まで載る） */
  untilAbsWeek: number
  reason: ReportReason
  /** 弱点を埋めるポジション */
  pos?: Position
  /** 画面で見た */
  seen?: boolean
}

export const REASON_LABEL: Record<ReportReason, string> = { need: '弱点を埋める', gem: '伸びしろ大', bargain: '移籍金なし' }

const nowOf = (state: GameState) => absWeekOf(state.season, state.week)

/** 掲載の残りの週（今週を含む） */
export function reportWeeksLeft(state: GameState, r: ScoutReport): number {
  return Math.max(0, r.untilAbsWeek - nowOf(state) + 1)
}

/** 載っている報告（引退などでいなくなった選手は除く） */
export function reportsOf(state: GameState): ScoutReport[] {
  return (state.scout.reports ?? []).filter((r) => state.players[r.playerId])
}

/** まだ見ていない報告の数（ナビのバッジ） */
export function unseenReports(state: GameState): number {
  return reportsOf(state).filter((r) => !r.seen).length
}

/**
 * その選手を報告する値打ちがあるか（なければ null）。
 *   弱点を埋める: 今の先発を推定で 3 以上上回る
 *   伸びしろ: 23 歳以下で、将来性がチームの水準より ★1 以上上（最低 ★3）
 *   移籍金なし: フリーで、チームの平均に近い力がある
 */
function judge(state: GameState, p: Player, ranks: Map<number, number>, spots: ReturnType<typeof weakSpots>): { reason: ReportReason; pos?: Position; score: number } | null {
  const me = state.clubs[state.playerClubId]
  if (p.retired || p.isYouth || p.loan || p.clubId === me.id) return null
  if (outOfReach(signability(state, p, ranks))) return null
  const e = estimate(state, p)
  const up = upgradeOf(state, p, spots, e)
  const cur = rawRating(p.attr, p.pos)
  const levelStars = Math.max(1, (spots.teamAvg - 45) / 9)
  const gem = ageOf(p, nowOf(state)) <= 23 && potentialOvr(p) >= cur + 8 && (e.potLo + e.potHi) / 2 >= Math.max(3, levelStars + 1)
  const bargain = p.clubId < 0 && (e.ovrLo + e.ovrHi) / 2 >= spots.teamAvg - 3
  let best: { reason: ReportReason; pos?: Position; score: number } | null = null
  const cands: { reason: ReportReason; score: number; pos?: Position }[] = []
  if (up) cands.push({ reason: 'need', score: 10 + up.gain * 2, pos: up.pos })
  if (gem) cands.push({ reason: 'gem', score: 8 + (potentialOvr(p) - cur) * 0.5 })
  if (bargain) cands.push({ reason: 'bargain', score: 6 })
  for (const c of cands) if (!best || c.score > best.score) best = c
  // 外国人枠（日本のクラブ）: 日本人を優先。在籍の外国籍が 5 人以上なら、外国籍は先発を大きく上回るときだけ
  if (best && me.country === 'JP') {
    if (isForeign(p, me)) {
      const full = foreignRoster(state, me).full
      if (full && !(up && up.gain >= FOREIGN_BIG_GAIN)) return null
      best = { ...best, score: best.score - (full ? 6 : 3) }
    } else best = { ...best, score: best.score + 3 }
  }
  return best
}

/** 調べた選手から、報告に載せる 1 人を選ぶ */
function pickReport(state: GameState, found: Player[], ranks: Map<number, number>, spots: ReturnType<typeof weakSpots>): { p: Player; reason: ReportReason; pos?: Position } | null {
  const listed = new Set([...state.scout.watch, ...reportsOf(state).map((r) => r.playerId)])
  let best: { p: Player; reason: ReportReason; pos?: Position; score: number } | null = null
  for (const p of found) {
    if (listed.has(p.id)) continue
    const j = judge(state, p, ranks, spots)
    if (j && (!best || j.score > best.score)) best = { p, ...j }
  }
  return best
}

/** 報告の中身（ニュースと画面の一言） */
export function reportText(state: GameState, r: ScoutReport): string {
  const p = state.players[r.playerId]
  if (!p) return ''
  if (r.reason === 'need') return `${r.pos ?? p.pos} の弱点を埋められる`
  if (r.reason === 'gem') return '伸びしろが大きい若手'
  return '移籍金なしで獲れる'
}

/** スカウトのひと言（推定の能力から。得意な能力をランクで） */
export function scoutComment(state: GameState, r: ScoutReport, up?: Upgrade | null): string {
  const p = state.players[r.playerId]
  if (!p) return ''
  const e = estimate(state, p)
  const err = Math.round((1 - e.k / 100) * 7)
  const top = strengthsOf(e.attr, p.pos).strong[0]
  const weapon = top ? `${top.name}（${rankRange(top.value, err)}）` : ''
  if (r.reason === 'need') {
    if (up) return `${up.pos} の弱点を埋められます。先発の ${Math.round(up.from)} に対して、推定 ${Math.round(up.to)}。${weapon}が武器です。`
    return `${r.pos ?? p.pos} を任せられる力があります。${weapon}が武器です。`
  }
  if (r.reason === 'gem') {
    const stars = e.potLo === e.potHi ? `★${e.potLo}` : `★${e.potLo}〜${e.potHi}`
    return `まだ荒削りですが、伸びしろは大きい（将来性 ${stars}）。${weapon}が光ります。`
  }
  return `契約が切れてフリーの選手です。移籍金なしで獲れます。${weapon}が武器です。`
}

/** 古いセーブから移した報告（staffId -1）を、いまの基準で選び直す。値打ちのないものは消す */
export function requalifyReports(state: GameState) {
  const list = state.scout.reports
  if (!list?.some((r) => r.staffId === -1)) return
  const ranks = squadRanks(state)
  const spots = weakSpots(state)
  state.scout.reports = list.flatMap((r) => {
    if (r.staffId !== -1) return [r]
    const p = state.players[r.playerId]
    const j = p ? judge(state, p, ranks, spots) : null
    return j ? [{ ...r, staffId: -2, reason: j.reason, pos: j.pos }] : []
  })
}

/** 毎週（クラブモード）: 期限の切れた報告を消し、スカウトが調べた選手から報告を出す */
export function reportWeek(state: GameState, found: ScoutFind[]) {
  const now = nowOf(state)
  const me = state.clubs[state.playerClubId]
  let reports = reportsOf(state).filter((r) => {
    const p = state.players[r.playerId]
    return r.untilAbsWeek >= now && p && !p.retired && p.clubId !== me.id
  })
  if (found.length) {
    const ranks = squadRanks(state)
    const spots = weakSpots(state)
    for (const f of found) {
      state.scout.reports = reports
      const s = state.staff[f.staffId]
      const pick = pickReport(state, f.players, ranks, spots)
      if (pick) {
        const r: ScoutReport = { playerId: pick.p.id, staffId: f.staffId, foundAbsWeek: now, untilAbsWeek: now + REPORT_WEEKS - 1, reason: pick.reason, pos: pick.pos }
        reports = [...reports, r]
        const m = state.scout.missions.find((x) => x.staffId === f.staffId)
        if (m) m.found = (m.found ?? 0) + 1
        state.news.push({ absWeek: now, category: 'transfer', mine: true, text: `スカウトの${s?.name ?? ''}から報告: ${pick.p.name}（${reportText(state, r)}）。掲載は ${REPORT_WEEKS} 週（移籍 → スカウト）。` })
      }
      // 視察の最終週: 前回の視察として残し、報告の数とあわせて知らせる
      if (f.done) {
        const count = f.done.found + (pick ? 1 : 0)
        state.scout.trips = { ...(state.scout.trips ?? {}), [f.staffId]: { region: f.done.region, absWeek: now, count } }
        state.news.push({ absWeek: now, category: 'transfer', mine: true, text: `${s?.name ?? 'スカウト'}が${REGION_LABEL[f.done.region]}の視察から戻りました（報告 ${count} 件${count ? '' : '。獲れそうな選手は見つかりませんでした'}）。` })
      }
    }
  }
  if (reports.length > MAX_REPORTS) reports = reports.slice(reports.length - MAX_REPORTS)
  state.scout.reports = reports
}

/** 報告の選手を注目へ移す（期限なしで残る） */
export function keepReport(state: GameState, playerId: number) {
  state.scout.reports = reportsOf(state).filter((r) => r.playerId !== playerId)
  if (!state.scout.watch.includes(playerId)) state.scout.watch = [...state.scout.watch, playerId]
}

/** 報告から外す */
export function dropReport(state: GameState, playerId: number) {
  state.scout.reports = reportsOf(state).filter((r) => r.playerId !== playerId)
}

/** 報告を見た */
export function markReportsSeen(state: GameState) {
  for (const r of reportsOf(state)) r.seen = true
}

/**
 * 古いセーブ: スカウトが注目リストに自動で入れた選手（ニュースで分かるもの）を報告に移す。
 * 自分で ★ を付けた選手はそのまま。
 */
export function migrateScoutWatch(state: GameState) {
  if (state.scout.reports !== undefined || state.mode === 'career') return
  const now = nowOf(state)
  const names = new Set<string>()
  for (const n of state.news) {
    const m = /が有望な選手 (.+) を見つけました/.exec(n.text)
    if (m) names.add(m[1])
  }
  const reports: ScoutReport[] = []
  const keep: number[] = []
  for (const id of state.scout.watch) {
    const p = state.players[id]
    if (p && names.has(p.name)) reports.push({ playerId: id, staffId: -1, foundAbsWeek: now, untilAbsWeek: now + REPORT_WEEKS - 1, reason: 'gem', seen: true })
    else keep.push(id)
  }
  state.scout.watch = keep
  state.scout.reports = reports.slice(-MAX_REPORTS)
}
